CREATE OR REPLACE package body XXOTM.XXOTM_ENGINE_PKG as

   -- NO package-level state above this line, deliberately. State makes a
   -- recompile raise ORA-04068 on live ORDS sessions; without it a
   -- redeploy only invalidates dependents.

   -- ========================================================================
   -- POST_OTM_DOCUMENTS   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/POST_OTM_DOCUMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure post_otm_documents (
   p_documentxid      in varchar2,
   p_documentfilename in varchar2,
   p_ownerobjectgid   in varchar2,
   p_clobcontent      in clob,
   p_documentmimetype in varchar2,
   p_documentdefgid   in varchar2,
   x_response_clob    out clob
)
as  
    -- Last Updated Date : 18-Dec-2025
    -- Last Updated By : Madhan
    -- Description : updated hardcoded credentials to web credentials
   l_json_payload clob;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
  l_mimetype             varchar2(100);
BEGIN
	
	
		l_mimetype := coalesce(replace(p_documentmimetype, '\/', '/'), 'image/png');
    -- 1. Build JSON Payload
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- Top-level fields
   apex_json.write(  
      'documentXid',
      p_documentxid
   );
   apex_json.write(
      'documentDefGid',
      p_documentdefgid
   );
   apex_json.write(
      'documentType',
      'BLOB'
   );
   apex_json.write(
      'documentMimeType',
      l_mimetype
   );
   apex_json.write(
      'documentFilename',
      p_documentfilename
   );
   apex_json.write(
      'ownerDataQueryTypeGid',
      'SHIPMENT'
   );
   apex_json.write(
      'ownerObjectGid',
      p_ownerobjectgid
   );
   apex_json.write(
      'domainName',
      'NAQLEEN'
   );
   apex_json.write(  
      'usedAs',
      'I'
   );
   apex_json.write(
      'documentCmsId',
      'NAQLEEN.' || p_documentxid
   );

    -- Contents Object
   apex_json.open_object('contents');
   apex_json.open_array('items');

    -- Item Object
   apex_json.open_object;
   apex_json.write(
      'domainName',
      'NAQLEEN'
   );
   apex_json.write(
      'clobContent',
      p_clobcontent
   );
   apex_json.close_object; -- Close Item

   apex_json.close_array; -- Close Items Array
   apex_json.close_object; -- Close Contents Object

   apex_json.close_object; -- Close Main Object

   l_json_payload := apex_json.get_clob_output;
   apex_json.free_output;

    -- 2. Call OTM REST API
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      x_response_clob := apex_web_service.make_rest_request(
         p_url         => xxotm_get_cfg('OTM_BASE_URL')
                          || '/logisticsRestApi/resources-int/v2/documents/'
         ,
         p_http_method => 'POST',
         p_credential_static_id => l_credential_static_id  ,
         p_body        => l_json_payload,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
      
      
       insert into xx_ws_payloads_t values ( 'XX_OTM_POST_DOCUMENTS_APEX',
                                            null,
                                            l_json_payload,
                                            x_response_clob,
                                            sysdate,
                                            xx_payload_seq.nextval );

      
      
      
      
      
      
   exception
      when others then
         x_response_clob := 'Error calling OTM API: ' || sqlerrm;
            -- Optionally log the error
   end;

exception
   when others then
      apex_json.free_output;
      x_response_clob := 'Error in POST_OTM_DOCUMENTS: ' || sqlerrm;
end post_otm_documents;

   -- ========================================================================
   -- POST_OTM_REFNUMS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/POST_OTM_REFNUMS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure post_otm_refnums (
   p_shipmentxid     varchar2 ,
   p_containerxid    varchar2 default null,
   p_refnum_qual_gid varchar2,
   p_refnum_value    varchar2 default null,
   x_response        out clob
)
is
    -- Last Updated Date : 18-Dec-2025
    -- Last Updated By : Madhan
    -- Description : updated hardcoded credentials to web credentials
   l_clob          clob;
   l_input_request clob := null;
   l_error_msg     varchar2(240);
   l_url           varchar2(4000);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
begin
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';

   -- Construct URL with shipment XID
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
            || trim(both ' ' from ltrim(
      p_shipmentxid,
      'NAQLEEN.'
   ))
            || '/refnums';

   -- Prepare JSON request body
   l_input_request := '{
    "shipmentRefnumQualGid": "'
                      || p_refnum_qual_gid
                      || '",
    "shipmentRefnumValue": "'
                      || nvl(
      p_refnum_value,
      p_containerxid
   )
                      || '",
    "domainName": "NAQLEEN"
}';

   begin
      l_clob := apex_web_service.make_rest_request(
         p_url         => l_url,
         p_http_method => 'POST',
         p_credential_static_id => l_credential_static_id,
         p_body        => l_input_request,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
      x_response := l_clob;
   exception
      when others then
         l_error_msg := 'Error occurred while calling Naqleen refnums service: ' || sqlerrm;
         dbms_output.put_line('ERROR: ' || l_error_msg);
         x_response := l_error_msg;
   end;

   -- Log payload
   begin
      insert into xx_ws_payloads_t values ( p_refnum_qual_gid,
                                            null,
                                            l_input_request,
                                            l_clob,
                                            sysdate,
                                            xx_payload_seq.nextval );
      commit;
   exception
      when others then
         null;
   end;

end post_otm_refnums;

   -- ========================================================================
   -- POST_OTM_TRACKING_EVENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/POST_OTM_TRACKING_EVENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure post_otm_tracking_events (
   p_integration_name varchar2 default null,
   p_statuscodegid    varchar2 default null,
   p_shipmentxid      varchar2 default null,
    p_event_timestamp  VARCHAR2 DEFAULT NULL,
   p_attribute1       varchar2 default null,
   p_attribute2       varchar2 default null,
   p_attribute3       varchar2 default null,
   p_attribute4       varchar2 default null,
   p_attribute5       varchar2 default null,
   p_attribute6       varchar2 default null,
   p_attribute7       varchar2 default null,
   p_attribute8       varchar2 default null,
   p_attribute9       varchar2 default null,
   p_attribute10      varchar2 default null,
 	p_attribute_number1       NUMBER default null,
    p_attribute_number2       NUMBER  default null,
    p_attribute_number3      NUMBER  default null,
   x_response         out clob
)
is
    -- Last Updated Date : 18-Dec-2025
    -- Last Updated By : Madhan
    -- Description : updated hardcoded credentials to web credentials
   l_clob           clob;
   l_input_request  clob := null;
   l_error_msg      varchar2(240);
   p_input_body     clob;
   l_transaction_id varchar2(240);
   l_parm_names     apex_application_global.vc_arr2;
   l_parm_values    apex_application_global.vc_arr2;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
  
    FUNCTION format_iso_timestamp(p_iso_str VARCHAR2) RETURN VARCHAR2 IS
      l_parsed_ts TIMESTAMP WITH TIME ZONE;
   BEGIN
      IF p_iso_str IS NULL THEN
         RETURN TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"');
      END IF;
      
      -- Parse and reformat to exact ISO with 6-digit microseconds + Z
      l_parsed_ts := TO_TIMESTAMP_TZ(
        REGEXP_REPLACE(p_iso_str, '(\.\d{6})Z$', 'Z'),
        'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
      );
      
      RETURN TO_CHAR(l_parsed_ts, 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"');
   EXCEPTION
      WHEN OTHERS THEN
         RETURN TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"');
   END format_iso_timestamp;
	
BEGIN
	
	
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
--#######################################
--REST API Calling
--#######################################


   l_input_request := '{
    "statusCodeGid": "NAQLEEN.'
                      ||REPLACE(p_statuscodegid, 'NAQLEEN.', '')
                      || '",
    "timeZoneGid": "UTC",
    "eventdate": {
        "value": "'
                      || format_iso_timestamp(p_event_timestamp)
                      || '"
    },
    "eventReceivedDate": {
        "value": "'
                      || format_iso_timestamp(p_event_timestamp)
                      || '"
    },
    "responsiblePartyGid": "CARRIER",
    "shipmentGid": "NAQLEEN.'
                      || trim(both ' ' from ltrim(
      p_shipmentxid,
      'NAQLEEN.'
   ))
                      || '",
    "domainName": "NAQLEEN"';

   case
      when p_integration_name = 'XX_OTM_POST_VEHICLE_EXIT_APEX' then
         l_input_request := l_input_request
                            || ',"attribute5": "'
                            || p_attribute5
                            || '"
}';
      when p_integration_name = 'XX_OTM_POST_POSITION_CONTAINER' then
         l_input_request := l_input_request
                            || ',"attribute1": "'
                            || p_attribute1
                            || '"';
        if p_attribute4 is not null then
            l_input_request := l_input_request
                               || ',"attribute4": "'
                               || p_attribute4
                               || '"';
         end if;
         l_input_request := l_input_request || '

}';
--       when
--          p_integration_name = 'XX_OTM_POST_STUFFING_CONTAINER'
--          and p_statuscodegid = 'NAQLEEN.STUFFED'
--       then
--          l_input_request := l_input_request
--                             || ',attribute2: '
--                             || p_attribute2
--                             || '
                            
-- }';
      when
         p_integration_name = 'XX_OTM_POST_STUFFING_CONTAINER'
         and p_statuscodegid = 'NAQLEEN.STUFFED'
      then
         l_input_request := l_input_request
                            || ',"attribute2": "'
                            || p_attribute2
                            || '"';
         if p_attribute3 is not null then
            l_input_request := l_input_request
                               || ',"attribute3": "'
                               || p_attribute3
                               || '"';
         end if;
         if p_attribute4 is not null then
            l_input_request := l_input_request
                               || ',"attribute4": "'
                               || p_attribute4
                               || '"';
         end if;
         l_input_request := l_input_request || '
}';
      when
         p_integration_name = upper('XX_OTM_POST_DESTUFFING_CONTAINER')
         and p_statuscodegid = 'NAQLEEN.DESTUFFED'
      then
         l_input_request := l_input_request
                            || ',"attribute2": "'
                            || p_attribute2
                            || '"
}';
      when
         p_integration_name = upper('XX_OTM_POST_DESTUFFING_CONTAINER')
         and p_statuscodegid = 'NAQLEEN.CONTAINER STORED'
      then
         l_input_request := l_input_request
                            || ',"attribute1": "'
                            || p_attribute1
                            || '"
                            
}';
      when
         p_integration_name = upper('XX_OTM_POST_POSITION_CONTAINER')
         and p_statuscodegid = 'NAQLEEN.CONTAINER STORED'
      then
         l_input_request := l_input_request
                            || ',"attribute1": "'
                            || p_attribute1
                            || '"
}';
  when
         p_integration_name = upper('XX_OTM_RELEASE_CONTAINER')
         and p_statuscodegid = 'NAQLEEN.CONTAINER RELEASED'
      then
          l_input_request := l_input_request
                            || ',"attribute3": "'
                            || p_attribute3
                            || '","attributeNumber1": '
                            || NVL(p_attribute_number1, 0)
                            || ',"attributeNumber2": '
                            || NVL(p_attribute_number2, 0)
                            || ',"attributeNumber3": '
                            || NVL(p_attribute_number3, 0)
                            || '
}';
  when
         p_statuscodegid = 'NAQLEEN.CONTAINER_RESTACKED'
      then
        l_input_request := l_input_request
                            || ',"attribute1": "'
                            || p_attribute1
                            || '"
}';
     when p_statuscodegid = upper('NAQLEEN.GATE IN') then
         if p_attribute3 is not null then
            l_input_request := l_input_request || ',"attribute3": "' || p_attribute3 || '"';
         end if;
         if p_attribute5 is not null then
            l_input_request := l_input_request || ',"attribute5": "' || p_attribute5 || '"';
         end if;
         l_input_request := l_input_request || '
}';
  when
         p_statuscodegid = 'NAQLEEN.TASK_ASSIGNED'
         and p_attribute3 IS NOT null
      then
        l_input_request := l_input_request
                            || ',"attribute3": "'
                            || p_attribute3
                            || '"
}';

      else
         l_input_request := l_input_request || '}';
   end case;

   begin
      l_clob := apex_web_service.make_rest_request(
         p_url         => xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/trackingEvents'
         ,
         p_http_method => 'POST',
         p_credential_static_id => l_credential_static_id,
         p_body        => l_input_request,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
      x_response := l_clob;
   exception
      when others then
         l_error_msg := 'Error occured while calling Naqleen service ' || sqlerrm;
         dbms_output.put_line('ERROR  ' || l_error_msg);
         x_response := l_error_msg;
   end;
--dbms_output.put_line(l_clob);
--dbms_output.put_line(l_input_request);
   begin
      insert into xx_ws_payloads_t values ( p_statuscodegid,
                                            null,
                                            l_input_request,
                                            l_clob,
                                            sysdate,
                                            xx_payload_seq.nextval );

   end;

end post_otm_tracking_events;

   -- ========================================================================
   -- XXOTM_ASSIGN_ROLE_TO_USER_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_ASSIGN_ROLE_TO_USER_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_assign_role_to_user_p (
    P_BODY IN CLOB
)
AS
    v_json_obj      JSON_OBJECT_T;
    v_user_id       NUMBER;
    v_role_code     VARCHAR2(100);
    v_action        VARCHAR2(20);
    v_count         NUMBER;
BEGIN
    v_json_obj := JSON_OBJECT_T.PARSE(P_BODY);
    v_user_id := v_json_obj.GET_NUMBER('userId');
    v_role_code := v_json_obj.GET_STRING('roleCode');
    v_action := v_json_obj.GET_STRING('action'); -- 'assign' or 'remove'
    
    IF v_action = 'assign' THEN
        -- Upsert: Update if exists, else insert
        MERGE INTO XX_USER_ROLE_ASSIGNMENT ua
        USING DUAL ON (ua.USER_ID = v_user_id AND ua.ROLE_CODE = v_role_code)
        WHEN MATCHED THEN
            UPDATE SET IS_ACTIVE = 'Y', LAST_UPDATE_DATE = SYSDATE, LAST_UPDATED_BY = USER
        WHEN NOT MATCHED THEN
            INSERT (ASSIGNMENT_ID, USER_ID, ROLE_CODE, IS_ACTIVE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (XX_USER_ROLE_ASSIGNMENT_ID_SEQ.NEXTVAL, v_user_id, v_role_code, 'Y', SYSDATE, USER, SYSDATE, USER);
            
    ELSIF v_action = 'remove' THEN
        UPDATE XX_USER_ROLE_ASSIGNMENT
        SET IS_ACTIVE = 'N', LAST_UPDATE_DATE = SYSDATE, LAST_UPDATED_BY = USER
        WHERE USER_ID = v_user_id AND ROLE_CODE = v_role_code;
    END IF;
    
    COMMIT;
    
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 200);
    APEX_JSON.WRITE('response_message', 'Success');
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
    
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        APEX_JSON.INITIALIZE_CLOB_OUTPUT;
        APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('response_code', 500);
        APEX_JSON.WRITE('response_message', 'Error: ' || SQLERRM);
        APEX_JSON.CLOSE_OBJECT;
        HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XXOTM_ASSIGN_ROLE_TO_USER_P;

   -- ========================================================================
   -- XXOTM_AUTHENTICATE_USER_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_AUTHENTICATE_USER_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_authenticate_user_p (
    P_EMAIL IN VARCHAR2,
    P_PASSWORD IN VARCHAR2,
    p_platform IN VARCHAR2 DEFAULT 'OTM_MOBILE_APP'
)
IS
    l_response_clob CLOB;
    l_access_token  VARCHAR2(10000);
    l_status_code   NUMBER;
    l_requestState  VARCHAR2(10000);
    l_email         VARCHAR2(1000);
    l_json_body     CLOB;
    jo              JSON_OBJECT_T;
    l_user_rec      XX_USER_CONFIG%ROWTYPE;
    l_response      JSON_OBJECT_T := JSON_OBJECT_T();
    l_data          JSON_OBJECT_T;
    ja_roles        JSON_ARRAY_T;
    ja_screens      JSON_ARRAY_T;
    l_screen_data   JSON_OBJECT_T;
	l_screen_role   varchar2(100);
    J               APEX_JSON.T_VALUES;
BEGIN
    -- 1. Check if user exists in XX_USER_CONFIG (by EMAIL)
    BEGIN
        SELECT * INTO l_user_rec 
        FROM XX_USER_CONFIG 
        WHERE LOWER(EMAIL) = LOWER(P_EMAIL)
          AND IS_ACTIVE = 'Y'
          AND ROWNUM = 1;
		 dbms_output.put_line('Platform received: ' || nvl(p_platform, 'NULL'));
        l_email := lower(l_user_rec.EMAIL);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            l_response.put('response_code', 404);
            l_response.put('response_message', 'User not found or inactive');
            GOTO output_json;
        WHEN OTHERS THEN
            l_response.put('response_code', 500);
            l_response.put('response_message', 'Database verification error: ' || SQLERRM);
            GOTO output_json;
    END;

    -- 2. Get IDCS Access Token
    l_access_token := REPLACE(XXOTM_IDCS_GET_TOKEN(), '"', '');

    IF l_access_token IS NULL THEN
        l_response.put('response_code', 401);
        l_response.put('response_message', 'Failed to obtain system access token');
        GOTO output_json;
    END IF;

    -- setup headers
    apex_web_service.g_request_headers.delete;
    apex_web_service.g_request_headers(1).name := 'Content-Type';
    apex_web_service.g_request_headers(1).value := 'application/json';
    apex_web_service.g_request_headers(2).name := 'Authorization';
    apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

    -- 3. IDCS: GET requestState
    -- Host from config, not a literal: prod and test are different identity
    -- domains, so the hardcoded tenant meant this body could never be identical
    -- in both environments -- and in test it authenticated against prod's IDCS.
    l_response_clob := apex_web_service.make_rest_request(
        p_url => xxotm_get_cfg('IDCS_BASE_URL') || '/sso/v1/sdk/authenticate',
        p_http_method => 'GET',
        p_wallet_path => xxotm_get_cfg('WALLET_PATH')
    );

    IF apex_web_service.g_status_code NOT BETWEEN 200 AND 299 THEN
        l_response.put('response_code', 401);
        l_response.put('response_message', 'IDCS Authentication Init Failed');
        GOTO output_json;
    END IF;

    jo := JSON_OBJECT_T.parse(l_response_clob);
    l_requestState := jo.get('requestState').to_string();
    l_requestState := REPLACE(l_requestState, '"', '');

    -- 4. IDCS: POST credentials
    DECLARE
        l_creds_json JSON_OBJECT_T := JSON_OBJECT_T();
        l_req_json   JSON_OBJECT_T := JSON_OBJECT_T();
    BEGIN
        l_creds_json.put('username', l_email); -- IDCS uses Email
        l_creds_json.put('password', P_PASSWORD);

        l_req_json.put('op', 'credSubmit');
        l_req_json.put('credentials', l_creds_json);
        l_req_json.put('requestState', l_requestState);

        l_json_body := l_req_json.to_clob;
    END;

    apex_web_service.g_request_headers(1).name := 'Content-Type';
    apex_web_service.g_request_headers(1).value := 'application/json';
    apex_web_service.g_request_headers(2).name := 'Authorization';
    apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

    l_response_clob := apex_web_service.make_rest_request(
        p_url => xxotm_get_cfg('IDCS_BASE_URL') || '/sso/v1/sdk/authenticate',
        p_http_method => 'POST',
        p_body => l_json_body,
        p_wallet_path => xxotm_get_cfg('WALLET_PATH')
    );

    l_status_code := apex_web_service.g_status_code;

    IF l_status_code BETWEEN 200 AND 299 THEN
        -- Success
        l_response.put('response_code', 200);
        l_response.put('response_message', 'Success');

        l_data := JSON_OBJECT_T();
        l_data.put('user_id', l_user_rec.ID);
        l_data.put('name', l_user_rec.NAME);
        l_data.put('email', l_user_rec.EMAIL);
        l_data.put('role', l_user_rec.ROLE);

        -- Add Roles Array
        ja_roles := JSON_ARRAY_T();
        -- Add Primary Role
        ja_roles.append(l_user_rec.ROLE);

        -- Add Secondary Roles
        FOR r IN (
            SELECT role_code 
            FROM XX_USER_ROLE_ASSIGNMENT 
            WHERE user_id = l_user_rec.ID 
              AND is_active = 'Y'
              AND role_code != l_user_rec.ROLE
        ) LOOP
            ja_roles.append(r.role_code);
        END LOOP;

        l_data.put('roles', ja_roles);

        -- SCREENS Array (Aggregated with Role)
        ja_screens := JSON_ARRAY_T();

        for s in (
            -- Screens from User Assignments
                select rc.role, rc.screen_name, rc.screen_path, rc.is_active
                    from xx_role_config rc
                    join xx_user_role_assignment ura on rc.role = ura.role_code
                    where ura.user_id = to_number(l_user_rec.ID)
                    and rc.is_active = 'Y' and ura.is_active = 'Y' AND (p_platform IS NOT NULL AND  platform = p_platform)
            order by role, screen_name
        ) loop
            l_screen_data := JSON_OBJECT_T();
            l_screen_data.put('screen_name', s.screen_name);
            l_screen_data.put('screen_path', s.screen_path);
            l_screen_data.put('is_active', s.is_active = 'Y');
	        l_screen_data.put('role', s.role); -- Added Role field
            ja_screens.append(l_screen_data);
        end loop;
            -- if l_user_rec.ID = 29 and p_platform = 'CMS'
            -- then
            --    l_screen_data.put('screen_name', 'Access Control');
            --    l_screen_data.put('screen_path', '/access-control');
            --    l_screen_data.put('is_active', true);
   	        -- l_screen_data.put('role', 'DEVELOPERS'); -- Added Role field
            --    ja_screens.append(l_screen_data);
            --    l_screen_data.put('screen_name', 'Manage Role');
            --    l_screen_data.put('screen_path', '/manage-role');
            --    l_screen_data.put('is_active', true);
   	        -- l_screen_data.put('role', 'DEVELOPERS'); -- Added Role field
            --    ja_screens.append(l_screen_data);
            -- end if;
        l_data.put('screens', ja_screens);

        -- ---------------------------------------------------------
        -- NEW: Parse ACCESSIBLE_LOCATIONS and add to response
        -- ---------------------------------------------------------
        DECLARE
            ja_locations JSON_ARRAY_T := JSON_ARRAY_T();
            jo_loc       JSON_OBJECT_T;
            l_loc_str    VARCHAR2(4000) := l_user_rec.ACCESSIBLE_LOCATIONS;
            l_loc_id     VARCHAR2(100);
            l_loc_name   VARCHAR2(200);
        BEGIN
            IF l_loc_str IS NOT NULL THEN
                -- Loop through the comma-separated string
                FOR i IN 1 .. REGEXP_COUNT(l_loc_str, ',') + 1 LOOP
                    l_loc_id := TRIM(REGEXP_SUBSTR(l_loc_str, '[^,]+', 1, i));
                    
                    IF l_loc_id IS NOT NULL THEN
                        jo_loc := JSON_OBJECT_T();
                        jo_loc.put('id', l_loc_id);
                        
                        -- Map the location ID to the Terminal Name
                        IF l_loc_id = '102' THEN
                            l_loc_name := 'Dammam';
                        ELSIF l_loc_id = '103' THEN
                            l_loc_name := 'Jeddah';
                        ELSE
                            l_loc_name := 'Unknown Location';
                        END IF;
                        
                        jo_loc.put('name', l_loc_name);
                        ja_locations.append(jo_loc);
                    END IF;
                END LOOP;
            END IF;
            
            -- Attach the accessible_locations array to the data object
            l_data.put('accessible_locations', ja_locations);
        END;
        -- ---------------------------------------------------------

        l_response.put('data', l_data);

        -- Update Last Login
        UPDATE XX_USER_CONFIG 
        SET LASTLOGINAT = SYSDATE 
        WHERE ID = l_user_rec.ID;
        COMMIT;

    ELSE
        l_response.put('response_code', 401);
        l_response.put('response_message', 'Invalid Credentials');
    END IF;

    <<output_json>>
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', l_response.get('response_code').to_number());
    APEX_JSON.WRITE('response_message', REPLACE(l_response.get('response_message').to_string(), '"', ''));

    IF l_response.has('data') THEN
        APEX_JSON.PARSE(J, l_data.to_string());
        APEX_JSON.WRITE('data', J);
    END IF;

    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);

EXCEPTION WHEN OTHERS THEN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 500);
    APEX_JSON.WRITE('response_message', 'Internal Error: ' || SQLERRM);
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XXOTM_AUTHENTICATE_USER_P;

   -- ========================================================================
   -- XXOTM_CONTAINER_GRVITY_SCRIPT_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_CONTAINER_GRVITY_SCRIPT_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_container_grvity_script_p
as
    TYPE l_loc IS TABLE OF VARCHAR2(100);

begin
FOR i IN (
SELECT 
    t1.terminal||'-'|| 
    t1.block||'-'||
    t1.lot_no||'-'||
    t1.row_no AS SLOT
FROM 
    xxotm_position_master_t t1
LEFT JOIN 
    xxotm_position_master_t t2 
ON 
    t1.terminal = t2.terminal 
    AND t1.block = t2.block 
    AND t1.lot_no = t2.lot_no 
    AND t1.row_no = t2.row_no 
    AND t2.level_no = (t1.level_no - 1)
WHERE 
    t1.is_occupied != 'N' 
    AND t1.level_no > 1
    AND (t2.is_occupied = 'N' OR t2.is_occupied IS NULL)

) LOOP

        DECLARE
            -- The specific stack you want to update
            v_target_stack VARCHAR2(100) := i.SLOT;-- <--- UPDATE THIS VALUE HERE

    -- Extracted components
   v_test_term    varchar2(50);
   v_test_block   varchar2(50);
   v_test_lot_no  varchar2(50);
   v_test_row_no  varchar2(50);

    -- Find all distinct stacks (Terminal, Block, Lot, Row) that have floating containers
    -- FOR A SPECIFIC LOCATION ONLY
   cursor c_stacks (
      p_term   varchar2,
      p_block  varchar2,
      p_lot_no varchar2,
      p_row_no varchar2
   ) is
   select distinct t1.terminal,
                   t1.block,
                   t1.lot_no,
                   t1.row_no
     from xxotm_position_master_t t1
     left join xxotm_position_master_t t2
   on t1.terminal = t2.terminal
      and t1.block = t2.block
      and t1.lot_no = t2.lot_no
      and t1.row_no = t2.row_no
      and t2.level_no = ( t1.level_no - 1 )
    where t1.is_occupied != 'N'
      and t1.level_no > 1
      and ( t2.is_occupied = 'N'
       or t2.is_occupied is null )
      and t1.terminal = p_term
      and t1.block = p_block
      and t1.lot_no = p_lot_no
      and t1.row_no = p_row_no;

    -- For a given stack, get all occupied containers ordered by level (lowest to highest)
   cursor c_containers (
      p_term  varchar2,
      p_block varchar2,
      p_lot   varchar2,
      p_row   varchar2
   ) is
   select level_no,
          container_nbr,
          shipment_nbr,
          is_occupied
     from xxotm_position_master_t
    where terminal = p_term
      and block = p_block
      and lot_no = p_lot
      and row_no = p_row
      and is_occupied != 'N'
    order by level_no;

   v_new_level    number;
   v_new_pos      varchar2(200);
   v_old_pos      varchar2(200);
   v_stacks_found number := 0;
   v_api_response clob;
   v_timestamp    varchar2(100);
begin
    -- Parse the target stack string dynamically
   v_test_term := regexp_substr(
      v_target_stack,
      '[^-]+',
      1,
      1
   );
   v_test_block := regexp_substr(
      v_target_stack,
      '[^-]+',
      1,
      2
   );
   v_test_lot_no := regexp_substr(
      v_target_stack,
      '[^-]+',
      1,
      3
   );
   v_test_row_no := regexp_substr(
      v_target_stack,
      '[^-]+',
      1,
      4
   );
   dbms_output.put_line('--- STARTING EXECUTION FOR LOCATION: '
                        || v_target_stack
                        || ' ---');
   for stack in c_stacks(
      v_test_term,
      v_test_block,
      v_test_lot_no,
      v_test_row_no
   ) loop
      v_stacks_found := v_stacks_found + 1;
      v_new_level := 1; -- We want to start stacking from level 1 upwards

      dbms_output.put_line('-- Processing Stack: '
                           || stack.terminal
                           || '-'
                           || stack.block
                           || '-'
                           || stack.lot_no
                           || '-'
                           || stack.row_no);

      for cont in c_containers(
         stack.terminal,
         stack.block,
         stack.lot_no,
         stack.row_no
      ) loop
            -- If the container is higher than the new target level, move it down
         if cont.level_no > v_new_level then
            v_old_pos := stack.terminal
                         || '-'
                         || stack.block
                         || '-'
                         || stack.lot_no
                         || '-'
                         || stack.row_no
                         || '-'
                         || cont.level_no;
            v_new_pos := stack.terminal
                         || '-'
                         || stack.block
                         || '-'
                         || stack.lot_no
                         || '-'
                         || stack.row_no
                         || '-'
                         || v_new_level;

            v_timestamp := to_char(
               sys_extract_utc(systimestamp),
               'YYYY-MM-DD"T"HH24:MI:SS"Z"'
            );
            dbms_output.put_line('  Moving Container '
                                 || nvl(
               cont.container_nbr,
               'UNNAMED_CONT'
            )
                                 || ' from '
                                 || v_old_pos
                                 || ' to '
                                 || v_new_pos);

                -- 1. Log to LOLO table
            insert into xxotm_restack_lolo_t (
               container_nbr,
               current_position,
               restack_position,
               updated_date,
               inbound_shipment_nbr
            ) values ( cont.container_nbr,
                       v_old_pos,
                       v_new_pos,
                       v_timestamp,
                       cont.shipment_nbr );

                -- 2. Update Inventory Position
            update xxotm_container_inventory_t
               set
               position = v_new_pos
             where container_nbr = cont.container_nbr
               and inbound_shipment_nbr = cont.shipment_nbr;

                -- 3. Free Current (Old) Position
            update xxotm_position_master_t
               set shipment_nbr = null,
                   container_nbr = null,
                   is_occupied = 'N',
                   last_event_time = systimestamp,
                   last_event_source = 'GRAVITY_SCRIPT'
             where terminal = stack.terminal
               and block = stack.block
               and lot_no = stack.lot_no
               and row_no = stack.row_no
               and level_no = cont.level_no;

                -- Sync log for freeing position
            insert into xx_otm_sync_logs (
               procedure_name,
               message_type,
               message_text,
               reference_id
            ) values ( 'GRAVITY_SCRIPT',
                       'INFO',
                       'Freed position master for container: '
                       || cont.container_nbr
                       || ' at '
                       || v_old_pos,
                       cont.shipment_nbr );

                -- 4. Occupy New Position
            update xxotm_position_master_t
               set shipment_nbr = cont.shipment_nbr,
                   container_nbr = cont.container_nbr,
                   is_occupied = cont.container_nbr,
                   last_event_time = systimestamp,
                   last_event_source = 'GRAVITY_SCRIPT'
             where terminal = stack.terminal
               and block = stack.block
               and lot_no = stack.lot_no
               and row_no = stack.row_no
               and level_no = v_new_level;

                -- Sync log for occupying position
            insert into xx_otm_sync_logs (
               procedure_name,
               message_type,
               message_text,
               reference_id
            ) values ( 'GRAVITY_SCRIPT',
                       'INFO',
                       'Updated position master for container: '
                       || cont.container_nbr
                       || ' at '
                       || v_new_pos,
                       cont.shipment_nbr );

            dbms_output.put_line('  -> Tables updated successfully.');

                -- 5. Send OTM Tracking Event
            begin
               post_otm_tracking_events(
                  p_integration_name => 'XX_OTM_RESTACK_CONTAINER',
                  p_statuscodegid    => 'NAQLEEN.CONTAINER_RESTACKED',
                  p_shipmentxid      => cont.shipment_nbr,
                  p_attribute3       => cont.container_nbr,
                  p_attribute1       => v_new_pos,
                  x_response         => v_api_response
               );

               dbms_output.put_line('  -> Event CONTAINER_RESTACKED posted. OTM API Response: '
                                    || dbms_lob.substr(
                  v_api_response,
                  100,
                  1
               ));

               if v_api_response like '%Error%' then
                  dbms_output.put_line('     WARNING: OTM API returned an error.');
               end if;
            exception
               when others then
                  dbms_output.put_line('  -> ERROR posting OTM event: ' || sqlerrm);
            end;

         end if;

            -- Increment the level for the next container in the same stack (so next one rests on this one)
         v_new_level := v_new_level + 1;
      end loop;
      dbms_output.put_line('----------------------------------------------------');
   end loop;

   if v_stacks_found > 0 then
      commit;  -- Commit all changes only if floating containers were successfully found/restacked
      dbms_output.put_line('COMMITTED data changes.');
   else
      dbms_output.put_line('No "floating" containers found in '
                           || v_target_stack
                           || ' to update.');
   end if;

   dbms_output.put_line('--- EXECUTION COMPLETED ---');
exception
   when others then
      rollback;
      dbms_output.put_line('--- ERROR OCCURRED: ROLLED BACK TRANSACTIONS ---');
      dbms_output.put_line(sqlerrm);
end;

end loop;
end;

   -- ========================================================================
   -- XXOTM_CREATE_ROLE_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_CREATE_ROLE_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_create_role_p (P_BODY IN CLOB)
AS
    v_json JSON_OBJECT_T;
    v_role_name VARCHAR2(100);
    v_screens JSON_ARRAY_T;
    v_screen_obj JSON_OBJECT_T;
    v_count NUMBER;

    -- Local variables to hold extracted values
    v_s_name VARCHAR2(255);
    v_s_path VARCHAR2(255);
BEGIN
    v_json := JSON_OBJECT_T.PARSE(P_BODY);
    v_role_name := UPPER(TRIM(v_json.GET_STRING('roleName')));
    v_screens := v_json.GET_ARRAY('screens');

    -- Check for duplicate
    SELECT COUNT(*) INTO v_count FROM XX_ROLE_CONFIG WHERE ROLE = v_role_name;

    IF v_count > 0 THEN
         HTP.P('{"response_code": 409, "response_message": "Role already exists"}');
         RETURN;
    END IF;

    -- Insert screens for the role
    IF v_screens IS NOT NULL THEN
        FOR i IN 0 .. v_screens.GET_SIZE - 1 LOOP
            -- Use TREAT to safely cast the array element to an object
            v_screen_obj := TREAT(v_screens.GET(i) AS JSON_OBJECT_T);

            -- Extract values to PL/SQL variables first (Avoids ORA-40573)
            v_s_name := v_screen_obj.GET_STRING('screenName');
            v_s_path := v_screen_obj.GET_STRING('screenPath');

            INSERT INTO XX_ROLE_CONFIG (ROLE, SCREEN_NAME, SCREEN_PATH, IS_ACTIVE, CREATED_DATE, CREATED_BY)
            VALUES (
                v_role_name,
                v_s_name,
                v_s_path,
                'N', -- Initialize as Denied
                SYSDATE,
                'ADMIN'
            );
        END LOOP;
    END IF;

    COMMIT;

    HTP.P('{"response_code": 200, "response_message": "Role created"}');

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        HTP.P('{"response_code": 500, "response_message": "' || REPLACE(SQLERRM, '"', '\"') || '"}');
END XXOTM_CREATE_ROLE_P;

   -- ========================================================================
   -- XXOTM_DELETE_RESERVATION_CONTAINERS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_DELETE_RESERVATION_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_delete_reservation_containers_p (
   -- Last Updated Date : 17-Dec-2025
   -- Last Updated By : Madhan
   -- Description : unreserving/deleting the booking id from container.
   payload in blob,
   p_user_id in varchar2 default null
)
is
   v_location varchar2(100);
   -- Convert payload
   p_payload             clob;

   -- Request variables
   l_booking_id          varchar2(100);
   l_container_nbr       varchar2(100);
   l_container_order_nbr varchar2(100);   -- Order linked to container

   -- Web service variables
   l_base_url            varchar2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2'
   ;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_wallet_path         varchar2(100) := 'file:/u01/app/oracle/product/wallet';
   l_api_url             varchar2(1000);
   l_api_response        clob;
   l_http_status         number;

   -- Tracking
   l_success_count       number := 0;
   l_fail_count          number := 0;
   l_total_count         number := 0;
   l_failed_containers   varchar2(4000) := null;
   l_api_error_msg       varchar2(500);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert BLOB to CLOB
   p_payload := to_clob(payload);

   -- Parse the JSON payload
   apex_json.parse(p_payload);

   -- Extract booking_id
   l_booking_id := apex_json.get_varchar2(p_path => 'booking_id');

   -- Validate booking_id
   if l_booking_id is null then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'booking_id is required'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   -- Get containers array count
   l_total_count := apex_json.get_count(p_path => 'unreserve_containers');
   if l_total_count is null
   or l_total_count = 0 then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'unreserve_containers array is empty or missing'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   -- Loop through each container
   for i in 1..l_total_count loop
      begin
         -- Get container number from array
         l_container_nbr := apex_json.get_varchar2(
            p_path => 'unreserve_containers[%d]',
            p0     => i
         );
         if l_container_nbr is null then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := 'Container['
                                      || i
                                      || '] is null';
            else
               l_failed_containers := l_failed_containers
                                      || ', Container['
                                      || i
                                      || '] is null';
            end if;
            continue;
         end if;

         -- ==================================================
         -- STEP 1: Fetch inbound_order_nbr for the CONTAINER
         -- (where container_nbr matches and booking_id matches)
         -- ==================================================
         begin
            select inbound_order_nbr
              into l_container_order_nbr
              from xxotm_container_inventory_t
             where container_nbr = l_container_nbr
               and booking_id = l_booking_id  and xxotm_container_inventory_t.location = v_location
               and rownum = 1;
         exception
            when no_data_found then
               -- Fallback: try finding it even if booking_id mismatch or null, 
               -- but safer to require match to ensure ownership.
               -- For now, strict match.
               l_container_order_nbr := null;
         end;

         if l_container_order_nbr is null then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := l_container_nbr || ' (no matching order for this booking)';
            else
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_container_nbr
                                      || ' (no matching order)';
            end if;
            continue;
         end if;

         -- ==================================================
         -- STEP 2: DELETE refnums - Remove Link booking from container's order
         -- DELETE /orderReleases/NAQLEEN.{container_order_nbr}/refnums/NAQLEEN.BOOKING_NO%7C{booking_id}
         -- Note: Using Composite Key format commonly used in OTM REST: {qualifier}|{value} or similar
         -- Previous attempt used 'x' separator. I will proceed with 'x' for now as per prior context, 
         -- but note that pipe '|' is also common.
         -- ==================================================
         l_api_url := l_base_url
                      || '/orderReleases/NAQLEEN.'
                      || l_container_order_nbr
                      || '/refnums/NAQLEEN.BOOKING_NOx'
                      || l_booking_id;
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_api_response := apex_web_service.make_rest_request(
            p_url         => l_api_url,
            p_http_method => 'DELETE',
            p_credential_static_id=> l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
         l_http_status := apex_web_service.g_status_code;

         -- 204 No Content is typical for DELETE success
         if l_http_status in ( 200,
                               204 ) then
            l_success_count := l_success_count + 1;

            -- Update Inventory: Remove booking_ID
            update xxotm_container_inventory_t
               set
               booking_id = null
             where container_nbr = l_container_nbr  and xxotm_container_inventory_t.location = v_location;

         else
            l_fail_count := l_fail_count + 1;
            l_api_error_msg := substr(
               nvl(
                  l_api_response,
                  'No response'
               ),
               1,
               200
            );
            if l_failed_containers is null then
               l_failed_containers := l_container_nbr
                                      || ' (DELETE '
                                      || l_http_status
                                      || ': '
                                      || l_api_error_msg
                                      || ')';
            elsif length(l_failed_containers) < 3500 then
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_container_nbr
                                      || ' (DELETE '
                                      || l_http_status
                                      || ')';
            end if;
         end if;

      exception
         when others then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := l_container_nbr
                                      || ' (Exception: '
                                      || substr(
                  sqlerrm,
                  1,
                  150
               )
                                      || ')';
            elsif length(l_failed_containers) < 3500 then
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_container_nbr
                                      || ' (Ex: '
                                      || substr(
                  sqlerrm,
                  1,
                  50
               )
                                      || ')';
            end if;
      end;
   end loop;

   -- Build response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_fail_count = 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Successfully unreserved '
         || l_success_count
         || ' containers'
      );
   elsif l_success_count = 0 then
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Failed to unreserve containers'
      );
   else
      apex_json.write(
         'response_code',
         207
      );
      apex_json.write(
         'response_message',
         'Partial: '
         || l_success_count
         || ' unreserved, '
         || l_fail_count
         || ' failed'
      );
   end if;

   apex_json.write(
      'success_count',
      l_success_count
   );
   apex_json.write(
      'fail_count',
      l_fail_count
   );
   apex_json.write(
      'booking_id',
      l_booking_id
   );
   if l_failed_containers is not null then
      apex_json.write(
         'debug_errors',
         l_failed_containers
      );
   end if;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Unexpected error: ' || sqlerrm
      );
      apex_json.write(
         'debug_errors',
         'Global exception: '
         || substr(
            sqlerrm,
            1,
            500
         )
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xxotm_delete_reservation_containers_p;

   -- ========================================================================
   -- XXOTM_DELETE_ROLE_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_DELETE_ROLE_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_delete_role_p (
    p_role_name IN VARCHAR2
)
AS
BEGIN
    -- Remove User Assignments
    DELETE FROM XX_USER_ROLE_ASSIGNMENT WHERE ROLE_CODE = p_role_name;

    -- Remove Permissions
    DELETE FROM XX_ROLE_CONFIG WHERE ROLE = p_role_name;

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END XXOTM_DELETE_ROLE_P;

   -- ========================================================================
   -- XXOTM_DELETE_TRUCK_P   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XXOTM_DELETE_TRUCK_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_delete_truck_p (
    p_truck_id IN VARCHAR2,
    p_user_id  IN VARCHAR2 DEFAULT NULL
)
AS
    -- Declared bare, assigned after BEGIN.
    v_location      VARCHAR2(100);
    l_status        VARCHAR2(100);
    l_order_type    VARCHAR2(50);
    l_shipment_nbr  VARCHAR2(4000);
    l_entry_time    VARCHAR2(100);                   -- ← added
    l_can_delete    BOOLEAN := FALSE;
    l_shp_count     NUMBER  := 0;
    -- Set alongside every apex_json response_code below, so the audit row
    -- records the code actually returned rather than assuming success. The four
    -- branches (200/400/409/404) converge after the inner block; without this
    -- the code is a literal in each and there is nothing to log.
    l_audit_code    NUMBER;
    l_audit_msg     VARCHAR2(400);
    resource_busy   EXCEPTION;
    PRAGMA EXCEPTION_INIT(resource_busy, -54);

    -- Host from config; the plaintext NAQLEEN.INTEGRATION password that used to
    -- be a constant here is gone -- the call below uses the OTM_API_AUTH
    -- credential instead of hand-rolling a Basic header.
    c_base_url      VARCHAR2(500);
    c_cred CONSTANT VARCHAR2(30) := 'OTM_API_AUTH';

    l_api_shp_found BOOLEAN := FALSE;
    l_api_work_done BOOLEAN := FALSE;

    -- ── normalize_tstz ────────────────────────────────────────────────────────
    -- Converts ISO-8601 strings (with Z or +HH:MM) to TIMESTAMP WITH TIME ZONE.
    -- Mirrors sync.sql normalize_tstz — handles fractional seconds or none.
    -- ─────────────────────────────────────────────────────────────────────────
    FUNCTION normalize_tstz(p_str IN VARCHAR2) RETURN TIMESTAMP WITH TIME ZONE IS
        v_str VARCHAR2(100);
    BEGIN
        IF p_str IS NULL THEN RETURN NULL; END IF;
        v_str := REPLACE(REPLACE(p_str, 'Z', '+00:00'), '+03:00', '+00:00');
        BEGIN
            RETURN TO_TIMESTAMP_TZ(v_str, 'YYYY-MM-DD"T"HH24:MI:SSFFTZH:TZM');
        EXCEPTION WHEN OTHERS THEN NULL; END;
        BEGIN
            RETURN TO_TIMESTAMP_TZ(v_str, 'YYYY-MM-DD"T"HH24:MI:SSTZH:TZM');
        EXCEPTION WHEN OTHERS THEN RETURN NULL; END;
    END normalize_tstz;

    -- ── call_otm_api ──────────────────────────────────────────────────────────
    -- For each shipment returned by the API, first checks that trackingEvents
    -- contains a VEHICLE ENTERED / GATE IN event at or after l_entry_time
    -- (anchors the shipment to THIS visit, not a past one).
    -- Only anchored shipments count toward l_api_shp_found.
    -- Among anchored shipments, sets l_api_work_done if a work-complete event
    -- is also present.
    -- ─────────────────────────────────────────────────────────────────────────
    PROCEDURE call_otm_api IS
        l_encoded_cred  VARCHAR2(400);
        l_query_params  VARCHAR2(2000);
        l_next_url      VARCHAR2(4000);
        l_response      CLOB;
        jo              json_object_t;
        l_items         json_array_t;
        l_item          json_object_t;
        l_links         json_array_t;
        l_link          json_object_t;
        l_te_obj        json_object_t;
        l_te_items      json_array_t;
        l_te_item       json_object_t;
        l_event_type    VARCHAR2(200);
        l_event_ts      TIMESTAMP WITH TIME ZONE;
        l_entry_ts      TIMESTAMP WITH TIME ZONE;
        l_evt_time_obj  json_object_t;
        l_is_anchored   BOOLEAN;
        l_shp_work_done BOOLEAN;
    BEGIN
        l_entry_ts := normalize_tstz(l_entry_time);   -- vehicle entry timestamp

        l_query_params :=
            'q=attribute1 eq "TERMINAL"'
            || ' and perspective eq "B"'
            || ' and attribute7 eq "' || p_truck_id || '"'
            || ' and refnums.shipmentRefnumQualGid eq "NAQLEEN.LOCATION"'
            || ' and refnums.shipmentRefnumValue eq "' || v_location || '"'
            || '&expand=trackingEvents&limit=100';

        l_next_url := c_base_url || '?' || utl_url.escape(l_query_params);

        WHILE l_next_url IS NOT NULL AND LOWER(l_next_url) <> 'null' LOOP

            apex_web_service.g_request_headers(1).name  := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            apex_web_service.g_request_headers(2).name  := 'Accept';
            apex_web_service.g_request_headers(2).value := 'application/json';

            l_response := apex_web_service.make_rest_request(
                p_url         => l_next_url,
                p_http_method => 'GET',
                p_credential_static_id => c_cred,
                p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
            );

            IF apex_web_service.g_status_code < 200
            OR apex_web_service.g_status_code > 299 THEN
                l_next_url := NULL;
            ELSE
                jo := json_object_t.parse(l_response);

                -- Next-page link
                l_next_url := NULL;
                IF jo.has('hasMore') AND jo.get_boolean('hasMore') THEN
                    l_links := jo.get_array('links');
                    FOR i IN 0 .. l_links.get_size() - 1 LOOP
                        l_link := treat(l_links.get(i) AS json_object_t);
                        IF l_link.get_string('rel') = 'next' THEN
                            l_next_url := l_link.get_string('href');
                            EXIT;
                        END IF;
                    END LOOP;
                END IF;

                IF jo.get('items').is_array THEN
                    l_items := json_array_t.parse(jo.get('items').to_clob());

                    FOR idx IN 0 .. l_items.get_size() - 1 LOOP
                        l_item         := treat(l_items.get(idx) AS json_object_t);
                        l_is_anchored  := FALSE;
                        l_shp_work_done := FALSE;

                        IF l_item.has('trackingEvents') THEN
                            l_te_obj := treat(l_item.get('trackingEvents') AS json_object_t);

                            IF l_te_obj.has('items') AND l_te_obj.get('items').is_array THEN
                                l_te_items := l_te_obj.get_array('items');

                                FOR t IN 0 .. l_te_items.get_size() - 1 LOOP
                                    l_te_item    := treat(l_te_items.get(t) AS json_object_t);
                                    l_event_type := REPLACE(
                                        l_te_item.get_string('eventTypeGid'),
                                        'NAQLEEN.', ''
                                    );

                                    -- Parse event timestamp
                                    l_event_ts := NULL;
                                    IF l_te_item.has('eventTime') THEN
                                        l_evt_time_obj := treat(
                                            l_te_item.get('eventTime') AS json_object_t
                                        );
                                        IF l_evt_time_obj.has('value') THEN
                                            l_event_ts := normalize_tstz(
                                                l_evt_time_obj.get_string('value')
                                            );
                                        END IF;
                                    END IF;

                                    -- Anchor check: VEHICLE ENTERED / GATE IN at or after entry
                                    IF l_event_type IN ('VEHICLE ENTERED', 'GATE IN')
                                       AND l_event_ts IS NOT NULL
                                       AND l_entry_ts IS NOT NULL
                                       AND l_event_ts >= l_entry_ts THEN
                                        l_is_anchored := TRUE;
                                    END IF;

                                    -- Work-complete check (same events as l_level = 40)
                                    IF l_event_type IN (
                                           'CONTAINER STORED',
                                           'CONTAINER RELEASED',
                                           'STUFFED',
                                           'DESTUFFED'
                                       ) THEN
                                        l_shp_work_done := TRUE;
                                    END IF;

                                END LOOP;
                            END IF;
                        END IF;

                        -- Only count shipments anchored to this visit
                        IF l_is_anchored THEN
                            l_api_shp_found := TRUE;
                            IF l_shp_work_done THEN
                                l_api_work_done := TRUE;
                            END IF;
                        END IF;

                    END LOOP;
                END IF;
            END IF;

        END LOOP;

    EXCEPTION
        WHEN OTHERS THEN NULL;
    END call_otm_api;

BEGIN
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    c_base_url := xxotm_get_cfg('OTM_BASE_URL')
                  || '/logisticsRestApi/resources-int/v2/shipments/';

    apex_json.initialize_clob_output;
    apex_json.open_object;

    BEGIN
        -- 1. Lock vehicle master — also fetch entry_time for API anchor check
        SELECT status, order_type, shipment_nbr, entry_time
          INTO l_status, l_order_type, l_shipment_nbr, l_entry_time
          FROM xxotm_vehicle_master_t
         WHERE truck_nbr = p_truck_id
           AND xxotm_vehicle_master_t.location  = v_location
           AND exit_time IS NULL
        FOR UPDATE NOWAIT;

        -- 2. Lock linked shipment rows
        IF l_shipment_nbr IS NOT NULL THEN
            FOR shp IN (
                SELECT shipment_xid FROM xxotm_shipments_t
                 WHERE shipment_xid IN (
                           REGEXP_SUBSTR(l_shipment_nbr, '[^,]+', 1, 1),
                           REGEXP_SUBSTR(l_shipment_nbr, '[^,]+', 1, 2),
                           'NAQLEEN.' || REGEXP_SUBSTR(l_shipment_nbr, '[^,]+', 1, 1),
                           'NAQLEEN.' || REGEXP_SUBSTR(l_shipment_nbr, '[^,]+', 1, 2)
                       )
                   AND xxotm_shipments_t.location = v_location
                FOR UPDATE NOWAIT
            ) LOOP NULL; END LOOP;
        ELSE
            FOR shp IN (
                SELECT shipment_xid FROM xxotm_shipments_t
                 WHERE truck_3pl = p_truck_id
                   AND xxotm_shipments_t.location = v_location
                FOR UPDATE NOWAIT
            ) LOOP NULL; END LOOP;
        END IF;

        -- 3. Count local shipments
        IF l_shipment_nbr IS NOT NULL THEN
            l_shp_count := 1;
        ELSE
            SELECT COUNT(*) INTO l_shp_count
              FROM xxotm_shipments_t
             WHERE truck_3pl = p_truck_id
               AND xxotm_shipments_t.location = v_location;
        END IF;

        -- 4. Nothing locally → call OTM API with entry_time anchor
        IF l_shp_count = 0 THEN
            call_otm_api;
        END IF;

        -- 5. Validation
        IF l_status IN ('vehicle_entry','VEHICLE_ENTRY','VEHICLE ENTRY',
                        'inspection','INSPECTION','gate_in') THEN
            l_can_delete := TRUE;
        ELSIF UPPER(REPLACE(l_status, 'NAQLEEN.', '')) LIKE '%GATE IN%'
          AND l_order_type IN ('LRO','CRO') THEN
            l_can_delete := TRUE;
        ELSIF l_shp_count = 0 AND NOT l_api_shp_found THEN
            l_can_delete := TRUE;   -- no shipment anywhere → orphaned
        ELSIF l_shp_count = 0 AND l_api_shp_found AND l_api_work_done THEN
            l_can_delete := FALSE;   -- API shipment anchored + ops complete
        ELSIF l_shp_count <>0 and l_api_shp_found = FALSE AND l_api_work_done = FALSE then
          l_can_delete := TRUE;
        END IF;

        -- 6. Execute
        IF l_can_delete THEN
            DELETE FROM xxotm_vehicle_master_t
             WHERE truck_nbr = p_truck_id
               AND xxotm_vehicle_master_t.location = v_location
               AND exit_time IS NULL;

            INSERT INTO xx_otm_sync_logs (PROCEDURE_NAME,MESSAGE_TYPE, REFERENCE_ID, MESSAGE_TEXT, LOG_TIMESTAMP)
            VALUES ('xxotm_delete_truck_p','DELETE_TRUCK', p_truck_id,
                    'Truck at location ' || v_location
                    || ' deleted by User ID: ' || p_user_id,
                    SYSTIMESTAMP);

            COMMIT;
            l_audit_code := 200;
            l_audit_msg  := 'Truck ' || p_truck_id || ' deleted';
            apex_json.write('response_code',    200);
            apex_json.write('response_message', 'Success: Truck ' || p_truck_id || ' has been deleted');
        ELSE
            l_audit_code := 400;
            l_audit_msg  := 'Status ' || l_status || ' does not allow deletion';
            apex_json.write('response_code',    400);
            apex_json.write('response_message',
                'Current vehicle status does not allow deletion');
        END IF;

    EXCEPTION
        WHEN resource_busy THEN
            l_audit_code := 409;
            l_audit_msg  := 'Locked by another user';
            apex_json.write('response_code',    409);
            apex_json.write('response_message', 'Conflict: Vehicle is being processed by another user');
        WHEN NO_DATA_FOUND THEN
            l_audit_code := 404;
            l_audit_msg  := 'Truck not found in yard at this location';
            apex_json.write('response_code',    404);
            apex_json.write('response_message', 'Truck not found');
    END;

    -- AUDIT. A deletion denied by status, or lost to a lock, is exactly the
    -- event worth having a record of -- so this logs all four outcomes, not
    -- just the successful delete.
    xxotm_log_activity(
        p_user_id        => p_user_id,
        p_module         => 'VEHICLE_INQUIRY',
        p_procedure_name => 'XXOTM_DELETE_TRUCK_P',
        p_action         => 'DELETE',
        p_entity_type    => 'TRUCK',
        p_entity_id      => p_truck_id,
        p_secondary_id   => l_shipment_nbr,
        p_response_code  => l_audit_code,
        p_message        => l_audit_msg,
        p_location       => v_location);

    apex_json.close_object;
    htp.prn(apex_json.get_clob_output);
    apex_json.free_output;

EXCEPTION
    WHEN OTHERS THEN
        xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'VEHICLE_INQUIRY',
            p_procedure_name => 'XXOTM_DELETE_TRUCK_P',
            p_action         => 'DELETE',
            p_entity_type    => 'TRUCK',
            p_entity_id      => p_truck_id,
            p_response_code  => 500,
            p_message        => SQLERRM,
            p_location       => v_location);

        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code',    500);
        apex_json.write('response_message', 'Failed to remove truck');
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        apex_json.free_output;
END xxotm_delete_truck_p;

   -- ========================================================================
   -- XXOTM_DELETE_USER_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_DELETE_USER_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_delete_user_p (
    p_email IN VARCHAR2
)
IS
    l_user_id        NUMBER;
    l_idcs_user_id   VARCHAR2(1000);
    l_access_token   VARCHAR2(32767);
    l_status_code    NUMBER;
    l_response_clob  CLOB;
    l_response       JSON_OBJECT_T := JSON_OBJECT_T();
    l_err_msg        VARCHAR2(4000);
	
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;

    IF p_email IS NULL THEN
        l_response.put('response_code', 400);
        l_response.put('response_message', 'Email is required');
        GOTO output_json;
    END IF;

    -- Check local db user
    BEGIN
        SELECT ID INTO l_user_id FROM XX_USER_CONFIG WHERE EMAIL = p_email;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        l_response.put('response_code', 404);
        l_response.put('response_message', 'User not found in local DB');
        GOTO output_json;
    END;

    -- Get token
    l_access_token := TRIM(BOTH '"' FROM xxotm_idcs_get_token);

    -- Get IDCS ID
    l_idcs_user_id := XXOTM_IDCS_GET_USER_ID(p_email, l_access_token);

    IF l_idcs_user_id IS NOT NULL THEN
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            apex_web_service.g_request_headers(2).name := 'Authorization';
            apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

            l_response_clob := apex_web_service.make_rest_request(
            p_url         => 'https://idcs-6cce7520f76c449188e5166f961e3cca.identity.oraclecloud.com/admin/v1/Users/' || l_idcs_user_id || '?forceDelete=true',
            p_http_method => 'DELETE',
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
        );
        l_status_code := apex_web_service.g_status_code;

        IF l_status_code NOT BETWEEN 200 AND 299 THEN
                l_response.put('response_code', l_status_code);
                l_response.put('response_message', 'Failed to delete from IDCS: ' || DBMS_LOB.SUBSTR(l_response_clob, 200));
                GOTO output_json;
        END IF;
    END IF;

    -- DB Delete
    DELETE FROM XX_USER_ROLE_ASSIGNMENT WHERE USER_ID = l_user_id;
    DELETE FROM XX_USER_CONFIG WHERE ID = l_user_id;
    COMMIT;

    l_response.put('response_code', 200);
    l_response.put('response_message', 'User deleted successfully');

<<output_json>>
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', l_response.get_number('response_code'));
    APEX_JSON.WRITE('response_message', l_response.get_string('response_message'));
    APEX_JSON.CLOSE_OBJECT;

    HTP.P(APEX_JSON.GET_CLOB_OUTPUT);
    APEX_JSON.FREE_OUTPUT;

EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    l_err_msg := SQLERRM;
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 500);
    APEX_JSON.WRITE('response_message', 'Internal Error: ' || l_err_msg);
    APEX_JSON.CLOSE_OBJECT;
    HTP.P(APEX_JSON.GET_CLOB_OUTPUT);
    APEX_JSON.FREE_OUTPUT;
END;

   -- ========================================================================
   -- XXOTM_GET_ALL_ROLES_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_GET_ALL_ROLES_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_all_roles_p
AS
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 200);
    APEX_JSON.WRITE('response_message', 'OK');

    APEX_JSON.OPEN_ARRAY('roles');
    FOR r IN (SELECT DISTINCT ROLE FROM XX_ROLE_CONFIG WHERE ROLE <> 'DEVELOPER' ORDER BY ROLE) LOOP
        APEX_JSON.WRITE(r.ROLE);
    END LOOP;

    APEX_JSON.CLOSE_ARRAY;
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
    WHEN OTHERS THEN
         APEX_JSON.INITIALIZE_CLOB_OUTPUT;
         APEX_JSON.OPEN_OBJECT;
         APEX_JSON.WRITE('response_code', 500);
         APEX_JSON.WRITE('response_message', SQLERRM);
         APEX_JSON.CLOSE_OBJECT;
         HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XXOTM_GET_ALL_ROLES_P;

   -- ========================================================================
   -- XXOTM_GET_ALL_USERS_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_GET_ALL_USERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_all_users_p
AS
   v_count NUMBER;
BEGIN
   APEX_JSON.INITIALIZE_CLOB_OUTPUT;
   APEX_JSON.OPEN_OBJECT;
   APEX_JSON.WRITE('response_code', 200);
   APEX_JSON.WRITE('response_message', 'OK');

   APEX_JSON.OPEN_ARRAY('users');

   FOR u IN (SELECT * FROM XX_USER_CONFIG ORDER BY NAME) LOOP
      APEX_JSON.OPEN_OBJECT;
      APEX_JSON.WRITE('USER_ID', u.ID);
      APEX_JSON.WRITE('NAME', u.NAME);
      APEX_JSON.WRITE('EMAIL', u.EMAIL);
      APEX_JSON.WRITE('IS_ACTIVE', u.IS_ACTIVE);
      IF u.LASTLOGINAT IS NOT NULL THEN
         APEX_JSON.WRITE('LASTLOGINAT', TO_CHAR(u.LASTLOGINAT, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
      END IF;

      -- Roles Array
      APEX_JSON.OPEN_ARRAY('ROLES');
      -- Add legacy role if valid and not in assignment? 
      -- For now, just use assignments + legacy as fallback if needed, but let's stick to assignments
      FOR r IN (
          SELECT ROLE_CODE 
          FROM XX_USER_ROLE_ASSIGNMENT 
          WHERE USER_ID = u.ID AND IS_ACTIVE = 'Y'
          UNION
          -- Optional: Include the legacy role column if not present in assignments? 
          -- Let's just include the legacy role column for now to be safe as migrated data
          SELECT u.ROLE FROM DUAL WHERE u.ROLE IS NOT NULL AND u.ROLE <> 'DEVELOPER'
      ) LOOP
         APEX_JSON.WRITE(r.ROLE_CODE);
      END LOOP;
      APEX_JSON.CLOSE_ARRAY;

      APEX_JSON.CLOSE_OBJECT;
   END LOOP;

   APEX_JSON.CLOSE_ARRAY;
   APEX_JSON.CLOSE_OBJECT;
   HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
   WHEN OTHERS THEN
      APEX_JSON.INITIALIZE_CLOB_OUTPUT;
      APEX_JSON.OPEN_OBJECT;
      APEX_JSON.WRITE('response_code', 500);
      APEX_JSON.WRITE('response_message', 'Error: ' || SQLERRM);
      APEX_JSON.CLOSE_OBJECT;
      HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XXOTM_GET_ALL_USERS_P;

   -- ========================================================================
   -- XXOTM_GET_AVAILABLE_RESERVED_P   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XXOTM_GET_AVAILABLE_RESERVED_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_available_reserved_p (
   p_cust_nbr   in varchar2,
   p_booking_id in varchar2,
   p_type       in varchar2,
   p_user_id in varchar2 default null
)
is
   -- API 3: Get Reserved AND Available Container Numbers for a Booking + Type
   -- Returns: { reserved: [...], available: [...] }
   -- Available = containers with booking_id IS NULL for this cust/type
   -- Author: Madhan
   -- Last Updated: 04-FEB-2026
   l_json_clob clob;
   v_first     boolean := true;
    v_location varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
   -- Start JSON response
   l_json_clob := '{
    "response_message": "Success",
    "response_code": 200,
    "booking_id": "'
                  || p_booking_id
                  || '",
    "container_type": "'
                  || p_type
                  || '",
    "reserved": [';

   -- Loop 1: Reserved containers (already assigned to this booking)
   v_first := true;
   for rec in (
      select container_nbr
        from xxotm_container_inventory_t
       where cust_nbr = p_cust_nbr
         and booking_id = p_booking_id
         and container_type = p_type
         and container_nbr is not null
         and position is not null
         and container_released_time is null 
         and xxotm_container_inventory_t.location = v_location
       order by container_nbr
   ) loop
      if not v_first then
         l_json_clob := l_json_clob || ',';
      end if;
      v_first := false;
      l_json_clob := l_json_clob
                     || '"'
                     || rec.container_nbr
                     || '"';
   end loop;

   l_json_clob := l_json_clob || '],
    "available": [';

   -- Loop 2: Available containers (not assigned to any booking)
   v_first := true;
   for rec in (
      select container_nbr
        from xxotm_container_inventory_t
       where container_type = p_type
         and cust_nbr = p_cust_nbr
         and booking_id is null
         and container_released_time is null
         and outbound_shipment_nbr is null
         and position is not null
         and container_stored_time is not null
         and inbound_shipment_nbr is not null
         and xxotm_container_inventory_t.location = v_location
       order by to_date(container_stored_time, 'YYYY-MM-DD"T"HH24:MI:SS"Z"') asc
   ) loop
      if not v_first then
         l_json_clob := l_json_clob || ',';
      end if;
      v_first := false;
      l_json_clob := l_json_clob
                     || '"'
                     || rec.container_nbr
                     || '"';
   end loop;

   l_json_clob := l_json_clob || ']}';
   htp.prn(l_json_clob);
exception
   when others then
      htp.prn('{"response_message":"Error: '
              || replace(
         sqlerrm,
         '"',
         '\"'
      ) || '","response_code":500,"reserved":[],"available":[]}');
end;

   -- ========================================================================
   -- XXOTM_GET_BOOKINGS_P   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XXOTM_GET_BOOKINGS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_bookings_p (
   p_cust_nbr    in varchar2,
   p_search_text in varchar2 default null,
   p_page        in number default 1,
   p_limit       in number default 20,
   p_user_id in varchar2 default null
)
is
   -- API 2: Get Bookings with Types (Paginated + Searchable)
   -- Author: Madhan
   -- Last Updated: 03-FEB-2026
   l_json_clob   clob;
   l_types_json  clob;
   v_first_book  boolean := true;
   v_first_type  boolean;
   v_offset      number := ( p_page - 1 ) * p_limit;
   v_total_count number := 0;
   v_search      varchar2(200) := '%'
                             || upper(nvl(
      p_search_text,
      ''
   )) || '%';
 v_location varchar2(100);
   -- Get distinct bookings with pagination
   cursor c_bookings is
   select distinct booking_id
        from xxotm_container_inventory_t
       where cust_nbr = p_cust_nbr
         and container_nbr is null
         and upper(order_type) like '%LRO%'
         and container_released_time is null
         and ( p_search_text is null
          or upper(booking_id) like v_search )  and xxotm_container_inventory_t.location = v_location
         order by booking_id
         offset v_offset rows fetch next p_limit rows only;

   -- Get types for a booking
   cursor c_types (
      p_book varchar2
   ) is
   select container_type,
          sum(
             case
                when container_nbr is null then
                   1
                else
                   0
             end
          ) as total,
          sum(
             case
                when container_nbr is not null
                   and position is not null then
                   1
                else
                   0
             end
          ) as reserved
     from xxotm_container_inventory_t
    where cust_nbr = p_cust_nbr
      and booking_id = p_book
      and container_type is not null
      and container_released_time is null  and xxotm_container_inventory_t.location = v_location
    group by container_type
    having sum(
      case
         when container_nbr is null then
            1
         else
            0
      end
   ) > 0
    order by container_type;

begin
 v_location := xx_get_user_location(p_user_id);
 -- Location is mandatory. xx_get_user_location returns NULL when
 -- req_location_id is absent, malformed, or not permitted for this user;
 -- it no longer falls back to a default site. Continuing on NULL would
 -- filter on "location = NULL" and return an empty result set -- an empty
 -- screen with no error, which is worse than a refusal.
 if v_location is null then
    xxotm_location_required;
    return;
 end if;
   -- Get total count for pagination
   select count(distinct booking_id)
     into v_total_count
     from xxotm_container_inventory_t
    where cust_nbr = p_cust_nbr
      and container_nbr is null
      and upper(order_type) like '%LRO%'
      and container_released_time is null
      and ( p_search_text is null
       or upper(booking_id) like v_search )  and xxotm_container_inventory_t.location = v_location;

   l_json_clob := '{
    "response_message": "Success",
    "response_code": 200,
    "total_count": '
                  || v_total_count
                  || ',
    "page": '
                  || p_page
                  || ',
    "limit": '
                  || p_limit
                  || ',
    "data": [';

   for book in c_bookings loop
      if not v_first_book then
         l_json_clob := l_json_clob || ',';
      end if;
      v_first_book := false;

      -- Build types array
      l_types_json := '[';
      v_first_type := true;
      for t in c_types(book.booking_id) loop
         if not v_first_type then
            l_types_json := l_types_json || ',';
         end if;
         v_first_type := false;
         l_types_json := l_types_json
                         || '{"type":"'
                         || t.container_type
                         || '","total":'
                         || t.total
                         || ',"reserved":'
                         || t.reserved
                         || ',"to_plan":'
                         || ( t.total - t.reserved )
                         || '}';
      end loop;

      l_types_json := l_types_json || ']';
      l_json_clob := l_json_clob
                     || '{"booking_id":"'
                     || book.booking_id
                     || '","types":'
                     || l_types_json
                     || '}';
   end loop;

   l_json_clob := l_json_clob || ']}';
   htp.prn(l_json_clob);
exception
   when others then
      htp.prn('{"response_message":"Error: '
              || replace(
         sqlerrm,
         '"',
         '\"'
      ) || '","response_code":500,"data":[],"total_count":0,"page":1,"limit":20}');
end;

   -- ========================================================================
   -- XXOTM_GET_CONTAINERS_OF_TYPE_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_GET_CONTAINERS_OF_TYPE_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_containers_of_type_p (p_container_type in varchar2, p_offset in number, p_search_text in varchar2,
   p_user_id in varchar2 default null)
as
   v_location varchar2(100);
   v_req_clob  clob;
   v_container varchar2(20);
   cursor c_containers (
      p_ctype varchar2
   ) is
   select container_nbr from (select container_nbr
     from xxotm_container_inventory_t
    where container_type = p_ctype
      and booking_id is null
      and container_released_time is null
      and outbound_shipment_nbr is null
      and position is not null
      and container_stored_time is not null
      and inbound_shipment_nbr is not null and xxotm_container_inventory_t.location = v_location
    order by 
            -- 1. Cluster by Block (Minimize Gantry Move)
     regexp_substr(
      position,
      '[^-]+',
      1,
      2
   ) asc,
        -- 2. Cluster by Lot (Bay)
        to_number(regexp_substr(
        position,
        '[^-]+',
        1,
        3
        )) asc,
            -- 3. Cluster by Row (Linear Movement)
             regexp_substr(
                position,
                '[^-]+',
                1,
                4
             ) desc,
                -- 4. Pick Topmost Container First (Safety/Accessibility)
                to_number(regexp_substr(
                    position,
                    '[^-]+',
                    1,
                    5
                )) desc offset p_offset rows) where container_nbr like '%'||upper(p_search_text)||'%' fetch first 20 rows only;

begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;

    select container_nbr into v_container from (select container_nbr, position
     from xxotm_container_inventory_t
    where container_type = p_container_type
      and booking_id is null
      and container_released_time is null
      and outbound_shipment_nbr is null
      and position is not null
      and container_stored_time is not null
      and inbound_shipment_nbr is not null and xxotm_container_inventory_t.location = v_location
      order by 
            -- 1. Cluster by Block (Minimize Gantry Move)
     regexp_substr(
      position,
      '[^-]+',
      1,
      2
   ) asc,
        -- 2. Cluster by Lot (Bay)
        to_number(regexp_substr(
        position,
        '[^-]+',
        1,
        3
        )) asc,
            -- 3. Cluster by Row (Linear Movement)
             regexp_substr(
                position,
                '[^-]+',
                1,
                4
             ) desc,
                -- 4. Pick Topmost Container First (Safety/Accessibility)
                to_number(regexp_substr(
                    position,
                    '[^-]+',
                    1,
                    5
                )) desc offset p_offset rows) where container_nbr like '%'||upper(p_search_text)||'%' fetch first 1 rows only;
   
    if v_container is null
    then
        raise no_data_found;
    end if;
   
   -- Initialize Output
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');
    for r in c_containers(p_container_type) loop
        exit when c_containers%notfound;
        apex_json.write(r.container_nbr);
    end loop;

   apex_json.close_array; -- data
   apex_json.close_object; -- root
   
   -- Flush Output
   htp.prn(apex_json.get_clob_output);
exception
   when no_data_found then
      apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write(
        'response_code',
        404
        );
        apex_json.write(
        'response_message',
        'NO DATA FOUND'
        );
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end;

   -- ========================================================================
   -- XXOTM_GET_CONTAINERS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_GET_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_containers_p (p_user_id in varchar2 default null)
AS
   v_location varchar2(100);
   l_data_clob  CLOB;
   l_final_clob CLOB;
BEGIN
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- Initialize Response
   DBMS_LOB.createtemporary(l_final_clob, TRUE);

   -- 1. Fetch Data grouped by cust_name (Option A structure)
   SELECT JSON_ARRAYAGG(
      JSON_OBJECT(
         'customer_name' VALUE cust_name,
         'containers' VALUE containers
         RETURNING CLOB
      )
      RETURNING CLOB
   )
   INTO l_data_clob
   FROM (
      SELECT 
         i.cust_name,
         JSON_ARRAYAGG(
            JSON_OBJECT(
               'container_nbr' VALUE i.container_nbr,
               'type' VALUE i.container_type,
               'status' VALUE CASE WHEN i.booking_id IS NOT NULL AND i.area <> 'CFS' THEN 'R' ELSE 'N' END,
               'position' VALUE CASE WHEN i.area IS NULL THEN i.position ELSE i.area END
            )
            RETURNING CLOB
         ) AS containers
      FROM (
         select cust_name, container_nbr, container_type, booking_id, position, shipment_name, null area, inbound_shipment_nbr, container_stored_time, container_released_time, outbound_shipment_nbr from xxotm_container_inventory_t where xxotm_container_inventory_t.location = v_location and container_nbr not in (select container_nbr from xxotm_cfs_containers_t where container_nbr is not null and release_date is null and xxotm_cfs_containers_t.location = v_location)
         union all
         select ci.cust_name, cf.container_nbr, ci.container_type, ci.booking_id, ci.position, ci.shipment_name, 'CFS' area, cf.shipment_nbr, cf.creation_date, cf.release_date, null outbound_shipment_nbr from xxotm_cfs_containers_t cf, xxotm_container_inventory_t ci where cf.shipment_nbr = ci.inbound_shipment_nbr and cf.location = v_location and ci.location = v_location 
      ) i
      WHERE i.container_nbr IS NOT NULL
        AND ((i.position IS NOT NULL AND i.position NOT IN ('NA','LEASED') AND i.container_stored_time IS NOT NULL) OR i.area = 'CFS')
        AND i.inbound_shipment_nbr IS NOT NULL
        AND i.container_released_time IS NULL
        -- AND i.cust_name IS NOT NULL
      GROUP BY i.cust_name
   );

   -- Handle Empty Result
   IF l_data_clob IS NULL THEN
      l_data_clob := '[]';
   END IF;

   -- 2. Build Standard Response Envelope
   l_final_clob := '{"response_code": 200, "response_message": "Success", "data": '
                   || l_data_clob
                   || '}';

   -- 3. Output Response (Chunked)
   DECLARE
      l_offset NUMBER := 1;
      l_amount NUMBER := 32000;
      l_len    NUMBER;
      l_buffer VARCHAR2(32767);
   BEGIN
      l_len := DBMS_LOB.getlength(l_final_clob);
      WHILE l_offset <= l_len LOOP
         DBMS_LOB.read(
            l_final_clob,
            l_amount,
            l_offset,
            l_buffer
         );
         HTP.prn(l_buffer);
         l_offset := l_offset + l_amount;
      END LOOP;
   END;

   -- Cleanup
   DBMS_LOB.freetemporary(l_final_clob);
EXCEPTION
   WHEN OTHERS THEN
      HTP.p('{"response_code": 400, "response_message": "Error involving XXOTM_GET_CONTAINERS_P: '
            || REPLACE(SQLERRM, '"', '\"')
            || '"}');
END;

   -- ========================================================================
   -- XXOTM_GET_CONTAINER_DETAILS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_GET_CONTAINER_DETAILS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_container_details_p (
    p_container_nbr IN VARCHAR2,
    p_user_id in varchar2 default null
)
AS
    v_location varchar2(100);
    v_container_nbr        VARCHAR2(50);
    v_cust_name            VARCHAR2(100);
    v_inbound_order_nbr    VARCHAR2(50);
    v_inbound_shipment_nbr VARCHAR2(50);
    v_container_type       VARCHAR2(100);
    v_booking_id           VARCHAR2(100);
    v_container_stored_time VARCHAR2(100);
    v_shipment_name        VARCHAR2(100);
    v_plug_in_status       VARCHAR2(20);
    
    -- Cursor for tracking events including Plugin/Out and Restack history
    CURSOR c_tracking_events IS
        SELECT event_type, event_date FROM (
            -- 1. Standard API Tracking Events (Excluding duplicates)
            SELECT (CASE WHEN te.event_type = 'VEHICLE ENTERED' THEN te.event_type || ' | ' || (select power_unit||truck_3pl from xxotm_shipments_t where shipment_xid = te.shipment_nbr and xxotm_shipments_t.location = v_location) ELSE te.event_type END) as event_type, te.event_date 
            FROM xxotm_tracking_events_t te, xxotm_container_inventory_t ci 
            WHERE
            --  te.container_nbr = ci.container_nbr 
            -- AND 
            te.shipment_nbr = ci.inbound_shipment_nbr 
            AND ci.position IS NOT NULL 
            AND ci.container_nbr = p_container_nbr
            AND te.event_type <> 'CONTAINER RESTACKED'

            UNION ALL

            -- 2. Plug In/Out History
            SELECT type || ' | ' || 'Actual : ' || current_temp || '°C  -  ' || 'Set Point : ' || set_point_temp || '°C' AS event_type, 
                   timestamp AS event_date 
            FROM XXOTM_PLUGINOUT_T 
            WHERE CONTAINER_NBR = p_container_nbr

            UNION ALL

            -- 3. Restack History - Using pipe delimiter for frontend parsing
            SELECT 'CONTAINER RESTACKED | ' || current_position || '  >  ' || restack_position AS event_type, 
                   updated_date AS event_date 
            FROM XXOTM_RESTACK_LOLO_T 
            WHERE CONTAINER_NBR = p_container_nbr
        )
        ORDER BY event_date;
BEGIN
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Fetch container details
    DECLARE
        v_is_cfs number := 0;
    BEGIN
        select COUNT(*) into v_is_cfs from xxotm_cfs_containers_t where container_nbr = p_container_nbr and xxotm_cfs_containers_t.location = v_location;
        IF v_is_cfs = 0
        THEN
            SELECT 
                CONTAINER_NBR,
                CUST_NAME,
                INBOUND_ORDER_NBR,
                INBOUND_SHIPMENT_NBR,
                CONTAINER_TYPE,
                BOOKING_ID,
                CONTAINER_STORED_TIME,
                SHIPMENT_NAME
            INTO
                v_container_nbr,
                v_cust_name,
                v_inbound_order_nbr,
                v_inbound_shipment_nbr,
                v_container_type,
                v_booking_id,
                v_container_stored_time,
                v_shipment_name
            FROM XXOTM_CONTAINER_INVENTORY_T
            WHERE CONTAINER_NBR = p_container_nbr
            AND container_stored_time is not null and container_released_time is null
            AND POSITION IS NOT NULL  and xxotm_container_inventory_t.location = v_location
            AND ROWNUM = 1;
        ELSE
            SELECT 
                cf.CONTAINER_NBR,
                ci.CUST_NAME,
                ci.INBOUND_ORDER_NBR,
                cf.SHIPMENT_NBR,
                ci.CONTAINER_TYPE,
                ci.BOOKING_ID,
                cf.CREATION_DATE,
                ci.SHIPMENT_NAME
            INTO
                v_container_nbr,
                v_cust_name,
                v_inbound_order_nbr,
                v_inbound_shipment_nbr,
                v_container_type,
                v_booking_id,
                v_container_stored_time,
                v_shipment_name
            FROM XXOTM_CFS_CONTAINERS_T cf, XXOTM_CONTAINER_INVENTORY_T ci
            WHERE cf.CONTAINER_NBR = p_container_nbr
            AND cf.shipment_nbr = ci.inbound_shipment_nbr AND cf.RELEASE_DATE is null  and ci.location = v_location;
        END IF;
    END;

    -- Determine plug-in status for reefer containers (type contains 'RT')
    v_plug_in_status := NULL;
    IF v_container_type IS NOT NULL AND INSTR(UPPER(v_container_type), 'RT') > 0 THEN
        BEGIN
            SELECT TYPE
            INTO v_plug_in_status
            FROM (
                SELECT TYPE
                FROM XXOTM_PLUGINOUT_T
                WHERE CONTAINER_NBR = p_container_nbr
                ORDER BY TIMESTAMP DESC
            )
            WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_plug_in_status := NULL;
        END;
    END IF;

    -- Build JSON response
    APEX_JSON.initialize_clob_output;
    APEX_JSON.open_object;
    APEX_JSON.write('response_code', 200);
    APEX_JSON.write('response_message', 'Success');
    
    APEX_JSON.open_object('data');
    APEX_JSON.write('container_number', v_container_nbr);
    APEX_JSON.write('customer_name', v_cust_name);
    APEX_JSON.write('inbound_order_nbr', v_inbound_order_nbr);
    APEX_JSON.write('inbound_shipment_nbr', v_inbound_shipment_nbr);
    APEX_JSON.write('container_type', v_container_type);
    APEX_JSON.write('booking_id', v_booking_id);
    APEX_JSON.write('container_stored_time', v_container_stored_time);
    APEX_JSON.write('shipment_name', v_shipment_name);
    APEX_JSON.write('plug_in_status', v_plug_in_status);
    
    -- Add tracking_events array
    APEX_JSON.open_array('tracking_events');
    FOR rec IN c_tracking_events LOOP
        APEX_JSON.open_object;
        APEX_JSON.write('event_type', rec.event_type);
        APEX_JSON.write('event_date', rec.event_date);
        APEX_JSON.close_object;
    END LOOP;
    APEX_JSON.close_array; -- tracking_events
    
    APEX_JSON.close_object; -- data
    
    APEX_JSON.close_object; -- root
    
    HTP.prn(APEX_JSON.get_clob_output);
    APEX_JSON.free_output;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        APEX_JSON.initialize_clob_output;
        APEX_JSON.open_object;
        APEX_JSON.write('response_code', 404);
        APEX_JSON.write('response_message', 'Container not found');
        APEX_JSON.write('data', '');
        APEX_JSON.close_object;
        HTP.prn(APEX_JSON.get_clob_output);
        APEX_JSON.free_output;
    WHEN OTHERS THEN
        APEX_JSON.initialize_clob_output;
        APEX_JSON.open_object;
        APEX_JSON.write('response_code', 500);
        APEX_JSON.write('response_message', SQLERRM);
        APEX_JSON.write('data', '');
        APEX_JSON.close_object;
        HTP.prn(APEX_JSON.get_clob_output);
        APEX_JSON.free_output;
END XXOTM_GET_CONTAINER_DETAILS_P;

   -- ========================================================================
   -- XXOTM_GET_CUSTOMERS_P   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XXOTM_GET_CUSTOMERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_customers_p (p_user_id in varchar2 default null)
is
   -- API 1: Get Customers with Booking Count
   -- Author: Madhan
   -- Last Updated: 03-FEB-2026
   l_json_clob clob;
   v_first     boolean := true;
    v_location varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
   l_json_clob := '{
    "response_message": "Success",
    "response_code": 200,
    "data": [';
   for rec in (
      select cust_name,
             cust_nbr,
             count(distinct booking_id) as booking_count
        from xxotm_container_inventory_t
       where cust_name is not null
         and container_nbr is null
         and upper(order_type) like '%LRO%'
         and container_released_time is null
         and xxotm_container_inventory_t.location = v_location
       group by cust_name,
                cust_nbr
       order by cust_name
   ) loop
      if not v_first then
         l_json_clob := l_json_clob || ',';
      end if;
      v_first := false;
      l_json_clob := l_json_clob
                     || '{"cust_name":"'
                     || rec.cust_name
                     || '","cust_nbr":"'
                     || rec.cust_nbr
                     || '","booking_count":'
                     || rec.booking_count
                     || '}';
   end loop;

   l_json_clob := l_json_clob || ']}';
   htp.prn(l_json_clob);
exception
   when others then
      htp.prn('{"response_message":"Error: '
              || replace(
         sqlerrm,
         '"',
         '\"'
      ) || '","response_code":500,"data":[]}');
end;

   -- ========================================================================
   -- XXOTM_GET_CUST_AND_BOOKINGS_P   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XXOTM_GET_CUST_AND_BOOKINGS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_cust_and_bookings_p (p_user_id in varchar2 default null)
is
   -- Last Updated Date : 17-DEC-2025
   -- Author : Madhan
   -- Modification: Added reserved_containers array to response
   l_json_clob clob;
    v_location varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Initialize JSON object
   l_json_clob := '{
    "response_message": "Success",
    "response_code": 200,
    "data": [';
   declare
      v_first_cust_output boolean := true;
      v_first_book_output boolean;
      v_first_type_output boolean;
      v_first_res_output  boolean;
      l_cust_buffer       clob;
      l_types_buffer      clob;
      l_res_buffer        clob;
      l_valid_types_count number;
      l_valid_books_count number;

      -- 1. Get Distinct Customers
      cursor c_cust is
      select distinct cust_name, cust_nbr
        from xxotm_container_inventory_t
       where cust_name is not null
         and container_nbr is null
         and upper(order_type) like '%LRO%'  and xxotm_container_inventory_t.location = v_location
       order by cust_name;

      -- 2. Get Bookings for a Customer
      cursor c_books (
         p_cust varchar2
      ) is
      select distinct booking_id
        from xxotm_container_inventory_t
       where cust_name = p_cust
         and container_nbr is null
         and upper(order_type) like '%LRO%'
         and container_released_time is null  and xxotm_container_inventory_t.location = v_location;

      -- 3. Get Container Types
      cursor c_types (
         p_cust varchar2,
         p_book varchar2
      ) is
      select container_type,
             count(*) as container_count
        from xxotm_container_inventory_t
       where cust_name = p_cust
         and booking_id = p_book
         and container_type is not null
         and container_nbr is null
         and container_released_time is null  and xxotm_container_inventory_t.location = v_location
       group by container_type;

      -- 4. Get Reserved Containers (New Cursor)
      cursor c_reserved (
         p_book varchar2,
         p_type varchar2
      ) is
      select distinct container_nbr
        from xxotm_container_inventory_t
       where booking_id = p_book
         and container_type = p_type
         and container_nbr is not null
         and position is not null
         and container_released_time is null  and xxotm_container_inventory_t.location = v_location;

   begin
      for cust in c_cust loop
         -- Reset Customer Buffer
         l_cust_buffer := '{ "cust_name": "'
                          || cust.cust_name
                          || '", "cust_nbr": "'
                          || cust.cust_nbr
                          || '", "bookings": [';
         l_valid_books_count := 0;
         v_first_book_output := true;
         for book in c_books(cust.cust_name) loop
             -- Reset Types Buffer
            l_types_buffer := null;
            l_valid_types_count := 0;
            v_first_type_output := true;
            for ctype in c_types(
               cust.cust_name,
               book.booking_id
            ) loop
               -- Build Reserved Containers Array
               l_res_buffer := '[';
               v_first_res_output := true;
               for res in c_reserved(
                  book.booking_id,
                  ctype.container_type
               ) loop
                  if not v_first_res_output then
                     l_res_buffer := l_res_buffer || ',';
                  end if;
                  v_first_res_output := false;
                  l_res_buffer := l_res_buffer || '"' || res.container_nbr || '"';
               end loop;
               l_res_buffer := l_res_buffer || ']';

               if not v_first_type_output then
                  l_types_buffer := l_types_buffer || ',';
               end if;
               v_first_type_output := false;
               l_types_buffer := l_types_buffer
                                 || '{ "container_type": "'
                                 || ctype.container_type
                                 || '", "container_count": '
                                 || ctype.container_count
                                 || ', "reserved_containers": ' 
                                 || l_res_buffer
                                 || '}';
               l_valid_types_count := l_valid_types_count + 1;
            end loop;

             -- Only add booking if we found container types
            if l_valid_types_count > 0 then
               if not v_first_book_output then
                  l_cust_buffer := l_cust_buffer || ',';
               end if;
               v_first_book_output := false;
               l_cust_buffer := l_cust_buffer
                                || '{ "booking_id": "'
                                || book.booking_id
                                || '", "container_types": ['
                                || l_types_buffer
                                || ']}';
               l_valid_books_count := l_valid_books_count + 1;
            end if;
         end loop;

         l_cust_buffer := l_cust_buffer || ']}';

         -- Only add customer if we found valid bookings
         if l_valid_books_count > 0 then
            if not v_first_cust_output then
               l_json_clob := l_json_clob || ',';
            end if;
            v_first_cust_output := false;
            l_json_clob := l_json_clob || l_cust_buffer;
         end if;
      end loop;
   end;

   l_json_clob := l_json_clob || ']}';

    -- Output JSON
   htp.prn(l_json_clob);
exception
   when others then
      htp.prn('{
            "response_message": "Error: '
              || replace(
         sqlerrm,
         '"',
         '\"'
      )
              || '",
            "response_code": 500,
            "data": []
        }');
end;

   -- ========================================================================
   -- XXOTM_GET_DASHBOARD_DRILLDOWN_P   [3b-prod-forward / TAKE-PROD]
   -- source: db/work/XXOTM_GET_DASHBOARD_DRILLDOWN_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_dashboard_drilldown_p (
   p_body in blob
)
is
    -- ===========================================================================
    -- Purpose:   Drill-down API for Trucks/Drivers Utilization
    --            Returns paginated row-level data for dashboard drill-downs
    -- Status Mapping:
    --   Dynamic mapping aligning with XXOTM_DASHBOARD_METRICS_P
    --   Input 'Committed' -> Filter 'TRUCK_COMMITTED'
    --   Output 'TRUCK_COMMITTED' -> 'Committed'
    -- ===========================================================================
    
    -- BLOB to CLOB conversion
   l_clob         clob;
   l_dest_offset  integer := 1;
   l_src_offset   integer := 1;
   l_lang_context integer := dbms_lob.default_lang_ctx;
   l_warning      integer;

    -- Request Payload
   jo_request     json_object_t;

    -- Input Parameters
   v_type         varchar2(20);   -- 'TRUCKS' or 'DRIVERS'
   v_status       varchar2(100);  -- 'ALL' or specific status e.g. 'Committed', 'Available'
   v_date         varchar2(20);   -- Single date (YYYY-MM-DD) or NULL
   v_start_date   varchar2(20);   -- Range start or NULL
   v_end_date     varchar2(20);   -- Range end or NULL
   v_page         number := 1;    -- Page number (1-based)
   v_page_size    number := 50;   -- Rows per page (default 50, max 100)

    -- Resolved Dates
   v_date_start   date;
   v_date_end     date;

    -- Mapped DB Status (for filtering)
   v_db_status    varchar2(100);

    -- Pagination
   v_total_rows   number := 0;
   v_total_pages  number := 0;
   v_offset       number := 0;

    -- Search Text
   v_search_text  varchar2(100);

    -- Response Building
   jo_response    json_object_t := json_object_t();
   jo_data        json_object_t := json_object_t();
   jo_pagination  json_object_t := json_object_t();
   jo_date_range  json_object_t := json_object_t();
   ja_rows        json_array_t := json_array_t();
   jo_row         json_object_t;

    -- Helper: Parse date string
   function parse_date (
      p_date_str in varchar2
   ) return date is
   begin
      if p_date_str is null then
         return null;
      end if;
      return to_date ( substr(
         p_date_str,
         1,
         10
      ),'YYYY-MM-DD' );
   exception
      when others then
         return null;
   end parse_date;

    -- Helper: Format status (trim prefix, capitalize first letter)
    -- Matches logic in XXOTM_DASHBOARD_METRICS_P
   function format_status (
      p_status in varchar2,
      p_prefix in varchar2
   ) return varchar2 is
      l_trimmed varchar2(100);
   begin
      -- Remove prefix if present
      if p_status like p_prefix || '%' then
         l_trimmed := substr(
            p_status,
            length(p_prefix) + 1
         );
      else
         l_trimmed := p_status;
      end if;
      -- Capitalize first letter, lowercase the rest, replace underscores with spaces
      return initcap(replace(
         lower(l_trimmed),
         '_',
         ' '
      ));
   end format_status;

begin
    -- =========================================================================
    -- 1. Convert BLOB to CLOB
    -- =========================================================================
   if p_body is not null then
      dbms_lob.createtemporary(
         l_clob,
         true
      );
      dbms_lob.converttoclob(
         dest_lob     => l_clob,
         src_blob     => p_body,
         amount       => dbms_lob.lobmaxsize,
         dest_offset  => l_dest_offset,
         src_offset   => l_src_offset,
         blob_csid    => nls_charset_id('AL32UTF8'),
         lang_context => l_lang_context,
         warning      => l_warning
      );
   else
      l_clob := '{}';
   end if;

    -- =========================================================================
    -- 2. Parse Request JSON
    -- =========================================================================
   begin
      jo_request := json_object_t.parse(l_clob);
   exception
      when others then
         jo_request := json_object_t();
   end;

    -- Extract parameters
   if jo_request.has('type') then
      v_type := upper(jo_request.get_string('type'));
   else
      v_type := 'TRUCKS';
   end if;

   if jo_request.has('status') then
      -- Keep case for display mapping (e.g. 'Committed' -> 'COMMITTED')
      v_status := jo_request.get_string('status');
   else
      v_status := 'ALL';
   end if;

   if jo_request.has('date') then
      v_date := jo_request.get_string('date');
   end if;

   if jo_request.has('startDate') then
      v_start_date := jo_request.get_string('startDate');
   end if;

   if jo_request.has('endDate') then
      v_end_date := jo_request.get_string('endDate');
   end if;

   if jo_request.has('page') then
      v_page := jo_request.get_number('page');
      if v_page < 1 then
         v_page := 1;
      end if;
   end if;

   if jo_request.has('pageSize') then
      v_page_size := jo_request.get_number('pageSize');
      if v_page_size < 1 then
         v_page_size := 50;
      end if;
      if v_page_size > 100 then
         v_page_size := 100;
      end if;
   end if;

    -- =========================================================================
    -- 3. Resolve Date Range
    -- =========================================================================
   if v_date is not null then
      v_date_start := parse_date(v_date);
      v_date_end := v_date_start;
   else
      v_date_start := parse_date(v_start_date);
      v_date_end := parse_date(v_end_date);
   end if;

   if v_date_start is null then
      v_date_start := trunc(sysdate);
   end if;
   if v_date_end is null then
      v_date_end := trunc(sysdate);
   end if;

    -- Calculate offset
   v_offset := ( v_page - 1 ) * v_page_size;

    -- =========================================================================
    -- 4. Map Display Status to DB Status
    -- =========================================================================
   if v_status is null
   or upper(v_status) = 'ALL' then
      v_db_status := null;
   else
      -- Reverse map: 'Committed' -> 'TRUCK_COMMITTED' or 'DRIVER_COMMITTED'
      -- Logic: Status -> Upper -> Replace space with _ -> Prepend Prefix
      if v_type = 'TRUCKS' then
         v_db_status := 'TRUCK_'
                        || replace(
            upper(v_status),
            ' ',
            '_'
         );
      elsif v_type = 'DRIVERS' then
         v_db_status := 'DRIVER_'
                        || replace(
            upper(v_status),
            ' ',
            '_'
         );
      end if;
   end if;

   if jo_request.has('searchText') then
      v_search_text := trim(jo_request.get_string('searchText'));
   end if;

    -- =========================================================================
    -- 5. Fetch Data Based on Type
    -- =========================================================================
   if v_type = 'TRUCKS' then
        -- Count total rows for pagination
      if v_db_status is null then
            -- ALL statuses
         select count(*)
           into v_total_rows
           from xxotm_vehicle_history_t
          where truck_daily_status is not null
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_date_start and v_date_end
            and ( v_search_text is null
             or length(v_search_text) < 3
             or ( upper(vehicle_xid) like '%'
                                          || upper(v_search_text)
                                          || '%'
         or upper(driver_xid) like '%'
                  || upper(v_search_text)
                  || '%'
         or upper(equipment) like '%'
                                  || upper(v_search_text)
                                  || '%' ) );
      else
            -- Specific status
         select count(*)
           into v_total_rows
           from xxotm_vehicle_history_t
          where truck_daily_status is not null
            and truck_daily_status = v_db_status
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_date_start and v_date_end
            and ( v_search_text is null
             or length(v_search_text) < 3
             or ( upper(vehicle_xid) like '%'
                                          || upper(v_search_text)
                                          || '%'
         or upper(driver_xid) like '%'
                  || upper(v_search_text)
                  || '%'
         or upper(equipment) like '%'
                                  || upper(v_search_text)
                                  || '%' ) );
      end if;

      v_total_pages := ceil(v_total_rows / v_page_size);

        -- Fetch paginated rows with dynamic status formatting
        -- Same query structure for both ALL and specific status to keep logic clean
        -- but distinct if/else for performance optimization of the filter
      if v_db_status is null then
         for rec in (
            select event_date,
                   vehicle_xid,
                   truck_daily_status,
                   driver_xid,
                   equipment
              from xxotm_vehicle_history_t
             where truck_daily_status is not null
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_date_start and v_date_end
               and ( v_search_text is null
                or length(v_search_text) < 3
                or ( upper(vehicle_xid) like '%'
                                             || upper(v_search_text)
                                             || '%'
            or upper(driver_xid) like '%'
                     || upper(v_search_text)
                     || '%'
            or upper(equipment) like '%'
                                     || upper(v_search_text)
                                     || '%' ) )
             order by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') desc,
                      vehicle_xid
            offset v_offset rows fetch next v_page_size rows only
         ) loop
            jo_row := json_object_t();
            jo_row.put(
               'eventDate',
               substr(
                  rec.event_date,
                  1,
                  10
               )
            );
            jo_row.put(
               'truckId',
               rec.vehicle_xid
            );
            -- Dynamic Status Formatting
            jo_row.put(
               'status',
               format_status(
                  rec.truck_daily_status,
                  'TRUCK_'
               )
            );
            jo_row.put(
               'driverId',
               rec.driver_xid
            );
            jo_row.put(
               'equipment',
               rec.equipment
            );
            ja_rows.append(jo_row);
         end loop;
      else
         for rec in (
            select event_date,
                   vehicle_xid,
                   truck_daily_status,
                   driver_xid,
                   equipment
              from xxotm_vehicle_history_t
             where truck_daily_status is not null
               and truck_daily_status = v_db_status
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_date_start and v_date_end
               and ( v_search_text is null
                or length(v_search_text) < 3
                or ( upper(vehicle_xid) like '%'
                                             || upper(v_search_text)
                                             || '%'
            or upper(driver_xid) like '%'
                     || upper(v_search_text)
                     || '%'
            or upper(equipment) like '%'
                                     || upper(v_search_text)
                                     || '%' ) )
             order by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') desc,
                      vehicle_xid
            offset v_offset rows fetch next v_page_size rows only
         ) loop
            jo_row := json_object_t();
            jo_row.put(
               'eventDate',
               substr(
                  rec.event_date,
                  1,
                  10
               )
            );
            jo_row.put(
               'truckId',
               rec.vehicle_xid
            );
            -- Dynamic Status Formatting
            jo_row.put(
               'status',
               format_status(
                  rec.truck_daily_status,
                  'TRUCK_'
               )
            );
            jo_row.put(
               'driverId',
               rec.driver_xid
            );
            jo_row.put(
               'equipment',
               rec.equipment
            );
            ja_rows.append(jo_row);
         end loop;
      end if;

   elsif v_type = 'DRIVERS' then
        -- Count total rows for pagination
      if v_db_status is null then
            -- ALL statuses
         select count(*)
           into v_total_rows
           from xxotm_driver_history_t
          where driver_daily_status is not null
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_date_start and v_date_end
            and ( v_search_text is null
             or length(v_search_text) < 3
             or ( upper(driver_xid) like '%'
                                         || upper(v_search_text)
                                         || '%'
         or upper(vehicle_xid) like '%'
                  || upper(v_search_text)
                  || '%'
         or upper(equipment) like '%'
                                  || upper(v_search_text)
                                  || '%' ) );
      else
            -- Specific status
         select count(*)
           into v_total_rows
           from xxotm_driver_history_t
          where driver_daily_status is not null
            and driver_daily_status = v_db_status
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_date_start and v_date_end
            and ( v_search_text is null
             or length(v_search_text) < 3
             or ( upper(driver_xid) like '%'
                                         || upper(v_search_text)
                                         || '%'
         or upper(vehicle_xid) like '%'
                  || upper(v_search_text)
                  || '%'
         or upper(equipment) like '%'
                                  || upper(v_search_text)
                                  || '%' ) );
      end if;

      v_total_pages := ceil(v_total_rows / v_page_size);

        -- Fetch paginated rows with dynamic status mapping
      if v_db_status is null then
         for rec in (
            select event_date,
                   driver_xid,
                   driver_daily_status,
                   vehicle_xid,
                   equipment
              from xxotm_driver_history_t
             where driver_daily_status is not null
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_date_start and v_date_end
               and ( v_search_text is null
                or length(v_search_text) < 3
                or ( upper(driver_xid) like '%'
                                            || upper(v_search_text)
                                            || '%'
            or upper(vehicle_xid) like '%'
                     || upper(v_search_text)
                     || '%'
            or upper(equipment) like '%'
                                     || upper(v_search_text)
                                     || '%' ) )
             order by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') desc,
                      driver_xid
            offset v_offset rows fetch next v_page_size rows only
         ) loop
            jo_row := json_object_t();
            jo_row.put(
               'eventDate',
               substr(
                  rec.event_date,
                  1,
                  10
               )
            );
            jo_row.put(
               'driverId',
               rec.driver_xid
            );
            -- Dynamic Status Formatting
            jo_row.put(
               'status',
               format_status(
                  rec.driver_daily_status,
                  'DRIVER_'
               )
            );
            jo_row.put(
               'truckId',
               rec.vehicle_xid
            );
            jo_row.put(
               'equipment',
               rec.equipment
            );
            ja_rows.append(jo_row);
         end loop;
      else
         for rec in (
            select event_date,
                   driver_xid,
                   driver_daily_status,
                   vehicle_xid,
                   equipment
              from xxotm_driver_history_t
             where driver_daily_status is not null
               and driver_daily_status = v_db_status
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_date_start and v_date_end
               and ( v_search_text is null
                or length(v_search_text) < 3
                or ( upper(driver_xid) like '%'
                                            || upper(v_search_text)
                                            || '%'
            or upper(vehicle_xid) like '%'
                     || upper(v_search_text)
                     || '%'
            or upper(equipment) like '%'
                                     || upper(v_search_text)
                                     || '%' ) )
             order by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') desc,
                      driver_xid
            offset v_offset rows fetch next v_page_size rows only
         ) loop
            jo_row := json_object_t();
            jo_row.put(
               'eventDate',
               substr(
                  rec.event_date,
                  1,
                  10
               )
            );
            jo_row.put(
               'driverId',
               rec.driver_xid
            );
            -- Dynamic Status Formatting
            jo_row.put(
               'status',
               format_status(
                  rec.driver_daily_status,
                  'DRIVER_'
               )
            );
            jo_row.put(
               'truckId',
               rec.vehicle_xid
            );
            jo_row.put(
               'equipment',
               rec.equipment
            );
            ja_rows.append(jo_row);
         end loop;
      end if;
   end if;

    -- =========================================================================
    -- 6. Build Response
    -- =========================================================================
    -- Date Range Object
   jo_date_range.put(
      'start',
      to_char(
         v_date_start,
         'YYYY-MM-DD'
      )
   );
   jo_date_range.put(
      'end',
      to_char(
         v_date_end,
         'YYYY-MM-DD'
      )
   );

    -- Pagination Object
   jo_pagination.put(
      'page',
      v_page
   );
   jo_pagination.put(
      'pageSize',
      v_page_size
   );
   jo_pagination.put(
      'totalRows',
      v_total_rows
   );
   jo_pagination.put(
      'totalPages',
      v_total_pages
   );

    -- Data Object
   jo_data.put(
      'type',
      v_type
   );
   jo_data.put(
      'status',
      v_status
   );
   jo_data.put(
      'dateRange',
      jo_date_range
   );
   jo_data.put(
      'pagination',
      jo_pagination
   );
   jo_data.put(
      'rows',
      ja_rows
   );

    -- Final Response
   jo_response.put(
      'response_code',
      200
   );
   jo_response.put(
      'response_message',
      'Success'
   );
   jo_response.put(
      'data',
      jo_data
   );

    -- =========================================================================
    -- 7. Output Response
    -- =========================================================================
   owa_util.mime_header(
      'application/json',
      false,
      'UTF-8'
   );
   owa_util.status_line(
      200,
      'OK'
   );
   owa_util.http_header_close;
   htp.p(jo_response.to_string);

    -- Cleanup
   if dbms_lob.istemporary(l_clob) = 1 then
      dbms_lob.freetemporary(l_clob);
   end if;

exception
   when others then
      jo_response := json_object_t();
      jo_response.put(
         'response_code',
         500
      );
      jo_response.put(
         'response_message',
         'Error: ' || sqlerrm
      );
      jo_response.put(
         'data',
         json_object_t()
      );
      owa_util.mime_header(
         'application/json',
         false,
         'UTF-8'
      );
      owa_util.status_line(
         500,
         'Internal Server Error'
      );
      owa_util.http_header_close;
      htp.p(jo_response.to_string);
end xxotm_get_dashboard_drilldown_p;

   -- ========================================================================
   -- xxotm_get_dashboard_metrics_p   [? / ?]
   -- source: db/work/XXOTM_GET_DASHBOARD_METRICS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_dashboard_metrics_p (
   p_body in blob
)
is
    -- ===========================================================================
    -- Procedure: XXOTM_GET_DASHBOARD_METRICS_P
    -- Purpose:   Dashboard metrics API with independent date controls
    --            Trends use viewMode only (DAILY/WEEKLY/MONTHLY) with fixed ranges
    -- ===========================================================================

    -- BLOB to CLOB conversion
   l_clob              clob;
   l_dest_offset       integer := 1;
   l_src_offset        integer := 1;
   l_lang_context      integer := dbms_lob.default_lang_ctx;
   l_warning           integer;

    -- Request Payload
   jo_request          json_object_t;
   jo_trucks           json_object_t;
   jo_drivers          json_object_t;
   jo_efficiency       json_object_t;
   jo_trucks_trend     json_object_t;
   jo_drivers_trend    json_object_t;

    -- Include Flags
   v_inc_trucks        boolean := false;
   v_inc_drivers       boolean := false;
   v_inc_efficiency    boolean := false;
   v_inc_trucks_trend  boolean := false;
   v_inc_drivers_trend boolean := false;

    -- Trucks/Drivers/Efficiency Date Ranges
   v_trucks_start      date;
   v_trucks_end        date;
   v_drivers_start     date;
   v_drivers_end       date;
   v_eff_start         date;
   v_eff_end           date;

    -- Trucks Trend: Mode only (fixed ranges)
   v_tt_mode           varchar2(20) := 'DAILY';
   v_tt_start          date;
   v_tt_end            date;

    -- Drivers Trend: Mode only (fixed ranges)
   v_dt_mode           varchar2(20) := 'DAILY';
   v_dt_start          date;
   v_dt_end            date;

    -- Truck Summary Counts
   v_truck_total       number := 0;

    -- Driver Summary Counts
   v_driver_total      number := 0;

    -- Efficiency Counts
   v_eff_truck_total   number := 0;
   v_eff_truck_active  number := 0;
   v_eff_driver_total  number := 0;
   v_eff_driver_active number := 0;
   v_truck_util_pct    number := 0;
   v_driver_util_pct   number := 0;
   v_overall_eff_pct   number := 0;

    -- Metadata: Min Dates
   v_vehicle_min_date  varchar2(10);
   v_driver_min_date   varchar2(10);

   -- Trend helper
   v_current_label     varchar2(100);

    -- Helper: Parse date string
   function parse_date (
      p_date_str in varchar2
   ) return date is
   begin
      if p_date_str is null then
         return null;
      end if;
      return to_date ( substr(
         p_date_str,
         1,
         10
      ),'YYYY-MM-DD' );
   exception
      when others then
         return null;
   end parse_date;

    -- Helper: Format status (trim prefix, capitalize first letter)
   function format_status (
      p_status in varchar2,
      p_prefix in varchar2
   ) return varchar2 is
      l_trimmed varchar2(100);
   begin
      -- Remove prefix if present
      if p_status like p_prefix || '%' then
         l_trimmed := substr(
            p_status,
            length(p_prefix) + 1
         );
      else
         l_trimmed := p_status;
      end if;
      -- Capitalize first letter, lowercase the rest, replace underscores with spaces
      return initcap(replace(
         lower(l_trimmed),
         '_',
         ' '
      ));
   end format_status;

    -- Helper: Resolve date range from date/startDate/endDate
   procedure resolve_dates (
      p_obj       in json_object_t,
      p_start_out out date,
      p_end_out   out date
   ) is
   begin
      if p_obj.has('date') then
         p_start_out := parse_date(p_obj.get_string('date'));
         p_end_out := p_start_out;
      else
         if p_obj.has('startDate') then
            p_start_out := parse_date(p_obj.get_string('startDate'));
         end if;
         if p_obj.has('endDate') then
            p_end_out := parse_date(p_obj.get_string('endDate'));
         end if;
      end if;
      if p_start_out is null then
         p_start_out := trunc(sysdate);
      end if;
      if p_end_out is null then
         p_end_out := trunc(sysdate);
      end if;
   end resolve_dates;

    -- Helper: Calculate date range from viewMode
    -- DAILY = last 7 days, WEEKLY = last 7 weeks, MONTHLY = last 12 months
   procedure resolve_trend_range (
      p_mode      in varchar2,
      p_start_out out date,
      p_end_out   out date
   ) is
   begin
      p_end_out := trunc(sysdate);
      case upper(p_mode)
         when 'DAILY' then
            p_start_out := p_end_out - 6;  -- Last 7 days including today
         when 'WEEKLY' then
            p_start_out := p_end_out - 48; -- Last 7 weeks (49 days)
         when 'MONTHLY' then
            p_start_out := add_months(
               p_end_out,
               -11
            ); -- Last 12 months
         else
            p_start_out := p_end_out - 6; -- Default to daily
      end case;
   end resolve_trend_range;

begin
    -- =========================================================================
    -- 1. Convert BLOB to CLOB
    -- =========================================================================
   if p_body is not null then
      dbms_lob.createtemporary(
         l_clob,
         true
      );
      dbms_lob.converttoclob(
         dest_lob     => l_clob,
         src_blob     => p_body,
         amount       => dbms_lob.lobmaxsize,
         dest_offset  => l_dest_offset,
         src_offset   => l_src_offset,
         blob_csid    => dbms_lob.default_csid,
         lang_context => l_lang_context,
         warning      => l_warning
      );
   else
      l_clob := empty_clob();
   end if;

    -- =========================================================================
    -- 2. Parse Request Payload
    -- =========================================================================
   begin
      jo_request := json_object_t.parse(l_clob);

        -- Parse Trucks Section
      if jo_request.has('trucks') then
         jo_trucks := jo_request.get_object('trucks');
         if jo_trucks.has('include') then
            v_inc_trucks := jo_trucks.get_boolean('include');
         end if;
         if v_inc_trucks then
            resolve_dates(
               jo_trucks,
               v_trucks_start,
               v_trucks_end
            );
         end if;
      end if;

        -- Parse Drivers Section
      if jo_request.has('drivers') then
         jo_drivers := jo_request.get_object('drivers');
         if jo_drivers.has('include') then
            v_inc_drivers := jo_drivers.get_boolean('include');
         end if;
         if v_inc_drivers then
            resolve_dates(
               jo_drivers,
               v_drivers_start,
               v_drivers_end
            );
         end if;
      end if;

        -- Parse Efficiency Section
      if jo_request.has('efficiency') then
         jo_efficiency := jo_request.get_object('efficiency');
         if jo_efficiency.has('include') then
            v_inc_efficiency := jo_efficiency.get_boolean('include');
         end if;
         if v_inc_efficiency then
            resolve_dates(
               jo_efficiency,
               v_eff_start,
               v_eff_end
            );
         end if;
      end if;

        -- Parse Trucks Trend Section (uses viewMode only)
      if jo_request.has('trucksTrend') then
         jo_trucks_trend := jo_request.get_object('trucksTrend');
         if jo_trucks_trend.has('include') then
            v_inc_trucks_trend := jo_trucks_trend.get_boolean('include');
         end if;
         if v_inc_trucks_trend then
            if jo_trucks_trend.has('viewMode') then
               v_tt_mode := upper(jo_trucks_trend.get_string('viewMode'));
            end if;
            resolve_trend_range(
               v_tt_mode,
               v_tt_start,
               v_tt_end
            );
         end if;
      end if;

        -- Parse Drivers Trend Section (uses viewMode only)
      if jo_request.has('driversTrend') then
         jo_drivers_trend := jo_request.get_object('driversTrend');
         if jo_drivers_trend.has('include') then
            v_inc_drivers_trend := jo_drivers_trend.get_boolean('include');
         end if;
         if v_inc_drivers_trend then
            if jo_drivers_trend.has('viewMode') then
               v_dt_mode := upper(jo_drivers_trend.get_string('viewMode'));
            end if;
            resolve_trend_range(
               v_dt_mode,
               v_dt_start,
               v_dt_end
            );
         end if;
      end if;

   exception
      when others then
         apex_json.initialize_clob_output;
         apex_json.open_object;
         apex_json.write(
            'response_code',
            400
         );
         apex_json.write(
            'response_message',
            'Invalid JSON payload: ' || sqlerrm
         );
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
   end;

    -- =========================================================================
    -- 3. Initialize APEX_JSON Output
    -- =========================================================================
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_object('data');

    -- =========================================================================
    -- 4. Trucks Summary (Daily Average for Date Ranges)
    -- =========================================================================
   if v_inc_trucks then
      -- Get distinct truck count
      select count(distinct vehicle_xid)
        into v_truck_total
        from xxotm_vehicle_history_t
       where truck_daily_status is not null
         and to_date(substr(
         event_date,
         1,
         10
      ),
        'YYYY-MM-DD') between v_trucks_start and v_trucks_end;

      apex_json.open_object('trucks');
      apex_json.write(
         'total',
         nvl(
            v_truck_total,
            0
         )
      );
      apex_json.open_array('statuses');

      -- Loop through statuses and get average daily counts
      for rec in (
         with daily_counts as (
            select truck_daily_status,
                   count(*) as status_count
              from xxotm_vehicle_history_t
             where truck_daily_status is not null
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_trucks_start and v_trucks_end
             group by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD'),
                      truck_daily_status
         )
         select truck_daily_status,
                round(avg(status_count)) as avg_count
           from daily_counts
          group by truck_daily_status
          order by truck_daily_status
      ) loop
         apex_json.open_object;
         apex_json.write(
            'status',
            format_status(
               rec.truck_daily_status,
               'TRUCK_'
            )
         );
         apex_json.write(
            'count',
            nvl(
               rec.avg_count,
               0
            )
         );
         apex_json.close_object;
      end loop;

      apex_json.close_array; -- statuses
      apex_json.open_object('dateRange');
      apex_json.write(
         'start',
         to_char(
            v_trucks_start,
            'YYYY-MM-DD'
         )
      );
      apex_json.write(
         'end',
         to_char(
            v_trucks_end,
            'YYYY-MM-DD'
         )
      );
      apex_json.close_object;
      apex_json.close_object;
   end if;

    -- =========================================================================
    -- 5. Drivers Summary (Daily Average for Date Ranges)
    -- =========================================================================
   if v_inc_drivers then
      -- Get distinct driver count
      select count(distinct driver_xid)
        into v_driver_total
        from xxotm_driver_history_t
       where driver_daily_status is not null
         and to_date(substr(
         event_date,
         1,
         10
      ),
        'YYYY-MM-DD') between v_drivers_start and v_drivers_end+1;

      apex_json.open_object('drivers');
      apex_json.write(
         'total',
         nvl(
            v_driver_total,
            0
         )
      );
      apex_json.open_array('statuses');

      -- Loop through statuses and get average daily counts
      for rec in (
         with daily_counts as (
            select driver_daily_status,
                   count(*) as status_count
              from xxotm_driver_history_t
             where driver_daily_status is not null
               and to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD') between v_drivers_start and v_drivers_end+1
             group by to_date(substr(
               event_date,
               1,
               10
            ),
        'YYYY-MM-DD'),
                      driver_daily_status
         )
         select driver_daily_status,
                round(avg(status_count)) as avg_count
           from daily_counts
          group by driver_daily_status
          order by driver_daily_status
      ) loop
         apex_json.open_object;
         apex_json.write(
            'status',
            format_status(
               rec.driver_daily_status,
               'DRIVER_'
            )
         );
         apex_json.write(
            'count',
            nvl(
               rec.avg_count,
               0
            )
         );
         apex_json.close_object;
      end loop;

      apex_json.close_array; -- statuses
      apex_json.open_object('dateRange');
      apex_json.write(
         'start',
         to_char(
            v_drivers_start,
            'YYYY-MM-DD'
         )
      );
      apex_json.write(
         'end',
         to_char(
            v_drivers_end,
            'YYYY-MM-DD'
         )
      );
      apex_json.close_object;
      apex_json.close_object;
   end if;

    -- =========================================================================
    -- 6. Efficiency (Daily Average for Date Ranges)
    -- =========================================================================
   if v_inc_efficiency then
      -- Step 1: Get distinct truck count
      select count(distinct vehicle_xid)
        into v_eff_truck_total
        from xxotm_vehicle_history_t
       where truck_daily_status is not null
         and to_date(substr(
         event_date,
         1,
         10
      ),
        'YYYY-MM-DD') between v_eff_start and v_eff_end;

      -- Step 2: Get average committed trucks per day
      select round(nvl(
         avg(committed),
         0
      ))
        into v_eff_truck_active
        from (
         select to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') as event_day,
                sum(
                   case
                      when truck_daily_status = 'TRUCK_COMMITTED' then
                         1
                      else
                         0
                   end
                ) as committed
           from xxotm_vehicle_history_t
          where truck_daily_status is not null
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_eff_start and v_eff_end
          group by to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD')
      );

      -- Step 3: Get distinct driver count
      select count(distinct driver_xid)
        into v_eff_driver_total
        from xxotm_driver_history_t
       where driver_daily_status is not null
         and to_date(substr(
         event_date,
         1,
         10
      ),
        'YYYY-MM-DD') between v_eff_start and v_eff_end;

      -- Step 4: Get average committed drivers per day
      select round(nvl(
         avg(committed),
         0
      ))
        into v_eff_driver_active
        from (
         select to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') as event_day,
                sum(
                   case
                      when driver_daily_status = 'DRIVER_COMMITTED' then
                         1
                      else
                         0
                   end
                ) as committed
           from xxotm_driver_history_t
          where driver_daily_status is not null
            and to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD') between v_eff_start and v_eff_end
          group by to_date(substr(
            event_date,
            1,
            10
         ),
        'YYYY-MM-DD')
      );

      -- Calculate utilization percentages
      if nvl(
         v_eff_truck_total,
         0
      ) > 0 then
         v_truck_util_pct := round(
            (nvl(
               v_eff_truck_active,
               0
            ) / v_eff_truck_total) * 100,
            2
         );
      end if;
      if nvl(
         v_eff_driver_total,
         0
      ) > 0 then
         v_driver_util_pct := round(
            (nvl(
               v_eff_driver_active,
               0
            ) / v_eff_driver_total) * 100,
            2
         );
      end if;
      if
         nvl(
            v_eff_truck_total,
            0
         ) > 0
         and nvl(
            v_eff_driver_total,
            0
         ) > 0
      then
         v_overall_eff_pct := round(
            (v_truck_util_pct + v_driver_util_pct) / 2,
            2
         );
      elsif nvl(
         v_eff_truck_total,
         0
      ) > 0 then
         v_overall_eff_pct := v_truck_util_pct;
      elsif nvl(
         v_eff_driver_total,
         0
      ) > 0 then
         v_overall_eff_pct := v_driver_util_pct;
      end if;

      apex_json.open_object('efficiency');
      apex_json.write(
         'truckUtilization',
         v_truck_util_pct
      );
      apex_json.write(
         'driverUtilization',
         v_driver_util_pct
      );
      apex_json.write(
         'overall',
         v_overall_eff_pct
      );
      apex_json.open_object('dateRange');
      apex_json.write(
         'start',
         to_char(
            v_eff_start,
            'YYYY-MM-DD'
         )
      );
      apex_json.write(
         'end',
         to_char(
            v_eff_end,
            'YYYY-MM-DD'
         )
      );
      apex_json.close_object;
      apex_json.close_object;
   end if;

    -- =========================================================================
    -- 7. Trucks Trend (with unique counts + averages for WEEKLY/MONTHLY)
    -- =========================================================================
   if v_inc_trucks_trend then
      apex_json.open_object('trucksTrend');
      apex_json.write(
         'viewMode',
         v_tt_mode
      );
      apex_json.open_array('data');
      if v_tt_mode = 'DAILY' then
         -- DAILY MODE: Keep original simple logic
         v_current_label := '___INIT___';
         for rec in (
            with trend_data as (
               select to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') as event_day,
                      truck_daily_status
                 from xxotm_vehicle_history_t
                where truck_daily_status is not null
                  and to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') between v_tt_start and v_tt_end
            )
            select to_char(
               event_day,
               'Mon DD'
            ) as label,
                   event_day as sort_date,
                   null as total,
                   truck_daily_status,
                   count(*) as status_count
              from trend_data
             group by to_char(
               event_day,
               'Mon DD'
            ),
                      event_day,
                      truck_daily_status
             order by sort_date,
                      label,
                      truck_daily_status
         ) loop
            if rec.label <> v_current_label then
               if v_current_label <> '___INIT___' then
                  apex_json.close_array; -- statuses
                  apex_json.close_object;
               end if;
               v_current_label := rec.label;
               apex_json.open_object;
               apex_json.write(
                  'label',
                  rec.label
               );
               apex_json.open_array('statuses');
            end if;

            apex_json.open_object;
            apex_json.write(
               'status',
               format_status(
                  rec.truck_daily_status,
                  'TRUCK_'
               )
            );
            apex_json.write(
               'count',
               rec.status_count
            );
            apex_json.close_object;
         end loop;

         if v_current_label <> '___INIT___' then
            apex_json.close_array; -- statuses
            apex_json.close_object;
         end if;
      else
         -- WEEKLY/MONTHLY MODE: Use unique counts + averages
         v_current_label := '___INIT___';
         for rec in (
            with raw_data as (
               select vehicle_xid,
                      to_date(substr(
                         event_date,
                         1,
                         10
                      ),
                              'YYYY-MM-DD') as event_day,
                      truck_daily_status,
                      case v_tt_mode
                         when 'WEEKLY'  then
                            to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                    'YYYY-MM-DD'),
                               'Mon'
                            )
                            || ' W'
                            || to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                     'YYYY-MM-DD'),
                               'W'
                            )
                         when 'MONTHLY' then
                            to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                    'YYYY-MM-DD'),
                               'Mon'
                            )
                      end as period_label,
                      case v_tt_mode
                         when 'WEEKLY'  then
                            trunc(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                  'YYYY-MM-DD'),
                               'MM'
                            ) + ( to_number(to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                     'YYYY-MM-DD'),
                               'W'
                            )) - 1 ) * 7
                         when 'MONTHLY' then
                            trunc(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                  'YYYY-MM-DD'),
                               'MM'
                            )
                      end as period_sort
                 from xxotm_vehicle_history_t
                where truck_daily_status is not null
                  and to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') between v_tt_start and v_tt_end
            ),
            -- Daily counts per status per day within each period
            daily_status_counts as (
               select period_label,
                      period_sort,
                      event_day,
                      truck_daily_status,
                      count(*) as daily_count
                 from raw_data
                group by period_label,
                         period_sort,
                         event_day,
                         truck_daily_status
            ),
            -- Unique trucks per period
            period_totals as (
               select period_label,
                      period_sort,
                      count(distinct vehicle_xid) as total_trucks
                 from raw_data
                group by period_label,
                         period_sort
            ),
            -- Average daily count per status per period
            period_averages as (
               select period_label,
                      period_sort,
                      truck_daily_status,
                      round(avg(daily_count)) as avg_count
                 from daily_status_counts
                group by period_label,
                         period_sort,
                         truck_daily_status
            )
            select pt.period_label as label,
                   pt.period_sort as sort_date,
                   pt.total_trucks as total,
                   pa.truck_daily_status,
                   pa.avg_count as status_count
              from period_totals pt
              join period_averages pa
            on pt.period_label = pa.period_label
               and pt.period_sort = pa.period_sort
             order by pt.period_sort,
                      pa.truck_daily_status
         ) loop
            if rec.label <> v_current_label then
               if v_current_label <> '___INIT___' then
                  apex_json.close_array; -- statuses
                  apex_json.close_object;
               end if;
               v_current_label := rec.label;
               apex_json.open_object;
               apex_json.write(
                  'label',
                  rec.label
               );
               apex_json.write(
                  'total',
                  rec.total
               );
               apex_json.open_array('statuses');
            end if;

            apex_json.open_object;
            apex_json.write(
               'status',
               format_status(
                  rec.truck_daily_status,
                  'TRUCK_'
               )
            );
            apex_json.write(
               'count',
               rec.status_count
            );
            apex_json.close_object;
         end loop;

         if v_current_label <> '___INIT___' then
            apex_json.close_array; -- statuses
            apex_json.close_object;
         end if;
      end if;

      apex_json.close_array; -- data
      apex_json.close_object; -- trucksTrend
   end if;

    -- =========================================================================
    -- 8. Drivers Trend (with unique counts + averages for WEEKLY/MONTHLY)
    -- =========================================================================
   if v_inc_drivers_trend then
      apex_json.open_object('driversTrend');
      apex_json.write(
         'viewMode',
         v_dt_mode
      );
      apex_json.open_array('data');
      if v_dt_mode = 'DAILY' then
         -- DAILY MODE: Keep original simple logic
         v_current_label := '___INIT___';
         for rec in (
            with trend_data as (
               select to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') as event_day,
                      driver_daily_status
                 from xxotm_driver_history_t
                where driver_daily_status is not null
                  and to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') between v_dt_start and v_dt_end
            )
            select to_char(
               event_day,
               'Mon DD'
            ) as label,
                   event_day as sort_date,
                   null as total,
                   driver_daily_status,
                   count(*) as status_count
              from trend_data
             group by to_char(
               event_day,
               'Mon DD'
            ),
                      event_day,
                      driver_daily_status
             order by sort_date,
                      label,
                      driver_daily_status
         ) loop
            if rec.label <> v_current_label then
               if v_current_label <> '___INIT___' then
                  apex_json.close_array; -- statuses
                  apex_json.close_object;
               end if;
               v_current_label := rec.label;
               apex_json.open_object;
               apex_json.write(
                  'label',
                  rec.label
               );
               apex_json.open_array('statuses');
            end if;

            apex_json.open_object;
            apex_json.write(
               'status',
               format_status(
                  rec.driver_daily_status,
                  'DRIVER_'
               )
            );
            apex_json.write(
               'count',
               rec.status_count
            );
            apex_json.close_object;
         end loop;

         if v_current_label <> '___INIT___' then
            apex_json.close_array; -- statuses
            apex_json.close_object;
         end if;
      else
         -- WEEKLY/MONTHLY MODE: Use unique counts + averages
         v_current_label := '___INIT___';
         for rec in (
            with raw_data as (
               select driver_xid,
                      to_date(substr(
                         event_date,
                         1,
                         10
                      ),
                              'YYYY-MM-DD') as event_day,
                      driver_daily_status,
                      case v_dt_mode
                         when 'WEEKLY'  then
                            to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                    'YYYY-MM-DD'),
                               'Mon'
                            )
                            || ' W'
                            || to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                     'YYYY-MM-DD'),
                               'W'
                            )
                         when 'MONTHLY' then
                            to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                    'YYYY-MM-DD'),
                               'Mon'
                            )
                      end as period_label,
                      case v_dt_mode
                         when 'WEEKLY'  then
                            trunc(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                  'YYYY-MM-DD'),
                               'MM'
                            ) + ( to_number(to_char(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                     'YYYY-MM-DD'),
                               'W'
                            )) - 1 ) * 7
                         when 'MONTHLY' then
                            trunc(
                               to_date(substr(
                                  event_date,
                                  1,
                                  10
                               ),
                                  'YYYY-MM-DD'),
                               'MM'
                            )
                      end as period_sort
                 from xxotm_driver_history_t
                where driver_daily_status is not null
                  and to_date(substr(
                  event_date,
                  1,
                  10
               ),
        'YYYY-MM-DD') between v_dt_start and v_dt_end
            ),
            -- Daily counts per status per day within each period
            daily_status_counts as (
               select period_label,
                      period_sort,
                      event_day,
                      driver_daily_status,
                      count(*) as daily_count
                 from raw_data
                group by period_label,
                         period_sort,
                         event_day,
                         driver_daily_status
            ),
            -- Unique drivers per period
            period_totals as (
               select period_label,
                      period_sort,
                      count(distinct driver_xid) as total_drivers
                 from raw_data
                group by period_label,
                         period_sort
            ),
            -- Average daily count per status per period
            period_averages as (
               select period_label,
                      period_sort,
                      driver_daily_status,
                      round(avg(daily_count)) as avg_count
                 from daily_status_counts
                group by period_label,
                         period_sort,
                         driver_daily_status
            )
            select pt.period_label as label,
                   pt.period_sort as sort_date,
                   pt.total_drivers as total,
                   pa.driver_daily_status,
                   pa.avg_count as status_count
              from period_totals pt
              join period_averages pa
            on pt.period_label = pa.period_label
               and pt.period_sort = pa.period_sort
             order by pt.period_sort,
                      pa.driver_daily_status
         ) loop
            if rec.label <> v_current_label then
               if v_current_label <> '___INIT___' then
                  apex_json.close_array; -- statuses
                  apex_json.close_object;
               end if;
               v_current_label := rec.label;
               apex_json.open_object;
               apex_json.write(
                  'label',
                  rec.label
               );
               apex_json.write(
                  'total',
                  rec.total
               );
               apex_json.open_array('statuses');
            end if;

            apex_json.open_object;
            apex_json.write(
               'status',
               format_status(
                  rec.driver_daily_status,
                  'DRIVER_'
               )
            );
            apex_json.write(
               'count',
               rec.status_count
            );
            apex_json.close_object;
         end loop;

         if v_current_label <> '___INIT___' then
            apex_json.close_array; -- statuses
            apex_json.close_object;
         end if;
      end if;

      apex_json.close_array; -- data
      apex_json.close_object; -- driversTrend
   end if;

    -- =========================================================================
    -- 9. Metadata (Min Dates for Date Picker Restrictions)
    -- =========================================================================
   apex_json.open_object('metadata');
   -- Vehicle min date
   begin
      select to_char(
         min(to_date(substr(
            event_date,
            1,
            10
         ),
             'YYYY-MM-DD')),
         'YYYY-MM-DD'
      )
        into v_vehicle_min_date
        from xxotm_vehicle_history_t
       where truck_daily_status is not null;
   exception
      when no_data_found then
         v_vehicle_min_date := null;
   end;
   apex_json.write(
      'vehicleMinDate',
      v_vehicle_min_date
   );

   -- Driver min date
   begin
      select to_char(
         min(to_date(substr(
            event_date,
            1,
            10
         ),
             'YYYY-MM-DD')),
         'YYYY-MM-DD'
      )
        into v_driver_min_date
        from xxotm_driver_history_t
       where driver_daily_status is not null;
   exception
      when no_data_found then
         v_driver_min_date := null;
   end;
   apex_json.write(
      'driverMinDate',
      v_driver_min_date
   );
   apex_json.close_object;

    -- =========================================================================
    -- 10. Close JSON
    -- =========================================================================
   apex_json.close_object; -- data
   apex_json.close_object; -- root
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
   if l_clob is not null then
      dbms_lob.freetemporary(l_clob);
   end if;
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Internal error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xxotm_get_dashboard_metrics_p;

   -- ========================================================================
   -- XXOTM_GET_INVALID_CONTAINERS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_GET_INVALID_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_invalid_containers_p (
   p_search_text in varchar2 default null,
   p_offset      in varchar2 default '0',
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   l_offset      number := 0;
   l_total_count number := 0;
   l_page_size   number := 50;
   l_data_found  boolean := false;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Safe offset conversion
   begin
      l_offset := to_number(nvl(p_offset, '0'));
   exception
      when others then
         l_offset := 0;
   end;

   l_offset := nvl(l_offset, 0);

   apex_json.initialize_clob_output;
   apex_json.open_object;

   /* ----------------------------
      TOTAL COUNT (WITH SEARCH)
      ---------------------------- */
   select count(*)
     into l_total_count
     from xxotm_container_inventory_t i
    where i.container_nbr is not null
      and i.container_stored_time is not null
      and i.container_released_time is null
      and i.position = 'NA'
      and i.location = v_location
      and (
            p_search_text is null
         or upper(i.container_nbr) like '%' || upper(p_search_text) || '%'
      );

   -- Response header
   apex_json.write('response_code', 200);
   apex_json.write('response_message', 'Success');
   apex_json.write('total_count', l_total_count);
   apex_json.write('offset', l_offset);
   apex_json.write('limit', l_page_size);

   apex_json.open_array('data');

   /* ----------------------------
      DATA QUERY (WITH SEARCH + PAGINATION)
      ---------------------------- */
   for r_container in (
      select *
        from (
         select i.container_nbr,
                i.container_type,
                i.inbound_shipment_nbr,
                i.container_stored_time,
                i.cust_name,
                row_number() over (
                   order by i.container_stored_time asc
                ) as row_idx
           from xxotm_container_inventory_t i
          where i.container_nbr is not null
            and i.container_stored_time is not null
            and i.container_released_time is null
            and i.position = 'NA'
            and i.location = v_location
            and (
                  p_search_text is null
               or upper(i.container_nbr) like '%' || upper(p_search_text) || '%'
            )
      )
       where row_idx > l_offset
         and row_idx <= (l_offset + l_page_size)
   ) loop
      l_data_found := true;

      apex_json.open_object;
      apex_json.write('container_nbr', r_container.container_nbr);
      apex_json.write('container_type', r_container.container_type);
      apex_json.write('shipment_nbr', r_container.inbound_shipment_nbr);
      apex_json.write('customer_name', r_container.cust_name);
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.close_object;

   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
      begin
         apex_json.free_output;
      exception
         when others then null;
      end;

      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm || ' - ' || dbms_utility.format_error_backtrace
      );
      apex_json.write('total_count', 0);
      apex_json.write('offset', 0);
      apex_json.write('limit', 50);
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;

      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xxotm_get_invalid_containers_p;

   -- ========================================================================
   -- XXOTM_GET_LEASED_AREA_CONTAINERS_P   [4-prod-only / KEEP+FIX]
   -- source: db/work/XXOTM_GET_LEASED_AREA_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_leased_area_containers_p (
   p_search_text in varchar2 default null,
   p_offset      in varchar2 default '0'
)
as
   l_offset      number := 0;
   l_total_count number := 0;
   l_page_size   number := 50;
   l_data_found  boolean := false;
begin
   -- Safe offset conversion
   begin
      l_offset := to_number(nvl(p_offset, '0'));
   exception
      when others then
         l_offset := 0;
   end;

   l_offset := nvl(l_offset, 0);

   apex_json.initialize_clob_output;
   apex_json.open_object;

   /* ----------------------------
      TOTAL COUNT (WITH SEARCH)
      ----------------------------
      Was position = 'NA'. This procedure returns the LEASED area, and the data
      query below filters position = 'LEASED', so the count described a
      different set of rows than the page did -- the client got a total (and a
      page count) for the invalid-position containers while being shown the
      leased ones. Almost certainly a copy of XXOTM_GET_INVALID_CONTAINERS_P,
      where 'NA' is correct in BOTH queries, with only the data predicate
      updated. Aligned to the data query. */
   select count(*)
     into l_total_count
     from xxotm_container_inventory_t i
    where i.container_nbr is not null
      and i.container_stored_time is not null
      and i.container_released_time is null
      and i.position = 'LEASED'
      and (
            p_search_text is null
         or upper(i.container_nbr) like '%' || upper(p_search_text) || '%'
      );

   -- Response header
   apex_json.write('response_code', 200);
   apex_json.write('response_message', 'Success');
   apex_json.write('total_count', l_total_count);
   apex_json.write('offset', l_offset);
   apex_json.write('limit', l_page_size);

   apex_json.open_array('data');

   /* ----------------------------
      DATA QUERY (WITH SEARCH + PAGINATION)
      ---------------------------- */
   for r_container in (
      select *
        from (
         select i.container_nbr,
                i.container_type,
                i.inbound_shipment_nbr,
                i.container_stored_time,
                i.cust_name,
                row_number() over (
                   order by i.container_stored_time asc
                ) as row_idx
           from xxotm_container_inventory_t i
          where i.container_nbr is not null
            and i.container_stored_time is not null
            and i.container_released_time is null
            and i.position = 'LEASED'
            and (
                  p_search_text is null
               or upper(i.container_nbr) like '%' || upper(p_search_text) || '%'
            )
      )
       where row_idx > l_offset
         and row_idx <= (l_offset + l_page_size)
   ) loop
      l_data_found := true;

      apex_json.open_object;
      apex_json.write('container_nbr', r_container.container_nbr);
      apex_json.write('container_type', r_container.container_type);
      apex_json.write('shipment_nbr', r_container.inbound_shipment_nbr);
      apex_json.write('customer_name', r_container.cust_name);
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.close_object;

   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
      begin
         apex_json.free_output;
      exception
         when others then null;
      end;

      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm || ' - ' || dbms_utility.format_error_backtrace
      );
      apex_json.write('total_count', 0);
      apex_json.write('offset', 0);
      apex_json.write('limit', 50);
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;

      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xxotm_get_leased_area_containers_p;

   -- ========================================================================
   -- XXOTM_GET_MASTER_SCREEN_LIST_P   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_GET_MASTER_SCREEN_LIST_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_master_screen_list_p
AS
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 200);
    APEX_JSON.WRITE('response_message', 'OK');
 
    APEX_JSON.OPEN_ARRAY('screens');
    FOR r IN (
        SELECT DISTINCT SCREEN_NAME, SCREEN_PATH 
        FROM XX_ROLE_CONFIG 
        WHERE SCREEN_NAME IS NOT NULL and SCREEN_PATH NOT IN ('/manage-role', '/3d-view', '/dashboards', '/access-control')
        ORDER BY SCREEN_NAME
    ) LOOP
        APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('screenName', r.SCREEN_NAME);
        APEX_JSON.WRITE('screenPath', r.SCREEN_PATH);
        APEX_JSON.CLOSE_OBJECT;
    END LOOP;
 
    APEX_JSON.CLOSE_ARRAY;
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
    WHEN OTHERS THEN
         APEX_JSON.INITIALIZE_CLOB_OUTPUT;
         APEX_JSON.OPEN_OBJECT;
         APEX_JSON.WRITE('response_code', 500);
         APEX_JSON.WRITE('response_message', SQLERRM);
         APEX_JSON.CLOSE_OBJECT;
         HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XXOTM_GET_MASTER_SCREEN_LIST_P;

   -- ========================================================================
   -- XXOTM_GET_OPERATORDETAILS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XXOTM_GET_OPERATORDETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_operatordetails (
    p_operator_name IN VARCHAR2 DEFAULT NULL
)
IS
    l_response_clob CLOB;
BEGIN
    -- 1. Input validation
    IF p_operator_name IS NULL THEN
        l_response_clob := JSON_OBJECT(
            'response_code' VALUE '400',
            'response_message' VALUE 'Missing required parameter: operator_name',
            'data' VALUE NULL
        );
        HTP.P(l_response_clob);
        RETURN;
    END IF;

    -- 2. Execute optimized SELECT into a JSON object (single row)
    BEGIN
        SELECT JSON_OBJECT(
            'response_code' VALUE '200',
            'response_message' VALUE 'Success',
            'data' VALUE JSON_OBJECT(
                'status' VALUE t.STATUS,
                'shipment_nbr' VALUE t.SHIPMENT_NBR,
                'assigned_date' VALUE t.ASSIGNED_DATE
            )
        ) INTO l_response_clob
        FROM XXOTM_TASK_ASSIGNMENT_T t
        JOIN XXOTM_CUSTOMER_INVENTORY_T c ON t.SHIPMENT_NBR = c.SHIPMENT_NBR
        WHERE t.OPERATOR = p_operator_name
        ORDER BY t.ASSIGNED_DATE DESC
        FETCH FIRST 1 ROWS ONLY;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
             l_response_clob := JSON_OBJECT(
                'response_code' VALUE '404',
                'response_message' VALUE 'No data found',
                'data' VALUE NULL
            );
    END;

    -- 6. Return/print the JSON
    HTP.P(l_response_clob);

EXCEPTION
    WHEN OTHERS THEN
        l_response_clob := JSON_OBJECT(
            'response_code' VALUE '500',
            'response_message' VALUE 'Internal Error: ' || SQLERRM,
            'data' VALUE NULL
        );
        HTP.P(l_response_clob);
END XXOTM_GET_OPERATORDETAILS;

   -- ========================================================================
   -- XXOTM_GET_RECOMMENDED_CONTAINERS_P   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XXOTM_GET_RECOMMENDED_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_get_recommended_containers_p (
   p_payload IN BLOB,
   p_user_id in varchar2 default null
)
AS
   v_req_clob  CLOB;
   v_count     NUMBER;
   v_cust_nbr VARCHAR2(50);
   v_type      VARCHAR2(100);
   v_req_count NUMBER;
   v_location varchar2(100);
   -- Gate OUT position (for distance calculation)
   c_gate_x CONSTANT NUMBER := -200;
   c_gate_z CONSTANT NUMBER := -35.4;
   
   -- Container dimensions
   c_20ft_length CONSTANT NUMBER := 6.058;
   c_40ft_length CONSTANT NUMBER := 12.192;
   c_lot_gap     CONSTANT NUMBER := 1.75;  -- From dynamic_icds.json
   
   -- Block center positions and lot counts (from dynamic_icds.json)
   -- Block A: x=-88.8, z=-55.75, 23 lots, 20ft
   -- Block B: x=-72, z=-15.06, 11 lots, 40ft
   -- Block C: x=-72, z=+15.06, 11 lots, 40ft
   -- Block D: x=-172, z=+59, varies, 20ft
   
   -- Cursor with proper distance calculation using lot_gap
   CURSOR c_containers (p_cust_nbr VARCHAR2, p_ctype VARCHAR2, p_limit NUMBER) IS
   SELECT container_nbr, position
   FROM (
      SELECT container_nbr,
             position,
             REGEXP_SUBSTR(position, '[^-]+', 1, 2) AS block_letter,
             TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 3)) AS lot_num,
             REGEXP_SUBSTR(position, '[^-]+', 1, 4) AS row_letter,
             -- Calculate approximate X position using proper formula:
             -- X = block_center_x + startX + (lotIndex * lot_spacing)
             -- startX = -totalWidth/2 + containerLength/2
             -- lot_spacing = containerLength + lot_gap
             CASE UPPER(REGEXP_SUBSTR(position, '[^-]+', 1, 2))
                -- Block A: center=-88.8, 23 lots, 20ft
                -- lot_spacing = 6.058 + 1.75 = 7.808
                -- totalWidth = 23 * 7.808 = 179.584
                -- startX = -179.584/2 + 6.058/2 = -86.763
                -- Lot 1: -88.8 + (-86.763 + 0*7.808) = -175.56
                WHEN 'A' THEN -88.8 + (-86.763 + (TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 3)) - 1) * 7.808)
                -- Block B: center=-72, 11 lots, 40ft
                -- lot_spacing = 12.192 + 1.75 = 13.942
                -- totalWidth = 11 * 13.942 = 153.362
                -- startX = -153.362/2 + 12.192/2 = -70.585
                -- Lot 1: -72 + (-70.585 + 0*13.942) = -142.585
                WHEN 'B' THEN -72 + (-70.585 + (TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 3)) - 1) * 13.942)
                -- Block C: same as B
                WHEN 'C' THEN -72 + (-70.585 + (TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 3)) - 1) * 13.942)
                -- Block D: center=-172, 20ft, assuming similar to A
                WHEN 'D' THEN -172 + (-40 + (TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 3)) - 1) * 7.808)
                ELSE 0
             END AS approx_x,
             -- Z position based on block
             CASE UPPER(REGEXP_SUBSTR(position, '[^-]+', 1, 2))
                WHEN 'A' THEN -55.75
                WHEN 'B' THEN -15.06
                WHEN 'C' THEN 15.06
                WHEN 'D' THEN 59
                ELSE 0
             END AS approx_z
        FROM xxotm_container_inventory_t
       WHERE container_type = p_ctype
         AND cust_nbr = p_cust_nbr
         AND booking_id IS NULL
         AND container_released_time IS NULL
         AND outbound_shipment_nbr IS NULL
         AND position IS NOT NULL
         AND container_stored_time IS NOT NULL
         AND inbound_shipment_nbr IS NOT NULL
         and xxotm_container_inventory_t.location = v_location
       ORDER BY TO_DATE(container_stored_time, 'YYYY-MM-DD"T"HH24:MI:SS"Z"') ASC
   )
   -- Order by distance from gate, then positional
   ORDER BY 
      -- 1. Manhattan distance from Gate OUT (smaller = closer = better)
      ABS(approx_x - c_gate_x) + ABS(approx_z - c_gate_z) ASC,
      -- 2. Lot number as tiebreaker (lower = closer to west)
      lot_num ASC,
      -- 3. Row ordering - conditional based on block letter
      CASE 
         WHEN UPPER(block_letter) IN ('A', 'D') THEN -ASCII(row_letter)
         ELSE ASCII(row_letter)
      END ASC,
      -- 4. Pick Topmost Container First (Safety/Accessibility)
      TO_NUMBER(REGEXP_SUBSTR(position, '[^-]+', 1, 5)) DESC
   FETCH FIRST p_limit ROWS ONLY;

BEGIN
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   v_req_clob := TO_CLOB(p_payload);

   BEGIN
      APEX_JSON.parse(v_req_clob);
   EXCEPTION
      WHEN OTHERS THEN
         APEX_JSON.initialize_clob_output;
         APEX_JSON.open_object;
         APEX_JSON.write('response_code', 400);
         APEX_JSON.write('response_message', 'Invalid JSON Input');
         APEX_JSON.open_array('data');
         APEX_JSON.close_array;
         APEX_JSON.close_object;
         HTP.prn(APEX_JSON.get_clob_output);
         RETURN;
   END;
   
   APEX_JSON.initialize_clob_output;
   APEX_JSON.open_object;
   APEX_JSON.write('response_code', 200);
   APEX_JSON.write('response_message', 'Success');
   APEX_JSON.open_array('data');

   v_count := APEX_JSON.get_count('container_types');
   v_cust_nbr := APEX_JSON.get_varchar2('cust_nbr');

   FOR i IN 1..v_count LOOP
      v_type := APEX_JSON.get_varchar2('container_types[%d].container_type', i);
      v_req_count := APEX_JSON.get_number('container_types[%d].container_count', i);
      
      APEX_JSON.open_object;
      APEX_JSON.write('container_type', v_type);
      APEX_JSON.open_array('recommended_containers');
      
      FOR r IN c_containers(v_cust_nbr, v_type, v_req_count) LOOP
         APEX_JSON.write(r.container_nbr);
      END LOOP;

      APEX_JSON.close_array;
      APEX_JSON.close_object;
   END LOOP;

   APEX_JSON.close_array;
   APEX_JSON.close_object;
   HTP.prn(APEX_JSON.get_clob_output);
   
EXCEPTION
   WHEN OTHERS THEN
      APEX_JSON.initialize_clob_output;
      APEX_JSON.open_object;
      APEX_JSON.write('response_code', 500);
      APEX_JSON.write('response_message', SQLERRM);
      APEX_JSON.open_array('data');
      APEX_JSON.close_array;
      APEX_JSON.close_object;
      HTP.prn(APEX_JSON.get_clob_output);
END xxotm_get_recommended_containers_p;

   -- ========================================================================
   -- XXOTM_IDCS_CREATE_USER   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_IDCS_CREATE_USER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_idcs_create_user (
    PAYLOAD IN BLOB
)
IS
    P_PAYLOAD CLOB;
    l_response_clob clob;
    L_RESPONSE JSON_OBJECT_T;
    l_email_count NUMBER;
    l_status_code NUMBER;
    jo        JSON_OBJECT_T;
    jn        JSON_OBJECT_T;
    ja_schemas JSON_ARRAY_T;
    ja_emails  JSON_ARRAY_T;
    jo_email   JSON_OBJECT_T;
    ja_groups  JSON_ARRAY_T;

    jo_group        JSON_OBJECT_T; 
    ja_group_schemas JSON_ARRAY_T;
    ja_group_operations JSON_ARRAY_T;
    jo_group_operation JSON_OBJECT_T;
    ja_group_members JSON_ARRAY_T;
    jo_group_member JSON_OBJECT_T;    

    jo_response JSON_OBJECT_T;
    l_access_token varchar2(10000);
    L_IDCS_USER_ID varchar2(1000);
    l_logs  JSON_OBJECT_T:= JSON_OBJECT_T();
    J APEX_JSON.T_VALUES;

BEGIN
    -- Blob payload to Clob type conversion
    P_PAYLOAD := TO_CLOB(PAYLOAD);

    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;

    -- Parse the JSON payload
    APEX_JSON.PARSE(P_PAYLOAD);
    L_RESPONSE := JSON_OBJECT_T();

    -- Check for existing User by Email in XX_USER_CONFIG
    SELECT count(*) INTO l_email_count FROM XX_USER_CONFIG WHERE email = apex_json.get_varchar2('email');

    IF l_email_count > 0 THEN
            APEX_JSON.WRITE('response_code', 400);
            APEX_JSON.WRITE('response_message', 'Email ' || apex_json.get_varchar2('email') || ' already exists');
            APEX_JSON.CLOSE_OBJECT;
            HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);  
            RETURN;
    END IF;

    -- UPDATED: Use the new function XXOTM_IDCS_GET_TOKEN
    l_access_token := XXOTM_IDCS_GET_TOKEN;
    l_access_token := trim(BOTH '"'  FROM l_access_token);

    IF l_access_token IS NOT NULL THEN

        ja_schemas := JSON_ARRAY_T();
        ja_schemas.append('urn:ietf:params:scim:schemas:core:2.0:User');

        -- Name object
        jn := JSON_OBJECT_T();
        jn.put('familyName', apex_json.get_varchar2('name')); -- Payload: name: FullName

        -- Emails array
        jo_email := JSON_OBJECT_T();
        jo_email.put('value',   apex_json.get_varchar2('email'));
        jo_email.put('type',    'work');
        jo_email.put('primary', TRUE);
        ja_emails := JSON_ARRAY_T();
        ja_emails.append(jo_email);

        -- Main JSON object for IDCS Creation
        jo := JSON_OBJECT_T();
        jo.put('schemas', ja_schemas);
        jo.put('userName', apex_json.get_varchar2('email')); -- Use Email as IDCS Username
        jo.put('name', jn);
        jo.put('emails', ja_emails);

        -- Headers
        apex_web_service.g_request_headers(1).name := 'Content-Type';
        apex_web_service.g_request_headers(1).value := 'application/json';

        apex_web_service.g_request_headers(2).name := 'Authorization';
        apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

        -- Call IDCS API
        l_response_clob := apex_web_service.make_rest_request(
            p_url => 'https://idcs-6cce7520f76c449188e5166f961e3cca.identity.oraclecloud.com/admin/v1/Users/',
            p_http_method => 'POST',
            p_body => jo.to_string(),
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
        );

        l_status_code :=  apex_web_service.g_status_code;

        IF l_status_code BETWEEN 200 AND 299 THEN 

            jo_response := json_object_t.parse(l_response_clob);
            L_IDCS_USER_ID := jo_response.get_string('id');
            L_RESPONSE.PUT('user created', L_IDCS_USER_ID);

            -- GROUPS ASSIGNMENT (MFA_USERS)
            BEGIN      
                -- schemas array
                ja_group_schemas := JSON_ARRAY_T();
                ja_group_schemas.append('urn:ietf:params:scim:api:messages:2.0:PatchOp');

                -- members array for value
                jo_group_member := JSON_OBJECT_T();
                jo_group_member.put('value', L_IDCS_USER_ID);
                jo_group_member.put('type', 'User');
                ja_group_members := JSON_ARRAY_T();
                ja_group_members.append(jo_group_member);

                -- Operation object
                jo_group_operation := JSON_OBJECT_T();
                jo_group_operation.put('op', 'add');
                jo_group_operation.put('path', 'members');
                jo_group_operation.put('value', ja_group_members);

                -- Operations array
                ja_group_operations := JSON_ARRAY_T();
                ja_group_operations.append(jo_group_operation);

                -- Main object
                jo_group := JSON_OBJECT_T();
                jo_group.put('schemas', ja_group_schemas);
                jo_group.put('Operations', ja_group_operations);

                -- Headers
                apex_web_service.g_request_headers(1).name := 'Content-Type';
                apex_web_service.g_request_headers(1).value := 'application/json';
                apex_web_service.g_request_headers(2).name := 'Authorization';
                apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

                -- PATCH Group
                l_response_clob := apex_web_service.make_rest_request(
                    p_url => 'https://idcs-6cce7520f76c449188e5166f961e3cca.identity.oraclecloud.com/admin/v1/Groups/8a83e54c28794c4ba948cc1600ff03b1',
                    p_http_method => 'PATCH', 
                    p_body => jo_group.to_string(),
                    p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                );
            EXCEPTION WHEN OTHERS THEN 
                l_logs.PUT('error_assigning_group', sqlerrm);
            END; 

            -- INSERT INTO LOCAL TABLE (XX_USER_CONFIG)
            BEGIN 
                INSERT INTO XX_USER_CONFIG (
                    ID,
                    NAME,
                    EMAIL,
                    ROLE,
                    IS_ACTIVE,
                    CREATED_DATE,
                    CREATED_BY
                ) VALUES (
                    XX_USER_CONFIG_ID_SEQ.NEXTVAL,
                    apex_json.get_varchar2('name'),
                    apex_json.get_varchar2('email'),
                    apex_json.get_varchar2('role'), -- Assuming payload has role
                    'Y',
                    SYSDATE,
                    'ADMIN' -- Or pass CreatedBy if available
                );

                L_RESPONSE.PUT('response_code', 200);
                L_RESPONSE.PUT('response_message', 'Success');

            EXCEPTION WHEN OTHERS THEN 
                L_RESPONSE.PUT('response_code', 500);
                L_RESPONSE.PUT('response_message', 'Database Insert Failed: ' || sqlerrm);
                l_logs.PUT('data_insertion_error', sqlerrm);
            END;

        ELSE 
             -- IDCS Creation Failed (Status != 2xx)
             L_RESPONSE.PUT('response_code', 401);
             L_RESPONSE.PUT('response_message', 'IDCS Creation Failed: ' || l_status_code);
             l_logs.PUT('idcs_response', l_response_clob);
        END IF;

    ELSE 
        -- Token Failure
        L_RESPONSE.PUT('response_code', 401);
        L_RESPONSE.PUT('response_message', 'Failed to get IDCS Access Token');
    END IF; 

    -- Final Response Output
    APEX_JSON.WRITE('response_code', L_RESPONSE.GET('response_code').TO_NUMBER());
    APEX_JSON.WRITE('response_message', REPLACE(L_RESPONSE.GET('response_message').TO_STRING(),'"',''));

    -- Optional: Return logs in data if needed, or structured response
    APEX_JSON.PARSE(J, l_logs.TO_STRING());
    APEX_JSON.WRITE('logs', J);

    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);

EXCEPTION WHEN OTHERS THEN
    L_RESPONSE.PUT('response_code', 500);
    L_RESPONSE.PUT('response_message', 'Unhandled Exception: ' || sqlerrm);

    APEX_JSON.WRITE('response_code', L_RESPONSE.GET('response_code').TO_NUMBER());
    APEX_JSON.WRITE('response_message', REPLACE(L_RESPONSE.GET('response_message').TO_STRING(),'"',''));
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);  
END XXOTM_IDCS_CREATE_USER;

   -- ========================================================================
   -- XXOTM_POST_RESERVATION_CONTAINERS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_POST_RESERVATION_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_post_reservation_containers_p (
   -- Last Updated Date : 18-Dec-2025
   -- Last Updated By : Madhan
   -- Description : updated hardcoded credentials to web credentials.
   payload IN BLOB,
   p_user_id in varchar2 default null
)
IS
   v_location varchar2(100);
   -- Convert payload
   p_payload              CLOB;

   -- Request variables
   l_booking_id           VARCHAR2(100);
   l_container_nbr        VARCHAR2(100);
   l_booking_order_nbr    VARCHAR2(100);   -- Order linked to booking (container_nbr IS NULL)
   l_container_order_nbr  VARCHAR2(100);   -- Order linked to container (booking_id IS NULL)

   -- Web service variables
   l_base_url             VARCHAR2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2';
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   l_api_url              VARCHAR2(1000);
   l_api_payload          CLOB;
   l_api_response         CLOB;
   l_http_status          NUMBER;

   -- Tracking
   l_success_count        NUMBER := 0;
   l_fail_count           NUMBER := 0;
   l_total_count          NUMBER := 0;
   l_failed_containers    VARCHAR2(4000) := NULL;
   l_api_error_msg        VARCHAR2(500);

BEGIN
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert BLOB to CLOB
   p_payload := TO_CLOB(payload);

   -- Parse the JSON payload
   APEX_JSON.parse(p_payload);

   -- Extract booking_id
   l_booking_id := APEX_JSON.get_varchar2(p_path => 'booking_id');

   -- Validate booking_id
   IF l_booking_id IS NULL THEN
      APEX_JSON.initialize_clob_output;
      APEX_JSON.open_object;
      APEX_JSON.write('response_code', 400);
      APEX_JSON.write('response_message', 'booking_id is required');
      APEX_JSON.close_object;
      HTP.prn(APEX_JSON.get_clob_output);
      RETURN;
   END IF;

   -- Get containers array count
   l_total_count := APEX_JSON.get_count(p_path => 'reserve_containers');

   IF l_total_count IS NULL OR l_total_count = 0 THEN
      APEX_JSON.initialize_clob_output;
      APEX_JSON.open_object;
      APEX_JSON.write('response_code', 400);
      APEX_JSON.write('response_message', 'reserve_containers array is empty or missing');
      APEX_JSON.close_object;
      HTP.prn(APEX_JSON.get_clob_output);
      RETURN;
   END IF;

   -- Loop through each container
   FOR i IN 1..l_total_count LOOP
      BEGIN
         -- Get container number from array
         l_container_nbr := APEX_JSON.get_varchar2(p_path => 'reserve_containers[%d]', p0 => i);

         IF l_container_nbr IS NULL THEN
            l_fail_count := l_fail_count + 1;
            IF l_failed_containers IS NULL THEN
               l_failed_containers := 'Container[' || i || '] is null';
            ELSE
               l_failed_containers := l_failed_containers || ', Container[' || i || '] is null';
            END IF;
            CONTINUE;
         END IF;

         -- ==================================================
         -- STEP 1: Fetch inbound_order_nbr for the BOOKING
         -- (where booking_id matches and container_nbr IS NULL)
         -- Commented as per Narayana Anna Suggestion
         -- ==================================================
         -- BEGIN
         --    SELECT inbound_order_nbr
         --    INTO l_booking_order_nbr
         --    FROM xxotm_container_inventory_t
         --    WHERE booking_id = l_booking_id
         --      AND container_nbr IS NULL
         --      AND ROWNUM = 1;
         -- EXCEPTION
         --    WHEN NO_DATA_FOUND THEN
         --       l_booking_order_nbr := NULL;
         -- END;

         -- IF l_booking_order_nbr IS NULL THEN
         --    l_fail_count := l_fail_count + 1;
         --    IF l_failed_containers IS NULL THEN
         --       l_failed_containers := l_container_nbr || ' (no order for booking ' || l_booking_id || ')';
         --    ELSE
         --       l_failed_containers := l_failed_containers || ', ' || l_container_nbr || ' (no order for booking)';
         --    END IF;
         --    CONTINUE;
         -- END IF;

         -- ==================================================
         -- STEP 2: Fetch inbound_order_nbr for the CONTAINER
         -- (where container_nbr matches and booking_id IS NULL)
         -- ==================================================
         BEGIN
            SELECT inbound_order_nbr
            INTO l_container_order_nbr
            FROM xxotm_container_inventory_t
            WHERE container_nbr = l_container_nbr
              AND booking_id IS NULL  and xxotm_container_inventory_t.location = v_location
              AND ROWNUM = 1;
         EXCEPTION
            WHEN NO_DATA_FOUND THEN
               l_container_order_nbr := NULL;
         END;

         IF l_container_order_nbr IS NULL THEN
            l_fail_count := l_fail_count + 1;
            IF l_failed_containers IS NULL THEN
               l_failed_containers := l_container_nbr || ' (no unbooked order for container)';
            ELSE
               l_failed_containers := l_failed_containers || ', ' || l_container_nbr || ' (no unbooked order)';
            END IF;
            CONTINUE;
         END IF;

         -- ==================================================
         -- STEP 3: PATCH - Update booking's order with container_nbr
         -- PATCH /orderReleases/NAQLEEN.{booking_order_nbr}
         -- Set attribute3 = container_nbr
         -- ==================================================
         -- l_api_url := l_base_url || '/orderReleases/NAQLEEN.' || l_booking_order_nbr;
         -- l_api_payload := '{attribute3: ' || l_container_nbr || '}';

         -- APEX_WEB_SERVICE.g_request_headers.DELETE;
         -- APEX_WEB_SERVICE.g_request_headers(1).name := 'Content-Type';
         -- APEX_WEB_SERVICE.g_request_headers(1).value := 'application/json';

         -- l_api_response := APEX_WEB_SERVICE.make_rest_request(
         --    p_url         => l_api_url,
         --    p_http_method => 'PATCH',
         --    p_credential_static_id => l_credential_static_id,
         --    p_wallet_path => l_wallet_path,
         --    p_body        => l_api_payload
         -- );
         -- l_http_status := APEX_WEB_SERVICE.g_status_code;

         -- IF l_http_status NOT IN (200, 201, 204) THEN
         --    l_fail_count := l_fail_count + 1;
         --    l_api_error_msg := SUBSTR(NVL(l_api_response, 'No response'), 1, 200);
         --    IF l_failed_containers IS NULL THEN
         --       l_failed_containers := l_container_nbr || ' (PATCH ' || l_http_status || ': ' || l_api_error_msg || ')';
         --    ELSIF LENGTH(l_failed_containers) < 3500 THEN
         --       l_failed_containers := l_failed_containers || ', ' || l_container_nbr || ' (PATCH ' || l_http_status || ')';
         --    END IF;
         --    CONTINUE;
         -- END IF;

         -- ==================================================
         -- STEP 4: POST refnums - Link booking to container's order
         -- POST /orderReleases/NAQLEEN.{container_order_nbr}/refnums
         -- ==================================================
         l_api_url := l_base_url || '/orderReleases/NAQLEEN.' || l_container_order_nbr || '/refnums';
         l_api_payload := '{' ||
            '"orderReleaseRefnumQualGid": "NAQLEEN.BOOKING_NO",' ||
            '"orderReleaseRefnumValue": "' || l_booking_id || '",' ||
            '"domainName": "NAQLEEN"' ||
         '}';

         APEX_WEB_SERVICE.g_request_headers.DELETE;
         APEX_WEB_SERVICE.g_request_headers(1).name := 'Content-Type';
         APEX_WEB_SERVICE.g_request_headers(1).value := 'application/json';

         l_api_response := APEX_WEB_SERVICE.make_rest_request(
            p_url         => l_api_url,
            p_http_method => 'POST',
            p_credential_static_id => l_credential_static_id,
            p_body        => l_api_payload,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
         l_http_status := APEX_WEB_SERVICE.g_status_code;

         IF l_http_status IN (200, 201, 204) THEN
            l_success_count := l_success_count + 1;
            -- if post is success then update that booking id agains that container number in the xxotm_container_inventory_t
            -- to solve UI descripencies due to sync time issues.
            UPDATE XXOTM_CONTAINER_INVENTORY_T SET BOOKING_ID = l_booking_id WHERE CONTAINER_NBR = l_container_nbr and CONTAINER_STORED_TIME IS NOT NULL AND CONTAINER_RELEASED_TIME IS null and xxotm_container_inventory_t.LOCATION = v_location;
         ELSE
            l_fail_count := l_fail_count + 1;
            l_api_error_msg := SUBSTR(NVL(l_api_response, 'No response'), 1, 200);
            IF l_failed_containers IS NULL THEN
               l_failed_containers := l_container_nbr || ' (POST refnums ' || l_http_status || ': ' || l_api_error_msg || ')';
            ELSIF LENGTH(l_failed_containers) < 3500 THEN
               l_failed_containers := l_failed_containers || ', ' || l_container_nbr || ' (POST ' || l_http_status || ')';
            END IF;
         END IF;

      EXCEPTION
         WHEN OTHERS THEN
            l_fail_count := l_fail_count + 1;
            IF l_failed_containers IS NULL THEN
               l_failed_containers := l_container_nbr || ' (Exception: ' || SUBSTR(SQLERRM, 1, 150) || ')';
            ELSIF LENGTH(l_failed_containers) < 3500 THEN
               l_failed_containers := l_failed_containers || ', ' || l_container_nbr || ' (Ex: ' || SUBSTR(SQLERRM, 1, 50) || ')';
            END IF;
      END;
   END LOOP;

   -- Build response
   APEX_JSON.initialize_clob_output;
   APEX_JSON.open_object;

   IF l_fail_count = 0 THEN
      APEX_JSON.write('response_code', 200);
      APEX_JSON.write('response_message', 'Successfully reserved ' || l_success_count || ' containers for booking ' || l_booking_id);
   ELSIF l_success_count = 0 THEN
      APEX_JSON.write('response_code', 500);
      APEX_JSON.write('response_message', 'Failed to reserve containers');
   ELSE
      APEX_JSON.write('response_code', 207);
      APEX_JSON.write('response_message', 'Partial: ' || l_success_count || ' reserved, ' || l_fail_count || ' failed');
   END IF;

   APEX_JSON.write('success_count', l_success_count);
   APEX_JSON.write('fail_count', l_fail_count);
   APEX_JSON.write('booking_id', l_booking_id);

   IF l_failed_containers IS NOT NULL THEN
      APEX_JSON.write('debug_errors', l_failed_containers);
   END IF;

   APEX_JSON.close_object;
   HTP.prn(APEX_JSON.get_clob_output);

EXCEPTION
   WHEN OTHERS THEN
      APEX_JSON.initialize_clob_output;
      APEX_JSON.open_object;
      APEX_JSON.write('response_code', 500);
      APEX_JSON.write('response_message', 'Unexpected error: ' || SQLERRM);
      APEX_JSON.write('debug_errors', 'Global exception: ' || SUBSTR(SQLERRM, 1, 500));
      APEX_JSON.close_object;
      HTP.prn(APEX_JSON.get_clob_output);
END xxotm_post_reservation_containers_p;

   -- ========================================================================
   -- XXOTM_PRINT_EIR   [4-prod-only / KEEP]
   -- source: db/work/XXOTM_PRINT_EIR.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_print_eir (
   p_eir_no         in  varchar2,
   p_gate_type      in  varchar2 default 'GATE OUT/RELEASE',
   p_shipment_nbr   in  varchar2,
   p_date_time      in  varchar2,
   p_container_no   in  varchar2,
   p_container_type in  varchar2,   -- ISO Code
   p_customer_name  in  varchar2,   -- Customer Name on gate in, Line on gate out
   p_shipper        in  varchar2,   -- gate out only
   p_booking_no     in  varchar2,
   p_port_discharge in  varchar2,
   p_seal_no        in  varchar2,
   p_serial_no      in  varchar2,   -- gate out only, e.g. 11/100
   p_remarks        in  varchar2,
   p_driver_name    in  varchar2,
   p_truck_no       in  varchar2,
   p_passed_user    in  varchar2 default null,
   p_printed_by     in  varchar2 default null,
   x_pdf            out blob
)
as
   c_gate_in constant boolean := upper(trim(p_gate_type)) = 'GATE IN';
   -- Gate out prints 12 rows, gate in 10: size the roll to the content
   c_cm_h    constant number  := case when c_gate_in then 23 else 25 end;
   c_page_w  constant number  := as_pdf3.conv2uu(8,      'cm');
   c_page_h  constant number  := as_pdf3.conv2uu(c_cm_h, 'cm');
   -- Integer geometry on purpose: fractional Y made identical hairlines rasterise at
   -- different weights row to row. Every line now sits on a whole point.
   c_left    constant number := 14;
   c_width   constant number := 199;
   c_rule    constant number := 0.5;    -- one line width for every divider
   c_row     constant number := 32;     -- row pitch: label + value + rule + breathing room
   l_y       number;
   l_logo    blob;
   l_px_w    number;
   l_px_h    number;
   l_lw      number;
   l_lh      number;

   procedure ctr (p_txt varchar2, p_y number) is       -- set the font first: str_len needs it
   begin
      as_pdf3.put_txt(round((c_page_w - as_pdf3.str_len(p_txt)) / 2), p_y, p_txt);
   end;

   procedure rule (p_y number) is
   begin
      as_pdf3.horizontal_line(c_left, round(p_y), c_width, c_rule, '000000');
   end;

   procedure fld (p_label varchar2, p_value varchar2) is
      l_val varchar2(4000) := nvl(p_value, '-');
   begin
      as_pdf3.set_color('000000');
      as_pdf3.set_font('helvetica', 'N', 7);
      as_pdf3.put_txt(c_left, l_y, upper(p_label));

      as_pdf3.set_font('helvetica', 'B', 11);
      if as_pdf3.str_len(l_val) > c_width then         -- never run past the 8cm width
         as_pdf3.set_font('helvetica', 'B', 8);
      end if;
      as_pdf3.put_txt(c_left, l_y - 13, l_val);

      rule(l_y - 21);                                  -- 8pt under the value
      l_y := l_y - c_row;                              -- 11pt down to the next label
   end;
begin
   as_pdf3.init;
   as_pdf3.set_page_size(8, c_cm_h, 'cm');        -- width first; no set_page_orientation after
   as_pdf3.set_margins(0.4, 0.4, 0.4, 0.4, 'cm'); -- 11.34pt, so write() accepts c_left = 14
   l_y := floor(c_page_h - 14);

   begin
      select asset_blob, asset_width_px, asset_height_px
        into l_logo, l_px_w, l_px_h
        from xxotm_assets_t
       where asset_code = 'NAQLEEN_LOGO';

      l_lw := 96;                                      -- must be <= l_px_w: cannot scale up
      l_lh := round(l_lw * l_px_h / l_px_w);           -- integer, and keeps the aspect ratio
      as_pdf3.put_image(
         p_img    => l_logo,
         p_x      => round((c_page_w - l_lw) / 2),     -- centre it yourself
         p_y      => l_y - l_lh,                       -- p_y is the BOTTOM of the image
         p_width  => l_lw,
         p_height => l_lh,
         p_align  => 'left'                            -- never leave this as 'center'
      );
      l_y := l_y - l_lh - 14;
   exception
      when no_data_found then l_y := l_y - 14;         -- print without the logo rather than fail
   end;

   as_pdf3.set_color('000000');
   as_pdf3.set_font('helvetica', 'B', 8);              -- 9pt would push this past the margins
   ctr('EQUIPMENT INTERCHANGE RECEIPT (EIR)', l_y);
   l_y := l_y - 18;

   -- Black bar, white knockout text: still strictly black and white
   as_pdf3.rect(c_left, l_y - 6, c_width, 20, null, '000000');
   as_pdf3.set_color('ffffff');
   as_pdf3.set_font('helvetica', 'B', 11);
   ctr(p_gate_type, l_y);
   as_pdf3.set_color('000000');
   l_y := l_y - 32;

   fld('Date and Time',     p_date_time|| ' UTC');
   fld('Container Number',  p_container_no);
   fld('ISO Code',          p_container_type);

   if c_gate_in then
      fld('Customer Name',  p_customer_name);          -- gate in has neither Line nor Shipper
   else
      fld('Line',           p_customer_name);          -- gate out uses customer name as Line
      fld('Shipper',        p_shipper);
   end if;

   fld('Booking Number',    p_booking_no);
   fld('Port of Discharge', p_port_discharge);
   fld('Seal No',           p_seal_no);

   if not c_gate_in then
      fld('Serial No',      p_serial_no);              -- gate out only
   end if;

   fld('Remarks',           p_remarks);
   fld('Driver Name',       p_driver_name);
   fld('Truck No',          p_truck_no);

   declare
      l_bc   blob;
      l_pw   number;
      l_ph   number;
      l_dw   number;
      l_dh   number;
      l_mask number;
   begin
      -- Shipment number: as_barcode prints whatever it encodes underneath the bars,
      -- so this also gives us the caption for free.
      l_bc := as_barcode.barcode_blob(
                 p_val    => p_shipment_nbr,
                 p_type   => 'code128',
                 p_parm   => '{"scale":4}',
                 p_format => 'PNG');          -- default is BMP, which as_pdf3 cannot read

      -- PNG layout: 8-byte signature, 4-byte length, 'IHDR', then width and height
      l_pw := to_number(rawtohex(dbms_lob.substr(l_bc, 4, 17)), 'xxxxxxxx');
      l_ph := to_number(rawtohex(dbms_lob.substr(l_bc, 4, 21)), 'xxxxxxxx');

      l_dw := least(c_width, l_pw / 2);            -- clamp to the 8cm content width
      l_dh := round(l_dw * l_ph / l_pw);           -- keep the aspect ratio: no squashing

      l_y := l_y - 16 - l_dh;
      as_pdf3.put_image(
         p_img    => l_bc,
         p_x      => round((c_page_w - l_dw) / 2),
         p_y      => l_y,
         p_width  => l_dw,
         p_height => l_dh,
         p_align  => 'left');

      -- as_barcode over-declares the PNG height by l_fh (14) rows: those rows carry no
      -- IDAT data and viewers paint them solid black, which reads as a thick bar under
      -- the barcode. Mask the strip, then draw a real hairline divider.
      l_mask := ceil(l_dh * 15 / l_ph);
      as_pdf3.rect(c_left, l_y, c_width, l_mask, null, 'ffffff');

      rule(l_y - 14);
      l_y := l_y - 30;

      if l_bc is not null and dbms_lob.istemporary(l_bc) = 1 then
         dbms_lob.freetemporary(l_bc);
      end if;
   end;

   as_pdf3.set_color('000000');
   as_pdf3.set_font('helvetica', 'N', 6);
   as_pdf3.write(
      p_txt         => 'This Equipment Interchange Receipt (EIR) certifies that the container '
                    || 'listed herein has been inspected and transferred in the condition noted '
                    || 'at the time of interchange. Any damages or discrepancies must be reported '
                    || 'immediately to Naqleen management. The undersigned acknowledges receipt '
                    || 'and agrees to the terms of this interchange.',
      p_x           => c_left,
      p_y           => l_y,
      p_line_height => 8,
      p_start       => c_left,
      p_width       => c_width);
   l_y := floor(as_pdf3.get(as_pdf3.c_get_y)) - 28;

   rule(l_y + 17);
   as_pdf3.set_font('helvetica', 'N', 7);
   as_pdf3.put_txt(c_left, l_y,      'Printer User: ' || p_printed_by);
   as_pdf3.put_txt(c_left, l_y - 11, 'Entry passed User: ' || p_passed_user);
   as_pdf3.put_txt(c_left, l_y - 22, 'Date of printing: '
                                  || to_char(sysdate, 'DD-MM-YYYY, HH24:MI'));

   x_pdf := as_pdf3.get_pdf;
end xxotm_print_eir;

   -- ========================================================================
   -- XXOTM_SWAP_RESERVATION_CONTAINERS_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_SWAP_RESERVATION_CONTAINERS_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_swap_reservation_containers_p (
   -- Last Updated Date : 18-Dec-2025
   -- Last Updated By : Madhan
   -- Description : updated hardcoded credentials to web credentials
   payload in blob,
   p_user_id in varchar2 default null
)
is
   v_location varchar2(100);
   -- Convert payload
   p_payload             clob;

   -- Request variables
   l_booking_id          varchar2(100);

   -- Loop/Process variables
   l_unreserve_nbr       varchar2(100);
   l_reserve_nbr         varchar2(100);
   l_container_order_nbr varchar2(100);   -- Order linked to container

   -- Web service variables
   l_base_url            varchar2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2'
   ;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   l_api_url             varchar2(1000);
   l_api_payload         clob;
   l_api_response        clob;
   l_http_status         number;

   -- Tracking
   l_success_count       number := 0;
   l_fail_count          number := 0;
   l_total_unreserve     number := 0;
   l_total_reserve       number := 0;
   l_failed_containers   varchar2(4000) := null;
   l_api_error_msg       varchar2(500);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert BLOB to CLOB
   p_payload := to_clob(payload);

   -- Parse the JSON payload
   apex_json.parse(p_payload);

   -- Extract booking_id
   l_booking_id := apex_json.get_varchar2(p_path => 'booking_id');

   -- Validate booking_id
   if l_booking_id is null then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'booking_id is required'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   -- Get array counts
   l_total_unreserve := apex_json.get_count(p_path => 'unreserve_containers');
   l_total_reserve := apex_json.get_count(p_path => 'reserve_containers');

   -- Validate arrays
   if l_total_unreserve is null
   or l_total_unreserve = 0 then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'unreserve_containers array is empty or missing'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   if l_total_reserve is null
   or l_total_reserve = 0 then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'reserve_containers array is empty or missing'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   if l_total_unreserve <> l_total_reserve then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'Mismatch in container counts. Must swap equal number of containers.'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      return;
   end if;

   -- Loop through each pair (index i)
   for i in 1..l_total_unreserve loop
      begin
         -- Get container numbers from both arrays at index i
         l_unreserve_nbr := apex_json.get_varchar2(
            p_path => 'unreserve_containers[%d]',
            p0     => i
         );
         l_reserve_nbr := apex_json.get_varchar2(
            p_path => 'reserve_containers[%d]',
            p0     => i
         );
         if l_unreserve_nbr is null
         or l_reserve_nbr is null then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := 'Pair['
                                      || i
                                      || '] has null container';
            else
               l_failed_containers := l_failed_containers
                                      || ', Pair['
                                      || i
                                      || '] has null';
            end if;
            continue;
         end if;

         -- ==================================================
         -- PART A: UNRESERVE (DELETE)
         -- ==================================================

         -- 1. Fetch inbound_order_nbr for the UNRESERVE container
         l_container_order_nbr := null;
         begin
            select inbound_order_nbr
              into l_container_order_nbr
              from xxotm_container_inventory_t
             where container_nbr = l_unreserve_nbr
               and booking_id = l_booking_id  and xxotm_container_inventory_t.location = v_location
               and rownum = 1;
         exception
            when no_data_found then
               l_container_order_nbr := null;
         end;

         if l_container_order_nbr is null then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := 'Swap['
                                      || i
                                      || ']: '
                                      || l_unreserve_nbr
                                      || ' (no matching order)';
            else
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_unreserve_nbr
                                      || ' (no matching order)';
            end if;
            continue; -- Convert to next pair/iteration
         end if;

         -- 2. DELETE refnums
         l_api_url := l_base_url
                      || '/orderReleases/NAQLEEN.'
                      || l_container_order_nbr
                      || '/refnums/NAQLEEN.BOOKING_NOx'
                      || l_booking_id;
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_api_response := apex_web_service.make_rest_request(
            p_url         => l_api_url,
            p_http_method => 'DELETE',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
         l_http_status := apex_web_service.g_status_code;
         if l_http_status not in ( 200,
                                   204 ) then
            -- DELETE FAILED
            l_fail_count := l_fail_count + 1;
            l_api_error_msg := substr(
               nvl(
                  l_api_response,
                  'No response'
               ),
               1,
               200
            );
            if l_failed_containers is null then
               l_failed_containers := l_unreserve_nbr
                                      || ' (Delete Failed '
                                      || l_http_status
                                      || ')';
            else
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_unreserve_nbr
                                      || ' (Delete Failed)';
            end if;
            continue; -- Do not proceed to Reserve if Unreserve failed
         end if;

         -- DELETE SUCCESS: Update Inventory for Unreserve
         update xxotm_container_inventory_t
            set
            booking_id = null
          where container_nbr = l_unreserve_nbr  and xxotm_container_inventory_t.location = v_location;

         -- ==================================================
         -- PART B: RESERVE (POST)
         -- ==================================================

         -- 1. Fetch inbound_order_nbr for the NEW RESERVE container
         l_container_order_nbr := null; -- Reset
         begin
            select inbound_order_nbr
              into l_container_order_nbr
              from xxotm_container_inventory_t
             where container_nbr = l_reserve_nbr
               and booking_id is null  and xxotm_container_inventory_t.location = v_location
               and rownum = 1;
         exception
            when no_data_found then
               l_container_order_nbr := null;
         end;

         if l_container_order_nbr is null then
            -- Unreserve worked, but Reserve failed pre-check. 
            -- We count this as a partial fail for this pair, but the Unreserve is committed.
            -- Logic choice: Count as fail? Or success-with-warning? 
            -- User wants swap. If swap fails, it's a fail.
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := l_reserve_nbr || ' (New container not available)';
            else
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_reserve_nbr
                                      || ' (New container not available)';
            end if;
            continue;
         end if;

         -- 2. POST refnums
         l_api_url := l_base_url
                      || '/orderReleases/NAQLEEN.'
                      || l_container_order_nbr
                      || '/refnums';
         l_api_payload := '{'
                          || '"orderReleaseRefnumQualGid": "NAQLEEN.BOOKING_NO",'
                          || '"orderReleaseRefnumValue": "'
                          || l_booking_id
                          || '",'
                          || '"domainName": "NAQLEEN"'
                          || '}';

         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_api_response := apex_web_service.make_rest_request(
            p_url         => l_api_url,
            p_http_method => 'POST',
            p_credential_static_id => l_credential_static_id,
            p_body        => l_api_payload,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
         l_http_status := apex_web_service.g_status_code;
         if l_http_status in ( 200,
                               201,
                               204 ) then
            -- SWAP COMPLETE SUCCESS
            l_success_count := l_success_count + 1;
            -- Update Inventory for Reserve
            update xxotm_container_inventory_t
               set
               booking_id = l_booking_id
             where container_nbr = l_reserve_nbr
             and xxotm_container_inventory_t.location = v_location;
         else
            -- RESERVE FAILED (Unreserve was successful)
            l_fail_count := l_fail_count + 1;
            l_api_error_msg := substr(
               nvl(
                  l_api_response,
                  'No response'
               ),
               1,
               200
            );
            if l_failed_containers is null then
               l_failed_containers := l_unreserve_nbr
                                      || '->'
                                      || l_reserve_nbr
                                      || ' (Reserve Failed '
                                      || l_http_status
                                      || ')';
            else
               l_failed_containers := l_failed_containers
                                      || ', '
                                      || l_unreserve_nbr
                                      || '->'
                                      || l_reserve_nbr
                                      || ' (Reserve Failed)';
            end if;
         end if;

      exception
         when others then
            l_fail_count := l_fail_count + 1;
            if l_failed_containers is null then
               l_failed_containers := 'Swap['
                                      || i
                                      || '] Exception: '
                                      || substr(
                  sqlerrm,
                  1,
                  100
               );
            else
               l_failed_containers := l_failed_containers
                                      || ', Swap['
                                      || i
                                      || '] Exception';
            end if;
      end;
   end loop;

   -- Build response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_fail_count = 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Successfully swapped '
         || l_success_count
         || ' containers'
      );
   elsif l_success_count = 0 then
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Failed to swap containers'
      );
   else
      apex_json.write(
         'response_code',
         207
      );
      apex_json.write(
         'response_message',
         'Partial: '
         || l_success_count
         || ' swapped, '
         || l_fail_count
         || ' failed'
      );
   end if;

   apex_json.write(
      'success_count',
      l_success_count
   );
   apex_json.write(
      'fail_count',
      l_fail_count
   );
   apex_json.write(
      'booking_id',
      l_booking_id
   );
   if l_failed_containers is not null then
      apex_json.write(
         'debug_errors',
         l_failed_containers
      );
   end if;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Unexpected error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xxotm_swap_reservation_containers_p;

   -- ========================================================================
   -- XXOTM_UPDATE_USER_P   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XXOTM_UPDATE_USER_P.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xxotm_update_user_p (
    p_payload IN BLOB
)
IS
    l_json_obj       JSON_OBJECT_T;
    l_assigned_roles JSON_ARRAY_T;
    l_role_node      JSON_ELEMENT_T;
    l_role_code      VARCHAR2(100);
    l_email          VARCHAR2(255);
    l_new_name       VARCHAR2(255);
    l_current_name   VARCHAR2(255);
    l_current_active_status VARCHAR2(1);
    l_current_role VARCHAR2(100);
    l_primary_role   VARCHAR2(100);
    l_is_active_bool BOOLEAN;
    l_is_active_val  VARCHAR2(1);
    l_user_id        NUMBER;
    l_idcs_user_id   VARCHAR2(1000);
    l_access_token   VARCHAR2(32767);
    l_url            VARCHAR2(1000);
    l_patch_body     CLOB;
    l_response_clob  CLOB;
    l_status_code    NUMBER;
    l_response       JSON_OBJECT_T := JSON_OBJECT_T();
    l_count          NUMBER;

    -- For IDCS Patch
    jo_patch         JSON_OBJECT_T;
    ja_schemas       JSON_ARRAY_T;
    ja_ops           JSON_ARRAY_T;
    jo_op_name       JSON_OBJECT_T;

    -- Exception buffer
    l_err_msg        VARCHAR2(4000);
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;

    -- Parse Payload
    BEGIN
        l_json_obj := JSON_OBJECT_T(p_payload);
        l_email := l_json_obj.get_string('email');
    EXCEPTION WHEN OTHERS THEN
        l_response.put('response_code', 400);
        l_response.put('response_message', 'Invalid JSON payload');
        GOTO output_json;
    END;

    IF l_email IS NULL THEN
        l_response.put('response_code', 400);
        l_response.put('response_message', 'Email is required');
        GOTO output_json;
    END IF;

    -- Find User
    BEGIN
        SELECT ID, NAME, IS_ACTIVE, ROLE
          INTO l_user_id, l_current_name, l_current_active_status, l_current_role
          FROM XX_USER_CONFIG
         WHERE EMAIL = l_email;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        l_response.put('response_code', 404);
        l_response.put('response_message', 'User not found');
        GOTO output_json;
    END;

    -- 1. Handling Name Update (IDCS Sync)
    IF l_json_obj.has('new_name') AND l_json_obj.get_string('new_name') <> l_current_name THEN
        l_new_name := l_json_obj.get_string('new_name');

        IF l_new_name IS NOT NULL THEN
             l_access_token := TRIM(BOTH '"' FROM xxotm_idcs_get_token);

             -- Get IDCS User ID dynamically
             l_idcs_user_id := XXOTM_IDCS_GET_USER_ID(l_email, l_access_token);

             IF l_idcs_user_id IS NOT NULL THEN
                 jo_patch := JSON_OBJECT_T();
                 ja_schemas := JSON_ARRAY_T();
                 ja_ops := JSON_ARRAY_T();
                 jo_op_name := JSON_OBJECT_T();

                 ja_schemas.append('urn:ietf:params:scim:api:messages:2.0:PatchOp');

                 jo_op_name.put('op', 'replace');
                 jo_op_name.put('path', 'name.familyName');
                 jo_op_name.put('value', l_new_name); 

                 ja_ops.append(jo_op_name);
                 jo_patch.put('schemas', ja_schemas);
                 jo_patch.put('Operations', ja_ops);
                 l_patch_body := jo_patch.to_clob();

                 apex_web_service.g_request_headers.delete;
                 apex_web_service.g_request_headers(1).name := 'Content-Type';
                 apex_web_service.g_request_headers(1).value := 'application/json';
                 apex_web_service.g_request_headers(2).name := 'Authorization';
                 apex_web_service.g_request_headers(2).value := 'Bearer ' || l_access_token;

                 l_url := 'https://idcs-6cce7520f76c449188e5166f961e3cca.identity.oraclecloud.com/admin/v1/Users/' || l_idcs_user_id;

                  l_response_clob := apex_web_service.make_rest_request(
                    p_url         => l_url,
                    p_http_method => 'PATCH',
                    p_body        => l_patch_body,
                    p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                );

                l_status_code := apex_web_service.g_status_code;

                IF l_status_code NOT BETWEEN 200 AND 299 THEN
                     l_response.put('response_code', l_status_code);
                     -- Limit error message size to avoid JSON issues
                     l_response.put('response_message', 'Failed to update IDCS: ' || DBMS_LOB.SUBSTR(l_response_clob, 200));
                     GOTO output_json;
                END IF;

                UPDATE XX_USER_CONFIG SET NAME = l_new_name WHERE ID = l_user_id;
             END IF;
        END IF;
    END IF;

    -- 2. Handle Is Active
    IF l_json_obj.has('is_active') AND l_json_obj.get_string('is_active') <> l_current_active_status THEN
        l_is_active_bool := l_json_obj.get_boolean('is_active');
        IF l_is_active_bool THEN
            l_is_active_val := 'Y';
        ELSE
            l_is_active_val := 'N';
        END IF;
        UPDATE XX_USER_CONFIG SET IS_ACTIVE = l_is_active_val WHERE ID = l_user_id;
    END IF;

    -- 3. Handle Primary Role
    l_primary_role := l_json_obj.get_string('primary_role');
    IF l_json_obj.has('primary_role') AND l_json_obj.get_string('primary_role') <> l_current_role THEN
        UPDATE XX_USER_CONFIG SET ROLE = l_primary_role WHERE ID = l_user_id;
        UPDATE XX_USER_ROLE_ASSIGNMENT SET IS_ACTIVE = 'Y', LAST_UPDATE_DATE = SYSDATE, LAST_UPDATED_BY = 'API' WHERE USER_ID = l_user_id AND ROLE_CODE = l_primary_role;
    END IF;

    -- 4. Handle Assigned Roles
    IF l_json_obj.has('assigned_roles') THEN
        l_assigned_roles := l_json_obj.get_array('assigned_roles');

        -- Deactivate all roles for this user first
        UPDATE XX_USER_ROLE_ASSIGNMENT SET IS_ACTIVE = 'N' WHERE USER_ID = l_user_id AND ROLE_CODE <> l_primary_role;

        FOR i IN 0 .. l_assigned_roles.get_size - 1 LOOP
             l_role_node := l_assigned_roles.get(i);
             l_role_code := l_role_node.to_string(); 
             -- Clean quotes if string or scalar
             l_role_code := TRIM(BOTH '"' FROM l_role_code);

             SELECT count(*) INTO l_count FROM XX_USER_ROLE_ASSIGNMENT 
              WHERE USER_ID = l_user_id AND ROLE_CODE = l_role_code;

             IF l_count > 0 THEN
                UPDATE XX_USER_ROLE_ASSIGNMENT 
                   SET IS_ACTIVE = 'Y', LAST_UPDATE_DATE = SYSDATE, LAST_UPDATED_BY = 'API'
                 WHERE USER_ID = l_user_id AND ROLE_CODE = l_role_code;
             ELSE
                INSERT INTO XX_USER_ROLE_ASSIGNMENT (ASSIGNMENT_ID, USER_ID, ROLE_CODE, IS_ACTIVE, CREATION_DATE, CREATED_BY)
                VALUES (XX_USER_ROLE_ASSIGNMENT_ID_SEQ.NEXTVAL, l_user_id, l_role_code, 'Y', SYSDATE, 'API');
             END IF;
        END LOOP;
    END IF;

    COMMIT;

    l_response.put('response_code', 200);
    l_response.put('response_message', 'User updated successfully');

<<output_json>>
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', l_response.get('response_code').to_number());
    APEX_JSON.WRITE('response_message', l_response.get('response_message').to_string());
    APEX_JSON.CLOSE_OBJECT;

EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    l_err_msg := SQLERRM;
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 500);
    APEX_JSON.WRITE('response_message', 'Internal Error: ' || l_err_msg);
    APEX_JSON.CLOSE_OBJECT;
END;

   -- ========================================================================
   -- XX_OTM_ASSIGN_TASK_TO_OPERATOR   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_ASSIGN_TASK_TO_OPERATOR.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_assign_task_to_operator (
   p_body in blob,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   l_clob          clob;
   l_shipment_nbr  varchar2(100);
   l_operator      varchar2(100);
   l_exists        number;
   l_response_msg  varchar2(200);
   l_response_code number := 200;
   l_event_ts      varchar2(100);
   l_api_response  clob;
   l_shipment_name  varchar2(100);
   l_container_nbr  varchar2(100);

    
    -- Blob conversion
   l_dest_offset   integer := 1;
   l_src_offset    integer := 1;
   l_lang_context  integer := dbms_lob.default_lang_ctx;
   l_warning       integer;
begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Convert BLOB to CLOB
   if p_body is not null then
      dbms_lob.createtemporary(
         l_clob,
         true
      );
      dbms_lob.converttoclob(
         dest_lob     => l_clob,
         src_blob     => p_body,
         amount       => dbms_lob.lobmaxsize,
         dest_offset  => l_dest_offset,
         src_offset   => l_src_offset,
         blob_csid    => dbms_lob.default_csid,
         lang_context => l_lang_context,
         warning      => l_warning
      );
   else
      l_clob := empty_clob();
   end if;
    
    -- Parse JSON
   apex_json.parse(l_clob);
   l_shipment_nbr := apex_json.get_varchar2('shipment_nbr');
   l_operator := apex_json.get_varchar2('operator');
   l_shipment_name :=  apex_json.get_varchar2('shipment_name');
    l_container_nbr :=  apex_json.get_varchar2('container_nbr');
   
   -- Generate ISO timestamp
   l_event_ts := to_char(
      sys_extract_utc(systimestamp),
      'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
   );
    
    -- Check if record exists in task assignment table
   select count(*)
     into l_exists
     from xxotm_task_assignment_t
    where shipment_nbr = l_shipment_nbr
      and xxotm_task_assignment_t.location = v_location;

   if l_exists > 0 then
        -- Update existing record
      update xxotm_task_assignment_t
         set operator = l_operator,
             assigned_date = l_event_ts
       where shipment_nbr = l_shipment_nbr
         and xxotm_task_assignment_t.location = v_location;

      l_response_msg := 'Task updated successfully';
   else
        -- Insert new record with status as null
      insert into xxotm_task_assignment_t (
         shipment_nbr,
         operator,
         status,
         assigned_date,
         location
      ) values ( l_shipment_nbr,
                 l_operator,
                 null,
                 l_event_ts,
                 v_location );

      l_response_msg := 'Task assigned successfully';
   end if;

   -- Send tracking event to OTM
   BEGIN
	   IF upper(l_shipment_name) IN ('CROSS_STUFFING', 'STUFFING') THEN 
      	 post_otm_tracking_events(
         p_integration_name => 'XX_OTM_ASSIGN_TASK',
         p_statuscodegid    => 'NAQLEEN.TASK_ASSIGNED',
         p_shipmentxid      => l_shipment_nbr,
         p_attribute3		=> l_container_nbr,
         x_response         => l_api_response
      );
	   ELSE
	   post_otm_tracking_events(
         p_integration_name => 'XX_OTM_ASSIGN_TASK',
         p_statuscodegid    => 'NAQLEEN.TASK_ASSIGNED',
         p_shipmentxid      => l_shipment_nbr,
         x_response         => l_api_response
      );
		END IF;
      if l_api_response like 'Error%' then
         -- Log error but don't fail the whole procedure
         null;
      end if;
   exception
      when others then
         null;
   end;

   commit;

   -- AUDIT. Assignment is a people decision, not a yard movement -- who gave
   -- which shipment to which operator is exactly what this table is for. The
   -- operator is the secondary id so "everything assigned to X" is one index
   -- lookup.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'TASK_ASSIGNMENT',
      p_procedure_name => 'XX_OTM_ASSIGN_TASK_TO_OPERATOR',
      p_action         => case when l_exists > 0 then 'REASSIGN' else 'ASSIGN' end,
      p_entity_type    => 'SHIPMENT',
      p_entity_id      => l_shipment_nbr,
      p_secondary_id   => l_operator,
      p_response_code  => 200,
      p_message        => l_response_msg,
      p_location       => v_location);

    -- Clean up CLOB
   if dbms_lob.istemporary(l_clob) = 1 then
      dbms_lob.freetemporary(l_clob);
   end if;

    -- Generate response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      l_response_msg
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      rollback;
      if dbms_lob.istemporary(l_clob) = 1 then
         dbms_lob.freetemporary(l_clob);
      end if;

      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'TASK_ASSIGNMENT',
         p_procedure_name => 'XX_OTM_ASSIGN_TASK_TO_OPERATOR',
         p_action         => 'ASSIGN',
         p_entity_type    => 'SHIPMENT',
         p_entity_id      => l_shipment_nbr,
         p_secondary_id   => l_operator,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);

      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_assign_task_to_operator;

   -- ========================================================================
   -- XX_OTM_BUILD_DOC_JSON   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_BUILD_DOC_JSON.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_build_doc_json (
   p_documentxid      in varchar2,
   p_documentfilename in varchar2,
   p_ownerobjectgid   in varchar2,
   p_clobcontent      in clob,
   p_documentmimetype in varchar2,
   x_json_output      out clob
)
as
begin
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- Top-level fields
   apex_json.write(
      'documentXid',
      p_documentxid
   );
   apex_json.write(
      'documentDefGid',
      'NAQLEEN.POD'
   );
   apex_json.write(
      'documentType',
      'BLOB'
   );
   apex_json.write(
      'documentMimeType',
      p_documentmimetype
   );
   apex_json.write(
      'documentFilename',
      p_documentfilename
   );
   apex_json.write(
      'ownerDataQueryTypeGid',
      'SHIPMENT'
   );
   apex_json.write(
      'ownerObjectGid',
      p_ownerobjectgid
   );
   apex_json.write(
      'domainName',
      'NAQLEEN'
   );
   apex_json.write(
      'usedAs',
      'I'
   );
   apex_json.write(
      'documentCmsId',
      'NAQLEEN.' || p_documentxid
   );

    -- Contents Object
   apex_json.open_object('contents');
   apex_json.open_array('items');

    -- Item Object
   apex_json.open_object;
   apex_json.write(
      'domainName',
      'NAQLEEN'
   );
   apex_json.write(
      'clobContent',
      p_clobcontent
   );
   apex_json.close_object; 

   apex_json.close_array;
   apex_json.close_object; 

   apex_json.close_object; 

   x_json_output := apex_json.get_clob_output;
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      raise;
end xx_otm_build_doc_json;

   -- ========================================================================
   -- XX_OTM_DELETE_SHIPMENT_FROM_STAGING   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_DELETE_SHIPMENT_FROM_STAGING.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_delete_shipment_from_staging (
   p_shipment_nbr IN  VARCHAR2 DEFAULT NULL,
   p_order_id     IN  VARCHAR2 DEFAULT NULL,
   x_log          OUT CLOB
)
AS
   -- Created Date : 02-Jan-2026
   -- Description  : Flexible helper to delete shipment data from staging tables.
   --                Checks OTM via Query API (attribute1=TERMINAL, perspective=B).
   --                Accepts either Shipment ID or Order ID.

   l_url                  VARCHAR2(1000);
   l_response_clob        CLOB;
   l_count                NUMBER;
   l_credential_static_id VARCHAR2(20) := 'OTM_API_AUTH';
   l_order_release_xid    VARCHAR2(200) := p_order_id;
   
   -- Cursor to find all shipments tied to the order
   CURSOR c_siblings (p_order_id_in VARCHAR2) IS
      SELECT DISTINCT shipment_xid
        FROM xxotm_order_movements_t
       WHERE order_release_xid = p_order_id_in
         AND shipment_xid IS NOT NULL;

   -- Cursor to find all order movements tied to the order
   CURSOR c_order_movements (p_order_id_in VARCHAR2) IS
      SELECT DISTINCT order_movement_xid
        FROM xxotm_order_movements_t
       WHERE order_release_xid = p_order_id_in
         AND order_movement_xid IS NOT NULL;

   -- Helper procedure to append to our log
   PROCEDURE log_msg(p_msg IN VARCHAR2) IS
   BEGIN
      DBMS_OUTPUT.PUT_LINE(p_msg);
      -- Append to x_log with a newline
      x_log := x_log || TO_CLOB(TO_CHAR(SYSTIMESTAMP, 'HH24:MI:SS.FF2') || ' - ' || p_msg || CHR(10));
   END log_msg;

BEGIN
   -- Initialize the output log parameter
   DBMS_LOB.CREATETEMPORARY(x_log, TRUE);
   
   log_msg('--- FLEXIBLE DELETION DEBUG START ---');
   
   -- 1. Resolve Order ID if not provided
   IF l_order_release_xid IS NULL AND p_shipment_nbr IS NOT NULL THEN
      BEGIN
         log_msg('Attempting to resolve Order ID from shipment: ' || p_shipment_nbr);
         
         SELECT order_release_xid
           INTO l_order_release_xid
           FROM xxotm_order_movements_t
          WHERE shipment_xid = p_shipment_nbr
            AND ROWNUM = 1;
            
         log_msg('Resolved Order ID: ' || l_order_release_xid);
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            l_order_release_xid := NULL;
            log_msg('No Order ID found for shipment: ' || p_shipment_nbr);
      END;
   END IF;

   -- 2. Process by Order Release (Batch verification)
   IF l_order_release_xid IS NOT NULL THEN
      log_msg('Processing by Order Release: ' || l_order_release_xid);
      
      -- 2A. Process Shipments
      FOR r IN c_siblings(l_order_release_xid) LOOP
         log_msg('Verifying sibling shipment: ' || r.shipment_xid);
         
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                  || '?q=attribute1 eq "TERMINAL" and perspective eq "B" and shipmentXid eq "'
                  || r.shipment_xid || '"';
        
         BEGIN
            log_msg('Calling OTM API Endpoint: ' || l_url);
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_url,
               p_http_method          => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
            
            apex_json.parse(l_response_clob);
            l_count := apex_json.get_number('count');
            log_msg('OTM API Count: ' || l_count);
         EXCEPTION
            WHEN OTHERS THEN
               l_count := 1;
               log_msg('Error calling OTM API: ' || SQLERRM);
         END;

         IF NVL(l_count, 1) = 0 THEN
            log_msg('Confirmed missing in OTM. Deleting shipment ' || r.shipment_xid || '...');
            
            DELETE FROM xxotm_shipments_t WHERE shipment_xid = r.shipment_xid;
            DELETE FROM xxotm_container_inventory_t WHERE inbound_shipment_nbr = r.shipment_xid;
            DELETE FROM xxotm_vehicle_master_t WHERE shipment_nbr LIKE '%'||r.shipment_xid||'%';
            
            UPDATE xxotm_container_inventory_t SET outbound_shipment_nbr = NULL WHERE outbound_shipment_nbr = r.shipment_xid;
             
            DELETE FROM xxotm_task_assignment_t WHERE shipment_nbr = r.shipment_xid;
            DELETE FROM xxotm_order_movements_t WHERE shipment_xid = r.shipment_xid;

            UPDATE xxotm_position_master_t
               SET shipment_nbr = NULL,
                   container_nbr = NULL,
                   is_occupied = 'N',
                   last_event_time = SYSTIMESTAMP,
                   last_event_source = r.shipment_xid || ' SHIPMENT_DELETED'
             WHERE shipment_nbr = r.shipment_xid;
                  
            IF SQL%ROWCOUNT > 0 THEN 
               INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id) 
               VALUES ('SHIPMENT_DELETED', 'INFO', 'Freed position master for shipment: ' || r.shipment_xid, r.shipment_xid);
            END IF;
      
            log_msg('Deletion complete for shipment: ' || r.shipment_xid);
         ELSE
             log_msg('Shipment ' || r.shipment_xid || ' found in OTM. Skipping deletion.');
         END IF;
      END LOOP;

      -- 2B. Process Order Movements
      FOR om IN c_order_movements(l_order_release_xid) LOOP
         log_msg('Verifying order movement: ' || om.order_movement_xid);
         
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/orderMovements/'
                  || '?q=orderMovementXid eq "' || om.order_movement_xid || '"';
        
         BEGIN
            log_msg('Calling OTM API Endpoint: ' || l_url);
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_url,
               p_http_method          => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
            
            apex_json.parse(l_response_clob);
            l_count := apex_json.get_number('count');
            log_msg('OTM API Count for Order Movement: ' || l_count);
         EXCEPTION
            WHEN OTHERS THEN
               l_count := 1;
               log_msg('Error calling OTM API for Order Movement: ' || SQLERRM);
         END;

         IF NVL(l_count, 1) = 0 THEN
            log_msg('Confirmed missing in OTM. Deleting order movement ' || om.order_movement_xid || '...');
            
            DELETE FROM xxotm_order_movements_t WHERE order_movement_xid = om.order_movement_xid;
            
            -- Only clean up the full order data if the movement goes away
            DELETE FROM xxotm_container_inventory_t WHERE inbound_order_nbr = l_order_release_xid;
            UPDATE xxotm_container_inventory_t SET outbound_order_nbr = NULL WHERE outbound_order_nbr = l_order_release_xid;

            log_msg('Deletion complete for order movement: ' || om.order_movement_xid);
         ELSE
             log_msg('Order movement ' || om.order_movement_xid || ' found in OTM. Skipping deletion.');
         END IF;
      END LOOP;

      COMMIT;

   -- 3. Process standalone shipment if no order ID linked
   ELSIF p_shipment_nbr IS NOT NULL THEN
      log_msg('Processing Standalone Shipment: ' || p_shipment_nbr);
      l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
               || '?q=attribute1 eq "TERMINAL" and perspective eq "B" and shipmentXid eq "'
               || p_shipment_nbr || '"';
     
      BEGIN
         log_msg('Calling OTM API Endpoint: ' || l_url);
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
         
         apex_json.parse(l_response_clob);
         l_count := apex_json.get_number('count');
         log_msg('OTM API Count: ' || l_count);
      EXCEPTION
         WHEN OTHERS THEN
            l_count := 1;
            log_msg('Error calling OTM API: ' || SQLERRM);
      END;

      IF NVL(l_count, 1) = 0 THEN
         log_msg('Confirmed missing in OTM. Deleting standalone shipment ' || p_shipment_nbr || '...');
         
         DELETE FROM xxotm_shipments_t WHERE shipment_xid = p_shipment_nbr;
         DELETE FROM xxotm_container_inventory_t WHERE inbound_shipment_nbr = p_shipment_nbr;
         DELETE FROM xxotm_task_assignment_t WHERE shipment_nbr = p_shipment_nbr;
         DELETE FROM xxotm_order_movements_t WHERE shipment_xid = p_shipment_nbr;
          
         COMMIT;
         log_msg('Deletion complete for standalone shipment.');
      ELSE
         log_msg('Standalone shipment ' || p_shipment_nbr || ' found in OTM. Skipping deletion.');
      END IF;
   END IF;

   log_msg('--- FLEXIBLE DELETION DEBUG END ---');

EXCEPTION
   WHEN OTHERS THEN
      ROLLBACK;
      -- Ensure we capture any hard errors alongside the stack
      log_msg('CRITICAL ERROR: ' || SQLERRM || ' - ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
END xx_otm_delete_shipment_from_staging;

   -- ========================================================================
   -- XX_OTM_FETCH_CFS_HISTORY_SHIPMENTS   [4-test-only / PORT+FIX]
   -- source: db/work/XX_OTM_FETCH_CFS_HISTORY_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_fetch_cfs_history_shipments (
   p_booking_nbr  in varchar2 default null,
   p_fetch_type   in varchar2, -- 'SHIPMENTS' or 'DETAILS'
   p_shipment_nbr in varchar2 default null,
   p_user_id      in varchar2 default null
)
as

   -- Was: xx_get_user_location(10) -- a hardcoded user id, so EVERY caller of
   -- CFS history was served user 10's depot regardless of their own. Present in
   -- the 18-May backup too, so it had been live for a long time. Now resolved
   -- from the real caller, which also means the ORDS handler must start binding
   -- p_user_id => :userId (Stage 6).
   v_location         varchar2(100);
   l_response_code    number := 200;
   l_response_message varchar2(200) := 'Success';
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      l_response_code
   );
   apex_json.write(
      'response_message',
      l_response_message
   );
   apex_json.open_array('data');
   if p_fetch_type = 'SHIPMENTS' then
        -- Option 1: Fetch list of shipments based on the booking number
        -- Assuming container_nbr might be null or derived conditionally. Using COALESCE from container or customer inventory.
      for r in (
         select distinct c.shipment_nbr,
                         c.shipment_name,
                         c.cust_name,
                         c.cust_nbr,
                   -- Try to get container_nbr from container inventory table if present
                         cont.container_nbr,
                         cont.booking_id
           from xxotm_customer_inventory_t c
           left join xxotm_container_inventory_t cont
         on c.shipment_nbr = cont.inbound_shipment_nbr
        and cont.location = v_location
          where ( upper(cont.booking_id) like '%'
                                              || upper(p_booking_nbr)
                                              || '%'
         or upper(cont.inbound_shipment_nbr) like '%'
                                                  || upper(p_booking_nbr)
                                                  || '%' )
            and c.location = v_location
          order by c.shipment_name
      ) loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            r.shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            r.shipment_name
         );
         apex_json.write(
            'container_number',
            r.container_nbr
         );
         apex_json.write(
            'customer_name',
            r.cust_name
         );
         apex_json.write(
            'customer_number',
            r.cust_nbr
         );
         apex_json.write(
            'booking_number',
            r.booking_id
         );
         apex_json.close_object;
      end loop;
   elsif p_fetch_type = 'DETAILS' then
        -- Option 2: Fetch the particular shipment items and details
        -- p_shipment_nbr is expected to be passed to get specific details
      if p_shipment_nbr is null then
            -- Close array to prepare for error throwing gracefully
         apex_json.close_array;
         apex_json.close_object;
         return;
      end if;
      declare
         v_header_written boolean := false;
      begin
         for r in (
            select c.shipment_nbr,
                   c.shipment_name,
                   c.cust_name,
                   c.cust_nbr,
                   cont.container_nbr,
                   c.creation_date,
                   c.item_code,
                   c.item_description,
                   c.qty,
                   c.qty_uom,
                   c.location,
                   cont.container_type
              from xxotm_customer_inventory_t c
              left join xxotm_container_inventory_t cont
            on c.shipment_nbr = cont.inbound_shipment_nbr
           and cont.location = v_location
             where c.shipment_nbr = p_shipment_nbr
               and c.location = v_location
         ) loop
            if not v_header_written then
               apex_json.open_object;
               apex_json.write(
                  'shipment_nbr',
                  r.shipment_nbr
               );
               apex_json.write(
                  'cust_name',
                  r.cust_name
               );
               apex_json.write(
                  'shipment_name',
                  r.shipment_name
               );
               apex_json.write(
                  'container_nbr',
                  r.container_nbr
               );
               apex_json.write(
                  'creation_date',
                 
                     r.creation_date
                 
               );
               apex_json.open_array('items');
               v_header_written := true;
            end if;

            apex_json.open_object;
            apex_json.write(
               'item_code',
               r.item_code
            );
            apex_json.write(
               'item_description',
               r.item_description
            );
            apex_json.write(
               'quantity',
               r.qty
            );
            apex_json.write(
               'uom',
               r.qty_uom
            );
            apex_json.write(
               'customer_name',
               r.cust_name
            );
            apex_json.write(
               'customer_number',
               r.cust_nbr
            );
         
            apex_json.close_object;
         end loop;

         if v_header_written then
            apex_json.close_array; -- items
            apex_json.close_object; -- single array element
         end if;
      end;
   end if;

   apex_json.close_array;
   apex_json.close_object;
exception
   when others then
      l_response_code := 500;
      l_response_message := 'Unexpected error: ' || sqlerrm;
        
        -- Try to close out gracefully and return error JSON.
        -- stringify() quotes AND escapes: l_response_message carries SQLERRM,
        -- and Oracle error text routinely contains a " (object names, literals),
        -- which interpolated raw would produce invalid JSON even with the outer
        -- quotes restored.
        -- NOTE: apex_json here writes straight to the HTP buffer (this procedure
        -- never calls initialize_clob_output), so on a mid-stream failure this
        -- error object is APPENDED to a partially written document. Pre-existing,
        -- inherited from test's body; left alone rather than widened here.
      htp.p('{"response_code": 500, "response_message": '
            || apex_json.stringify(l_response_message)
            || ', "data": []}');
end xx_otm_fetch_cfs_history_shipments;

   -- ========================================================================
   -- XX_OTM_GATE_OUT_TRUCK_DETAILS   [3d-high-risk / TAKE-TEST + prod creds]
   -- source: db/work/XX_OTM_GATE_OUT_TRUCK_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_gate_out_truck_details (
   p_truck_nbr in varchar2,
   p_user_id   in varchar2 default null
)
as

-- Last Updated Date : 23-Feb-2026
    -- Last Updated By : Assistant
    -- Description : Fetch gate-out shipments. Checks VM -> DB -> API (attribute7) as fallbacks.
    --               After VM pass, DB pass now supplements remaining slots (up to 2 total).
    -- Declared bare and assigned after BEGIN. As an initialiser, any failure in
    -- xx_get_user_location would escape this block's own exception handler and
    -- ORDS would return a raw Oracle stack instead of the JSON envelope.
    v_location varchar2(100);

   l_url              varchar2(4000);
   l_search_url       varchar2(4000);
   l_q                varchar2(4000);   -- PASS 3 filter, built then escaped
   l_response_clob    clob;
   l_found_count      number := 0;
   
   type t_shipment_rec is record (
      shipment_nbr     varchar2(100),
      shipment_type    varchar2(100),
      container_nbr    varchar2(100),
      container_type   varchar2(100),
      order_nbr        varchar2(100),
      customer_name    varchar2(100)
   );
   type t_shipment_tab is table of t_shipment_rec index by pls_integer;
   l_shipments        t_shipment_tab;
   
   l_driver_name      varchar2(100);
   l_driver_iqama_nbr varchar2(100);
   l_order_type       varchar2(100);
   l_vm_shipments_str varchar2(4000);

   l_events_count         number;
   l_statuses_count       number;
   l_status_code          varchar2(200);
   l_status_value_gid     varchar2(200);

   l_has_gate_in          boolean;
   l_has_gate_out         boolean;
   l_work_complete        boolean;
   l_is_trip_completed    boolean;
   
   type t_string_table is table of varchar2(100) index by pls_integer;
   l_vm_target_shipments t_string_table;
   l_db_target_shipments t_string_table;
   
   l_target_shipment_xid varchar2(200);
   l_idx    number := 1;
   l_db_idx number := 1;
   l_api_shipments_count number;

    cursor c_shipments is
    select s.shipment_xid, 
            s.shipment_name,
            s.customer_name,          
            s.cont_no,
            s.container_type,
            o.order_release_xid
        from xxotm_shipments_t s
    left join xxotm_order_movements_t o 
        on s.shipment_xid = o.shipment_xid
        where s.truck_3pl = p_truck_nbr 
        and s.location = v_location
        order by s.update_date desc;


begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   dbms_output.put_line('--------------------------------------------------');
   dbms_output.put_line('START: Fetch Gate Out Shipments for Truck: ' || p_truck_nbr);
   
   apex_json.initialize_clob_output;
   apex_json.open_object;

   -- 1. Get Driver Details and Vehicle Master Shipments
   dbms_output.put_line('1. Fetching details from xxotm_vehicle_master_t...');
   begin
      select driver_name, driver_iqama, order_type, shipment_nbr
        into l_driver_name, l_driver_iqama_nbr, l_order_type, l_vm_shipments_str
        from xxotm_vehicle_master_t
       where truck_nbr = p_truck_nbr and exit_time is null and xxotm_vehicle_master_t.location = v_location
         and rownum = 1;
      dbms_output.put_line('   -> Driver Name: ' || l_driver_name);
      dbms_output.put_line('   -> Driver Iqama: ' || l_driver_iqama_nbr);
      dbms_output.put_line('   -> Order Type: ' || l_order_type);
      dbms_output.put_line('   -> VM Shipments Str: ' || nvl(l_vm_shipments_str, 'NULL'));
   exception
      when no_data_found then
         dbms_output.put_line('   -> NO DATA FOUND in vehicle_master_t or exit_time is not NULL.');
   end;

   -- 2. Build target shipment lists
   dbms_output.put_line('2. Building target shipments lists...');
   if l_vm_shipments_str is not null then
      dbms_output.put_line('   -> Parsing comma-separated shipments from Vehicle Master...');
      for c in (
         select regexp_substr(l_vm_shipments_str, '[^,]+', 1, level) as val 
         from dual 
         connect by regexp_substr(l_vm_shipments_str, '[^,]+', 1, level) is not null
      ) loop
         l_vm_target_shipments(l_idx) := trim(c.val);
         dbms_output.put_line('      -> Added VM: ' || l_vm_target_shipments(l_idx));
         l_idx := l_idx + 1;
      end loop;
   end if;

   dbms_output.put_line('   -> Getting assigned shipments from xxotm_shipments_t...');
   for r in c_shipments loop
      l_db_target_shipments(l_db_idx) := r.shipment_xid;
      dbms_output.put_line('      -> Added DB: ' || l_db_target_shipments(l_db_idx));
      l_db_idx := l_db_idx + 1;
   end loop;

   -- 3. Validate Shipments
   dbms_output.put_line('3. Starting Shipment Evaluation...');

   -- PASS 1: Evaluate Vehicle Master Shipments
   if l_vm_target_shipments.count > 0 then
      dbms_output.put_line('   -> PASS 1: Evaluating Vehicle Master Shipments...');
      for i in 1..l_vm_target_shipments.count loop
         l_target_shipment_xid := l_vm_target_shipments(i);
         dbms_output.put_line('   --- Evaluating Shipment (VM): ' || l_target_shipment_xid || ' ---');
         
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                  || l_target_shipment_xid
                  || '?expand=trackingEvents,statuses';
         
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name  := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         
         begin
            dbms_output.put_line('   -> URL: ' || l_url);
            l_response_clob := apex_web_service.make_rest_request(
               p_url          => l_url,
               p_http_method  => 'GET',
               p_credential_static_id => 'OTM_API_AUTH',
               p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
            );
            dbms_output.put_line('   -> HTTP Status Code: ' || apex_web_service.g_status_code);
   
            l_has_gate_in       := false;
            l_has_gate_out      := false;
            l_work_complete     := false;
            l_is_trip_completed := false;
   
            if apex_web_service.g_status_code = 200 then
               apex_json.parse(l_response_clob);
               l_events_count := nvl(apex_json.get_count('trackingEvents.items'), 0);
               dbms_output.put_line('   -> Tracking Events Count: ' || l_events_count);
               for k in 1..l_events_count loop
                  l_status_code := apex_json.get_varchar2('trackingEvents.items[%d].statusCodeGid', k);
                  if instr(l_status_code, 'GATE OUT') > 0 then l_has_gate_out := true; end if;
                  if instr(l_status_code, 'GATE IN') > 0 then l_has_gate_in := true; end if;
                  if instr(l_status_code, 'CONTAINER STORED') > 0
                     or instr(l_status_code, 'CONTAINER RELEASED') > 0
                     or instr(l_status_code, 'STUFFED') > 0
                     or instr(l_status_code, 'DESTUFFED') > 0 then
                     l_work_complete := true;
                  end if;
               end loop;
      
               declare
                  tmp_shipment_name varchar2(100);
                  tmp_cont_no       varchar2(100); 
                  tmp_cont_type     varchar2(100);
                  tmp_customer_name varchar2(100);
                  tmp_order_nbr     varchar2(100);
               begin
                  tmp_shipment_name := apex_json.get_varchar2('shipmentName');
                  dbms_output.put_line('   -> API Shipment Name: ' || tmp_shipment_name);
                  begin
                     select s.cont_no, s.container_type, s.customer_name, o.ORDER_RELEASE_XID
                       into tmp_cont_no, tmp_cont_type, tmp_customer_name, tmp_order_nbr
                       from xxotm_shipments_t s left join xxotm_order_movements_t o on s.shipment_xid = o.shipment_xid
                      where s.shipment_xid = l_target_shipment_xid and rownum = 1
                      and s.location = v_location;
                  exception when no_data_found then dbms_output.put_line('      -> Warning: Shipment details missing from xxotm_shipments_t.'); end;
      
                  if not l_work_complete then
                     l_statuses_count := nvl(apex_json.get_count('statuses.items'), 0);
                     dbms_output.put_line('   -> Checking statuses (Count: ' || l_statuses_count || ')');
                     for m in 1..l_statuses_count loop
                        l_status_code      := apex_json.get_varchar2('statuses.items[%d].statusTypeGid', m);
                        l_status_value_gid := apex_json.get_varchar2('statuses.items[%d].statusValueGid', m);
                        if instr(l_status_code, 'NAQLEEN.TRIP_STATUS') > 0 and instr(l_status_value_gid, 'NAQLEEN.TRIP_COMPLETED') > 0 then
                           l_is_trip_completed := true;
                           dbms_output.put_line('      -> Found NAQLEEN.TRIP_COMPLETED status.');
                           exit;
                        end if;
                     end loop;
                     if l_is_trip_completed and tmp_shipment_name in ('OFFLOADING_LCL', 'LOADING_LCL') then
                        l_work_complete := true;
                     end if;
                  end if;
                  
                  dbms_output.put_line('   -> Summary: GATE_IN=' || case when l_has_gate_in then 'Y' else 'N' end || 
                                       ', GATE_OUT=' || case when l_has_gate_out then 'Y' else 'N' end ||
                                       ', WORK_COMPLETE=' || case when l_work_complete then 'Y' else 'N' end);
                  if l_has_gate_in and not l_has_gate_out and l_work_complete then
                     dbms_output.put_line('   => Candidate Shipment passed criteria!');
                     if l_found_count = 1 then
                        if tmp_shipment_name != l_shipments(1).shipment_type then
                           dbms_output.put_line('   => SKIPPING: Type mismatch.');
                           goto skip_shipment_vm;
                        end if;
                     end if;
                     l_found_count := l_found_count + 1;
                     l_shipments(l_found_count).shipment_nbr   := l_target_shipment_xid;
                     l_shipments(l_found_count).shipment_type  := tmp_shipment_name;
                     l_shipments(l_found_count).container_nbr  := tmp_cont_no;
                     l_shipments(l_found_count).container_type := tmp_cont_type;
                     l_shipments(l_found_count).order_nbr      := tmp_order_nbr;
                     l_shipments(l_found_count).customer_name  := tmp_customer_name;
                     dbms_output.put_line('   => ADDED (Count: ' || l_found_count || ')');
                     if l_found_count = 2 then goto generate_response; end if;
                     <<skip_shipment_vm>> null;
                  else
                     dbms_output.put_line('   => Criteria check failed.');
                  end if;
               end;
            else
               dbms_output.put_line('   -> Warning: API returned non-200 code: ' || apex_web_service.g_status_code);
            end if;
         exception when others then dbms_output.put_line('   -> ERROR: ' || sqlerrm); end;
      end loop;
   end if;

   -- ============================================================
   -- PASS 2: Supplement from DB shipments if fewer than 2 found
   -- (Previously only ran when l_found_count = 0 — now fills up to 2)
   -- ============================================================
   if l_found_count < 2 and l_db_target_shipments.count > 0 then
      dbms_output.put_line('   -> PASS 2: VM yielded ' || l_found_count || ' result(s). Checking DB Shipments for additional...');
      
      for i in 1..l_db_target_shipments.count loop
         l_target_shipment_xid := l_db_target_shipments(i);
         
         -- Skip shipments already added from PASS 1
         declare
            l_already_added boolean := false;
         begin
            for j in 1..l_found_count loop
               if l_shipments(j).shipment_nbr = l_target_shipment_xid then
                  l_already_added := true;
                  exit;
               end if;
            end loop;
            if l_already_added then
               dbms_output.put_line('   --- Skipping (already added in PASS 1): ' || l_target_shipment_xid || ' ---');
               goto skip_db_duplicate;
            end if;
         end;

         dbms_output.put_line('   --- Evaluating Shipment (DB): ' || l_target_shipment_xid || ' ---');
         
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                  || l_target_shipment_xid
                  || '?expand=trackingEvents,statuses';
         
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name  := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         
         begin
            dbms_output.put_line('   -> URL: ' || l_url);
            l_response_clob := apex_web_service.make_rest_request(
               p_url          => l_url,
               p_http_method  => 'GET',
               p_credential_static_id => 'OTM_API_AUTH',
               p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
            );
            dbms_output.put_line('   -> HTTP Status Code: ' || apex_web_service.g_status_code);
   
            l_has_gate_in       := false;
            l_has_gate_out      := false;
            l_work_complete     := false;
            l_is_trip_completed := false;
   
            if apex_web_service.g_status_code = 200 then
               apex_json.parse(l_response_clob);
               l_events_count := nvl(apex_json.get_count('trackingEvents.items'), 0);
               dbms_output.put_line('   -> Tracking Events Count: ' || l_events_count);
               for k in 1..l_events_count loop
                  l_status_code := apex_json.get_varchar2('trackingEvents.items[%d].statusCodeGid', k);
                  if instr(l_status_code, 'GATE OUT') > 0 then l_has_gate_out := true; end if;
                  if instr(l_status_code, 'GATE IN') > 0 then l_has_gate_in := true; end if;
                  if instr(l_status_code, 'CONTAINER STORED') > 0
                     or instr(l_status_code, 'CONTAINER RELEASED') > 0
                     or instr(l_status_code, 'STUFFED') > 0
                     or instr(l_status_code, 'DESTUFFED') > 0 then
                     l_work_complete := true;
                  end if;
               end loop;
      
               declare
                  tmp_shipment_name varchar2(100);
                  tmp_cont_no       varchar2(100); 
                  tmp_cont_type     varchar2(100);
                  tmp_customer_name varchar2(100);
                  tmp_order_nbr     varchar2(100);
               begin
                  tmp_shipment_name := apex_json.get_varchar2('shipmentName');
                  dbms_output.put_line('   -> API Shipment Name: ' || tmp_shipment_name);
                  begin
                     select s.cont_no, s.container_type, s.customer_name, o.ORDER_RELEASE_XID
                       into tmp_cont_no, tmp_cont_type, tmp_customer_name, tmp_order_nbr
                       from xxotm_shipments_t s left join xxotm_order_movements_t o on s.shipment_xid = o.shipment_xid
                      where s.shipment_xid = l_target_shipment_xid and rownum = 1
                      and s.location = v_location;
                  exception when no_data_found then dbms_output.put_line('      -> Warning: Shipment details missing from xxotm_shipments_t.'); end;
      
                  if not l_work_complete then
                     l_statuses_count := nvl(apex_json.get_count('statuses.items'), 0);
                     dbms_output.put_line('   -> Checking statuses (Count: ' || l_statuses_count || ')');
                     for m in 1..l_statuses_count loop
                        l_status_code      := apex_json.get_varchar2('statuses.items[%d].statusTypeGid', m);
                        l_status_value_gid := apex_json.get_varchar2('statuses.items[%d].statusValueGid', m);
                        if instr(l_status_code, 'NAQLEEN.TRIP_STATUS') > 0 and instr(l_status_value_gid, 'NAQLEEN.TRIP_COMPLETED') > 0 then
                           l_is_trip_completed := true;
                           dbms_output.put_line('      -> Found NAQLEEN.TRIP_COMPLETED status.');
                           exit;
                        end if;
                     end loop;
                     if l_is_trip_completed and tmp_shipment_name in ('OFFLOADING_LCL', 'LOADING_LCL') then
                        l_work_complete := true;
                     end if;
                  end if;
                  
                  dbms_output.put_line('   -> Summary: GATE_IN=' || case when l_has_gate_in then 'Y' else 'N' end || 
                                       ', GATE_OUT=' || case when l_has_gate_out then 'Y' else 'N' end ||
                                       ', WORK_COMPLETE=' || case when l_work_complete then 'Y' else 'N' end);
                  if l_has_gate_in and not l_has_gate_out and l_work_complete then
                     dbms_output.put_line('   => Candidate Shipment passed criteria!');
                     if l_found_count = 1 then
                        if tmp_shipment_name != l_shipments(1).shipment_type then
                           dbms_output.put_line('   => SKIPPING: Type mismatch (' || tmp_shipment_name || ' vs ' || l_shipments(1).shipment_type || ').');
                           goto skip_shipment_db;
                        end if;
                     end if;
                     l_found_count := l_found_count + 1;
                     l_shipments(l_found_count).shipment_nbr   := l_target_shipment_xid;
                     l_shipments(l_found_count).shipment_type  := tmp_shipment_name;
                     l_shipments(l_found_count).container_nbr  := tmp_cont_no;
                     l_shipments(l_found_count).container_type := tmp_cont_type;
                     l_shipments(l_found_count).order_nbr      := tmp_order_nbr;
                     l_shipments(l_found_count).customer_name  := tmp_customer_name;
                     dbms_output.put_line('   => ADDED (Count: ' || l_found_count || ')');
                     if l_found_count = 2 then goto generate_response; end if;
                     <<skip_shipment_db>> null;
                  else
                     dbms_output.put_line('   => Criteria check failed.');
                  end if;
               end;
            else
               dbms_output.put_line('   -> Warning: API returned non-200 code: ' || apex_web_service.g_status_code);
            end if;
         exception when others then dbms_output.put_line('   -> ERROR: ' || sqlerrm); end;

         <<skip_db_duplicate>> null;
      end loop;
   end if;

   -- PASS 3: If still < 2, search via API using truck number in attribute7
   if l_found_count = 0 then
      dbms_output.put_line('   -> All DB passes yielded 0. Checking PASS 3 (API Global Search)...');
      
      -- FIX: the truck number is now QUOTED for OTM's filter language and the
      -- whole filter is percent-encoded for the URL.
      --
      -- Saudi plates contain a space -- this repo's own debug stub hardcodes
      -- '1111 ABH'. Unquoted and unescaped, this built
      --     ?q=(attribute7 eq 1111 ABH) and ...
      -- which is a malformed filter inside a malformed URL, so PASS 3 never
      -- returned anything for a real plate. It is the last-resort recovery path
      -- -- reached only when the vehicle-master row AND the local shipments
      -- table both come up empty -- so it failed at precisely the moment it was
      -- needed, and did so silently: the handler below just logs and falls
      -- through to a 404.
      --
      -- Embedded double quotes are stripped so a crafted truck number cannot
      -- close the quoted value and append its own filter terms.
      -- utl_url.escape(..., TRUE) also escapes reserved characters, which is
      -- correct here because only the VALUE of q= is being escaped, not the URL
      -- around it. Same call shape as prod_functions.sql:83.
      --
      -- v_location is quoted too, matching XX_OTM_GENERATE_EIR and the sync
      -- package; it worked unquoted only because site codes are numeric.
      l_q := '(attribute7 eq "'
             || replace(
         p_truck_nbr,
         '"'
      )
             || '")'
             || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
             || ' and refnums.shipmentRefnumValue eq "'
             || v_location
             || '"';

      l_search_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments'
                      || '?q=' || utl_url.escape(
         l_q,
         true
      )
                      || '&orderBy=insertDate:desc'
                      || '&expand=trackingEvents,statuses';
                      
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name  := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      
      begin
         dbms_output.put_line('   -> Search URL: ' || l_search_url);
         l_response_clob := apex_web_service.make_rest_request(
            p_url          => l_search_url,
            p_http_method  => 'GET',
            p_credential_static_id => 'OTM_API_AUTH',
            p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
         );
         dbms_output.put_line('   -> HTTP Status Code: ' || apex_web_service.g_status_code);
         
         if apex_web_service.g_status_code = 200 then
            apex_json.parse(l_response_clob);
            l_api_shipments_count := nvl(apex_json.get_count('items'), 0);
            dbms_output.put_line('   -> API Search found ' || l_api_shipments_count || ' matching shipments.');
            
            for i in 1..l_api_shipments_count loop
               l_target_shipment_xid := replace(apex_json.get_varchar2('items[%d].shipmentXid', i), 'NAQLEEN.', '');
               dbms_output.put_line('   --- Evaluating Shipment (API): ' || l_target_shipment_xid || ' ---');
               
               l_has_gate_in       := false;
               l_has_gate_out      := false;
               l_work_complete     := false;
               l_is_trip_completed := false;
               
               l_events_count := nvl(apex_json.get_count('items[%d].trackingEvents.items', i), 0);
               dbms_output.put_line('   -> Tracking Events Count: ' || l_events_count);
               for k in 1..l_events_count loop
                  l_status_code := apex_json.get_varchar2('items[%d].trackingEvents.items[%d].statusCodeGid', i, k);
                  if instr(l_status_code, 'GATE OUT') > 0 then l_has_gate_out := true; end if;
                  if instr(l_status_code, 'GATE IN') > 0 then l_has_gate_in := true; end if;
                  if instr(l_status_code, 'CONTAINER STORED') > 0
                     or instr(l_status_code, 'CONTAINER RELEASED') > 0
                     or instr(l_status_code, 'STUFFED') > 0
                     or instr(l_status_code, 'DESTUFFED') > 0 then
                     l_work_complete := true;
                  end if;
               end loop;
      
               declare
                  tmp_shipment_name varchar2(100);
                  tmp_cont_no       varchar2(100); 
                  tmp_cont_type     varchar2(100);
                  tmp_customer_name varchar2(100);
                  tmp_order_nbr     varchar2(100);
               begin
                  tmp_shipment_name := apex_json.get_varchar2('items[%d].shipmentName', i);
                  dbms_output.put_line('   -> API Shipment Name: ' || tmp_shipment_name);
                  begin
                     select s.cont_no, s.container_type, s.customer_name, o.ORDER_RELEASE_XID
                       into tmp_cont_no, tmp_cont_type, tmp_customer_name, tmp_order_nbr
                       from xxotm_shipments_t s left join xxotm_order_movements_t o on s.shipment_xid = o.shipment_xid
                      where s.shipment_xid = l_target_shipment_xid and rownum = 1
                      and s.location = v_location;
                  exception when no_data_found then dbms_output.put_line('      -> Warning: Shipment details missing from xxotm_shipments_t.'); end;
      
                  if not l_work_complete then
                     l_statuses_count := nvl(apex_json.get_count('items[%d].statuses.items', i), 0);
                     for m in 1..l_statuses_count loop
                        l_status_code      := apex_json.get_varchar2('items[%d].statuses.items[%d].statusTypeGid', i, m);
                        l_status_value_gid := apex_json.get_varchar2('items[%d].statuses.items[%d].statusValueGid', i, m);
                        if instr(l_status_code, 'NAQLEEN.TRIP_STATUS') > 0 and instr(l_status_value_gid, 'NAQLEEN.TRIP_COMPLETED') > 0 then
                           l_is_trip_completed := true;
                           exit;
                        end if;
                     end loop;
                     if l_is_trip_completed and tmp_shipment_name in ('OFFLOADING_LCL', 'LOADING_LCL') then
                        l_work_complete := true;
                     end if;
                  end if;
                  
                  dbms_output.put_line('   -> Summary: GATE_IN=' || case when l_has_gate_in then 'Y' else 'N' end || 
                                       ', GATE_OUT=' || case when l_has_gate_out then 'Y' else 'N' end ||
                                       ', WORK_COMPLETE=' || case when l_work_complete then 'Y' else 'N' end);
                  if l_has_gate_in and not l_has_gate_out and l_work_complete then
                     dbms_output.put_line('   => Candidate Shipment passed criteria!');
                     if l_found_count = 1 then
                        if tmp_shipment_name != l_shipments(1).shipment_type then
                           dbms_output.put_line('   => SKIPPING: Type mismatch.');
                           goto skip_shipment_api;
                        end if;
                     end if;
                     l_found_count := l_found_count + 1;
                     l_shipments(l_found_count).shipment_nbr   := l_target_shipment_xid;
                     l_shipments(l_found_count).shipment_type  := tmp_shipment_name;
                     l_shipments(l_found_count).container_nbr  := tmp_cont_no;
                     l_shipments(l_found_count).container_type := tmp_cont_type;
                     l_shipments(l_found_count).order_nbr      := tmp_order_nbr;
                     l_shipments(l_found_count).customer_name  := tmp_customer_name;
                     dbms_output.put_line('   => ADDED (Count: ' || l_found_count || ')');
                     if l_found_count = 2 then goto generate_response; end if;
                     <<skip_shipment_api>> null;
                  else
                     dbms_output.put_line('   => Criteria check failed.');
                  end if;
               end;
            end loop;
         else
            dbms_output.put_line('   -> API Search failed. Status: ' || apex_web_service.g_status_code);
         end if;
      exception
         when others then dbms_output.put_line('   -> ERROR during API search: ' || sqlerrm);
      end;
   end if;

<<generate_response>>
   dbms_output.put_line('4. Constructing Response...');
   if l_found_count > 0 then
      dbms_output.put_line('   -> RETURNING: SUCCESS (200) with ' || l_found_count || ' shipment(s).');
      apex_json.write('response_message', 'Success');
      apex_json.write('response_code', 200);
      apex_json.open_array('data');
      for i in 1..l_found_count loop
         apex_json.open_object;
         apex_json.write('shipment_name',   l_shipments(i).shipment_type);
         apex_json.write('order_nbr',       l_shipments(i).order_nbr);
         apex_json.write('customer_name',   l_shipments(i).customer_name);
         apex_json.write('shipment_nbr',    l_shipments(i).shipment_nbr);
         apex_json.write('container_nbr',   l_shipments(i).container_nbr);
         apex_json.write('container_type',  l_shipments(i).container_type);
         apex_json.write('truck_nbr',       p_truck_nbr);
         apex_json.write('driver_name',     l_driver_name);
         apex_json.write('driver_nbr',      l_driver_iqama_nbr);
         apex_json.write('order_type',      l_order_type);
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      dbms_output.put_line('   -> RETURNING: No Data Found (404).');
      apex_json.write('response_message', 'No Data Found');
      apex_json.write('response_code', 404);
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
   dbms_output.put_line('END: xx_otm_gate_out_truck_details completed smoothly.');

exception
   when others then
      dbms_output.put_line('CRITICAL ERROR: ' || sqlerrm);
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.write('response_code', 500);
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_gate_out_truck_details;

   -- ========================================================================
   -- XX_OTM_GENERATE_EIR   [4-prod-only / KEEP]
   -- source: db/work/XX_OTM_GENERATE_EIR.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_generate_eir (
   p_shipment_nbr in varchar2,
   p_truck_nbr    in varchar2,
   p_remarks      in varchar2 default null,
   p_passed_user  in varchar2 default null,
   p_user_id      in varchar2 default null,   -- MERGE: location scoping
   x_ok           out boolean,
   x_message      out varchar2
)
as

   c_proc           constant varchar2(30) := 'XX_OTM_GENERATE_EIR';
   l_ship           varchar2(100) := replace(
      p_shipment_nbr,
      'NAQLEEN.',
      ''
   );
   l_eir_no         varchar2(50);
   l_pdf            blob;
   l_resp           clob;
   l_container_no   varchar2(200);
   l_container_list varchar2(1000);   -- every container on the truck, comma separated
   l_container_type varchar2(200);
   l_customer_name  varchar2(200);
   l_shipper        varchar2(100);
   l_booking_no     varchar2(100);
   l_source_loc     varchar2(100);
   l_seal_no        varchar2(100);
   l_driver_name    varchar2(240);
   l_shipment_name  varchar2(100);
   l_gate_type      varchar2(30);
   l_serial_no      varchar2(100);    -- '1/2' alone, '1,2/2' with a second container
   l_driver_id      varchar2(100);
   l_truck_ships    varchar2(4000);   -- vehicle master list for this visit
   l_sib_ship       varchar2(100);
   l_sib_container  varchar2(200);
   l_sib_serial     varchar2(100);
   l_ser_num        varchar2(100);    -- numerator(s) sharing one denominator
   l_ser_den        varchar2(30);
   l_ser_extra      varchar2(200);    -- pairs from a sibling on another booking

   -- The other shipments riding on this truck, in the order the vehicle master lists them
   type t_ship_rec is record (
         ship      varchar2(100),
         container varchar2(200),
         booking   varchar2(100)
   );
   type t_ship_tab is
      table of t_ship_rec index by pls_integer;
   l_sibs           t_ship_tab;
   l_sib_rec        t_ship_rec;

   -- On-demand container re-sync (used only when an inventory row has no container)
   -- MERGE: was a hardcoded host plus a plaintext username/password. Now read
   -- from config, and declared BARE rather than as CONSTANTs -- an exception
   -- raised while elaborating a DECLARE-section initialiser is not catchable by
   -- this block's own EXCEPTION handler, so the assignment moved after BEGIN.
   c_or_url         varchar2(300);
   c_or_user        varchar2(50);
   c_or_pwd         varchar2(50);
   -- MERGE: location scoping. Bare, assigned as the first statement after BEGIN.
   v_location       varchar2(100);

   procedure log_it (
      p_type varchar2,
      p_text varchar2
   ) is
      pragma autonomous_transaction;                     -- survives a caller rollback
   begin
      insert into xx_otm_sync_logs (
         procedure_name,
         message_type,
         message_text,
         reference_id,
         log_timestamp
      ) values ( c_proc,
                 p_type,
                 substr(
                    p_text,
                    1,
                    4000
                 ),
                 l_ship,
                 systimestamp );
      commit;
   exception
      when others then
         rollback;
   end;

   -- OTM echoes the created document on success (documentXid, no "status"), and returns
   -- {"status":NNN,...,"o:errorDetails":[...]} on failure. Our own wrappers return plain
   -- text starting with "Error"/"No PDF content", neither of which contains documentXid.
   function upload_ok (
      p_resp clob
   ) return boolean is
      l_head varchar2(1000);
   begin
      if p_resp is null then
         return false;
      end if;
      l_head := dbms_lob.substr(
         p_resp,
         1000
      );
      return
         instr(
            l_head,
            '"documentXid"'
         ) > 0
         and instr(
            l_head,
            'o:errorDetails'
         ) = 0
         and instr(
            l_head,
            '"status"'
         ) = 0;
   end;

   -- Container number for one shipment. Blank usually means the order release reached
   -- our inventory before OTM had a container assigned to it, so pull that single order
   -- back from OTM (attribute3 carries the container nbr) and re-read the row.
   function resolve_container (
      p_ship in varchar2
   ) return varchar2 is
      l_cont  varchar2(200);
      l_order varchar2(100);
   begin
      begin
         select container_nbr,
                order_nbr
           into
            l_cont,
            l_order
           from (
            select ci.container_nbr,
                   ci.inbound_order_nbr as order_nbr
              from xxotm_container_inventory_t ci
             where ci.inbound_shipment_nbr in ( p_ship,
                                                'NAQLEEN.' || p_ship )
             order by ci.container_nbr nulls last
         )
          where rownum = 1;
      exception
         when no_data_found then
            l_cont := null;
            l_order := null;
      end;

      if l_cont is not null then
         return l_cont;
      end if;
      if l_order is null then                          -- no inventory row at all yet
         begin
            select inbound_order_nbr
              into l_order
              from (
               select om.inbound_order_nbr
                 from xxotm_container_inventory_t om
                where om.inbound_shipment_nbr in ( p_ship,
                                                   'NAQLEEN.' || p_ship )
                  and om.inbound_order_nbr is not null
            )
             where rownum = 1;
         exception
            when no_data_found then
               l_order := null;
         end;
      end if;

      if l_order is null then
         log_it(
            'WARN',
            'No OTM order found for shipment '
            || p_ship
            || ' - container left blank'
         );
         return null;
      end if;

      begin
         xx_naqleen_otm_data_sync_pkg.xx_otm_container_inventory_sync(
            c_or_url,
            c_or_user,
            c_or_pwd,
            'q=attribute1 eq "TERMINAL"  and orderReleaseTypeGid in '
            || '["INBOUND_CONTAINER","LRO","CRO","STUFFING","DESTUFFING","STORE_AS_IT_IS",'
            || '"RELEASE_CFS","CFS","CROSS_STUFFING","OFFLOADING_LCL","LOADING_LCL"]  and  '
            || 'refnums.orderReleaseRefnumQualGid eq "NAQLEEN.LOCATION" and '
            || 'refnums.orderReleaseRefnumValue eq "'   -- MERGE: was hardcoded "103"
            || v_location
            || '"  and orderReleaseXid eq "'
            || l_order
            || '" '
            || '&expand=refnums&limit=100'
         );
      exception
         when others then                              -- never block the EIR on a sync
            log_it(
               'WARN',
               'Container re-sync failed for order '
               || l_order
               || ': '
               || sqlerrm
            );
      end;

      begin
         select container_nbr
           into l_cont
           from (
            select ci.container_nbr
              from xxotm_container_inventory_t ci
             where ci.inbound_shipment_nbr in ( p_ship,
                                                'NAQLEEN.' || p_ship )
         )
          where rownum = 1;
      exception
         when no_data_found then
            l_cont := null;                            -- nothing came back from OTM
      end;

      if l_cont is null then
         log_it(
            'WARN',
            'No container number for shipment '
            || p_ship
            || ' (order '
            || l_order
            || ') - EIR printed without it'
         );
      else
         log_it(
            'INFO',
            'Container '
            || l_cont
            || ' resolved from OTM order '
            || l_order
            || ' for shipment '
            || p_ship
         );
      end if;

      return l_cont;
   end;

   -- Booking a shipment sits on. A sibling normally shares the payload shipment's
   -- booking, but nothing guarantees it, and the serial is numbered per booking.
   function ship_booking (
      p_ship in varchar2
   ) return varchar2 is
      l_book varchar2(100);
   begin
      select booking_id
        into l_book
        from (
         select ci.booking_id
           from xxotm_container_inventory_t ci
          where ci.inbound_shipment_nbr in ( p_ship,
                                             'NAQLEEN.' || p_ship )
          order by ci.booking_id nulls last
      )
       where rownum = 1;
      return l_book;
   exception
      when no_data_found then
         return null;
   end;
begin
   -- MERGE: assigned here, never in DECLARE. An exception during declaration
   -- elaboration escapes this block's handler and the caller gets a raw stack.
   v_location := xx_get_user_location(p_user_id);
   -- No HTTP output here: this reports through x_ok/x_message to
   -- XX_OTM_SUBMIT_GATE_OUT, which is deliberately fail-open on the EIR.
   if v_location is null then
      x_ok      := false;
      x_message := 'EIR not generated: no usable location on the request '
                   || '(req_location_id missing or not permitted).';
      return;
   end if;
   c_or_url   := xxotm_get_cfg('OTM_BASE_URL')
                 || '/logisticsRestApi/resources-int/v2/orderReleases';
   c_or_user  := xxotm_get_cfg('OTM_SYNC_USERNAME');
   c_or_pwd   := xxotm_get_cfg('OTM_SYNC_PASSWORD');

   x_ok := false;
   select container_no,
          container_type,
          customer_name,
          cust_short_name,
          booking_id,
          source_location_id,
          seal_number,
          shipment_name,
          driver_3pl
     into
      l_container_no,
      l_container_type,
      l_customer_name,
      l_shipper,
      l_booking_no,
      l_source_loc,
      l_seal_no,
      l_shipment_name,
      l_driver_id
     from (
      select ci.container_nbr as container_no,
             ci.container_type,
             coalesce(
                s.customer_name,
                ci.cust_name
             ) as customer_name,
             s.cust_short_name,
             ci.booking_id,
             ci.source_location_id,
             s.seal_number,
             coalesce(
                s.shipment_name,
                ci.shipment_name
             ) as shipment_name,
             driver_3pl
        from xxotm_shipments_t s
        left join xxotm_container_inventory_t ci
      on ci.inbound_shipment_nbr = s.shipment_xid
       where s.shipment_xid in ( l_ship,
                                 'NAQLEEN.' || l_ship )
       order by ci.container_nbr nulls last
   )
    where rownum = 1;

   if l_container_no is null then
      l_container_no := resolve_container(l_ship);

      -- The inventory row may have only just been created by that re-sync, so pick up
      -- the columns that come from it. coalesce keeps what we already have for the ones
      -- the sync does not maintain (e.g. source_location_id).
      if l_container_no is not null then
         begin
            select container_type,
                   booking_id,
                   source_location_id
              into
               l_container_type,
               l_booking_no,
               l_source_loc
              from (
               select coalesce(
                  ci.container_type,
                  l_container_type
               ) as container_type,
                      coalesce(
                         ci.booking_id,
                         l_booking_no
                      ) as booking_id,
                      coalesce(
                         ci.source_location_id,
                         l_source_loc
                      ) as source_location_id
                 from xxotm_container_inventory_t ci
                where ci.inbound_shipment_nbr in ( l_ship,
                                                   'NAQLEEN.' || l_ship )
                order by ci.container_nbr nulls last
            )
             where rownum = 1;
         exception
            when no_data_found then
               null;
         end;
      end if;
   end if;

   -- A truck can carry two containers, i.e. two shipments, but the gate submit payload
   -- names only one of them. The vehicle master row for the open visit holds the full
   -- comma separated list, so the second container comes from there. Everything else on
   -- the ticket - barcode, booking, line, seal, serial - stays on the payload shipment.
   l_container_list := l_container_no;
   begin
      select shipment_nbr
        into l_truck_ships
        from (
         select vm.shipment_nbr
           from xxotm_vehicle_master_t vm
          where upper(trim(vm.truck_nbr)) = upper(trim(p_truck_nbr))
            and vm.exit_time is null
            and vm.shipment_nbr is not null
          order by
            case
               when ','
                    || replace(
                  upper(vm.shipment_nbr),
                  ' '
               )
                    || ',' like '%,'
                                || upper(l_ship)
                                || ',%' then
                  0
               else
                  1
            end,                              -- the visit that names our shipment
            vm.entry_time desc nulls last
      )
       where rownum = 1;
   exception
      when no_data_found then
         l_truck_ships := null;                        -- single container visit
   end;

   if
      l_truck_ships is not null
      and instr(
         l_truck_ships,
         ','
      ) > 0
   then
      for r in (
         select ship
           from (
            select trim(replace(
               regexp_substr(
                  l_truck_ships,
                  '[^,]+',
                  1,
                  level
               ),
               'NAQLEEN.'
            )) as ship,
                   level as lvl
              from dual
            connect by
               regexp_substr(
                  l_truck_ships,
                  '[^,]+',
                  1,
                  level
               ) is not null
         )
          group by ship                                -- a repeated entry is one shipment
          order by min(lvl)
      ) loop
         l_sib_ship := r.ship;
         if
            l_sib_ship is not null
            and upper(l_sib_ship) <> upper(l_ship)
         then
            l_sib_container := resolve_container(l_sib_ship);

            -- Recorded even when the container could not be resolved: the shipment is
            -- still leaving on this truck and still owes the booking a serial.
            l_sib_rec.ship := l_sib_ship;
            l_sib_rec.container := l_sib_container;
            l_sib_rec.booking := ship_booking(l_sib_ship);
            l_sibs(l_sibs.count + 1) := l_sib_rec;
            if
               l_sib_container is not null
               and instr(
                  ','
                  || l_container_list
                  || ',',
                  ','
                  || l_sib_container
                  || ','
               ) = 0
            then
               l_container_list :=
                  case
                     when l_container_list is null then
                        l_sib_container
                     else l_container_list
                          || ','
                          || l_sib_container
                  end;
               log_it(
                  'INFO',
                  'Container '
                  || l_sib_container
                  || ' added from shipment '
                  || l_sib_ship
                  || ' sharing truck '
                  || p_truck_nbr
               );
            end if;
         end if;
      end loop;
   end if;

   -- Driver: latest still-inside row for this truck. Kept out of the join above so a
   -- truck with more than one open row can't multiply the result set.
   begin
      select driver_name
        into l_driver_name
        from xxotm_vehicle_master_t vm
       where upper(trim(vm.truck_nbr)) = upper(trim(p_truck_nbr))
         and driver_iqama = l_driver_id
         and rownum = 1;
   exception
      when no_data_found then
         l_driver_name := l_driver_id;
   end;

   -- Release movements are the gate-out side; anything else is an inbound receipt
   l_gate_type :=
      case
         when upper(trim(l_shipment_name)) in ( 'CRO',
                                                'LRO',
                                                'RELEASE_CFS' ) then
            'GATE OUT'
         else 'GATE IN'
      end;

   l_eir_no := to_char(xx_eir_seq.nextval);

   -- Serial No (gate out only): allocated and persisted, not derived from timestamps,
   -- so it can't duplicate, skip, or change when a ticket is reprinted. Keyed on the
   -- payload shipment, so it takes that shipment's container, not the printed list.
   if l_gate_type = 'GATE OUT' then
      l_serial_no := xx_otm_get_eir_serial(
         p_booking_id    => l_booking_no,
         p_shipment_nbr  => l_ship,
         p_container_nbr => l_container_no,
         p_truck_nbr     => p_truck_nbr,
         p_eir_no        => l_eir_no
      );

      -- One number per container. The denominator counts containers on the booking, so
      -- a ticket carrying two of them must take two numbers or the booking's count runs
      -- behind and the last truck out never prints n/n. Every shipment on the truck gets
      -- its own serial under the same EIR no; those sharing the payload's booking merge
      -- into one pair ('1,2/2'), one on another booking keeps its own ('1/2, 1/3').
      -- Any failure here leaves the payload shipment's serial standing on its own.
      if l_sibs.count > 0 then
         begin
            l_ser_num := substr(
               l_serial_no,
               1,
               instr(
                          l_serial_no,
                          '/'
                       ) - 1
            );
            l_ser_den := substr(
               l_serial_no,
               instr(
                          l_serial_no,
                          '/'
                       ) + 1
            );
            for i in 1..l_sibs.count loop
               l_sib_serial := xx_otm_get_eir_serial(
                  p_booking_id    => l_sibs(i).booking,
                  p_shipment_nbr  => l_sibs(i).ship,
                  p_container_nbr => l_sibs(i).container,
                  p_truck_nbr     => p_truck_nbr,
                  p_eir_no        => l_eir_no
               );

               if l_sib_serial is not null then
                  if l_ser_num is null then            -- payload had no bookable serial
                     l_ser_num := substr(
                        l_sib_serial,
                        1,
                        instr(
                                            l_sib_serial,
                                            '/'
                                         ) - 1
                     );
                     l_ser_den := substr(
                        l_sib_serial,
                        instr(
                                            l_sib_serial,
                                            '/'
                                         ) + 1
                     );
                  elsif l_sibs(i).booking = l_booking_no then
                     l_ser_num := l_ser_num
                                  || ','
                                  || substr(
                        l_sib_serial,
                        1,
                        instr(
                                            l_sib_serial,
                                            '/'
                                         ) - 1
                     );
                     -- the later call sees the higher total; keep the larger denominator.
                     -- to_number, or '9' would beat '10' on a string comparison.
                     l_ser_den := to_char(greatest(
                        to_number(l_ser_den),
                        to_number(substr(
                                          l_sib_serial,
                                          instr(
                                                                 l_sib_serial,
                                                                 '/'
                                                              ) + 1
                                       ))
                     ));
                  else
                     l_ser_extra := l_ser_extra
                                    || ', '
                                    || l_sib_serial;
                  end if;

                  log_it(
                     'INFO',
                     'Serial '
                     || l_sib_serial
                     || ' allocated to shipment '
                     || l_sibs(i).ship
                     || ' on EIR '
                     || l_eir_no
                  );
               end if;
            end loop;

            if l_ser_num is not null then
               l_serial_no := l_ser_num
                              || '/'
                              || l_ser_den
                              || l_ser_extra;
            end if;
         exception
            when others then
               log_it(
                  'WARN',
                  'Combined serial build failed for EIR '
                  || l_eir_no
                  || ': '
                  || sqlerrm
               );
         end;
      end if;

      l_gate_type := 'GATE OUT/RELEASE';
   end if;

   xxotm_print_eir(
      p_eir_no         => l_eir_no,
      p_gate_type      => l_gate_type,
      p_shipment_nbr   => l_ship,               -- barcode: the payload shipment only
      p_date_time      => to_char(
         sysdate,
         'DD-MM-YYYY, HH24:MI'
      ),
      p_container_no   => l_container_list,     -- every container on the truck
      p_container_type => l_container_type,
      p_customer_name  => l_customer_name,
      p_shipper        => l_shipper,
      p_booking_no     => l_booking_no,
      p_port_discharge => l_source_loc,
      p_seal_no        => l_seal_no,
      p_serial_no      => l_serial_no,
      p_remarks        => p_remarks,
      p_driver_name    => l_driver_name,
      p_truck_no       => p_truck_nbr,
      p_passed_user    => p_passed_user,
      x_pdf            => l_pdf
   );

   xx_otm_post_pdf(
      p_pdf            => l_pdf,
      p_filename       => 'EIR_'
                    || l_eir_no
                    || '.pdf',
      p_ownerobjectgid => 'NAQLEEN.' || l_ship,
      p_documentxid    => 'EIR_' || l_eir_no,      -- sequence already makes it unique
      p_documentdefgid => 'NAQLEEN.EIR',
      x_response_clob  => l_resp
   );


   if
      l_pdf is not null
      and dbms_lob.istemporary(l_pdf) = 1
   then
      dbms_lob.freetemporary(l_pdf);
   end if;

   if upload_ok(l_resp) then
      x_ok := true;
      -- CASE rather than NVL2: NVL2's 2nd and 3rd arguments must agree on type,
      -- and a bare NULL third argument leaves that to implicit conversion. The
      -- explicit form says what it means and concatenates identically, since
      -- NULL || x and '' || x are the same in Oracle.
      x_message := 'EIR '
                   || l_eir_no
                   || ' ('
                   || l_gate_type
                   || case
                         when l_serial_no is not null then ' ' || l_serial_no
                         else ''
                      end
                   || ') attached to shipment '
                   || l_ship;
      log_it(
         'INFO',
         x_message
      );
   else
      x_message := 'EIR '
                   || l_eir_no
                   || ' generated but OTM upload failed: '
                   || dbms_lob.substr(
         l_resp,
         500
      );
      log_it(
         'ERROR',
         x_message
      );
   end if;
exception
   when no_data_found then
      x_message := 'No shipment/container data found for '
                   || l_ship
                   || ' / truck '
                   || p_truck_nbr
                   || ' - EIR not generated';
      log_it(
         'ERROR',
         x_message
      );
   when others then
      if
         l_pdf is not null
         and dbms_lob.istemporary(l_pdf) = 1
      then
         dbms_lob.freetemporary(l_pdf);
      end if;
      x_message := 'EIR generation failed: ' || sqlerrm;
      log_it(
         'ERROR',
         x_message
      );
end xx_otm_generate_eir;

   -- ========================================================================
   -- XX_OTM_GET_ACTIVE_SHIPMENTS_BY_CUSTOMER_AND_TYPE   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_ACTIVE_SHIPMENTS_BY_CUSTOMER_AND_TYPE.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_active_shipments_by_customer_and_type (
   p_customer_nbr  in varchar2,
   p_shipment_name in varchar2,
   p_search_text   in varchar2 default null
)
as
   l_url                  varchar2(4000);
   l_response_clob        clob;
   l_items_count          number;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   l_shipment_xid         varchar2(100);
   l_shipment_name        varchar2(100);
   l_container_no         varchar2(100);
   l_attribute2           varchar2(100);
begin
   apex_json.initialize_clob_output;

   -- Filter by:
   -- 1. Attribute2 (Customer Number)
   -- 2. Shipment Name
   -- 3. Trip Status = NOT STARTED (Active/Available)
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments';
   l_url := l_url
            || '?q=attribute2 eq "'
            || 'NAQLEEN.'
            || replace(
      p_customer_nbr,
      'NAQLEEN.',
      ''
   )
            || '" and shipmentName eq "'
            || upper(p_shipment_name)
            || '" and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED"'
            ;

   if p_search_text is not null then
      l_url := l_url
               || ' and shipmentXid co "'
               || upper(p_search_text)
               || '"';
   end if;

   l_url := l_url || '&limit=100'; -- Reasonable limit
   l_url := l_url || '&orderBy=updateDate:desc';

   -- DEBUG: Print URL
    apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );


      apex_json.parse(l_response_clob);
      l_items_count := apex_json.get_count('items');

      -- DEBUG: Item count
     apex_json.open_object; -- Root

      if l_items_count > 0 then
         apex_json.write(
            'response_message',
            'Success'
         );
         apex_json.write(
            'response_code',
            200
         );
         apex_json.open_array('data');
         for i in 1..l_items_count loop
            l_shipment_xid := apex_json.get_varchar2(
               'items[%d].shipmentXid',
               i
            );
            l_shipment_name := apex_json.get_varchar2(
               'items[%d].shipmentName',
               i
            );

            apex_json.open_object;
            apex_json.write(
               'shipment_nbr',
               l_shipment_xid
            );
            apex_json.write(
               'shipment_name',
               l_shipment_name
            );

            apex_json.close_object;
         end loop;

         apex_json.close_array;
      else
         apex_json.write(
            'response_message',
            'No Data Found'
         );
         apex_json.write(
            'response_code',
            404
         );
         apex_json.open_array('data');
         apex_json.close_array;
      end if;


      apex_json.close_object;
   exception
      when others then
         apex_json.open_object;
         apex_json.write(
            'response_message',
            'Error: ' || sqlerrm
         );
         apex_json.write(
            'response_code',
            500
         );


         apex_json.close_object;
   end;

   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_active_shipments_by_customer_and_type;

   -- ========================================================================
   -- XX_OTM_GET_ACTIVE_SHIPMENTS_FOR_LCL   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_ACTIVE_SHIPMENTS_FOR_LCL.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_active_shipments_for_lcl (
   p_customer_nbr  in varchar2,
   p_shipment_name in varchar2,
   p_booking_nbr   in varchar2,
   p_search_text   in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   l_url                  varchar2(4000);
   l_response_clob        clob;
   l_items_count          number;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   l_shipment_xid         varchar2(100);
   l_shipment_name        varchar2(100);
   l_container_no         varchar2(100);
   l_attribute2           varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;

   -- Filter by:
   -- 1. Attribute2 (Customer Number)
   -- 2. Shipment Name
   -- 3. Trip Status = NOT STARTED (Active/Available)
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments'
   ;
   l_url := l_url
            || '?q=attribute2 eq "'
            || 'NAQLEEN.'
            || replace(
      p_customer_nbr,
      'NAQLEEN.',
      ''
   )
            || '" and shipmentName eq "'
            || upper(p_shipment_name)
            || '" and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED" and refnums.shipmentRefnumQualGid eq "NAQLEEN.BOOKING_NO" and refnums.shipmentRefnumValue eq "'
            || upper(p_booking_nbr)
            || '"';

   if p_search_text is not null then
      l_url := l_url
               || ' and shipmentXid co "'
               || upper(p_search_text)
               || '"';
   end if;

   l_url := l_url || '&limit=100'; -- Reasonable limit
   l_url := l_url || '&orderBy=updateDate:desc';

   -- DEBUG: Print URL
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url         => l_url,
         p_http_method => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         
      );


      apex_json.parse(l_response_clob);
      l_items_count := apex_json.get_count('items');

      -- DEBUG: Item count
      apex_json.open_object; -- Root

      if l_items_count > 0 then
         apex_json.write(
            'response_message',
            'Success'
         );
         apex_json.write(
            'response_code',
            200
         );
         apex_json.open_array('data');
         for i in 1..l_items_count loop
            l_shipment_xid := apex_json.get_varchar2(
               'items[%d].shipmentXid',
               i
            );
            l_shipment_name := apex_json.get_varchar2(
               'items[%d].shipmentName',
               i
            );
            apex_json.open_object;
            apex_json.write(
               'shipment_nbr',
               l_shipment_xid
            );
            apex_json.write(
               'shipment_name',
               l_shipment_name
            );
            apex_json.close_object;
         end loop;

         apex_json.close_array;
      else
         apex_json.write(
            'response_message',
            'No Data Found'
         );
         apex_json.write(
            'response_code',
            404
         );
         apex_json.open_array('data');
         apex_json.close_array;
      end if;


      apex_json.close_object;
   exception
      when others then
         apex_json.open_object;
         apex_json.write(
            'response_message',
            'Error: ' || sqlerrm
         );
         apex_json.write(
            'response_code',
            500
         );
         apex_json.close_object;
   end;

   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_active_shipments_for_lcl;

   -- ========================================================================
   -- XX_OTM_GET_ASSIGNED_TASK_ASSIGNMENT_SHIPMENTS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_ASSIGNED_TASK_ASSIGNMENT_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_assigned_task_assignment_shipments (
   p_search_text   in varchar2 default '',
   p_page_num in number default 0,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_cursor sys_refcursor;
   p_page_size number:=100;
   v_location varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
    -- Configure APEX_JSON to output to CLOB
   apex_json.initialize_clob_output;
   apex_json.open_object;
    
    -- Write Standard Response Headers
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );

    -- Open the cursor for the query with aliased columns to match desired JSON keys
   open l_cursor for select ta.shipment_nbr as "shipment_nbr",
                            s.shipment_name as "shipment_name",
                            nvl(ta.status,'assigned') as "shipment_status"
                                         from xxotm_task_assignment_t ta
                                         join xxotm_shipments_t s
                                       on ta.shipment_nbr = s.shipment_xid
                      where ( p_search_text is null
                         or upper(ta.shipment_nbr) like '%'
                                                        || upper(p_search_text)
                                                        || '%' ) and s.location = v_location and ta.location = v_location
                                                        ORDER BY ASSIGNED_DATE desc
OFFSET (p_page_num-1 ) * p_page_size ROWS
FETCH NEXT p_page_size ROWS ONLY;

    -- Write cursor to 'shipments' array
   apex_json.write(
      'data',
      l_cursor
   );
   apex_json.close_object;

 htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
    htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_assigned_task_assignment_shipments;

   -- ========================================================================
   -- XX_OTM_GET_AVAILABLEPOSITIONS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_AVAILABLEPOSITIONS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_availablepositions (
    p_container_nbr IN VARCHAR2
)
AS
BEGIN
    apex_json.initialize_clob_output;
    apex_json.open_object;

    apex_json.write('response_code', 200);
    apex_json.write('response_message', 'Success');

    apex_json.open_array('data');

    FOR rec IN (
        SELECT DISTINCT
               position
        FROM  xxotm_container_inventory_t ci
        WHERE position IS NOT NULL
          AND (p_container_nbr IS NULL
               OR UPPER(ci.container_nbr) LIKE '%' || UPPER(p_container_nbr) || '%')
        ORDER BY position
    )
    LOOP
        apex_json.write(rec.position);
    END LOOP;

    apex_json.close_array;
    apex_json.close_object;

    htp.prn(apex_json.get_clob_output);
        DBMS_OUTPUT.PUT_LINE(apex_json.get_clob_output);


EXCEPTION
    WHEN OTHERS THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 400);
        apex_json.write('response_message', SQLERRM);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
            DBMS_OUTPUT.PUT_LINE(apex_json.get_clob_output);

END xx_otm_get_AvailablePositions;

   -- ========================================================================
   -- XX_OTM_GET_AVAILABLE_OPERATORS   [3d-high-risk / MANUAL]
   -- source: db/work/XX_OTM_GET_AVAILABLE_OPERATORS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_available_operators (
   searchtext in varchar2 default null,
   p_user_id  in varchar2 default null
)
AS
   v_location   varchar2(100);
   l_data_found boolean := false;
BEGIN
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   apex_json.initialize_clob_output;
   apex_json.open_object;
   for r_operator in (
      select distinct ta.operator                          as operator_id,
                      nvl(ta.operator_name, ta.operator)   as operator_name
        from xxotm_task_assignment_t ta
       where ta.operator is not null
         and ta.location = v_location
            -- Case-insensitive, and matches the display name as well as the id.
            -- Prod compared the raw id only, so searching for an operator by the
            -- name shown on screen found nothing.
         and ( searchtext is null
               or upper(ta.operator) like '%' || upper(searchtext) || '%'
               or upper(ta.operator_name) like '%' || upper(searchtext) || '%' )
       order by 2
   ) loop
        -- If this is the first row, write the success header
      if not l_data_found then
         apex_json.write(
            'response_message',
            'Success'
         );
         apex_json.write(
            'response_code',
            200
         );
         apex_json.open_array('data');
         l_data_found := true;
      end if;

      apex_json.open_object;
      apex_json.write('id',   r_operator.operator_id);
      apex_json.write('name', r_operator.operator_name);
      apex_json.close_object;
   end loop;

   if not l_data_found then
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.write(
         'response_code',
         404
      );
   else
      apex_json.close_array; -- Close the data array
   end if;

   apex_json.close_object; -- Close the root object

   htp.prn(apex_json.get_clob_output);
   -- dbms_output.put_line of the whole payload removed: it raises ORA-06502 once
   -- the response exceeds the DBMS_OUTPUT line limit, turning a good response
   -- into a 500. It was debug output on a production endpoint.
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_available_operators;

   -- ========================================================================
   -- XX_OTM_GET_AVAILABLE_POSITION_LOV   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_AVAILABLE_POSITION_LOV.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_available_position_lov (
   p_flag           in varchar2,
   p_terminal       in varchar2 default null,
   p_block          in varchar2 default null,
   p_row            in varchar2 default null,
   p_lot            in number default null,
   p_container_type in varchar2 default null,
   p_container_nbr  in varchar2 default null,  -- Container number to exclude its current position
   p_user_id        in varchar2 default null
)
as
   v_location varchar2(100);
   -- Updated Date : 26-12-2024
   -- Updated By : Sai Sanjit
   -- Description : Added container_nbr parameter to exclude current position from suggestions
   --               Container cannot be restacked to the same Terminal + Block + Lot combination
   --               Added debug logging

   -- Define collection types
   type t_varchar_list is
      table of varchar2(100);
   type t_number_list is
      table of number;
   
   -- Initialize collections to avoid ORA-06531
   v_terminals                t_varchar_list := t_varchar_list();
   v_blocks                   t_varchar_list := t_varchar_list();
   v_rows                     t_varchar_list := t_varchar_list();
   v_lots                     t_number_list := t_number_list();
   v_level                    number := 0;
   v_has_data                 boolean := false;
   v_rephrased_container_type varchar2(10);
   
   -- Current container position variables
   v_container_position       varchar2(200);
   v_curr_terminal            varchar2(50);
   v_curr_block               varchar2(50);
   v_curr_lot_no              varchar2(50);
   v_curr_row_no              varchar2(50);
   v_exclude_position         boolean := false;
   
   -- Debug variable
   l_debug                    varchar2(4000) := '';
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   l_debug := l_debug || 'START | ';
   l_debug := l_debug
              || 'Params: flag='
              || p_flag
              || ', terminal='
              || p_terminal
              || ', block='
              || p_block
              || ', container_type='
              || p_container_type
              || ', container_nbr='
              || p_container_nbr
              || ' | ';

   apex_json.initialize_clob_output;
   apex_json.open_object; -- Root object

   if p_flag not in ( 'I',
                      'T',
                      'B',
                      'R',
                      'L' ) then
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'Invalid flag passed'
      );
      apex_json.write(
         'debug',
         l_debug || 'Invalid flag'
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      return;
   end if;

   if p_container_type like '2%' then
      v_rephrased_container_type := '20FT';
   else
      v_rephrased_container_type := '40FT';
   end if;

   l_debug := l_debug
              || 'Rephrased container_type='
              || v_rephrased_container_type
              || ' | ';
   
   -- Get current container position if container_nbr is provided
   if p_container_nbr is not null then
      l_debug := l_debug || 'Looking up container position | ';
      begin
         select position
           into v_container_position
           from xxotm_container_inventory_t
          where container_nbr = p_container_nbr
            and position is not null
            and container_stored_time is not null
            and container_released_time is null and xxotm_container_inventory_t.location = v_location
            and rownum = 1;

         l_debug := l_debug
                    || 'Found position='
                    || v_container_position
                    || ' | ';
         if v_container_position is not null then
            -- Parse position: terminal-block-lot_no-row_no-level_no
            v_curr_terminal := regexp_substr(
               v_container_position,
               '[^-]+',
               1,
               1
            );
            v_curr_block := regexp_substr(
               v_container_position,
               '[^-]+',
               1,
               2
            );
            v_curr_lot_no := regexp_substr(
               v_container_position,
               '[^-]+',
               1,
               3
            );
            v_curr_row_no := regexp_substr(
               v_container_position,
               '[^-]+',
               1,
               4
            );
            v_exclude_position := true;
            l_debug := l_debug
                       || 'Parsed: T='
                       || v_curr_terminal
                       || ', B='
                       || v_curr_block
                       || ', L='
                       || v_curr_lot_no
                       || ', R='
                       || v_curr_row_no
                       || ' | ';
         end if;
      exception
         when no_data_found then
            l_debug := l_debug || 'Container not found in inventory | ';
            v_exclude_position := false;
      end;
   else
      l_debug := l_debug || 'No container_nbr provided | ';
   end if;
   
   -- Fetch data
   case p_flag
      when 'I' then
         l_debug := l_debug || 'Getting terminals | ';
         -- Get Terminals (Based on Container Type)
         select distinct terminal
         bulk collect
           into v_terminals
           from xxotm_position_master_t
          where container_type = v_rephrased_container_type
            and is_occupied = 'N'
            and xxotm_position_master_t.location = v_location
          order by terminal;
         v_has_data := v_terminals.count > 0;
         l_debug := l_debug
                    || 'Found '
                    || v_terminals.count
                    || ' terminals | ';
      when 'T' then
         l_debug := l_debug || 'Getting blocks | ';
         -- Get Blocks (Based on Terminal)
         select distinct block
         bulk collect
           into v_blocks
           from xxotm_position_master_t
          where terminal = p_terminal
            and is_occupied = 'N'
            and xxotm_position_master_t.location = v_location
            and container_type = v_rephrased_container_type
          order by block;
         v_has_data := v_blocks.count > 0;
         l_debug := l_debug
                    || 'Found '
                    || v_blocks.count
                    || ' blocks | ';
      when 'B' then
         l_debug := l_debug || 'Getting lots | ';
         -- Get Lots (Based on Terminal + Block)
         -- No exclusion needed for lots - exclusion only applies to rows
         select distinct lot_no
         bulk collect
           into v_lots
           from xxotm_position_master_t
          where terminal = p_terminal
            and block = p_block
            and is_occupied = 'N'
            and xxotm_position_master_t.location = v_location
            and container_type = v_rephrased_container_type
          order by lot_no;
         v_has_data := v_lots.count > 0;
         l_debug := l_debug
                    || 'Found '
                    || v_lots.count
                    || ' lots | ';
      when 'L' then
         l_debug := l_debug || 'Getting rows | ';
         -- Get Rows (Based on Terminal + Block + Lot)
         -- Check if we should exclude the container's current row
         if
            v_exclude_position
            and p_terminal = v_curr_terminal
            and p_block = v_curr_block
            and to_char(p_lot) = v_curr_lot_no
         then
            l_debug := l_debug
                       || 'Excluding row='
                       || v_curr_row_no
                       || ' | ';
            -- Exclude the container's current row
            select distinct row_no
            bulk collect
              into v_rows
              from xxotm_position_master_t
             where terminal = p_terminal
               and block = p_block
               and lot_no = p_lot
               and is_occupied = 'N'
               and xxotm_position_master_t.location = v_location
               and container_type = v_rephrased_container_type
               and row_no != v_curr_row_no  -- Exclude current row
             order by row_no;
         else
            l_debug := l_debug || 'No exclusion needed | ';
            select distinct row_no
            bulk collect
              into v_rows
              from xxotm_position_master_t
             where terminal = p_terminal
               and block = p_block
               and lot_no = p_lot
               and is_occupied = 'N'
               and xxotm_position_master_t.location = v_location
               and container_type = v_rephrased_container_type
             order by row_no;
         end if;
         v_has_data := v_rows.count > 0;
         l_debug := l_debug
                    || 'Found '
                    || v_rows.count
                    || ' rows | ';
      when 'R' then
         l_debug := l_debug || 'Getting level | ';
         -- Get Levels (Based on Terminal + Block + Lot + Row)
         -- Logic Change: Get ONLY the lowest available level (next stackable position)
         begin
            select level_no
              into v_level
              from xxotm_position_master_t
             where terminal = p_terminal
               and block = p_block
               and lot_no = p_lot
               and row_no = p_row
               and is_occupied = 'N'
               and xxotm_position_master_t.location = v_location
               and container_type = v_rephrased_container_type
             order by level_no asc
             fetch first 1 rows only;
            v_has_data := true;
            l_debug := l_debug
                       || 'Found level='
                       || v_level
                       || ' | ';
         exception
            when no_data_found then
               v_level := 0;
               v_has_data := false;
               l_debug := l_debug || 'No level found | ';
         end;
   end case;
   
   -- Write Response
   if not v_has_data then
      l_debug := l_debug || 'No data found | ';
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No Data Found'
      );
   else
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_object('data');
      case p_flag
         when 'I' then
            apex_json.open_array('terminals');
            for i in 1..v_terminals.count loop
               apex_json.write(v_terminals(i));
            end loop;
            apex_json.close_array;
         when 'T' then
            apex_json.open_array('blocks');
            for i in 1..v_blocks.count loop
               apex_json.write(v_blocks(i));
            end loop;
            apex_json.close_array;
         when 'B' then
            apex_json.open_array('lots');
            for i in 1..v_lots.count loop
               apex_json.write(v_lots(i));
            end loop;
            apex_json.close_array;
         when 'L' then
            apex_json.open_array('rows');
            for i in 1..v_rows.count loop
               apex_json.write(v_rows(i));
            end loop;
            apex_json.close_array;
         when 'R' then
            apex_json.write(
               'level',
               v_level
            );
      end case;

      apex_json.close_object;
   end if;
   
   -- Add debug info
   apex_json.write(
      'debug',
      l_debug
   );
   if v_exclude_position then
      apex_json.write(
         'excluded_position',
         v_container_position
      );
   end if;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
    --   apex_json.write(
    --      'debug',
    --      l_debug
    --      || 'EXCEPTION: '
    --      || sqlerrm
    --   );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_available_position_lov;

   -- ========================================================================
   -- XX_OTM_GET_AVAILABLE_TRUCKS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_AVAILABLE_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_available_trucks (p_user_id in varchar2 default null)
as
   v_location varchar2(100);
   type record_type is record (
         truck_nbr    varchar2(100),
         driver_name  varchar2(100),
         driver_iqama varchar2(100),
         type         varchar2(100),
         entry_time   varchar2(100)
   );
   l_record record_type;
   cursor c_data_cursor is
   select distinct truck_nbr,
                   driver_name,
                   driver_iqama,
                   type,
                   entry_time
     from xxotm_vehicle_master_t
    where entry_time is not null
      and exit_time is null
      and status = 'vehicle_entry'
      and xxotm_vehicle_master_t.location = v_location
    ORDER BY entry_time DESC;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   owa_util.mime_header(
      'application/json',
      true
   );
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');
   open c_data_cursor;
   loop
      fetch c_data_cursor into l_record;
      exit when c_data_cursor%notfound;
      apex_json.open_object;
      apex_json.write(
         'truck_number',
         l_record.truck_nbr
      );
      apex_json.write(
         'driver_name',
         l_record.driver_name
      );
      apex_json.write(
         'iqama_number',
         l_record.driver_iqama
      );
      apex_json.write(
         'type',
         l_record.type
      );
      apex_json.write(
         'entry_time',
         l_record.entry_time
      );
      apex_json.close_object;
   end loop;
   close c_data_cursor;
   apex_json.close_array;
   apex_json.close_object;

   -- Output Success Response in chunks
   DECLARE
       l_clob   CLOB;
       l_offset NUMBER := 1;
       l_amount NUMBER := 32000;
       l_len    NUMBER;
       l_buffer VARCHAR2(32767);
   BEGIN
       l_clob := apex_json.get_clob_output;
       l_len  := dbms_lob.getlength(l_clob);
       
       WHILE l_offset <= l_len LOOP
           dbms_lob.read(l_clob, l_amount, l_offset, l_buffer);
           htp.prn(l_buffer);
           l_offset := l_offset + l_amount;
       END LOOP;
       
       -- Optional: If you still need debug output for small payloads
       -- dbms_output.put_line(dbms_lob.substr(l_clob, 32000, 1));
   END;

   apex_json.free_output;

exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'ERROR WHILE EXECUTING METHOD: ' || sqlerrm
      );
      apex_json.close_object;
      
      -- Output Error Response in chunks
      DECLARE
          l_clob_err   CLOB;
          l_offset_err NUMBER := 1;
          l_amount_err NUMBER := 32000;
          l_len_err    NUMBER;
          l_buffer_err VARCHAR2(32767);
      BEGIN
          l_clob_err := apex_json.get_clob_output;
          l_len_err  := dbms_lob.getlength(l_clob_err);
          
          WHILE l_offset_err <= l_len_err LOOP
              dbms_lob.read(l_clob_err, l_amount_err, l_offset_err, l_buffer_err);
              htp.prn(l_buffer_err);
              l_offset_err := l_offset_err + l_amount_err;
          END LOOP;
      END;

      apex_json.free_output;
end;

   -- ========================================================================
   -- XX_OTM_GET_CFS_HISTORY_CONTAINERS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_CFS_HISTORY_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_cfs_history_containers (
    p_search_text IN VARCHAR2 DEFAULT NULL,
    p_page_number IN NUMBER DEFAULT 1,
    p_page_size IN NUMBER DEFAULT 20
)
AS
    l_total_count NUMBER := 0;
    l_offset NUMBER;
    l_json_output CLOB;
    l_first_record BOOLEAN := TRUE;
    l_page_num NUMBER;
    l_page_sz NUMBER;
    l_record_count NUMBER := 0;
    l_search_text VARCHAR2(200);
BEGIN
    -- Set default values
    l_page_num := NVL(p_page_number, 1);
    l_page_sz := NVL(p_page_size, 20);
    l_search_text := UPPER(TRIM(p_search_text));
    
    DBMS_OUTPUT.PUT_LINE('DEBUG: p_search_text = [' || p_search_text || ']');
    DBMS_OUTPUT.PUT_LINE('DEBUG: l_search_text = [' || l_search_text || ']');
    DBMS_OUTPUT.PUT_LINE('DEBUG: l_search_text IS NOT NULL = ' || CASE WHEN l_search_text IS NOT NULL THEN 'TRUE' ELSE 'FALSE' END);
    
    -- Calculate offset for pagination
    l_offset := (l_page_num - 1) * l_page_sz;
    
    -- Get total count for pagination (with search filter if provided)
    IF l_search_text IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE('DEBUG: Executing search query with text: [' || l_search_text || ']');
        SELECT COUNT(*)
        INTO l_total_count
        FROM xxotm_customer_inventory_t ci,
             xxotm_shipments_t sh
        WHERE ci.shipment_nbr = sh.SHIPMENT_XID
        AND sh.shipment_name IN ('DESTUFFING', 'STUFFING', 'STORE_AS_IT_IS')
        AND UPPER(ci.container_nbr) LIKE '%' || l_search_text || '%';
        DBMS_OUTPUT.PUT_LINE('DEBUG: Search count = ' || l_total_count);
    ELSE
        DBMS_OUTPUT.PUT_LINE('DEBUG: Executing query without search filter');
        SELECT COUNT(*)
        INTO l_total_count
        FROM xxotm_customer_inventory_t ci,
             xxotm_shipments_t sh
        WHERE ci.shipment_nbr = sh.SHIPMENT_XID
        AND sh.shipment_name IN ('DESTUFFING', 'STUFFING', 'STORE_AS_IT_IS');
        DBMS_OUTPUT.PUT_LINE('DEBUG: No-search count = ' || l_total_count);
    END IF;
    
    -- Check if no data found
    IF l_total_count = 0 THEN
        l_json_output := '{"response_message":"No data found","response_code":404,"total_records":0,"page_number":' || 
                         l_page_num || ',"page_size":' || l_page_sz || ',"total_pages":0,"search_text":"' || p_search_text || '","data":[]}';
        HTP.PRN(l_json_output);
        DBMS_OUTPUT.PUT_LINE(l_json_output);
        RETURN;
    END IF;
    
    -- Build JSON manually with proper parameter values
    l_json_output := '{"response_message":"Success","response_code":200,"total_records":' || 
                     l_total_count || ',"page_number":' || l_page_num || 
                     ',"page_size":' || l_page_sz || ',"total_pages":' || 
                     CEIL(l_total_count / l_page_sz) || ',"search_text":"' || p_search_text || '","data":[';
    
    -- Fetch and add data (with search filter if provided)
    IF l_search_text IS NOT NULL THEN
        FOR rec IN (
            SELECT 
                ci.container_nbr,
                ci.cust_name AS customer,
                sh.shipment_name AS type,
                ci.creation_date
            FROM xxotm_customer_inventory_t ci,
                 xxotm_shipments_t sh
            WHERE ci.shipment_nbr = sh.SHIPMENT_XID
            AND sh.shipment_name IN ('DESTUFFING', 'STUFFING', 'STORE_AS_IT_IS')
            AND UPPER(ci.container_nbr) LIKE '%' || l_search_text || '%'
            ORDER BY ci.creation_date DESC NULLS LAST
            OFFSET l_offset ROWS FETCH NEXT l_page_sz ROWS ONLY
        ) LOOP
            IF NOT l_first_record THEN
                l_json_output := l_json_output || ',';
            END IF;
            
            l_json_output := l_json_output || '{"container_nbr":"' || rec.container_nbr ||
                             '","customer":"' || rec.customer || '","type":"' || rec.type ||
                             '","creation_date":"' || rec.creation_date || '"}';
            
            l_first_record := FALSE;
            l_record_count := l_record_count + 1;
        END LOOP;
    ELSE
        FOR rec IN (
            SELECT 
                ci.container_nbr,
                ci.cust_name AS customer,
                sh.shipment_name AS type,
                ci.creation_date
            FROM xxotm_customer_inventory_t ci,
                 xxotm_shipments_t sh
            WHERE ci.shipment_nbr = sh.SHIPMENT_XID
            AND sh.shipment_name IN ('DESTUFFING', 'STUFFING', 'STORE_AS_IT_IS')
            ORDER BY ci.creation_date DESC NULLS LAST
            OFFSET l_offset ROWS FETCH NEXT l_page_sz ROWS ONLY
        ) LOOP
            IF NOT l_first_record THEN
                l_json_output := l_json_output || ',';
            END IF;
            
            l_json_output := l_json_output || '{"container_nbr":"' || rec.container_nbr ||
                             '","customer":"' || rec.customer || '","type":"' || rec.type ||
                             '","creation_date":"' || rec.creation_date || '"}';
            
            l_first_record := FALSE;
            l_record_count := l_record_count + 1;
        END LOOP;
    END IF;
    
    -- Check if current page has no records
    IF l_record_count = 0 THEN
        l_json_output := '{"response_message":"No records found for this page","response_code":404,"total_records":' || 
                         l_total_count || ',"page_number":' || l_page_num || 
                         ',"page_size":' || l_page_sz || ',"total_pages":' || 
                         CEIL(l_total_count / l_page_sz) || ',"search_text":"' || p_search_text || '","data":[]}';
    ELSE
        l_json_output := l_json_output || ']}';
    END IF;
    
    -- Output the JSON
    HTP.PRN(l_json_output);
    DBMS_OUTPUT.PUT_LINE(l_json_output);
    
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        HTP.PRN('{"response_message":"No data found","response_code":404,"total_records":0,"page_number":1,"page_size":20,"total_pages":0,"search_text":"' || p_search_text || '","data":[]}');
        DBMS_OUTPUT.PUT_LINE('{"response_message":"No data found","response_code":404,"total_records":0,"page_number":1,"page_size":20,"total_pages":0,"search_text":"' || p_search_text || '","data":[]}');
    WHEN OTHERS THEN
        HTP.PRN('{"response_message":"Error: ' || SQLERRM || '","response_code":500,"total_records":0,"page_number":1,"page_size":20,"total_pages":0,"search_text":"' || p_search_text || '","data":[]}');
        DBMS_OUTPUT.PUT_LINE('{"response_message":"Error: ' || SQLERRM || '","response_code":500,"total_records":0,"page_number":1,"page_size":20,"total_pages":0,"search_text":"' || p_search_text || '","data":[]}');
END XX_OTM_GET_CFS_HISTORY_CONTAINERS;

   -- ========================================================================
   -- XX_OTM_GET_CFS_HISTORY_DETAILS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_CFS_HISTORY_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_cfs_history_details (
   p_container_nbr in varchar2
)
as
   l_container_found number := 0;
   l_json_output     clob;
   l_first_item      boolean := true;
   l_first_record    boolean := true;
begin
    -- Check if container exists
   select count(*)
     into l_container_found
     from xxotm_customer_inventory_t
    where container_nbr = p_container_nbr;
    
    -- If container not found, return 404
   if l_container_found = 0 then
      l_json_output := '{"response_message":"Container not found","response_code":404,"data":[]}';
      htp.prn(l_json_output);
      dbms_output.put_line(l_json_output);
      return;
   end if;
    
    -- Build JSON response with container details and items
   l_json_output := '{"response_message":"Success","response_code":200,"data":[';
    
    -- Fetch unique container details with items
   for rec in (
      select distinct cust_name as customer,
                      container_nbr,
                      shipment_nbr,
                      stuffed_by
        from xxotm_customer_inventory_t
       where container_nbr = p_container_nbr
   ) loop
      if not l_first_record then
         l_json_output := l_json_output || ',';
      end if;
      l_json_output := l_json_output
                       || '{"customer":"'
                       || rec.customer
                       || '","container_nbr":"'
                       || rec.container_nbr
                       || '","shipment_nbr":"'
                       || rec.shipment_nbr
                       || '","stuffed_by":"'
                       || nvl(
         rec.stuffed_by,
         ''
      )
                       || '","items":[';

      l_first_item := true;
        
        -- Fetch items for this container
      for item_rec in (
         select item_code,  -- Added item_code
                 item_description,
                qty as quantity,
                qty_uom as quantity_uom
           from xxotm_customer_inventory_t
          where container_nbr = p_container_nbr
      ) loop
         if not l_first_item then
            l_json_output := l_json_output || ',';
         end if;
         l_json_output := l_json_output
                          || '{"item_code":"'
                          || nvl(
            item_rec.item_code,
            ''
         )
                          || '","item_description":"'
                          || nvl(
            item_rec.item_description,
            ''
         )
                          || '","quantity":'
                          || nvl(
            item_rec.quantity,
            0
         )
                          || ',"quantity_uom":"'
                          || nvl(
            item_rec.quantity_uom,
            ''
         )
                          || '"}';

         l_first_item := false;
      end loop;

      l_json_output := l_json_output || ']}';
      l_first_record := false;
   end loop;

   l_json_output := l_json_output || ']}';
    
    -- Output the JSON
   htp.prn(l_json_output);
   dbms_output.put_line(l_json_output);
exception
   when others then
      htp.prn('{"response_message":"Error: '
              || sqlerrm
              || '","response_code":500,"data":[]}');
      dbms_output.put_line('{"response_message":"Error: '
                           || sqlerrm
                           || '","response_code":500,"data":[]}');
end xx_otm_get_cfs_history_details;

   -- ========================================================================
   -- XX_OTM_GET_CHAT_MESSAGES   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_CHAT_MESSAGES.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_chat_messages (
    P_USER1_ID IN NUMBER,
    P_USER2_ID IN NUMBER
)
AS
    V_COUNT NUMBER := 0;
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('response_code', 200);
        APEX_JSON.WRITE('response_message', 'Messages retrieved successfully');
        APEX_JSON.OPEN_ARRAY('messages');
        FOR REC IN (
            SELECT 
                MESSAGE_ID,
                SENDER_ID,
                RECEIVER_ID,
                MESSAGE_TEXT,
                TO_CHAR(SENT_AT, 'YYYY-MM-DD HH24:MI:SS') as SENT_AT_STR      
            FROM 
                XXOTM_CHAT_MESSAGES_T
            WHERE 
                (SENDER_ID = P_USER1_ID AND RECEIVER_ID = P_USER2_ID)
                OR 
                (SENDER_ID = P_USER2_ID AND RECEIVER_ID = P_USER1_ID)
            ORDER BY 
                SENT_AT ASC
        ) LOOP
            V_COUNT := V_COUNT + 1;
            APEX_JSON.OPEN_OBJECT;
            APEX_JSON.WRITE('message_id', REC.MESSAGE_ID);
            APEX_JSON.WRITE('sender_id', REC.SENDER_ID);
            APEX_JSON.WRITE('receiver_id', REC.RECEIVER_ID);
            APEX_JSON.WRITE('text', REC.MESSAGE_TEXT);
            APEX_JSON.WRITE('sent_at', REC.SENT_AT_STR);
           
            -- Helper flag to easily identify if message is from the requester (User 1)
            APEX_JSON.WRITE('is_me', CASE WHEN REC.SENDER_ID = P_USER1_ID THEN TRUE ELSE FALSE END);
            APEX_JSON.CLOSE_OBJECT;
        END LOOP;
        APEX_JSON.CLOSE_ARRAY;
        
        APEX_JSON.WRITE('total_messages', V_COUNT);
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
    WHEN OTHERS THEN
        APEX_JSON.INITIALIZE_CLOB_OUTPUT;
        APEX_JSON.OPEN_OBJECT;
            APEX_JSON.WRITE('response_code', 500);
            APEX_JSON.WRITE('response_message', 'Unexpected error: ' || SQLERRM);
        APEX_JSON.CLOSE_OBJECT;
        HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XX_OTM_GET_CHAT_MESSAGES;

   -- ========================================================================
   -- XX_OTM_GET_CHAT_USERS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_CHAT_USERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_chat_users (
    P_CURRENT_USER_ID IN NUMBER
)
AS
    V_COUNT NUMBER := 0;
BEGIN
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('response_code', 200);
        APEX_JSON.WRITE('response_message', 'Chat users retrieved successfully');
        APEX_JSON.OPEN_ARRAY('users');
        FOR REC IN (
            SELECT 
                USER_ID,
                USERNAME,
                FULL_NAME
                              
            FROM 
                XXOTM_CHAT_USERS_T
            WHERE 
                USER_ID != P_CURRENT_USER_ID
            ORDER BY 
                FULL_NAME
        ) LOOP
            V_COUNT := V_COUNT + 1;
            APEX_JSON.OPEN_OBJECT;
            APEX_JSON.WRITE('user_id', REC.USER_ID);
            APEX_JSON.WRITE('username', REC.USERNAME);
            APEX_JSON.WRITE('full_name', INITCAP(REC.FULL_NAME));
          
            
            APEX_JSON.CLOSE_OBJECT;
        END LOOP;
        APEX_JSON.CLOSE_ARRAY;
        
        APEX_JSON.WRITE('total_users', V_COUNT);
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
    WHEN OTHERS THEN
        APEX_JSON.INITIALIZE_CLOB_OUTPUT;
        APEX_JSON.OPEN_OBJECT;
            APEX_JSON.WRITE('response_code', 500);
            APEX_JSON.WRITE('response_message', 'Unexpected error: ' || SQLERRM);
        APEX_JSON.CLOSE_OBJECT;
        HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XX_OTM_GET_CHAT_USERS;

   -- ========================================================================
   -- XX_OTM_GET_CONTAINER_REPAIR_STATUS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_CONTAINER_REPAIR_STATUS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_container_repair_status (
   p_container_nbr in varchar2
)
as
   v_shipment_xid    varchar2(100);
   v_url             varchar2(1000);
   v_response_clob   clob;
   v_jo              json_object_t;
   v_items           json_array_t;
   v_item            json_object_t;
   v_date_obj        json_object_t;
   v_event_date_str  varchar2(200);
   v_event_date      timestamp with time zone;
   v_status_code_gid varchar2(200);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   v_response_json   json_object_t;
   v_data_json       json_object_t;
   v_events_array    json_array_t;
   v_event_json      json_object_t;
   
   -- Type for storing events before sorting
   type t_event_rec is record (
         event_date     timestamp with time zone,
         status_code    varchar2(200),
         event_date_str varchar2(200)
   );
   type t_event_tab is
      table of t_event_rec index by pls_integer;
   l_events          t_event_tab;
   l_event_count     pls_integer := 0;
   l_temp_event      t_event_rec;
   l_swapped         boolean;
begin
   -- 1. Get Shipment XID
   begin
      select shipment_xid
        into v_shipment_xid
        from xxotm.xxotm_shipments_t
       where cont_no = p_container_nbr
         and rownum = 1;
   exception
      when no_data_found then
         v_response_json := json_object_t();
         v_response_json.put(
            'response_code',
            404
         );
         v_response_json.put(
            'response_message',
            'Container not found or no shipment associated'
         );
         htp.prn(v_response_json.to_clob);
         return;
   end;

   -- 2. Call OTM API
   v_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
            || v_shipment_xid
            || '/trackingEvents';
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   v_response_clob := apex_web_service.make_rest_request(
      p_url         => v_url,
      p_http_method => 'GET',
      p_credential_static_id => l_credential_static_id,
      p_wallet_path => xxotm_get_cfg('WALLET_PATH')
   );

   -- 3. Process Response
   if apex_web_service.g_status_code = 200 then
      v_jo := json_object_t.parse(v_response_clob);
      if v_jo.has('items') then
         v_items := v_jo.get_array('items');
         
         -- Collect all events
         for i in 0..v_items.get_size - 1 loop
            v_item := treat(v_items.get(i) as json_object_t);
            v_event_date := null;
            v_status_code_gid := null;
            v_event_date_str := null;
                
            -- Get Status Code
            if v_item.has('statusCodeGid') then
               v_status_code_gid := v_item.get_string('statusCodeGid');
            end if;
                
            -- Get Event Date (Check for both 'eventdate' and 'eventDate')
            v_date_obj := null;
            if v_item.has('eventdate') then
               v_date_obj := treat(v_item.get('eventdate') as json_object_t);
            elsif v_item.has('eventDate') then
               v_date_obj := treat(v_item.get('eventDate') as json_object_t);
            end if;

            if v_date_obj is not null then
               v_event_date_str := v_date_obj.get_string('value');
               begin
                  -- Handle potential 'Z' or timezone offsets
                  v_event_date := to_timestamp_tz ( replace(
                     v_event_date_str,
                     'Z',
                     '+00:00'
                  ),'YYYY-MM-DD"T"HH24:MI:SS.FFTZH:TZM' );
               exception
                  when others then
                     begin
                        v_event_date := to_timestamp_tz ( replace(
                           v_event_date_str,
                           'Z',
                           '+00:00'
                        ),'YYYY-MM-DD"T"HH24:MI:SSTZH:TZM' );
                     exception
                        when others then
                           v_event_date := null;
                     end;
               end;
            end if;
            
            -- Store event in collection (only repair-related events)
            if v_status_code_gid in ( 'NAQLEEN.ESTIMATION SENT',
                                      'NAQLEEN.APPROVAL RECEIVED',
                                      'NAQLEEN.APPROVAL DENIED',
                                      'NAQLEEN.REPAIR ORDER CREATED',
                                      'NAQLEEN.REPAIR COMPLETED' ) then
               l_event_count := l_event_count + 1;
               l_events(l_event_count).event_date := v_event_date;
               l_events(l_event_count).status_code := v_status_code_gid;
               if v_event_date is not null then
                  l_events(l_event_count).event_date_str := to_char(
                     v_event_date,
                     'YYYY-MM-DD"T"HH24:MI:SS"Z"'
                  );
               else
                  l_events(l_event_count).event_date_str := '';
               end if;
            end if;
         end loop;
      end if;
      
      -- Sort events by event_date ascending (bubble sort)
      if l_event_count > 1 then
         loop
            l_swapped := false;
            for i in 1..l_event_count - 1 loop
               -- Handle nulls: put nulls at the end
               if
                  l_events(i).event_date is null
                  and l_events(i + 1).event_date is not null
               then
                  l_temp_event := l_events(i);
                  l_events(i) := l_events(i + 1);
                  l_events(i + 1) := l_temp_event;
                  l_swapped := true;
               elsif
                  l_events(i).event_date is not null
                  and l_events(i + 1).event_date is not null
                  and l_events(i).event_date > l_events(i + 1).event_date
               then
                  l_temp_event := l_events(i);
                  l_events(i) := l_events(i + 1);
                  l_events(i + 1) := l_temp_event;
                  l_swapped := true;
               end if;
            end loop;
            exit when not l_swapped;
         end loop;
      end if;
      
      -- Build response JSON
      v_response_json := json_object_t();
      v_response_json.put(
         'response_code',
         200
      );
      v_response_json.put(
         'response_message',
         'Success'
      );
      v_data_json := json_object_t();
      v_data_json.put(
         'container_nbr',
         p_container_nbr
      );
      v_data_json.put(
         'shipment_xid',
         v_shipment_xid
      );
      
      -- Build events array
      v_events_array := json_array_t();
      for i in 1..l_event_count loop
         v_event_json := json_object_t();
         v_event_json.put(
            'status_code',
            l_events(i).status_code
         );
         v_event_json.put(
            'event_time',
            l_events(i).event_date_str
         );
         v_events_array.append(v_event_json);
      end loop;

      v_data_json.put(
         'events',
         v_events_array
      );
      v_data_json.put(
         'total_events',
         l_event_count
      );
      v_response_json.put(
         'data',
         v_data_json
      );
      htp.prn(v_response_json.to_clob);
   else
      v_response_json := json_object_t();
      v_response_json.put(
         'response_code',
         apex_web_service.g_status_code
      );
      v_response_json.put(
         'response_message',
         'Error calling OTM API'
      );
      htp.prn(v_response_json.to_clob);
   end if;

exception
   when others then
      v_response_json := json_object_t();
      v_response_json.put(
         'response_code',
         500
      );
      v_response_json.put(
         'response_message',
         sqlerrm
      );
      htp.prn(v_response_json.to_clob);
end xx_otm_get_container_repair_status;

   -- ========================================================================
   -- XX_OTM_GET_CUSTOMERINVENTORY   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_CUSTOMERINVENTORY.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customerinventory (
   p_customer in varchar2
)
as
   type record_type is record (
         cust_nbr          varchar2(50),
         cust_name         varchar2(100),
         container_nbr     varchar2(50),
         shipment_nbr      varchar2(50),
         item_description varchar2(50),
         item_code         varchar2(100),
         qty               varchar2(50),
         qty_uom           varchar2(10),
         CREATION_DATE           varchar2(10)
   );
   
   l_record           record_type;
   l_response         json_object_t;
   l_data_array       json_array_t;
   l_customer_obj     json_object_t;
   l_containers_array json_array_t;
   l_container_obj    json_object_t;
   l_items_array      json_array_t;
   l_item_obj         json_object_t;
   j                  apex_json.t_values;
   l_prev_customer    varchar2(100) := null;
   l_prev_container   varchar2(50) := null;

    -- Chunking variables
   l_final_clob       clob;
   l_offset           number := 1;
   l_amount           number := 32000;
   l_len              number;
   l_buffer           varchar2(32767);
   cursor c_data_cursor (
      p_customer varchar2
   ) is
   select cust_nbr,
          cust_name,
          container_nbr,
          shipment_nbr,
          item_description,
          item_code,
          qty,
          qty_uom,
          CREATION_DATE
     from xxotm_customer_inventory_t
    where ( p_customer is null
       or upper(cust_name) like '%'
                                || upper(p_customer)
                                || '%' )
    order by shipment_nbr;

begin
   l_response := json_object_t();
   l_data_array := json_array_t();
   open c_data_cursor(p_customer);
   loop
      fetch c_data_cursor into l_record;
      exit when c_data_cursor%notfound;

        -- Check if new customer
      if l_prev_customer is null
      or l_prev_customer != l_record.cust_name then
            -- Save previous customer object if exists
         if l_prev_customer is not null then
            l_customer_obj.put(
               'containers',
               l_containers_array
            );
            l_data_array.append(l_customer_obj);
         end if;

            -- Initialize new customer object
         l_customer_obj := json_object_t();
         l_customer_obj.put(
            'customer',
            l_record.cust_name
         );
         l_containers_array := json_array_t();
         l_prev_customer := l_record.cust_name;
         l_prev_container := null;
      end if;

        -- Check if new container
      if l_prev_container is null
      or l_prev_container != l_record.container_nbr then
            -- Save previous container object if exists
         if l_prev_container is not null then
            l_container_obj.put(
               'items',
               l_items_array
            );
            l_containers_array.append(l_container_obj);
         end if;

            -- Initialize new container object
         l_container_obj := json_object_t();
         l_container_obj.put(
            'container_nbr',
            l_record.container_nbr
         );
         l_container_obj.put(
            'shipment_nbr',
            l_record.shipment_nbr
         );
         l_container_obj.put(
            'stuffed_by',
            ''
         ); 
         l_container_obj.put(
            'stuffed_date',
            l_record.CREATION_DATE
         ); 
         
         l_items_array := json_array_t();
         l_prev_container := l_record.container_nbr;
      end if;

        -- Add item
      l_item_obj := json_object_t();
      l_item_obj.put(
         'item_description',
         l_record.item_description
      );
      l_item_obj.put(
         'item_code',
         l_record.item_code
      );
      l_item_obj.put(
         'quantity',
         l_record.qty
      );
      l_item_obj.put(
         'quantity_uom',
         l_record.qty_uom
      );
      l_items_array.append(l_item_obj);
   end loop;
   close c_data_cursor;

    -- Save last container and customer
   if l_prev_container is not null then
      l_container_obj.put(
         'items',
         l_items_array
      );
      l_containers_array.append(l_container_obj);
   end if;

   if l_prev_customer is not null then
      l_customer_obj.put(
         'containers',
         l_containers_array
      );
      l_data_array.append(l_customer_obj);
   end if;

   l_response.put(
      'response_code',
      200
   );
   l_response.put(
      'response_message',
      'Success'
   );
   l_response.put(
      'data',
      l_data_array
   );
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      l_response.get('response_code').to_number()
   );
   apex_json.write(
      'response_message',
      replace(
         l_response.get('response_message').to_string(),
         '"',
         ''
      )
   );
    
    -- Converting json string to table of values
    -- Changed to_string() to to_clob() to handle large data
   apex_json.parse(
      j,
      l_response.get('data').to_clob()
   );
   apex_json.write(
      'data',
      j
   );
   apex_json.close_object;

    -- Get the full CLOB
   l_final_clob := apex_json.get_clob_output;
   apex_json.free_output;

    -- Chunked Output
   l_len := dbms_lob.getlength(l_final_clob);
   l_offset := 1;
   l_amount := 32000; -- Chunk size

   while l_offset <= l_len loop
      dbms_lob.read(
         l_final_clob,
         l_amount,
         l_offset,
         l_buffer
      );
      htp.prn(l_buffer);
      l_offset := l_offset + l_amount;
   end loop;

exception
   when others then
      l_response := json_object_t();
      l_response.put(
         'response_code',
         400
      );
      l_response.put(
         'response_message',
         'ERROR WHILE EXECUTING METHOD: ' || sqlerrm
      );
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         l_response.get('response_code').to_number()
      );
      apex_json.write(
         'response_message',
         replace(
            l_response.get('response_message').to_string(),
            '"',
            ''
         )
      );
      apex_json.close_object;
        
        -- Simple output for error as it should be small
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_customerinventory;

   -- ========================================================================
   -- xx_otm_get_customer_bookings   [? / ?]
   -- source: db/work/XX_OTM_GET_CUSTOMER_BOOKINGS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customer_bookings (
   p_customer_name in varchar2,
   p_search_text   in varchar2 default null,
   p_shipment_name in varchar2 default null,
   p_user_id       in varchar2 default null
)
as
   v_location varchar2(100);
   l_cust     varchar2(200);
   c_max_rows constant pls_integer := 30;
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   l_cust := upper(replace(
      p_customer_name,
      'NAQLEEN.'
   ));
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_array('data');
   for r in (
      select st.booking_id
        from xxotm_shipments_t st
       where upper(st.liner_name) = l_cust
         and st.location = v_location
         and st.booking_id is not null
         and ( st.trip_status in ( 'TRIP_NOT_STARTED',
                                   'NAQLEEN.TRIP_NOT_STARTED' )
          or st.trip_status like '%TRIP_NOT_STARTED%' )
         and ( ( p_shipment_name is null
         and st.shipment_name in ( 'STORE_AS_IT_IS',
                                   'CRO',
                                   'LRO',
                                   'RELEASE_CFS',
                                   'CFS' ) )
          or ( p_shipment_name is not null
         and st.shipment_name = upper(p_shipment_name) ) )
         and ( p_search_text is null
          or upper(st.booking_id) like '%'
                                       || upper(p_search_text)
                                       || '%' )
       group by st.booking_id
       order by max(st.update_date) desc nulls last,
                st.booking_id
       fetch first c_max_rows rows only
   ) loop
      apex_json.write(r.booking_id);
   end loop;

   -- Finalize JSON payload
   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_customer_bookings;

   -- ========================================================================
   -- XX_OTM_GET_CUSTOMER_INVENTORY_CUSTOMERS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_CUSTOMER_INVENTORY_CUSTOMERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customer_inventory_customers (
   p_search_text in varchar2 default null
)
as
   -- API variables
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_base_url             varchar2(200) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments'
   ;
   l_items_count          number;
   -- Variables to hold extracted values
   l_customer_name        varchar2(200);
   l_customer_number      varchar2(200);
   l_refnum_items_count   number;
   l_qual_gid             varchar2(200);
   l_refnum_value         varchar2(200);
   l_attr2                varchar2(200);
   
   -- Collection to hold unique customers to avoid duplicates
   type t_cust_rec is record (
         customer_name   varchar2(200),
         customer_number varchar2(200)
   );
   type t_cust_tab is
      table of t_cust_rec index by varchar2(400); -- Keyed by customer_name + customer_number
   l_unique_customers     t_cust_tab;
   l_cust_key             varchar2(400);

   -- Clean function for customer name
   function clean_customer_name (
      p_name in varchar2
   ) return varchar2 is
   begin
      return replace(
         upper(p_name),
         'NAQLEEN.',
         ''
      );
   end;

begin
   apex_json.initialize_clob_output;
   apex_json.open_object;

   -- Construct URL
   l_url := l_base_url || '?q=';
   
   -- Status Filters
   l_url := l_url || 'statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and (statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED" or statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED")'
   ;
   
   -- Search Text Filter (if provided)
   if p_search_text is not null then
      l_url := l_url
               || ' and refnums.shipmentRefnumQualGid eq "NAQLEEN.CUS_NAME" and refnums.shipmentRefnumValue co "'
               || clean_customer_name(p_search_text)
               || '"';
   end if;

   -- Add fields to select to minimize payload (we need refnums for cus name and attribute2 for number/liner)
   l_url := l_url || ' &expand=refnums';
   
   -- Limit results - fetching more to find unique customers
   l_url := l_url || '&limit=50'; 

dbms_output.put_line(l_url);
   -- Headers
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')

      );

      if apex_web_service.g_status_code = 200 then
         apex_json.write(
            'response_code',
            200
         );
         apex_json.write(
            'response_message',
            'Success'
         );
         apex_json.parse(l_response_clob);
         l_items_count := apex_json.get_count('items');
         if l_items_count is null then
            l_items_count := 0;
         end if;
         for i in 1..l_items_count loop
            l_customer_name := null;
            l_customer_number := null;

            -- Get Customer Number from attribute2 (Liner Name)
            l_customer_number := upper(apex_json.get_varchar2(
               'items[%d].attribute2',
               i
            ));
            
            -- Get Customer Name from refnums
            l_refnum_items_count := apex_json.get_count(
               'items[%d].refnums.items',
               i
            );
            if l_refnum_items_count is not null then
               for j in 1..l_refnum_items_count loop
                  l_qual_gid := apex_json.get_varchar2(
                     'items[%d].refnums.items[%d].shipmentRefnumQualGid',
                     i,
                     j
                  );
                  if l_qual_gid = 'NAQLEEN.CUS_NAME' then
                     l_refnum_value := apex_json.get_varchar2(
                        'items[%d].refnums.items[%d].shipmentRefnumValue',
                        i,
                        j
                     );
                     l_customer_name := clean_customer_name(l_refnum_value);
                     exit; -- Found the name
                  end if;
               end loop;
            end if;

            if
               l_customer_name is not null
               and l_customer_number is not null
            then
               l_cust_key := l_customer_name
                             || '|'
                             || l_customer_number;
               if not l_unique_customers.exists(l_cust_key) then
                  l_unique_customers(l_cust_key).customer_name := l_customer_name;
                  l_unique_customers(l_cust_key).customer_number := l_customer_number;
               end if;
            end if;

         end loop;

         -- Output Data
         apex_json.open_array('data');
         l_cust_key := l_unique_customers.first;
         while l_cust_key is not null loop
            apex_json.open_object;
            apex_json.write(
               'customer_name',
               l_unique_customers(l_cust_key).customer_name
            );
            apex_json.write(
               'customer_number',
               l_unique_customers(l_cust_key).customer_number
            );
            apex_json.close_object;
            l_cust_key := l_unique_customers.next(l_cust_key);
         end loop;
         apex_json.close_array;
      else
         apex_json.write(
            'response_code',
            apex_web_service.g_status_code
         );
         apex_json.write(
            'response_message',
            'API Error: ' || apex_web_service.g_status_code
         );
         apex_json.open_array('data');
         apex_json.close_array;
      end if;

   exception
      when others then
         apex_json.write(
            'response_code',
            500
         );
         apex_json.write(
            'response_message',
            'Error: ' || sqlerrm
         );
         apex_json.open_array('data');
         apex_json.close_array;
   end;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end;

   -- ========================================================================
   -- XX_OTM_GET_CUSTOMER_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_CUSTOMER_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customer_shipments (
   p_customer_name in varchar2,
   p_search_text in varchar2,
   p_page_num      in number default 0
)
as
    -- Last Updated Date : 18-Dec-2025
    -- Last Updated By : Madhan
    -- Description : updated hardcoded credentials to web credentials
   l_url           varchar2(4000);
   l_response_clob clob;
   l_count         number;
   l_shipment_xid  varchar2(50);
   l_status_value  varchar2(100);
   l_shipment_name varchar2(200);
   l_cont_no       varchar2(100);
   l_offset        number;
   l_limit         number := 25;
   l_date_filter   varchar2(50);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   -- Variables for JSON parsing
   l_items_count   number;
begin
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_array('data');
   -- Calculate offset
   l_offset := p_page_num * l_limit;
   
   -- Calculate date filter (yesterday)
   l_date_filter := to_char(
      sysdate - 1,
      'YYYY-MM-DD"T"HH24:MI:SS"Z"'
   );
   -- Construct API URL with filters
   -- Base URL
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/?q='
   ;
   
   -- Filters
   l_url := l_url
            || 'attribute1 eq "TERMINAL" and '
            || 'perspective eq "B" and '
            || 'statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and (statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED" or statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED") and (shipmentName co "DESTUFFING" or shipmentName co "STORE_AS_IT_IS"  or shipmentName co "OFFLOADING_LCL" )'
            || ' and attribute2 eq "NAQLEEN.'
            || replace( p_customer_name,'NAQLEEN.','')|| '"'||' and '||'shipmentXid co "'||upper(p_search_text)||'"';
            
   -- Pagination
   l_url := l_url
            || '&offset='
            || l_offset;

   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url         => l_url,
         p_http_method => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
      -- Parse JSON Response
      apex_json.parse(l_response_clob);
      -- Check if items exist
      l_items_count := apex_json.get_count(p_path => 'items');
      for i in 1..l_items_count loop
        
   
             
             -- If found, write to JSON
            apex_json.open_object;
            apex_json.write(
               'shipment_nbr',
              apex_json.get_varchar2(
            p_path => 'items[%d].shipmentXid',
            p0     => i
         )
            );
            apex_json.write(
               'shipment_name',
              apex_json.get_varchar2(
            p_path => 'items[%d].shipmentName',
            p0     => i
         )
            );
            apex_json.write(
               'container_nbr',
               apex_json.get_varchar2(
            p_path => 'items[%d].attribute3',
            p0     => i
         )
            );
             
           
            apex_json.close_object;
         
      end loop;
   exception
      when others then
         apex_json.open_object;
         apex_json.write(
            'error',
            'API Request Failed: ' || sqlerrm
         );
         apex_json.close_object;
   end;
   
   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xx_otm_get_customer_shipments;

   -- ========================================================================
   -- XX_OTM_GET_CUSTOMER_STOCK   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_CUSTOMER_STOCK.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customer_stock (
   p_customer_name in varchar2 default null,
   p_item_code     in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 27-Jan-2026
   -- Description  : Gets customer stock items based on customer number and optional item code
   -- Update       : Added CLOB chunking for large data sets (ORA-06502 fix) AND hardened types

   -- Variables for chunking the output
   l_clob          clob;
   l_offset        number := 1;
   l_chunk_size    number := 8000;
   l_length        number;

   cursor c_stock is
   select cust_name,
          cust_nbr,
          item_code,
          item_description,
          nvl(available_qty, 0) as available_qty,
          qty_uom,
          nvl(net_weight, 0) as net_weight,
          weight_uom
     from xxotm_customer_stock_t
    where ( p_customer_name is null
       or trim(p_customer_name) is null
       or upper(cust_name) like '%' || upper(trim(p_customer_name)) || '%' )
      and ( p_item_code is null
       or trim(p_item_code) is null
       or upper(item_code) like '%' || upper(trim(p_item_code)) || '%' )
      and available_qty > 0
      and xxotm_customer_stock_t.location = v_location
    order by item_code;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.open_array('data');
   
   for r in c_stock loop
      apex_json.open_object;
      
      -- Force String conversion to prevent hidden NULL crashes
      apex_json.write('cust_name',        nvl(to_char(r.cust_name), ' '));
      apex_json.write('cust_nbr',         nvl(to_char(r.cust_nbr), ' '));
      apex_json.write('item_code',        nvl(to_char(r.item_code), ' '));
      apex_json.write('item_description', nvl(to_char(r.item_description), ' '));
      
      -- Force Numeric conversion
      apex_json.write('available_qty',    r.available_qty);
      apex_json.write('qty_uom',          nvl(to_char(r.qty_uom), ' '));
      apex_json.write('net_weight',       r.net_weight);
      apex_json.write('weight_uom',       nvl(to_char(r.weight_uom), ' '));
      
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   
   -- Add response metadata
   apex_json.write('response_code', 200);
   apex_json.write('response_message', 'Success');
   apex_json.close_object;
   
   -- ==========================================
   -- CHUNKED OUTPUT FIX (Solves 32K buffer limit)
   -- ==========================================
   l_clob := apex_json.get_clob_output;
   l_length := dbms_lob.getlength(l_clob);

   while l_offset <= l_length loop
      htp.prn(dbms_lob.substr(l_clob, l_chunk_size, l_offset));
      l_offset := l_offset + l_chunk_size;
   end loop;
   
   apex_json.free_output;

exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      
      -- If the error was so generic that the error payload itself is safe, print it
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_customer_stock;

   -- ========================================================================
   -- XX_OTM_GET_CUSTOMER_STOCK_ITEMS_SEARCH   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_CUSTOMER_STOCK_ITEMS_SEARCH.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_customer_stock_items_search (
   p_customer_nbr in varchar2,
   p_search_text  in varchar2 default null,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   -- Created Date : 27-Jan-2026
   -- Description  : Gets customer stock items based on customer number and optional item code search

 v_location varchar2(100);
   cursor c_stock is
   select cust_name,
          cust_nbr,
          item_code,
          available_qty
     from xxotm_customer_stock_t
    where cust_nbr = p_customer_nbr
      and ( p_search_text is null
       or upper(item_code) like '%'
                                || upper(p_search_text)
                                || '%' )
        and available_qty >0
        and xxotm_customer_stock_t.location = v_location
    order by item_code fetch first 100 rows only;

begin
 v_location := xx_get_user_location(p_user_id);
 -- Location is mandatory. xx_get_user_location returns NULL when
 -- req_location_id is absent, malformed, or not permitted for this user;
 -- it no longer falls back to a default site. Continuing on NULL would
 -- filter on "location = NULL" and return an empty result set -- an empty
 -- screen with no error, which is worse than a refusal.
 if v_location is null then
    xxotm_location_required;
    return;
 end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.open_array('data');
   for r in c_stock loop
      apex_json.open_object;
      apex_json.write(
         'item_code',
         r.item_code
      );
      apex_json.write(
         'available_qty',
         r.available_qty
      );
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   
   -- Add response metadata
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_customer_stock_items_search;

   -- ========================================================================
   -- XX_OTM_GET_DESTUFFED_CONTAINERS   [4-test-only / PORT]
   -- source: db/work/XX_OTM_GET_DESTUFFED_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_destuffed_containers (
   p_booking_id in varchar2,
   p_search_text in varchar2 DEFAULT NULL,
   p_user_id     in varchar2 default null
)
as
   -- Declared bare, assigned after BEGIN: an exception during declaration
   -- elaboration escapes this block's own handler.
   v_location varchar2(100);

    -- Last Updated Date : 23-Feb-2026
    -- Description : Returns destuffed containers from customer_inventory
    --               matching the given booking_id, along with shipment_name.
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;

   declare
      l_found boolean := false;
      
      cursor c_containers is
         select distinct
                ci.container_nbr,
                ci.shipment_nbr,
                co.shipment_name,
                ci.cust_name
           from xxotm_customer_inventory_t ci,  XXOTM_CONTAINER_INVENTORY_T co 
          where  ci.shipment_nbr = co.INBOUND_SHIPMENT_NBR and CO.shipment_name = 'DESTUFFING'
           and co.booking_id = p_booking_id and ci.RCVD_QTY is not null
           and (p_search_text is null or  upper(ci.container_nbr) like '%'|| upper(p_search_text)||'%')
            and (is_cross_stuffed is null or is_cross_stuffed !=1 )
            and ci.location = v_location 
          order by ci.container_nbr;
   begin
      for r in c_containers loop
         if not l_found then
            l_found := true;
            apex_json.write('response_message', 'Success');
            apex_json.write('response_code', 200);
            apex_json.open_array('data');
         end if;

         apex_json.open_object;
         apex_json.write('container_nbr',  r.container_nbr);
         apex_json.write('shipment_nbr',   r.shipment_nbr);
         apex_json.write('shipment_name',  r.shipment_name);
         apex_json.write('customer_name',  r.cust_name);
         apex_json.close_object;
      end loop;

      if l_found then
         apex_json.close_array;
      else
         apex_json.write('response_message', 'No Data Found');
         apex_json.write('response_code', 404);
         apex_json.open_array('data');
         apex_json.close_array;
      end if;
   end;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.write('response_code', 500);
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_destuffed_containers;

   -- ========================================================================
   -- XX_OTM_GET_DESTUFFED_ITEMS   [4-test-only / PORT]
   -- source: db/work/XX_OTM_GET_DESTUFFED_ITEMS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_destuffed_items (
   p_shipment_nbr in varchar2,
   p_user_id      in varchar2 default null
)
as
   -- Declared bare, assigned after BEGIN: an exception during declaration
   -- elaboration escapes this block's own handler.
   v_location varchar2(100);

    -- Last Updated Date : 23-Feb-2026
    -- Description : Returns all items from customer_inventory for a given destuffed shipment.
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;

   declare
      l_found        boolean := false;
      l_cont_no      varchar2(100);
      l_customer     varchar2(200);

      cursor c_items is
         select 
                ci.item_code,
                ci.item_description,
                ci.qty
           from xxotm_customer_inventory_t ci
          where ci.shipment_nbr = p_shipment_nbr
           and ci.location = v_location
          order by ci.item_code;
   begin
      for r in c_items loop
         if not l_found then
            l_found := true;

            apex_json.write('response_message', 'Success');
            apex_json.write('response_code', 200);
            apex_json.open_object('data');
            apex_json.open_array('items');
         end if;

         apex_json.open_object;
         apex_json.write('item_code',        r.item_code);
         apex_json.write('item_description', r.item_description);
         apex_json.write('quantity',          r.qty);
         apex_json.close_object;
      end loop;

      if l_found then
         apex_json.close_array;
         apex_json.close_object; -- close data
      else
         apex_json.write('response_message', 'No Data Found');
         apex_json.write('response_code', 404);
         apex_json.open_object('data');
         apex_json.close_object;
      end if;
   end;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.write('response_code', 500);
      apex_json.open_object('data');
      apex_json.close_object;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_destuffed_items;

   -- ========================================================================
   -- XX_OTM_GET_DESTUFFING_CONTAINERS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_DESTUFFING_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_destuffing_containers (
   p_search_text in varchar2 default null,
   p_user_id     in varchar2 default null
)
as
   -- Declared bare and assigned after the PROCEDURE's own BEGIN. The automated
   -- graft skipped this file because the first "^BEGIN$" belongs to the nested
   -- process_shipments, and assigning there would leave v_location NULL on the
   -- first call.
   v_location varchar2(100);
    -- Last Updated Date : 23-Jan-2026
    -- Description       : Live OTM API version.
    --                     1. DESTUFFING: Status TRIP_STARTED
    --                     2. OFFLOADING_LCL: Status NOT COMPLETED/CANCELLED + Has TASK_ASSIGNED event
    -- Update            : Added shipment_name to response.
    -- Update            : Added global sorting by update_date desc (merging two lists).

   l_api_base_url         varchar2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'

   ;
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_item_count           number;
   l_cont_no              varchar2(100);
   l_shipment_gid         varchar2(100);
   l_shipment_name        varchar2(100);
   l_update_date_str      varchar2(100);
   
   -- OFFLOADING_LCL specific
   l_events_count         number;
   l_event_gid            varchar2(200);
   l_has_task_assigned    boolean;
   type t_res_rec is record (
         container_nbr varchar2(100),
         shipment_nbr  varchar2(100),
         shipment_name varchar2(100),
         update_date   varchar2(100) -- Clean ISO string for sorting
   );
   type t_res_tab is
      table of t_res_rec;
   l_valid_data           t_res_tab := t_res_tab();
   l_temp_rec             t_res_rec;
   l_unique_check         varchar2(32767) := '|';

   procedure process_shipments (
      p_shipment_type in varchar2
   ) is
   begin
      -- Construct URL based on type
      if p_shipment_type = 'DESTUFFING' then
          -- CALL 1: DESTUFFING + TRIP_STARTED
         l_url := l_api_base_url
                  || '?q=perspective eq "B" and attribute1 eq "TERMINAL" and shipmentName eq "DESTUFFING"'
                  || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"'
                  || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
                  || ' and refnums.shipmentRefnumValue eq ' || v_location;
      else
          -- CALL 2: OFFLOADING_LCL + Not Completed/Cancelled + Expand Events
         l_url := l_api_base_url
                  || '?q=perspective eq "B" and attribute1 eq "TERMINAL" and shipmentName eq "OFFLOADING_LCL"'
                  || ' and statuses.statusValueGid ne "NAQLEEN.TRIP_COMPLETED" and statuses.statusValueGid ne "NAQLEEN.TRIP_CANCELLED"'
                  || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
                  || ' and refnums.shipmentRefnumValue eq ' || v_location
                  || '&expand=trackingEvents';
      end if;

      -- Add search filter
      if p_search_text is not null then
         l_url := l_url
                  || ' and attribute3 co "'
                  || apex_util.url_encode(p_search_text)
                  || '"';
      end if;
      
      -- Limit and Sorting (Sorting here helps, but merging ruins it, so we sort again later)
      l_url := l_url || '&limit=200&orderBy=updateDate:desc';

      -- Call API
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      begin
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
      exception
         when others then
            return;
      end;

      if
         apex_web_service.g_status_code = 200
         and l_response_clob is not null
      then
         apex_json.parse(l_response_clob);
         l_item_count := nvl(
            apex_json.get_count('items'),
            0
         );
         for i in 1..l_item_count loop
            l_cont_no := apex_json.get_varchar2(
               'items[%d].attribute3',
               i
            );
            l_shipment_gid := apex_json.get_varchar2(
               'items[%d].shipmentXid',
               i
            );
            l_shipment_name := apex_json.get_varchar2(
               'items[%d].shipmentName',
               i
            );
            l_update_date_str := apex_json.get_varchar2(
               'items[%d].updateDate.value',
               i
            );
            
            -- Validation Logic
            l_has_task_assigned := false;
            if p_shipment_type = 'DESTUFFING' then
               l_has_task_assigned := true;
            elsif p_shipment_type = 'OFFLOADING_LCL' then
               l_events_count := nvl(
                  apex_json.get_count(
                     'items[%d].trackingEvents.items',
                     i
                  ),
                  0
               );
               for j in 1..l_events_count loop
                  l_event_gid := apex_json.get_varchar2(
                     'items[%d].trackingEvents.items[%d].quickEventGid',
                     i,
                     j
                  );
                  if l_event_gid is null then
                     l_event_gid := apex_json.get_varchar2(
                        'items[%d].trackingEvents.items[%d].trackingEventXid',
                        i,
                        j
                     );
                  end if;

                  if
                     l_event_gid is not null
                     and ( l_event_gid = 'NAQLEEN.TASK_ASSIGNED'
                     or l_event_gid like '%TASK_ASSIGNED' )
                  then
                     l_has_task_assigned := true;
                     exit;
                  end if;
               end loop;
            end if;

            -- Add if Valid and Unique
            if
               l_has_task_assigned
               and l_cont_no is not null
               and instr(
                  l_unique_check,
                  '|'
                  || l_cont_no
                  || '|'
               ) = 0
            then
               l_shipment_gid := replace(
                  l_shipment_gid,
                  'NAQLEEN.',
                  ''
               ); -- Clean XID
               l_valid_data.extend;
               l_valid_data(l_valid_data.count).container_nbr := l_cont_no;
               l_valid_data(l_valid_data.count).shipment_nbr := l_shipment_gid;
               l_valid_data(l_valid_data.count).shipment_name := l_shipment_name;
               l_valid_data(l_valid_data.count).update_date := l_update_date_str;
               l_unique_check := l_unique_check
                                 || l_cont_no
                                 || '|';
            end if;
         end loop;
      end if;
   end;

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

    -- 1. Process DESTUFFING
   process_shipments('DESTUFFING');

    -- 2. Process OFFLOADING_LCL
   process_shipments('OFFLOADING_LCL');

    -- 3. Perform Bubble Sort on Combined Data (Desc by update_date)
   if l_valid_data.count > 1 then
      for i in 1..l_valid_data.count - 1 loop
         for j in i + 1..l_valid_data.count loop
                -- String comparison of ISO timestamps works for sorting
                -- We want DESCENDING order (Newest first), so if i < j, swap
            if nvl(
               l_valid_data(i).update_date,
               ''
            ) < nvl(
               l_valid_data(j).update_date,
               ''
            ) then
               l_temp_rec := l_valid_data(i);
               l_valid_data(i) := l_valid_data(j);
               l_valid_data(j) := l_temp_rec;
            end if;
         end loop;
      end loop;
   end if;

    -- 4. Build JSON Response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_valid_data.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_valid_data.count loop
         apex_json.open_object;
         apex_json.write(
            'container_nbr',
            l_valid_data(i).container_nbr
         );
         apex_json.write(
            'shipment_nbr',
            l_valid_data(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_valid_data(i).shipment_name
         );
         -- apex_json.write('update_date', l_valid_data(i).update_date); -- Optional debug
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_destuffing_containers;

   -- ========================================================================
   -- XX_OTM_GET_DESTUFFING_CONTAINER_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_DESTUFFING_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_destuffing_container_details (
   p_container_no in varchar2,
   p_user_id in varchar2 default null
)
as
    v_location varchar2(100);
    -- Created Date : 05-Jan-2026
    -- Description  : Fetches packing list details for a destuffing container.
    --               Mandatory Status Check: Confirms TRIP_STARTED in OTM via live API.

   l_api_base_url         varchar2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'

   ;
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_item_count           number;
   l_is_verified          boolean := false;
   l_shipment_nbr         varchar2(100);
    
    -- Record for cursor
   type t_record is record (
         container_nbr    varchar2(50),
         cust_name        varchar2(100),
         cust_nbr         varchar2(100),
         item_code        varchar2(20),
         item_description varchar2(200),
         qty              number,
         qty_uom          varchar2(10)
   );
   l_rec                  t_record;
   l_found_local          boolean := false;
   
   -- Variables for fallback when no items found
   l_fallback_cust_name   varchar2(200);
   l_fallback_cust_nbr    varchar2(100);

    -- JSON buffers
   l_data_obj             json_object_t;
   l_items_array          json_array_t;
   l_item_obj             json_object_t;
   j                      apex_json.t_values;

    -- Cursor for local data
   cursor c_items (
      p_shipment_nbr varchar2
   ) is
   select container_nbr,
          cust_name,
          cust_nbr,
          item_code,
          item_description,
          qty,
          qty_uom
     from xxotm_customer_inventory_t
    where container_nbr = p_container_no
      and shipment_nbr = p_shipment_nbr
       and xxotm_customer_inventory_t.location = v_location
    order by item_code;

begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- 1. LIVE VERIFICATION: Check OTM for active TRIP_STARTED status
   l_url := l_api_base_url
            || '?q=perspective eq "B" and attribute1 eq "TERMINAL" and shipmentName eq "DESTUFFING"'
            || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"'
            || ' and attribute3 eq "'
            || p_container_no
            || '"';

   begin
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );

      if l_response_clob is not null then
         apex_json.parse(l_response_clob);
         l_item_count := apex_json.get_count('items');
         if nvl(
            l_item_count,
            0
         ) > 0 then
            l_is_verified := true;
            l_shipment_nbr := apex_json.get_varchar2('items[1].shipmentXid');
         end if;
      end if;
   exception
      when others then
         dbms_output.put_line('VERIFICATION API ERROR: ' || sqlerrm);
   end;

    -- 2. GENERATE JSON RESPONSE
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_is_verified then
      l_data_obj := json_object_t();
      l_items_array := json_array_t();
      open c_items(l_shipment_nbr);
      loop
         fetch c_items into l_rec;
         exit when c_items%notfound;
         if not l_found_local then
            l_found_local := true;
            l_data_obj.put(
               'container_number',
               l_rec.container_nbr
            );
            l_data_obj.put(
               'customer_name',
               l_rec.cust_name
            );
            l_data_obj.put(
               'customer_nbr',
               l_rec.cust_nbr
            );
            l_data_obj.put(
               'shipment_nbr',
               l_shipment_nbr
            );
         end if;

         l_item_obj := json_object_t();
         l_item_obj.put(
            'item_code',
            l_rec.item_code
         );
         l_item_obj.put(
            'description',
            l_rec.item_description
         );
         l_item_obj.put(
            'actual_quantity',
            l_rec.qty
         );
         l_item_obj.put(
            'quantity_uom',
            l_rec.qty_uom
         );
         l_items_array.append(l_item_obj);
      end loop;
      close c_items;
      
      -- If local items found, return them
      if l_found_local then
         l_data_obj.put(
            'items',
            l_items_array
         );
         apex_json.write(
            'response_code',
            200
         );
         apex_json.write(
            'response_message',
            'Success'
         );
         apex_json.parse(
            j,
            l_data_obj.to_string()
         );
         apex_json.write(
            'data',
            j
         );
      else
         -- NO ITEMS FOUND: Fetch header details from shipments\/order movements tables
         begin
            select distinct s.customer_name,
                            s.liner_name
              into
               l_fallback_cust_name,
               l_fallback_cust_nbr
              from xxotm_shipments_t s,
                   xxotm_order_movements_t o
             where s.shipment_xid = o.shipment_xid
               and s.location = v_location
               and s.shipment_xid = l_shipment_nbr
             fetch first 1 rows only;
         exception
            when others then
               l_fallback_cust_name := null;
               l_fallback_cust_nbr := null;
         end;
         
         -- Constuct response with empty items array
         l_data_obj.put(
            'container_number',
            p_container_no
         );
         l_data_obj.put(
            'customer_name',
            l_fallback_cust_name
         );
         l_data_obj.put(
            'customer_nbr',
            l_fallback_cust_nbr
         );
         l_data_obj.put(
            'shipment_nbr',
            l_shipment_nbr
         );
         l_data_obj.put(
            'items',
            json_array_t()
         ); -- Empty Array

         apex_json.write(
            'response_code',
            200
         );
         apex_json.write(
            'response_message',
            'Success (No Items)'
         );
         apex_json.parse(
            j,
            l_data_obj.to_string()
         );
         apex_json.write(
            'data',
            j
         );
      end if;
   else
      apex_json.write(
         'response_code',
         403
      );
      apex_json.write(
         'response_message',
         'Verification Failed: Container is not in TRIP_STARTED status for Destuffing in OTM'
      );
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if c_items%isopen then
         close c_items;
      end if;
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_destuffing_container_details;

   -- ========================================================================
   -- XX_OTM_GET_DESTUFFING_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_DESTUFFING_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_destuffing_shipments (
   p_search_text in varchar2 default null
)
as
   -- Created Date : 23-Jan-2026
   -- Description  : Gets verified shipment numbers for active DESTUFFING tasks only.
   --                Logic:
   --                1. Fetch candidate shipment IDs from local assignment table.
   --                2. Call OTM API with shipmentName=DESTUFFING filter.
   --                3. Validate Status (TRIP_STARTED).

   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_shipment_list        varchar2(32767) := '[';
   l_shipment_count       number := 0;
   l_api_shipment_count   number;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   
   -- Loop vars
   l_sh_xid               varchar2(100);
   l_sh_name              varchar2(100);
   l_ct_nbr               varchar2(100);
   l_tr_nbr               varchar2(100);
   l_dr_name              varchar2(200);
   l_pw_unt               varchar2(200);
   
   -- Validation vars
   l_status_count         number;
   l_status_gid           varchar2(200);
   l_status_val           varchar2(200);
   l_is_valid             boolean;
   l_trip_status_val      varchar2(200);
   
   -- Output Collection
   type t_shpmt_rec is record (
         shipment_nbr  varchar2(100),
         shipment_name varchar2(100),
         container_nbr varchar2(100),
         truck_nbr     varchar2(100),
         driver_name   varchar2(200)
   );
   type t_shpmt_tab is
      table of t_shpmt_rec;
   l_verified_shipments   t_shpmt_tab := t_shpmt_tab();
   cursor c_assignments is
   select shipment_nbr
     from xxotm_task_assignment_t
    where shipment_nbr is not null
      and ( p_search_text is null
       or upper(shipment_nbr) like '%'
                                   || upper(p_search_text)
                                   || '%' )
    group by shipment_nbr
    order by max(assigned_date) desc;

begin
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- 1. Collect candidate shipments from local assignment table
   for r in c_assignments loop
      l_shipment_count := l_shipment_count + 1;
      if l_shipment_count > 1 then
         l_shipment_list := l_shipment_list || ',';
      end if;
      l_shipment_list := l_shipment_list
                         || '"'
                         || r.shipment_nbr
                         || '"';
      
      -- Batch limit
      if l_shipment_count >= 100 then
         exit;
      end if;
   end loop;
   l_shipment_list := l_shipment_list || ']';
   if l_shipment_count > 0 then
      -- 2. Call OTM API 
      -- Filter: IDs in list AND shipmentName eq DESTUFFING
      -- Expand: statuses
      l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
               || '?q=shipmentName eq "DESTUFFING" and shipmentXid in '
               || l_shipment_list
               || '&limit=200&expand=statuses';
      begin
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         if
            apex_web_service.g_status_code = 200
            and l_response_clob is not null
         then
            apex_json.parse(l_response_clob);
            l_api_shipment_count := nvl(
               apex_json.get_count('items'),
               0
            );
            
            -- 3. Verify each shipment
            for i in 1..l_api_shipment_count loop
               l_sh_xid := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );
               l_sh_name := apex_json.get_varchar2(
                  'items[%d].shipmentName',
                  i
               ); -- Should be DESTUFFING
               
               -- A. Get Trip Status
               l_trip_status_val := null;
               l_status_count := nvl(
                  apex_json.get_count(
                     'items[%d].statuses.items',
                     i
                  ),
                  0
               );
               for s in 1..l_status_count loop
                  l_status_gid := apex_json.get_varchar2(
                     'items[%d].statuses.items[%d].statusTypeGid',
                     i,
                     s
                  );
                  if l_status_gid = 'NAQLEEN.TRIP_STATUS' then
                     l_status_val := apex_json.get_varchar2(
                        'items[%d].statuses.items[%d].statusValueGid',
                        i,
                        s
                     );
                     l_trip_status_val := l_status_val;
                     exit;
                  end if;
               end loop;

               -- B. Validation Logic (TRIP_STARTED)
               l_is_valid := false;
               if l_trip_status_val = 'NAQLEEN.TRIP_STARTED' then
                  l_is_valid := true;
               end if;

               -- 4. Add if Valid
               if l_is_valid then
                  l_ct_nbr := apex_json.get_varchar2(
                     'items[%d].attribute3',
                     i
                  );
                  l_tr_nbr := apex_json.get_varchar2(
                     'items[%d].attribute7',
                     i
                  );
                  l_dr_name := apex_json.get_varchar2(
                     'items[%d].attribute8',
                     i
                  );
                  
                  -- Truck Fallback
                  if l_tr_nbr is null then
                     l_pw_unt := apex_json.get_varchar2(
                        'items[%d].powerUnitGid',
                        i
                     );
                     if l_pw_unt is not null then
                        l_tr_nbr := replace(
                           l_pw_unt,
                           'NAQLEEN.',
                           ''
                        );
                     end if;
                  end if;
                  
                  -- Container Fallback
                  if l_ct_nbr is null then
                     begin
                        select container_nbr
                          into l_ct_nbr
                          from xxotm_customer_inventory_t
                         where shipment_nbr = l_sh_xid
                         fetch first 1 rows only;
                     exception
                        when others then
                           l_ct_nbr := null;
                     end;
                  end if;

                  l_verified_shipments.extend;
                  l_verified_shipments(l_verified_shipments.count).shipment_nbr := l_sh_xid;
                  l_verified_shipments(l_verified_shipments.count).shipment_name := l_sh_name;
                  l_verified_shipments(l_verified_shipments.count).container_nbr := l_ct_nbr;
                  l_verified_shipments(l_verified_shipments.count).truck_nbr := l_tr_nbr;
                  l_verified_shipments(l_verified_shipments.count).driver_name := l_dr_name;
               end if;
            end loop;
         end if;
      exception
         when others then
            null;
      end;
   end if;
   
   -- 5. Build JSON Response
   if l_verified_shipments.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_verified_shipments.count loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_verified_shipments(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_verified_shipments(i).shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_verified_shipments(i).container_nbr
         );
         apex_json.write(
            'truck_nbr',
            l_verified_shipments(i).truck_nbr
         );
         apex_json.write(
            'driver_name',
            l_verified_shipments(i).driver_name
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No active destuffing shipments found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_destuffing_shipments;

   -- ========================================================================
   -- XX_OTM_GET_EMPTY_CONTAINERS_BY_CUST   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_EMPTY_CONTAINERS_BY_CUST.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_empty_containers_by_cust (
   p_cust_nbr       in varchar2 default null,
   p_container_type in varchar2 default null,
   p_flag           in varchar2 default 'TYPE',
   p_search_text    in varchar2 default null,
   p_shipment_nbr   in varchar2 default null,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   -- Created Date : 04-Jan-2026
   -- Description  : Get empty container types or container numbers for a specified customer.
   --                Modes: 'TYPE' (unique types), 'CONTAINER' (container numbers for a type),
   --                       'CUSTOMER' (unique customers for a shipment).
   --                Filters: shipment_name = 'INBOUND_CONTAINER', stored but not released.
   --                Added Filter: load_status in ('E', 'F') - COMMENTED OUT
   l_cust_nbr  varchar2(100);
   v_location varchar2(100);
   -- Collection for Types/Containers
   type t_data_tab is
      table of varchar2(100);
   l_data_list t_data_tab := t_data_tab();
   
   -- Record and Collection for Customers
   type t_cust_rec is record (
         cust_name varchar2(200),
         cust_nbr  varchar2(100)
   );
   type t_cust_tab is
      table of t_cust_rec;
   l_cust_list t_cust_tab := t_cust_tab();
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if p_cust_nbr = 'NAQLEEN' then
      l_cust_nbr := 'BDL-TERMINAL';
   else
      l_cust_nbr := p_cust_nbr;
   end if;

   if upper(p_flag) = 'TYPE' then
      -- Fetch unique container types for the customer
      select distinct container_type
      bulk collect
        into l_data_list
        from xxotm_container_inventory_t
       where shipment_name = 'INBOUND_CONTAINER'
         and container_stored_time is not null
         and container_released_time is null
         and cust_nbr = upper(l_cust_nbr)
         and container_type is not null
         and ( load_status is NULL OR load_status =''
          or upper(load_status) != 'LOADED' )
          and xxotm_container_inventory_t.location = v_location
       order by container_type;

   elsif upper(p_flag) = 'CONTAINER' then
      -- Fetch container numbers for a specific type and optional search text
      select distinct container_nbr
      bulk collect
        into l_data_list
        from xxotm_container_inventory_t
       where shipment_name = 'INBOUND_CONTAINER'
         and container_stored_time is not null
         and container_released_time is null
         and cust_nbr = upper(l_cust_nbr)
         and ( p_container_type is null
          or container_type = p_container_type )
         and ( p_search_text is null
          or upper(container_nbr) like '%'
                                       || upper(p_search_text)
                                       || '%' )
         and ( load_status is null
          or upper(load_status) != 'LOADED' )
          and xxotm_container_inventory_t.location = v_location
       order by container_nbr;

   elsif upper(p_flag) = 'CUSTOMER' then
      -- Fetch distinct customers for a specific shipment
      -- Must adhere to same Empty conditions
      select distinct cust_name,
                      cust_nbr
      bulk collect
        into l_cust_list
        from xxotm_container_inventory_t
       where shipment_name = 'INBOUND_CONTAINER'
         and container_stored_time is not null
         and container_released_time is null
         and ( cust_nbr in (select distinct cust_nbr from xxotm_container_inventory_t where inbound_shipment_nbr = p_shipment_nbr and xxotm_container_inventory_t.location = v_location)
          or cust_nbr = 'BDL-TERMINAL' )
         and ( load_status is NULL OR load_status =''
          or upper(load_status) != 'LOADED' )
          and xxotm_container_inventory_t.location = v_location
       order by cust_name;
   end if;

   -- Build JSON Response
   if l_data_list.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_data_list.count loop
         apex_json.write(l_data_list(i));
      end loop;
      apex_json.close_array;
   elsif l_cust_list.count > 0 then
      -- Response for CUSTOMER flag (Array of Objects)
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_cust_list.count loop
         apex_json.open_object;
         apex_json.write(
            'cust_name',
            l_cust_list(i).cust_name
         );
         apex_json.write(
            'cust_nbr',
            l_cust_list(i).cust_nbr
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_empty_containers_by_cust;

   -- ========================================================================
   -- XX_OTM_GET_GATE_IN_TRUCKS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_GATE_IN_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_gate_in_trucks (
   p_search_text in varchar2 default null,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_count number;
   cursor c_trucks( v_location varchar2) is
   select vm.truck_nbr
     from xxotm_vehicle_master_t vm
    where vm.entry_time is not null
      and vm.exit_time is null
      and ( vm.status = 'gate_in'
       or vm.status like '%INSPECTED%' ) and ( p_search_text is null
       or upper(truck_nbr) like '%'
                                || upper(p_search_text)
                                || '%' ) and vm.location = v_location
                                order BY vm.ENTRY_TIME DESC;
       v_location varchar2(100);
begin
       v_location := xx_get_user_location(p_user_id);
       -- Location is mandatory. xx_get_user_location returns NULL when
       -- req_location_id is absent, malformed, or not permitted for this user;
       -- it no longer falls back to a default site. Continuing on NULL would
       -- filter on "location = NULL" and return an empty result set -- an empty
       -- screen with no error, which is worse than a refusal.
       if v_location is null then
          xxotm_location_required;
          return;
       end if;
    -- Check if data exists
   select count(*)
     into l_count
     from xxotm_vehicle_master_t
    where entry_time is not null
      and exit_time is null
      and ( status = 'gate_in'
       or status like '%INSPECTED%' ) and xxotm_vehicle_master_t.location = v_location
      and ( p_search_text is null
       or upper(truck_nbr) like '%'
                                || upper(p_search_text)
                                || '%' );

   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_count = 0 then
      apex_json.write(
         'response_message',
         'No Data Found'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.open_array('data');
      apex_json.close_array;
   else
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_array('data');
      for i in c_trucks(v_location) loop
         apex_json.write(i.truck_nbr);
      end loop;
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end;

   -- ========================================================================
   -- xx_otm_get_gate_in_truck_details   [? / ?]
   -- source: db/work/XX_OTM_GET_GATE_IN_TRUCK_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_gate_in_truck_details (
   p_truck_nbr in varchar2,
   p_user_id   in varchar2 default null
)
as
   -- Declared bare, assigned after BEGIN: an exception during declaration
   -- elaboration escapes this block's own handler.
   v_location         varchar2(100);
    -- Last Updated Date : 29-Jul-2026, merged 06-Aug-2026
    -- Description : Multi-shipment search for INSPECTED trucks (up to 2, for a
    --               truck carrying two containers). Response is
    --               data.shipments[] plus data.shipment_count; the flat
    --               top-level fields mirror shipments[1] for older consumers.
    -- Flow based on VM status:
    --   INSPECTED : Collect up to 2 shipments (VM -> Local -> OTM API & Sync).
    --               Error 500 only if NONE found.
    --   LCL       : Customer list + LCL options.
    --   ALL OTHERS: Check active shipments -> Error 409 if found (data=null), else customer list + order_type.
    -- Environment: both. Host and wallet come from XXOTM_APP_CONFIG.


   l_shipment_name    varchar2(100 char);
   l_shipment_nbr     varchar2(100 char);
   l_container_nbr    varchar2(100 char);
   l_container_type   varchar2(100 char);
   l_customer_name    varchar2(200 char);
   l_cust_nbr         varchar2(200 char);
   l_truck_nbr        varchar2(100 char);
   l_driver_name      varchar2(200 char);
   l_driver_iqama_nbr varchar2(100 char);
   l_otm_order_nbr    varchar2(100 char);
   
   -- VM Attributes
   l_vm_shipment_nbr  varchar2(500 char);
   l_vm_status        varchar2(100 char);
   -- Shipments already gated in on THIS visit. Written by gate in alone, which
   -- is why the flag below cannot come from SHIPMENT_NBR: inspection sets that
   -- one, so the inspected shipment would report as gated in before it was.
   l_vm_gate_in_ships varchar2(400 char);
   l_truck_order_type varchar2(50 char);
   l_truck_type       varchar2(50 char);
   l_found            boolean := false;

   -- Did STEP 0 actually resolve a vehicle master row?
   --
   -- Both STEP 0 queries used to fail into DBMS_OUTPUT and let the procedure
   -- carry on with every scalar NULL. The truck then came back as a 200 whose
   -- truck_nbr was only the echoed parameter and whose driver fields were
   -- absent, and the app opened a details screen for a truck that is not at
   -- this site. A truck the caller cannot see is a 404, not a blank form.
   l_vm_found         boolean := false;

   -- SQLERRM from the customer-list cursor, when it raises. Kept so an actual
   -- query failure reports as 500 rather than being flattened into the same
   -- "nothing available" 404 as a genuinely empty result.
   l_cust_err         varchar2(4000 char);

   -- DUAL CONTAINER. Prod resolved exactly one shipment and exited the search on
   -- the first hit; a truck carrying two containers therefore showed only one.
   -- The three passes below now accumulate into this collection instead.
   c_max_ships        constant pls_integer := 2;
   type t_ship is record (
         shipment_nbr   varchar2(100),
         shipment_name  varchar2(100),
         container_nbr  varchar2(100),
         container_type varchar2(100),
         customer_name  varchar2(200),
         cust_nbr       varchar2(100),
         load_status    varchar2(100),
         otm_order_nbr  varchar2(100),
      -- 'Y' once this shipment has been gated in on this visit. The app shows
      -- the completed one as done and opens on the pending one, so an operator
      -- who closed the app mid-truck lands straight on the work that is left.
         gate_in_done   varchar2(1)
   );
   type t_ships is
      table of t_ship index by binary_integer;
   l_ships            t_ships;
   l_pending_count    pls_integer;
   l_load_status      varchar2(100 char);
   
   -- Parsing variables for VM shipment_nbr
   l_parsed_nbr       varchar2(100 char);
   l_csv_remaining    varchar2(500 char);
   l_comma_pos        number;
   
   -- Active shipment check variables
   l_active_ship_nbr  varchar2(100 char);
   l_active_ship_name varchar2(100 char);
   
   -- Customer map variables
   type t_cust_map is
      table of varchar2(200 char) index by varchar2(200 char);
   l_customers        t_cust_map;
   l_cust_idx         varchar2(200 char);
   
   -- API Variables
   l_url              varchar2(4000 char);
   l_response_clob    clob;
   
   -- Environment constants (TEST)
   -- Host from config so this body is identical in both environments; the
   -- plaintext NAQLEEN.INTEGRATION password that used to sit here is gone, the
   -- REST calls now use the OTM_API_AUTH credential.
   c_base_url         varchar2(400);
   c_cred             constant varchar2(30) := 'OTM_API_AUTH';

   -- ================================================================
   -- HELPER: Validate shipment via OTM API (checks trip status)
   -- ================================================================
   function validate_shipment_api (
      p_shipment_xid in varchar2
   ) return boolean is
      l_val_url         varchar2(4000);
      l_val_clob        clob;
      l_val_count       number;
      l_val_status_type varchar2(200);
      l_val_status_val  varchar2(200);
      l_trip_active     boolean := true;
   begin
      dbms_output.put_line('DEBUG: Validating Shipment API: ' || p_shipment_xid);
      l_val_url := c_base_url
                   || 'NAQLEEN.'
                   || p_shipment_xid
                   || '/?q=attribute1 eq "TERMINAL" and perspective eq "B" &expand=statuses';
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      l_val_clob := apex_web_service.make_rest_request(
         p_url                  => l_val_url,
         p_http_method          => 'GET',
         p_credential_static_id => c_cred,
         p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
      );

      apex_json.parse(l_val_clob);
      l_val_count := nvl(
         apex_json.get_count('statuses.items'),
         0
      );
      if l_val_count > 0 then
         for i in 1..l_val_count loop
            l_val_status_type := apex_json.get_varchar2(
               'statuses.items[%d].statusTypeGid',
               i
            );
            l_val_status_val := apex_json.get_varchar2(
               'statuses.items[%d].statusValueGid',
               i
            );
            if l_val_status_type = 'NAQLEEN.TRIP_STATUS' then
               if l_val_status_val in ( 'NAQLEEN.TRIP_COMPLETED',
                                        'NAQLEEN.TRIP_CANCELLED' ) then
                  l_trip_active := false;
                  exit;
               end if;
            end if;
         end loop;

         if l_trip_active then
            dbms_output.put_line('DEBUG: Shipment '
                                 || p_shipment_xid
                                 || ' is ACTIVE.');
            return true;
         else
            dbms_output.put_line('DEBUG: Shipment '
                                 || p_shipment_xid
                                 || ' is COMPLETED or CANCELLED.');
         end if;
      else
         dbms_output.put_line('DEBUG: No statuses returned for ' || p_shipment_xid);
      end if;
      return false;
   exception
      when others then
         dbms_output.put_line('DEBUG: Error in validate_shipment_api: ' || sqlerrm);
         return false;
   end validate_shipment_api;

   -- ================================================================
   -- HELPER: Check if truck has any active shipment
   -- ================================================================
   procedure check_active_shipments (
      p_active_nbr  out varchar2,
      p_active_name out varchar2
   ) is
   begin
      p_active_nbr := null;
      p_active_name := null;

      -- 1. Search local table first
      for r in (
         select st.shipment_xid,
                st.shipment_name
           from xxotm_shipments_t st
          where st.truck_3pl = p_truck_nbr
            and st.location = v_location
            and st.shipment_name in ( 'STORE_AS_IT_IS',
                                      'RELEASE_CFS',
                                      'CFS',
                                      'CRO',
                                      'LRO' )
          order by st.update_date desc
      ) loop
         dbms_output.put_line('DEBUG: Active check - local candidate: ' || r.shipment_xid);
         if validate_shipment_api(r.shipment_xid) then
            p_active_nbr := r.shipment_xid;
            p_active_name := r.shipment_name;
            return;
         end if;
      end loop;

      -- 2. Check OTM API fallback
      dbms_output.put_line('DEBUG: No active shipment found locally. Checking OTM API...');
      l_url := c_base_url
               || '?q=attribute7 eq "'
               || p_truck_nbr
               || '"'
               || ' and (statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and statuses.statusValueGid in ["NAQLEEN.TRIP_STARTED"])'
               || ' and (shipmentName eq "LOADING_LCL" or shipmentName eq "OFFLOADING_LCL" or shipmentName eq "STORE_AS_IT_IS" or shipmentName eq "CRO" or shipmentName eq "LRO" or shipmentName eq "RELEASE_CFS")'
               || ' and attribute1 eq "TERMINAL" and perspective eq "B"'
               || '&orderBy=updateDate:desc&limit=1';

      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      begin
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => c_cred,
            p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
         );
         apex_json.parse(l_response_clob);
         if nvl(
            apex_json.get_count('items'),
            0
         ) > 0 then
            p_active_nbr := apex_json.get_varchar2(
               'items[%d].shipmentXid',
               1
            );
            p_active_name := apex_json.get_varchar2(
               'items[%d].shipmentName',
               1
            );
            dbms_output.put_line('DEBUG: Active shipment found via API: ' || p_active_nbr);
         end if;
      exception
         when others then
            dbms_output.put_line('DEBUG: Error checking API for active shipments: ' || sqlerrm);
      end;
   end check_active_shipments;


   -- Subprograms must sit at the END of the declarative section in PL/SQL, so
   -- these follow the existing two.
   function ship_taken (
      p_nbr in varchar2
   ) return boolean is
   begin
      for i in 1..l_ships.count loop
         if l_ships(i).shipment_nbr = p_nbr then
            return true;
         end if;
      end loop;
      return false;
   end ship_taken;

   -- Adds a shipment if there is room and it is not already held. The passes
   -- overlap -- A2 can legitimately re-find what A1 already took -- so the
   -- duplicate check is required, not defensive.
   procedure add_ship (
      p_nbr in varchar2
   ) is
   begin
      if p_nbr is null
      or ship_taken(p_nbr)
      or l_ships.count >= c_max_ships then
         return;
      end if;
      l_ships(l_ships.count + 1).shipment_nbr := p_nbr;
      l_found := true;
   end add_ship;
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   c_base_url := xxotm_get_cfg('OTM_BASE_URL')
                 || '/logisticsRestApi/resources-int/v2/shipments/';
   dbms_output.put_line('DEBUG: ========================================');
   dbms_output.put_line('DEBUG: Starting XX_OTM_GET_GATE_IN_TRUCK_DETAILS for truck: ' || p_truck_nbr);
   apex_json.initialize_clob_output;
   apex_json.open_object;

   -- ================================================================
   -- STEP 0: Get Vehicle Master Details
   -- ================================================================
   begin
      select truck_nbr,
             driver_name,
             driver_iqama,
             order_type,
             '3PL',
             status,
             shipment_nbr,
             gate_in_shipments
        into
         l_truck_nbr,
         l_driver_name,
         l_driver_iqama_nbr,
         l_truck_order_type,
         l_truck_type,
         l_vm_status,
         l_vm_shipment_nbr,
         l_vm_gate_in_ships
        from xxotm_vehicle_master_t
       where truck_nbr = p_truck_nbr
         and exit_time is null
         and xxotm_vehicle_master_t.location = v_location
         and entry_time = (
         select max(entry_time)
           from xxotm_vehicle_master_t
          where truck_nbr = p_truck_nbr
            and exit_time is null
            and xxotm_vehicle_master_t.location = v_location
      );
      l_vm_found := true;
   exception
      when no_data_found then
         l_truck_order_type := null;
         l_vm_status := null;
         begin
            select truck_nbr,
                   driver_name,
                   driver_iqama,
                   order_type,
                   '3PL',
                   status,
                   shipment_nbr,
                   gate_in_shipments
              into
               l_truck_nbr,
               l_driver_name,
               l_driver_iqama_nbr,
               l_truck_order_type,
               l_truck_type,
               l_vm_status,
               l_vm_shipment_nbr,
               l_vm_gate_in_ships
              from xxotm_vehicle_master_t
             where truck_nbr = p_truck_nbr
               and xxotm_vehicle_master_t.location = v_location
             order by entry_time desc
             fetch first 1 rows only;
            l_vm_found := true;
         exception
            when others then
               dbms_output.put_line('DEBUG: No VM record at all for this truck.');
         end;
      when others then
         l_truck_order_type := null;
         dbms_output.put_line('DEBUG: Error querying VM: ' || sqlerrm);
   end;

   -- ================================================================
   -- STEP 0a: TRUCK NOT AT THIS SITE -> 404
   -- ================================================================
   -- Neither STEP 0 query found the truck, so there is no visit to gate in
   -- against. Every branch below reads l_vm_status / l_truck_order_type, both
   -- NULL here, so BRANCH C would run its OTM lookups on a truck that is not
   -- present and then emit a customer list -- and the app, seeing data != null,
   -- would open the details screen. Say so instead.
   --
   -- Note this is location-scoped: the truck may well exist at the OTHER site.
   -- That is deliberate and matches every other predicate in this procedure;
   -- the message is worded so an operator reads it as "not here", not "no such
   -- truck". A LOCATION column that is NULL rather than backfilled also lands
   -- here, which is the intended signal -- previously it produced a blank form.
   if not l_vm_found then
      dbms_output.put_line('DEBUG: No vehicle master row for '
                           || p_truck_nbr
                           || ' at location '
                           || v_location
                           || '. Returning 404.');
      apex_json.write(
         'response_message',
         'Truck '
         || p_truck_nbr
         || ' was not found at this location. '
         || 'Please check the truck number.'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'data',
         to_char(null)
      );
      apex_json.close_object; -- root
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      return;
   end if;

   -- ================================================================
   -- BRANCH A: INSPECTED STATUS -> Single Shipment Search
   -- ================================================================
   if l_vm_status like '%INSPECTED%' then
      dbms_output.put_line('DEBUG: === INSPECTED BRANCH ===');

      -- A1. Check VM Shipment Number
      if l_vm_shipment_nbr is not null then
         dbms_output.put_line('DEBUG: A1 - Checking VM Shipment: ' || l_vm_shipment_nbr);
         l_csv_remaining := l_vm_shipment_nbr;
         loop
            l_comma_pos := instr(
               l_csv_remaining,
               ','
            );
            if l_comma_pos > 0 then
               l_parsed_nbr := trim(substr(
                  l_csv_remaining,
                  1,
                  l_comma_pos - 1
               ));
               l_csv_remaining := trim(substr(
                  l_csv_remaining,
                  l_comma_pos + 1
               ));
            else
               l_parsed_nbr := trim(l_csv_remaining);
               l_csv_remaining := null;
            end if;

            if l_parsed_nbr is not null then
               if validate_shipment_api(l_parsed_nbr) then
                  add_ship(l_parsed_nbr);
                  exit when l_ships.count >= c_max_ships;
               end if;
            end if;
            exit when l_csv_remaining is null;
         end loop;
      end if;

      -- A2. Search Local Shipments Table (fills any remaining slot)
      if l_ships.count < c_max_ships then
         dbms_output.put_line('DEBUG: A2 - Searching local table for INBOUND_CONTAINER.');
         for r in (
            select st.shipment_xid
              from xxotm_shipments_t st
             where st.truck_3pl = p_truck_nbr
               and st.location = v_location
               and st.shipment_name = 'INBOUND_CONTAINER'
             order by st.update_date desc
         ) loop
            if validate_shipment_api(r.shipment_xid) then
               add_ship(r.shipment_xid);
               exit when l_ships.count >= c_max_ships;
            end if;
         end loop;
      end if;

      -- A3. Search OTM API & Sync (fills any remaining slot)
      if l_ships.count < c_max_ships then
         dbms_output.put_line('DEBUG: A3 - Searching OTM API for INBOUND_CONTAINER.');
         l_url := c_base_url
                  || '?q=attribute7 eq "'
                  || p_truck_nbr
                  || '"'
                  || ' and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
                  || ' and statuses.statusValueGid ne "NAQLEEN.TRIP_COMPLETED"'
                  || ' and statuses.statusValueGid ne "NAQLEEN.TRIP_CANCELLED"'
                  || ' and attribute1 eq "TERMINAL" and perspective eq "B"'
                  || ' and shipmentName eq "INBOUND_CONTAINER"'
                  || ' and refnums.shipmentRefnumQualGid eq "NAQLEEN.LOCATION" and refnums.shipmentRefnumValue eq "'
                  || v_location
                  || '"'
                  || '&orderBy=updateDate:desc&limit='
                  || to_char(c_max_ships - l_ships.count);

         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         begin
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_url,
               p_http_method          => 'GET',
               p_credential_static_id => c_cred,
               p_wallet_path          => xxotm_get_cfg('WALLET_PATH')
            );
            apex_json.parse(l_response_clob);
            for i in 1..nvl(
               apex_json.get_count('items'),
               0
            ) loop
               exit when l_ships.count >= c_max_ships;
               l_shipment_nbr := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );

               -- Trigger Data Sync
               --
               -- TODO (blocks final cutover): XX_NAQLEEN_OTM_DATA_SYNC_PKG takes a
               -- username and password as arguments, so it cannot use the
               -- OTM_API_AUTH credential the way the REST calls above now do.
               -- Give xx_otm_shipments_sync a p_credential_static_id parameter
               -- and call that instead. Until then these two keys are the ONE
               -- deliberate exception to "no secrets in XXOTM_APP_CONFIG" -- the
               -- alternative was leaving the password as a literal here, which
               -- is strictly worse. Delete both keys once the package is fixed.
               begin
                  xx_naqleen_otm_data_sync_pkg.xx_otm_shipments_sync(
                     c_base_url,
                     'XXOTM_SHIPMENTS_T',
                     xxotm_get_cfg('OTM_SYNC_USERNAME'),
                     xxotm_get_cfg('OTM_SYNC_PASSWORD'),
                     'q=shipmentXid eq "'
                     || l_shipment_nbr
                     || '" and attribute1 eq "TERMINAL" and perspective eq "B"'
                  );
                  add_ship(l_shipment_nbr);
               exception
                  when others then
                     dbms_output.put_line('DEBUG: Sync failed for '
                                          || l_shipment_nbr
                                          || ': '
                                          || sqlerrm);
               end;
            end loop;
         exception
            when others then
               dbms_output.put_line('DEBUG: Error in A3 API search: ' || sqlerrm);
         end;
      end if;

      -- Populate shipment details if found
      if l_found then
         -- Details for every shipment collected, not just one.
         for i in 1..l_ships.count loop
            begin
               select shipment_name,
                      cont_no,
                      container_type,
                      customer_name,
                      liner_name,
                      load_status
                 into
                  l_ships(i).shipment_name,
                  l_ships(i).container_nbr,
                  l_ships(i).container_type,
                  l_ships(i).customer_name,
                  l_ships(i).cust_nbr,
                  l_ships(i).load_status
                 from xxotm_shipments_t
                where shipment_xid = l_ships(i).shipment_nbr
                  and xxotm_shipments_t.location = v_location
                  and rownum = 1;
            exception
               when others then
                  l_ships(i).shipment_name := 'UNKNOWN';
            end;

            begin
               select order_release_xid
                 into l_ships(i).otm_order_nbr
                 from xxotm_order_movements_t
                where shipment_xid = l_ships(i).shipment_nbr
                  and rownum = 1;
            exception
               when others then
                  l_ships(i).otm_order_nbr := null;
            end;

            -- Has this shipment already been gated in on this visit?
            -- Comma-bounded membership, the same test gate in uses when it
            -- appends: a bare INSTR would report SH123 as done when the column
            -- holds SH1234, and the app would hide work that is still pending.
            l_ships(i).gate_in_done :=
               case
                  when
                     l_vm_gate_in_ships is not null
                     and instr(
                        ','
                        || l_vm_gate_in_ships
                        || ',',
                        ','
                        || l_ships(i).shipment_nbr
                        || ','
                     ) > 0
                  then
                     'Y'
                  else 'N'
               end;
         end loop;

         -- Keep the scalars pointing at the first shipment so the flat
         -- top-level fields below stay populated for legacy consumers.
         l_shipment_nbr := l_ships(1).shipment_nbr;
         l_shipment_name := l_ships(1).shipment_name;
         l_container_nbr := l_ships(1).container_nbr;
         l_container_type := l_ships(1).container_type;
         l_customer_name := l_ships(1).customer_name;
         l_cust_nbr := l_ships(1).cust_nbr;
         l_load_status := l_ships(1).load_status;
         l_otm_order_nbr := l_ships(1).otm_order_nbr;
      else
         -- No shipment found for INSPECTED -> Error 500
         dbms_output.put_line('DEBUG: INSPECTED found 0 shipments. Returning sync error.');
         apex_json.write(
            'response_message',
            'Sync in process. Please wait'
         );
         apex_json.write(
            'response_code',
            500
         );
         apex_json.write(
            'data',
            to_char(null)
         );
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
      end if;

   -- ================================================================
   -- BRANCH B: LCL -> Customer List + LCL Options
   -- ================================================================
   elsif l_truck_order_type = 'LCL' then
      dbms_output.put_line('DEBUG: === LCL BRANCH === Skipping to customer list.');
      l_found := false;

   -- ================================================================
   -- BRANCH C: ALL OTHERS -> Active Shipment Check
   -- ================================================================
   else
      dbms_output.put_line('DEBUG: === DEFAULT BRANCH === Checking for active shipments.');
      check_active_shipments(
         l_active_ship_nbr,
         l_active_ship_name
      );
      if l_active_ship_nbr is not null then
         dbms_output.put_line('DEBUG: Active shipment '
                              || l_active_ship_nbr
                              || ' found. Returning 409 with null data.');
         apex_json.write(
            'response_message',
            'Active shipment '
            || l_active_ship_nbr
            || ' found with this truck. Please complete the shipment.'
         );
         apex_json.write(
            'response_code',
            409
         );
         apex_json.write(
            'data',
            to_char(null)
         );
         apex_json.close_object; -- root
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
      else
         l_found := false;
      end if;
   end if;

   -- ================================================================
   -- OUTPUT RESPONSE
   -- ================================================================
   if l_found then
      -- ============ SHIPMENT DETAILS (ARRAY + LEGACY FLAT FIELDS) ============
      dbms_output.put_line('DEBUG: Outputting '
                           || l_ships.count
                           || ' shipment(s).');
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');

      -- Which screen the client should open. Stated, not inferred.
      --
      -- The app used to derive this from customer_list being non-empty, so an
      -- EMPTY customer_list -- a legitimate "nothing to select" result -- read
      -- as "shipment details are present" and it rendered the workflow with
      -- blank shipment and container fields. An empty array is a value, not a
      -- mode. Absent on an older server build, where the client keeps its old
      -- inference (lib/features/gate/bloc/gate_bloc.dart).
      apex_json.write(
         'flow',
         'SHIPMENTS'
      );

      -- Every container on the truck. GateTruckDetails.fromJson reads this array
      -- and falls back to the flat fields below only when it is absent
      -- (lib/features/gate/models/gate_common_model.dart:52-79).
      apex_json.write(
         'shipment_count',
         l_ships.count
      );

      -- How many are still outstanding, so the app can decide at a glance
      -- whether this is a fresh truck or one being resumed.
      l_pending_count := 0;
      for i in 1..l_ships.count loop
         if nvl(
            l_ships(i).gate_in_done,
            'N'
         ) = 'N' then
            l_pending_count := l_pending_count + 1;
         end if;
      end loop;
      apex_json.write(
         'pending_count',
         l_pending_count
      );
      apex_json.open_array('shipments');
      for i in 1..l_ships.count loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_ships(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_ships(i).shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_ships(i).container_nbr
         );
         apex_json.write(
            'container_type',
            l_ships(i).container_type
         );
         apex_json.write(
            'customer_name',
            l_ships(i).customer_name
         );
         apex_json.write(
            'customer_nbr',
            l_ships(i).cust_nbr
         );
         apex_json.write(
            'load_status',
            nvl(
               l_ships(i).load_status,
               'UNLOADED'
            )
         );
         apex_json.write(
            'otm_order_nbr',
            l_ships(i).otm_order_nbr
         );
         -- Boolean, not 'Y'/'N': the Flutter model decodes JSON booleans
         -- directly and a string would need a bespoke parser on that field.
         apex_json.write(
            'gate_in_completed',
            case
                  when nvl(
                     l_ships(i).gate_in_done,
                     'N'
                  ) = 'Y' then
                     true
                  else false
               end
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;

      -- Flat fields, from the first shipment. Retained for compatibility.
      apex_json.write(
         'shipment_nbr',
         l_shipment_nbr
      );
      apex_json.write(
         'shipment_name',
         l_shipment_name
      );
      apex_json.write(
         'container_nbr',
         l_container_nbr
      );
      apex_json.write(
         'container_type',
         l_container_type
      );
      apex_json.write(
         'customer_name',
         l_customer_name
      );
      apex_json.write(
         'customer_nbr',
         l_cust_nbr
      );
      apex_json.write(
         'truck_nbr',
         nvl(
            l_truck_nbr,
            p_truck_nbr
         )
      );
      apex_json.write(
         'driver_name',
         l_driver_name
      );
      apex_json.write(
         'driver_nbr',
         l_driver_iqama_nbr
      );
      apex_json.write(
         'load_status',
         nvl(
            l_load_status,
            'UNLOADED'
         )
      );
      apex_json.write(
         'otm_order_nbr',
         l_otm_order_nbr
      );
      apex_json.close_object; -- data
   else
      -- ============ CUSTOMER LIST (LCL + ALL OTHERS) ============
      -- Built BEFORE any of the envelope is written. The list has to be known
      -- to decide whether this is a 200 at all, and APEX_JSON cannot unwrite an
      -- object once it is open.
      begin
         for r in (
            select distinct st.customer_name,
                            'NAQLEEN.'
                            || replace(
                               st.liner_name,
                               'NAQLEEN.'
                            ) as customer_nbr
              from xxotm_shipments_t st
             where st.location = v_location
               and ( st.trip_status in ( 'TRIP_NOT_STARTED',
                                         'NAQLEEN.TRIP_NOT_STARTED' )
                or st.trip_status like '%TRIP_NOT_STARTED%' )
               and st.shipment_name in ( 'LOADING_LCL',
                                         'OFFLOADING_LCL',
                                         'STORE_AS_IT_IS',
                                         'CRO',
                                         'LRO',
                                         'RELEASE_CFS' )
               and st.customer_name is not null
               and st.liner_name is not null
             order by st.customer_name
         ) loop
            if not l_customers.exists(r.customer_nbr) then
               l_customers(r.customer_nbr) := r.customer_name;
            end if;
         end loop;
      exception
         when others then
            -- Captured, not just logged: a cursor that raises produced an empty
            -- collection, which is indistinguishable over HTTP from a query
            -- that legitimately matched nothing. They need different codes.
            l_cust_err := sqlerrm;
            dbms_output.put_line('DEBUG: Error in local Customer List fetch: ' || sqlerrm);
      end;

      -- Nothing for the operator to choose, so there is no screen to open.
      -- This is the second half of the same bug as STEP 0a: the response was a
      -- 200 carrying customer_list: [] and no shipments, and the app read a
      -- non-null data as "go", landing on a details screen with no shipment_nbr
      -- and a Submit button that would post empty strings.
      if l_customers.count = 0 then
         if l_cust_err is not null then
            dbms_output.put_line('DEBUG: Customer list failed to build. Returning 500.');
            apex_json.write(
               'response_message',
               'Error: ' || l_cust_err
            );
            apex_json.write(
               'response_code',
               500
            );
         else
            dbms_output.put_line('DEBUG: Customer list is empty for location '
                                 || v_location
                                 || '. Returning 404.');
            apex_json.write(
               'response_message',
               'No shipments are available to gate in for truck '
               || p_truck_nbr
               || ' at this location.'
            );
            apex_json.write(
               'response_code',
               404
            );
         end if;
         apex_json.write(
            'data',
            to_char(null)
         );
         apex_json.close_object; -- root
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
      end if;

      dbms_output.put_line('DEBUG: Outputting customer list from xxotm_shipments_t.');
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');
      -- LCL needs the extra operation step before booking, so the two selection
      -- flows are distinct values rather than one "needs selection" boolean.
      apex_json.write(
         'flow',
         case
               when l_truck_order_type = 'LCL' then
                  'LCL_SELECT'
               else 'CUSTOMER_SELECT'
            end
      );
      apex_json.write(
         'truck_nbr',
         nvl(
            l_truck_nbr,
            p_truck_nbr
         )
      );
      apex_json.write(
         'driver_name',
         l_driver_name
      );
      apex_json.write(
         'driver_nbr',
         l_driver_iqama_nbr
      );
      apex_json.write(
         'truck_type',
         l_truck_type
      );
      apex_json.write(
         'order_type',
         l_truck_order_type
      );
      apex_json.write(
         'load_status',
         nvl(
            l_load_status,
            'UNLOADED'
         )
      );
      apex_json.open_array('customer_list');
      l_cust_idx := l_customers.first;
      while l_cust_idx is not null loop
         apex_json.open_object;
         apex_json.write(
            'customer_name',
            l_customers(l_cust_idx)
         );
         apex_json.write(
            'customer_nbr',
            l_cust_idx
         );
         apex_json.close_object;
         l_cust_idx := l_customers.next(l_cust_idx);
      end loop;
      apex_json.close_array;
      if l_truck_order_type = 'LCL' then
         apex_json.open_array('lcl_options');
         apex_json.write('OFFLOADING_LCL');
         apex_json.write('LOADING_LCL');
         apex_json.close_array;
      end if;
      apex_json.close_object; -- data
   end if;

   apex_json.close_object; -- root
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      dbms_output.put_line('DEBUG: Critical Error: ' || sqlerrm);
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'data',
         to_char(null)
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_gate_in_truck_details;

   -- ========================================================================
   -- XX_OTM_GET_GATE_OUT_TRUCKS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_GATE_OUT_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_gate_out_trucks (
   p_search_text in varchar2 default null,
   p_user_id in varchar2 default null
)
as
    v_location varchar2(100);
    -- Last Updated Date : 26-Jan-2026
    -- Updated By : Madhan
    -- Description       : Updated to check NAQLEEN.TRIP_STATUS via separate API call for LCL shipments

   l_url                  varchar2(4000);
   l_shipment_url         varchar2(4000);
   l_status_url           varchar2(4000);
   l_response_clob        clob;
   l_status_found         boolean;
   l_items_count          number;
   l_status_code          varchar2(200);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   l_truck_idx            varchar2(200);
   l_gate_out_found       boolean;
   l_is_trip_completed    boolean;
   l_shipment_name        varchar2(200);
   l_status_value_gid     varchar2(200);
   l_gate_in_found       boolean;

    -- Associative array to hold unique trucks (Key = Truck Number)
   type t_truck_map is
      table of boolean index by varchar2(200);
   l_unique_map           t_truck_map;
   cursor c_trucks is
   select v.truck_nbr,
          s.shipment_xid
     from xxotm_vehicle_master_t v
     join xxotm_shipments_t s
   on (
    --  s.power_unit = v.truck_nbr
    --    or
        s.truck_3pl = v.truck_nbr )
    where v.exit_time is null
    --   and v.status not like '%GATE OUT%'
      and v.location = v_location
      and s.location = v_location
      and ( p_search_text is null
       or v.truck_nbr like '%'
                           || p_search_text
                           || '%' )
    order by s.update_date desc;

begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Initialize output
   apex_json.initialize_clob_output;

    -- Iterate through trucks
   for r in c_trucks loop
        
        -- OPTIMIZATION: If we already found this truck is valid from a previous shipment iteration, 
        -- skip the expensive API call and move to the next row.
      if l_unique_map.exists(r.truck_nbr) then
         continue;
      end if;
      l_status_found := false;
      l_gate_out_found := false;
      l_is_trip_completed := false;
         l_gate_in_found := false;
        -- Construct API URL to get ALL tracking events
      l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
               || r.shipment_xid
               || '/trackingEvents';

        -- Set Headers
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      begin
            -- Make REST Request for Tracking Events
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

            -- Parse JSON Response
         apex_json.parse(l_response_clob);
         l_items_count := apex_json.get_count('items');

            -- Iterate through events to find matching status
         for i in 1..l_items_count loop
            l_status_code := apex_json.get_varchar2(
               'items[%d].statusCodeGid',
               i
            );
            if instr(
               l_status_code,
               'GATE IN'
            ) > 0 then
               l_gate_in_found := true;
              
            end if;
            -- Check for disqualifier
            if instr(
               l_status_code,
               'GATE OUT'
            ) > 0 then
               l_gate_out_found := true;
               exit; -- Stop checking, this truck is invalid
            end if;

            -- Check for required statuses (Existing Logic)
            if instr(
               l_status_code,
               'CONTAINER STORED'
            ) > 0
            or instr(
               l_status_code,
               'CONTAINER RELEASED'
            ) > 0
            or instr(
               l_status_code,
               'STUFFED'
            ) > 0
            or instr(
               l_status_code,
               'DESTUFFED'
            ) > 0 then
               l_status_found := true;
            end if;

         end loop;

      exception
         when others then
                -- Ignore API errors and continue to next truck
            null;
      end;

      -- Extra Check: If NOT already valid and NOT gated out, check Trip Status and Shipment Name
      if l_gate_in_found and
         not l_gate_out_found
         and not l_status_found
      then
         begin
            -- 1. Check Trip Status (NAQLEEN.TRIP_STATUS)
            l_status_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                            || r.shipment_xid
                            || '/statuses/NAQLEEN.TRIP_STATUS';
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_status_url,
               p_http_method          => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );

             -- If request successful, check statusValueGid
            if apex_web_service.g_status_code = 200 then
               apex_json.parse(l_response_clob);
               l_status_value_gid := apex_json.get_varchar2('statusValueGid');
               if l_status_value_gid = 'NAQLEEN.TRIP_COMPLETED' then
                  l_is_trip_completed := true;
               end if;
            end if;

             -- 2. If Trip Completed, Check Shipment Name for LCL
            if l_is_trip_completed then
               l_shipment_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.' || r.shipment_xid
               ;
               l_response_clob := apex_web_service.make_rest_request(
                  p_url                  => l_shipment_url,
                  p_http_method          => 'GET',
                  p_credential_static_id => l_credential_static_id,
                  p_wallet_path => xxotm_get_cfg('WALLET_PATH')
               );

               if apex_web_service.g_status_code = 200 then
                  apex_json.parse(l_response_clob);
                  l_shipment_name := apex_json.get_varchar2('shipmentName');
                  if l_shipment_name in ( 'OFFLOADING_LCL',
                                          'LOADING_LCL' ) then
                     l_status_found := true;
                  end if;
               end if;
            end if;

         exception
            when others then
               null; -- Ignore errors in extra checks
         end;
      end if;

        -- If valid, add to the Unique Map
      if l_gate_in_found and
         l_status_found
         and not l_gate_out_found
      then
         l_unique_map(r.truck_nbr) := true;
      end if;
   end loop;

    -- Generate JSON Output
   apex_json.open_object;
   if l_unique_map.count > 0 then
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_array('data');
        
        -- Iterate through the unique keys in the map
      l_truck_idx := l_unique_map.first;
      while l_truck_idx is not null loop
         apex_json.write(l_truck_idx);
         l_truck_idx := l_unique_map.next(l_truck_idx);
      end loop;

      apex_json.close_array;
   else
      apex_json.write(
         'response_message',
         'No Data Found'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_gate_out_trucks;

   -- ========================================================================
   -- XX_OTM_GET_INSPECTED_CONTAINERS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_INSPECTED_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_inspected_containers (
   p_search_text in varchar2 default null,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_count      number := 0;
   type t_container_list is
      table of xxotm_container_inspection_t.container_nbr%type;
   l_containers t_container_list;
   v_location varchar2(100);
   -- Bindable in FETCH FIRST since 12c; XXOTM_GET_BOOKINGS_P already relies on
   -- that. Named rather than inline so the cap is visible at the top.
   c_max_rows constant pls_integer := 50;
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Oracle applies ROWNUM before DISTINCT, so "select distinct ... and rownum
   -- <= 50" took the first 50 RAW rows and then deduplicated them. A container
   -- inspected ten times consumed ten of the fifty, so the picker could show
   -- well under 50 containers -- arbitrarily chosen, with nothing to indicate
   -- the list had been truncated.
   --
   -- Grouping first, then capping, makes the fifty a genuine fifty containers.
   -- Ordering by the most recent inspection puts the ones an operator is likely
   -- looking for at the top rather than leaving it to the access path.
   select c.container_nbr
   bulk collect
     into l_containers
     from xxotm_container_inspection_t c
    where ( p_search_text is null
       or upper(c.container_nbr) like '%'
                                      || upper(p_search_text)
                                      || '%' )
      and c.location = v_location
    group by c.container_nbr
    order by max(c.timestamp) desc nulls last,
             c.container_nbr
   fetch first c_max_rows rows only;

   apex_json.open_object;
   if l_containers.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_containers.count loop
         apex_json.write(l_containers(i));
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
   end if;

   apex_json.close_object;
exception
   when others then
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
end;

   -- ========================================================================
   -- XX_OTM_GET_INSPECTED_CONTAINER_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_INSPECTED_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_inspected_container_details (
   p_container_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- ------------------------------------------------------------------------
   -- OUTER joins, driven off the inspection row.
   --
   -- This was a three-table INNER join, so a container was only returned when a
   -- shipment AND a vehicle-master row both existed and all three carried this
   -- location. XX_OTM_GET_INSPECTED_CONTAINERS lists from ONE table with ONE
   -- predicate, so the picker offered containers this query could not resolve
   -- and the operator got "No data found" on a container the app had just shown
   -- them. Three independent ways that happened:
   --
   --   1. The join ran through s.cont_no, which is NULL until OTM assigns a
   --      container to the shipment. (XX_OTM_GENERATE_EIR carries a whole
   --      resolve_container() fallback for that same gap, so it is common.)
   --      It now joins on the SHIPMENT NUMBER the inspection row already
   --      stores -- an exact key, recorded at inspection time, that cannot go
   --      stale. That is also what the 18-May ancestor joined on; prod
   --      rewrote it to go through cont_no.
   --   2. No vehicle-master row matched power_unit / truck_3pl -- both NULL on
   --      the shipment, or the plate differing by case or a stray space. The
   --      comparison is now upper(trim(...)) on both sides, matching the rest
   --      of the codebase.
   --   3. s.location or d.location was NULL. XXOTM_SHIPMENTS_T.LOCATION was
   --      never written by prod's sync at all, so every shipment synced before
   --      that fix silently failed the join.
   --
   -- None of those tables contributes anything to the inspection payload --
   -- images, hotspots and comments all live in c.inspection_details. They only
   -- decorate it with truck, driver, liner and container type. A missing
   -- decoration must not hide the record, so they are LEFT joins now and the
   -- fields simply come back null.
   --
   -- The location predicates moved INTO the ON clauses. Left in the WHERE they
   -- would silently convert both outer joins back to inner ones and restore the
   -- exact bug this is fixing.
   --
   -- A truck has many visits, so the vehicle-master join can match more than
   -- one row. Only the first row is ever fetched, so rather than restricting
   -- the join, the ORDER BY decides: newest inspection, then newest visit.
   -- Without that second key which visit's driver appeared would be left to the
   -- access path.
   -- ------------------------------------------------------------------------
   cursor c_details is
   select c.container_nbr,
          c.shipment_nbr,
          s.container_type,
          v.truck_nbr as truck_number,
          s.liner_name as liner,
          v.driver_name,
          v.driver_iqama as iqama_number,
          c.timestamp as inspected_time,
          c.inspection_details
     from xxotm_container_inspection_t c
     left join xxotm_shipments_t s
     on replace(
        upper(s.shipment_xid),
        'NAQLEEN.'
     ) = replace(
        upper(c.shipment_nbr),
        'NAQLEEN.'
     )
        and s.location = v_location
     left join xxotm_vehicle_master_t v
     on ( upper(trim(v.truck_nbr)) = upper(trim(s.power_unit))
       or upper(trim(v.truck_nbr)) = upper(trim(s.truck_3pl)) )
        and v.location = v_location
    where c.container_nbr = p_container_nbr
      and c.location = v_location
    order by c.timestamp desc,
             v.entry_time desc nulls last;
   l_detail            c_details%rowtype;
   l_details_count     number;
   l_images_count      number;
   l_image_name        varchar2(4000);
   l_image_name_no_ext varchar2(4000);
   l_hotspot_name      varchar2(4000);
   l_comments          varchar2(4000);
   l_base_url          varchar2(4000) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/custom-actions/download/documents/NAQLEEN.INSPECTION-'
   ;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   open c_details;
   fetch c_details into l_detail;
   if c_details%found then
      apex_json.open_object;
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_object('data');
      apex_json.write(
         'container_number',
         l_detail.container_nbr
      );
      apex_json.write(
         'shipment_number',
         l_detail.shipment_nbr
      );
      apex_json.write(
         'container_type',
         l_detail.container_type
      );
      apex_json.write(
         'truck_number',
         l_detail.truck_number
      );
      apex_json.write(
         'liner',
         l_detail.liner
      );
      apex_json.write(
         'driver_name',
         l_detail.driver_name
      );
      apex_json.write(
         'iqama_number',
         l_detail.iqama_number
      );
      apex_json.write(
         'inspected_time',
         l_detail.inspected_time
      );

      -- Parse inspection details once
      if l_detail.inspection_details is not null then
         begin
            apex_json.parse(l_detail.inspection_details);
            l_details_count := apex_json.get_count(p_path => '.');
         exception
            when others then
               l_details_count := 0;
         end;
      else
         l_details_count := 0;
      end if;

      -- Images array (Root)
      apex_json.open_array('images');
      if l_details_count > 0 then
         for i in 1..l_details_count loop
            l_images_count := apex_json.get_count(
               p_path => '[%d].images',
               p0     => i
            );
            for j in 1..l_images_count loop
               l_image_name := apex_json.get_varchar2(
                  p_path => '[%d].images[%d]',
                  p0     => i,
                  p1     => j
               );
               -- Strip extension for URL
               l_image_name_no_ext := regexp_replace(
                  l_image_name,
                  '\.[jJ][pP][gG]$',
                  ''
               );
               if l_image_name_no_ext is not null then
                  apex_json.write(l_base_url
                                  || l_image_name_no_ext
                                  || '/contents/NAQLEEN.INSPECTION-'
                                  || l_image_name_no_ext);
               end if;
            end loop;
         end loop;
      end if;
      apex_json.close_array;

      -- Inspection Details Array (Parsed and Reconstructed)
      apex_json.open_array('inspection_details');
      if l_details_count > 0 then
         for i in 1..l_details_count loop
            apex_json.open_object;
            l_hotspot_name := apex_json.get_varchar2(
               p_path => '[%d].hotspot_name',
               p0     => i
            );
            l_comments := apex_json.get_varchar2(
               p_path => '[%d].comments',
               p0     => i
            );
            apex_json.write(
               'hotspot_name',
               l_hotspot_name
            );
            apex_json.write(
               'comments',
               l_comments
            );

            -- Recalculate images count for this detail item!
            l_images_count := apex_json.get_count(
               p_path => '[%d].images',
               p0     => i
            );
            apex_json.open_array('images');
            for j in 1..l_images_count loop
               l_image_name := apex_json.get_varchar2(
                  p_path => '[%d].images[%d]',
                  p0     => i,
                  p1     => j
               );
               if l_image_name is not null then
                   -- Keep original filename in details to allow UI matching (or should we strip? user said remove from image name before adding to url)
                   -- If we strip here, UI matching is easier. But let's follow: image.jpg in details, INSPECTION-image in URL. 
                   -- UI matching 'url.contains(filename)' will FAIL if we don't handle it.
                   -- But I must follow strict prompt.
                  apex_json.write(l_image_name);
               end if;
            end loop;
            apex_json.close_array;
            apex_json.close_object;
         end loop;
      end if;
      apex_json.close_array;
      apex_json.close_object; -- data
      apex_json.close_object; -- root
   else
      apex_json.open_object;
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.close_object;
   end if;

   close c_details;
exception
   when others then
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
end;

   -- ========================================================================
   -- XX_OTM_GET_INSPECTION_TRUCKS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_INSPECTION_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_inspection_trucks (p_user_id in varchar2 default null)
as
   v_location varchar2(100);
   type record_type is record (
         truck_nbr    varchar2(100),
         driver_name  varchar2(100),
         driver_iqama varchar2(100),
         type         varchar2(100),
         entry_time   varchar2(100)
   );
   l_record record_type;
   cursor c_data_cursor (p_location varchar2) is
   select distinct v.truck_nbr,
                   v.driver_name,
                   v.driver_iqama,
                   v.type,
                   v.entry_time
     from xxotm_vehicle_master_t v
    where v.exit_time is null
      and v.status = 'inspection'
      and v.location = p_location
      and v.location = v_location
    ORDER BY entry_time desc;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');
   open c_data_cursor(v_location);
   loop
      fetch c_data_cursor into l_record;
      exit when c_data_cursor%notfound;
      apex_json.open_object;
      apex_json.write(
         'truck_number',
         l_record.truck_nbr
      );
      apex_json.write(
         'driver_name',
         l_record.driver_name
      );
      apex_json.write(
         'iqama_number',
         l_record.driver_iqama
      );
      apex_json.write(
         'type',
         l_record.type
      );
      apex_json.write(
         'entry_time',
         l_record.entry_time
      );
      apex_json.close_object;
   end loop;
   close c_data_cursor;
   apex_json.close_array;
   apex_json.close_object;

    -- Use apex_util.prn for CLOB support
   htp.prn(apex_json.get_clob_output);
   dbms_output.put_line(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'ERROR WHILE EXECUTING METHOD: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end;

