   -- ========================================================================
   -- XX_OTM_GET_INVENTORY   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_INVENTORY.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_inventory (
   p_search_cust in varchar2 default '',
   p_search_cont in varchar2 default '',
   p_search_ship in varchar2 default '',
   p_page_num    in number default 0
)
as
   l_prev_cust     varchar2(200) := null;
   l_prev_cont     varchar2(100) := null;
   l_is_first_cust boolean := true;
   l_final_clob    clob;
    
    -- Filtered and Ranked Data Cursor
   cursor c_data is
   with ranked_data as (
      select t.cust_name,
             t.cust_nbr,
             t.container_nbr,
             t.shipment_nbr,
             t.cargo_description,
             t.qty,
             t.qty_uom,
             t.item_code,
             t.gross_weight,
             t.net_weight,
             t.weight_uom,
             t.volume,
             t.volume_uom,
             t.un_class,
             t.country_of_origin,
             t.rcvd_qty,
             t.item_description,
             dense_rank()
             over(
                 order by t.cust_name
             ) as cust_rn,
             dense_rank()
             over(partition by t.cust_name
                  order by t.container_nbr
             ) as cont_rn,
             row_number()
             over(partition by t.cust_name,
                               t.container_nbr
                  order by t.cargo_description
             ) as item_rn
        from xxotm_customer_inventory_t t
       where ( p_search_cust is null
          or upper(t.cust_name) like '%'
                                     || upper(p_search_cust)
                                     || '%' )
         and ( p_search_cont is null
          or upper(t.container_nbr) like '%'
                                         || upper(p_search_cont)
                                         || '%' )
         and ( p_search_ship is null
          or upper(t.shipment_nbr) like '%'
                                        || upper(p_search_ship)
                                        || '%' )
   )
   select *
     from ranked_data
    where cust_rn > ( nvl(
         p_page_num,
         0
      ) * 10 )
      and cust_rn <= ( ( nvl(
      p_page_num,
      0
   ) + 1 ) * 10 )
      and cont_rn <= 10
      and item_rn <= 10
    order by cust_name,
             container_nbr,
             cargo_description;

begin
    -- Configure APEX_JSON Output
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');
   for r in c_data loop
        -- New Customer Handling
        -- BUG FIX: Use l_is_first_cust boolean instead of checking if l_prev_cust is null, 
        -- because cust_name itself can be null.
      if l_is_first_cust
      or nvl(
         l_prev_cust,
         '###'
      ) != nvl(
         r.cust_name,
         '###'
      ) then
         if not l_is_first_cust then
            apex_json.close_array; -- Close previous container items
            apex_json.close_object; -- Close previous container
            apex_json.close_array; -- Close previous customer containers
            apex_json.close_object; -- Close previous customer
         end if;

         apex_json.open_object; -- New Customer
         apex_json.write(
            'customer',
            r.cust_name
         );
         apex_json.write(
            'customer_nbr',
            r.cust_nbr
         );
         apex_json.open_array('containers');
         l_prev_cust := r.cust_name;
         l_is_first_cust := false;
         l_prev_cont := '###START###'; -- Reset container tracker for new customer
      end if;
        
        -- New Container Handling
      if l_prev_cont = '###START###'
      or nvl(
         l_prev_cont,
         '###'
      ) != nvl(
         r.container_nbr,
         '###'
      ) then
         if l_prev_cont != '###START###' then
            apex_json.close_array; -- Close previous container items
            apex_json.close_object; -- Close previous container
         end if;
         apex_json.open_object; -- New Container
         apex_json.write(
            'container_nbr',
            r.container_nbr
         );
         apex_json.write(
            'shipment_nbr',
            r.shipment_nbr
         );
         apex_json.open_array('items');
         l_prev_cont := r.container_nbr;
      end if;
        
        -- Add Item
      apex_json.open_object;
      apex_json.write(
         'item_description',
         r.item_description
      );
      apex_json.write(
         'cargo_description',
         r.cargo_description
      );
      apex_json.write(
         'item_code',
         r.item_code
      );
      apex_json.write(
         'gross_weight',
         r.gross_weight
      );
      apex_json.write(
         'net_weight',
         r.net_weight
      );
      apex_json.write(
         'weight_uom',
         r.weight_uom
      );
      apex_json.write(
         'volume',
         r.volume
      );
      apex_json.write(
         'volume_uom',
         r.volume_uom
      );
      apex_json.write(
         'un_class',
         r.un_class
      );
      apex_json.write(
         'country_of_origin',
         r.country_of_origin
      );
      apex_json.write(
         'rcvd_qty',
         r.rcvd_qty
      );
      apex_json.write(
         'quantity',
         r.qty
      );
      apex_json.write(
         'quantity_uom',
         r.qty_uom
      );
      apex_json.close_object;
   end loop;

    -- Close remaining open structures
   if not l_is_first_cust then
      apex_json.close_array; -- Close last container items
      apex_json.close_object; -- Close last container
      apex_json.close_array; -- Close last customer containers
      apex_json.close_object; -- Close last customer
   end if;

   apex_json.close_array; -- Close data array
   apex_json.close_object; -- Close root object

   -- Capture Output
   l_final_clob := apex_json.get_clob_output;

   -- Chunked Output
   declare
      l_offset number := 1;
      l_amount number := 32000;
      l_len    number;
      l_buffer varchar2(32767);
   begin
      if l_final_clob is not null then
         l_len := dbms_lob.getlength(l_final_clob);
         while l_offset <= l_len loop
            dbms_lob.read(
               l_final_clob,
               l_amount,
               l_offset,
               l_buffer
            );
            htp.prn(l_buffer);
            l_offset := l_offset + l_amount;
         end loop;
      end if;
   end;

   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      
      -- Simple output for error
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_inventory;

   -- ========================================================================
   -- XX_OTM_GET_ITEMS_BY_CUST_NBR   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_ITEMS_BY_CUST_NBR.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_items_by_cust_nbr (
   p_customer_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
 v_location varchar2(100);

   cursor c_items is
   select item_code,
          item_description,
          available_qty,
          qty_uom,
          net_weight,
          weight_uom
     from xxotm_customer_stock_t
    where cust_nbr = p_customer_nbr
      and available_qty > 0
      and xxotm_customer_stock_t.location = v_location;
begin
 v_location := xx_get_user_location(p_user_id);
 -- Location is mandatory. xx_get_user_location returns NULL when
 -- req_location_id is absent, malformed, or not permitted for this user;
 -- it no longer falls back to a default site. Continuing on NULL would
 -- filter on "location = NULL" and return an empty result set -- an empty
 -- screen with no error, which is worse than a refusal.
 if v_location is null then
    xxotm_location_required;
    return;
 end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.open_array('data');
   for r in c_items loop
      apex_json.open_object;
      apex_json.write(
         'item_code',
         r.item_code
      );
      apex_json.write(
         'item_description',
         r.item_description
      );
      apex_json.write(
         'available_qty',
         r.available_qty
      );
      apex_json.write(
         'qty_uom',
         r.qty_uom
      );
      apex_json.write(
         'net_weight',
         r.net_weight
      );
      apex_json.write(
         'weight_uom',
         r.weight_uom
      );
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_items_by_cust_nbr;

   -- ========================================================================
   -- XX_OTM_GET_LCL_SHIPMENT_DETAILS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_LCL_SHIPMENT_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_lcl_shipment_details (
   p_shipment_nbr in varchar2,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_root_obj        json_object_t;
   l_data_obj        json_object_t;
   l_items_array     json_array_t;
   l_item_obj        json_object_t;
   l_found_local     boolean := false;
   l_customer_name   varchar2(200);
   l_customer_nbr    varchar2(100);
   l_response_clob   clob;
    v_location varchar2(100);
   cursor c_items is
   select distinct
          cust_name,
          cust_nbr,
          item_code,
          item_description,
          qty,
          qty_uom
     from xxotm_customer_inventory_t
    where shipment_nbr = p_shipment_nbr and xxotm_customer_inventory_t.location = v_location
    order by item_code;

begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
   l_root_obj := json_object_t();
   l_data_obj := json_object_t();
   l_items_array := json_array_t();

   for r in c_items loop
       if not l_found_local then
           l_found_local := true;
           l_data_obj.put('shipment_nbr', p_shipment_nbr);
           l_data_obj.put('customer_name', r.cust_name);
           l_data_obj.put('customer_nbr', r.cust_nbr);
       end if;

       l_item_obj := json_object_t();
       l_item_obj.put('item_code', r.item_code);
       l_item_obj.put('description', r.item_description);
       l_item_obj.put('actual_quantity', r.qty);
       l_item_obj.put('quantity_uom', r.qty_uom);
       l_items_array.append(l_item_obj);
   end loop;

   if l_found_local then
       l_data_obj.put('items', l_items_array);
       
       l_root_obj.put('response_code', 200);
       l_root_obj.put('response_message', 'Success');
       l_root_obj.put('data', l_data_obj);
   else
       begin
           select distinct s.customer_name, s.liner_name
             into l_customer_name, l_customer_nbr
             from xxotm_shipments_t s
            where s.shipment_xid = p_shipment_nbr and s.location = v_location
            fetch first 1 rows only;
           
           l_data_obj.put('shipment_nbr', p_shipment_nbr);
           l_data_obj.put('customer_name', l_customer_name);
           l_data_obj.put('customer_nbr', l_customer_nbr);
           l_data_obj.put('items', json_array_t());
           
           l_root_obj.put('response_code', 200);
           l_root_obj.put('response_message', 'Success (No Items)');
           l_root_obj.put('data', l_data_obj);
       exception
           when others then
               l_root_obj.put('response_code', 404);
               l_root_obj.put('response_message', 'Shipment not found');
       end;
   end if;

   l_response_clob := l_root_obj.to_clob;
   htp.prn(l_response_clob);
exception
   when others then
       l_root_obj := json_object_t();
       l_root_obj.put('response_code', 500);
       l_root_obj.put('response_message', 'Error: ' || sqlerrm);
       l_response_clob := l_root_obj.to_clob;
       htp.prn(l_response_clob);
end xx_otm_get_lcl_shipment_details;

   -- ========================================================================
   -- XX_OTM_GET_LOADING_LCL_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_LOADING_LCL_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_loading_lcl_shipments (
   p_search_text in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 23-Jan-2026
   -- Description  : Gets verified shipment numbers for active LOADING_LCL tasks only.
   --                Logic:
   --                1. Fetch candidate shipment IDs from local assignment table.
   --                2. Call OTM API with shipmentName=LOADING_LCL filter.
   --                3. Validate Status (NOT COMPLETED/CANCELLED).
   --                4. (Updated) Removed Event Validation (TASK_ASSIGNED check removed).
   -- Updated      : Removed Debug Logs.

   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_shipment_list        varchar2(32767) := '[';
   l_shipment_count       number := 0;
   l_api_shipment_count   number;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   
   -- Loop vars
   l_sh_xid               varchar2(100);
   l_sh_name              varchar2(100);
   l_ct_nbr               varchar2(100);
   l_tr_nbr               varchar2(100);
   l_dr_name              varchar2(200);
   l_pw_unt               varchar2(200);
   
   -- Validation vars
   l_status_count         number;
   l_status_gid           varchar2(200);
   l_status_val           varchar2(200);
   l_is_valid             boolean;
   l_trip_status_val      varchar2(200);
   
   -- Output Collection
   type t_shpmt_rec is record (
         shipment_nbr  varchar2(100),
         shipment_name varchar2(100),
         container_nbr varchar2(100),
         truck_nbr     varchar2(100),
         driver_name   varchar2(200)
   );
   type t_shpmt_tab is
      table of t_shpmt_rec;
   l_verified_shipments   t_shpmt_tab := t_shpmt_tab();
   cursor c_assignments is
   select shipment_nbr
     from xxotm_task_assignment_t
    where shipment_nbr is not null
      and ( p_search_text is null
       or upper(shipment_nbr) like '%'
                                   || upper(p_search_text)
                                   || '%' )
    and xxotm_task_assignment_t.location = v_location
    group by shipment_nbr
    order by max(assigned_date) desc;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- 1. Collect candidate shipments from local assignment table
   for r in c_assignments loop
      l_shipment_count := l_shipment_count + 1;
      if l_shipment_count > 1 then
         l_shipment_list := l_shipment_list || ',';
      end if;
      l_shipment_list := l_shipment_list
                         || '"'
                         || r.shipment_nbr
                         || '"';
      
      -- Batch limit
      if l_shipment_count >= 100 then
         exit;
      end if;
   end loop;
   l_shipment_list := l_shipment_list || ']';
   if l_shipment_count > 0 then
      -- 2. Call OTM API 
      -- Filter: IDs in list AND shipmentName eq LOADING_LCL
      -- Expand: statuses
      l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
               || '?q=shipmentName eq "LOADING_LCL" and shipmentXid in '
               || l_shipment_list
               || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
               || ' and refnums.shipmentRefnumValue eq ' || v_location
               || '&limit=200&expand=statuses';
      begin
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         if
            apex_web_service.g_status_code = 200
            and l_response_clob is not null
         then
            apex_json.parse(l_response_clob);
            l_api_shipment_count := nvl(
               apex_json.get_count('items'),
               0
            );
            
            -- 3. Verify each shipment
            for i in 1..l_api_shipment_count loop
               l_sh_xid := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );
               l_sh_name := apex_json.get_varchar2(
                  'items[%d].shipmentName',
                  i
               );
               
               -- A. Get Trip Status
               l_trip_status_val := null;
               l_status_count := nvl(
                  apex_json.get_count(
                     'items[%d].statuses.items',
                     i
                  ),
                  0
               );
               for s in 1..l_status_count loop
                  l_status_gid := apex_json.get_varchar2(
                     'items[%d].statuses.items[%d].statusTypeGid',
                     i,
                     s
                  );
                  if l_status_gid = 'NAQLEEN.TRIP_STATUS' then
                     l_status_val := apex_json.get_varchar2(
                        'items[%d].statuses.items[%d].statusValueGid',
                        i,
                        s
                     );
                     l_trip_status_val := l_status_val;
                     exit;
                  end if;
               end loop;

               -- B. Validation Logic (Simplified: removed TASK_ASSIGNED check)
               l_is_valid := false;
               if l_trip_status_val not in ( 'NAQLEEN.TRIP_COMPLETED',
                                             'NAQLEEN.TRIP_CANCELLED' ) then
                  l_is_valid := true;
               end if;

               -- 4. Add if Valid
               if l_is_valid then
                  l_ct_nbr := apex_json.get_varchar2(
                     'items[%d].attribute3',
                     i
                  );
                  l_tr_nbr := apex_json.get_varchar2(
                     'items[%d].attribute7',
                     i
                  );
                  l_dr_name := apex_json.get_varchar2(
                     'items[%d].attribute8',
                     i
                  );
                  
                  -- Truck Fallback
                  if l_tr_nbr is null then
                     l_pw_unt := apex_json.get_varchar2(
                        'items[%d].powerUnitGid',
                        i
                     );
                     if l_pw_unt is not null then
                        l_tr_nbr := replace(
                           l_pw_unt,
                           'NAQLEEN.',
                           ''
                        );
                     end if;
                  end if;
                  
                  -- Container Fallback
                  if l_ct_nbr is null then
                     begin
                        select container_nbr
                          into l_ct_nbr
                          from xxotm_customer_inventory_t
                         where shipment_nbr = l_sh_xid
                         and xxotm_customer_inventory_t.location = v_location
                         fetch first 1 rows only;
                     exception
                        when others then
                           l_ct_nbr := null;
                     end;
                  end if;

                  l_verified_shipments.extend;
                  l_verified_shipments(l_verified_shipments.count).shipment_nbr := l_sh_xid;
                  l_verified_shipments(l_verified_shipments.count).shipment_name := l_sh_name;
                  l_verified_shipments(l_verified_shipments.count).container_nbr := l_ct_nbr;
                  l_verified_shipments(l_verified_shipments.count).truck_nbr := l_tr_nbr;
                  l_verified_shipments(l_verified_shipments.count).driver_name := l_dr_name;
               end if;
            end loop;
         end if;
      exception
         when others then
            null;
      end;
   end if;
   
   -- 5. Build JSON Response
   if l_verified_shipments.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_verified_shipments.count loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_verified_shipments(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_verified_shipments(i).shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_verified_shipments(i).container_nbr
         );
         apex_json.write(
            'truck_nbr',
            l_verified_shipments(i).truck_nbr
         );
         apex_json.write(
            'driver_name',
            l_verified_shipments(i).driver_name
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No active loading LCL shipments found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_loading_lcl_shipments;

   -- ========================================================================
   -- XX_OTM_GET_OFFLOADING_LCL_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_OFFLOADING_LCL_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_offloading_lcl_shipments (
   p_search_text in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 23-Jan-2026
   -- Description  : Gets verified shipment numbers for active OFFLOADING_LCL tasks only.
   --                Logic:
   --                1. Fetch candidate shipment IDs from local assignment table.
   --                2. Call OTM API with shipmentName=OFFLOADING_LCL filter.
   --                3. Validate Status (NOT COMPLETED/CANCELLED).
   --                4. Validate Event (Must have TASK_ASSIGNED).
   -- Updated      : Removed Debug Logs.
   -- Updated      : Added checks for statusCodeGid in trackingEvents.

   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_shipment_list        varchar2(32767) := '[';
   l_shipment_count       number := 0;
   l_api_shipment_count   number;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   
   -- Loop vars
   l_sh_xid               varchar2(100);
   l_sh_name              varchar2(100);
   l_ct_nbr               varchar2(100);
   l_tr_nbr               varchar2(100);
   l_dr_name              varchar2(200);
   l_pw_unt               varchar2(200);
   
   -- Validation vars
   l_status_count         number;
   l_events_count         number;
   l_status_gid           varchar2(200);
   l_status_val           varchar2(200);
   l_event_gid            varchar2(200);
   l_is_valid             boolean;
   l_trip_status_val      varchar2(200);
   l_has_task_assigned    boolean;
   
   -- Output Collection
   type t_shpmt_rec is record (
         shipment_nbr  varchar2(100),
         shipment_name varchar2(100),
         container_nbr varchar2(100),
         truck_nbr     varchar2(100),
         driver_name   varchar2(200)
   );
   type t_shpmt_tab is
      table of t_shpmt_rec;
   l_verified_shipments   t_shpmt_tab := t_shpmt_tab();
   cursor c_assignments is
   select shipment_nbr
     from xxotm_task_assignment_t
    where shipment_nbr is not null
      and ( p_search_text is null
       or upper(shipment_nbr) like '%'
                                   || upper(p_search_text)
                                   || '%' ) and xxotm_task_assignment_t.location = v_location
    group by shipment_nbr
    order by max(assigned_date) desc;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- 1. Collect candidate shipments from local assignment table
   for r in c_assignments loop
      l_shipment_count := l_shipment_count + 1;
      if l_shipment_count > 1 then
         l_shipment_list := l_shipment_list || ',';
      end if;
      l_shipment_list := l_shipment_list
                         || '"'
                         || r.shipment_nbr
                         || '"';
      
      -- Batch limit
      if l_shipment_count >= 100 then
         exit;
      end if;
   end loop;
   l_shipment_list := l_shipment_list || ']';
   if l_shipment_count > 0 then
      -- 2. Call OTM API 
      l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
               || '?q=shipmentName eq "OFFLOADING_LCL" and shipmentXid in '
               || l_shipment_list
               || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
               || ' and refnums.shipmentRefnumValue eq ' || v_location
               || '&limit=200&expand=statuses,trackingEvents';
      begin
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
             p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         if
            apex_web_service.g_status_code = 200
            and l_response_clob is not null
         then
            apex_json.parse(l_response_clob);
            l_api_shipment_count := nvl(
               apex_json.get_count('items'),
               0
            );
            
            -- 3. Verify each shipment
            for i in 1..l_api_shipment_count loop
               l_sh_xid := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );
               l_sh_name := apex_json.get_varchar2(
                  'items[%d].shipmentName',
                  i
               );
               
               -- A. Get Trip Status
               l_trip_status_val := null;
               l_status_count := nvl(
                  apex_json.get_count(
                     'items[%d].statuses.items',
                     i
                  ),
                  0
               );
               for s in 1..l_status_count loop
                  l_status_gid := apex_json.get_varchar2(
                     'items[%d].statuses.items[%d].statusTypeGid',
                     i,
                     s
                  );
                  if l_status_gid = 'NAQLEEN.TRIP_STATUS' then
                     l_status_val := apex_json.get_varchar2(
                        'items[%d].statuses.items[%d].statusValueGid',
                        i,
                        s
                     );
                     l_trip_status_val := l_status_val;
                     exit;
                  end if;
               end loop;

               -- B. Validation Logic
               l_is_valid := false;
               l_has_task_assigned := false;
               if l_trip_status_val not in ( 'NAQLEEN.TRIP_COMPLETED',
                                             'NAQLEEN.TRIP_CANCELLED' ) then
                   -- Check Events for TASK_ASSIGNED
                   -- Updated to check statusCodeGid, quickEventGid, trackingEventXid
                  l_events_count := nvl(
                     apex_json.get_count(
                        'items[%d].trackingEvents.items',
                        i
                     ),
                     0
                  );
                  for e in 1..l_events_count loop
                     l_event_gid := apex_json.get_varchar2(
                        'items[%d].trackingEvents.items[%d].statusCodeGid',
                        i,
                        e
                     );
                     if l_event_gid is null then
                        l_event_gid := apex_json.get_varchar2(
                           'items[%d].trackingEvents.items[%d].quickEventGid',
                           i,
                           e
                        );
                     end if;
                     if l_event_gid is null then
                        l_event_gid := apex_json.get_varchar2(
                           'items[%d].trackingEvents.items[%d].trackingEventXid',
                           i,
                           e
                        );
                     end if;

                     if
                        l_event_gid is not null
                        and ( l_event_gid = 'NAQLEEN.TASK_ASSIGNED'
                        or l_event_gid like '%TASK_ASSIGNED' )
                     then
                        l_has_task_assigned := true;
                        exit;
                     end if;
                  end loop;

                  if l_has_task_assigned then
                     l_is_valid := true;
                  end if;
               end if;

               -- 4. Add if Valid
               if l_is_valid then
                  l_ct_nbr := apex_json.get_varchar2(
                     'items[%d].attribute3',
                     i
                  );
                  l_tr_nbr := apex_json.get_varchar2(
                     'items[%d].attribute7',
                     i
                  );
                  l_dr_name := apex_json.get_varchar2(
                     'items[%d].attribute8',
                     i
                  );
                  
                  -- Truck Fallback
                  if l_tr_nbr is null then
                     l_pw_unt := apex_json.get_varchar2(
                        'items[%d].powerUnitGid',
                        i
                     );
                     if l_pw_unt is not null then
                        l_tr_nbr := replace(
                           l_pw_unt,
                           'NAQLEEN.',
                           ''
                        );
                     end if;
                  end if;
                  
                  -- Container Fallback
                  if l_ct_nbr is null then
                     begin
                        select container_nbr
                          into l_ct_nbr
                          from xxotm_customer_inventory_t
                         where shipment_nbr = l_sh_xid
                         and xxotm_customer_inventory_t.location = v_location
                         fetch first 1 rows only;
                     exception
                        when others then
                           l_ct_nbr := null;
                     end;
                  end if;

                  l_verified_shipments.extend;
                  l_verified_shipments(l_verified_shipments.count).shipment_nbr := l_sh_xid;
                  l_verified_shipments(l_verified_shipments.count).shipment_name := l_sh_name;
                  l_verified_shipments(l_verified_shipments.count).container_nbr := l_ct_nbr;
                  l_verified_shipments(l_verified_shipments.count).truck_nbr := l_tr_nbr;
                  l_verified_shipments(l_verified_shipments.count).driver_name := l_dr_name;
               end if;
            end loop;
         end if;
      exception
         when others then
            null;
      end;
   end if;
   
   -- 5. Build JSON Response
   if l_verified_shipments.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_verified_shipments.count loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_verified_shipments(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_verified_shipments(i).shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_verified_shipments(i).container_nbr
         );
         apex_json.write(
            'truck_nbr',
            l_verified_shipments(i).truck_nbr
         );
         apex_json.write(
            'driver_name',
            l_verified_shipments(i).driver_name
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No active offloading LCL shipments found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_offloading_lcl_shipments;

   -- ========================================================================
   -- XX_OTM_GET_OPERATORS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_OPERATORS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_operators
as
    -- Last Updated Date : 04-Feb-2026
    -- Description : Fetch drivers from OTM and return ID + Name (FirstName).
    --               Output format: [{id: XID, name: Name}, ...]

   l_clob                 clob;
   l_url                  varchar2(4000) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/drivers?q=driverTypeGid ne "DEFAULT"'
   ;
   j                      apex_json.t_values;
   l_count                number;
   l_driver_xid           varchar2(200);
   l_first_name           varchar2(200);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
    -- Workspace Context
   l_workspace_id         number;
   l_workspace_name       varchar2(100) := 'XXOTM';
begin

    -- Set Request Headers
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';

    -- Make REST Request
   l_clob := apex_web_service.make_rest_request(
      p_url                  => l_url,
      p_http_method          => 'GET',
      p_credential_static_id => l_credential_static_id,
      p_wallet_path => xxotm_get_cfg('WALLET_PATH')
   );

   dbms_output.put_line('Response' || l_clob);

    -- Parse the Response
   apex_json.parse(
      j,
      l_clob
   );
   
    -- Construct the Output JSON
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.open_array('data');

    -- Loop through request items
   l_count := apex_json.get_count(
      p_path   => 'items',
      p_values => j
   );
   for i in 1..l_count loop
      l_driver_xid := apex_json.get_varchar2(
         p_path   => 'items[%d].driverXid',
         p0       => i,
         p_values => j
      );

      l_first_name := apex_json.get_varchar2(
         p_path   => 'items[%d].firstName',
         p0       => i,
         p_values => j
      );

      if l_driver_xid is not null then
         apex_json.open_object;
         apex_json.write(
            'id',
            l_driver_xid
         );
         apex_json.write(
            'name',
               l_first_name
         ); -- Fallback to ID if name is null? Or just null?
         apex_json.close_object;
      end if;
   end loop;

   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Unexpected error: ' || sqlerrm
      );
      apex_json.write(
         'error_backtrace',
         dbms_utility.format_error_backtrace
      );
      
      -- Include raw response if available
      if l_clob is not null then
         apex_json.write(
            'api_response',
            l_clob
         );
      end if;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_operators;

   -- ========================================================================
   -- XX_OTM_GET_PLUG_IN_OUT_CONTAINERS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_PLUG_IN_OUT_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_plug_in_out_containers (
   searchtext in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   cursor c_containers is
   select distinct container_nbr
     from xxotm_container_inventory_t
    where position is not null
      and container_type in ( '20RT',
                              '22RT',
                              '25RT',
                              '40RT',
                              '42RT',
                              '45RT' )
                              AND CONTAINER_RELEASED_TIME IS NULL  
      and upper(container_nbr) like '%'
                                    || upper(searchtext)
                                    || '%'
      and xxotm_container_inventory_t.location = v_location;

   l_count number := 0;
begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- First count matching rows
   select count(*)
     into l_count
     from xxotm_container_inventory_t
    where position is not null
      and container_type in ( '20RT',
                              '22RT',
                              '25RT',
                              '40RT',
                              '42RT',
                              '45RT' )
                              AND CONTAINER_RELEASED_TIME IS NULL
      and upper(container_nbr) like '%'
                                    || upper(searchtext)
                                    || '%'
      and xxotm_container_inventory_t.location = v_location;


   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_count = 0 then
        -- No data found
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      dbms_output.put_line(apex_json.get_clob_output);
      return;
   end if;

    -- If data exists → Success response
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_array('data');
   for r_container in c_containers loop
      apex_json.write(r_container.container_nbr);
   end loop;
   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   dbms_output.put_line(apex_json.get_clob_output);
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
--        apex_json.open_array('data');
--        apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      dbms_output.put_line(apex_json.get_clob_output);
end xx_otm_get_plug_in_out_containers;

   -- ========================================================================
   -- XX_OTM_GET_PLUG_IN_OUT_CONTAINER_DETAILS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_PLUG_IN_OUT_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_plug_in_out_container_details (
    p_contianer_nbr IN VARCHAR2,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
AS
     l_count NUMBER := 0;
v_location varchar2(100);
    CURSOR c_history IS  
    SELECT type,
               set_point_temp,
               current_temp,
               remarks,
               timestamp
          FROM xxotm_pluginout_t p ,xxotm_container_inventory_t c
    where p.container_nbr = c.CONTAINER_NBR 
    AND c.INBOUND_SHIPMENT_NBR = p.INBOUND_SHIPMENT_NBR AND 
    c.CONTAINER_STORED_TIME IS NOT NULL
    AND c.CONTAINER_RELEASED_TIME IS null
    AND c.CONTAINER_TYPE in ( '20RT',
                              '22RT',
                              '25RT',
                              '40RT',
                              '42RT',
                              '45RT' )
    and c.location = v_location
      and upper(c.container_nbr) = upper(p_contianer_nbr);
          
BEGIN
v_location := xx_get_user_location(p_user_id);
-- Location is mandatory. xx_get_user_location returns NULL when
-- req_location_id is absent, malformed, or not permitted for this user;
-- it no longer falls back to a default site. Continuing on NULL would
-- filter on "location = NULL" and return an empty result set -- an empty
-- screen with no error, which is worse than a refusal.
if v_location is null then
   xxotm_location_required;
   return;
end if;

    apex_json.initialize_clob_output;
    apex_json.open_object;
    SELECT count(*) INTO l_count FROM xxotm_container_inventory_t c WHERE 
     c.CONTAINER_STORED_TIME IS NOT NULL AND c.CONTAINER_RELEASED_TIME IS NULL AND upper(c.container_nbr) = upper(p_contianer_nbr) and c.location = v_location;
                                    
    IF (l_count > 0 ) THEN 
    
    apex_json.write('response_message', 'Success');
    apex_json.write('response_code', 200);

    apex_json.open_object('data');
    apex_json.write('container_nbr', p_contianer_nbr);
    apex_json.open_array('history');

    FOR r_history IN c_history LOOP
        apex_json.open_object;
        apex_json.write('type', r_history.type);
        apex_json.write('setPointTemp', r_history.set_point_temp);
        apex_json.write('currentTemp', r_history.current_temp);
        apex_json.write('remarks', r_history.remarks);
        apex_json.write('timestamp', r_history.timestamp);
        apex_json.close_object;
    END LOOP;

    apex_json.close_array;  -- history
    apex_json.close_object; -- data
    apex_json.close_object; -- main

    htp.prn(apex_json.get_clob_output);
     DBMS_OUTPUT.PUT_LINE(apex_json.get_clob_output);
ELSE 
	  apex_json.write('response_message', 'Container Not Found');
    apex_json.write('response_code', 404);
     apex_json.close_object;
htp.prn(apex_json.get_clob_output);
	END IF;
EXCEPTION
    WHEN OTHERS THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_message', 'Error: ' || SQLERRM);
        apex_json.write('response_code', 500);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
         DBMS_OUTPUT.PUT_LINE(apex_json.get_clob_output);
END xx_otm_get_plug_in_out_container_details;

   -- ========================================================================
   -- XX_OTM_GET_POSITION_CONTAINER_TRUCKS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_POSITION_CONTAINER_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_position_container_trucks (
   p_search_text in varchar2,
   p_user_id in varchar2 default null
)
as
    v_location varchar2(100);
    l_url                  varchar2(4000);
   -- Widened from prod's varchar2(50). Prod's hotfix assigns the raw
   -- vehicle_master.shipment_nbr here, which can be a COMMA-SEPARATED LIST, and
   -- only splits it on the next statement -- so the assignment itself raises
   -- ORA-06502 as soon as the list exceeds 50 characters. Two prefixed shipment
   -- numbers run about 37, which is why it has held so far; dual container is
   -- exactly what makes the multi-shipment case ordinary.
   l_shipment_xid         varchar2(4000);
   l_response_clob        clob;
   
   -- Flags for status checks
   l_has_gate_in          boolean;
   l_has_gate_out         boolean;
   l_has_container_stored boolean;
   l_event_count          number;
   l_status_code          varchar2(200);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   cursor c_trucks is
   select truck_nbr,
          shipment_nbr          -- added by prod after the snapshot (drift_scan)
     from xxotm_vehicle_master_t
    where entry_time is not null
      and exit_time is null
      and ( p_search_text is null
       or truck_nbr like '%'
                         || p_search_text
                         || '%' ) and xxotm_vehicle_master_t.location = v_location;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_array('data');
   for r_truck in c_trucks loop
      -- Prod hotfix, post-snapshot (found by db/tools/drift_scan.py): take the
      -- shipment from Vehicle Master first and only fall back to a query on
      -- XXOTM_SHIPMENTS_T when it is null. Saves a per-truck query on the
      -- common path.
      l_shipment_xid := r_truck.shipment_nbr;

      -- Multiple shipments arrive comma-separated; take the first.
      if l_shipment_xid is not null
         and instr(l_shipment_xid, ',') > 0
      then
         l_shipment_xid := trim(regexp_substr(l_shipment_xid, '[^,]+', 1, 1));
      end if;

      -- Vehicle Master stores the prefixed form; the API path adds its own.
      if l_shipment_xid is not null
         and instr(l_shipment_xid, 'NAQLEEN.') > 0
      then
         l_shipment_xid := replace(l_shipment_xid, 'NAQLEEN.', '');
      end if;

      if l_shipment_xid is null then
         begin
            select shipment_xid
              into l_shipment_xid
              from xxotm_shipments_t st
             where r_truck.truck_nbr = st.truck_3pl
               and st.trip_status = 'TRIP_STARTED'   -- added by prod post-snapshot
               and ( st.shipment_name like '%INBOUND_CONTAINER%'
                or st.shipment_name like '%STORE_AS_IT_IS%'  or st.shipment_name = 'CFS' )
               and st.location = v_location
             ORDER BY UPDATE_DATE DESC FETCH FIRST 1 ROWS ONLY ;
         exception
            when no_data_found then
               l_shipment_xid := null;
         end;
      end if;

      if l_shipment_xid is not null then
      
         -- Reset flags for each shipment
         l_has_gate_in := false;
         l_has_gate_out := false;
         l_has_container_stored := false;

         ------------------------------------------------------------------
         -- Single API Call: Fetch ALL tracking events
         ------------------------------------------------------------------
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                  || l_shipment_xid
                  || '/trackingEvents';
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         begin
            l_response_clob := apex_web_service.make_rest_request(
               p_url         => l_url,
               p_http_method => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );

            apex_json.parse(l_response_clob);
            l_event_count := apex_json.get_count('items');
            for i in 1..l_event_count loop
               l_status_code := apex_json.get_varchar2(
                  'items[%d].statusCodeGid',
                  i
               );
               
            
               if instr(
                  l_status_code,
                  'GATE IN'
               ) > 0 then
                  l_has_gate_in := true;
               end if;
               if instr(
                  l_status_code,
                  'GATE OUT'
               ) > 0 then
                  l_has_gate_out := true;
               end if;
               if instr(
                  l_status_code,
                  'CONTAINER STORED'
               ) > 0 then
                  l_has_container_stored := true;
               end if;
            end loop;

         exception
            when others then
               -- If API fails, we likely can't validate position, so usually assume False or skip.
               l_has_gate_in := false;
         end;

       
         if
            l_has_gate_in
            and not l_has_gate_out
            and not l_has_container_stored
         then
            apex_json.write(r_truck.truck_nbr);
         end if;
      end if;
   end loop;

   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_position_container_trucks;

   -- ========================================================================
   -- XX_OTM_GET_RELEASE_CONTAINER_TRUCKS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_RELEASE_CONTAINER_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_release_container_trucks (
   p_search_text in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Last Updated Date : 22-Dec-2024
   -- Description : Get release container trucks
   --               LRO/CRO: from vehicle_master with GATE IN status (no API call)
   --               No order_type: from vehicle_master with GATE IN, validated via shipments API (limit 500)
   
   -- API variables
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_api_count            number;
   l_shipment_xid         varchar2(200);
   
   -- Collection to store unique trucks
   type t_truck_tab is
      table of varchar2(200) index by varchar2(200);
   l_trucks               t_truck_tab;
   l_valid_cfs_trucks     t_truck_tab;
   l_truck_key            varchar2(200);
   l_truck_count          number := 0;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- Part 1: Get LRO/CRO trucks from vehicle_master with GATE IN status (no API call needed)
   for r in (
      select distinct v.truck_nbr
        from xxotm_vehicle_master_t v
       where v.entry_time is not null
         and v.exit_time is null
         and v.status like '%GATE IN%'
         and v.order_type in ( 'CRO',
                               'LRO' )
         and ( p_search_text is null
          or upper(v.truck_nbr) like '%'
                                     || upper(p_search_text)
                                     || '%' )
        and v.location = v_location
   ) loop
      l_trucks(r.truck_nbr) := r.truck_nbr;
   end loop;
   
   -- Part 2: Get trucks with GATE IN and NO order_type
   -- Call shipments API with RELEASE_CFS and TRIP_STARTED status (limit 500)
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
            || '?q=shipmentName eq "RELEASE_CFS"'
            || ' and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
            || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"'
            || '&fields=shipmentXid'
            || '&limit=500';
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );

      apex_json.parse(l_response_clob);
      l_api_count := apex_json.get_count('items');
      if l_api_count is null then
         l_api_count := 0;
      end if;
      
      -- Get truck numbers from shipments table for these valid RELEASE_CFS shipments
      for i in 1..l_api_count loop
         l_shipment_xid := apex_json.get_varchar2(
            'items[%d].shipmentXid',
            i
         );
         l_shipment_xid := replace(
            l_shipment_xid,
            'NAQLEEN.',
            ''
         );
         
         -- Get truck number from shipments table and store as valid CFS truck
         for r_truck in (
            select distinct case
                               when power_unit is not null then
                                  power_unit
                               else
                                  truck_3pl
                            end as truck_nbr
              from xxotm_shipments_t
             where shipment_xid = l_shipment_xid
               and xxotm_shipments_t.location = v_location
               and ( power_unit is not null
                or truck_3pl is not null )
         ) loop
            if r_truck.truck_nbr is not null then
               l_valid_cfs_trucks(r_truck.truck_nbr) := r_truck.truck_nbr;
            end if;
         end loop;
      end loop;

   exception
      when others then
         -- On API error, continue with what we have
         null;
   end;
   
   -- Now get trucks from vehicle_master with GATE IN and NO order_type
   -- Only include if they exist in the valid CFS trucks list
   for r in (
      select distinct v.truck_nbr
        from xxotm_vehicle_master_t v
       where v.entry_time is not null
         and v.exit_time is null
         and v.status like '%GATE IN%'
         and v.order_type is null
         and ( p_search_text is null
          or upper(v.truck_nbr) like '%'
                                     || upper(p_search_text)
                                     || '%' ) and v.location = v_location
   ) loop
      -- Only add if truck is in the valid CFS trucks list
      if l_valid_cfs_trucks.exists(r.truck_nbr) then
         l_trucks(r.truck_nbr) := r.truck_nbr;
      end if;
   end loop;
   
   -- Build response
   l_truck_count := l_trucks.count;
   if l_truck_count > 0 then
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_array('data');
      l_truck_key := l_trucks.first;
      while l_truck_key is not null loop
         apex_json.write(l_trucks(l_truck_key));
         l_truck_key := l_trucks.next(l_truck_key);
      end loop;

      apex_json.close_array;
   else
      apex_json.write(
         'response_message',
         'No Data Found'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_release_container_trucks;

   -- ========================================================================
   -- XX_OTM_GET_REPAIR_STATUS_CONTAINERS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_REPAIR_STATUS_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_repair_status_containers (
   p_search_text in varchar2 default null,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_count      number := 0;
   type t_container_list is
      table of xxotm_container_inspection_t.container_nbr%type;
   l_containers t_container_list;
   v_location varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   select distinct container_nbr
   bulk collect
     into l_containers
     from xxotm_container_inspection_t
    where ( p_search_text is null
       or upper(container_nbr) like '%'
                                    || upper(p_search_text)
                                    || '%' )
        and xxotm_container_inspection_t.location = v_location
      and rownum <= 50;

   apex_json.open_object;
   if l_containers.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_containers.count loop
         apex_json.write(l_containers(i));
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
exception
   when others then
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
end;

   -- ========================================================================
   -- XX_OTM_GET_RESTACKING_CONTAINERS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_RESTACKING_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_restacking_containers (
   p_search_text in varchar2 default null,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_data_array       json_array_t;
   l_response         json_object_t;
   l_obj              json_object_t;
   j                  apex_json.t_values;
   
    v_location varchar2(100);
   cursor c_data_cursor is
   select distinct ci.container_nbr
     from xxotm_container_inventory_t ci
    where ci.inbound_shipment_nbr IS NOT NULL AND  ci.outbound_shipment_nbr is NULL AND ci.POSITION IS NOT NULL 
    AND ci.container_nbr IS NOT NULL
    AND ci.container_stored_time IS NOT NULL AND ci.container_released_time IS null
      and ( p_search_text is null
       or upper(ci.container_nbr) like '%'
                                       || upper(p_search_text)
                                       || '%' )
      and ci.location = v_location
    order by ci.container_nbr;
    
   l_container_nbr    varchar2(50);
   l_position         varchar2(100);
   l_container_type   varchar2(50);
   e_no_data exception;
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
   l_response := json_object_t();
   l_data_array := json_array_t();
   
   -- 1. Build Containers Array
   open c_data_cursor;
   loop
      fetch c_data_cursor into
         l_container_nbr;
      exit when c_data_cursor%notfound;
      l_data_array.append(l_container_nbr);
   end loop;
   close c_data_cursor;

   if l_data_array.get_size() = 0 then
      raise e_no_data;
   end if;

   -- 4. Final Response
   l_response.put('response_code', 200);
   l_response.put('response_message', 'Success');
   l_response.put('data', l_data_array);

   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      l_response.get_number('response_code')
   );
   apex_json.write(
      'response_message',
      l_response.get_string('response_message')
   );
   
   -- Parse the data object to CLOB for output
   apex_json.parse(
      j,
      l_response.get('data').to_clob()
   );
   apex_json.write(
      'data',
      j
   );
   
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when e_no_data then
      l_response := json_object_t();
      l_response.put('response_code', 404);
      l_response.put('response_message', 'No data found');
      
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', l_response.get_number('response_code'));
      apex_json.write('response_message', l_response.get_string('response_message'));
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
   when others then
      l_response := json_object_t();
      l_response.put('response_code', 400);
      l_response.put('response_message', 'ERROR WHILE EXECUTING METHOD: ' || sqlerrm);
      
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', l_response.get_number('response_code'));
      apex_json.write('response_message', l_response.get_string('response_message'));
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_restacking_containers;

   -- ========================================================================
   -- XX_OTM_GET_RESTACKING_CONTAINER_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_RESTACKING_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_restacking_container_details (
   p_container_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   type record_type is record (
         container_nbr    varchar2(50),
         current_position varchar2(20),
         container_type   varchar2(10)
   );
   l_record          record_type;
   l_event_data      json_object_t;
   l_terminals_array json_array_t;
   l_response        json_object_t;
   j                 apex_json.t_values;
   cursor c_data_cursor is
   select distinct ci.container_nbr,
                    (select p.terminal||'-'||p.block||'-'||p.lot_no||'-'||p.row_no||'-'||p.level_no
                       from xxotm_position_master_t p
                      -- The ci. qualifier is required. XXOTM_POSITION_MASTER_T has
                      -- a CONTAINER_NBR column of its own, so an unqualified
                      -- container_nbr binds to p.container_nbr and the predicate
                      -- degenerates to p.is_occupied = p.container_nbr, correlating
                      -- nothing to the outer row. Backported from the dropped
                      -- XX_OTM_GET_RESTACKING_CONTAINER_DETAILS_TEST clone.
                      where p.is_occupied = ci.container_nbr
                        and ci.inbound_shipment_nbr = p.shipment_nbr
                        and p.location = v_location) position,
                   sh.container_type
     from xxotm_container_inventory_t ci,
          xxotm_shipments_t sh
    where ci.CONTAINER_STORED_TIME is NOT null
      and ci.container_released_time is null
      and ci.container_nbr = sh.cont_no
      and upper(ci.container_nbr) = upper(p_container_nbr)
      and ci.location = v_location
      and sh.location = v_location;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Build JSON array from cursor
   l_response := json_object_t();
   -- Initialised BEFORE the loop. A zero-row cursor otherwise leaves
   -- l_event_data NULL, and the l_event_data.put('terminals', ...) after the loop
   -- then raises ORA-30625 (method dispatch on NULL SELF argument) -- which the
   -- handler converts into a 400, so the caller sees a validation error for what
   -- is really "no such container". Backported from the dropped
   -- XX_OTM_GET_RESTACKING_CONTAINER_DETAILS_TEST clone.
   l_event_data := json_object_t();
   open c_data_cursor;
   loop
      fetch c_data_cursor into l_record;
      exit when c_data_cursor%notfound;
      l_event_data.put(
         'container_nbr',
         l_record.container_nbr
      );
      l_event_data.put(
         'current_position',
         l_record.current_position
      );
      l_event_data.put(
         'type',
         l_record.container_type
      );
   end loop;

   l_terminals_array := json_array_t();
   for i in (
      select distinct terminal
        from xxotm_position_master_t
       where is_occupied = 'N'
         and xxotm_position_master_t.location = v_location
       order by terminal
   ) loop
      l_terminals_array.append(i.terminal);
   end loop;

   -- 3. Construct Data Object
   l_event_data.put(
      'terminals',
      l_terminals_array
   );
   close c_data_cursor;
   -- Wrap in response object
   l_response.put(
      'response_code',
      200
   );
   l_response.put(
      'response_message',
      'Success'
   );
   l_response.put(
      'data',
      l_event_data
   );

   -- Output using APEX_JSON
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      l_response.get('response_code').to_number()
   );
   apex_json.write(
      'response_message',
      replace(
         l_response.get('response_message').to_string(),
         '"',
         ''
      )
   );

   -- Convert JSON array string to APEX_JSON.t_values
   apex_json.parse(
      j,
      l_response.get('data').to_string()
   );
   apex_json.write(
      'data',
      j
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      l_response := json_object_t();
      l_response.put(
         'response_code',
         400
      );
      l_response.put(
         'response_message',
         'ERROR WHILE EXECUTING METHOD: ' || sqlerrm
      );
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         l_response.get('response_code').to_number()
      );
      apex_json.write(
         'response_message',
         replace(
            l_response.get('response_message').to_string(),
            '"',
            ''
         )
      );

      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_restacking_container_details;

   -- ========================================================================
   -- XX_OTM_GET_ROLE_INFO   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_ROLE_INFO.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_role_info (
   p_role in varchar2,
   p_platform IN varchar2 DEFAULT null
)
as
   v_screen_count    number := 0;
   v_associated_role varchar2(4000); -- Increased size for list
begin
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Role info retrieved successfully'
   );

    -- Role information with screens included
   apex_json.open_object('role_info');
   apex_json.write(
      'role',
      p_role
   );
   apex_json.write(
      'name',
      initcap(replace(
         p_role,
         '_',
         ' '
      ))
   );

    -- Screens array within role_info
   apex_json.open_array('screens');
   for rec in (
      select screen_name,
             screen_path,
             is_active
        from xx_role_config
       where role = upper(trim(p_role)) AND (p_platform IS NOT NULL AND  platform = p_platform)
       order by screen_name
   ) loop
      v_screen_count := v_screen_count + 1;
      apex_json.open_object;
      apex_json.write(
         'screen_name',
         rec.screen_name
      );
      apex_json.write(
         'screen_path',
         rec.screen_path
      );
      apex_json.write(
         'is_active',
         case
               when rec.is_active = 'Y' then
                  true
               else false
            end
      );

        -- Admin specific logic: Add 'role' field referencing other roles
        -- Uses LISTAGG to capture ALL roles associated with this screen
      if upper(trim(p_role)) = 'ADMIN' then
         begin
            select listagg(role, ',') within group (order by role)
              into v_associated_role
              from xx_role_config
             where screen_path = rec.screen_path
               and role <> 'ADMIN'  AND (p_platform IS NOT NULL AND  platform = p_platform);
         exception
            when no_data_found then
               v_associated_role := null;
         end;

         if v_associated_role is not null then
            apex_json.write(
               'role',
               v_associated_role
            );
         end if;
      end if;

      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.close_object;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
exception
   when no_data_found then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'Role not found: ' || p_role
      );
      apex_json.write(
         'role',
         p_role
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Unexpected error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xx_otm_get_role_info;

   -- ========================================================================
   -- XX_OTM_GET_SHIPMENTS_BY_BOOKING   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_SHIPMENTS_BY_BOOKING.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_shipments_by_booking (
   p_booking_no  in varchar2,
   p_search_text in varchar2 default null,
   p_page_num    in number default 1,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Last Updated Date : 18-Dec-2025
   -- Last Updated By : Sanjit
   -- Description : Added order_type lookup - skip shipment search for CRO/LRO

   l_url                    varchar2(32767);
   l_response_clob          clob;
   l_shipment_count         number;
   l_shipment_xid           varchar2(200);
   l_shipment_name          varchar2(200);
   l_container_nbr          varchar2(200);
   l_limit                  number := 25;
   l_offset                 number;
   l_credential_static_id   varchar2(20) := 'OTM_API_AUTH';
   l_order_type             varchar2(50);
   l_fetched_container_type varchar2(50);
   l_refnum_count           number;
   l_ref_qual               varchar2(200);
   l_ref_value              varchar2(200);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- Get order type from container inventory table
   begin
      select order_type
        into l_order_type
        from xxotm.xxotm_container_inventory_t
       where upper(booking_id) = upper(p_booking_no) AND order_type IN ('STORE_AS_IT_IS','RELEASE_CFS','CFS','CRO','LRO')
         and rownum = 1;
   exception
      when no_data_found then
         l_order_type := null;
   end;

   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   
   -- Open data object
   apex_json.open_object('data');
   apex_json.write(
      'order_type',
      nvl(
         l_order_type,
         ''
      )
   );
   
   -- If order type is CRO or LRO, return empty shipments array without searching
   if l_order_type in ( 'CRO',
                        'LRO' ) then
      apex_json.open_array('shipments');
      apex_json.close_array;
      apex_json.close_object; -- Close data object
      apex_json.close_object; -- Close main object
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      return;
   end if;

   apex_json.open_array('shipments');

   -- Calculate offset (0-based) from page number (1-based)
   l_offset := ( p_page_num - 1 ) * l_limit;

   -- Construct URL with filters
   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
            || '?q=attribute1 eq "TERMINAL" and perspective eq "B" and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
            || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED" and shipmentName in ["STORE_AS_IT_IS","RELEASE_CFS","CFS"]'
            ;
   
   -- Add Booking Number filter (exact match)
   l_url := l_url
            || ' and refnums.shipmentRefnumQualGid eq "NAQLEEN.BOOKING_NO" and refnums.shipmentRefnumValue eq "'
            || p_booking_no
            || '"';

   -- Add Shipment Number search filter (contains) if provided
   if p_search_text is not null then
      l_url := l_url
               || ' and shipmentXid co "'
               || upper(p_search_text)
               || '"';
   end if;
   
   -- Add Pagination and Expansion
   l_url := l_url
            || '&limit='
            || l_limit
            || '&offset='
            || l_offset
            || '&expand=refnums,statuses';

   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );

      apex_json.parse(l_response_clob);
      l_shipment_count := apex_json.get_count('items');
      if l_shipment_count is null then
         l_shipment_count := 0;
      end if;
      for i in 1..l_shipment_count loop
         l_fetched_container_type := null;
         l_refnum_count := apex_json.get_count(
            'items[%d].refnums.items',
            i
         );
         if l_refnum_count is null then
            l_refnum_count := 0;
         end if;
         for j in 1..l_refnum_count loop
            l_ref_qual := apex_json.get_varchar2(
               'items[%d].refnums.items[%d].shipmentRefnumQualGid',
               i,
               j
            );
            l_ref_value := apex_json.get_varchar2(
               'items[%d].refnums.items[%d].shipmentRefnumValue',
               i,
               j
            );
            if l_ref_qual = 'NAQLEEN.CONTAINER_TYPE' then
               l_fetched_container_type := l_ref_value;
            end if;
         end loop;

         l_shipment_xid := apex_json.get_varchar2(
            'items[%d].shipmentXid',
            i
         );
         l_shipment_name := apex_json.get_varchar2(
            'items[%d].shipmentName',
            i
         );
         l_container_nbr := apex_json.get_varchar2(
            'items[%d].attribute3',
            i
         );
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_shipment_xid
         );
         apex_json.write(
            'shipment_name',
            l_shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_container_nbr
         );
         apex_json.write(
            'container_type',
            l_fetched_container_type
         );
         apex_json.close_object;
      end loop;

   exception
      when others then
         null;
   end;

   apex_json.close_array;  -- Close shipments array
   apex_json.close_object; -- Close data object
   apex_json.close_object; -- Close main object
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_object('data');
      apex_json.write(
         'order_type',
         ''
      );
      apex_json.open_array('shipments');
      apex_json.close_array;
      apex_json.close_object;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_shipments_by_booking;

   -- ========================================================================
   -- XX_OTM_GET_SHIPMENTS_FOR_CUSTOMER_INVENTORY   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_SHIPMENTS_FOR_CUSTOMER_INVENTORY.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_shipments_for_customer_inventory (
   p_customer_nbr in varchar2,
      p_search_text  in varchar2 default null
)
as
   cursor c_shipments is
   select shipment_xid,cont_no
     from xxotm_shipments_t
    where UPPER(liner_name) = UPPER(p_customer_nbr)
      and shipment_name in ( 'STORE_AS_IS_IT',
                             'DESTUFFING',
                             'STUFFING' )
                              and ( p_search_text is null
       or upper(shipment_xid) like '%'
                                   || upper(p_search_text)
                                   || '%' );
begin
   apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
   apex_json.open_array('data');
   for r in c_shipments loop
      apex_json.open_object();
      apex_json.write(
      'shipment_nbr',
        r.shipment_xid
      );
    apex_json.write(
      'container_nbr',
        r.cont_no
      );
	 apex_json.close_object();
   end loop;

   apex_json.close_array;
    apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_shipments_for_customer_inventory;

   -- ========================================================================
   -- XX_OTM_GET_SHIPMENT_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_SHIPMENT_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_shipment_details (
   p_shipment_nbr  in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   l_shipment_type    varchar2(50);
   l_shipment_name    varchar2(100);
   l_shipment_nbr     varchar2(50);
   l_container_nbr    varchar2(50);
   l_container_type   varchar2(50);
   l_truck_nbr        varchar2(50);
   l_driver_name      varchar2(100);
   l_driver_iqama_nbr varchar2(50);
   l_otm_order_nbr    varchar2(50);
   l_power_unit       varchar2(50);
   l_truck_3pl        varchar2(50);	
   l_customer_name 	  varchar2(50);	
   l_customer_nbr    varchar2(50);	
   l_load_status      varchar2(100 );
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_object('data');
   begin
        -- Fetch Shipment and Order Details
      select st.shipment_name,
             st.shipment_xid,
             st.cont_no,
             st.container_type,
             st.customer_name,
             st.liner_name,
             st.power_unit,
             st.truck_3pl,
             om.order_release_xid,
             st.load_status
        into
         l_shipment_name,
         l_shipment_nbr,
         l_container_nbr,
         l_container_type,
         l_customer_name,
         l_customer_nbr,
         l_power_unit,
         l_truck_3pl,
         l_otm_order_nbr,
         l_load_status
        from xxotm_shipments_t st
        ,xxotm_order_movements_t om
      WHERE st.shipment_xid  = om.SHIPMENT_XID AND  st.shipment_xid = p_shipment_nbr
      and st.location = v_location
        
         and rownum = 1;

        -- Determine Truck Number (Power Unit or 3PL)
      l_truck_nbr := nvl(
         l_power_unit,
         l_truck_3pl
      );

        -- Fetch Driver Details if Truck Number exists
--      if l_truck_nbr is not null then
--         begin
--            select xvmt.driver_name,
--                   xvmt.driver_iqama
--              into
--               l_driver_name,
--               l_driver_iqama_nbr
--              from xxotm_vehicle_master_t xvmt
--             where xvmt.truck_nbr = l_truck_nbr
--               and rownum = 1;
--         exception
--            when no_data_found then
--               l_driver_name := null;
--               l_driver_iqama_nbr := null;
--         end;
--      end if;

   exception
      when no_data_found then
            -- Handle case where shipment/customer combo is not found
         l_shipment_type := null;
         l_shipment_name := null;
         l_shipment_nbr := null;
         l_container_nbr := null;
         l_container_type := null;
         l_truck_nbr := null;
         l_driver_name := null;
         l_driver_iqama_nbr := null;
         l_otm_order_nbr := null;
   end;

    -- Write JSON Output

   apex_json.write(
      'shipment_type',
      l_shipment_type
   );
   apex_json.write(
      'shipment_name',
      l_shipment_name
   );
   apex_json.write(
      'shipment_nbr',
      l_shipment_nbr
   );
   apex_json.write(
      'container_nbr',
      l_container_nbr
   );
   apex_json.write(
      'container_type',
      l_container_type
   );
   apex_json.write(
      'customer_name',
      l_customer_name
   );
   apex_json.write(
      'customer_nbr',
      l_customer_nbr
   );
--   apex_json.write(
--      'driver_name',
--      l_driver_name
--   );
  apex_json.write(
     'load_status',
     nvl(l_load_status,'UNLOADED')
  );
   apex_json.write(
      'otm_order_nbr',
      l_otm_order_nbr
   );
   apex_json.close_object; -- Close data object
   apex_json.close_object; -- Close main object

   htp.prn(apex_json.get_clob_output);
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xx_otm_get_shipment_details;

   -- ========================================================================
   -- XX_OTM_GET_SHIPMENT_INVENTORY   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_SHIPMENT_INVENTORY.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_shipment_inventory (
   p_shipment_nbr  in varchar2 default null,
   p_customer_name in varchar2 default null,
   p_item_code     in varchar2 default null,
   p_booking_nbr   in varchar2 default null
)
as
   l_clob       clob;
   l_chunk_size integer := 4000;
   l_length     integer;
   l_offset     integer;
begin
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');

    -- Outer loop: Iterate through distinct shipments that match the criteria
   for s in (
      select distinct 
         xci.shipment_nbr,
                      xci.cust_name,
                      xci.cust_nbr,
                      xci.shipment_name,
                      (select operator from xxotm_task_assignment_t where shipment_nbr =  xci.shipment_nbr) operator,
                      ct.booking_id
        from xxotm_customer_inventory_t xci,XXOTM_CONTAINER_INVENTORY_T ct
       where  xci.shipment_nbr = ct.INBOUND_SHIPMENT_NBR  and      
       ( p_shipment_nbr is null
      or upper(xci.shipment_nbr) like '%'
               || upper(p_shipment_nbr)
               || '%'
    )
         and ( p_customer_name is null
          or upper(xci.cust_name) like '%'
                                           || upper(p_customer_name)
                                           || '%' )
         and ( p_item_code is null
          or upper(xci.item_code) like '%'
                                       || upper(p_item_code)
                                       || '%' )
         and ( p_booking_nbr is null
          or upper(ct.booking_id) like '%'
                                           || upper(p_booking_nbr)
                                           || '%' )
   ) loop
      apex_json.open_object;
        
        -- Shipment Header Details
      apex_json.write(
         'shipment_nbr',
         s.shipment_nbr
      );
      apex_json.write(
         'customer_name',
         s.cust_name
      );
      apex_json.write(
         'customer_number',
         s.cust_nbr
      );
      apex_json.write(
         'shipment_name',
         s.shipment_name
      );
      apex_json.write(
         'operator',
         s.operator
      );
      apex_json.write(
         'booking_id',
         s.booking_id
      );
        
        -- Inner loop: Items for this specific shipment
      apex_json.open_array('items');
      for i in (
         select xci.item_code,
                xci.item_description,
                xci.qty,
                xci.net_weight,
                xci.qty_uom,
                xci.weight_uom
           from xxotm_customer_inventory_t xci
          where ( xci.shipment_nbr = s.shipment_nbr
             )
            and ( p_item_code is null
             or upper(xci.item_code) like '%'
                                          || upper(p_item_code)
                                          || '%' )
                    -- No need to filter by customer again as it's implicit in the shipment grouping
      ) loop
         apex_json.open_object;
         apex_json.write(
            'item_code',
            i.item_code
         );
         apex_json.write(
            'item_description',
            i.item_description
         );
         apex_json.write(
            'quantity',
            i.qty
         );
         apex_json.write(
            'weight',
            i.net_weight
         );
       
         apex_json.write(
            'package_uom',
            i.qty_uom
         );
         apex_json.write(
            'weight_uom',
            i.weight_uom
         );
        
         apex_json.close_object;
      end loop;
      apex_json.close_array; -- End items array

      apex_json.close_object; -- End shipment object
   end loop;

   apex_json.close_array; -- End data array
   apex_json.close_object; -- End root object

   l_clob := apex_json.get_clob_output;
    
    -- Output in chunks
   l_length := dbms_lob.getlength(l_clob);
   l_offset := 1;
   while l_offset <= l_length loop
      htp.prn(dbms_lob.substr(
         l_clob,
         l_chunk_size,
         l_offset
      ));
      l_offset := l_offset + l_chunk_size;
   end loop;

   apex_json.free_output;
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      l_clob := apex_json.get_clob_output;
      htp.p(l_clob);
      apex_json.free_output;
end xx_otm_get_shipment_inventory;

   -- ========================================================================
   -- XX_OTM_GET_STUFFING_CONTAINERS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_STUFFING_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_stuffing_containers (
   p_search_text in varchar2
)
as
    -- Last Updated Date : 18-Dec-2025
    -- Last Updated By : Madhan
    -- Description : updated hardcoded credentials to web credentials
   cursor c_containers is
   select cont_no as container_nbr,
          shipment_xid
     from xxotm_shipments_t
    where shipment_name = 'STUFFING'
      and ( p_search_text is null
       or cont_no like '%'
                       || p_search_text
                       || '%' );

   l_api_url          varchar2(500);
   l_track_response   clob;
   l_status_code      varchar2(200);
   l_gate_in_count    number;
   l_gate_out_count   number;
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   type t_container_list is
      table of varchar2(100);
   l_valid_containers t_container_list := t_container_list();
begin
    -- Configure APEX_JSON
   apex_json.initialize_clob_output;
   apex_json.open_object;
   for r in c_containers loop
      l_api_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                   || 'NAQLEEN.'
                   || r.shipment_xid
                   || '/trackingEvents';
        
        -- Reset counters for each container
      l_gate_in_count := 0;
      l_gate_out_count := 0;
      begin
            -- Make API Call
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_track_response := apex_web_service.make_rest_request(
            p_url         => l_api_url,
            p_http_method => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
            
            -- Parse Response
         apex_json.parse(l_track_response);
            
            -- Check Events
         for i in 1..apex_json.get_count('items') loop
            l_status_code := apex_json.get_varchar2(
               'items[%d].statusCodeGid',
               i
            );
                
                -- Check for GATE IN
            if upper(l_status_code) like '%GATE IN%'
            or upper(l_status_code) = 'NAQLEEN.GATE IN'
            or upper(l_status_code) = 'GATE_IN' then
               l_gate_in_count := l_gate_in_count + 1;
                
                -- Check for GATE OUT
            elsif upper(l_status_code) like '%GATE OUT%'
            or upper(l_status_code) = 'NAQLEEN.GATE OUT'
            or upper(l_status_code) = 'GATE_OUT' then
               l_gate_out_count := l_gate_out_count + 1;
            end if;
         end loop;

            -- Logic: Valid if (Has Gate In) AND (Has NO Gate Out)
         if
            l_gate_in_count >= 1
            and l_gate_out_count = 0
         then
            l_valid_containers.extend;
            l_valid_containers(l_valid_containers.count) := r.container_nbr;
            
            -- Limit to 10 records
            if l_valid_containers.count >= 10 then
               exit;
            end if;
         end if;

      exception
         when others then
                -- Ignore API errors for a single container, just don't add it
            null;
      end;
   end loop;

    -- Build Final Response
   if l_valid_containers.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_valid_containers.count loop
         apex_json.write(l_valid_containers(i));
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No data found'
      );
        -- Empty data array might be polite, but adhering to user snippet style derived from chat history
        -- actually user snippet had commented out empty data array. I'll omit it for 404 to match.
   end if;

   apex_json.close_object;
    
    -- Output
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_stuffing_containers;

   -- ========================================================================
   -- XX_OTM_GET_STUFFING_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_STUFFING_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_stuffing_shipments (
   p_search_text in varchar2 default null,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 05-Jan-2026
   -- Description  : Gets verified shipment numbers for active STUFFING tasks.
   --                Uses Live OTM API with direct filtering.
   -- Updated      : Refactored to match destuffing pattern - direct OTM API query.

   l_api_base_url         varchar2(500) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'

   ;
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_item_count           number;
   
   -- Loop vars
   l_sh_xid               varchar2(100);
   l_sh_name              varchar2(100);
   l_ct_nbr               varchar2(100);
   l_tr_nbr               varchar2(100);
   l_dr_name              varchar2(200);
   l_pw_unt               varchar2(200);
   l_customer_nbr         varchar2(100);
   l_update_date_str      varchar2(100);
   
   -- Record to hold details
   type t_res_rec is record (
         shipment_nbr  varchar2(100),
         shipment_name varchar2(100),
         container_nbr varchar2(100),
         customer_nbr  varchar2(100),
         truck_nbr     varchar2(100),
         driver_name   varchar2(200),
         update_date   varchar2(100)
   );
   type t_res_tab is
      table of t_res_rec;
   l_verified_shipments   t_res_tab := t_res_tab();
   l_temp_rec             t_res_rec;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- 1. Construct URL with direct filtering
   l_url := l_api_base_url
            || '?q=perspective eq "B" and attribute1 eq "TERMINAL" and shipmentName in ["STUFFING","CROSS_STUFFING"]'
            || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
            || ' and refnums.shipmentRefnumValue eq ' || v_location
            || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"';
   
   -- Add search filter if provided
   if p_search_text is not null then
      l_url := l_url
               || ' and shipmentXid co "'
               || apex_util.url_encode(upper(p_search_text))
               || '"';
   end if;
   
   -- Add limit and sorting
   l_url := l_url || '&limit=200&orderBy=updateDate:desc';
   
   -- 2. Call OTM API
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
   exception
      when others then
         goto build_response;
   end;
   
   -- 3. Parse Response
   if
      apex_web_service.g_status_code = 200
      and l_response_clob is not null
   then
      apex_json.parse(l_response_clob);
      l_item_count := nvl(
         apex_json.get_count('items'),
         0
      );
      for i in 1..l_item_count loop
         l_sh_xid := apex_json.get_varchar2(
            'items[%d].shipmentXid',
            i
         );
         l_sh_name := apex_json.get_varchar2(
            'items[%d].shipmentName',
            i
         );
         l_ct_nbr := apex_json.get_varchar2(
            'items[%d].attribute3',
            i
         );
         l_tr_nbr := apex_json.get_varchar2(
            'items[%d].attribute7',
            i
         );
         l_dr_name := apex_json.get_varchar2(
            'items[%d].attribute8',
            i
         );
         l_update_date_str := apex_json.get_varchar2(
            'items[%d].updateDate.value',
            i
         );
         
         -- Get truck from powerUnitGid if not in attribute7
         if l_tr_nbr is null then
            l_pw_unt := apex_json.get_varchar2(
               'items[%d].powerUnitGid',
               i
            );
            if l_pw_unt is not null then
               l_tr_nbr := replace(
                  l_pw_unt,
                  'NAQLEEN.',
                  ''
               );
            end if;
         end if;
         
         -- Get container from inventory if not in attribute3
         if l_ct_nbr is null then
            begin
               select container_nbr
                 into l_ct_nbr
                 from xxotm_customer_inventory_t
                where shipment_nbr = l_sh_xid
                and xxotm_customer_inventory_t.location = v_location
                fetch first 1 rows only;
            exception
               when others then
                  l_ct_nbr := null;
            end;
         end if;
         
         -- Get customer number
         l_customer_nbr := null;
         if l_ct_nbr is not null then
            begin
               select DISTINCT cust_nbr
                 into l_customer_nbr
                 from xxotm_container_inventory_t
                where INBOUND_SHIPMENT_NBR = l_sh_xid
                and xxotm_container_inventory_t.location = v_location;
            exception
               when others then
                  l_customer_nbr := null;
            end;
         end if;
         
         -- Clean shipment XID and add to results
         l_sh_xid := replace(
            l_sh_xid,
            'NAQLEEN.',
            ''
         );
         l_verified_shipments.extend;
         l_verified_shipments(l_verified_shipments.count).shipment_nbr := l_sh_xid;
         l_verified_shipments(l_verified_shipments.count).shipment_name := l_sh_name;
         l_verified_shipments(l_verified_shipments.count).container_nbr := l_ct_nbr;
         l_verified_shipments(l_verified_shipments.count).customer_nbr := l_customer_nbr;
         l_verified_shipments(l_verified_shipments.count).truck_nbr := l_tr_nbr;
         l_verified_shipments(l_verified_shipments.count).driver_name := l_dr_name;
         l_verified_shipments(l_verified_shipments.count).update_date := l_update_date_str;
      end loop;
   end if;
   
   -- 4. Sort by update_date (desc) if needed
   if l_verified_shipments.count > 1 then
      for i in 1..l_verified_shipments.count - 1 loop
         for j in i + 1..l_verified_shipments.count loop
            if nvl(
               l_verified_shipments(i).update_date,
               ''
            ) < nvl(
               l_verified_shipments(j).update_date,
               ''
            ) then
               l_temp_rec := l_verified_shipments(i);
               l_verified_shipments(i) := l_verified_shipments(j);
               l_verified_shipments(j) := l_temp_rec;
            end if;
         end loop;
      end loop;
   end if;
   
   -- 5. Build JSON Response
   << build_response >> apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_verified_shipments.count > 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_array('data');
      for i in 1..l_verified_shipments.count loop
         apex_json.open_object;
         apex_json.write(
            'shipment_nbr',
            l_verified_shipments(i).shipment_nbr
         );
         apex_json.write(
            'shipment_name',
            l_verified_shipments(i).shipment_name
         );
         apex_json.write(
            'container_nbr',
            l_verified_shipments(i).container_nbr
         );
         apex_json.write(
            'customer_nbr',
            l_verified_shipments(i).customer_nbr
         );
         apex_json.write(
            'truck_nbr',
            l_verified_shipments(i).truck_nbr
         );
         apex_json.write(
            'driver_name',
            l_verified_shipments(i).driver_name
         );
         apex_json.close_object;
      end loop;
      apex_json.close_array;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No active stuffing shipments found'
      );
      apex_json.open_array('data');
      apex_json.close_array;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_stuffing_shipments;

   -- ========================================================================
   -- XX_OTM_GET_STUFFING_SHIPMENT_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_STUFFING_SHIPMENT_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_stuffing_shipment_details (
   p_shipment_no in varchar2,
   p_cust_nbr    in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 05-Jan-2026
   -- Updated By   : Madhan
   -- Description  : Added p_cust_nbr parameter to fetch local data for a specific customer
   -- Refactored   : 27-Jan-2026 - Fixed ORA-06502 with CLOB chunked output & character semantics
   
   -- Use explicit CHAR semantics to avoid multibyte byte-length issues
   l_api_base_url         varchar2(1000 char) := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/';
   l_cust_nbr             varchar2(100)  ;
   l_cust_name             varchar2(100)  ;
   l_url                  varchar2(32767 char);
   l_response_clob        clob;
   l_credential_static_id varchar2(200 char) := 'OTM_API_AUTH';
   l_item_count           number;
   l_is_verified          boolean := false;
   l_container_no         varchar2(4000 char);
   l_shipment_nbr         varchar2(4000 char);
   l_error_msg            varchar2(4000 char);
   l_found_header         boolean := false;
   l_header_container     varchar2(4000 char);
   l_header_cust_name     varchar2(4000 char);
   l_header_cust_nbr      varchar2(4000 char);

   -- For chunked output
   l_clob_out             clob;
   l_offset               number := 1;
   l_chunk                varchar2(32767 char);
   l_amount               number := 32000;
   l_step                 varchar2(200 char) := 'START';
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Initialize apex_json
   apex_json.initialize_clob_output;

   -- 1. LIVE VERIFICATION
   begin
      l_step := 'FETCH_OTM';
      if p_shipment_no is null then
         raise_application_error(
            -20002,
            'Shipment number is required'
         );
      end if;
      l_url := l_api_base_url
               || '?q=perspective eq "B" and attribute1 eq "TERMINAL" and shipmentName IN ["STUFFING","CROSS_STUFFING"]'
               || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"'
               || ' and shipmentXid eq "'
               || p_shipment_no
               || '"';

      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      l_response_clob := apex_web_service.make_rest_request(
         p_url                  => l_url,
         p_http_method          => 'GET',
         p_credential_static_id => l_credential_static_id,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );

      if l_response_clob is not null then
         l_step := 'PARSE_OTM';
         apex_json.parse(l_response_clob);
         l_item_count := nvl(
            apex_json.get_count('items'),
            0
         );
         if l_item_count > 0 then
            l_is_verified := true;
            l_shipment_nbr := apex_json.get_varchar2('items[1].shipmentXid');
            l_container_no := apex_json.get_varchar2('items[1].attribute3');
            l_cust_name := apex_json.get_varchar2('items[1].linerName');
            l_cust_nbr :=nvl(p_cust_nbr, replace(apex_json.get_varchar2('items[1].attribute2'),'NAQLEEN.',''));
         end if;
      end if;
   exception
      when others then
         -- Silently handle verification errors; will return 403
         dbms_output.put_line('OTM Verification Error: ' || sqlerrm);
   end;

   -- 2. GENERATE JSON RESPONSE
   l_step := 'BUILD_JSON';
   apex_json.open_object;
   if l_is_verified then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_object('data');
      for r in (
         select container_nbr,
                cust_name,
                cust_nbr,
                item_code,
                item_description,
                qty,
                qty_uom
           from xxotm_customer_inventory_t
          where cust_nbr = l_cust_nbr and shipment_nbr = p_shipment_no  and xxotm_customer_inventory_t.location = v_location
          order by item_code
      ) loop
         if not l_found_header then
            l_found_header := true;
            l_header_container := r.container_nbr;
            l_header_cust_name := nvl(l_cust_name,r.cust_name);
            l_header_cust_nbr := nvl(l_cust_nbr,r.cust_nbr);
            apex_json.write(
               'container_number',
               nvl(
                  l_container_no,
                  l_header_container
               )
            );
            apex_json.write(
               'customer_name',
               l_header_cust_name
            );
            apex_json.write(
               'customer_nbr',
               l_header_cust_nbr
            );
            apex_json.write(
               'shipment_nbr',
               p_shipment_no
            );
            apex_json.open_array('items');
         end if;

         apex_json.open_object;
         apex_json.write(
            'item_code',
            r.item_code
         );
         apex_json.write(
            'description',
            r.item_description
         );
         apex_json.write(
            'actual_quantity',
            r.qty
         );
         apex_json.write(
            'quantity_uom',
            r.qty_uom
         );
         apex_json.close_object;
      end loop;

      if l_found_header then
         apex_json.close_array;
      else
         apex_json.write(
            'container_number',
            l_container_no
         );
         apex_json.write(
            'shipment_nbr',
            p_shipment_no
         );
         apex_json.open_array('items');
         apex_json.close_array;
      end if;

      apex_json.close_object; -- data
   else
      apex_json.write(
         'response_code',
         403
      );
      apex_json.write(
         'response_message',
         'Verification Failed: Shipment is not in TRIP_STARTED status for Stuffing in OTM'
      );
   end if;

   apex_json.close_object;

   -- 3. CHUNKED OUTPUT (Avoids 32k htp limit and 06502 on prn)
   l_step := 'OUTPUT';
   l_clob_out := apex_json.get_clob_output;
   l_offset := 1;
   while l_offset <= dbms_lob.getlength(l_clob_out) loop
      l_chunk := dbms_lob.substr(
         l_clob_out,
         l_amount,
         l_offset
      );
      htp.prn(l_chunk);
      l_offset := l_offset + l_amount;
   end loop;

   apex_json.free_output;
exception
   when others then
      l_error_msg := substr(
         'Step: '
         || l_step
         || ' | '
         || sqlerrm
         || ' '
         || dbms_utility.format_error_backtrace,
         1,
         4000
      );

      begin
         apex_json.free_output;
      exception
         when others then
            null;
      end;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || l_error_msg
      );
      apex_json.close_object;

      -- Print error in one go (hopefully short enough)
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_stuffing_shipment_details;

   -- ========================================================================
   -- XX_OTM_GET_TASK_ASSIGNMENT_SHIPMENTS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_TASK_ASSIGNMENT_SHIPMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_task_assignment_shipments (
   p_search_text in varchar2 default null,
   p_page_num    in number default 0,
   p_user_id     in varchar2 default null
)
as
   -- Declared bare and assigned after the PROCEDURE's own BEGIN. The automated
   -- graft skipped this file because the first "^BEGIN$" belongs to the nested
   -- log_debug procedure.
   v_location varchar2(100);
    -- Last Updated Date : 16-Feb-2026 (v9)
    -- Description : 1. UNCONDITIONALLY set APEX Workspace Context for 'XXOTM'
    --               2. Use Web Credential 'OTM_API_AUTH'
    --               3. Separate API Calls for non-LCL and LCL shipments
    --               4. URL Encoding applied to 'q' parameter to prevent 403/400 errors
    --               5. Merge results into a single JSON response
    --               6. Added &expand=refnums to fetch Booking Number
    --               7. EXTRACTED: Container (Attr3), Booking (Refnum), Truck (Attr7), Driver (Attr8)
    --               8. LCL filter: Only include if GATE IN exists, no TASK_ASSIGNED, no GATE OUT
    --               9. LCL filter reads events from API response payload (trackingEvents)

   l_url                  clob;
   l_q_param              varchar2(32000);
   l_response_clob        clob;
   l_items_count          number;
   l_shipment_xid         varchar2(100);
   l_shipment_name        varchar2(100);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   -- Local Task Status variables
   l_task_status          varchar2(100);
   l_shipment_status      varchar2(100);
   l_limit                number := 500;
   
   -- Truck/Driver/Container/Booking Variables
   l_power_unit           varchar2(100);
   l_truck_nbr            varchar2(100);
   l_driver_name          varchar2(200);
   l_container_nbr        varchar2(100);
   l_booking_nbr          varchar2(100);
   
   -- Refnum parsing
   l_refnum_count         number;
   l_ref_qual             varchar2(200);
   l_ref_value            varchar2(200);
   l_offset               number;

   -- Workspace Context
   l_workspace_id         number;
   l_workspace_name       varchar2(100) := 'XXOTM'; 

   -- LCL event filtering
   l_has_gate_in          number;
   l_has_task_assigned    number;
   l_has_gate_out         number;

   -- Debug Logging Collection
   type t_debug_logs is
      table of varchar2(4000) index by pls_integer;
   l_debug_logs           t_debug_logs;
   l_debug_idx            number := 0;

   -- Helper to log to both DBMS_OUTPUT and Collection
   procedure log_debug (
      p_msg in varchar2
   ) is
   begin
      dbms_output.put_line(p_msg);
      l_debug_idx := l_debug_idx + 1;
      l_debug_logs(l_debug_idx) := p_msg;
   end;

   -- Internal procedure to process results from a single API call
   -- p_is_lcl: TRUE for LCL shipments (apply GATE IN / no TASK_ASSIGNED / no GATE OUT filter)
   procedure process_otm_response (
      p_response clob,
      p_is_lcl   boolean default false
   ) is
      l_count number;
   begin
      begin
         apex_json.parse(p_response);
         l_count := nvl(
            apex_json.get_count(p_path => 'items'),
            0
         );
      exception
         when others then
            -- log_debug('ERROR: JSON Parsing failed: ' || sqlerrm);
            l_count := 0;
      end;

    --   log_debug('DEBUG: Items count = '
    --             || l_count
    --             || ', is_lcl = '
    --             || case
    --      when p_is_lcl then
    --         'TRUE'
    --      else 'FALSE'
    --   end);

      if l_count > 0 then
         for i in 1..l_count loop
            l_shipment_xid := apex_json.get_varchar2(
               p_path => 'items[%d].shipmentXid',
               p0     => i
            );
            l_shipment_name := apex_json.get_varchar2(
               p_path => 'items[%d].shipmentName',
               p0     => i
            );
            
            -- Reset Details
            l_truck_nbr := null;
            l_driver_name := null;
            l_power_unit := null;
            l_container_nbr := null;
            l_booking_nbr := null;

            -- Check if shipment exists in task assignment table
            begin
               select status
                 into l_task_status
                 from xxotm_task_assignment_t
                where shipment_nbr = l_shipment_xid
                  and rownum = 1
                  and xxotm_task_assignment_t.location = v_location;

               -- If exists in task assignment, skip
            --    log_debug('DEBUG: Shipment '
            --              || l_shipment_xid
            --              || ' already in task_assignment (status='
            --              || l_task_status
            --              || '), SKIPPING');
               null;
            exception
               when no_data_found then
                  l_shipment_status := 'new';

                  -- =====  =======================================================
                  -- LCL FILTER: Check statuses from API response payload.
                  -- Only include if GATE IN exists, no TASK_ASSIGNED, no GATE OUT
                  -- ============================================================
                  if p_is_lcl then
                     declare
                        l_status_count number;
                        l_status_type  varchar2(200);
                        l_status_value varchar2(200);
                     begin
                        l_has_gate_in := 0;
                        l_has_task_assigned := 0;
                        l_has_gate_out := 0;
                        l_status_count := nvl(
                           apex_json.get_count(
                              p_path => 'items[%d].trackingEvents.items',
                              p0     => i
                           ),
                           0
                        );

                        -- log_debug('DEBUG LCL: Shipment '
                        --           || l_shipment_xid
                        --           || ' ('
                        --           || l_shipment_name
                        --           || ') - trackingEvents count = '
                        --           || l_status_count);

                        for s in 1..l_status_count loop
                           l_status_value := apex_json.get_varchar2(
                              'items[%d].trackingEvents.items[%d].statusCodeGid',
                              i,
                              s
                           );
                        --    log_debug('DEBUG LCL:   status['
                        --              || s
                        --              || '] = '
                        --              || nvl(
                        --       l_status_value,
                        --       'NULL'
                        --    ));

                           if l_status_value = 'NAQLEEN.GATE IN' then
                              l_has_gate_in := 1;
                           elsif l_status_value = 'NAQLEEN.TASK_ASSIGNED' then
                              l_has_task_assigned := 1;
                           elsif l_status_value = 'NAQLEEN.GATE OUT' then
                              l_has_gate_out := 1;
                           end if;
                        end loop;

                        -- log_debug('DEBUG LCL: Shipment '
                        --           || l_shipment_xid
                        --           || ' => GATE_IN='
                        --           || l_has_gate_in
                        --           || ', TASK_ASSIGNED='
                        --           || l_has_task_assigned
                        --           || ', GATE_OUT='
                        --           || l_has_gate_out);
                     end;

                     -- Skip if: no GATE IN, or has TASK_ASSIGNED, or has GATE OUT
                     if l_has_gate_in = 0
                     or l_has_task_assigned > 0
                     or l_has_gate_out > 0 then
                        -- log_debug('DEBUG LCL: Shipment '
                        --           || l_shipment_xid
                        --           || ' SKIPPED (filter failed)');
                        goto next_shipment;
                     end if;

                    --  log_debug('DEBUG LCL: Shipment '
                    --            || l_shipment_xid
                    --            || ' PASSED filter, including in response');
                  end if;

                  -- 1. Get Container Number (Attribute3)
                  l_container_nbr := apex_json.get_varchar2(
                     p_path => 'items[%d].attribute3',
                     p0     => i
                  );

                  -- 2. Get Truck/Driver (Attribute 7/8)
                  l_truck_nbr := apex_json.get_varchar2(
                     p_path => 'items[%d].attribute7',
                     p0     => i
                  );
                  l_driver_name := apex_json.get_varchar2(
                     p_path => 'items[%d].attribute8',
                     p0     => i
                  );
                  if l_truck_nbr is null then
                     l_power_unit := apex_json.get_varchar2(
                        p_path => 'items[%d].powerUnitGid',
                        p0     => i
                     );
                     if l_power_unit is not null then
                        l_truck_nbr := replace(
                           l_power_unit,
                           'NAQLEEN.',
                           ''
                        );
                     end if;
                  end if;

                  -- 3. Get Booking Number (Refnum: NAQLEEN.BOOKING_NO)
                  l_refnum_count := nvl(
                     apex_json.get_count(
                        p_path => 'items[%d].refnums.items',
                        p0     => i
                     ),
                     0
                  );
                  if l_refnum_count > 0 then
                     for r in 1..l_refnum_count loop
                        l_ref_qual := apex_json.get_varchar2(
                           'items[%d].refnums.items[%d].shipmentRefnumQualGid',
                           i,
                           r
                        );
                        if l_ref_qual = 'NAQLEEN.BOOKING_NO' then
                           l_booking_nbr := apex_json.get_varchar2(
                              'items[%d].refnums.items[%d].shipmentRefnumValue',
                              i,
                              r
                           );
                           exit; -- Found booking number
                        end if;
                     end loop;
                  end if;

                  apex_json.open_object;
                  apex_json.write(
                     'shipment_xid',
                     l_shipment_xid
                  );
                  apex_json.write(
                     'shipment_name',
                     l_shipment_name
                  );
                  apex_json.write(
                     'shipment_status',
                     l_shipment_status
                  );
                  apex_json.write(
                     'container_nbr',
                     l_container_nbr
                  );
                  apex_json.write(
                     'booking_nbr',
                     l_booking_nbr
                  );
                  apex_json.write(
                     'truck_nbr',
                     l_truck_nbr
                  );
                  apex_json.write(
                     'driver_name',
                     l_driver_name
                  );
                  apex_json.close_object;
            end;

            << next_shipment >> null;
         end loop;
      end if;
   end;

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   apex_json.initialize_clob_output;
   
   -- 0. FORCE SET WORKSPACE CONTEXT
   begin
      l_workspace_id := apex_util.find_security_group_id(p_workspace => l_workspace_name);
      if l_workspace_id is not null then
         apex_util.set_security_group_id(l_workspace_id);
      end if;
   exception
      when others then
         log_debug('WARNING: Failed to set workspace context: ' || sqlerrm);
   end;

   -- Calculate Offset
   l_offset := ( greatest(
      nvl(
         p_page_num,
         1
      ),
      1
   ) - 1 ) * l_limit;

   -- Prepare JSON Response Header
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');

   -- ------------------------------------------------------------
   -- CALL 1: NON-LCL SHIPMENTS (NOT_STARTED)
   -- ------------------------------------------------------------
   l_q_param := 'attribute1 eq "TERMINAL" and perspective eq "B" and shipmentName in ["STUFFING","DESTUFFING","CROSS_STUFFING"] and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED"'
                  || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
                  || ' and refnums.shipmentRefnumValue eq ' || v_location
   ;
   if trim(p_search_text) is not null then
      l_q_param := l_q_param
                   || ' and shipmentXid co "'
                   || upper(trim(p_search_text))
                   || '"';
   end if;

   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/?q='
            || apex_util.url_encode(l_q_param)
            || '&limit=500&orderBy=updateDate:desc'
            || '&expand=refnums'
            || '&offset='
            || l_offset;

--    log_debug('DEBUG: CALL 1 (NON-LCL) URL = ' || l_url);
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   l_response_clob := apex_web_service.make_rest_request(
      p_url                  => l_url,
      p_http_method          => 'GET',
      p_credential_static_id => l_credential_static_id,
      p_wallet_path => xxotm_get_cfg('WALLET_PATH')
   );
   process_otm_response(
      p_response => l_response_clob,
      p_is_lcl   => false
   );

   -- ------------------------------------------------------------
   -- CALL 2: LCL SHIPMENTS (NOT COMPLETED/CANCELLED)
   -- Filter: Must have GATE IN, no TASK_ASSIGNED, no GATE OUT
   -- ------------------------------------------------------------
   l_q_param := 'attribute1 eq "TERMINAL" and perspective eq "B" and shipmentName in ["LOADING_LCL","OFFLOADING_LCL"] and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS" and statuses.statusValueGid ne "NAQLEEN.TRIP_COMPLETED" and statuses.statusValueGid ne "NAQLEEN.TRIP_CANCELLED"'
                  || ' and refnums.shipmentRefnumQualGid eq NAQLEEN.LOCATION'
                  || ' and refnums.shipmentRefnumValue eq ' || v_location
   ;
   if trim(p_search_text) is not null then
      l_q_param := l_q_param
                   || ' and shipmentXid co "'
                   || upper(trim(p_search_text))
                   || '"';
   end if;

   l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/?q='
            || apex_util.url_encode(l_q_param)
            || '&limit=500&orderBy=updateDate:desc'
            || '&expand=refnums,trackingEvents'
            || '&offset='
            || l_offset;

--    log_debug('DEBUG: CALL 2 (LCL) URL = ' || l_url);
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   l_response_clob := apex_web_service.make_rest_request(
      p_url                  => l_url,
      p_http_method          => 'GET',
      p_credential_static_id => l_credential_static_id,
      p_wallet_path => xxotm_get_cfg('WALLET_PATH')
   );
   process_otm_response(
      p_response => l_response_clob,
      p_is_lcl   => true
   );
   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      log_debug('DEBUG: Critical Error: ' || sqlerrm);
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_task_assignment_shipments;

   -- ========================================================================
   -- XX_OTM_GET_TASK_ASSIGNMENT_SHIPMENT_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_TASK_ASSIGNMENT_SHIPMENT_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_task_assignment_shipment_details (
   p_shipment_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Created Date : 02-Jan-2026
   -- Description  : Get shipment details. If not found locally, call deletion helper.
   -- Updated      : Add OTM API call for BOL and fetch container type
   -- Updated      : Add Truck/Driver details from Attr7/8 + PowerUnit Fallback

   l_shipment_xid   varchar2(100);
   l_shipment_name  varchar2(200);
   l_cont_no        varchar2(100);
   l_operator       varchar2(100);
   l_status         varchar2(50);
   l_date           varchar2(100);
   l_found          boolean := false;
   l_customer_name  varchar2(200);
   l_customer_nbr   varchar2(100);
   l_order_nbr      varchar2(100);
   l_booking_nbr    varchar2(100);
   l_container_type varchar2(100);
   l_bol_number     varchar2(100);
   
   -- Truck/Driver
   l_truck_nbr      varchar2(100);
   l_driver_name    varchar2(200);
   l_power_unit     varchar2(100);
   
   -- API Call variables
   l_url            varchar2(1000);
   l_resp_clob      clob;
   l_json_resp      json_object_t;
   l_refnums_sect   json_object_t;
   l_refnums_arr    json_array_t;
   l_refnum_item    json_object_t;
   l_qual           varchar2(200);
   l_load_status           varchar2(200);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   dbms_output.put_line('--- DETAILS DEBUG START ---');
   dbms_output.put_line('Request Shipment: ' || p_shipment_nbr);
   apex_json.initialize_clob_output;
   apex_json.open_object;
    
    -- 1. Try to get shipment details from local staging tables
   begin
      select s.shipment_xid,
             s.shipment_name,
             s.cont_no,
             c.cust_name,
             c.cust_nbr,
             c.inbound_order_nbr,
             c.booking_id,
             c.container_type,
             c.load_status
        into
         l_shipment_xid,
         l_shipment_name,
         l_cont_no,
         l_customer_name,
         l_customer_nbr,
         l_order_nbr,
         l_booking_nbr,
         l_container_type,
         l_load_status
        from xxotm_shipments_t s,
             xxotm_container_inventory_t c
       where s.shipment_xid = p_shipment_nbr
         and s.shipment_xid = c.inbound_shipment_nbr
         and c.location = v_location
         and rownum = 1;

      l_found := true;
      dbms_output.put_line('Shipment found locally: ' || l_shipment_xid);
   exception
      when no_data_found then
         l_found := false;
         dbms_output.put_line('Shipment NOT found locally. Calling lazy deletion helper...');
--         xx_otm_delete_shipment_from_staging(p_shipment_nbr);
   end;

   if l_found then
        -- 2. Get operator and status from task assignment table
      begin
         select operator,
                status,
                assigned_date
           into
            l_operator,
            l_status,
            l_date
           from xxotm_task_assignment_t
          where shipment_nbr = p_shipment_nbr
            and rownum = 1
            and xxotm_task_assignment_t.location = v_location;

         dbms_output.put_line('Assignment Found: Operator='
                              || l_operator
                              || ', Status='
                              || l_status);
      exception
         when no_data_found then
            l_operator := null;
            l_status := null;
            l_date := null;
            dbms_output.put_line('No assignment record found in xxotm_task_assignment_t');
      end;

      -- 3. Call OTM API to get BOL Number using refnums, and Truck/Driver using Attributes
      begin
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                  || p_shipment_nbr
                  || '?expand=refnums';
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_resp_clob := apex_web_service.make_rest_request(
            p_url                  => l_url,
            p_http_method          => 'GET',
            p_credential_static_id => 'OTM_API_AUTH',
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         if l_resp_clob is not null then
            l_json_resp := json_object_t.parse(l_resp_clob);
            
            -- Extract Truck/Driver Details (Attr7/8)
            if l_json_resp.has('attribute7') then
               l_truck_nbr := l_json_resp.get_string('attribute7');
            end if;
            if l_json_resp.has('attribute8') then
               l_driver_name := l_json_resp.get_string('attribute8');
            end if;

            -- Fallback for Truck
            if
               l_truck_nbr is null
               and l_json_resp.has('powerUnitGid')
            then
               l_power_unit := l_json_resp.get_string('powerUnitGid');
               if l_power_unit is not null then
                  l_truck_nbr := replace(
                     l_power_unit,
                     'NAQLEEN.',
                     ''
                  );
               end if;
            end if;

            -- Extract BOL
            if l_json_resp.has('refnums') then
               l_refnums_sect := l_json_resp.get_object('refnums');
               if l_refnums_sect.has('items') then
                  l_refnums_arr := l_refnums_sect.get_array('items');
                  for i in 0..l_refnums_arr.get_size() - 1 loop
                     l_refnum_item := treat(l_refnums_arr.get(i) as json_object_t);
                     if l_refnum_item.has('shipmentRefnumQualGid') then
                        l_qual := l_refnum_item.get_string('shipmentRefnumQualGid');
                        if l_qual = 'NAQLEEN.BOL_NUMBER' then
                           l_bol_number := l_refnum_item.get_string('shipmentRefnumValue');
                           exit;
                        end if;
                     end if;
                  end loop;
               end if;
            end if;
         end if;
      exception
         when others then
            dbms_output.put_line('Error calling OTM API for BOL/Truck: ' || sqlerrm);
            l_bol_number := null;
      end;

      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');
      apex_json.write(
         'shipment_nbr',
         l_shipment_xid
      );
      apex_json.write(
         'shipment_name',
         l_shipment_name
      );
      apex_json.write(
         'cont_no',
         l_cont_no
      );
      apex_json.write(
         'customer_name',
         l_customer_name
      );
      apex_json.write(
         'customer_nbr',
         l_customer_nbr
      );
      apex_json.write(
         'order_nbr',
         l_order_nbr
      );
      apex_json.write(
         'booking_nbr',
         l_booking_nbr
      );
      apex_json.write(
         'operator',
         l_operator
      );
      apex_json.write(
         'status',
         l_status
      );
      apex_json.write(
         'assigned_date',
         l_date
      );
      apex_json.write(
         'container_type',
         l_container_type
      );
      apex_json.write(
         'bol_number',
         l_bol_number
      );
      apex_json.write(
         'truck_nbr',
         l_truck_nbr
      );
      apex_json.write(
         'driver_name',
         l_driver_name
      );
      apex_json.write(
         'load_status',
         nvl(l_load_status,'UNLOADED')
      );
      apex_json.close_object;
   else
      dbms_output.put_line('Returning 404 response.');
      apex_json.write(
         'response_message',
         'Shipment Not Found'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.open_object('data');
      apex_json.close_object;
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
   dbms_output.put_line('--- DETAILS DEBUG END ---');
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_object('data');
      apex_json.close_object;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      dbms_output.put_line('CRITICAL ERROR in details procedure: ' || sqlerrm);
end xx_otm_get_task_assignment_shipment_details;

   -- ========================================================================
   -- XX_OTM_GET_TRACKING_CONTAINERS   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_GET_TRACKING_CONTAINERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_tracking_containers (
   p_search_text in varchar2,
   p_user_id     in varchar2 default null
)
as
   -- Declared bare and first: the cursor below references it, and PL/SQL
   -- requires a declaration to precede its use.
   v_location         varchar2(100);
   l_event_data_array json_array_t;
   l_response         json_object_t;
   cursor c_data_cursor is
   select distinct container_nbr
     from xxotm_container_inventory_t
    where container_stored_time is not null and upper(container_nbr) like '%'
                                    || upper(p_search_text)
                                    || '%'
      and xxotm_container_inventory_t.location = v_location
    order by container_nbr
    fetch first 10 rows only;
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- Initialize Array
   l_event_data_array := json_array_t();
   
   -- Loop through cursor
   for r in c_data_cursor loop
      -- Append container number string directly to array
      l_event_data_array.append(r.container_nbr);
   end loop;
   -- Construct Response
   l_response := json_object_t();
   l_response.put(
      'response_code',
      200
   );
   l_response.put(
      'response_message',
      'Success'
   );
   l_response.put(
      'data',
      l_event_data_array
   );
   
   -- Output
   apex_json.initialize_clob_output;
   htp.prn(l_response.to_clob);
exception
   when others then
      l_response := json_object_t();
      l_response.put(
         'response_code',
         400
      );
      l_response.put(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.initialize_clob_output;
      htp.prn(l_response.to_clob);
end xx_otm_get_tracking_containers;

   -- ========================================================================
   -- XX_OTM_GET_TRACK_CONTAINER_DETAILS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_TRACK_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_track_container_details (
   p_container_nbr in varchar2
)
as
    -- Last Updated Date : 20-Jan-2026
    -- Last Updated By : AI Agent
    -- Description : 1. Replaced API call with DB tables fetch (XXOTM_TRACKING_EVENTS_T)
    --               2. Logic added to fetch Outbound Shipment based on 'CONTAINER RELEASED'/'GATE OUT'
    --               3. Override Outbound Order Number with Inbound Order Number if valid outbound shipment found.
    
   -- Container Inventory Variables
   l_cust_nbr              varchar2(100);
   l_cust_name             varchar2(200);
   l_container_type             varchar2(200);
   l_inbound_order_nbr     varchar2(100);
   l_inbound_shipment_nbr  varchar2(100);
   l_outbound_order_nbr    varchar2(100);
   l_outbound_shipment_nbr varchar2(100);
   l_position              varchar2(100);
   l_inbound_gate_out_date varchar2(100);
   l_outbound_shipment_id  varchar2(100);
   l_latest_inbound_event_type varchar2(100);
   l_latest_inbound_event_date varchar2(100);
   l_container_released_time varchar2(100);
   l_shipment_name           varchar2(100);   
   l_outbound_shipment_name  varchar2(100);   
 
begin
   apex_json.initialize_clob_output;

   begin
      select shipment_xid,event_type,event_date,inbound_order_nbr,outbound_order_nbr,outbound_shipment_nbr,container_released_time,position,cust_name,container_type,shipment_name
        into l_inbound_shipment_nbr,l_latest_inbound_event_type,l_latest_inbound_event_date,
             l_inbound_order_nbr,l_outbound_order_nbr,l_outbound_shipment_nbr,l_container_released_time,l_position,l_cust_name,l_container_type,l_shipment_name
        from (
         select s.shipment_xid,te.event_type,te.event_date,ci.inbound_order_nbr,ci.outbound_order_nbr,ci.outbound_shipment_nbr,ci.container_released_time,ci.position,ci.cust_name,ci.container_type,s.shipment_name
           from xxotm_shipments_t s,
            xxotm_tracking_events_t te,xxotm_container_inventory_t ci
         where s.shipment_xid = te.shipment_nbr and ci.inbound_shipment_nbr = s.shipment_xid
          and s.cont_no = p_container_nbr
            and s.shipment_name in ( 'INBOUND_CONTAINER',
                                     'CFS',
                                     'DESTUFFING',
                                     'STUFFING',
                                     'STORE_AS_IT_IS' )
            and te.event_type in ('CONTAINER STORED','INSPECTED','GATE IN','TASK ASSIGNED','STUFFED','DESTUFFED')
          order by te.event_date desc
      )
       where rownum = 1;
   exception
      when no_data_found then
         l_inbound_shipment_nbr := null;
   end;
   
   -- 4. Get Outbound Shipment (Another shipment with RELEASED or GATE OUT event AFTER Inbound Gate Out)
   if
      l_outbound_shipment_nbr is null
      and l_inbound_shipment_nbr is not null
      and l_latest_inbound_event_date is not null
   then
      begin
         select shipment_nbr
           into l_outbound_shipment_id
           from (
            select te.shipment_nbr
              from xxotm_tracking_events_t te
             where te.container_nbr = p_container_nbr
               and te.event_type in ( 'CONTAINER RELEASED' )
               and te.event_date > l_latest_inbound_event_date
               and te.shipment_nbr != l_inbound_shipment_nbr -- Ensure it's 'another' shipment
             order by te.event_date asc -- Get the one occurring 'right after'
         )
          where rownum = 1;
          
      exception
         when no_data_found then
            l_outbound_shipment_id := null;
      end;
      
      -- 5. Override Variables if Outbound Shipment Found
      if l_outbound_shipment_id is not null then
         l_outbound_shipment_nbr := l_outbound_shipment_id;
         
         -- Take the shipment and search in contianer inventory table for the order nbr 
         -- (found as inbound order nbr) and send as outbound order nbr
         begin
            select inbound_order_nbr,shipment_name
              into l_outbound_order_nbr,l_outbound_shipment_name
              from xxotm_container_inventory_t
             where inbound_shipment_nbr = l_outbound_shipment_id
               and rownum = 1;
         exception
            when no_data_found then
               l_outbound_order_nbr := null;
         end;
      end if;
   end if;

    if l_container_released_time is not null then
        l_position := null;
    end if;

   -- 6. Write JSON Response
   apex_json.open_object; -- Root Object
   
   -- Write Container Inventory Data
   apex_json.write(
      'container_nbr',
      p_container_nbr
   );
    apex_json.write(
      'container_type',
      l_container_type
   );
   apex_json.write(
      'customer',
      l_cust_name
   );
   apex_json.write(
      'inbound_order_nbr',
      l_inbound_order_nbr
   );
   apex_json.write(
      'inbound_shipment_nbr',
      l_inbound_shipment_nbr
   );
   apex_json.write(
      'outbound_order_nbr',
      l_outbound_order_nbr
   );
   apex_json.write(
      'outbound_shipment_nbr',
      l_outbound_shipment_nbr
   );
   apex_json.write(
      'position',
      l_position
   );
   apex_json.write(
      'inbound_shipment_name',
      l_shipment_name
   );
   apex_json.write(
      'outbound_shipment_name',
      l_outbound_shipment_name
   );
    -- Write available container types
   apex_json.open_array('available_container_types');
   for ct in (
      select distinct container_type 
        from xxotm_container_inventory_t 
       where container_type is not null
       order by container_type
   ) loop
      apex_json.write(ct.container_type);
   end loop;
   apex_json.close_array;

   apex_json.open_array('tracking_events'); -- Nested Array

   if l_inbound_shipment_nbr is not null then
       
       -- Process Inbound Events: Print all until 'CONTAINER STORED'
      for r in (
         select event_type,
                event_date
           from xxotm_tracking_events_t
          where shipment_nbr = l_inbound_shipment_nbr
            and event_type in ( 'INSPECTED',
                                'CONTAINER STORED',
                                'GATE IN',
                                'CONTAINER RELEASED',
                                'GATE OUT' )
          order by event_date asc
      ) loop
         apex_json.open_object;
         apex_json.write(
            'status_code',
            r.event_type
         );
         
         -- Map Status Code to Event Name
         case r.event_type
            when 'INSPECTED' then
               apex_json.write(
                  'event_name',
                  'Container Inspected'
               );
            when 'CONTAINER STORED' then
               apex_json.write(
                  'event_name',
                  'Container Stored'
               );
            when 'GATE IN' then
               apex_json.write(
                  'event_name',
                  'Gate In'
               );
            when 'CONTAINER RELEASED' then
               apex_json.write(
                  'event_name',
                  'Container Released'
               );
            when 'GATE OUT' then
               apex_json.write(
                  'event_name',
                  'Gate Out'
               );
            else
               apex_json.write(
                  'event_name',
                  initcap(r.event_type)
               );
         end case;

         apex_json.write(
            'event_date',
            r.event_date
         );
         apex_json.close_object;
         if r.event_type = 'CONTAINER STORED' then
            exit;
         end if;
      end loop;
   end if; -- End Inbound
   
   -- Process Outbound Events if we found a valid outbound shipment
   if l_outbound_shipment_nbr is not null then
         -- Process Outbound Events: Only CONTAINER RELEASED and GATE OUT are requested usually, 
         -- but loop filters common ones just in case.
      for r in (
         select event_type,
                event_date
           from xxotm_tracking_events_t
          where shipment_nbr = l_outbound_shipment_nbr
            and event_type in ( 'CONTAINER RELEASED',
                                'GATE OUT' )
          order by event_date asc
      ) loop
         apex_json.open_object;
         apex_json.write(
            'status_code',
            r.event_type
         );
            
            -- Map Status Code to Event Name
         case r.event_type
            when 'INSPECTED' then
               apex_json.write(
                  'event_name',
                  'Inspected'
               );
            when 'CONTAINER STORED' then
               apex_json.write(
                  'event_name',
                  'Stored'
               );
            when 'GATE IN' then
               apex_json.write(
                  'event_name',
                  'Gate In'
               );
            when 'CONTAINER RELEASED' then
               apex_json.write(
                  'event_name',
                  'Container Released'
               );
            when 'GATE OUT' then
               apex_json.write(
                  'event_name',
                  'Gate Out'
               );
            else
               apex_json.write(
                  'event_name',
                  initcap(r.event_type)
               );
         end case;

         apex_json.write(
            'event_date',
            r.event_date
         );
         apex_json.close_object;
      end loop;
   end if;

   apex_json.close_array; -- tracking_events
   apex_json.close_object; -- Root Object
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'error',
         'Procedure Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_track_container_details;

   -- ========================================================================
   -- XX_OTM_GET_TRUCKS_AWAITING_FOR_GATE_OUT   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_GET_TRUCKS_AWAITING_FOR_GATE_OUT.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_trucks_awaiting_for_gate_out (
    p_user_id IN VARCHAR2 DEFAULT NULL
)
AS
    -- Created Date : 17-Jun-2026
    -- Description  : Returns gate-out eligible trucks in pages, chunked output.
    -- Declared bare, assigned after BEGIN.
    v_location   VARCHAR2(100);
    l_data_clob  CLOB;
    l_final_clob CLOB;
    l_total      NUMBER;
BEGIN
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;

    DBMS_LOB.createtemporary(l_final_clob, TRUE);

    SELECT COUNT(*) INTO l_total
      FROM xxotm_v_gate_out_eligible
     WHERE xxotm_v_gate_out_eligible.location = v_location;

    SELECT JSON_ARRAYAGG(
               JSON_OBJECT(
                   'truck_number'  VALUE truck_nbr,
                   'driver_name'   VALUE driver_name,
                   'driver_id'     VALUE driver_iqama,
                   'entry_time'    VALUE entry_time,
                   'shipment_nbr'  VALUE shipment_nbr,
                   'customer_name' VALUE customer_name,
                   'order_type'    VALUE order_type,
                   'ops_event'     VALUE ops_event,
                   'ops_time'      VALUE ops_time
                   RETURNING CLOB
               )
               RETURNING CLOB
           )
      INTO l_data_clob
      FROM (
               SELECT truck_nbr, driver_name, driver_iqama, entry_time,
                      shipment_nbr, customer_name, order_type, ops_event, ops_time
                 FROM xxotm_v_gate_out_eligible
                WHERE xxotm_v_gate_out_eligible.location = v_location
                ORDER BY entry_time DESC
           );

    IF l_data_clob IS NULL THEN
        l_data_clob := '[]';
    END IF;

    l_final_clob := '{"response_code": 200, "response_message": "Success",'
                 || '"total_count": '  || l_total
                 || ',"data": '        || l_data_clob
                 || '}';

    DECLARE
        l_offset NUMBER := 1;
        l_amount NUMBER := 32000;
        l_len    NUMBER;
        l_buffer VARCHAR2(32767);
    BEGIN
        l_len := DBMS_LOB.getlength(l_final_clob);
        WHILE l_offset <= l_len LOOP
            DBMS_LOB.read(l_final_clob, l_amount, l_offset, l_buffer);
            HTP.prn(l_buffer);
            l_offset := l_offset + l_amount;
        END LOOP;
    END;

    DBMS_LOB.freetemporary(l_final_clob);

EXCEPTION
    WHEN OTHERS THEN
        -- Was hand-built JSON with unquoted keys and an unescaped SQLERRM, so
        -- the client could not parse it and the operator saw a generic failure
        -- rather than the message. The REPLACE had an empty search string and
        -- did nothing. apex_json escapes properly. Prod's non-leaking wording is
        -- kept: procedure name and Oracle text go to the log, not the response.
        DBMS_OUTPUT.PUT_LINE('XX_OTM_GET_TRUCKS_AWAITING_FOR_GATE_OUT: ' || SQLERRM);
        APEX_JSON.initialize_clob_output;
        APEX_JSON.open_object;
        APEX_JSON.write('response_code', 500);
        APEX_JSON.write('response_message', 'Something went wrong. Please try again later.');
        APEX_JSON.close_object;
        HTP.prn(APEX_JSON.get_clob_output);
        APEX_JSON.free_output;
END XX_OTM_GET_TRUCKS_AWAITING_FOR_GATE_OUT;

   -- ========================================================================
   -- XX_OTM_GET_TRUCKS_IN_YARD   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_GET_TRUCKS_IN_YARD.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_trucks_in_yard (
    p_user_id IN VARCHAR2 DEFAULT NULL
)
AS
    -- Created Date : 17-Jun-2026
    -- Description  : Returns trucks in yard in pages, chunked output.
    -- Declared bare, assigned after BEGIN.
    v_location   VARCHAR2(100);
    l_data_clob  CLOB;
    l_final_clob CLOB;
    l_total      NUMBER;
BEGIN
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;

    DBMS_LOB.createtemporary(l_final_clob, TRUE);
    SELECT COUNT(*) INTO l_total
      FROM xxotm_v_trucks_in_yard
     WHERE xxotm_v_trucks_in_yard.location = v_location;

    SELECT JSON_ARRAYAGG(
               JSON_OBJECT(
                   'truck_number' VALUE truck_nbr,
                   'driver_name'  VALUE driver_name,
                   'driver_id'    VALUE driver_iqama,
                   'entry_time'   VALUE entry_time,
                   'status'       VALUE clean_status,
                   'shipment_nbr' VALUE shipment_nbr,
                   'order_type'   VALUE order_type
                   RETURNING CLOB
               )
               RETURNING CLOB
           )
      INTO l_data_clob
      FROM (
               SELECT truck_nbr, driver_name, driver_iqama, entry_time,
                      clean_status, shipment_nbr, order_type
                 FROM xxotm_v_trucks_in_yard
                WHERE xxotm_v_trucks_in_yard.location = v_location
                ORDER BY entry_time DESC
               
           );

    IF l_data_clob IS NULL THEN
        l_data_clob := '[]';
    END IF;

    l_final_clob := '{"response_code": 200, "response_message": "Success",'
                 || '"total_count": '  || l_total
                 || ',"data": '        || l_data_clob
                 || '}';

    DECLARE
        l_offset NUMBER := 1;
        l_amount NUMBER := 32000;
        l_len    NUMBER;
        l_buffer VARCHAR2(32767);
    BEGIN
        l_len := DBMS_LOB.getlength(l_final_clob);
        WHILE l_offset <= l_len LOOP
            DBMS_LOB.read(l_final_clob, l_amount, l_offset, l_buffer);
            HTP.prn(l_buffer);
            l_offset := l_offset + l_amount;
        END LOOP;
    END;

    DBMS_LOB.freetemporary(l_final_clob);

EXCEPTION
    WHEN OTHERS THEN
        -- Was hand-built JSON with unquoted keys and an unescaped SQLERRM, so
        -- the client could not parse it and the operator saw a generic failure
        -- rather than the message. The REPLACE had an empty search string and
        -- did nothing. apex_json escapes properly. Prod's non-leaking wording is
        -- kept: procedure name and Oracle text go to the log, not the response.
        DBMS_OUTPUT.PUT_LINE('XX_OTM_GET_TRUCKS_IN_YARD: ' || SQLERRM);
        APEX_JSON.initialize_clob_output;
        APEX_JSON.open_object;
        APEX_JSON.write('response_code', 500);
        APEX_JSON.write('response_message', 'Something went wrong. Please try again later.');
        APEX_JSON.close_object;
        HTP.prn(APEX_JSON.get_clob_output);
        APEX_JSON.free_output;
END XX_OTM_GET_TRUCKS_IN_YARD;

   -- ========================================================================
   -- XX_OTM_GET_TRUCK_INFO   [4-test-only / PORT]
   -- source: db/work/XX_OTM_GET_TRUCK_INFO.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_truck_info (
   p_truck_nbr in varchar2
)
as
   -- Created Date : 25-Feb-2026
   -- Description  : Fetches registered truck/vehicle details from Driver Vehicle Master.
   --                Validates if the truck is already inside the yard.
   
   l_truck_rec      xxotm_driver_vehicle_master_t%rowtype;
   l_truck_inside   varchar2(100);
   l_fallback_iqama varchar2(100);
begin
   apex_json.initialize_clob_output;
  
   -- 1. Check if Truck is Already Inside the Yard
   begin
      select truck_nbr
        into l_truck_inside
        from xxotm_vehicle_master_t
       where truck_nbr = p_truck_nbr 
         and exit_time is null
         and rownum = 1;
         
      -- If no exception is raised, the truck IS inside. Return error.
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write('response_message', 'Truck Already Inside - Cannot Re-enter');
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      return;
   exception
      when no_data_found then
         -- Truck is NOT inside the yard. Proceed to fetch master info.
         null;
   end;
   -- 2. Query the Master Table Directory
   begin
      select *
        into l_truck_rec
        from xxotm_driver_vehicle_master_t
       where VEHICLE_XID = p_truck_nbr
         and rownum = 1;
   exception
      when no_data_found then
         -- Truck not registered in the master
         apex_json.open_object;
         apex_json.write('response_code', 200);
         apex_json.write('response_message', 'Truck not found in master registry');
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
   end;
   -- 3. Determine Final IQAMA (Use Master, fallback to Historical Yard Data)
   if l_truck_rec.driver_iqama is not null then
      l_fallback_iqama := l_truck_rec.driver_iqama;
   else
      begin
         select driver_iqama 
           into l_fallback_iqama 
           from xxotm_vehicle_master_t 
          where truck_nbr = p_truck_nbr 
            and driver_iqama is not null
          order by entry_time desc 
          fetch first 1 rows only;
      exception
         when no_data_found then
            l_fallback_iqama := '';
      end;
   end if;
   -- 4. Output the Found Truck Data
   apex_json.open_object;
   apex_json.write('response_code', 200);
   apex_json.write('response_message', 'Success');
   
   apex_json.open_object('data');
   
   -- Map columns from the master table
   apex_json.write('truck_nbr',    nvl(l_truck_rec.VEHICLE_XID, ''));
   apex_json.write('driver_name',  nvl(l_truck_rec.driver_name, ''));
   apex_json.write('driver_iqama', l_fallback_iqama);
   
   apex_json.close_object; -- data
   apex_json.close_object; -- root
   
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_truck_info;

   -- ========================================================================
   -- XX_OTM_GET_VALIDATE_CONTAINER_APEX   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_VALIDATE_CONTAINER_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_validate_container_apex (
   p_container_number in varchar2,
   p_user_id in varchar2 default null
)
as
    v_location varchar2(100);
    -- Last Updated Date : 11-Feb-2026
    -- Last Updated By : Sanjit
    -- Description : Removed TRIP_STARTED shipments validation condition
   type record_type is record (
         container_type varchar2(100),
         cont_no        varchar2(100),
         shipment_xid   varchar2(100),
         customer_name  varchar2(100)
   );
   l_record         record_type;
   l_data           json_object_t;
   v_found          boolean := false;
   l_status_value   varchar2(100) := null;
   l_count          number := 0;
   l_remarks        varchar2(240) := null;
   l_http_status    varchar2(240) := null;
   l_customername   varchar2(240) := null;
   l_track_response clob := null;
   l_output         clob;
   l_container_nbr varchar2(100);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   cursor c_data_cursor (
      p_container_number varchar2
   ) is
   select distinct container_type,
                   cont_no,
                   shipment_xid,
                   customer_name
     from xxotm_shipments_t
    where cont_no = p_container_number and xxotm_shipments_t.location = v_location
      and shipment_name = 'INBOUND_CONTAINER' and cont_no not in (select container_nbr from xxotm_container_inventory_t where container_stored_time is not null  and container_released_time is  null and container_nbr = p_container_number and xxotm_container_inventory_t.location = v_location);

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   begin
       select container_nbr into l_container_nbr from xxotm_container_inventory_t 
       where container_stored_time is not null  and container_released_time is  null and container_nbr = p_container_number and xxotm_container_inventory_t.location = v_location;
        apex_json.initialize_clob_output;
        apex_json.open_object;
         apex_json.write(
             'response_code',
             400
          );
          apex_json.write(
             'response_message',
             'Container present in the Yard'
          );
           apex_json.close_object;
           l_output := apex_json.get_clob_output;
           htp.prn(l_output);
           apex_json.free_output;
           return;
       exception
       when others then 
       null;
    end;

   l_data := json_object_t();
   open c_data_cursor(p_container_number);
   loop
      fetch c_data_cursor into l_record;
      exit when c_data_cursor%notfound;

        -- First API call - Get Trip Status
      begin
         apex_web_service.g_request_headers.delete();
         l_track_response := apex_web_service.make_rest_request(
            p_url         => xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                     || l_record.shipment_xid
                     || '/statuses/NAQLEEN.TRIP_STATUS?expand=all',
            p_http_method => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );
      exception
         when others then
            l_remarks := sqlerrm;
            dbms_output.put_line('Error in first API call: ' || sqlerrm);
      end;

      l_http_status := apex_web_service.g_status_code;
      dbms_output.put_line('First API Status: ' || l_http_status);
      if l_http_status in ( '200',
                            '201' ) then
         apex_json.parse(l_track_response);
         l_status_value := apex_json.get_varchar2(p_path => 'statusValueGid');
         dbms_output.put_line('Status Value: ' || l_status_value);
         if l_status_value in ( 
                                'NAQLEEN.TRIP_NOT_STARTED' ) then
            l_count := l_count + 1;
            dbms_output.put_line('Count: ' || l_count);

                -- Second API call - Get Customer Name
            if l_count = 1 then
               l_track_response := null;
               begin
                  l_track_response := apex_web_service.make_rest_request(
                     p_url         => xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                              || l_record.shipment_xid
                              || '/refnums?expand=all',
                     p_http_method => 'GET',
                     p_credential_static_id => l_credential_static_id,
                     p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                  );
               exception
                  when others then
                     l_remarks := sqlerrm;
                     dbms_output.put_line('Error in second API call: ' || sqlerrm);
               end;

               l_http_status := apex_web_service.g_status_code;
               dbms_output.put_line('Second API Status: ' || l_http_status);
               if l_http_status in ( '200',
                                     '201' ) then
                  apex_json.parse(l_track_response);
                  for i in 1..apex_json.get_count('items') loop
                     if apex_json.get_varchar2(
                        p_path => 'items[%d].shipmentRefnumQualGid',
                        p0     => i
                     ) = 'NAQLEEN.CUS_NAME' then
                        l_customername := apex_json.get_varchar2(
                           p_path => 'items[%d].shipmentRefnumValue',
                           p0     => i
                        );
                        v_found := true;
                        exit; -- Exit loop after finding customer name
                     end if;
                  end loop;

                  dbms_output.put_line('Customer Name: ' || l_customername);
               end if;
            end if;
         end if;
      end if;

        -- Build data object if found
      if v_found then
         l_data.put(
            'container_type',
            l_record.container_type
         );
         l_data.put(
            'liner',
            l_customername
         );
         exit; -- Exit after first successful match
      end if;

   end loop;
   close c_data_cursor;

    -- Build final response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if v_found then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.open_object('data');
      apex_json.write(
         'container_type',
         l_data.get_string('container_type')
      );
      apex_json.write(
         'liner',
         l_data.get_string('liner')
      );
      apex_json.write(
         'shipment_nbr',
         l_record.shipment_xid
      );
      apex_json.close_object;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No Data Found'
      );
   end if;

   apex_json.close_object;
   l_output := apex_json.get_clob_output;
--    dbms_output.put_line('Final Output: ' || l_output);
   htp.prn(l_output);
   apex_json.free_output;
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         400
      );
      apex_json.write(
         'response_message',
         'ERROR WHILE EXECUTING METHOD: ' || sqlerrm
      );
      apex_json.close_object;
      l_output := apex_json.get_clob_output;
    --   dbms_output.put_line('Error Output: ' || l_output);
      htp.prn(l_output);
      apex_json.free_output;
end xx_otm_get_validate_container_apex;

   -- ========================================================================
   -- XX_OTM_GET_VEHICLE_EXIT_APEX   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_GET_VEHICLE_EXIT_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_vehicle_exit_apex (
    p_truck_number IN VARCHAR2,
    p_user_id in varchar2 default null
)
AS
    v_location varchar2(100);

    TYPE record_type IS RECORD (
        driver_iqama VARCHAR2(100),
        driver_name  VARCHAR2(100)
    );
    l_record     record_type;
    l_response   json_object_t;
    l_data       json_object_t;
    j            apex_json.t_values;
    v_found      BOOLEAN := FALSE;

    CURSOR c_data_cursor (p_truck_number VARCHAR2) IS
    SELECT DISTINCT driver_iqama, driver_name
    FROM xxotm_vehicle_master_t
    WHERE truck_nbr = p_truck_number AND exit_time IS NULL AND status LIKE '%GATE OUT%'
      AND xxotm_vehicle_master_t.location = v_location;

BEGIN
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    l_response := json_object_t();
    l_data := json_object_t();

    OPEN c_data_cursor(p_truck_number);
    LOOP
        FETCH c_data_cursor INTO l_record;
        EXIT WHEN c_data_cursor%NOTFOUND;

        v_found := TRUE;
        -- Single object instead of array
        l_data.put('driver_iqama', l_record.driver_iqama);
        l_data.put('driver_name',  l_record.driver_name);
        EXIT; -- exit after first match
    END LOOP;
    CLOSE c_data_cursor;

    -- If no driver found
    IF NOT v_found THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 404);
        apex_json.write('response_message', 'Vehicle Not Found');
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        RETURN;
    END IF;

    l_response.put('response_code', 200);
    l_response.put('response_message', 'Success');
    l_response.put('data', l_data);

    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write('response_code', 200);
    apex_json.write('response_message', 'Success');

    -- Convert object to JSON
    apex_json.parse(j, l_response.get('data').to_string());
    apex_json.write('data', j);

    apex_json.close_object;
    htp.prn(apex_json.get_clob_output);

EXCEPTION
    WHEN OTHERS THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 400);
        apex_json.write('response_message', 'ERROR WHILE EXECUTING METHOD: ' || sqlerrm);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);

END XX_OTM_GET_VEHICLE_EXIT_APEX;

   -- ========================================================================
   -- XX_OTM_GET_VEHICLE_INQUIRY_APEX   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_GET_VEHICLE_INQUIRY_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_vehicle_inquiry_apex (
    p_truck_number IN VARCHAR2,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
AS
  -- Last Updated : 11-Jun-2026
    -- Changes:
    --   1. Cross-check XXOTM_TRACKING_EVENTS_T for stale vehicle master status.
    --   2. Multi-shipment support: parse up to 2 slots from vehicle master (PATH A),
    --      or fall back to truck_3pl lookup anchored to entry_time (PATH B).
    --   3. PATH B deduplicates via GROUP BY — guarantees 2 DIFFERENT shipments.
    --   4. Outbound/release shipment fallback via container_inventory.
    --   5. All workflow steps carry actual event timestamps from tracking_events.
    --   6. LCL: two ops steps (TASK ASSIGNED + STUFFED/DESTUFFED event-driven label).
    TYPE record_type IS RECORD (
        truck_nbr    VARCHAR2(100),
        type         VARCHAR2(100),
        driver_name  VARCHAR2(100),
        driver_iqama VARCHAR2(100),
        entry_time   VARCHAR2(100),
        exit_time    VARCHAR2(100),
        status       VARCHAR2(100),
        order_type   VARCHAR2(100),
        shipment_nbr VARCHAR2(4000)
    );
    l_record              record_type;
    l_data                json_object_t;
    l_steps               json_array_t;
    l_response            json_object_t;
    l_found               BOOLEAN := FALSE;
    j                     apex_json.t_values;

    l_clean_status        VARCHAR2(100);
    l_order_type          VARCHAR2(100);
    l_level               NUMBER  := 10;
    l_is_rejected         BOOLEAN := FALSE;
    l_ops_event           VARCHAR2(100);

    -- Tracking-events cross-check: shipment pointers
    l_te_shipment         VARCHAR2(200);  -- first active shipment (echoed in response)
    l_te_outbound_shp     VARCHAR2(200);

    -- Tracking-events cross-check: timestamps per step
    l_te_inspected_time     VARCHAR2(100);
    l_te_gate_in_time       VARCHAR2(100);
    l_te_ops_time           VARCHAR2(100);  -- CONTAINER STORED / RELEASED
    l_te_gate_out_time      VARCHAR2(100);
    l_te_task_assigned_time VARCHAR2(100);  -- LCL only
    l_te_stuffed_time       VARCHAR2(100);  -- LCL only
    l_te_lcl_ops_event      VARCHAR2(50);   -- 'STUFFED' or 'DESTUFFED' when event exists

    -- Declared BARE, and here rather than lower down: c_data_cursor below filters
    -- on v_location, and a cursor cannot reference a variable declared after it.
    -- It is assigned as the first statement after BEGIN, never as an initialiser
    -- -- an exception raised while elaborating a declaration is not catchable by
    -- this block's own EXCEPTION handler, so ORDS would return a raw Oracle stack
    -- instead of the JSON envelope.
    --
    -- This declaration had been commented out while five statements below still
    -- referenced v_location, so the procedure could not compile (PLS-00201) and
    -- neither precompile_check nor assemble_package can see that -- both are
    -- text-level tools.
    v_location            VARCHAR2(100);

    -- ── c_data_cursor ─────────────────────────────────────────────────────────
    CURSOR c_data_cursor (p_truck VARCHAR2) IS
        SELECT truck_nbr, type, driver_name, driver_iqama,
               entry_time, exit_time, status, order_type, shipment_nbr
          FROM xxotm_vehicle_master_t
         WHERE truck_nbr = p_truck
        --    AND location  = p_loc
        and xxotm_vehicle_master_t.location = v_location
         ORDER BY entry_time DESC
         FETCH FIRST 1 ROWS ONLY;

    -- ── fetch_te_events ───────────────────────────────────────────────────────
    -- Single pass over tracking_events for one shipment XID.
    -- Populates all timestamp variables; upgrades l_level / l_clean_status only
    -- when the event represents higher progress than what the vehicle master shows.
    -- Safe to call multiple times (for 2 shipments) — only ever upgrades.
    PROCEDURE fetch_te_events(p_shipment IN VARCHAR2) IS
    BEGIN
        FOR rec IN (
            SELECT event_type, event_date
              FROM xxotm_tracking_events_t
             WHERE shipment_nbr = p_shipment
               AND event_type IN (
                   'INSPECTED',
                   'GATE IN',
                   'TASK_ASSIGNED',
                   'STUFFED',
                   'DESTUFFED',
                   'CONTAINER STORED',
                   'CONTAINER RELEASED',
                   'GATE OUT'
               )
             ORDER BY event_date ASC
        ) LOOP
            CASE rec.event_type
                WHEN 'INSPECTED' THEN
                    l_te_inspected_time := rec.event_date;

                WHEN 'GATE IN' THEN
                    l_te_gate_in_time := rec.event_date;

                WHEN 'TASK_ASSIGNED' THEN
                    l_te_task_assigned_time := rec.event_date;

                WHEN 'STUFFED' THEN
                    l_te_stuffed_time  := rec.event_date;
                    l_te_lcl_ops_event := 'STUFFED';
                    IF l_level < 40 THEN
                        l_level := 40; l_clean_status := 'STUFFED';
                    END IF;

                WHEN 'DESTUFFED' THEN
                    l_te_stuffed_time  := rec.event_date;
                    l_te_lcl_ops_event := 'DESTUFFED';
                    IF l_level < 40 THEN
                        l_level := 40; l_clean_status := 'DESTUFFED';
                    END IF;

                WHEN 'CONTAINER STORED' THEN
                    l_te_ops_time := rec.event_date;
                    IF l_level < 40 THEN
                        l_level := 40; l_clean_status := 'CONTAINER STORED';
                    END IF;

                WHEN 'CONTAINER RELEASED' THEN
                    l_te_ops_time := rec.event_date;
                    IF l_level < 40 THEN
                        l_level := 40; l_clean_status := 'CONTAINER RELEASED';
                    ELSIF l_level = 40 THEN
                        l_clean_status := 'CONTAINER RELEASED';
                    END IF;

                WHEN 'GATE OUT' THEN
                    l_te_gate_out_time := rec.event_date;
                    IF l_level < 50 THEN
                        l_level := 50; l_clean_status := 'GATE OUT';
                    END IF;

                ELSE NULL;
            END CASE;
        END LOOP;
    END fetch_te_events;

    -- ── fetch_outbound_te_events ──────────────────────────────────────────────
    -- Looks up the outbound/release shipment from container_inventory when
    -- CONTAINER RELEASED / GATE OUT are posted under a CRO/LRO shipment XID
    -- rather than the inbound one. Only runs when ops events not yet found.
    PROCEDURE fetch_outbound_te_events(p_inbound_shipment IN VARCHAR2) IS
    BEGIN
        IF l_te_ops_time IS NULL THEN
            BEGIN
                SELECT REPLACE(outbound_shipment_nbr, 'NAQLEEN.', '')
                  INTO l_te_outbound_shp
                  FROM xxotm_container_inventory_t
                 WHERE inbound_shipment_nbr  = p_inbound_shipment
                   AND outbound_shipment_nbr IS NOT NULL
                   AND rownum = 1
                   and xxotm_container_inventory_t.location = v_location;
                fetch_te_events(l_te_outbound_shp);
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;
    END fetch_outbound_te_events;

    -- ── process_shipment ──────────────────────────────────────────────────────
    -- Entry point per shipment: runs both event fetches and backfills order_type.
    PROCEDURE process_shipment(p_shipment IN VARCHAR2) IS
    BEGIN
        IF p_shipment IS NULL THEN RETURN; END IF;

        IF l_te_shipment IS NULL THEN
            l_te_shipment := p_shipment;
        END IF;

        fetch_te_events(p_shipment);
        fetch_outbound_te_events(p_shipment);

        IF l_order_type IS NULL THEN
            BEGIN
                SELECT UPPER(shipment_name)
                  INTO l_order_type
                  FROM xxotm_shipments_t
                 WHERE shipment_xid = p_shipment
                    OR shipment_xid = 'NAQLEEN.' || p_shipment
                    and xxotm_shipments_t.location = v_location
                 FETCH FIRST 1 ROWS ONLY;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;
    END process_shipment;

BEGIN
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    --
    -- Must precede OPEN c_data_cursor: the cursor's predicate reads v_location,
    -- and it is bound at OPEN.
    IF v_location IS NULL THEN
        xxotm_location_required;
        RETURN;
    END IF;

    l_response := json_object_t();
    l_data     := json_object_t();

    OPEN c_data_cursor(p_truck_number);
    FETCH c_data_cursor INTO l_record;

    IF c_data_cursor%FOUND THEN
        l_found := TRUE;

        -- Strip NAQLEEN. prefix; preserve case for matching rules
        l_clean_status := REPLACE(NVL(l_record.status, ''), 'NAQLEEN.', '');
        l_order_type   := UPPER(NVL(l_record.order_type, ''));

        -- Fallback: fetch order_type from shipments when missing on vehicle master
        IF l_order_type IS NULL AND l_record.shipment_nbr IS NOT NULL THEN
            BEGIN
                SELECT UPPER(shipment_name)
                  INTO l_order_type
                  FROM xxotm_shipments_t
                 WHERE shipment_xid = REGEXP_SUBSTR(l_record.shipment_nbr, '[^,]+', 1, 1)
                   AND rownum = 1
                   and xxotm_shipments_t.location = v_location;
            EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
            END;
        END IF;

        -- Map local status → progress level (10 – 60)
        IF    l_clean_status IN ('vehicle_exit','VEHICLE_EXIT','VEHICLE EXIT')        THEN l_level := 60;
        ELSIF l_clean_status IN ('GATE_OUT','GATE OUT')                               THEN l_level := 50;
        ELSIF l_clean_status IN ('CONTAINER STORED','CONTAINER RELEASED',
                                 'STUFFED','DESTUFFED')                               THEN l_level := 40;
        ELSIF l_clean_status IN ('GATE_IN','GATE IN')                                 THEN l_level := 30;
        ELSIF l_clean_status  = 'gate_in'                                             THEN l_level := 25;
        ELSIF l_clean_status  = 'INSPECTED'                                           THEN l_level := 20;
        ELSIF l_clean_status IN ('inspection','INSPECTION')                           THEN l_level := 15;
        ELSIF l_clean_status IN ('GATE EXIT','gate_exit','GATE_EXIT')                 THEN l_level := 50; l_is_rejected := TRUE;
        ELSE  l_level := 10;
        END IF;

        -- ── Cross-check XXOTM_TRACKING_EVENTS_T ──────────────────────────────
        --
        -- PATH A — shipment_nbr present on vehicle master
        --   Parse up to 2 comma-separated XIDs. These are already the correct
        --   active shipments (written by the gate-in process).
        --
        -- PATH B — shipment_nbr is NULL on vehicle master
        --   Look up via xxotm_shipments_t.truck_3pl (same fallback used by
        --   XX_OTM_GATE_OUT_TRUCK_DETAILS Pass 2).
        --   Anchor filter: shipment must have a VEHICLE ENTERED or GATE IN event
        --   at or after l_record.entry_time — ties it to THIS visit, not a past one.
        --   GROUP BY collapses duplicate shipment rows; FETCH FIRST 2 guarantees
        --   at most 2 distinct active shipments (one truck = max 2 containers).
        -- ─────────────────────────────────────────────────────────────────────

        IF l_record.shipment_nbr IS NOT NULL THEN
            -- PATH A
            process_shipment(
                REPLACE(REGEXP_SUBSTR(l_record.shipment_nbr, '[^,]+', 1, 1), 'NAQLEEN.', ''));
            process_shipment(
                REPLACE(REGEXP_SUBSTR(l_record.shipment_nbr, '[^,]+', 1, 2), 'NAQLEEN.', ''));

        ELSE
            -- PATH B
            FOR rec IN (
                SELECT shp_xid
                  FROM (
                      SELECT REPLACE(s.shipment_xid, 'NAQLEEN.', '') AS shp_xid,
                             MAX(s.update_date)                       AS latest_update
                        FROM xxotm_shipments_t s
                       WHERE s.truck_3pl = p_truck_number
                         AND s.location  = v_location
                         AND EXISTS (
                             SELECT 1
                               FROM xxotm_tracking_events_t te
                              WHERE te.shipment_nbr = REPLACE(s.shipment_xid, 'NAQLEEN.', '')
                                AND te.event_type   IN ('VEHICLE ENTERED', 'GATE IN')
                                AND te.event_date   >= l_record.entry_time
                         )
                       GROUP BY s.shipment_xid
                       ORDER BY latest_update DESC
                  )
                 FETCH FIRST 2 ROWS ONLY
            ) LOOP
                process_shipment(rec.shp_xid);
            END LOOP;
        END IF;
        -- ── End Cross-check ──────────────────────────────────────────────────

        -- Populate JSON response fields
        l_data.put('truck_nbr',        l_record.truck_nbr);
        l_data.put('type',             l_record.type);
        l_data.put('driver_name',      NVL(l_record.driver_name,  'N/A'));
        l_data.put('driver_iqama_nbr', NVL(l_record.driver_iqama, 'N/A'));
        l_data.put('entry_time',       NVL(l_record.entry_time,   'N/A'));
        l_data.put('exit_time',        NVL(l_record.exit_time,    'N/A'));
        l_data.put('status',           NVL(l_clean_status, NVL(l_record.status, 'N/A')));
        l_data.put('order_type',       NVL(l_order_type,          'N/A'));
        l_data.put('shipment_nbr',     NVL(l_record.shipment_nbr, NVL(l_te_shipment, 'N/A')));

               -- can_delete_truck: allowed only at entry / inspection / gate_in stages,
        --   LRO/CRO at GATE IN, OR when no shipment is resolvable post-ops (orphaned truck).
        IF l_clean_status IN ('vehicle_entry','VEHICLE_ENTRY','VEHICLE ENTRY',
                              'inspection','INSPECTION','gate_in') THEN
            l_data.put('can_delete_truck', true);
        ELSIF l_clean_status = 'GATE IN' AND l_order_type IN ('LRO','CRO') THEN
            l_data.put('can_delete_truck', true);
        ELSIF l_record.shipment_nbr IS NULL
          AND l_te_shipment IS NULL
          AND l_level >= 40 THEN
            l_data.put('can_delete_truck', true);   -- ops done but no shipment ever linked
        ELSE
            l_data.put('can_delete_truck', false);
        END IF;


        -- ── Workflow steps ────────────────────────────────────────────────────
        l_steps := json_array_t();

        DECLARE
            l_pending_added BOOLEAN := FALSE;

            PROCEDURE add_step(p_event  IN VARCHAR2,
                               p_status IN VARCHAR2,
                               p_time   IN VARCHAR2) IS
                l_obj json_object_t;
            BEGIN
                IF l_pending_added THEN RETURN; END IF;
                l_obj := json_object_t();
                l_obj.put('event',  p_event);
                l_obj.put('status', p_status);
                l_obj.put('time',   NVL(p_time, 'N/A'));
                l_steps.append(l_obj);
                IF p_status = 'PENDING' THEN l_pending_added := TRUE; END IF;
            END add_step;

        BEGIN
            -- 1. Vehicle Entry — always completed (truck is already inside)
            add_step('VEHICLE ENTRY', 'COMPLETED', l_record.entry_time);

            -- 2. Inspection — INBOUND_CONTAINER only
            IF l_order_type = 'INBOUND_CONTAINER'
               OR UPPER(l_clean_status) IN ('INSPECTED','INSPECTION') THEN
                IF l_level >= 20 THEN add_step('INSPECTED', 'COMPLETED', l_te_inspected_time);
                ELSE                  add_step('INSPECTION', 'PENDING',   NULL);
                END IF;
            END IF;

            IF l_is_rejected THEN
                -- Rejected path — truck exited without full gate processing
                add_step('GATE EXIT', 'COMPLETED', l_te_gate_out_time);

            ELSE
                -- 3. Gate In
                IF l_level >= 30 THEN add_step('GATE IN', 'COMPLETED', l_te_gate_in_time);
                ELSE                  add_step('GATE IN', 'PENDING',   NULL);
                END IF;

                         -- 4. Container ops
            IF l_order_type IN ('LCL','LOADING_LCL','OFFLOADING_LCL') THEN

                -- 4a. Task Assigned
                IF l_te_task_assigned_time IS NOT NULL THEN
                    add_step('TASK ASSIGNED', 'COMPLETED', l_te_task_assigned_time);
                ELSIF l_level >= 40 THEN
                    add_step('TASK ASSIGNED', 'COMPLETED', NULL);
                ELSE
                    add_step('TASK ASSIGNMENT', 'PENDING', NULL);
                END IF;

                -- 4b. Stuffed / Destuffed
                IF l_te_lcl_ops_event IS NOT NULL THEN
                    add_step(l_te_lcl_ops_event,    'COMPLETED', l_te_stuffed_time);
                ELSIF l_level >= 50 THEN
                    add_step('STUFFED / DESTUFFED', 'COMPLETED', NULL);
                ELSE
                    add_step('STUFFING / DESTUFFING', 'PENDING',   NULL);
                END IF;

            ELSE
                -- LRO / CRO / INBOUND_CONTAINER / RELEASE_CFS — single ops step
                IF    UPPER(l_clean_status) = 'CONTAINER RELEASED'  THEN l_ops_event := 'CONTAINER RELEASED';
                ELSIF UPPER(l_clean_status) = 'CONTAINER STORED'    THEN l_ops_event := 'CONTAINER POSITIONED';
                ELSIF l_order_type IN ('CRO','LRO','RELEASE_CFS')   THEN l_ops_event := 'CONTAINER RELEASED';
                ELSE                                                      l_ops_event := 'CONTAINER POSITIONED';
                END IF;

                IF l_level >= 40 THEN
                    add_step(l_ops_event, 'COMPLETED', l_te_ops_time);   -- 'CONTAINER RELEASED' / 'CONTAINER POSITIONED'
                ELSE
                    CASE l_ops_event
                    WHEN 'CONTAINER RELEASED'   THEN add_step('CONTAINER RELEASE',  'PENDING', NULL);
                    WHEN 'CONTAINER POSITIONED' THEN add_step('CONTAINER POSITION', 'PENDING', NULL);
                    ELSE                             add_step(l_ops_event,           'PENDING', NULL);
                    END CASE;
                END IF;

            END IF;

            -- 5. Gate Out
            IF l_level >= 50 THEN add_step('GATE OUT', 'COMPLETED', l_te_gate_out_time);
            ELSE                  add_step('GATE OUT', 'PENDING',   NULL);
            END IF;

            END IF;

            -- 6. Vehicle Exit
            IF l_level >= 60 THEN add_step('VEHICLE EXIT', 'COMPLETED', l_record.exit_time);
            ELSE                  add_step('VEHICLE EXIT', 'PENDING',   NULL);
            END IF;
        END;

        l_data.put('workflow_steps', l_steps);

    END IF;

    CLOSE c_data_cursor;

    apex_json.initialize_clob_output;
    apex_json.open_object;
    IF l_found THEN
        apex_json.write('response_code',    200);
        apex_json.write('response_message', 'Success');
        apex_json.parse(j, l_data.to_string());
        apex_json.write('data', j);
    ELSE
        apex_json.write('response_code',    404);
        apex_json.write('response_message', 'Truck not found');
        apex_json.write('data', '');
    END IF;
    apex_json.close_object;
    htp.prn(apex_json.get_clob_output);
    apex_json.free_output;

EXCEPTION
    WHEN OTHERS THEN
        apex_json.free_output;
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code',    500);
        apex_json.write('response_message', 'ERROR WHILE EXECUTING METHOD: ' || sqlerrm);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        apex_json.free_output;
END XX_OTM_GET_VEHICLE_INQUIRY_APEX;

   -- ========================================================================
   -- XX_OTM_GET_VEHICLE_INQUIRY_TRUCKS   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_GET_VEHICLE_INQUIRY_TRUCKS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_get_vehicle_inquiry_trucks (
   p_search_text in varchar2 default null,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
    
 v_location varchar2(100);

begin
 v_location := xx_get_user_location(p_user_id);
 -- Location is mandatory. xx_get_user_location returns NULL when
 -- req_location_id is absent, malformed, or not permitted for this user;
 -- it no longer falls back to a default site. Continuing on NULL would
 -- filter on "location = NULL" and return an empty result set -- an empty
 -- screen with no error, which is worse than a refusal.
 if v_location is null then
    xxotm_location_required;
    return;
 end if;
    -- Configure APEX_JSON to output to CLOB
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- Write Standard Response Headers
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');

   -- Loop through results and write directly as strings
   for i in (
      select truck_nbr
        from xxotm_vehicle_master_t
       where ( p_search_text is null
          or upper(truck_nbr) like '%'
                                   || upper(p_search_text)
                                   || '%' )  and xxotm_vehicle_master_t.location = v_location
       group by truck_nbr
       order by max(entry_time) desc
   ) loop
      apex_json.write(i.truck_nbr);
   end loop;

   apex_json.close_array;
   apex_json.close_object;

    -- Output the generated JSON
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if apex_json.get_clob_output is not null then
         apex_json.free_output;
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_get_vehicle_inquiry_trucks;

   -- ========================================================================
   -- XX_OTM_MOBILE_DASHBORDS   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_MOBILE_DASHBORDS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_mobile_dashbords (
   p_is_web      in varchar2 default 'N',   -- 'Y' for web
   p_start_date  in varchar2 default null,  -- Format: 'YYYY-MM-DD'
   p_end_date    in varchar2 default null,  -- Format: 'YYYY-MM-DD'
   p_year        in varchar2 default null,  -- Format: 'YYYY'
   p_fetch_mode  in varchar2 default 'ALL', -- 'ALL', 'DAILY_TRANSACTIONS', or 'MONTHLY_TRANSACTIONS'
   p_user_id     in varchar2 default null
)
as
   -- Declared bare, assigned after BEGIN.
   v_location varchar2(100);
   -- Updated Date : 24-Feb-2026
   -- Description  : Dashboard metrics. Fixed ORDS NULL binding issue.
   
   l_trucks_in_yard       number;
   l_gate_in_no_gate_out  number;
   l_containers_terminal  number;
   l_empty_slots          number;
   l_invalid_containers   number;
   l_cfs_containers       number;
   
   l_start_date           varchar2(10);
   l_end_date             varchar2(10);
   l_year                 varchar2(4);
   
   -- We will store the resolved fetch mode here
   l_mode                 varchar2(50);

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- Apply NVL to handle APEX REST passing explicit NULLs
   l_mode := nvl(upper(p_fetch_mode), 'ALL');

   -- 1. Determine Target Dates & Year as Strings
   begin
      if p_start_date is not null then
         l_start_date := substr(p_start_date, 1, 10);
      else
         l_start_date := to_char(sysdate - 7, 'YYYY-MM-DD');
      end if;

      if p_end_date is not null then
         l_end_date := substr(p_end_date, 1, 10);
      else
         l_end_date := to_char(sysdate, 'YYYY-MM-DD');
      end if;

      if p_year is not null then
         l_year := substr(p_year, 1, 4);
      else
         l_year := to_char(sysdate, 'YYYY');
      end if;
   exception
      when others then 
         l_start_date := to_char(sysdate - 7, 'YYYY-MM-DD');
         l_end_date   := to_char(sysdate, 'YYYY-MM-DD');
         l_year       := to_char(sysdate, 'YYYY');
   end;

   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write('response_code', 200);
   apex_json.write('response_message', 'Success');
   apex_json.open_object('data');

   -- ============================================================
   -- TRANSACTIONS ARRAYS (Calculated if WEB)
   -- ============================================================
   if upper(p_is_web) = 'Y' then

      if l_mode in ('ALL', 'DAILY_TRANSACTIONS') then
         apex_json.write('start_date_used', l_start_date);
         apex_json.write('end_date_used',   l_end_date);
         
         apex_json.open_array('daily_transactions');
         for r in (
            select dt as txn_date,
                   sum(stored_cnt) as stored_count,
                   sum(released_cnt) as released_count
              from (
                   select substr(container_stored_time, 1, 10) as dt, 1 as stored_cnt, 0 as released_cnt
                     from xxotm_container_inventory_t
                    where substr(container_stored_time, 1, 10) between l_start_date and l_end_date
                      and container_stored_time is not null and xxotm_container_inventory_t.location = v_location
                   union all
                   select substr(container_released_time, 1, 10) as dt, 0 as stored_cnt, 1 as released_cnt
                     from xxotm_container_inventory_t
                    where substr(container_released_time, 1, 10) between l_start_date and l_end_date
                      and container_released_time is not null and xxotm_container_inventory_t.location = v_location
              )
             group by dt
             order by txn_date
         ) loop
            apex_json.open_object;
            apex_json.write('date',           r.txn_date);
            apex_json.write('stored_count',   r.stored_count);
            apex_json.write('released_count', r.released_count);
            apex_json.close_object;
         end loop;
         apex_json.close_array;
      end if;

      if l_mode in ('ALL', 'MONTHLY_TRANSACTIONS') then
         apex_json.write('year_used', l_year);
         
         apex_json.open_array('monthly_transactions');
         for r in (
            select month_num,
                   sum(stored_cnt) as stored_count,
                   sum(released_cnt) as released_count
              from (
                   select substr(container_stored_time, 6, 2) as month_num, 1 as stored_cnt, 0 as released_cnt
                     from xxotm_container_inventory_t
                    where substr(container_stored_time, 1, 4) = l_year
                      and container_stored_time is not null and xxotm_container_inventory_t.location = v_location
                        and shipment_name in ('INBOUND_CONTAINER','STORE_AS_IT_IS')
                   union all
                   select substr(container_released_time, 6, 2) as month_num, 0 as stored_cnt, 1 as released_cnt
                     from xxotm_container_inventory_t
                    where substr(container_released_time, 1, 4) = l_year
                      and container_released_time is not null and xxotm_container_inventory_t.location = v_location
                        and shipment_name in ('CRO','LRO','RELEASE_CFS')
              )
             group by month_num
             order by month_num
         ) loop
            apex_json.open_object;
            begin
               apex_json.write('month', to_char(to_date(r.month_num, 'MM'), 'Mon'));
            exception
               when others then apex_json.write('month', r.month_num);
            end;
            apex_json.write('stored_count',   r.stored_count);
            apex_json.write('released_count', r.released_count);
            apex_json.close_object;
         end loop;
         apex_json.close_array;
      end if;
   end if;

   -- ============================================================
   -- FULL DASHBOARD METRICS
   -- ============================================================
   if l_mode = 'ALL' then

      select count(*) into l_trucks_in_yard
	  from xxotm_v_trucks_in_yard
	  where xxotm_v_trucks_in_yard.location = v_location;

     select count(*) into l_gate_in_no_gate_out
	  from xxotm_v_gate_out_eligible
	  where xxotm_v_gate_out_eligible.location = v_location;

      select count(*) into l_containers_terminal
        from xxotm_container_inventory_t
       where container_stored_time is not null
         and container_released_time is null
         and xxotm_container_inventory_t.location = v_location;

      select count(*) into l_empty_slots
        from xxotm_position_master_t
       where is_occupied = 'N' and xxotm_position_master_t.location = v_location;

      apex_json.write('trucks_in_yard',         l_trucks_in_yard);
      apex_json.write('gate_in_no_gate_out',    l_gate_in_no_gate_out);
      apex_json.write('containers_in_terminal', l_containers_terminal);
      apex_json.write('empty_slots',            l_empty_slots);

      if upper(nvl(p_is_web, 'N')) = 'Y' then

         select count(*) into l_invalid_containers
           from xxotm_container_inventory_t
          where container_stored_time is not null
            and container_released_time is null
            and (POSITION is null or POSITION = 'NA')
            and xxotm_container_inventory_t.location = v_location;

         select count(*) into l_cfs_containers
           from xxotm_cfs_containers_t
          where release_date is null and xxotm_cfs_containers_t.location = v_location;

         apex_json.write('invalid_containers', l_invalid_containers);
         apex_json.write('cfs_containers',     l_cfs_containers);

         apex_json.open_array('containers_by_customer');
         for r in (
            select ci.cust_name, count(*) as cnt
              from xxotm_container_inventory_t ci
             where ci.container_stored_time is not null
               and ci.container_released_time is null and ci.location = v_location
             group by ci.cust_name
             order by cnt desc
         ) loop
            apex_json.open_object;
            apex_json.write('customer_name', r.cust_name);
            apex_json.write('count',         r.cnt);
            apex_json.close_object;
         end loop;
         apex_json.close_array;

         apex_json.open_array('containers_by_type');
         for r in (
            select ci.container_type, count(*) as cnt
              from xxotm_container_inventory_t ci
             where ci.container_stored_time is not null
               and ci.container_released_time is null and ci.location = v_location
             group by ci.container_type
             order by cnt desc
         ) loop
            apex_json.open_object;
            apex_json.write('container_type', r.container_type);
            apex_json.write('count',          r.cnt);
            apex_json.close_object;
         end loop;
         apex_json.close_array;
      end if;
   end if;

   apex_json.close_object; -- data
   apex_json.close_object; -- root
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write('response_message', 'Error: ' || sqlerrm);
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_mobile_dashbords;

   -- ========================================================================
   -- XX_OTM_PACKING_LIST   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_PACKING_LIST.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_packing_list (
   p_body in blob,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   l_clob           clob;
   l_count          number;

   -- Header Variables
   l_customer       varchar2(200);
   l_customer_nbr   varchar2(100);
   l_container_nbr  varchar2(100);
   l_shipment_nbr   varchar2(100);
   l_hs_code        varchar2(100);
   l_cargo_desc     varchar2(4000);

   -- Item Variables
   l_item_desc      varchar2(4000);
   l_quantity       number;
   l_quantity_uom   varchar2(50);
   l_gross_weight   number;
   l_net_weight     number;
   l_weight_uom     varchar2(50);
   l_volume         number;
   l_volume_uom     varchar2(50);
   l_un_class       varchar2(50);
   l_country_origin varchar2(100);
   l_item_code      varchar2(100);
   l_shipment_name  varchar2(100);
   l_stock_exists  NUMBER;
   -- Stock Aggregation Variables
   type t_stock_rec is record (
         item_code varchar2(100),
         total_qty number
   );
   type t_stock_tab is
      table of t_stock_rec index by varchar2(100);
   l_stock_map      t_stock_tab;
   l_item_key       varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert BLOB to CLOB
   l_clob := to_clob(p_body);

   -- Parse JSON
   apex_json.parse(l_clob);

   -- Extract Header Data
   l_customer := apex_json.get_varchar2('customer_name');
   l_customer_nbr := apex_json.get_varchar2('customer_nbr');
   l_container_nbr := apex_json.get_varchar2('container_nbr');
   l_shipment_nbr := apex_json.get_varchar2('shipment_nbr');
   l_shipment_name := apex_json.get_varchar2('shipment_name');
   l_cargo_desc := apex_json.get_varchar2('cargo_description');

   -- Process Items Array
   l_count := apex_json.get_count('items');
   for i in 1..l_count loop
      -- Extract Item Data
      l_item_code := apex_json.get_varchar2(
         'items[%d].item_code',
         i
      );
      l_item_desc := apex_json.get_varchar2(
         'items[%d].item_description',
         i
      );
      l_quantity := apex_json.get_number(
         'items[%d].quantity',
         i
      );
      l_quantity_uom := apex_json.get_varchar2(
         'items[%d].quantity_uom',
         i
      );
      l_gross_weight := apex_json.get_number(
         'items[%d].gross_weight',
         i
      );
      l_net_weight := apex_json.get_number(
         'items[%d].net_weight',
         i
      );
      l_weight_uom := apex_json.get_varchar2(
         'items[%d].weight_uom',
         i
      );
      l_volume := apex_json.get_number(
         'items[%d].volume',
         i
      );
      l_volume_uom := apex_json.get_varchar2(
         'items[%d].volume_uom',
         i
      );
      l_un_class := apex_json.get_varchar2(
         'items[%d].UN_Class',
         i
      );
      l_country_origin := apex_json.get_varchar2(
         'items[%d].country_of_origin',
         i
      );

      -- Insert into Inventory Table (detailed line items)
      insert into xxotm_customer_inventory_t (
         cust_name,
         cust_nbr,
         container_nbr,
         shipment_nbr,
         item_code,
         cargo_description,
         item_description,
         qty,
         qty_uom,
         gross_weight,
         net_weight,
         weight_uom,
         volume,
         volume_uom,
         un_class,
         country_of_origin,
         creation_date,
         created_by,shipment_name
         , location
) values ( l_customer,
                 l_customer_nbr,
                 l_container_nbr,
                 l_shipment_nbr,
                 l_item_code,
                 l_cargo_desc,
                 l_item_desc,
                 l_quantity,
                 l_quantity_uom,
                 l_gross_weight,
                 l_net_weight,
                 l_weight_uom,
                 l_volume,
                 l_volume_uom,
                 l_un_class,
                 l_country_origin,
                 sysdate,
                 user,
                 l_shipment_name
                 , v_location
);

      -- Aggregate quantities by item_code for stock table only for STORE-AS-IT-IS
        -- Update Stock Table (Aggregation)

        if l_shipment_name is not null and l_shipment_name = 'STORE_AS_IT_IS' then
            select count(1)
              into l_stock_exists
              from xxotm_customer_stock_t
             where cust_nbr = l_customer_nbr
               and item_code = l_item_code and xxotm_customer_stock_t.location = v_location;

            if l_stock_exists > 0 then
                 -- Update existing stock
               update xxotm_customer_stock_t
                  set available_qty = available_qty + to_number(l_quantity)
                where cust_nbr = l_customer_nbr
                  and item_code = l_item_code and xxotm_customer_stock_t.location = v_location;
            else
                 -- Insert new stock record
               insert into xxotm_customer_stock_t (
                  cust_name,
                  cust_nbr,
                  item_code,
                  item_description,
                  available_qty,
                  qty_uom,
                  net_weight,
                  weight_uom
                  , location
) values ( l_customer,
                          l_customer_nbr,
                          l_item_code,
                          l_item_desc,
                          to_number(l_quantity),
                          l_quantity_uom,
                         to_number(l_net_weight),
                          l_weight_uom
                          , v_location
);
            end if;
        end if;
   end loop;

   -- Update Stock Table with aggregated quantities
   

   -- Output Success Response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);

   -- Clean up
   if dbms_lob.isopen(l_clob) = 1 then
      dbms_lob.freetemporary(l_clob);
   end if;

exception
   when others then
      if dbms_lob.isopen(l_clob) = 1 then
         dbms_lob.freetemporary(l_clob);
      end if;

      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xx_otm_packing_list;

   -- ========================================================================
   -- XX_OTM_POSITION_TRUCK_DETAILS   [3d-high-risk / MANUAL]
   -- source: db/work/XX_OTM_POSITION_TRUCK_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_position_truck_details (
   p_truck_nbr in varchar2,
   p_user_id   in varchar2 default null
)
as
   c_max_containers constant pls_integer := 2;

   -- Declared bare and assigned after BEGIN: an exception raised while
   -- elaborating a declaration escapes this block's own handler, and ORDS would
   -- return a raw Oracle stack instead of the JSON envelope.
   v_location             varchar2(100);

   l_truck_nbr            varchar2(50);
   l_driver_name          varchar2(50);
   l_driver_iqama         varchar2(50);
   l_credential_static_id varchar2(30) := 'OTM_API_AUTH';

    -- API Variables
   l_url                  varchar2(4000);
   l_response_clob        clob;

   -- Per-shipment evaluation flags
   l_has_gate_in          boolean;
   l_has_gate_out         boolean;
   l_has_container_stored boolean;
   l_event_count          number;
   l_status_code          varchar2(200);

   -- Containers found on this truck
   type t_cont is record (
      shipment_xid   varchar2(50),
      container_nbr  varchar2(50),
      container_type varchar2(50),
      shipment_name  varchar2(50),
      remarks        varchar2(4000)
   );
   type t_conts is table of t_cont index by binary_integer;
   l_conts                t_conts;
   l_rec                  t_cont;

   -- Terminal lookup is driven by the container types actually present. At most
   -- two distinct types can appear, so two slots is enough and keeps the query
   -- static.
   l_type_a               varchar2(10);
   l_type_b               varchar2(10);
   l_mapped               varchar2(10);

   -- Shipments gate in recorded against THIS truck visit, comma separated.
   -- Declared before the cursor because the cursor reads it; assigned after
   -- BEGIN, and bound at OPEN.
   l_vm_shipments         varchar2(4000);

   -- --------------------------------------------------------------------------
   -- Candidate shipments: the truck's OPEN VISIT first, truck_3pl only as a
   -- fallback.
   --
   -- Position is the step after gate in, so by the time this runs the vehicle
   -- master already names the shipments that came in on this truck. Reading
   -- them is both more accurate and cheaper than re-deriving the set:
   --
   --   * VISIT SCOPING. st.truck_3pl = p_truck_nbr matches EVERY shipment ever
   --     linked to that plate, with no exit_time filter. A shipment from a
   --     previous visit that never reached CONTAINER STORED still passes the
   --     tracking-event test below (GATE IN, no GATE OUT, no CONTAINER STORED),
   --     so it could be positioned against today's truck. The visit list cannot
   --     do that -- it describes one visit.
   --
   --   * BOUNDED API CALLS. The loop below makes one OTM call per candidate and
   --     only stops once two are ACCEPTED, so a truck with many historical
   --     shipments and none qualifying walks the entire cursor, one synchronous
   --     round trip at a time. A visit names at most two.
   --
   --   * ONE SOURCE OF TRUTH. It is the same list XX_OTM_GENERATE_EIR splits for
   --     siblings, XX_OTM_GATE_OUT_TRUCK_DETAILS uses for PASS 1, and
   --     XX_OTM_SUBMIT_GATE_OUT checks ownership against. Position was the only
   --     one of the four deriving its own set.
   --
   -- The truck_3pl fallback is kept and only fires when the visit names nothing
   -- -- an older row written before gate in populated shipment_nbr, or a truck
   -- that reached the yard by another route. Without it those trucks would drop
   -- off the position screen entirely.
   --
   -- The shipment_name filter stays on BOTH paths. It is what keeps the screen
   -- to containers being stored: a CRO/LRO release also has GATE IN and no
   -- CONTAINER STORED, so the tracking-event test alone would let it through.
   -- --------------------------------------------------------------------------
   cursor c_shipments is
   select st.shipment_xid,
          st.cont_no,
          st.container_type,
          st.shipment_name
     from xxotm_shipments_t st
    where st.location = v_location
      and ( st.shipment_name like '%INBOUND_CONTAINER%'
       or st.shipment_name like '%STORE_AS_IT_IS%'  )
      and (
             -- named on this truck's open visit
             ( l_vm_shipments is not null
               and ','
                   || replace(replace(
                         upper(l_vm_shipments),
                         ' '
                      ), 'NAQLEEN.')
                   || ',' like '%,'
                              || upper(st.shipment_xid)
                              || ',%' )
             -- fallback: the sync's link, only when the visit names nothing
          or ( l_vm_shipments is null
               and st.truck_3pl = p_truck_nbr )
          );

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   apex_json.initialize_clob_output;
   apex_json.open_object;

   -- Get Truck/Driver Details (Once, as they are common for the truck)
   --
   -- shipment_nbr comes back in the same pass -- this row IS the open visit the
   -- cursor needs, so fetching it separately would query the same row twice.
   -- It must be assigned before the cursor opens below; a cursor binds its
   -- variables at OPEN, not at declaration.
   begin
      select xvmt.truck_nbr,
             xvmt.driver_name,
             xvmt.driver_iqama,
             xvmt.shipment_nbr
        into
         l_truck_nbr,
         l_driver_name,
         l_driver_iqama,
         l_vm_shipments
        from xxotm_vehicle_master_t xvmt
       where xvmt.truck_nbr = p_truck_nbr
         and entry_time is not null
         and exit_time is null
         and xvmt.location = v_location
         and rownum = 1;
   exception
      when no_data_found then
         -- No open visit at this site. Leaving l_vm_shipments null is what puts
         -- the cursor on its truck_3pl fallback, which is the right answer here:
         -- with no visit to describe, the sync link is all there is.
         l_truck_nbr := p_truck_nbr;
         l_driver_name := null;
         l_driver_iqama := null;
         l_vm_shipments := null;
   end;

   -- Collect every shipment with GATE IN and no GATE OUT / CONTAINER STORED.
   -- Prod exited on the first hit, which is what made this endpoint
   -- single-container.
   for r in c_shipments loop
      exit when l_conts.count >= c_max_containers;

      l_has_gate_in := false;
      l_has_gate_out := false;
      l_has_container_stored := false;
      l_rec.remarks := null;

      -- One call per shipment, expanded so attribute5 (remarks) comes back with
      -- the tracking events.
      l_url := xxotm_get_cfg('OTM_BASE_URL')
               || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
               || r.shipment_xid
               || '?expand=trackingEvents';
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      begin
         l_response_clob := apex_web_service.make_rest_request(
            p_url         => l_url,
            p_http_method => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         apex_json.parse(l_response_clob);

         -- STORE_AS_IT_IS carries the operator's note in attribute5.
         l_rec.remarks := apex_json.get_varchar2('attribute5');

         l_event_count := nvl(apex_json.get_count('trackingEvents.items'), 0);
         for i in 1..l_event_count loop
            l_status_code := apex_json.get_varchar2(
               'trackingEvents.items[%d].statusCodeGid',
               i
            );
            if instr(
               l_status_code,
               'GATE IN'
            ) > 0 then
               l_has_gate_in := true;
            end if;
            if instr(
               l_status_code,
               'GATE OUT'
            ) > 0 then
               l_has_gate_out := true;
            end if;
            if instr(
               l_status_code,
               'CONTAINER STORED'
            ) > 0 then
               l_has_container_stored := true;
            end if;
         end loop;

      exception
         when others then
            l_has_gate_in := false; -- Fail safe
      end;

      -- Must have GATE IN, must NOT have GATE OUT or CONTAINER STORED
      if
         l_has_gate_in
         and not l_has_gate_out
         and not l_has_container_stored
      then
         l_rec.shipment_xid   := r.shipment_xid;
         l_rec.container_nbr  := r.cont_no;
         l_rec.container_type := r.container_type;
         l_rec.shipment_name  := r.shipment_name;
         l_conts(l_conts.count + 1) := l_rec;

         -- Remember the mapped types so the terminal list covers every
         -- container on the truck, not just the first.
         if r.container_type like '2%' then
            l_mapped := '20FT';
         elsif r.container_type like '4%' then
            l_mapped := '40FT';
         else
            l_mapped := null;
         end if;

         if l_mapped is not null then
            if l_type_a is null or l_type_a = l_mapped then
               l_type_a := l_mapped;
            else
               l_type_b := l_mapped;
            end if;
         end if;
      end if;

   end loop;

   if l_conts.count > 0 then
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');

      -- Free terminals for the container types actually on this truck.
      -- '~' is an unmatchable placeholder so an unused slot contributes nothing.
      apex_json.open_array('terminals');
      for i in (
         select distinct terminal
           from xxotm_position_master_t
          where is_occupied = 'N'
            and xxotm_position_master_t.location = v_location
            and lower(container_type) in ( lower(nvl(l_type_a, '~')),
                                           lower(nvl(l_type_b, '~')) )
          order by terminal
      ) loop
         apex_json.write(i.terminal);
      end loop;
      apex_json.close_array;

      -- Every container on the truck.
      apex_json.open_array('containers');
      for i in 1 .. l_conts.count loop
         apex_json.open_object;
         apex_json.write('shipment_nbr',   l_conts(i).shipment_xid);
         apex_json.write('container_nbr',  l_conts(i).container_nbr);
         apex_json.write('container_type', l_conts(i).container_type);
         apex_json.write('shipment_name',  l_conts(i).shipment_name);
         apex_json.write('remarks',        l_conts(i).remarks);
         apex_json.close_object;
      end loop;
      apex_json.close_array;

      -- Legacy flat fields, from the first container. The client prefers
      -- containers[] and only falls back to these when it is absent.
      apex_json.write(
         'shipment_nbr',
         l_conts(1).shipment_xid
      );
      apex_json.write(
         'container_nbr',
         l_conts(1).container_nbr
      );
      apex_json.write(
         'container_type',
         l_conts(1).container_type
      );
      apex_json.write(
         'shipment_name',
         l_conts(1).shipment_name
      );
      apex_json.write(
         'truck_nbr',
         l_truck_nbr
      );
      -- The client reads driver_name ?? driver_nbr, so both names work. Prod
      -- emitted the driver NAME under the key 'driver_nbr', which was simply
      -- mislabelled; it is emitted under both keys here so no consumer breaks.
      apex_json.write(
         'driver_name',
         l_driver_name
      );
      apex_json.write(
         'driver_nbr',
         l_driver_name
      );
      apex_json.write(
         'driver_iqama',
         l_driver_iqama
      );

      apex_json.close_object; -- Close data object
   else
      apex_json.write(
         'response_message',
         'No Data Found'
      );
      apex_json.write(
         'response_code',
         404
      );
   end if;

   apex_json.close_object; -- Close main object
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_position_truck_details;

   -- ========================================================================
   -- XX_OTM_POST_CUSTOMER_INVENTORY   [3d-high-risk / MANUAL]
   -- source: db/work/XX_OTM_POST_CUSTOMER_INVENTORY.sql   (full rationale is in that file)
   -- ========================================================================
  PROCEDURE XX_OTM_POST_CUSTOMER_INVENTORY (
   p_body    in blob,
   p_user_id in varchar2 default null
) as
   -- Declared bare, assigned after BEGIN: an exception raised while elaborating
   -- a declaration is not catchable by this block's own handler.
   v_location          varchar2(100);
   l_json_clob         clob;
   l_root_elem         json_element_t;
   l_shape             varchar2(20);
   l_flag              varchar2(50);
   l_count             number;
   l_final_clob        clob;

   -- One normalised row per (container, item), whatever shape arrived.
   type t_row is record (
      customer          varchar2(200),
      customer_nbr      varchar2(100),
      container_nbr     varchar2(100),
      shipment_nbr      varchar2(100),
      shipment_name     varchar2(100),
      direction         number,          -- +1 add, -1 deduct
      status_code       varchar2(100),   -- OTM event that closes the shipment
      item_code         varchar2(100),
      item_description  varchar2(500),
      cargo_description varchar2(500),
      hs_code           varchar2(50),
      gross_weight      number,
      net_weight        number,
      weight_uom        varchar2(20),
      volume            number,
      volume_uom        varchar2(20),
      un_class          varchar2(50),
      country_of_origin varchar2(50),
      quantity          number,
      quantity_uom      varchar2(20),
      rcvd_qty          number
   );
   type t_rows is
      table of t_row index by pls_integer;
   l_rows              t_rows;
   l_n                 pls_integer := 0;

   -- Deductions summed per stock key, so repeats in one payload are checked
   -- against their total rather than each passing on its own.
   type t_qty_by_key is
      table of number index by varchar2(400);
   l_required          t_qty_by_key;
   l_key               varchar2(400);

   l_hdr_count         number;
   l_item_count        number;
   l_available         number;
   l_ship_name         varchar2(100);

   -- Shipments that actually had a row written, and the OTM event that closes
   -- each one. Keyed by shipment so a payload spanning two shipments posts one
   -- event per shipment, not one per item -- the event is a property of the
   -- shipment, and posting it N times would record N operations in OTM.
   type t_code_by_ship is
      table of varchar2(100) index by varchar2(200);
   l_to_post           t_code_by_ship;
   l_ship_key          varchar2(200);
   -- CLOB, not VARCHAR2: post_otm_tracking_events declares x_response as
   -- OUT CLOB, and PL/SQL does not implicitly convert for an OUT parameter.
   l_api_response      clob;

   -- Validation failures, reported together rather than one at a time.
   type t_msg_list is
      table of varchar2(400);
   l_errors            t_msg_list := t_msg_list();

   -- Duplicate rows skipped by the CHECK branch.
   type t_index_list is
      table of number;
   l_failed_indices    t_index_list := t_index_list();

   e_row_locked exception;
   pragma exception_init(e_row_locked, -54);

   ---------------------------------------------------------------------------
   -- Append one normalised row. Shared by all three shapes so the field
   -- defaulting lives in exactly one place.
   ---------------------------------------------------------------------------
   procedure add_row (
      p_customer          in varchar2,
      p_customer_nbr      in varchar2,
      p_container_nbr     in varchar2,
      p_shipment_nbr      in varchar2,
      p_cargo_description in varchar2,
      p_item_code         in varchar2,
      p_item_description  in varchar2,
      p_hs_code           in varchar2,
      p_gross_weight      in number,
      p_net_weight        in number,
      p_weight_uom        in varchar2,
      p_volume            in number,
      p_volume_uom        in varchar2,
      p_un_class          in varchar2,
      p_country_of_origin in varchar2,
      p_quantity          in number,
      p_quantity_uom      in varchar2,
      p_rcvd_qty          in number
   ) is
   begin
      l_n := l_n + 1;
      l_rows(l_n).customer := p_customer;
      l_rows(l_n).customer_nbr := p_customer_nbr;
      l_rows(l_n).container_nbr := p_container_nbr;
      l_rows(l_n).shipment_nbr := p_shipment_nbr;
      l_rows(l_n).cargo_description := p_cargo_description;
      l_rows(l_n).item_code := p_item_code;
      l_rows(l_n).item_description := p_item_description;
      -- hs_code and item_code are distinct columns but the CMS derives
      -- item_code FROM the HS code, so either may be the one supplied.
      l_rows(l_n).hs_code := nvl(p_hs_code, p_item_code);
      l_rows(l_n).gross_weight := p_gross_weight;
      l_rows(l_n).net_weight := p_net_weight;
      l_rows(l_n).weight_uom := p_weight_uom;
      l_rows(l_n).volume := p_volume;
      l_rows(l_n).volume_uom := p_volume_uom;
      l_rows(l_n).un_class := p_un_class;
      l_rows(l_n).country_of_origin := p_country_of_origin;
      l_rows(l_n).quantity := p_quantity;
      l_rows(l_n).quantity_uom := p_quantity_uom;
      -- rcvd_qty drives the stock movement; absent, the ordered quantity is
      -- taken to have been received in full. Prod's behaviour, kept.
      l_rows(l_n).rcvd_qty := nvl(p_rcvd_qty, p_quantity);
   end add_row;

   ---------------------------------------------------------------------------
   -- Emit a response and finish. One exit point for every refusal so none of
   -- them can fall through into the write pass.
   ---------------------------------------------------------------------------
   procedure respond (
      p_code in number,
      p_msg  in varchar2
   ) is
   begin
      rollback;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         p_code
      );
      apex_json.write(
         'response_message',
         p_msg
      );
      if l_errors.count > 0 then
         apex_json.open_array('data');
         for j in 1..l_errors.count loop
            apex_json.open_object;
            apex_json.write(
               'detail',
               l_errors(j)
            );
            apex_json.close_object;
         end loop;
         apex_json.close_array;
      end if;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
   end respond;

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   l_json_clob := to_clob(p_body);

   -- =====================================================================
   -- PHASE 1 -- SHAPE DETECTION AND NORMALISATION
   -- =====================================================================
   -- Wrapped whole, so a payload this procedure cannot read comes back as a
   -- 400 naming the shape it thought it had -- see the handler at the end of
   -- this block.
   begin

   -- json_element_t, not apex_json: see the header note. Asking apex_json for
   -- a member name is exactly what fails on a root array.
   begin
      l_root_elem := json_element_t.parse(l_json_clob);
   exception
      when others then
         respond(
            400,
            'Request body is not valid JSON.'
         );
         return;
   end;

   apex_json.parse(l_json_clob);

   if l_root_elem.is_array then
      l_shape := 'ARRAY_ITEMS';                 -- [ { header, items:[...] } ]
   elsif treat(l_root_elem as json_object_t).has('data') then
      l_shape := 'FLAG_DATA';                   -- { flag, data:[ rows ] }
   else
      l_shape := 'OBJECT_ITEMS';                -- { header, items:[...] }
   end if;

   -- The flag is read from ANY object root, not just the flag/data shape.
   --
   -- It travels with the CMS single-entry payload too -- that client posts
   -- {header, items:[...], flag:'CHECK'} and then re-posts the same body with
   -- flag:'INSERT' when the operator confirms a duplicate. Reading it only for
   -- FLAG_DATA pinned that client to CHECK for ever: the confirmation would
   -- skip the duplicate a second time and appear to do nothing.
   --
   -- A root ARRAY carries no flag -- there is nowhere to put one -- so it is not
   -- consulted there; asking apex_json for a member of an array root is the
   -- supertype/subtype error this procedure exists to avoid.
   if l_shape != 'ARRAY_ITEMS' then
      l_flag := upper(apex_json.get_varchar2('flag'));
   end if;

   -- Anything unrecognised falls to CHECK, the non-destructive branch. Only an
   -- explicit INSERT skips duplicate detection.
   if l_flag is null or l_flag not in ( 'CHECK', 'INSERT' ) then
      l_flag := 'CHECK';
   end if;

   if l_shape = 'FLAG_DATA' then
      -- Each element is already one item, with the header repeated on it.
      l_hdr_count := nvl(apex_json.get_count('data'), 0);
      for i in 1..l_hdr_count loop
         add_row(
            p_customer          => nvl(apex_json.get_varchar2('data[%d].customer', i),
                                       apex_json.get_varchar2('data[%d].customer_name', i)),
            p_customer_nbr      => apex_json.get_varchar2('data[%d].customer_nbr', i),
            p_container_nbr     => apex_json.get_varchar2('data[%d].container_nbr', i),
            p_shipment_nbr      => apex_json.get_varchar2('data[%d].shipment_nbr', i),
            p_cargo_description => apex_json.get_varchar2('data[%d].cargo_description', i),
            p_item_code         => apex_json.get_varchar2('data[%d].item_code', i),
            p_item_description  => apex_json.get_varchar2('data[%d].item_description', i),
            p_hs_code           => apex_json.get_varchar2('data[%d].hs_code', i),
            p_gross_weight      => apex_json.get_number('data[%d].gross_weight', i),
            p_net_weight        => apex_json.get_number('data[%d].net_weight', i),
            p_weight_uom        => apex_json.get_varchar2('data[%d].weight_uom', i),
            p_volume            => apex_json.get_number('data[%d].volume', i),
            p_volume_uom        => apex_json.get_varchar2('data[%d].volume_uom', i),
            p_un_class          => apex_json.get_varchar2('data[%d].un_class', i),
            p_country_of_origin => apex_json.get_varchar2('data[%d].country_of_origin', i),
            p_quantity          => apex_json.get_number('data[%d].quantity', i),
            p_quantity_uom      => apex_json.get_varchar2('data[%d].quantity_uom', i),
            p_rcvd_qty          => apex_json.get_number('data[%d].rcvd_qty', i)
         );
      end loop;

   elsif l_shape = 'ARRAY_ITEMS' then
      -- Root array of headers, each with nested items. The CMS bulk upload.
      -- Key case matches the client exactly: HS_Code and UN_Class are sent
      -- capitalised, and apex_json paths are case sensitive.
      l_hdr_count := nvl(apex_json.get_count('.'), 0);
      for h in 1..l_hdr_count loop
         l_item_count := nvl(apex_json.get_count('[%d].items', h), 0);
         for i in 1..l_item_count loop
            add_row(
               p_customer          => apex_json.get_varchar2('[%d].customer_name', h),
               p_customer_nbr      => apex_json.get_varchar2('[%d].customer_nbr', h),
               p_container_nbr     => apex_json.get_varchar2('[%d].container_nbr', h),
               p_shipment_nbr      => apex_json.get_varchar2('[%d].shipment_nbr', h),
               p_cargo_description => apex_json.get_varchar2('[%d].cargo_description', h),
               p_item_code         => apex_json.get_varchar2('[%d].items[%d].item_code', h, i),
               p_item_description  => apex_json.get_varchar2('[%d].items[%d].item_description', h, i),
               p_hs_code           => apex_json.get_varchar2('[%d].HS_Code', h),
               p_gross_weight      => apex_json.get_number('[%d].items[%d].gross_weight', h, i),
               p_net_weight        => apex_json.get_number('[%d].items[%d].net_weight', h, i),
               p_weight_uom        => apex_json.get_varchar2('[%d].items[%d].weight_uom', h, i),
               p_volume            => apex_json.get_number('[%d].items[%d].volume', h, i),
               p_volume_uom        => apex_json.get_varchar2('[%d].items[%d].volume_uom', h, i),
               p_un_class          => apex_json.get_varchar2('[%d].items[%d].UN_Class', h, i),
               p_country_of_origin => apex_json.get_varchar2('[%d].items[%d].country_of_origin', h, i),
               p_quantity          => apex_json.get_number('[%d].items[%d].quantity', h, i),
               p_quantity_uom      => apex_json.get_varchar2('[%d].items[%d].quantity_uom', h, i),
               p_rcvd_qty          => apex_json.get_number('[%d].items[%d].rcvd_quantity', h, i)
            );
         end loop;
      end loop;

   else
      -- Single header with nested items. The CMS single-entry form.
      l_item_count := nvl(apex_json.get_count('items'), 0);
      for i in 1..l_item_count loop
         add_row(
            p_customer          => apex_json.get_varchar2('customer_name'),
            p_customer_nbr      => apex_json.get_varchar2('customer_nbr'),
            p_container_nbr     => apex_json.get_varchar2('container_nbr'),
            p_shipment_nbr      => apex_json.get_varchar2('shipment_nbr'),
            p_cargo_description => apex_json.get_varchar2('cargo_description'),
            p_item_code         => apex_json.get_varchar2('items[%d].item_code', i),
            p_item_description  => apex_json.get_varchar2('items[%d].item_description', i),
            p_hs_code           => apex_json.get_varchar2('HS_Code'),
            p_gross_weight      => apex_json.get_number('items[%d].gross_weight', i),
            p_net_weight        => apex_json.get_number('items[%d].net_weight', i),
            p_weight_uom        => apex_json.get_varchar2('items[%d].weight_uom', i),
            p_volume            => apex_json.get_number('items[%d].volume', i),
            p_volume_uom        => apex_json.get_varchar2('items[%d].volume_uom', i),
            p_un_class          => apex_json.get_varchar2('items[%d].UN_Class', i),
            p_country_of_origin => apex_json.get_varchar2('items[%d].country_of_origin', i),
            p_quantity          => apex_json.get_number('items[%d].quantity', i),
            p_quantity_uom      => apex_json.get_varchar2('items[%d].quantity_uom', i),
            p_rcvd_qty          => apex_json.get_number('items[%d].rcvd_quantity', i)
         );
      end loop;
   end if;

   if l_rows.count = 0 then
      respond(
         400,
         'No inventory items found in the request.'
      );
      return;
   end if;

   exception
      when others then
         -- Any failure reading the payload is a BAD REQUEST, reported with the
         -- shape that was detected and the Oracle error, not an ORDS-25001 with
         -- a raw PL/SQL stack. Nothing has been written at this point -- the
         -- first INSERT is in pass 2 -- so there is nothing to undo.
         --
         -- apex_json raises ORA-06502 "cannot assign supertype instance to
         -- subtype" whenever a path is read against a node of the wrong kind:
         -- a member name against an array, or an index against an object. That
         -- is a client contract problem and has to reach the client as one.
         respond(
            400,
            'Could not read the request body (detected shape: '
            || nvl(l_shape, 'UNKNOWN') || '). ' || sqlerrm
         );
         return;
   end;

   -- =====================================================================
   -- PASS 1 -- RESOLVE DIRECTION, LOCK STOCK, VALIDATE. Writes nothing.
   -- =====================================================================
   for i in 1..l_rows.count loop

      if l_rows(i).item_code is null or l_rows(i).shipment_nbr is null then
         l_errors.extend;
         l_errors(l_errors.count) :=
            'Row ' || i || ': shipment_nbr and item_code are both required.';
         goto next_validation;
      end if;

      -- Direction comes from the shipment, never from the payload.
      -- Both forms of the id are accepted because the sync writes the prefixed
      -- one and clients send the bare one -- the same pair XX_OTM_SUBMIT_GATE_OUT
      -- matches on.
      begin
         select upper(trim(shipment_name))
           into l_ship_name
           from xxotm_shipments_t
          where shipment_xid in ( l_rows(i).shipment_nbr,
                                  'NAQLEEN.' || l_rows(i).shipment_nbr )
            and xxotm_shipments_t.location = v_location
          fetch first 1 rows only;
      exception
         when no_data_found then
            l_ship_name := null;
      end;

      if l_ship_name is null then
         l_errors.extend;
         l_errors(l_errors.count) :=
            'Shipment ' || l_rows(i).shipment_nbr
            || ' was not found at this location.';
         goto next_validation;
      end if;

      l_rows(i).shipment_name := l_ship_name;
      l_rows(i).direction :=
         case
            when l_ship_name in ( 'DESTUFFING',
                                  'OFFLOADING_LCL',
                                  'STORE_AS_IT_IS' ) then
               1
            when l_ship_name in ( 'STUFFING',
                                  'LOADING_LCL' ) then
               -1
            else null
         end;

      -- The event that CLOSES the shipment, identical to the one its
      -- truck-based counterpart posts. Without it the shipment stays in
      -- TRIP_STARTED, keeps appearing in the lookup, and the same movement can
      -- be recorded again -- see the header note.
      --
      -- STORE_AS_IT_IS is deliberately null: it has no truck-based counterpart
      -- and therefore no established status code, and inventing one would put a
      -- value into OTM that nothing else in this system writes or reads.
      l_rows(i).status_code :=
         case l_ship_name
            when 'DESTUFFING'     then 'NAQLEEN.DESTUFFED'
            when 'OFFLOADING_LCL' then 'NAQLEEN.DESTUFFED'
            when 'STUFFING'       then 'NAQLEEN.STUFFED'
            when 'LOADING_LCL'    then 'NAQLEEN.STUFFED'
            else null
         end;

      if l_rows(i).direction is null then
         -- Refused rather than defaulted. Adding on an unknown type is how the
         -- old body turned every STUFFING into a stock increase.
         l_errors.extend;
         l_errors(l_errors.count) :=
            'Shipment ' || l_rows(i).shipment_nbr || ' is of type '
            || l_ship_name || ', which has no defined stock movement.';
         goto next_validation;
      end if;

      if nvl(l_rows(i).rcvd_qty, 0) <= 0 then
         l_errors.extend;
         l_errors(l_errors.count) :=
            'Item ' || l_rows(i).item_code || ': quantity must be greater than zero.';
         goto next_validation;
      end if;

      -- Lock the stock row now, in pass 1, so the quantity checked below is
      -- still the quantity present when pass 2 applies the movement.
      begin
         select nvl(available_qty, 0)
           into l_available
           from xxotm_customer_stock_t
          where cust_nbr = l_rows(i).customer_nbr
            and item_code = l_rows(i).item_code
            and xxotm_customer_stock_t.location = v_location
            for update nowait;
      exception
         when no_data_found then
            l_available := null;         -- no row yet; only an add may proceed
         when e_row_locked then
            respond(
               409,
               'Stock for item ' || l_rows(i).item_code
               || ' is being updated by another operation. Try again in a moment.'
            );
            return;
      end;

      if l_rows(i).direction = -1 then
         -- Sum repeats before comparing: two lines of 6 against a stock of 10
         -- must fail as 12, not pass twice as 6.
         l_key := l_rows(i).customer_nbr || '|' || l_rows(i).item_code;
         l_required(l_key) := nvl(l_required(l_key), 0) + l_rows(i).rcvd_qty;

         if l_available is null then
            l_errors.extend;
            l_errors(l_errors.count) :=
               'Item ' || l_rows(i).item_code || ': no stock held for this customer at '
               || 'this location, so ' || l_rows(i).rcvd_qty || ' cannot be removed.';
         elsif l_available < l_required(l_key) then
            l_errors.extend;
            l_errors(l_errors.count) :=
               'Item ' || l_rows(i).item_code || ': insufficient stock. Available '
               || l_available || ', requested ' || l_required(l_key)
               || ', short by ' || ( l_required(l_key) - l_available ) || '.';
         end if;
      end if;

      <<next_validation>>
      null;
   end loop;

   if l_errors.count > 0 then
      respond(
         409,
         'Request rejected: ' || l_errors.count || ' item(s) could not be processed.'
      );
      return;
   end if;

   -- =====================================================================
   -- PASS 2 -- WRITE. Every row is known good and its stock row is locked.
   -- =====================================================================
   for i in 1..l_rows.count loop

      if l_flag = 'CHECK' then
         select count(*)
           into l_count
           from xxotm_customer_inventory_t
          where cust_name = l_rows(i).customer
            and container_nbr = l_rows(i).container_nbr
            and shipment_nbr = l_rows(i).shipment_nbr
            and item_code = l_rows(i).item_code
            and item_description = l_rows(i).item_description
            and xxotm_customer_inventory_t.location = v_location;

         if l_count > 0 then
            -- Duplicate: skip the row entirely. Reported below, and no stock
            -- moves for it -- recording the same receipt twice would otherwise
            -- double the customer's stock.
            l_failed_indices.extend;
            l_failed_indices(l_failed_indices.count) := i;
            goto next_write;
         end if;
      end if;

      insert into xxotm_customer_inventory_t (
         cust_name,
         cust_nbr,
         container_nbr,
         shipment_nbr,
         item_code,
         item_description,
         cargo_description,
         hs_code,
         gross_weight,
         net_weight,
         weight_uom,
         volume,
         volume_uom,
         un_class,
         country_of_origin,
         qty,
         qty_uom,
         rcvd_qty,
         creation_date,
         location
      ) values ( l_rows(i).customer,
                 l_rows(i).customer_nbr,
                 l_rows(i).container_nbr,
                 l_rows(i).shipment_nbr,
                 l_rows(i).item_code,
                 l_rows(i).item_description,
                 l_rows(i).cargo_description,
                 l_rows(i).hs_code,
                 l_rows(i).gross_weight,
                 l_rows(i).net_weight,
                 l_rows(i).weight_uom,
                 l_rows(i).volume,
                 l_rows(i).volume_uom,
                 l_rows(i).un_class,
                 l_rows(i).country_of_origin,
                 l_rows(i).quantity,
                 l_rows(i).quantity_uom,
                 l_rows(i).rcvd_qty,
                 sysdate,
                 v_location );

      -- Stock movement, signed. Update first and insert only if no row was
      -- touched -- the same order XX_OTM_POST_DESTUFFING_CONTAINER uses.
      update xxotm_customer_stock_t
         set available_qty = nvl(available_qty, 0)
                             + ( l_rows(i).direction * l_rows(i).rcvd_qty )
       where cust_nbr = l_rows(i).customer_nbr
         and item_code = l_rows(i).item_code
         and xxotm_customer_stock_t.location = v_location;

      if sql%rowcount = 0 then
         -- Only reachable on an add: pass 1 refuses a deduct with no stock row.
         insert into xxotm_customer_stock_t (
            cust_name,
            cust_nbr,
            item_code,
            item_description,
            available_qty,
            qty_uom,
            net_weight,
            weight_uom,
            location
         ) values ( l_rows(i).customer,
                    l_rows(i).customer_nbr,
                    l_rows(i).item_code,
                    l_rows(i).item_description,
                    l_rows(i).rcvd_qty,
                    l_rows(i).quantity_uom,
                    l_rows(i).net_weight,
                    l_rows(i).weight_uom,
                    v_location );
      end if;

      -- Recorded only after a row actually landed. A shipment whose every row
      -- was skipped as a duplicate must NOT be closed -- nothing happened to it
      -- on this request.
      if l_rows(i).status_code is not null then
         l_to_post(l_rows(i).shipment_nbr) := l_rows(i).status_code;
      end if;

      <<next_write>>
      null;
   end loop;

   -- =====================================================================
   -- PASS 3 -- CLOSE THE SHIPMENTS IN OTM
   -- =====================================================================
   -- This is what the four truck-based procedures do and this one did not.
   -- The lookup that feeds this screen filters on
   -- statuses.statusValueGid in (TRIP_STARTED, TRIP_NOT_STARTED), so a shipment
   -- that is never advanced stays selectable for ever and the same stock
   -- movement can be applied repeatedly.
   --
   -- LAST, and fail-closed. The OTM event cannot be recalled, so it is posted
   -- only once every local write has succeeded; and if OTM rejects it the whole
   -- request is rolled back, because a movement recorded locally under a
   -- shipment OTM still believes is open is the state this pass exists to
   -- prevent. Same call as XX_OTM_POST_DESTUFFING_CONTAINER, which also treats
   -- a rejected event as a 500.
   --
   -- Nothing is committed before this point: the two INSERTs above and this
   -- pass land together or not at all.
   l_ship_key := l_to_post.first;
   while l_ship_key is not null loop
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_CUSTOMER_INVENTORY',
         p_statuscodegid    => l_to_post(l_ship_key),
         p_shipmentxid      => l_ship_key,
         x_response         => l_api_response
      );

      if l_api_response like '%Error%' then
         l_errors.extend;
         l_errors(l_errors.count) := substr(l_api_response, 1, 380);
         respond(
            500,
            'Stock was not updated: OTM rejected the '
            || l_to_post(l_ship_key) || ' event for shipment ' || l_ship_key || '.'
         );
         return;
      end if;

      l_ship_key := l_to_post.next(l_ship_key);
   end loop;

   -- =====================================================================
   -- RESPONSE
   -- =====================================================================
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_failed_indices.count = 0 then
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
   else
      -- Duplicates. Code 500 is kept because the CMS confirm-then-force-insert
      -- flow keys on "not 200" and re-posts with flag=INSERT; changing it to a
      -- 409 here would need that client changed in the same release.
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Duplicate records found'
      );
      apex_json.open_array('data');
      for j in 1..l_failed_indices.count loop
         declare
            idx pls_integer := l_failed_indices(j);
         begin
            apex_json.open_object;
            apex_json.write(
               'container_nbr',
               l_rows(idx).container_nbr
            );
            apex_json.write(
               'shipment_nbr',
               l_rows(idx).shipment_nbr
            );
            apex_json.write(
               'item_description',
               l_rows(idx).item_description
            );
            apex_json.write(
               'item_code',
               l_rows(idx).item_code
            );
            apex_json.close_object;
         end;
      end loop;
      apex_json.close_array;
   end if;
   apex_json.close_object;

   l_final_clob := apex_json.get_clob_output;

   -- Chunked output: the duplicate list can exceed the 32k htp.prn limit.
   declare
      l_offset number := 1;
      l_amount number := 32000;
      l_len    number;
      l_buffer varchar2(32767);
   begin
      if l_final_clob is not null then
         l_len := dbms_lob.getlength(l_final_clob);
         while l_offset <= l_len loop
            dbms_lob.read(
               l_final_clob,
               l_amount,
               l_offset,
               l_buffer
            );
            htp.prn(l_buffer);
            l_offset := l_offset + l_amount;
         end loop;
      end if;
   end;

   apex_json.free_output;
exception
   when others then
      -- Nothing partial survives a failure: the inventory row and the stock
      -- movement have to land together or not at all.
      rollback;
      begin
         apex_json.free_output;
      exception
         when others then
            null;
      end;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_customer_inventory;

   -- ========================================================================
   -- XX_OTM_POST_DELETE_ORDER   [3b-prod-forward / TAKE-PROD]
   -- source: db/work/XX_OTM_POST_DELETE_ORDER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_delete_order (
   p_body in blob
)
as
   l_order_id   varchar2(100);
   l_json_obj   json_object_t;
   l_xml        xmltype;
   l_delete_log clob;

   -- Variables for safe BLOB to CLOB conversion
   l_clob        clob;
   l_dest_offset integer := 1;
   l_src_offset  integer := 1;
   l_lang_ctx    integer := dbms_lob.default_lang_ctx;
   l_warning     integer;

   -- Variables for substring fallback
   l_start_pos integer;
   l_xid_start integer;
   l_xid_end   integer;
begin
   -- Attempt 1: Parse as JSON
   begin
      l_json_obj := json_object_t.parse(p_body);
      if l_json_obj.has('orderId') then
         l_order_id := l_json_obj.get_string('orderId');
      elsif l_json_obj.has('order_id') then
         l_order_id := l_json_obj.get_string('order_id');
      end if;
   exception
      when others then
         l_order_id := null;
   end;

   -- Attempt 2: Safely convert BLOB to CLOB and parse
   if l_order_id is null then
      begin
         dbms_lob.createtemporary(l_clob, true);
         
         dbms_lob.converttoclob(
            dest_lob     => l_clob,
            src_blob     => p_body,
            amount       => dbms_lob.lobmaxsize,
            dest_offset  => l_dest_offset,
            src_offset   => l_src_offset,
            blob_csid    => nls_charset_id('AL32UTF8'), -- Explicitly force UTF8 instead of DB default
            lang_context => l_lang_ctx,
            warning      => l_warning
         );
         
         -- Attempt 2A: Full XML Parsing with explicit Namespaces
         begin
            l_xml := xmltype(l_clob);
            
            select x.xid
              into l_order_id
              from xmltable(
                 xmlnamespaces(
                    default 'http://xmlns.oracle.com/apps/otm/transmission/v6.4',
                    'http://xmlns.oracle.com/apps/otm/transmission/v6.4' as otm
                 ),
                 '//otm:Release/otm:ReleaseGid/otm:Gid'
                 passing l_xml
                 columns xid varchar2(100) path 'otm:Xid'
              ) x
             where rownum = 1;
         exception
            when others then
               l_order_id := null;
         end;
         
         -- Attempt 2B: Bulletproof INSTR/SUBSTR fallback if XML parsing fails due to schema quirks
         if l_order_id is null then
            -- Find the start of the ReleaseGid tag
            l_start_pos := dbms_lob.instr(l_clob, 'ReleaseGid>');
            if l_start_pos > 0 then
               -- Look for the Xid tag immediately after ReleaseGid
               l_xid_start := dbms_lob.instr(l_clob, 'Xid>', l_start_pos);
               if l_xid_start > 0 then
                  l_xid_start := l_xid_start + 4; -- Move past Xid> text
                  l_xid_end := dbms_lob.instr(l_clob, '</', l_xid_start);
                  if l_xid_end > l_xid_start then
                     -- Extract exactly what is inside the tag
                     l_order_id := dbms_lob.substr(l_clob, l_xid_end - l_xid_start, l_xid_start);
                  end if;
               end if;
            end if;
         end if;
         
         if l_clob is not null then
            dbms_lob.freetemporary(l_clob);
         end if;
         
      exception
         when others then
            if l_clob is not null then
               dbms_lob.freetemporary(l_clob);
            end if;
            l_order_id := null;
      end;
   end if;

   -- Trigger the staging cleanup if we successfully fetched an order_id
   if l_order_id is not null then
      xx_otm_delete_shipment_from_staging(
        p_shipment_nbr => null,
         p_order_id => l_order_id, 
         x_log      => l_delete_log
      );
   else
      l_delete_log := 'Failed to extract order_id from payload.';
   end if;

   -- Log the request
   insert into xx_otm_deleted_orders_log (
      order_id,
      payload,
      created_by,
      delete_logs
   ) values ( 
      l_order_id,
      p_body,
      'API_USER',
      l_delete_log
   );
   
   commit;

   -- Return a success response, clearly outputting the state of the order_id
   htp.p('{"status": "success", "message": "Delete request logged and staging data cleared", "extracted_order_id": "' || nvl(l_order_id, 'NOT_FOUND') || '"}');

exception
   when others then
      -- rollback;
      -- Log the error (optional, could write to a general error log)
      raise;
end xx_otm_post_delete_order;

   -- ========================================================================
   -- XX_OTM_POST_DESTUFFING_CONTAINER   [3d-high-risk / TAKE-TEST + prod fixes]
   -- source: db/work/XX_OTM_POST_DESTUFFING_CONTAINER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_destuffing_container (
   payload   in blob,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
is
   -- =====================================================
   -- Response & Logging Variables
   -- =====================================================
   l_response_code       NUMBER := 200;
   l_response_msg        VARCHAR2(4000) := 'Success';
   l_validation_errors   VARCHAR2(4000);
   -- Declared bare, assigned after BEGIN. As an initialiser a failure here would
   -- escape this block's own handler and ORDS would return a raw Oracle stack
   -- instead of the JSON envelope.
   v_location            VARCHAR2(100);

   -- ORA-00054, restored per the merge decision. Test caught lock contention
   -- with WHEN OTHERS, which also reports genuine defects to the operator as
   -- "another operation is updating this stock". Naming it keeps 409 for real
   -- contention and sends everything else to the 500 handler.
   e_row_locked          EXCEPTION;
   PRAGMA EXCEPTION_INIT(e_row_locked, -54);

   -- JSON parsing
   l_clob                CLOB;
   l_values              APEX_JSON.T_VALUES;
   l_dest_offset         INTEGER := 1;
   l_src_offset          INTEGER := 1;
   l_lang_context        INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
   l_warning             INTEGER;

   -- Top-level fields
   l_container_number    VARCHAR2(50);
   l_customer            VARCHAR2(100);
   l_shipment_number     VARCHAR2(100);
   l_seal_number         VARCHAR2(100);
   
   -- Position fields
   l_current_position    VARCHAR2(100);
   l_restacking_shipment VARCHAR2(100);
   l_blocking_container  VARCHAR2(100);
   v_curr_level_num      NUMBER;
   
   -- Item Collection
   l_item_count          PLS_INTEGER;
   l_items_updated       NUMBER := 0;
   l_events_posted       NUMBER := 0;
   
   TYPE t_item_rec IS RECORD (
      item_code         VARCHAR2(50),
      rcvd_quantity     NUMBER,
      cust_name         VARCHAR2(1000),
      item_desc         VARCHAR2(1000),
      qty_uom           VARCHAR2(100),
      weight_uom        VARCHAR2(100),
      net_weight        NUMBER,
      exists_in_inv     BOOLEAN := FALSE
   );
   TYPE t_item_tab IS TABLE OF t_item_rec INDEX BY BINARY_INTEGER;
   l_items t_item_tab;

   -- Network Response
   l_api_response        CLOB;
   l_dummy               NUMBER;

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- =====================================================
   -- PHASE 1: PARSE, VALIDATE, PRE-FETCH & LOCK
   -- =====================================================
   
   -- 1. JSON Parse Payload
   IF payload IS NULL THEN
      l_response_code := 400; l_response_msg := 'Empty request body';
      GOTO build_response;
   END IF;

   DBMS_LOB.CREATETEMPORARY(l_clob, TRUE);
   DBMS_LOB.CONVERTTOCLOB(
      dest_lob => l_clob, src_blob => payload, amount => DBMS_LOB.GETLENGTH(payload),
      dest_offset => l_dest_offset, src_offset => l_src_offset, 
      blob_csid => DBMS_LOB.DEFAULT_CSID, lang_context => l_lang_context, warning => l_warning
   );

   BEGIN
      APEX_JSON.PARSE(p_values => l_values, p_source => l_clob);
   EXCEPTION
      WHEN OTHERS THEN
         l_response_code := 400; l_response_msg := 'Invalid JSON payload';
         GOTO cleanup_and_respond;
   END;

   l_container_number := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'container_nbr');
   l_shipment_number  := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'shipment_nbr');
   l_customer         := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'customer_nbr');
   l_seal_number      := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'seal_nbr');

   IF l_container_number IS NULL THEN
      BEGIN
         SELECT container_nbr INTO l_container_number
         FROM   xxotm_container_inventory_t
         WHERE  inbound_shipment_nbr = l_shipment_number AND ROWNUM = 1
         and xxotm_container_inventory_t.location = v_location;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN NULL;
      END;
   END IF;
   
   IF l_container_number IS NULL THEN
       l_response_code := 400; l_response_msg := 'Unable to find correlated container number.';
       GOTO cleanup_and_respond;
   END IF;

   -- 2. Setup Stacking Validation Data Extracts
   BEGIN
      SELECT position, inbound_shipment_nbr INTO l_current_position, l_restacking_shipment
      FROM   xxotm_container_inventory_t
      WHERE  container_nbr = l_container_number
      AND    container_stored_time IS NOT NULL AND container_released_time IS NULL
      AND    xxotm_container_inventory_t.location = v_location AND ROWNUM = 1;
   EXCEPTION
      WHEN NO_DATA_FOUND THEN l_current_position := NULL;
   END;

   IF l_current_position IS NULL THEN
      BEGIN
         SELECT TERMINAL||'-'||BLOCK||'-'||LOT_NO||'-'||ROW_NO ||'-'||LEVEL_NO INTO l_current_position
         FROM   XXOTM_POSITION_MASTER_T
         WHERE  container_nbr = l_container_number AND ROWNUM = 1
         and xxotm_position_master_t.location = v_location;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN l_current_position := NULL;
      END;
   END IF;

   -- 3. Stacking Block Validation Check
   IF l_current_position IS NOT NULL AND l_current_position != 'CFS' THEN
      v_curr_level_num := TO_NUMBER(NVL(REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 5), '6'));

      IF v_curr_level_num < 6 THEN
         FOR check_level IN (v_curr_level_num + 1)..6 LOOP
            BEGIN
               SELECT container_nbr INTO l_blocking_container
               FROM   xxotm_container_inventory_t
               WHERE  position = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 1) || '-' ||
                                 REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 2) || '-' ||
                                 REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 3) || '-' ||
                                 REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 4) || '-' || TO_CHAR(check_level)
               AND    container_stored_time IS NOT NULL AND container_released_time IS NULL
               AND    xxotm_container_inventory_t.location = v_location AND ROWNUM = 1;
               
               IF l_blocking_container IS NOT NULL THEN
                  l_response_code := 400;
                  -- Prod's exact wording, restored. This string is what the app
                  -- puts in front of the operator, and it tells them what to do
                  -- next; test's terser "Blocked by ..." does not.
                  l_response_msg  := 'Cannot destuff container ' || l_container_number
                                     || '. Container ' || l_blocking_container
                                     || ' is stacked above at level ' || check_level
                                     || '. Please restack the container above first.';
                  l_validation_errors := 'Stacking Validation Failure';
                  GOTO cleanup_and_respond;
               END IF;
            EXCEPTION
               WHEN NO_DATA_FOUND THEN NULL;
            END;
         END LOOP;
      END IF;
   END IF;

   -- 4. Process Item List & Lock Customer Stock (Race Condition Proofing)
   l_item_count := NVL(APEX_JSON.GET_COUNT(p_values => l_values, p_path => 'items'), 0);
   
   FOR i IN 1..l_item_count LOOP
      l_items(i).item_code     := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'items[%d].item_code', p0 => i);
      l_items(i).rcvd_quantity := NVL(APEX_JSON.GET_NUMBER(p_values => l_values, p_path => 'items[%d].rcvd_quantity', p0 => i), 0);
      
      -- RACE CONDITION LOCK: Prevent concurrent operations overwriting exact stock entries
      BEGIN
         SELECT 1 INTO l_dummy 
         FROM   xxotm_customer_stock_t 
         WHERE  cust_nbr = l_customer AND item_code = l_items(i).item_code AND xxotm_customer_stock_t.location = v_location
         FOR UPDATE NOWAIT;
      EXCEPTION 
         WHEN NO_DATA_FOUND THEN NULL; -- Fully acceptable, handled via Insert in Phase 3
         WHEN e_row_locked THEN
            l_response_code := 409;
            l_response_msg := 'Stock record for item ' || l_items(i).item_code || ' is locked. Another operation is updating this stock.';
            GOTO cleanup_and_respond;
      END;

      -- Validate existence against Customer Inventory & Extract properties
      BEGIN
         SELECT cust_name, item_description, qty_uom, weight_uom, to_number(net_weight)
         INTO   l_items(i).cust_name, l_items(i).item_desc, l_items(i).qty_uom, l_items(i).weight_uom, l_items(i).net_weight
         FROM   xxotm_customer_inventory_t
         WHERE  shipment_nbr = l_shipment_number
         AND    item_code = l_items(i).item_code
         AND    xxotm_customer_inventory_t.location = v_location AND ROWNUM = 1;
         
         l_items(i).exists_in_inv := TRUE;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            l_items(i).exists_in_inv := FALSE;
      END;
   END LOOP;


   -- =====================================================
   -- PHASE 2: OTM CLOUD NETWORK APIS
   -- =====================================================
   
   -- API Call 1: Post DESTUFFED event
   post_otm_tracking_events(
      p_integration_name => 'XX_OTM_POST_DESTUFFING_CONTAINER',
      p_statuscodegid    => 'NAQLEEN.DESTUFFED',
      p_shipmentxid      => l_shipment_number,
      p_attribute2       => l_seal_number,
      x_response         => l_api_response
   );

   IF l_api_response LIKE '%Error%' THEN
      l_response_code := 500;
      l_response_msg  := 'Failed communicating with OTM. DESTUFFED event rejected.';
      l_validation_errors := SUBSTR(l_api_response, 1, 250);
      GOTO cleanup_and_respond;
   END IF;
   l_events_posted := l_events_posted + 1;

   -- API Call 2: Post Restack event logically tracking displacement to CFS 
   post_otm_tracking_events(
      p_integration_name => 'XX_OTM_RESTACK_CONTAINER',
      p_statuscodegid    => 'NAQLEEN.CONTAINER_RESTACKED',
      p_shipmentxid      => l_restacking_shipment,
      p_attribute1       => 'CFS',
      x_response         => l_api_response
   );

   IF l_api_response LIKE '%Error%' THEN
      l_response_code := 500;
      l_response_msg  := 'Failed communicating with OTM. RESTACKED event rejected.';
      l_validation_errors := SUBSTR(l_api_response, 1, 250);
      GOTO cleanup_and_respond;
   END IF;
   l_events_posted := l_events_posted + 1;


   -- =====================================================
   -- PHASE 3: DATABASE EXECUTION
   -- (Totally safe to commit, network succeeded)
   -- =====================================================

   -- 1. Process local Inventory and Master Stock Records
   FOR i IN 1..l_item_count LOOP
      IF l_items(i).exists_in_inv THEN
         
         UPDATE xxotm_customer_inventory_t
         SET    rcvd_qty = l_items(i).rcvd_quantity
         WHERE  shipment_nbr = l_shipment_number
         AND    item_code = l_items(i).item_code AND xxotm_customer_inventory_t.location = v_location;
         
         IF SQL%ROWCOUNT > 0 THEN
            l_items_updated := l_items_updated + 1;
            
            -- Increment Stock
            UPDATE xxotm_customer_stock_t
            SET    available_qty = NVL(available_qty, 0) + l_items(i).rcvd_quantity
            WHERE  cust_nbr = l_customer AND item_code = l_items(i).item_code AND xxotm_customer_stock_t.location = v_location;
            
            -- Insert if stock doesn't physically exist for this customer yet
            IF SQL%ROWCOUNT = 0 THEN
               INSERT INTO xxotm_customer_stock_t (
                  cust_nbr, cust_name, item_code, item_description, available_qty, qty_uom, weight_uom, net_weight, location
               ) VALUES (
                  l_customer, l_items(i).cust_name, l_items(i).item_code, l_items(i).item_desc,
                  l_items(i).rcvd_quantity, l_items(i).qty_uom, l_items(i).weight_uom, l_items(i).net_weight, v_location
               );
            END IF;
         END IF;
      END IF;
   END LOOP;

   -- 2. Mark Container directly within the CFS physical zones 
   SELECT COUNT(1) INTO l_dummy
   FROM   xxotm_cfs_containers_t
   WHERE  shipment_nbr = l_shipment_number AND container_nbr = l_container_number AND xxotm_cfs_containers_t.location = v_location;
   
   IF l_dummy = 0 THEN
      INSERT INTO xxotm_cfs_containers_t (
         shipment_nbr, container_nbr, creation_date, location
      ) VALUES (
         l_shipment_number, l_container_number, TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'), v_location
      );
   END IF;
   
   -- 3. Free up prior Slot Position Matrix
   IF l_current_position IS NOT NULL AND l_current_position != 'CFS' THEN
      UPDATE xxotm_position_master_t
      SET    is_occupied = 'N', shipment_nbr = NULL, container_nbr = NULL, LAST_EVENT_TIME = systimestamp
      WHERE  terminal = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 1)
      AND    block    = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 2)
      AND    lot_no   = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 3)
      AND    row_no   = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 4)
      AND    level_no = REGEXP_SUBSTR(l_current_position, '[^-]+', 1, 5)
      and xxotm_position_master_t.location = v_location;
      
      IF SQL%ROWCOUNT > 0 THEN 
         INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id) 
         VALUES ('XX_OTM_POST_DESTUFFING_CONTAINER', 'INFO', 'Freed slot: ' || l_current_position || ' for ' || l_container_number, l_restacking_shipment);
      END IF;
   END IF;

   -- 4. Set current inventory logical location flag to CFS
   UPDATE xxotm_container_inventory_t 
   SET    position = 'CFS'
   WHERE  container_nbr = l_container_number AND inbound_shipment_nbr = l_restacking_shipment
   AND    container_stored_time IS NOT NULL AND container_released_time IS NULL
   AND    xxotm_container_inventory_t.location = v_location;
   
   IF SQL%ROWCOUNT > 0 THEN 
      INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id) 
      VALUES ('XX_OTM_POST_DESTUFFING_CONTAINER', 'INFO', 'Relocated container ' || l_container_number || ' to CFS staging', l_restacking_shipment);
   END IF;

   COMMIT;

<<build_response>>
   -- AUDIT. Success falls through to here; every rejection arrives via
   -- cleanup_and_respond, which jumps here after its rollback -- so the code
   -- logged is the one actually returned.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'DESTUFFING',
      p_procedure_name => 'XX_OTM_POST_DESTUFFING_CONTAINER',
      p_action         => 'DESTUFF',
      p_entity_type    => 'CONTAINER',
      p_entity_id      => l_container_number,
      p_secondary_id   => l_shipment_number,
      p_response_code  => l_response_code,
      p_message        => l_response_msg,
      p_location       => v_location);

   APEX_JSON.INITIALIZE_CLOB_OUTPUT;
   APEX_JSON.OPEN_OBJECT;
   APEX_JSON.WRITE('response_code', l_response_code);
   APEX_JSON.WRITE('response_message', l_response_msg);
   
   IF l_response_code = 200 THEN
      APEX_JSON.OPEN_OBJECT('data');
      APEX_JSON.WRITE('items_updated', l_items_updated);
      APEX_JSON.WRITE('events_posted', l_events_posted);
      APEX_JSON.WRITE('seal_number', l_seal_number);
      APEX_JSON.CLOSE_OBJECT;
   END IF;
   APEX_JSON.CLOSE_OBJECT;
   
   HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
   APEX_JSON.FREE_OUTPUT;
   GOTO cleanup;

<<cleanup_and_respond>>
   ROLLBACK;
   IF l_response_code >= 400 THEN
       INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
       VALUES ('xx_otm_post_destuffing_container', 'ERROR','Response: ' || NVL(l_response_msg, 'Unknown') || ' | Trace: ' || NVL(l_validation_errors, 'No detail available'), l_restacking_shipment);
       COMMIT;
   END IF;
   GOTO build_response;

<<cleanup>>
   IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
      DBMS_LOB.FREETEMPORARY(l_clob);
   END IF;

     EXCEPTION
      WHEN OTHERS THEN
         -- 1. Grab the error before the rollback
         l_validation_errors := l_validation_errors||' '||SQLERRM;
         
         -- 2. Catch catastrophic server crashes smoothly
         ROLLBACK;
         
         -- 3. Now insert using the variable!
         INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
         VALUES ('xx_otm_post_destuffing_container', 'FATAL_ERROR', 'Server crash: ' || l_validation_errors, l_restacking_shipment);
         COMMIT;

         -- This path never reaches build_response.
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'DESTUFFING',
            p_procedure_name => 'XX_OTM_POST_DESTUFFING_CONTAINER',
            p_action         => 'DESTUFF',
            p_entity_type    => 'CONTAINER',
            p_entity_id      => l_container_number,
            p_secondary_id   => l_shipment_number,
            p_response_code  => 500,
            p_message        => l_validation_errors,
            p_location       => v_location);

         APEX_JSON.INITIALIZE_CLOB_OUTPUT;
         APEX_JSON.OPEN_OBJECT;
         APEX_JSON.WRITE('response_code', 500);
         APEX_JSON.WRITE('response_message', 'A system error occurred during processing. Please try again.');
         APEX_JSON.CLOSE_OBJECT;
         HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
         APEX_JSON.FREE_OUTPUT;
         
         IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
            DBMS_LOB.FREETEMPORARY(l_clob);
         END IF;

end xx_otm_post_destuffing_container;

   -- ========================================================================
   -- XX_OTM_POST_INSPECTION_DETAILS   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_POST_INSPECTION_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_inspection_details (
   payload   in blob,
   p_user_id in varchar2 default null
)
is
   -- Declared bare, assigned after BEGIN.
   v_location                      varchar2(100);
   l_dummy                         number;

   -- ORA-00054. The 18-May ancestor had this guard on the truck lock below;
   -- prod deleted the whole validation block and test kept the check but dropped
   -- the lock, so neither environment serialises two operators inspecting the
   -- same truck. Restored per the merge decision.
   e_row_locked                    exception;
   pragma exception_init(e_row_locked, -54);
    -- Last Updated Date : 02-02-2026
    -- Last Updated By : Sanjit
    -- Description :  -- added shipment nbr in vehicle master for easy operations
    -- Converted payload as CLOB
   p_payload                       clob;
   l_blob_len                      integer;
   l_pos                           integer := 1;
   l_chunk_raw                     raw(32767);
   l_chunk_vc                      varchar2(32767);
   l_chunk_size                    constant pls_integer := 32767;
   l_container_type varchar2(100);
   -- Core fields
   l_shipment_gid                  varchar2(100);
   l_shipment_xid                  varchar2(100);
   l_container_nbr                 varchar2(50);
   l_truck_nbr                     varchar2(100);
   l_driver_nbr                    varchar2(100);
   l_customer_name					varchar2(100);
   l_liner_name						varchar2(100);
    l_order_nbr                      varchar2(100);
   -- API Response Variables
   l_api_response                  clob;
   l_tracking_events_response_clob clob;
   l_tracking_events_vehicle_response_clob clob;
   l_response_clob                 clob;
   l_request_clob                  clob;
l_entry_time VARCHAR2(100);
   
   -- Document variables
   l_document_xid                  varchar2(100);
   l_document_filename             varchar2(200);
   l_document_mimetype             varchar2(100);
   l_document_defgid               varchar2(100);
   l_owner_object_gid              varchar2(100);
   l_clob_content                  clob;
   
   -- Refnum variables
   l_refnum_qual_gid               varchar2(200);
   l_refnum_value                  clob;
   l_domain_name                   varchar2(100);
   
   -- Inspection details
   l_inspection_details            clob;
   l_status_code                   varchar2(100);
   
   -- Error Handling
   l_error_message                 clob;
   l_has_error                     boolean := false;
   
   -- Logging
   type t_log_array is
      table of varchar2(4000);
   l_logs                          t_log_array := t_log_array();
   
   -- Counters
   l_count                         pls_integer;
   l_documents_posted              pls_integer := 0;
   l_refnums_posted                pls_integer := 0;
   
   -- API Credentials
   l_refnums_url                   varchar2(1000);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
   
   -- Procedure to add log entry
   procedure add_log (
      p_message varchar2
   ) is
   begin
      l_logs.extend;
      l_logs(l_logs.count) := to_char(
         systimestamp,
         'HH24:MI:SS.FF3'
      )
                              || ' - '
                              || p_message;
   end;

begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   add_log('Starting inspection details processing');
   
   -- 1) Convert BLOB -> CLOB safely
   add_log('Converting BLOB payload to CLOB');
   p_payload:=to_clob(payload);
   -- 2) Parse payload JSON
   add_log('Parsing JSON payload');
   apex_json.parse(p_payload);
   
   -- Extract main fields
   l_shipment_gid := apex_json.get_varchar2(p_path => 'shipmentNbr');
   l_container_nbr := apex_json.get_varchar2(p_path => 'containerNbr');
   l_truck_nbr := apex_json.get_varchar2(p_path => 'truckNbr');
   l_driver_nbr := apex_json.get_varchar2(p_path => 'driverNbr');
   l_shipment_xid := replace(
      l_shipment_gid,
      'NAQLEEN.',
      ''
   );
   add_log('Extracted: Shipment='
           || l_shipment_xid
           || ', Container='
           || l_container_nbr
           || ', Truck='
           || l_truck_nbr);

   -- =====================================================
   -- TRUCK OWNERSHIP LOCK  (restored from the 18-May ancestor)
   -- -----------------------------------------------------
   -- Prod deleted this block entirely; test kept the ownership condition but
   -- dropped the FOR UPDATE NOWAIT, so two operators could inspect the same
   -- truck concurrently and the second would overwrite the first.
   --
   -- 'inspection'          -- not yet claimed, any operator may take it
   -- 'NAQLEEN.INSPECTED'   -- already claimed; only the same operator may
   --                          re-submit (a second container on the same truck)
   -- =====================================================
   begin
      select 1
        into l_dummy
        from xxotm_vehicle_master_t
       where upper(truck_nbr) = upper(l_truck_nbr)
         and exit_time is null
         and xxotm_vehicle_master_t.location = v_location
         and ( xxotm_vehicle_master_t.status = 'inspection'
               or (    xxotm_vehicle_master_t.status  = 'NAQLEEN.INSPECTED'
                   and xxotm_vehicle_master_t.user_id = p_user_id) )
         and rownum = 1
         for update nowait;
   exception
      when no_data_found then
         -- AUDIT. The ownership lock refusing a second operator. Nothing is
         -- written to the business tables on this path, so this row is the only
         -- evidence the attempt happened.
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'INSPECTION',
            p_procedure_name => 'XX_OTM_POST_INSPECTION_DETAILS',
            p_action         => 'INSPECT',
            p_entity_type    => 'TRUCK',
            p_entity_id      => l_truck_nbr,
            p_secondary_id   => l_container_nbr,
            p_response_code  => 403,
            p_message        => 'Not awaiting inspection, or held by another operator',
            p_location       => v_location);
         apex_json.initialize_clob_output;
         apex_json.open_object;
         apex_json.write('response_code', 403);
         apex_json.write('response_message',
            'Truck not found for inspection, or already inspected by another operator.');
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
      when e_row_locked then
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'INSPECTION',
            p_procedure_name => 'XX_OTM_POST_INSPECTION_DETAILS',
            p_action         => 'INSPECT',
            p_entity_type    => 'TRUCK',
            p_entity_id      => l_truck_nbr,
            p_secondary_id   => l_container_nbr,
            p_response_code  => 409,
            p_message        => 'Row locked by a concurrent inspection',
            p_location       => v_location);
         -- The ancestor returned 500 here, which is wrong: contention is not a
         -- server fault and the client retries on 409.
         apex_json.initialize_clob_output;
         apex_json.open_object;
         apex_json.write('response_code', 409);
         apex_json.write('response_message',
            'Truck ' || l_truck_nbr || ' is being inspected by another user. Please try again.');
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         return;
   end;

   l_refnums_url := xxotm_get_cfg('OTM_BASE_URL')
                    || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.'
                    || l_shipment_xid
                    || '/refnums';
   
   begin
    SELECT st.customer_name,st.liner_name,om.ORDER_RELEASE_XID INTO l_customer_name,l_liner_name,l_order_nbr FROM xxotm_shipments_t st, xxotm_order_movements_t om WHERE st.shipment_xid = l_shipment_xid and om.shipment_xid = st.SHIPMENT_XID and st.location = v_location;
   exception
   when others then
    null;
   end;
   -- -------------------------------
   -- OPERATION 1: Post Documents
   -- -------------------------------
   add_log('OPERATION 1: Starting document posting');
   l_count := apex_json.get_count(p_path => 'documents');
   add_log('Found '
           || l_count
           || ' documents to post');
   if l_count > 0 then
      for i in 1..l_count loop
         begin
            l_document_xid := apex_json.get_varchar2(
               p_path => 'documents[%d].documentXid',
               p0     => i
            );
            l_document_filename := apex_json.get_varchar2(
               p_path => 'documents[%d].documentName',
               p0     => i
            );
            l_document_mimetype := apex_json.get_varchar2(
               p_path => 'documents[%d].documentMimeType',
               p0     => i
            );
            l_document_defgid := 'NAQLEEN.INSPECTION_DOCS';
            l_owner_object_gid := 'NAQLEEN.'||l_shipment_xid;
            l_clob_content := apex_json.get_clob(
               p_path => 'documents[%d].documentBase64Content',
               p0     => i
            );
            add_log('Posting document '
                    || i
                    || ': '
                    || l_document_filename);
            post_otm_documents(
               p_documentxid      => l_document_xid,
               p_documentfilename => l_document_filename,
               p_ownerobjectgid   => l_owner_object_gid,
               p_clobcontent      => l_clob_content,
               p_documentmimetype => l_document_mimetype,
               p_documentdefgid   => l_document_defgid,
               x_response_clob    => l_api_response
            );

            if l_api_response like 'Error%' then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Document Error ('
                                  || l_document_xid
                                  || '): '
                                  || l_api_response
                                  || '; ';
               add_log('ERROR: Document post failed - '
                       || substr(
                  l_api_response,
                  1,
                  100
               ));
            else
               l_documents_posted := l_documents_posted + 1;
               add_log('SUCCESS: Document posted - ' || l_document_filename);
            end if;
         exception
            when others then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Document Exception ('
                                  || l_document_xid
                                  || '): '
                                  || sqlerrm
                                  || '; ';
               add_log('EXCEPTION: Document post failed - ' || sqlerrm);
         end;
      end loop;
   end if;
   add_log('OPERATION 1 Complete: Posted '
           || l_documents_posted
           || ' of '
           || l_count
           || ' documents');
   
   -- -------------------------------
   -- OPERATION 2: Post Refnums
   -- -------------------------------
   add_log('OPERATION 2: Starting refnum posting');
   l_count := apex_json.get_count(p_path => 'refnums');
   add_log('Found '
           || l_count
           || ' refnums to post');
   if l_count > 0 then
      for j in 1..l_count loop
         begin
            -- Extract refnum values - using CLOB for value to handle long strings
            l_refnum_qual_gid := apex_json.get_varchar2(
               p_path => 'refnums[%d].shipmentRefnumQualGid',
               p0     => j
            );
            
            -- Use get_clob for the value since it can be long with newlines
            l_refnum_value := apex_json.get_clob(
               p_path => 'refnums[%d].shipmentRefnumValue',
               p0     => j
            );
            l_domain_name := apex_json.get_varchar2(
               p_path => 'refnums[%d].domainName',
               p0     => j
            );
            add_log('Posting refnum '
                    || j
                    || ': '
                    || l_refnum_qual_gid);
            
            -- Build JSON using APEX_JSON to ensure proper escaping
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write(
               'shipmentRefnumQualGid',
               l_refnum_qual_gid
            );
            apex_json.write(
               'shipmentRefnumValue',
               l_refnum_value
            );
            apex_json.write(
               'domainName',
               l_domain_name
            );
            apex_json.close_object;
            l_request_clob := apex_json.get_clob_output;
            apex_json.free_output;
            
            -- Post the refnum
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            l_api_response := apex_web_service.make_rest_request(
               p_url         => l_refnums_url,
               p_http_method => 'POST',
               p_credential_static_id => l_credential_static_id,
               p_body        => l_request_clob,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
            
            -- Check for API error
            if instr(
               lower(l_api_response),
               'error'
            ) > 0 then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Refnum API Error ('
                                  || l_refnum_qual_gid
                                  || '): '
                                  || substr(
                  l_api_response,
                  1,
                  200
               )
                                  || '; ';
               add_log('ERROR: Refnum post failed - '
                       || substr(
                  l_api_response,
                  1,
                  100
               ));
            else
               l_refnums_posted := l_refnums_posted + 1;
               add_log('SUCCESS: Refnum posted - ' || l_refnum_qual_gid);
            end if;

         exception
            when others then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Refnum Exception ('
                                  || nvl(
                  l_refnum_qual_gid,
                  'unknown'
               )
                                  || '): '
                                  || sqlerrm
                                  || '; ';
               add_log('EXCEPTION: Refnum post failed - ' || sqlerrm);
         end;
      end loop;
   end if;
   add_log('OPERATION 2 Complete: Posted '
           || l_refnums_posted
           || ' of '
           || l_count
           || ' refnums');
   
   -- -------------------------------
   -- OPERATION 3: Insert Inspections
   -- -------------------------------
   add_log('OPERATION 3: Inserting inspection details');
   begin
      select json_query(p_payload,
           '$.inspection_details' returning clob)
        into l_inspection_details
        from dual;

      insert into xxotm_container_inspection_t (
         container_nbr,
         
       
         shipment_nbr,
         inspection_details,
         timestamp,
         location
      ) values ( l_container_nbr,
      			
                 l_shipment_xid,
                 l_inspection_details,
                 to_char(
                    sysdate,
                    'YYYY-MM-DD HH24:MI:SS'
                 ),
                 v_location );
      add_log('SUCCESS: Inspection details inserted for container ' || l_container_nbr);
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Inspection Insert Error: '
                            || sqlerrm
                            || '; ';
         add_log('ERROR: Inspection insert failed - ' || sqlerrm);
   end;
   
   -- -------------------------------
   -- OPERATION 4: Update Inventory
   -- -------------------------------
                 
	SELECT container_type INTO l_container_type FROM XXOTM_SHIPMENTS_T xst WHERE xst.SHIPMENT_XID =l_shipment_gid AND xst.location = v_location;                 
   add_log('OPERATION 4: Inserting container inventory');
   begin
			    merge into xxotm_container_inventory_t t
			using (
			  select l_container_nbr    as container_nbr,
			         l_shipment_xid     as inbound_shipment_nbr,
			         l_customer_name    as cust_nbr,
			         l_liner_name       as cust_name,
			         l_order_nbr        as inbound_order_nbr,
			         l_container_type   as container_type
			    from dual
			) s
			on ( t.inbound_shipment_nbr = s.inbound_shipment_nbr
			     and t.location = v_location )
			when matched then
			  update set
			    t.cust_nbr       = s.cust_nbr,
			    t.cust_name      = s.cust_name,
			    t.inbound_order_nbr = s.inbound_order_nbr,
			    t.container_type = s.container_type
			when not matched then
			  insert (
			    container_nbr,
			    inbound_shipment_nbr,
			    cust_nbr,
			    cust_name,
			    inbound_order_nbr,
			    outbound_order_nbr,
			    outbound_shipment_nbr,
			    position,
			    container_type,
			    location
			  )
			  values (
			    s.container_nbr,
			    s.inbound_shipment_nbr,
			    s.cust_nbr,
			    s.cust_name,
			    s.inbound_order_nbr,
			    null,
			    null,
			    null,
			    s.container_type,
			    v_location
			  );

      add_log('SUCCESS: Container inventory created for ' || l_container_nbr);
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Inventory Insert Error: '
                            || sqlerrm
                            || '; ';
         add_log('ERROR: Inventory insert failed - ' || sqlerrm);
   end;
   
   -- -------------------------------
   -- OPERATION 5: Tracking Event
   -- -------------------------------
     SELECT entry_time INTO l_entry_time FROM XXOTM_VEHICLE_MASTER_T xvmt WHERE upper(truck_nbr) = upper(l_truck_nbr) AND xvmt.location = v_location ORDER BY ENTRY_TIME DESC FETCH FIRST 1 ROWS only ;
  
  
      
     begin
      post_otm_tracking_events(
        p_integration_name => 'XX_OTM_POST_INSPECTION_APEX',
         p_statuscodegid => 'NAQLEEN.VEHICLE ENTERED',
         p_shipmentxid   => l_shipment_xid,
          p_event_timestamp =>  TO_CHAR(
					    TO_TIMESTAMP_TZ(
					      REGEXP_REPLACE(l_entry_time, '(\.\d{6})Z$', 'Z'),
					      'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
					    ),
					    'YYYY-MM-DD"T"HH24:MI:SS'
					  ),
         x_response      => l_tracking_events_vehicle_response_clob 
      );
      if l_tracking_events_vehicle_response_clob  like 'Error%' then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Error (NAQLEEN.VEHICLE ENTERED): '
                            || l_tracking_events_vehicle_response_clob 
                            || '; ';
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Exception (NAQLEEN.VEHICLE ENTERED): '
                            || sqlerrm
                            || '; ';
   end;
   
   begin
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_INSPECTION_APEX',
         p_statuscodegid    => 'NAQLEEN.INSPECTED',
         p_shipmentxid      => l_shipment_xid,
         p_attribute1       => null,
         p_attribute2       => l_container_nbr,
         p_attribute3       => null,
         p_attribute4       => null,
         p_attribute5       => null,
         p_attribute6       => null,
         p_attribute7       => null,
         p_attribute8       => null,
         p_attribute9       => null,
         p_attribute10      => null,
         x_response         => l_tracking_events_response_clob
      );

      if l_tracking_events_response_clob like 'Error%' then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Tracking Event Error: '
                            || l_tracking_events_response_clob
                            || '; ';
         add_log('ERROR: Tracking event failed - '
                 || substr(
            l_tracking_events_response_clob,
            1,
            100
         ));
      else
         add_log('SUCCESS: Tracking event posted for shipment ' || l_shipment_xid);
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Tracking Event Exception: '
                            || sqlerrm
                            || '; ';
         add_log('EXCEPTION: Tracking event failed - ' || sqlerrm);
   end;
   
   -- -------------------------------
   -- OPERATION 6: Update Shipment Attributes (Truck/Driver)
   -- -------------------------------
   add_log('OPERATION 6: Updating shipment attributes (truck/driver)');
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'attribute7',
      l_truck_nbr
   );
   apex_json.write(
      'attribute8',
      l_driver_nbr
   );
   apex_json.close_object;
   l_request_clob := apex_json.get_clob_output;
   apex_json.free_output;
   apex_web_service.g_request_headers.delete;
   apex_web_service.g_request_headers(1).name := 'Content-Type';
   apex_web_service.g_request_headers(1).value := 'application/json';
   begin
      l_response_clob := apex_web_service.make_rest_request(
         p_url         => xxotm_get_cfg('OTM_BASE_URL')
                          || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.' || l_shipment_gid
         ,
         p_http_method => 'PATCH',
         p_credential_static_id => l_credential_static_id,
         p_body        => l_request_clob,
         p_wallet_path => xxotm_get_cfg('WALLET_PATH')
      );
      
      -- Check for error in response
      if l_response_clob like 'Error%'
      or instr(
         lower(l_response_clob),
         'error'
      ) > 0 then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Shipment Update Error: '
                            || substr(
            l_response_clob,
            1,
            200
         )
                            || '; ';
         add_log('ERROR: Shipment update failed - '
                 || substr(
            l_response_clob,
            1,
            100
         ));
      else
         add_log('SUCCESS: Shipment attributes updated');
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Shipment Update Exception: '
                            || sqlerrm
                            || '; ';
         add_log('EXCEPTION: Shipment update failed - ' || sqlerrm);
   end;
   
   -- -------------------------------
   -- OPERATION 7: Update Vehicle Master
   -- -------------------------------
   add_log('OPERATION 7: Updating vehicle master status');
   begin
      update xxotm_vehicle_master_t
         set
         status = 'NAQLEEN.INSPECTED',
         user_id = p_user_id,   -- CLAIM THE LOCK: the ownership check above tests
                                -- this column, so without the claim the second
                                -- scan of a two-container truck always fails
         shipment_nbr = l_shipment_xid   -- added shipment nbr for easy operations
       where truck_nbr = l_truck_nbr
         and entry_time is not null
         and exit_time is null
         and status = 'inspection'
         and xxotm_vehicle_master_t.location = v_location;

      if sql%rowcount > 0 then
         add_log('SUCCESS: Vehicle master updated for truck '
                 || l_truck_nbr
                 || ' ('
                 || sql%rowcount
                 || ' rows)');
      else
         add_log('WARNING: No vehicle master records updated for truck ' || l_truck_nbr);
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Vehicle Master Update Error: '
                            || sqlerrm
                            || '; ';
         add_log('ERROR: Vehicle master update failed - ' || sqlerrm);
   end;
	
      begin
      update xxotm_shipments_t
         set
         truck_3pl = l_truck_nbr, driver_3pl = nvl(l_driver_nbr,'')  -- added shipment nbr for easy operations
       where 
         shipment_xid = l_shipment_xid
         and xxotm_shipments_t.location = v_location;

      if sql%rowcount > 0 then
         add_log('SUCCESS: xxotm_shipments_t updated for truck '
                 || l_shipment_xid
                 || ' ('
                 || sql%rowcount
                 || ' rows)');
      else
         add_log('WARNING: No xxotm_shipments_t records updated for shipment ' || l_shipment_xid);
      end if;
   exception
      when others then
         
         l_error_message := l_error_message
                            || 'xxotm_shipments_t Update Error: '
                            || sqlerrm
                            || '; ';
         dbms_output.put_line('ERROR: xxotm_shipments_t update failed - ' || sqlerrm);
   end; 
      
      
      
   add_log('Committing transaction');
   commit;
   add_log('Processing complete');
   
   -- -------------------------------
   -- Build JSON Response
   -- -------------------------------
   -- AUDIT. l_has_error is set by any of the seven operations above (documents,
   -- refnums, inspection insert, inventory merge, tracking events, shipment
   -- patch, vehicle master), so a partial failure is recorded even though the
   -- commit already happened.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'INSPECTION',
      p_procedure_name => 'XX_OTM_POST_INSPECTION_DETAILS',
      p_action         => 'INSPECT',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck_nbr,
      p_secondary_id   => l_container_nbr,
      p_response_code  => case when l_has_error then 500 else 200 end,
      p_message        => nvl(substr(l_error_message, 1, 400), l_shipment_xid),
      p_location       => v_location);

   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_has_error then
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Partial or Full Failure: ' || l_error_message
      );
   else
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
   end if;
   
   -- Add logs array to response
   apex_json.open_array('logs');
   for i in 1..l_logs.count loop
      apex_json.write(l_logs(i));
   end loop;
   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
   
   -- Clean up temp lob
   if dbms_lob.istemporary(p_payload) = 1 then
      dbms_lob.freetemporary(p_payload);
   end if;

exception
   when others then
      -- Global Exception Handler
      add_log('CRITICAL EXCEPTION: ' || sqlerrm);
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'INSPECTION',
         p_procedure_name => 'XX_OTM_POST_INSPECTION_DETAILS',
         p_action         => 'INSPECT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck_nbr,
         p_secondary_id   => l_container_nbr,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);
      if dbms_lob.istemporary(p_payload) = 1 then
         dbms_lob.freetemporary(p_payload);
      end if;

      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      
      -- Add logs array even in exception
      apex_json.open_array('logs');
      for i in 1..l_logs.count loop
         apex_json.write(l_logs(i));
      end loop;
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_inspection_details;

   -- ========================================================================
   -- XX_OTM_POST_LCL_SHIPMENT   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_LCL_SHIPMENT.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_lcl_shipment (
   payload in blob,
   p_user_id in varchar2 default null
)
is
   v_location varchar2(100);
   p_payload          clob;
   l_shipment_nbr     varchar2(100);
   l_customer_name    varchar2(200);
   l_customer_nbr     varchar2(100);
   l_seal_number      varchar2(100);
   
   l_items_count      number;
   l_item_code        varchar2(50);
   l_description      varchar2(200);
   l_qty              number;
   l_uom              varchar2(20);
   
   l_exist_count      number;
   l_items_processed  number := 0;
   
   -- New Variables
   l_status_code      varchar2(100) := 'NAQLEEN.DESTUFFED';
   l_response_out     clob;
   l_events_posted    number := 0;
   l_error_msg        varchar2(4000);

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert Blob to Clob
   p_payload := to_clob(payload);
   
   -- Parse JSON
   apex_json.parse(p_payload);
   
   -- Get Header Fields
   l_shipment_nbr   := apex_json.get_varchar2('shipment_nbr');
   l_customer_name  := apex_json.get_varchar2('customer_name');
   l_customer_nbr   := apex_json.get_varchar2('customer_nbr');
   l_seal_number    := apex_json.get_varchar2('seal_nbr');
   
   -- Process Items
   l_items_count := apex_json.get_count('items');
   
   for i in 1..l_items_count loop
       l_item_code   := apex_json.get_varchar2('items[%d].item_code', i);
       l_description := apex_json.get_varchar2('items[%d].description', i);
       l_qty         := apex_json.get_number('items[%d].qty', i);
       l_uom         := apex_json.get_varchar2('items[%d].qty_uom', i);
       
       -- Check if item exists
       select count(*) into l_exist_count
         from xxotm_customer_inventory_t
        where shipment_nbr = l_shipment_nbr
          and item_code = l_item_code
          and xxotm_customer_inventory_t.location = v_location;
          
       if l_exist_count > 0 then
           -- Update existing
           update xxotm_customer_inventory_t
              set rcvd_qty = nvl(rcvd_qty, 0) + l_qty
            where shipment_nbr = l_shipment_nbr
              and item_code = l_item_code and xxotm_customer_inventory_t.location = v_location;
       else
           -- Insert new
           insert into xxotm_customer_inventory_t (
               shipment_nbr,
               cust_name,      -- Corrected from customer_name
               cust_nbr,       -- Corrected from customer_nbr
               item_code,
               item_description, -- Corrected from description
               qty,
               rcvd_qty,
               qty_uom,
               creation_date,
               created_by
               , location
) values (
               l_shipment_nbr,
               l_customer_name,
               l_customer_nbr,
               l_item_code,
               l_description,
               l_qty, -- Original qty
               l_qty, -- Received qty
               l_uom,
               sysdate,
               'MOBILE_APP'
               , v_location
);
       end if;
       
       l_items_processed := l_items_processed + 1;
   end loop;
   
   -- Post DESTUFFED Event
   begin
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_DESTUFFING_CONTAINER',
         p_statuscodegid    => l_status_code,
         p_shipmentxid      => l_shipment_nbr,
         p_attribute2       => l_seal_number, 
         x_response         => l_response_out
      );

      if l_response_out not like 'Error%' then
         l_events_posted := 1;
      else
         l_error_msg := 'OTM Event Error: ' || substr(l_response_out, 1, 200);
      end if;
   exception when others then
       l_error_msg := 'Event Posting Failed: ' || sqlerrm;
   end;
   
   -- Commit changes
   commit;
   
   -- Response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   if l_error_msg is null then
       apex_json.write('response_code', 200);
       apex_json.write('response_message', 'Success');
   else
       apex_json.write('response_code', 200);
       apex_json.write('response_message', 'Items updated. ' || l_error_msg);
   end if;

   apex_json.open_object('data');
   apex_json.write('items_processed', l_items_processed);
   apex_json.write('events_posted', l_events_posted);
   apex_json.write('seal_number', l_seal_number);
   apex_json.close_object;
   apex_json.close_object;
   
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

exception
   when others then
       rollback;
       apex_json.initialize_clob_output;
       apex_json.open_object;
       apex_json.write('response_code', 500);
       apex_json.write('response_message', 'Error: ' || sqlerrm);
       apex_json.close_object;
       htp.prn(apex_json.get_clob_output);
       apex_json.free_output;
end xx_otm_post_lcl_shipment;

   -- ========================================================================
   -- XX_OTM_POST_LOADING_LCL   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_POST_LOADING_LCL.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_loading_lcl (
   payload in blob,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
is
    -- Created Date : 05-Jan-2026
    -- Description  : Submits stuffing results. 
    --               1. Updates stuffed_qty for items in local inventory.
    --               2. Posts STUFFED tracking event with seal number to OTM.
    --               3. Updates customer stock available quantity.

   p_payload          clob;
   l_container_number varchar2(50);
   l_customer_nbr     varchar2(100);
   l_shipment_number  varchar2(100);
   l_seal_number      varchar2(100);
   l_item_code        varchar2(20);
   l_stuffed_quantity number;
   l_status_code      varchar2(100) := 'NAQLEEN.STUFFED';
   l_items_updated    number := 0;
   l_events_posted    number := 0;
   l_item_count       number;
   l_cont_no          varchar2(100);
   l_response_out     clob;
   l_cfs_count        number;
   l_error_msg        varchar2(4000);
   l_attribute4       varchar2(100);
   l_shipment_name    varchar2(200); -- Added to check shipment type
    v_location varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- 1. Payload Conversion
   p_payload := to_clob(payload);
    
    -- 2. Initial Response Setup
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- 3. JSON Parsing
   begin
      apex_json.parse(p_payload);
   exception
      when others then
         raise_application_error(
            -20001,
            'Invalid JSON payload: ' || sqlerrm
         );
   end;

    -- 4. Extract Header Fields from standardized JSON paths
   l_shipment_number := apex_json.get_varchar2('shipment_nbr');
   l_customer_nbr := apex_json.get_varchar2('customer_nbr');

    -- ------------------------------------------------------------
    -- OPERATION 1: Update Item Quantities and Customer Stock
    -- ------------------------------------------------------------
   l_item_count := apex_json.get_count('items');
   if l_item_count > 0 then
      for i in 1..l_item_count loop
         l_item_code := apex_json.get_varchar2(
            'items[%d].item_code',
            i
         );
         l_stuffed_quantity := apex_json.get_number(
            'items[%d].stuffed_quantity',
            i
         );
         update xxotm_customer_inventory_t
            set
            stuffed_qty = l_stuffed_quantity
          where shipment_nbr = l_shipment_number
            and item_code = l_item_code and xxotm_customer_inventory_t.location = v_location;

         if sql%rowcount > 0 then
            l_items_updated := l_items_updated + 1;
         end if;
            
         -- Reduce customer stock quantity
         update xxotm_customer_stock_t
            set
            available_qty = available_qty - l_stuffed_quantity
          where cust_nbr = l_customer_nbr
            and item_code = l_item_code and xxotm_customer_stock_t.location = v_location;

      end loop;
   end if;



   begin
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_STUFFING_CONTAINER',
         p_statuscodegid    => l_status_code,
         p_shipmentxid      => l_shipment_number,
         x_response         => l_response_out
      );

      if l_response_out not like 'Error%' then
         l_events_posted := 1;
      else
         l_error_msg := 'OTM Event Error: '
                        || substr(
            l_response_out,
            1,
            200
         );
      end if;
   exception
      when others then
         dbms_output.put_line('Event Posting Error: ' || sqlerrm);
         l_error_msg := 'OTM Event Exception: ' || sqlerrm;
   end;

   
    -- 5. Finalize Transaction and Build Response
   if l_items_updated > 0
   or l_events_posted > 0 then
      commit;
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         nvl(
            l_error_msg,
            'Success'
         )
      );
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No items updated and event posting failed. ' || l_error_msg
      );
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      rollback;
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_loading_lcl;

   -- ========================================================================
   -- XX_OTM_POST_OFFLOADING_SHIPMENT   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_OFFLOADING_SHIPMENT.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_offloading_shipment (
   payload in blob,
   p_user_id in varchar2 default null
)
is
    v_location varchar2(100);
    -- Created Date : 27-Jan-2026
    -- Updated Date : 04-Feb-2026
    -- Description  : Submits Offloading results. 
    --               1. Updates rcvd_qty for items in local inventory.
    --               2. Updates (or Inserts) customer stock available quantity.
    --               3. Posts DESTUFFED tracking event to OTM.

   p_payload          clob;
   l_container_number varchar2(50);
   l_customer         varchar2(100);
   l_shipment_number  varchar2(100);
   l_seal_number      varchar2(100);
   l_item_code        varchar2(20);
   l_rcvd_quantity    number;
   l_status_code      varchar2(100) := 'NAQLEEN.DESTUFFED';
   l_items_updated    number := 0;
   l_events_posted    number := 0;
   l_item_count       number;
   l_response_out     clob;
   l_error_msg        varchar2(4000);
   
   -- Variables for fetching additional item details
   l_cust_name        varchar2(200);
   l_item_desc        varchar2(500);
   l_qty_uom          varchar2(50);
   l_weight_uom       varchar2(50);
   l_net_weight       number;
begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- 1. Payload Conversion
   p_payload := to_clob(payload);
    
    -- 2. Initial Response Setup
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- 3. JSON Parsing
   begin
      apex_json.parse(p_payload);
   exception
      when others then
         raise_application_error(
            -20001,
            'Invalid JSON payload: ' || sqlerrm
         );
   end;

    -- 4. Extract Header Fields from updated JSON paths
   l_shipment_number := apex_json.get_varchar2('shipment_nbr');
   l_customer := apex_json.get_varchar2('customer_nbr');

    -- ------------------------------------------------------------
    -- OPERATION 1: Update Item Quantities and Customer Stock
    -- ------------------------------------------------------------
   l_item_count := apex_json.get_count('items');
   if l_item_count > 0 then
      for i in 1..l_item_count loop
         l_item_code := apex_json.get_varchar2(
            'items[%d].item_code',
            i
         );
         l_rcvd_quantity := apex_json.get_number(
            'items[%d].qty',
            i
         );
         
         -- 1.1 Update Customer Inventory (Received Qty)
         update xxotm_customer_inventory_t
            set
            rcvd_qty = to_number(l_rcvd_quantity)
          where shipment_nbr = l_shipment_number
            and item_code = l_item_code and xxotm_customer_inventory_t.location = v_location;

         if sql%rowcount > 0 then
            l_items_updated := l_items_updated + 1;
            
            -- Fetch details for stock update/insert
            begin
               select cust_name,
                      item_description,
                      qty_uom,
                      weight_uom,
                      net_weight
                 into
                  l_cust_name,
                  l_item_desc,
                  l_qty_uom,
                  l_weight_uom,
                  l_net_weight
                 from xxotm_customer_inventory_t
                where shipment_nbr = l_shipment_number
                  and item_code = l_item_code and xxotm_customer_inventory_t.location = v_location
                  and rownum = 1;
            exception
               when no_data_found then
                  l_cust_name := null;
                  l_item_desc := null;
                  l_qty_uom := null;
            end;
            
            -- 1.2 Update Customer Stock (Attempt Update First)
            update xxotm_customer_stock_t
               set
               available_qty = nvl(
                  available_qty,
                  0
               ) + to_number(l_rcvd_quantity)
             where cust_nbr = l_customer
               and item_code = l_item_code and xxotm_customer_stock_t.location = v_location;
               
            -- 1.3 Insert (If Update Failed)
            if sql%rowcount = 0 then
               insert into xxotm_customer_stock_t (
                  cust_nbr,
                  cust_name,
                  item_code,
                  item_description,
                  available_qty,
                  qty_uom,
                  weight_uom,
                  net_weight
                  , location
) values ( l_customer,
                          l_cust_name,
                          l_item_code,
                          l_item_desc,
                          to_number(l_rcvd_quantity),
                          l_qty_uom,
                          l_weight_uom,
                          l_net_weight
                          , v_location
);
            end if;

         else
             -- If inventory update matches nothing, we likely skip stock update? 
             -- For now, consistency implies we rely on inventory match.
            null;
         end if;

      end loop;
   end if;

    -- ------------------------------------------------------------
    -- OPERATION 2: Post DESTUFFED Event 
    -- ------------------------------------------------------------
   begin
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_DESTUFFING_CONTAINER',
         p_statuscodegid    => l_status_code,
         p_shipmentxid      => l_shipment_number,
         x_response         => l_response_out
      );

      if l_response_out not like 'Error%' then
         l_events_posted := 1;
      else
         l_error_msg := l_error_msg
                        || 'OTM Event Error: '
                        || substr(
            l_response_out,
            1,
            200
         );
      end if;
   exception
      when others then
         dbms_output.put_line('Event Posting Error: ' || sqlerrm);
         l_error_msg := l_error_msg
                        || 'OTM Event Exception: '
                        || sqlerrm;
   end;

    -- 3. Finalize Transaction and Build Response
   if l_items_updated > 0
   or l_events_posted > 0 then
      commit;
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         nvl(
            l_error_msg,
            'Success'
         )
      );
      apex_json.open_object('data');
      apex_json.write(
         'items_updated',
         l_items_updated
      );
      apex_json.write(
         'events_posted',
         l_events_posted
      );
      apex_json.write(
         'seal_number',
         l_seal_number
      );
      apex_json.close_object;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No items updated and event posting failed. ' || l_error_msg
      );
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      rollback;
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_offloading_shipment;

   -- ========================================================================
   -- XX_OTM_POST_PDF   [4-prod-only / KEEP]
   -- source: db/work/XX_OTM_POST_PDF.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_pdf (
   p_pdf            in  blob,
   p_filename       in  varchar2,
   p_ownerobjectgid in  varchar2,
   p_documentxid    in  varchar2,
   p_documentdefgid in  varchar2 default 'NAQLEEN.EIR',
   x_response_clob  out clob
)
as
   l_b64 clob;
begin
   if p_pdf is null or nvl(dbms_lob.getlength(p_pdf), 0) = 0 then
      x_response_clob := 'No PDF content to send';
      return;
   end if;

   -- BLOB2CLOBBASE64 injects CRLF every 64 chars. apex_json escapes them into valid
   -- JSON, but OTM's decoder is happier with one unbroken base64 string.
   l_b64 := replace(replace(apex_web_service.blob2clobbase64(p_pdf), chr(13)), chr(10));

   post_otm_documents(
      p_documentxid      => p_documentxid,
      p_documentfilename => p_filename,
      p_ownerobjectgid   => p_ownerobjectgid,
      p_clobcontent      => l_b64,
      p_documentmimetype => 'application/pdf',
      p_documentdefgid   => p_documentdefgid,
      x_response_clob    => x_response_clob);

   if l_b64 is not null and dbms_lob.istemporary(l_b64) = 1 then
      dbms_lob.freetemporary(l_b64);
   end if;
exception
   when others then
      if l_b64 is not null and dbms_lob.istemporary(l_b64) = 1 then
         dbms_lob.freetemporary(l_b64);
      end if;
      x_response_clob := 'Error in XX_OTM_POST_PDF: ' || sqlerrm;
end xx_otm_post_pdf;

   -- ========================================================================
   -- XX_OTM_POST_PLUG_IN_OUT_CONTAINER   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_PLUG_IN_OUT_CONTAINER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_plug_in_out_container (
    payload IN BLOB,
    p_user_id in varchar2 default null
)
AS
    v_location varchar2(100);
    p_payload           CLOB;
    l_container_nbr     VARCHAR2(50);
    l_type              VARCHAR2(20);
    l_set_point_temp    NUMBER;
    l_current_temp      NUMBER;
    l_remarks           VARCHAR2(200);
    l_timestamp         varchar2(240);
    l_position          VARCHAR2(20);
    l_inbound_shipment_nbr VARCHAR2(50);
    l_container_exists  NUMBER := 0;
BEGIN
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Convert BLOB to CLOB
    p_payload := TO_CLOB(payload);

    -- Parse JSON payload
    apex_json.parse(p_payload);

    -- Extract values from JSON
    l_container_nbr := apex_json.get_varchar2(p_path => 'container_nbr');
    l_type := apex_json.get_varchar2(p_path => 'type');
    l_set_point_temp := apex_json.get_number(p_path => 'setPointTemp');
    l_current_temp := apex_json.get_number(p_path => 'currentTemp');
    l_remarks := apex_json.get_varchar2(p_path => 'remarks');
    l_timestamp := apex_json.get_varchar2(p_path => 'timestamp');


    BEGIN
        SELECT COUNT(*)
        INTO l_container_exists
        FROM xxotm_container_inventory_t
        WHERE container_nbr = l_container_nbr and xxotm_container_inventory_t.location = v_location;

        IF l_container_exists = 0 THEN
            xxotm_log_activity(
                p_user_id        => p_user_id,
                p_module         => 'PLUG_IN_OUT',
                p_procedure_name => 'XX_OTM_POST_PLUG_IN_OUT_CONTAINER',
                p_action         => UPPER(l_type),
                p_entity_type    => 'CONTAINER',
                p_entity_id      => l_container_nbr,
                p_response_code  => 404,
                p_message        => 'Container not in inventory at this location',
                p_location       => v_location);
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write('response_code', 404);
            apex_json.write('response_message', 'Container not found in inventory');
            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
            RETURN;
        END IF;

        -- Fetch additional details
        BEGIN
            SELECT position, inbound_shipment_nbr
            INTO l_position, l_inbound_shipment_nbr
            FROM xxotm_container_inventory_t
            WHERE container_nbr = l_container_nbr  AND 	outbound_shipment_nbr IS NULL 
        AND inbound_shipment_nbr IS NOT NULL AND POSITION IS NOT NULL
        AND xxotm_container_inventory_t.location = v_location fetch first 1 rows ONLY;

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                l_position := NULL;
                l_inbound_shipment_nbr := NULL;
        END;

        -- Insert into history table
        INSERT INTO xxotm_pluginout_t (
            container_nbr,
            type,
            set_point_temp,
            current_temp,
            remarks,
            timestamp,
            inbound_shipment_nbr,
            position
        ) VALUES (
            l_container_nbr,
            l_type,
            l_set_point_temp,
            l_current_temp,
            l_remarks,
            l_timestamp, -- Explicit conversion
            l_inbound_shipment_nbr,
            l_position
        );

        COMMIT;

        xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'PLUG_IN_OUT',
            p_procedure_name => 'XX_OTM_POST_PLUG_IN_OUT_CONTAINER',
            p_action         => UPPER(l_type),
            p_entity_type    => 'CONTAINER',
            p_entity_id      => l_container_nbr,
            p_secondary_id   => l_position,
            p_response_code  => 200,
            p_message        => 'set=' || l_set_point_temp || 'C actual=' || l_current_temp || 'C',
            p_location       => v_location);

        -- Success response
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 200);
        apex_json.write('response_message', 'Plug in-out operation recorded successfully');
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write('response_code', 500);
            apex_json.write('response_message', 'Database error: ' || SQLERRM);
            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
    END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 500);
        apex_json.write('response_message', 'Error: ' || SQLERRM);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
END xx_otm_post_plug_in_out_container;

   -- ========================================================================
   -- XX_OTM_POST_PLUG_IN_OUT_CONTAINER_TEST   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_POST_PLUG_IN_OUT_CONTAINER_TEST.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_plug_in_out_container_test (
    payload IN CLOB
)
AS
    p_payload           CLOB;
    l_container_nbr     VARCHAR2(50);
    l_type              VARCHAR2(20);
    l_set_point_temp    NUMBER;
    l_current_temp      NUMBER;
    l_remarks           VARCHAR2(200);
    l_timestamp          VARCHAR2(200);
    l_position          VARCHAR2(20);
    l_outbound_shipment VARCHAR2(50);
    l_container_exists  NUMBER := 0;
BEGIN
    -- Convert BLOB to CLOB
  p_payload := payload;

    -- Parse JSON payload
    apex_json.parse(p_payload);

    -- Extract values from JSON
    l_container_nbr := apex_json.get_varchar2(p_path => 'container_nbr');
    l_type := apex_json.get_varchar2(p_path => 'type');
    l_set_point_temp := apex_json.get_number(p_path => 'setPointTemp');
    l_current_temp := apex_json.get_number(p_path => 'currentTemp');
    l_remarks := apex_json.get_varchar2(p_path => 'remarks');
    l_timestamp := apex_json.get_varchar2(p_path => 'timestamp');


    -- Verify container exists in inventory
    BEGIN
        SELECT COUNT(*)
        INTO l_container_exists
        FROM xxotm_container_inventory_t
        WHERE container_nbr = l_container_nbr;


    END;

    -- Get position and outbound shipment from inventory
    BEGIN
        SELECT position, outbound_shipment_nbr
        INTO l_position, l_outbound_shipment
        FROM xxotm_container_inventory_t
        WHERE container_nbr = l_container_nbr
        AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            l_position := NULL;
            l_outbound_shipment := NULL;
    END;

    -- Insert plug in/out record
    BEGIN
        INSERT INTO xxotm_pluginout_t (
            container_nbr,
            set_point_temp,
            current_temp,
            type,
            remarks,
            timestamp,
            outbound_shipment_nbr,
            position
        ) VALUES (
            l_container_nbr,
            l_set_point_temp,
            l_current_temp,
            l_type,
            l_remarks,
         l_timestamp,
            l_outbound_shipment,
            l_position
        );

        COMMIT;

        -- Success response
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 200);
        apex_json.write('response_message', 'Plug in/out operation recorded successfully');
        apex_json.open_object('data');
        apex_json.write('container_nbr', l_container_nbr);
        apex_json.write('type', l_type);
        apex_json.write('setPointTemp', l_set_point_temp);
        apex_json.write('currentTemp', l_current_temp);
        apex_json.write('timestamp',l_timestamp);
        apex_json.close_object;
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        dbms_output.put_line(apex_json.get_clob_output);

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write('response_code', 500);
            apex_json.write('response_message', 'Database error: ' || SQLERRM);
            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
            dbms_output.put_line(apex_json.get_clob_output);
    END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code', 500);
        apex_json.write('response_message', 'Error: ' || SQLERRM);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        dbms_output.put_line(apex_json.get_clob_output);
END xx_otm_post_plug_in_out_container_test;

   -- ========================================================================
   -- XX_OTM_POST_RESTACKCONTAINER   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_RESTACKCONTAINER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_restackcontainer (
   payload in blob,
   p_user_id in varchar2 default null
)
is
   v_location varchar2(100);
   -- Updated Date : 20-01-2026
   -- Updated By : Madhan
   -- Description : Container restack with stacking validation and position management
   
   p_payload          clob;
   l_container_nbr    varchar2(50);
   l_new_position     varchar2(20);
   l_current_position varchar2(20);
   l_timestamp        varchar2(100);
   l_shipment_nbr     varchar2(100);
   l_response         json_object_t;
   l_api_response     clob;
   
   -- Position parsing variables
   v_curr_terminal    varchar2(50);
   v_curr_block       varchar2(50);
   v_curr_row_no      varchar2(50);
   v_curr_lot_no      varchar2(50);
   v_curr_level_no    varchar2(50);
   v_curr_level_num   number;
   v_new_terminal     varchar2(50);
   v_new_block        varchar2(50);
   v_new_row_no       varchar2(50);
   v_new_lot_no       varchar2(50);
   v_new_level_no     varchar2(50);

   -- Both FOR UPDATE NOWAIT statements below were unguarded: lock contention
   -- surfaced as a raw "ORA-00054: resource busy and acquire with NOWAIT
   -- specified" rendered straight into response_message, under a 400 that says
   -- the request was bad when in fact it was merely simultaneous. Declared at
   -- procedure level and handled once in the outer EXCEPTION section, so both
   -- lock sites are covered by one 409.
   e_row_locked exception;
   pragma exception_init(e_row_locked, -54);

   -- Validation variables
   l_blocking_container varchar2(100);
   l_blocking_level     number;
   l_has_blocking       boolean := false;
   v_inv_rows           number;
   l_curr_container     varchar2(100);
   l_val_position      varchar2(100);
   -- Set alongside each response below so the audit row carries the code
   -- actually returned; the inner block's 200 and 500 converge on one output.
   l_audit_code         number;
   l_audit_msg          varchar2(400);
   
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   -- Convert blob to clob and initialize JSON response
   p_payload := to_clob(payload);
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- Parse input payload
   apex_json.parse(p_payload);
   
   -- Extract JSON values
   l_container_nbr    := apex_json.get_varchar2(p_path => 'container_nbr');
   l_new_position     := apex_json.get_varchar2(p_path => 'newPosition');
   l_current_position := apex_json.get_varchar2(p_path => 'currentPosition');
   l_timestamp        := apex_json.get_varchar2(p_path => 'timestamp');
   l_shipment_nbr     := apex_json.get_varchar2(p_path => 'shipment_nbr');
   
   -- Get shipment from inventory if not provided
   if l_shipment_nbr is null then
      begin
         select inbound_shipment_nbr 
         into l_shipment_nbr 
         from xxotm_container_inventory_t 
         where container_nbr = l_container_nbr
           and container_stored_time is not null 
           and container_released_time is null
           and xxotm_container_inventory_t.location = v_location
         order by container_stored_time desc 
         fetch first 1 rows only;
      exception
         when no_data_found then
            l_shipment_nbr := null;
      end;
   end if;
   
   -- Parse current position (TERMINAL-BLOCK-LOT-ROW-LEVEL)
   v_curr_terminal := regexp_substr(l_current_position, '[^-]+', 1, 1);
   v_curr_block    := regexp_substr(l_current_position, '[^-]+', 1, 2);
   v_curr_lot_no   := regexp_substr(l_current_position, '[^-]+', 1, 3);
   v_curr_row_no   := regexp_substr(l_current_position, '[^-]+', 1, 4);
   v_curr_level_no := regexp_substr(l_current_position, '[^-]+', 1, 5);
   v_curr_level_num := to_number(nvl(v_curr_level_no, '0'));
   
   -- Parse new position
   v_new_terminal := regexp_substr(l_new_position, '[^-]+', 1, 1);
   v_new_block    := regexp_substr(l_new_position, '[^-]+', 1, 2);
   v_new_lot_no   := regexp_substr(l_new_position, '[^-]+', 1, 3);
   v_new_row_no   := regexp_substr(l_new_position, '[^-]+', 1, 4);
   v_new_level_no := regexp_substr(l_new_position, '[^-]+', 1, 5);
    
   -- Lock both positions -- the slot being vacated and the slot being taken --
   -- before any of the stacking validation below reads them, so two operators
   -- restacking into the same slot cannot both pass.
   --
   -- The two identical row-constructor SELECTs are now one local procedure. Same
   -- statement twice with ten interleaved variables is where a copy-paste slip
   -- (curr where new belongs) hides in plain sight, and that slip would lock the
   -- wrong slot while appearing to work.
   --
   -- ORA-00054 propagates to the outer handler as a 409; NO_DATA_FOUND means the
   -- position does not exist at this site, which is a genuine 400 and is left to
   -- the same handler with a message that says so.
   declare
      l_dummy number;

      procedure lock_position (
         p_terminal varchar2,
         p_block    varchar2,
         p_lot_no   varchar2,
         p_row_no   varchar2,
         p_level_no varchar2,
         p_which    varchar2
      ) is
      begin
         select 1
           into l_dummy
           from xxotm_position_master_t
          where terminal = p_terminal
            and block = p_block
            and lot_no = p_lot_no
            and row_no = p_row_no
            and level_no = p_level_no
            and xxotm_position_master_t.location = v_location
         for update nowait;
      exception
         when no_data_found then
            raise_application_error(
               -20011,
               'The ' || p_which || ' position ' || p_terminal || '-' || p_block
               || '-' || p_lot_no || '-' || p_row_no || '-' || p_level_no
               || ' does not exist at this location.'
            );
      end lock_position;
   begin
      lock_position(
         v_curr_terminal,
         v_curr_block,
         v_curr_lot_no,
         v_curr_row_no,
         v_curr_level_no,
         'current'
      );

      lock_position(
         v_new_terminal,
         v_new_block,
         v_new_lot_no,
         v_new_row_no,
         v_new_level_no,
         'target'
      );
   end;

    begin
--    select container_nbr
--      into l_curr_container
--      from xxotm_position_master_t
--     where terminal = v_curr_terminal
--       and block    = v_curr_block
--       and lot_no   = v_curr_lot_no
--       and row_no   = v_curr_row_no
--       and level_no = v_curr_level_no;
    
    select TERMINAL||'-'||BLOCK ||'-'||LOT_NO ||'-'||ROW_NO ||'-'||LEVEL_NO into l_val_position from xxotm_position_master_t where container_nbr = l_container_nbr
    and xxotm_position_master_t.location = v_location;

    if l_val_position is not null then
       if  replace(l_val_position,' ','') != replace(l_current_position,' ','') then
          raise_application_error(
             -20010,
            'Container ' || l_container_nbr || ' is not available at location ' || l_current_position || '. Please refresh and try again.'
          );
       end if;
   end if;
    exception
       when no_data_found then
          raise_application_error(
             -20010,
             'Container ' || l_container_nbr || ' is not available at location ' || l_current_position || '. Please refresh and try again.'
          );
          when others then 
          null;
    end;

   -- CRITICAL: Check containers above current position
   begin
      select container_nbr into l_blocking_container
      from xxotm_position_master_t
      where terminal = v_curr_terminal
        and block = v_curr_block
        and lot_no = v_curr_lot_no
        and row_no = v_curr_row_no
        and level_no > v_curr_level_no
        and shipment_nbr is not null
        and xxotm_position_master_t.location = v_location
      fetch first 1 rows only;
     if  l_blocking_container is not null then
      raise_application_error(-20010, 'Cannot restack. Container ' || l_blocking_container || ' is stacked above.');
      end if;
   exception
      when no_data_found then null; -- Safe to proceed
   end;
   
   -- Validate target slot is empty
   declare v_exists number;
   begin
      select count(*) into v_exists
      from xxotm_position_master_t
      where terminal = v_new_terminal
        and block = v_new_block
        and lot_no = v_new_lot_no
        and row_no = v_new_row_no
        and level_no = v_new_level_no
        and container_nbr is not null
        and xxotm_position_master_t.location = v_location;
        
      if v_exists > 0 then
         raise_application_error(-20001, 'Target slot already occupied');
      end if;
   end;
   

   
   -- Additional stacking validation (check levels 1-6 above current)
   if v_curr_level_num < 6 then
      for check_level in (v_curr_level_num + 1)..6 loop
         declare
            l_check_position varchar2(200);
            l_found_container varchar2(100);
         begin
            l_check_position := v_curr_terminal || '-' || v_curr_block || '-' || 
                               v_curr_lot_no || '-' || v_curr_row_no || '-' || check_level;
            
            select container_nbr into l_found_container
            from xxotm_container_inventory_t
            where position = l_check_position
              and container_stored_time is not null
              and container_released_time is null
            --   and shipment_name like '%INBOUND%'
            and rownum = 1
            and xxotm_container_inventory_t.location = v_location;
            
            l_blocking_container := l_found_container;
            l_blocking_level := check_level;
            l_has_blocking := true;
            exit;
         exception
            when no_data_found then null;
         end;
      end loop;
      
      if l_has_blocking then
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'RESTACK',
            p_procedure_name => 'XX_OTM_POST_RESTACKCONTAINER',
            p_action         => 'RESTACK',
            p_entity_type    => 'CONTAINER',
            p_entity_id      => l_container_nbr,
            p_secondary_id   => l_current_position,
            p_response_code  => 400,
            p_message        => 'Blocked by ' || l_blocking_container
                                || ' at level ' || l_blocking_level,
            p_location       => v_location);
         apex_json.write('response_code', 400);
         apex_json.write('response_message',
            'Cannot restack at level ' || v_curr_level_num ||
            '. Container ' || l_blocking_container || ' above at level ' || l_blocking_level);
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         return;
      end if;
   end if;
   
   -- BUSINESS LOGIC: Perform restack
   begin
                -- DOUBLE CHECK (failsafe)
            declare v_cnt number;
            begin
                select count(*) into v_cnt
                from xxotm_position_master_t
                where terminal = v_new_terminal
                  and block = v_new_block
                  and lot_no = v_new_lot_no
                  and row_no = v_new_row_no
                  and level_no = v_new_level_no
                  and container_nbr is not null
                  and xxotm_position_master_t.location = v_location;

                if v_cnt > 0 then
                    raise_application_error(-20003, 'Slot became occupied during processing');
                end if;
            end;
      -- Log to LOLO table
      insert into xxotm_restack_lolo_t (
         container_nbr, current_position, restack_position, 
         updated_date, inbound_shipment_nbr
      ) values (
         l_container_nbr, l_current_position, l_new_position, 
         l_timestamp, l_shipment_nbr
      );
      
      -- Update inventory position
      update xxotm_container_inventory_t
      set position = l_new_position
      where container_nbr = l_container_nbr
        and inbound_shipment_nbr = l_shipment_nbr
        and xxotm_container_inventory_t.location = v_location;
      
      v_inv_rows := sql%rowcount;
      
      -- FREE CURRENT POSITION
      update xxotm_position_master_t
      set shipment_nbr = null,
          container_nbr = null,
          is_occupied = 'N',
          last_event_time = systimestamp,
          last_event_source = 'MOBILE'
      where
    --    terminal = v_curr_terminal
    --     and block = v_curr_block
    --     and lot_no = v_curr_lot_no
    --     and row_no = v_curr_row_no
    --     and level_no = v_curr_level_no and 
        container_nbr = l_container_nbr and shipment_nbr = l_shipment_nbr
        and xxotm_position_master_t.location = v_location;
      
 INSERT INTO xx_otm_sync_logs (
      procedure_name, message_type, message_text, reference_id
   ) VALUES (
      'XX_OTM_POST_RESTACKCONTAINER',
      'INFO',
      'Freed position master for container: ' || l_container_nbr || ' at ' || v_curr_terminal||'-'||v_curr_block||'-'||v_curr_lot_no||'-'||v_curr_row_no||'-'||v_curr_level_no,
      l_shipment_nbr
   );

      -- OCCUPY NEW POSITION
      update xxotm_position_master_t
      set shipment_nbr = l_shipment_nbr,
          container_nbr = l_container_nbr,
          is_occupied = l_container_nbr,
          last_event_time = systimestamp,
          last_event_source = 'MOBILE'
      where terminal = v_new_terminal
        and block = v_new_block
        and lot_no = v_new_lot_no
        and row_no = v_new_row_no
        and level_no = v_new_level_no
        and xxotm_position_master_t.location = v_location;
     
      INSERT INTO xx_otm_sync_logs (
      procedure_name, message_type, message_text, reference_id
   ) VALUES (
      'XX_OTM_POST_RESTACKCONTAINER',
      'INFO',
      'Updated position master for container: ' || l_container_nbr || ' at ' || v_new_terminal||'-'||v_new_block||'-'||v_new_lot_no||'-'||v_new_row_no||'-'||v_new_level_no,
      l_shipment_nbr
   );
      commit;
      
      -- Send OTM tracking event
       begin

         post_otm_tracking_events(
            p_integration_name => 'XX_OTM_RESTACK_CONTAINER',
            p_statuscodegid    => 'NAQLEEN.CONTAINER_RESTACKED',
            p_shipmentxid      => l_shipment_nbr,
            p_attribute3      => l_container_nbr,
            p_attribute1       => l_new_position,
            x_response         => l_api_response
         );

         if l_api_response like '%Error%' then
            raise_application_error(-20002,l_api_response);
         end if;

       end;
      l_audit_code := 200;
      l_audit_msg  := l_current_position || ' -> ' || l_new_position;
      apex_json.write('response_code', 200);
      apex_json.write('response_message', 'Container restacked successfully');
   exception
      when others then
         rollback;
         l_audit_code := 500;
         l_audit_msg  := sqlerrm;
         apex_json.write('response_code', 500);
         apex_json.write('response_message', 'Restack failed: ' || regexp_replace(sqlerrm, '^ORA-[0-9]+:\s*', ''));
   end;

   -- AUDIT. Both inner branches converge here.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'RESTACK',
      p_procedure_name => 'XX_OTM_POST_RESTACKCONTAINER',
      p_action         => 'RESTACK',
      p_entity_type    => 'CONTAINER',
      p_entity_id      => l_container_nbr,
      p_secondary_id   => l_shipment_nbr,
      p_response_code  => l_audit_code,
      p_message        => l_audit_msg,
      p_location       => v_location);

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);

exception
   when e_row_locked then
      -- ORA-00054 from either lock_position call. Another operator is mid-restack
      -- on one of these two slots. 409, not 400: the request was well formed and
      -- retrying it shortly is the correct response, which is not what a 400
      -- tells the client. Previously this fell into the handler below and the
      -- operator was shown the raw Oracle text.
      rollback;
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'RESTACK',
         p_procedure_name => 'XX_OTM_POST_RESTACKCONTAINER',
         p_action         => 'RESTACK',
         p_entity_type    => 'CONTAINER',
         p_entity_id      => l_container_nbr,
         p_secondary_id   => l_new_position,
         p_response_code  => 409,
         p_message        => 'Position locked by another operator: ' || sqlerrm,
         p_location       => v_location);
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 409);
      apex_json.write('response_message',
         'Another operator is moving a container in one of these positions. '
         || 'Try again in a moment.');
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
   when others then
      rollback;
      -- Reached when validation above raised (-20010 slot occupied, container
      -- not at the stated position, target slot taken, -20011 position unknown
      -- at this site).
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'RESTACK',
         p_procedure_name => 'XX_OTM_POST_RESTACKCONTAINER',
         p_action         => 'RESTACK',
         p_entity_type    => 'CONTAINER',
         p_entity_id      => l_container_nbr,
         p_secondary_id   => l_new_position,
         p_response_code  => 400,
         p_message        => sqlerrm,
         p_location       => v_location);
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 400);
      apex_json.write('response_message', regexp_replace(sqlerrm, '^ORA-[0-9]+:\s*', ''));
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
end xx_otm_post_restackcontainer;

   -- ========================================================================
   -- XX_OTM_POST_STUFFING_CONTAINER   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_STUFFING_CONTAINER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_stuffing_container (
   payload in blob,
   p_user_id in varchar2 default null
)
is
    v_location varchar2(100);
    -- Created Date : 05-Jan-2026
    -- Description  : Submits stuffing results. 
    --               1. Updates stuffed_qty for items in local inventory.
    --               2. Posts STUFFED tracking event with seal number to OTM.
    --               3. Updates container area to 'CFS' in local staging.
    --               4. Reduces customer stock available quantity.
    --               5. Validates no containers are stacked above this container.

   p_payload          clob;
   l_container_number varchar2(50);
   l_customer_nbr     varchar2(100);
   l_shipment_number  varchar2(100);
   l_seal_number      varchar2(100);
   l_item_code        varchar2(20);
   l_stuffed_quantity number;
   l_status_code      varchar2(100) := 'NAQLEEN.STUFFED';
   l_items_updated    number := 0;
   l_events_posted    number := 0;
   l_item_count       number;
   l_cont_no          varchar2(100);
   l_response_out     clob;
   l_cfs_count        number;
   l_error_msg        varchar2(4000);
   l_attribute4       varchar2(100);
   l_shipment_name    varchar2(200); -- Added to check shipment type
   l_containers_above number := 0;   -- Added to check stacking constraints
   l_restacking_shipment_nbr varchar2(100);
   
      l_current_position   varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- 1. Payload Conversion
   p_payload := to_clob(payload);
    
    -- 2. Initial Response Setup
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- 3. JSON Parsing
   begin
      apex_json.parse(p_payload);
   exception
      when others then
         raise_application_error(
            -20001,
            'Invalid JSON payload: ' || sqlerrm
         );
   end;

    -- 4. Extract Header Fields from standardized JSON paths
   l_container_number := apex_json.get_varchar2('container_nbr');
   l_shipment_number := apex_json.get_varchar2('shipment_nbr');
   l_customer_nbr := apex_json.get_varchar2('customer_nbr');
   l_seal_number := apex_json.get_varchar2('seal_nbr');



      -- =====================================================
   -- STACKING VALIDATION: Check for containers above current position
   -- =====================================================
   declare
      v_curr_terminal      varchar2(50);
      v_curr_block         varchar2(50);
      v_curr_row_no        varchar2(50);
      v_curr_lot_no        varchar2(50);
      v_curr_level_no      varchar2(50);
      v_curr_level_num     number;
      l_blocking_container varchar2(100);
      l_blocking_level     number;
      l_has_blocking       boolean := false;
   begin
      if l_container_number is not null then
         -- Get current position from inventory
         begin
            select position,inbound_shipment_nbr
              into l_current_position,l_restacking_shipment_nbr
              from xxotm_container_inventory_t
             where container_nbr = l_container_number
               and container_stored_time is not null
               and container_released_time is null
                and xxotm_container_inventory_t.location = v_location
               and rownum = 1;
         exception
            when no_data_found then
               l_current_position := null;
         end;

         if l_current_position is not null then
            -- Parse position: terminal-block-lot_no-row_no-level_no
            v_curr_terminal := regexp_substr(
               l_current_position,
               '[^-]+',
               1,
               1
            );
            v_curr_block := regexp_substr(
               l_current_position,
               '[^-]+',
               1,
               2
            );
            v_curr_lot_no := regexp_substr(
               l_current_position,
               '[^-]+',
               1,
               3
            );
            v_curr_row_no := regexp_substr(
               l_current_position,
               '[^-]+',
               1,
               4
            );
            v_curr_level_no := regexp_substr(
               l_current_position,
               '[^-]+',
               1,
               5
            );
            begin
               v_curr_level_num := to_number ( v_curr_level_no );
            exception
               when others then
                  v_curr_level_num := 6;
            end;

            if v_curr_level_num < 6 then
               for check_level in ( v_curr_level_num + 1 )..6 loop
                  declare
                     l_check_position  varchar2(200);
                     l_found_container varchar2(100);
                  begin
                     l_check_position := v_curr_terminal
                                         || '-'
                                         || v_curr_block
                                         || '-'
                                         || v_curr_lot_no
                                         || '-'
                                         || v_curr_row_no
                                         || '-'
                                         || to_char(check_level);
                     select container_nbr
                       into l_found_container
                       from xxotm_container_inventory_t
                      where position = l_check_position
                        and container_stored_time is not null
                        and container_released_time is null and xxotm_container_inventory_t.location = v_location
                        and rownum = 1;

                     l_blocking_container := l_found_container;
                     l_blocking_level := check_level;
                     l_has_blocking := true;
                     exit;
                  exception
                     when no_data_found then
                        null;
                  end;
               end loop;

               if l_has_blocking then
                  xxotm_log_activity(
                     p_user_id        => p_user_id,
                     p_module         => 'STUFFING',
                     p_procedure_name => 'XX_OTM_POST_STUFFING_CONTAINER',
                     p_action         => 'STUFF',
                     p_entity_type    => 'CONTAINER',
                     p_entity_id      => l_container_number,
                     p_secondary_id   => l_shipment_number,
                     p_response_code  => 400,
                     p_message        => 'Blocked by ' || l_blocking_container
                                         || ' at level ' || l_blocking_level,
                     p_location       => v_location);
                  apex_json.write(
                     'response_code',
                     400
                  );
                  apex_json.write(
                     'response_message',
                     'Cannot destuff container '
                     || l_container_number
                     || '. Container '
                     || l_blocking_container
                     || ' is stacked above at level '
                     || l_blocking_level
                     || '. Please restack the container above first.'
                  );
                  apex_json.close_object;
                  htp.prn(apex_json.get_clob_output);
                  apex_json.free_output;
                  return;
               end if;
            end if;
         end if;
      end if;
   exception
      when others then
         null; -- Log invalid validation attempt but proceed? strict: fail. loose: proceed. 
         -- Reusing strict logic: if validation fails technically, maybe best to log & ignore to avoid blocking valid ops.
   end;

    -- ------------------------------------------------------------
    -- OPERATION 1: Update Item Quantities and Customer Stock
    -- ------------------------------------------------------------
   l_item_count := apex_json.get_count('items');
   if l_item_count > 0 then
      for i in 1..l_item_count loop
         l_item_code := apex_json.get_varchar2(
            'items[%d].item_code',
            i
         );
         l_stuffed_quantity := apex_json.get_number(
            'items[%d].stuffed_quantity',
            i
         );
         update xxotm_customer_inventory_t
            set
            stuffed_qty = l_stuffed_quantity
          where shipment_nbr = l_shipment_number
            and item_code = l_item_code  and xxotm_customer_inventory_t.location = v_location;

         if sql%rowcount > 0 then
            l_items_updated := l_items_updated + 1;
         end if;
         
         -- Reduce customer stock quantity
         update xxotm_customer_stock_t
            set
            available_qty = available_qty - to_number(l_stuffed_quantity)
          where cust_nbr = l_customer_nbr
            and item_code = l_item_code  and xxotm_customer_stock_t.location = v_location;

      end loop;
   end if;

   begin
      select container_nbr
        into l_cont_no
        from xxotm_customer_inventory_t
       where shipment_nbr = l_shipment_number  and xxotm_customer_inventory_t.location = v_location
       fetch first 1 rows only;
   exception
      when others then
         null;
   end;
    
    -- Consolidate container number logic
   if l_container_number is null then
      l_container_number := l_cont_no;
   end if;

    -- Fetch Shipment Name for Conditional Logic
   begin
      select shipment_name
        into l_shipment_name
        from xxotm_shipments_t
       where shipment_xid = l_shipment_number
       and xxotm_shipments_t.location = v_location;
   exception
      when others then
         l_shipment_name := null;
   end;
   

    -- ------------------------------------------------------------
    -- OPERATION 2: Post STUFFED Event with Seal Number
    -- ------------------------------------------------------------
   
   -- Determine attribute4 logic: 'LOADED' only if container exists AND shipment is CROSS_STUFFING
   if
      l_container_number is not null
   then
      l_attribute4 := 'LOADED';
   else
      l_attribute4 := null;
   end if;

   begin
      post_otm_tracking_events(
         p_integration_name => 'XX_OTM_POST_STUFFING_CONTAINER',
         p_statuscodegid    => l_status_code,
         p_shipmentxid      => l_shipment_number,
         p_attribute2       => l_seal_number, -- Seal number goes to attribute2 for STUFFED
         p_attribute3       => l_container_number,
         p_attribute4       => l_attribute4, -- Conditional LOADED based on CROSS_STUFFING
         x_response         => l_response_out
      );

      if l_response_out not like 'Error%' then
         l_events_posted := 1;
      else
         l_error_msg := 'OTM Event Error: '
                        || substr(
            l_response_out,
            1,
            200
         );
      end if;
   exception
      when others then
         dbms_output.put_line('Event Posting Error: ' || sqlerrm);
         l_error_msg := 'OTM Event Exception: ' || sqlerrm;
   end;

    -- Post RESTACKED event ONLY if container number exists AND shipment is CROSS_STUFFING
   if
      l_container_number is not null
      and l_restacking_shipment_nbr is not null
   then
      begin
         post_otm_tracking_events(
            p_statuscodegid => 'NAQLEEN.CONTAINER_RESTACKED',
            p_shipmentxid   => l_restacking_shipment_nbr,
            p_attribute1    => 'CFS',
            x_response      => l_response_out
         );

         if l_response_out not like 'Error%' then
            l_events_posted := 1;

              -- ------------------------------------------------------------
         -- NEW REQUIREMENT: Update Position Master to Free Slot
         -- ------------------------------------------------------------
         if
            l_events_posted > 0
            and l_current_position is not null
         then
            declare
               v_p_terminal varchar2(50);
               v_p_block    varchar2(50);
               v_p_lot_no   varchar2(50);
               v_p_row_no   varchar2(50);
               v_p_level_no varchar2(50);
            begin
               v_p_terminal := regexp_substr(
                  l_current_position,
                  '[^-]+',
                  1,
                  1
               );
               v_p_block := regexp_substr(
                  l_current_position,
                  '[^-]+',
                  1,
                  2
               );
               v_p_lot_no := regexp_substr(
                  l_current_position,
                  '[^-]+',
                  1,
                  3
               );
               v_p_row_no := regexp_substr(
                  l_current_position,
                  '[^-]+',
                  1,
                  4
               );
               v_p_level_no := regexp_substr(
                  l_current_position,
                  '[^-]+',
                  1,
                  5
               );
               update xxotm_position_master_t
                  set is_occupied = 'N',
                        shipment_nbr = null,
                        container_nbr = null,
                      LAST_EVENT_TIME = systimestamp
                where terminal = v_p_terminal
                  and block = v_p_block
                  and row_no = v_p_row_no
                  and lot_no = v_p_lot_no
                  and level_no = v_p_level_no
                  and xxotm_position_master_t.location = v_location;
                 
                 update xxotm_container_inventory_t set position = 'CFS'
             where container_nbr = l_container_number and inbound_shipment_nbr = l_restacking_shipment_nbr
               and container_stored_time is not null
               and container_released_time is null
               and xxotm_container_inventory_t.location = v_location;
            exception
               when others then
                  dbms_output.put_line('Error updating position master: ' || sqlerrm);
                  -- Log but don't fail the transaction as main events succeeded?
                  l_error_msg := l_error_msg
                                 || ' | Position Update Error: '
                                 || sqlerrm;
            end;
         end if;

         else
            l_error_msg := l_error_msg
                           || ' | Restack Event Error: '
                           || substr(
               l_response_out,
               1,
               200
            );
         end if;
      exception
         when others then
            dbms_output.put_line('Event Posting Error: ' || sqlerrm);
            l_error_msg := l_error_msg
                           || ' | Restack Event Exception: '
                           || sqlerrm;
      end;
   end if;

    -- ------------------------------------------------------------
    -- OPERATION 3: Update Container Area to CFS
    -- ------------------------------------------------------------
   if l_container_number is not null then
      begin
         select count(*)
           into l_cfs_count
           from xxotm_cfs_containers_t
          where shipment_nbr = l_shipment_number
            and container_nbr = l_container_number  and xxotm_cfs_containers_t.location = v_location;

         if l_cfs_count = 0 then
            insert into xxotm_cfs_containers_t (
               shipment_nbr,
               container_nbr,
               creation_date
               , location
) values ( l_shipment_number,
                       l_container_number,
                       to_char(
                          sys_extract_utc(systimestamp),
                          'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
                       )
                       , v_location
);
         end if;
      exception
         when others then
            l_error_msg := 'Error: CFS Container insert check failed: '
                           || sqlerrm
                           || '. ';
      end;
   end if;
    -- AUDIT. 200 when anything landed (items updated OR an OTM event posted),
    -- 404 when neither did. l_error_msg carries the OTM failure text on the
    -- partial case, which is the one worth finding later.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'STUFFING',
      p_procedure_name => 'XX_OTM_POST_STUFFING_CONTAINER',
      p_action         => 'STUFF',
      p_entity_type    => 'CONTAINER',
      p_entity_id      => l_container_number,
      p_secondary_id   => l_shipment_number,
      p_response_code  => case when l_items_updated > 0 or l_events_posted > 0
                               then 200 else 404 end,
      p_message        => nvl(l_error_msg, 'items=' || l_items_updated
                                           || ' events=' || l_events_posted),
      p_location       => v_location);

    -- 5. Finalize Transaction and Build Response
   if l_items_updated > 0
   or l_events_posted > 0 then
      commit;
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         nvl(
            l_error_msg,
            'Success'
         )
      );
      apex_json.open_object('data');
      apex_json.write(
         'items_updated',
         l_items_updated
      );
      apex_json.write(
         'events_posted',
         l_events_posted
      );
      apex_json.write(
         'seal_number',
         l_seal_number
      );
      apex_json.close_object;
   else
      apex_json.write(
         'response_code',
         404
      );
      apex_json.write(
         'response_message',
         'No items updated and event posting failed. ' || l_error_msg
      );
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      rollback;
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'STUFFING',
         p_procedure_name => 'XX_OTM_POST_STUFFING_CONTAINER',
         p_action         => 'STUFF',
         p_entity_type    => 'CONTAINER',
         p_entity_id      => l_container_number,
         p_secondary_id   => l_shipment_number,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'CRITICAL ERROR: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_stuffing_container;

   -- ========================================================================
   -- xx_otm_post_update_truck_status_apex   [? / ?]
   -- source: db/work/XX_OTM_POST_UPDATE_TRUCK_STATUS_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_update_truck_status_apex (
   payload   in blob,
   p_user_id in varchar2 default null
)
is
   v_location        varchar2(100);
   p_payload         clob;
   l_status          varchar2(100);
   l_truck_number    varchar2(100);
   l_entry_timestamp timestamp;
   l_response        json_object_t;
   l_updated_count   number := 0;
   l_not_found_count number := 0;
   l_output          clob;
   l_array_count     number;
begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
    -- Convert the BLOB payload to a CLOB
   p_payload := to_clob(payload);

    -- Parse the JSON payload
   apex_json.parse(p_payload);

    -- Extract the status
   l_status := apex_json.get_varchar2(p_path => 'status');

    -- Get count of trucks array
   l_array_count := apex_json.get_count(p_path => 'trucks');

    -- Initialize the response object
   l_response := json_object_t();
   begin


        -- Loop through each truck in the array
      for i in 1..l_array_count loop
            -- Extract truck details
         l_truck_number := apex_json.get_varchar2(
            p_path => 'trucks[%d].truck_number',
            p0     => i
         );
         if upper(l_status) = 'LCL' then
            update xxotm_vehicle_master_t
               set status = 'gate_in',
                   order_type = 'LCL',
                   user_id = p_user_id
             where truck_nbr = l_truck_number
               and xxotm_vehicle_master_t.location = v_location
               and entry_time = (
               select max(entry_time)
                 from xxotm_vehicle_master_t
                where truck_nbr = l_truck_number
                  and xxotm_vehicle_master_t.location = v_location
            )
               and status = 'vehicle_entry';

            if sql%rowcount > 0 then
               l_updated_count := l_updated_count + 1;
            else
               l_not_found_count := l_not_found_count + 1;
            end if;
         elsif upper(l_status) = 'GATE_EXIT' then
            update xxotm_vehicle_master_t
               set status = 'gate_exit',
                   exit_time = to_char(
                      sys_extract_utc(systimestamp),
                      'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
                   )
             where truck_nbr = l_truck_number
               and xxotm_vehicle_master_t.location = v_location
               and entry_time = (
               select max(entry_time)
                 from xxotm_vehicle_master_t
                where truck_nbr = l_truck_number
                  and xxotm_vehicle_master_t.location = v_location
            );

            if sql%rowcount > 0 then
               l_updated_count := l_updated_count + 1;
            else
               l_not_found_count := l_not_found_count + 1;
            end if;
         else
            update xxotm_vehicle_master_t
               set status = l_status,
                   user_id = p_user_id
             where truck_nbr = l_truck_number
               and xxotm_vehicle_master_t.location = v_location
               and entry_time = (
               select max(entry_time)
                 from xxotm_vehicle_master_t
                where truck_nbr = l_truck_number
                  and xxotm_vehicle_master_t.location = v_location
            )
               and status = 'vehicle_entry';

            if sql%rowcount > 0 then
               l_updated_count := l_updated_count + 1;
            else
               l_not_found_count := l_not_found_count + 1;
            end if;
         end if;
      end loop;

      commit;

        -- Set response based on results
      if
         l_updated_count > 0
         and l_not_found_count = 0
      then
         l_response.put(
            'response_code',
            200
         );
         l_response.put(
            'response_message',
            'Success'
         );
      else
         l_response.put(
            'response_code',
            404
         );
         l_response.put(
            'response_message',
            'Truck not found or status updated by another operator.'
         );
      end if;

   exception
      when others then
         rollback;
         l_response.put(
            'response_code',
            400
         );
         l_response.put(
            'response_message',
            'ERROR: ' || sqlerrm
         );
   end;

    -- Build JSON output using apex_json
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      l_response.get_number('response_code')
   );
   apex_json.write(
      'response_message',
      l_response.get_string('response_message')
   );
   apex_json.close_object;

    -- Get output
   l_output := apex_json.get_clob_output;

    -- Print output
   htp.prn(l_output);
   apex_json.free_output;
end xx_otm_post_update_truck_status_apex;

   -- ========================================================================
   -- XX_OTM_POST_VEHICLE_ENTRY_APEX   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_VEHICLE_ENTRY_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_vehicle_entry_apex (
        payload IN BLOB,
        p_user_id in varchar2 default null
    )
IS
        v_location varchar2(100);

        p_payload             CLOB;
        l_truck_number        VARCHAR2(100);
        l_power_unit_truck    VARCHAR2(100);
        l_driver_name         VARCHAR2(100);
        l_iqama_number        VARCHAR2(100);
        l_driver_phone_number VARCHAR2(200);
        l_entry_time          VARCHAR2(100);
        l_exit_time           VARCHAR2(100);
        l_status              VARCHAR2(200);
        l_response            json_object_t;
    BEGIN
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Blob payload to Clob type conversion
        p_payload := to_clob(payload);
        apex_json.initialize_clob_output;
        apex_json.open_object;

    -- Parse the JSON payload
        apex_json.parse(p_payload);

    -- Extract values from the JSON payload
        l_truck_number := apex_json.get_varchar2(p_path => 'truck_number');
        l_driver_name := apex_json.get_varchar2(p_path => 'driver_name');
        l_iqama_number := apex_json.get_varchar2(p_path => 'iqama_number');
        l_driver_phone_number := apex_json.get_varchar2(p_path => 'driver_phone_number');
        l_entry_time := apex_json.get_varchar2(p_path => 'entry_time');

    -- Initialize the response object
        l_response := json_object_t();
        BEGIN
            SELECT DISTINCT
                truck_nbr
            INTO l_power_unit_truck
            FROM
                xxotm_power_units_t
            WHERE
                truck_nbr = l_truck_number;

        EXCEPTION
            WHEN OTHERS THEN
                l_power_unit_truck := NULL;
        END;

    -- Check if the truck number exists in the vehicle master table
        BEGIN
        -- Try to find an existing truck number
            SELECT
                truck_nbr
            INTO l_truck_number
            FROM
                xxotm_vehicle_master_t
            WHERE
                truck_nbr = l_truck_number and exit_time is null
                and xxotm_vehicle_master_t.location = v_location;


        -- If found, no need to insert, just set response and return
        l_response.put('response_code', 500);
        l_response.put('response_message', 'Truck Already Inside - Cannot Re-enter');

        EXCEPTION
            WHEN no_data_found THEN
            -- Truck number not found, insert new entry
                INSERT INTO xxotm_vehicle_master_t (
                    truck_nbr,
                    driver_iqama,
                    driver_name,
                    entry_time,
                    exit_time,
                    type,
                    status
                    , location
                    , user_id
) VALUES ( l_truck_number,
                           l_iqama_number,
                           l_driver_name,
                           l_entry_time,
                           NULL,  -- You can adjust exit_time if you have a value in payload
                           CASE
                               WHEN l_power_unit_truck IS NOT NULL THEN
                                   'Own'
                               ELSE
                                   '3PL'
                           END,  -- You can replace 'unknown' with a type based on payload
                           'vehicle_entry'   -- Status is set as '200' as requested
                           , v_location
                           , p_user_id
);

            -- Set the response code and message
                l_response.put('response_code', 200);
                l_response.put('response_message', 'Truck Check-In Completed Successfully');
        END;

    -- AUDIT. Both branches set response_code before reaching here -- 500 when
    -- the truck is already inside, 200 on a fresh check-in -- so the same
    -- expression the response uses is safe to read.
        xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'SECURITY',
            p_procedure_name => 'XX_OTM_POST_VEHICLE_ENTRY_APEX',
            p_action         => 'ENTRY',
            p_entity_type    => 'TRUCK',
            p_entity_id      => l_truck_number,
            p_secondary_id   => l_iqama_number,
            p_response_code  => l_response.get('response_code').to_number(),
            p_message        => l_response.get('response_message').to_string(),
            p_location       => v_location);

    -- Output the JSON response
        apex_json.write('response_code',
                        l_response.get('response_code').to_number());
        apex_json.write('response_message',
                        replace(
                  l_response.get('response_message').to_string(),
                  '"',
                  ''
              ));

        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
    EXCEPTION
        WHEN OTHERS THEN
        -- Handle any other errors
            l_response.put('response_code', 400);
            l_response.put('response_message', sqlerrm);

            xxotm_log_activity(
                p_user_id        => p_user_id,
                p_module         => 'SECURITY',
                p_procedure_name => 'XX_OTM_POST_VEHICLE_ENTRY_APEX',
                p_action         => 'ENTRY',
                p_entity_type    => 'TRUCK',
                p_entity_id      => l_truck_number,
                p_response_code  => 400,
                p_message        => sqlerrm,
                p_location       => v_location);

        -- Output the error JSON response
            apex_json.write('response_code',
                            l_response.get('response_code').to_number());
            apex_json.write('response_message',
                            replace(
                      l_response.get('response_message').to_string(),
                      '"',
                      ''
                  ));

            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
    END XX_OTM_POST_VEHICLE_ENTRY_APEX;

   -- ========================================================================
   -- XX_OTM_POST_VEHICLE_EXIT_APEX   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_POST_VEHICLE_EXIT_APEX.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_post_vehicle_exit_apex (
   payload in blob,
   p_user_id in varchar2 default null
)
is
    v_location varchar2(100);
    -- Last Updated Date : 05-Feb-2026
    -- Description : Updated to check ALL associated shipments for GATE OUT but no VEHICLE EXIT
    --               and send events to ALL of them.

   p_payload              clob;
   l_truck_number         varchar2(100);
   l_exit_time            varchar2(100);
   l_response             json_object_t;
    
    -- Shipment processing
   type t_shipment_tab is
      table of varchar2(200) index by pls_integer;
   l_candidate_shipments  t_shipment_tab;
   l_valid_shipments      t_shipment_tab; -- Store all valid shipments
   l_shipment_list        varchar2(32767);
   l_valid_count          number := 0;
    
    -- API variables
   l_http_status          number;
   l_response_clob        clob;
   l_api_url              varchar2(32767);
   l_credential_static_id varchar(20) := 'OTM_API_AUTH';
    
    -- JSON parsing
   l_items_count          number;
   l_events_count         number;
   l_shipment_xid         varchar2(200);
   l_status_code          varchar2(200);
    
    -- Flags
   l_has_gate_out         boolean;
   l_has_vehicle_exit     boolean;
   l_found_valid_shipment boolean := false;
    
    -- Loop vars
   i                      number;
   j                      number;
   k                      number;
begin
    v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Convert Payload
   p_payload := to_clob(payload);
   apex_json.initialize_clob_output;
   apex_json.open_object;

    -- Parse JSON
   apex_json.parse(p_payload);
   l_truck_number := apex_json.get_varchar2(p_path => 'truck_number');
   l_exit_time := apex_json.get_varchar2(p_path => 'exit_time');
   l_response := json_object_t();
   dbms_output.put_line('Truck Number: ' || l_truck_number);

    -- 1. Gather ALL Candidate Shipments
   select s.shipment_xid
   bulk collect
     into l_candidate_shipments
     from xxotm_vehicle_master_t vm
     join xxotm_shipments_t s
   on (
    --  vm.truck_nbr = s.power_unit
    --    or
        vm.truck_nbr = s.truck_3pl )
    where vm.truck_nbr = l_truck_number
      and vm.location   = v_location
      and s.location    = v_location
      and vm.entry_time = (
      select max(entry_time)
        from xxotm_vehicle_master_t v
       where v.truck_nbr = l_truck_number
         and v.location  = v_location
   )
    order by s.update_date desc;

   if l_candidate_shipments.count > 0 then
        -- Build CSV list for API (Batch)
      l_shipment_list := '';
      for i in 1..l_candidate_shipments.count loop
         if l_shipment_list is null then
            l_shipment_list := '"'
                               || l_candidate_shipments(i)
                               || '"';
         else
            l_shipment_list := l_shipment_list
                               || ',"'
                               || l_candidate_shipments(i)
                               || '"';
         end if;
      end loop;
        
        -- 2. Call OTM API for Tracking Events (Batch)
        -- Query: shipmentXid in [LIST] & expand=trackingEvents
      l_api_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                   || '?q='
                   || 'shipmentXid in ['
                   || l_shipment_list
                   || ']'
                   || ' and (attribute7 eq "'
                   || l_truck_number
                   || '"'
                   || ' or powerUnitGid co "'
                   || l_truck_number
                   || '")'
                   || '&expand=refnums,trackingEvents'
                   || '&limit=1000'
                   || '&fields=shipmentXid,trackingEvents';

      dbms_output.put_line('API URL: ' || l_api_url);
      apex_web_service.g_request_headers.delete;
      apex_web_service.g_request_headers(1).name := 'Content-Type';
      apex_web_service.g_request_headers(1).value := 'application/json';
      begin
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => l_api_url,
            p_http_method          => 'GET',
            p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         l_http_status := apex_web_service.g_status_code;
         if l_http_status = 200 then
            apex_json.parse(l_response_clob);
            l_items_count := apex_json.get_count('items');
            if l_items_count is null then
               l_items_count := 0;
            end if;
                
                -- 3. Iterate Shipments to Find ALL Targets
            for i in 1..l_items_count loop
               l_shipment_xid := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );
               l_has_gate_out := false;
               l_has_vehicle_exit := false;
               l_events_count := apex_json.get_count(
                  'items[%d].trackingEvents.items',
                  i
               );
               if l_events_count is null then
                  l_events_count := 0;
               end if;
               for j in 1..l_events_count loop
                  l_status_code := apex_json.get_varchar2(
                     'items[%d].trackingEvents.items[%d].statusCodeGid',
                     i,
                     j
                  );
                  if instr(
                     upper(l_status_code),
                     'GATE OUT'
                  ) > 0 then
                     l_has_gate_out := true;
                  end if;

                  if instr(
                     upper(l_status_code),
                     'VEHICLE EXIT'
                  ) > 0 then
                     l_has_vehicle_exit := true;
                  end if;
               end loop;
                    
                    -- CRITERIA: Has GATE OUT and NO VEHICLE EXIT
               if
                  l_has_gate_out
                  and not l_has_vehicle_exit
               then
                  l_valid_count := l_valid_count + 1;
                  l_valid_shipments(l_valid_count) := l_shipment_xid;
                  l_found_valid_shipment := true;
                  dbms_output.put_line('Found Valid Shipment: ' || l_shipment_xid);
               end if;
            end loop;
         end if;
      exception
         when others then
            dbms_output.put_line('API Error: ' || sqlerrm);
      end;
   end if;

    -- 4. Process Result
   if l_found_valid_shipment then
         -- Update Vehicle Master (Only need to update once for the truck)
      begin
       
             
             -- Post VEHICLE EXIT Event for ALL Valid Shipments
         for k in 1..l_valid_count loop
            declare
               l_evt_resp    clob;
               l_current_xid varchar2(200);
            begin
               l_current_xid := l_valid_shipments(k);
               dbms_output.put_line('Posting VEHICLE EXIT for: ' || l_current_xid);
               post_otm_tracking_events(
                  p_integration_name => 'XX_OTM_POST_VEHICLE_EXIT_APEX',
                  p_statuscodegid    => 'NAQLEEN.VEHICLE EXIT',
                  p_shipmentxid      => replace(
                     l_current_xid,
                     'NAQLEEN.',
                     ''
                  ),
                  x_response         => l_evt_resp
               );
            exception
               when others then
                  dbms_output.put_line('Event Post Error for '
                                       || l_current_xid
                                       || ': '
                                       || sqlerrm);
            end;
         end loop;

        update xxotm_vehicle_master_t
            set exit_time = l_exit_time,
                status = 'NAQLEEN.VEHICLE EXIT'
          where truck_nbr = l_truck_number
            and xxotm_vehicle_master_t.location   = v_location
            and entry_time = (select max(entry_time)
        from xxotm_vehicle_master_t v
       where v.truck_nbr = l_truck_number
         and v.location  = v_location) and exit_time is null;
         commit;


         l_response.put(
            'response_code',
            200
         );
         l_response.put(
            'response_message',
            'Success. Updated '
            || l_valid_count
            || ' shipments.'
         );
      exception
         when others then
            rollback;
            l_response.put(
               'response_code',
               500
            );
            l_response.put(
               'response_message',
               'Update Failed: ' || sqlerrm
            );
      end;
   else
      l_response.put(
         'response_code',
         404
      );
      l_response.put(
         'response_message',
         'No valid shipments found (Must have GATE OUT and no VEHICLE EXIT)'
      );
   end if;

    -- AUDIT. 200 with a count of shipments closed, 404 when no shipment
    -- qualified (gate out present, vehicle exit absent), 500 on update failure.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'SECURITY',
      p_procedure_name => 'XX_OTM_POST_VEHICLE_EXIT_APEX',
      p_action         => 'EXIT',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck_number,
      p_response_code  => to_number(l_response.get('response_code').to_string),
      p_message        => l_response.get('response_message').to_string(),
      p_location       => v_location);

    -- Output JSON
   apex_json.write(
      'response_code',
      to_number(l_response.get('response_code').to_string)
   );
    
    -- Safe cleanup string
   apex_json.write(
      'response_message',
      replace(
         l_response.get('response_message').to_string(),
         '"',
         ''
      )
   );
   apex_json.write(
      'debug_log',
      l_api_url
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'SECURITY',
         p_procedure_name => 'XX_OTM_POST_VEHICLE_EXIT_APEX',
         p_action         => 'EXIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck_number,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);

      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_post_vehicle_exit_apex;

   -- ========================================================================
   -- XX_OTM_RELEASE_CONTAINER_TRUCK_DETAILS   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_RELEASE_CONTAINER_TRUCK_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_release_container_truck_details (
   p_truck_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Last Updated Date : 08-Feb-2026
   -- Description : Sending huge repsonse in chunks
                
   -- Variables from vehicle master
   l_truck_nbr            varchar2(100);
   l_driver_name          varchar2(100);
   l_driver_iqama_nbr     varchar2(100);
   l_customer_nbr         varchar2(100);
   l_customer_name        varchar2(200);
   l_booking_nbr          varchar2(100);
   l_order_type           varchar2(50);
   l_found                boolean := false;
     l_data_clob  CLOB;
   l_final_clob CLOB;

   -- API variables
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_shipment_list        varchar2(32000);
   l_api_shipment_count   number;
   l_shipment_xid         varchar2(200);

   -- Collection for shipments per container type
   type t_shipment_tab is
      table of varchar2(200) index by pls_integer;
   l_shipments            t_shipment_tab;
   l_valid_shipments      t_shipment_tab;
   l_shipment_count       pls_integer;
   l_valid_count          pls_integer;

   -- Variables for RELEASE_CFS validation
   l_target_shipment_xid  varchar2(200);
   l_target_booking_id    varchar2(100);
   l_target_cust_nbr      varchar2(100);
   l_target_cust_name     varchar2(200);
   l_target_cont_nbr      varchar2(100);
   l_target_cont_type     varchar2(100);
   l_target_position      varchar2(100);
   l_cfs_found            boolean := false;
   
   -- Cursor for all potential CFS shipments
   cursor c_cfs_shipments is
   select s.shipment_xid,
          s.update_date
     from xxotm_shipments_t s
    where ( s.power_unit = p_truck_nbr
       or s.truck_3pl = p_truck_nbr )
      and s.shipment_name = 'RELEASE_CFS'
      and s.location = v_location
    order by s.update_date desc;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
--    dbms_output.put_line('=== START xx_otm_release_container_truck_details ===');
--    dbms_output.put_line('Input Truck Number: ' || p_truck_nbr);
   apex_json.initialize_clob_output;
   apex_json.open_object;

   -- Step 1: Search vehicle master for truck with GATE IN status
   begin
      select truck_nbr,
             driver_name,
             driver_iqama,
             replace(
                customer_nbr,
                'NAQLEEN.',
                ''
             ),
             customer_name,
             booking_id,
             order_type
        into
         l_truck_nbr,
         l_driver_name,
         l_driver_iqama_nbr,
         l_customer_nbr,
         l_customer_name,
         l_booking_nbr,
         l_order_type
        from xxotm_vehicle_master_t
       where truck_nbr = p_truck_nbr
         and entry_time is not null
         and exit_time is null
         and status like '%GATE IN%'  and xxotm_vehicle_master_t.location = v_location
       order by entry_time desc
       fetch first 1 rows only;
      l_found := true;
    --   dbms_output.put_line('Vehicle Master Found: ' || l_order_type);
   exception
      when no_data_found then
         l_found := false;
        --  dbms_output.put_line('ERROR: No vehicle master record found for truck ' || p_truck_nbr);
   end;

   if
      l_found
      and l_order_type in ( 'CRO',
                            'LRO' )
   then
      dbms_output.put_line('=== Processing '
                           || l_order_type
                           || ' ===');

      -- [Existing CRO/LRO Logic Unchanged]
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');
      apex_json.write(
         'truck_nbr',
         l_truck_nbr
      );
      apex_json.write(
         'driver_name',
         l_driver_name
      );
      apex_json.write(
         'driver_iqama_nbr',
         l_driver_iqama_nbr
      );
      apex_json.write(
         'customer_nbr',
         l_customer_nbr
      );
      apex_json.write(
         'customer_name',
         l_customer_name
      );
      apex_json.write(
         'booking_nbr',
         l_booking_nbr
      );
      apex_json.write(
         'order_type',
         l_order_type
      );
    --   DBMS_OUTPUT.PUT_LINE(l_booking_nbr||'-'||l_customer_name||'-'||l_customer_nbr||'-'||l_driver_iqama_nbr||'-'||l_truck_nbr);
      apex_json.open_object('container_types');
      if l_order_type = 'LRO' then
         for ct in (
            select distinct container_type
              from xxotm_container_inventory_t
             where cust_nbr = l_customer_nbr
               and booking_id = l_booking_nbr
               and container_type is not null
               and container_stored_time is not null
               and container_released_time is null
               and shipment_name like '%INBOUND_CONTAINER%'
               and xxotm_container_inventory_t.location = v_location
             order by container_type
         ) loop
            apex_json.open_object(ct.container_type);
            -- [API Logic for LRO Validated Shipments]
            l_shipment_count := 0;
            l_shipments.delete;
            for s in (
               select distinct inbound_shipment_nbr
                 from xxotm_container_inventory_t
                where cust_nbr = l_customer_nbr
                  and booking_id = l_booking_nbr
                  and container_type = ct.container_type
                  and inbound_shipment_nbr is not NULL
                  and shipment_name  = 'LRO'
                  and xxotm_container_inventory_t.location = v_location
            ) loop
               l_shipment_count := l_shipment_count + 1;
               l_shipments(l_shipment_count) := s.inbound_shipment_nbr;
            end loop;

            l_valid_count := 0;
            l_valid_shipments.delete;
            if l_shipment_count > 0 then
               l_shipment_list := '[';
               for i in 1..l_shipment_count loop
                  if i > 1 then
                     l_shipment_list := l_shipment_list || ',';
                  end if;
                  l_shipment_list := l_shipment_list
                                     || '"'
                                     || l_shipments(i)
                                     || '"';
               end loop;
               l_shipment_list := l_shipment_list || ']';
               l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                        || '?q=shipmentXid in '
                        || l_shipment_list
                        || ' and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
                        || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED"'
                        || ' and shipmentName eq "LRO"'
                        || ' &fields=shipmentXid';

               begin
                  apex_web_service.g_request_headers.delete;
                  apex_web_service.g_request_headers(1).name := 'Content-Type';
                  apex_web_service.g_request_headers(1).value := 'application/json';
                  l_response_clob := apex_web_service.make_rest_request(
                     p_url                  => l_url,
                     p_http_method          => 'GET',
                     p_credential_static_id => l_credential_static_id,
                     p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                  );
                  apex_json.parse(l_response_clob);
                  l_api_shipment_count := apex_json.get_count('items');
                  if l_api_shipment_count is null then
                     l_api_shipment_count := 0;
                  end if;
                  for i in 1..l_api_shipment_count loop
                     l_shipment_xid := apex_json.get_varchar2(
                        'items[%d].shipmentXid',
                        i
                     );
                     if l_shipment_xid is not null then
                        l_valid_count := l_valid_count + 1;
                        l_valid_shipments(l_valid_count) := l_shipment_xid;
                     end if;
                  end loop;
               exception
                  when others then
                     l_valid_count := l_shipment_count; -- Fallback
                     l_valid_shipments := l_shipments;
               end;
            end if;

            apex_json.open_array('shipments');
            for i in 1..l_valid_count loop
               apex_json.write(l_valid_shipments(i));
            end loop;
            apex_json.close_array;
            apex_json.open_array('containers');
            for c in (
               select container_nbr,
                      position
                 from xxotm_container_inventory_t
                where cust_nbr = l_customer_nbr
                  and booking_id = l_booking_nbr
                  and container_type = ct.container_type
                  and container_stored_time is not null
                  and container_released_time is null
                  and shipment_name like '%INBOUND_CONTAINER%'
                  and xxotm_container_inventory_t.location = v_location
                order by container_nbr
            ) loop
               apex_json.open_object;
               apex_json.write(
                  'position',
                  c.position
               );
               apex_json.write(
                  'container_nbr',
                  c.container_nbr
               );
               apex_json.close_object;
            end loop;
            apex_json.close_array;
            apex_json.close_object;
         end loop;
      elsif l_order_type = 'CRO' then
         -- [Existing CRO Logic - Simplified for brevity but logic maintained]
         for ct in (
            select distinct container_type
              from xxotm_container_inventory_t
             where cust_nbr = l_customer_nbr
               and booking_id is null
               and container_nbr is not null
               and container_type is not null
               and container_stored_time is not null
               and container_released_time is null
               and shipment_name like '%INBOUND_CONTAINER%'
               and xxotm_container_inventory_t.location = v_location
               and container_type in (
               select distinct container_type
                 from xxotm_container_inventory_t
                where booking_id = l_booking_nbr
                and xxotm_container_inventory_t.location = v_location
            )
             order by container_type
         ) loop
            apex_json.open_object(ct.container_type);
             
            -- [Repeated API Check Logic for CRO - same as LRO]
            l_shipment_count := 0;
            l_shipments.delete;
            for s in (
               select distinct inbound_shipment_nbr
                 from xxotm_container_inventory_t
                where cust_nbr = l_customer_nbr
                  and booking_id = l_booking_nbr
                  and container_type = ct.container_type
                  and inbound_shipment_nbr is not null 
                  and shipment_name  = 'CRO'
                  and xxotm_container_inventory_t.location = v_location
            ) loop
               l_shipment_count := l_shipment_count + 1;
               l_shipments(l_shipment_count) := s.inbound_shipment_nbr;
            end loop;
    
            l_valid_count := 0;
            l_valid_shipments.delete;
            if l_shipment_count > 0 then
               l_shipment_list := '[';
               for i in 1..l_shipment_count loop
                  if i > 1 then
                     l_shipment_list := l_shipment_list || ',';
                  end if;
                  l_shipment_list := l_shipment_list
                                     || '"'
                                     || l_shipments(i)
                                     || '"';
               end loop;
               l_shipment_list := l_shipment_list || ']';
                    --  DBMS_OUTPUT.PUT_LINE(l_shipment_list);

               l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                        || '?q=shipmentXid in '
                        || l_shipment_list
                        || ' and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
                        || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_NOT_STARTED"'
                        || ' and shipmentName eq "CRO"'
                        || ' &fields=shipmentXid';

               begin
                  apex_web_service.g_request_headers.delete;
                  apex_web_service.g_request_headers(1).name := 'Content-Type';
                  apex_web_service.g_request_headers(1).value := 'application/json';
                  l_response_clob := apex_web_service.make_rest_request(
                     p_url                  => l_url,
                     p_http_method          => 'GET',
                     p_credential_static_id => l_credential_static_id,
                     p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                  );
                  apex_json.parse(l_response_clob);
                  l_api_shipment_count := apex_json.get_count('items');
                  if l_api_shipment_count is null then
                     l_api_shipment_count := 0;
                  end if;
                  for i in 1..l_api_shipment_count loop
                     l_shipment_xid := apex_json.get_varchar2(
                        'items[%d].shipmentXid',
                        i
                     );
                     if l_shipment_xid is not null then
                        l_valid_count := l_valid_count + 1;
                        l_valid_shipments(l_valid_count) := l_shipment_xid;
                     end if;
                  end loop;
               exception
                  when others then
                     l_valid_count := l_shipment_count;
                     l_valid_shipments := l_shipments;
               end;
            end if;

            apex_json.open_array('shipments');
            for i in 1..l_valid_count loop
               apex_json.write(l_valid_shipments(i));
            end loop;
            apex_json.close_array;
            apex_json.open_array('containers');
            for c in (
               select container_nbr,
                      position
                 from xxotm_container_inventory_t
                where cust_nbr = l_customer_nbr
                  and booking_id is null
                  and container_type = ct.container_type
                  and container_stored_time is not null
                  and container_released_time is null
                  and position is not null
                  and position != 'NA'
                  and shipment_name like '%INBOUND_CONTAINER%'
                  and xxotm_container_inventory_t.location = v_location
                order by container_nbr
            ) loop
                --   DBMS_OUTPUT.PUT_LINE(c.position||'-'||c.container_nbr);

               apex_json.open_object;
               apex_json.write(
                  'position',
                  c.position
               );
               apex_json.write(
                  'container_nbr',
                  c.container_nbr
               );
               apex_json.close_object;
            end loop;
            apex_json.close_array;
            apex_json.close_object;
         end loop;
      end if;
      apex_json.close_object;
      apex_json.close_object;
   elsif l_found then
      -- ==========================================
      -- RELEASE_CFS LOGIC UPDATED
      -- ==========================================
    --   dbms_output.put_line('=== Processing RELEASE_CFS ===');
      
      -- 1. Get ALL RELEASE_CFS shipments for this truck
      l_shipment_count := 0;
      l_shipments.delete;
      l_shipment_list := '';
      for s in c_cfs_shipments loop
         l_shipment_count := l_shipment_count + 1;
         l_shipments(l_shipment_count) := s.shipment_xid;
         if l_shipment_list is null then
            l_shipment_list := '"'
                               || s.shipment_xid
                               || '"';
         else
            l_shipment_list := l_shipment_list
                               || ',"'
                               || s.shipment_xid
                               || '"';
         end if;
      end loop;

    --   dbms_output.put_line('Found '
    --                        || l_shipment_count
    --                        || ' potential CFS shipments.');
      if l_shipment_count > 0 then
         -- 2. Bulk Validate via API (TRIP_NOT_STARTED)
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                  || '?q=shipmentXid in ['
                  || l_shipment_list
                  || ']'
                  || ' and statuses.statusTypeGid eq "NAQLEEN.TRIP_STATUS"'
                  || ' and statuses.statusValueGid eq "NAQLEEN.TRIP_STARTED"'
                  || ' &fields=shipmentXid';

         dbms_output.put_line('API URL: ' || l_url);
         begin
            apex_web_service.g_request_headers.delete;
            apex_web_service.g_request_headers(1).name := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_url,
               p_http_method          => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
            apex_json.parse(l_response_clob);
            l_api_shipment_count := apex_json.get_count('items');
            if l_api_shipment_count is null then
               l_api_shipment_count := 0;
            end if;
            -- dbms_output.put_line('API Valid Shipments: ' || l_api_shipment_count);
            
            -- Process Valid Shipments
            l_valid_shipments.delete;
            l_valid_count := 0;
            for i in 1..l_api_shipment_count loop
               l_shipment_xid := apex_json.get_varchar2(
                  'items[%d].shipmentXid',
                  i
               );
               if l_shipment_xid is not null then
                  l_valid_count := l_valid_count + 1;
                   -- Store plain XID if API returns formatted
                  l_valid_shipments(l_valid_count) := replace(
                     l_shipment_xid,
                     'NAQLEEN.',
                     ''
                  );
               end if;
            end loop;

            -- 3. Match DB (sorted by update_date desc) with API Valid List
            -- We want the MOST RECENT UPDATED shipment that is also VALID.
            l_cfs_found := false;
            for i in 1..l_shipment_count loop
               declare
                  l_db_shipment varchar2(200) := l_shipments(i);
               begin
                    -- Check if db shipment is in valid list
                  for k in 1..l_valid_count loop
                     if l_valid_shipments(k) = l_db_shipment
                     or l_valid_shipments(k) = 'NAQLEEN.' || l_db_shipment then
                        l_target_shipment_xid := l_db_shipment;
                        l_cfs_found := true;
                        -- dbms_output.put_line('>> Selected Target Shipment: ' || l_target_shipment_xid);
                        exit;
                     end if;
                  end loop;
               end;
               if l_cfs_found then
                  exit;
               end if;
            end loop;

         exception
            when others then
               dbms_output.put_line('API Error: ' || sqlerrm);
         end;
      end if;

      if l_cfs_found then
          -- 4. Get Details for Target Shipment
         begin
            select s.cont_no,
                   s.container_type,
                   s.customer_name,
                   s.liner_name,
                   t.booking_id
              into
               l_target_cont_nbr,
               l_target_cont_type,
               l_target_cust_name,
               l_target_cust_nbr,
               l_target_booking_id
              from xxotm_shipments_t s,
                   xxotm_container_inventory_t t
             where s.shipment_xid = l_target_shipment_xid
               and s.shipment_xid = t.inbound_shipment_nbr
               and t.location = v_location
               and rownum = 1;
                
             -- Get Position
            begin
               select position
                 into l_target_position
                 from xxotm_container_inventory_t
                where container_nbr = l_target_cont_nbr
                  and container_stored_time is not null
                  and container_released_time is null
                  and xxotm_container_inventory_t.location = v_location
                  and rownum = 1;
            exception
               when others then
                  l_target_position := '';
            end;

            apex_json.write(
               'response_message',
               'Success'
            );
            apex_json.write(
               'response_code',
               200
            );
            apex_json.open_object('data');
            apex_json.write(
               'order_type',
               'RELEASE_CFS'
            );
            apex_json.write(
               'truck_nbr',
               l_truck_nbr
            );
            apex_json.write(
               'driver_name',
               l_driver_name
            );
            apex_json.write(
               'driver_iqama_nbr',
               l_driver_iqama_nbr
            );
            apex_json.write(
               'customer_nbr',
               l_target_cust_nbr
            );
            apex_json.write(
               'customer_name',
               l_target_cust_name
            );
            apex_json.write(
               'booking_nbr',
               l_target_booking_id
            );
            apex_json.write(
               'shipment_nbr',
               l_target_shipment_xid
            );
            apex_json.write(
               'container_nbr',
               l_target_cont_nbr
            );
            apex_json.write(
               'container_type',
               l_target_cont_type
            );
            apex_json.write(
               'position',
               l_target_position
            );
             
             -- Build Container Types (single shipment focus but structured as requested)
            apex_json.open_object('container_types');
             
             -- Find types related to this customer/booking
            for ct in (
               select distinct t.container_type
                 from xxotm_container_inventory_t t
                where t.cust_nbr = l_target_cust_nbr
                  and t.booking_id = l_target_booking_id
                  and t.container_type is not null
                   -- Ensure we only include types relevant to released reqs if needed, 
                   -- but sticking to original logic of showing available stack
                 and t.location = v_location
                  and exists (
                  select 1
                    from xxotm_shipments_t s
                   where s.shipment_xid = t.inbound_shipment_nbr
                     and s.shipment_name = 'RELEASE_CFS'
                     and s.location = v_location
               )
            ) loop
               apex_json.open_array(ct.container_type);
               for c in (
                  select distinct t.container_nbr,
                                  t.inbound_shipment_nbr as shipment_nbr,
                                  (
                                     select x.position
                                       from xxotm_container_inventory_t x
                                      where x.container_nbr = t.container_nbr
                                        and x.container_stored_time is not null
                                        and x.container_released_time is null
                                        and x.position is not null
                                        and x.location = v_location
                                        and rownum = 1
                                  ) as c_pos
                    from xxotm_container_inventory_t t
                   where t.cust_nbr = l_target_cust_nbr
                     and t.booking_id = l_target_booking_id
                     and t.container_type = ct.container_type
                     and t.container_nbr is not null
                     and t.inbound_shipment_nbr is not null
                     and t.container_nbr != l_target_cont_nbr -- Exclude current if needed?
                     and t.location = v_location
                     and exists (
                     select 1
                       from xxotm_shipments_t s
                      where s.shipment_xid = t.inbound_shipment_nbr
                        and s.shipment_name = 'RELEASE_CFS'
                        and s.location = v_location
                  )
               ) loop
                  apex_json.open_object;
                  apex_json.write(
                     'container',
                     c.container_nbr
                  );
                  apex_json.write(
                     'shipment_nbr',
                     c.shipment_nbr
                  );
                  apex_json.write(
                     'position',
                     c.c_pos
                  );
                  apex_json.close_object;
               end loop;
               apex_json.close_array;
            end loop;

            apex_json.close_object; -- container_types
            apex_json.close_object; -- data

         exception
            when others then
               dbms_output.put_line('Error fetching details for Target Shipment: ' || sqlerrm);
               apex_json.write(
                  'response_code',
                  500
               );
               apex_json.write(
                  'response_message',
                  'Error details: ' || sqlerrm
               );
               apex_json.open_object('data');
               apex_json.close_object;
         end;
      else
         apex_json.write(
            'response_message',
            'No valid shipment found (TRIP_NOT_STARTED)'
         );
         apex_json.write(
            'response_code',
            404
         );
         apex_json.open_object('data');
         apex_json.close_object;
      end if;

   else
      apex_json.write(
         'response_message',
         'No Data Found (Truck not in GATE IN)'
      );
      apex_json.write(
         'response_code',
         404
      );
      apex_json.open_object('data');
      apex_json.close_object;
   end if;
 apex_json.close_object; -- Close Root Object

   -- Get final CLOB
l_final_clob := apex_json.get_clob_output();
apex_json.free_output;

-- Chunked output for large responses (>32K)
   if dbms_lob.getlength(l_final_clob) > 32000 then
      declare
         l_offset number := 1;
         l_amount number := 4000; -- CHANGED FROM 32000 TO 8000 TO PREVENT OVERFLOW
         l_len    number;
         l_buffer varchar2(30000);
      begin
         l_len := dbms_lob.getlength(l_final_clob);
         while l_offset <= l_len loop
            dbms_lob.read(
               l_final_clob,
               l_amount,
               l_offset,
               l_buffer
            );
            htp.prn(l_buffer);
            l_offset := l_offset + l_amount;
         end loop;
      end;
      dbms_lob.freetemporary(l_final_clob);
   else
      htp.prn(l_final_clob);
   end if;


exception

   when others then
      rollback;
      apex_json.free_output;
      
      -- Safe error response
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write('response_code', 500);
      apex_json.write('response_message', substr(sqlerrm, 1, 1000));
      apex_json.close_object;
      
      -- Chunked error output
      l_final_clob := apex_json.get_clob_output();
      apex_json.free_output;
      
      declare
         l_offset number := 1;
         l_amount number := 32000;
         l_len    number;
         l_buffer varchar2(32767);
      begin
         l_len := dbms_lob.getlength(l_final_clob);
         while l_offset <= l_len loop
            dbms_lob.read(l_final_clob, l_amount, l_offset, l_buffer);
            htp.prn(l_buffer);
            l_offset := l_offset + l_amount;
         end loop;
      end;
      dbms_lob.freetemporary(l_final_clob);
end xx_otm_release_container_truck_details;

   -- ========================================================================
   -- XX_OTM_SEARCH_CUSTOMERS_IN_GATE_IN   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_SEARCH_CUSTOMERS_IN_GATE_IN.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_search_customers_in_gate_in (
   p_search_text in varchar2 default null,
   p_user_id     in varchar2 default null
)
as
   -- Declared bare, assigned after BEGIN: an exception during declaration
   -- elaboration escapes this block's own handler and ORDS would return a raw
   -- Oracle stack instead of the JSON envelope.
   --
   -- (The nested clean_customer_name() that used to sit here is gone, so this
   -- file no longer trips the automated location graft -- its first "BEGIN" is
   -- now the procedure's own.)
   v_location varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.open_array('data');

   for r in (
      select 'NAQLEEN.' || upper(st.liner_name) as customer_number,
             -- Most recently updated shipment wins a name collision -- see
             -- note 3 in the header.
             max(replace(upper(st.customer_name), 'NAQLEEN.'))
                keep (dense_rank first order by st.update_date desc nulls last)
                as customer_name
        from xxotm_shipments_t st
       where st.location = v_location
         and st.customer_name is not null
         and st.liner_name is not null
         -- TRIP_STATUS is stored de-prefixed: the sync writes
         -- after_dot(statusValueGid), so 'NAQLEEN.TRIP_NOT_STARTED' lands as
         -- 'TRIP_NOT_STARTED'. Rows synced before that normalisation may still
         -- carry the prefix, hence all three forms -- the same defensive test
         -- XX_OTM_GET_GATE_IN_TRUCK_DETAILS uses on this table.
         and ( st.trip_status in ( 'TRIP_NOT_STARTED',
                                   'NAQLEEN.TRIP_NOT_STARTED' )
                or st.trip_status like '%TRIP_NOT_STARTED%' )
         -- All eight names the API query listed. NOT the six that
         -- XX_OTM_GET_GATE_IN_TRUCK_DETAILS uses -- narrowing this to match
         -- would hide DESTUFFING and STUFFING customers from the picker.
         and st.shipment_name in ( 'LOADING_LCL',
                                   'OFFLOADING_LCL',
                                   'DESTUFFING',
                                   'STUFFING',
                                   'STORE_AS_IT_IS',
                                   'CRO',
                                   'LRO',
                                   'RELEASE_CFS' )
         -- An empty searchText from the client is NULL in Oracle, so the
         -- no-filter case needs no special handling.
         and ( p_search_text is null
                or upper(st.customer_name) like '%'
                                                || upper(p_search_text)
                                                || '%' )
       group by 'NAQLEEN.' || upper(st.liner_name)
       -- Key order, matching the associative-array walk this replaces.
       order by 1
   ) loop
      apex_json.open_object;
      apex_json.write(
         'customer_name',
         r.customer_name
      );
      apex_json.write(
         'customer_number',
         r.customer_number
      );
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_search_customers_in_gate_in;

   -- ========================================================================
   -- XX_OTM_SEARCH_CUSTOMERS_IN_STOCK   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_SEARCH_CUSTOMERS_IN_STOCK.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_search_customers_in_stock (
   p_customer_name in varchar2,
   p_user_id in varchar2 default null
)
as
 v_location varchar2(100);

   cursor c_customers is
   select distinct cust_name,
                   cust_nbr
     from xxotm_customer_stock_t
    where upper(cust_name) like '%'
                                || upper(p_customer_name)
                                || '%'
                                and xxotm_customer_stock_t.location = v_location;
begin
 v_location := xx_get_user_location(p_user_id);
 -- Location is mandatory. xx_get_user_location returns NULL when
 -- req_location_id is absent, malformed, or not permitted for this user;
 -- it no longer falls back to a default site. Continuing on NULL would
 -- filter on "location = NULL" and return an empty result set -- an empty
 -- screen with no error, which is worse than a refusal.
 if v_location is null then
    xxotm_location_required;
    return;
 end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.open_array('data');
   for r in c_customers loop
      apex_json.open_object;
      apex_json.write(
         'cust_name',
         r.cust_name
      );
      apex_json.write(
         'cust_nbr',
         r.cust_nbr
      );
      apex_json.close_object;
   end loop;

   apex_json.close_array;
   apex_json.write(
      'response_code',
      200
   );
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.open_array('data');
      apex_json.close_array;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_search_customers_in_stock;

   -- ========================================================================
   -- XX_OTM_SEND_CHAT_MESSAGE   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_SEND_CHAT_MESSAGE.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_send_chat_message (
    P_BODY IN BLOB
)
AS
    L_CLOB          CLOB;
    L_SENDER_ID     NUMBER;
    L_RECEIVER_ID   NUMBER;
    L_TEXT          VARCHAR2(4000);
    L_NEW_ID        NUMBER;
    L_RESPONSE_CODE NUMBER := 200;
    L_RESPONSE_MSG  VARCHAR2(4000) := 'Message sent successfully';
BEGIN
    -- Convert BLOB to CLOB
    L_CLOB := TO_CLOB(P_BODY);
    -- Parse JSON
    APEX_JSON.PARSE(L_CLOB);
    L_SENDER_ID   := APEX_JSON.GET_NUMBER('sender_id');
    L_RECEIVER_ID := APEX_JSON.GET_NUMBER('receiver_id');
    L_TEXT        := APEX_JSON.GET_VARCHAR2('text');
    -- Insert the message
    BEGIN
        INSERT INTO XXOTM_CHAT_MESSAGES_T (
            SENDER_ID,
            RECEIVER_ID,
            MESSAGE_TEXT,
            SENT_AT
            
        ) VALUES (
           to_number( L_SENDER_ID),
           to_number( L_RECEIVER_ID),
            L_TEXT,
            SYSTIMESTAMP
            
        ) RETURNING MESSAGE_ID INTO L_NEW_ID;
 
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            L_RESPONSE_CODE := 500;
            L_RESPONSE_MSG := 'Error inserting message: ' || SQLERRM;
    END;
    -- Clean up temporary CLOB
    IF DBMS_LOB.ISTEMPORARY(L_CLOB) = 1 THEN
        DBMS_LOB.FREETEMPORARY(L_CLOB);
    END IF;
    -- Generate Response
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('response_code', L_RESPONSE_CODE);
        APEX_JSON.WRITE('response_message', L_RESPONSE_MSG);
        
        IF L_RESPONSE_CODE = 200 THEN
            APEX_JSON.WRITE('message_id', L_NEW_ID);
            APEX_JSON.WRITE('sent_at', TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'));
        END IF;
        
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
    APEX_JSON.FREE_OUTPUT;
EXCEPTION
    WHEN OTHERS THEN
        IF DBMS_LOB.ISTEMPORARY(L_CLOB) = 1 THEN
            DBMS_LOB.FREETEMPORARY(L_CLOB);
        END IF;
        APEX_JSON.FREE_OUTPUT;
        APEX_JSON.INITIALIZE_CLOB_OUTPUT;
        APEX_JSON.OPEN_OBJECT;
            APEX_JSON.WRITE('response_code', 500);
            APEX_JSON.WRITE('response_message', 'Unexpected error: ' || SQLERRM);
        APEX_JSON.CLOSE_OBJECT;
        HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
        APEX_JSON.FREE_OUTPUT;
END XX_OTM_SEND_CHAT_MESSAGE;

   -- ========================================================================
   -- XX_OTM_STUFFING_CONTAINER_DETAILS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_STUFFING_CONTAINER_DETAILS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_stuffing_container_details (
    p_container_nbr IN VARCHAR2
)
AS
    l_customer VARCHAR2(100);
    l_container_found NUMBER := 0;

    CURSOR c_items IS
    SELECT item_code,
           cargo_description AS description,
           qty AS actual_quantity,
           qty_uom AS quantity_uom
      FROM xxotm_customer_inventory_t
     WHERE container_nbr = p_container_nbr;
BEGIN
    -- Validate container parameter
    IF p_container_nbr IS NULL THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_message', 'Container number is required');
        apex_json.write('response_code', 400);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        RETURN;
    END IF;

    -- Get customer name and verify container exists
    BEGIN
        SELECT cust_name, COUNT(*)
        INTO l_customer, l_container_found
        FROM xxotm_customer_inventory_t
        WHERE container_nbr = p_container_nbr
        GROUP BY cust_name;

        IF l_container_found = 0 THEN
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write('response_message', 'No Data found');
            apex_json.write('response_code', 404);
            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
            RETURN;
        END IF;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            apex_json.initialize_clob_output;
            apex_json.open_object;
            apex_json.write('response_message', 'No Data Found');
            apex_json.write('response_code', 404);
            apex_json.close_object;
            htp.prn(apex_json.get_clob_output);
                dbms_output.put_line(apex_json.get_clob_output);

            RETURN;
    END;

    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write('response_message', 'Success');
    apex_json.write('response_code', 200);
    apex_json.open_object('data');
    apex_json.write('container_number', p_container_nbr);
    apex_json.write('customer', l_customer);

    apex_json.open_array('items');
    FOR r_item IN c_items LOOP
        apex_json.open_object;
        apex_json.write('item_code', r_item.item_code);
        apex_json.write('description', r_item.description);
        apex_json.write('actual_quantity', r_item.actual_quantity);
        apex_json.write('quantity_uom', r_item.quantity_uom);
        apex_json.close_object;
    END LOOP;
    apex_json.close_array;

    apex_json.close_object;
    apex_json.close_object;
    htp.prn(apex_json.get_clob_output);
    dbms_output.put_line(apex_json.get_clob_output);

EXCEPTION
    WHEN OTHERS THEN
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_message', 'Error: ' || SQLERRM);
        apex_json.write('response_code', 500);
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
END xx_otm_stuffing_container_details;

   -- ========================================================================
   -- XX_OTM_SUBMIT_CONTAINER_POSITION   [3d-high-risk / TAKE-TEST + prod fields]
   -- source: db/work/XX_OTM_SUBMIT_CONTAINER_POSITION.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_submit_container_position (
   p_body    IN BLOB,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
AS

   -- ── Response ───────────────────────────────────────────
   l_response_code    NUMBER        := 200;
   l_response_msg     VARCHAR2(4000) := 'Success';
   -- Declared bare, assigned after BEGIN. As an initialiser a failure in
   -- xx_get_user_location would bypass this block's own handler and ORDS would
   -- return a raw Oracle stack instead of the JSON envelope.
   v_location         VARCHAR2(100);

   -- A truck carries at most two shipments, one container each (shipment to
   -- container is 1:1 -- see db/MERGE_DECISIONS.md "Domain model"). Matches
   -- c_max_containers in XX_OTM_POSITION_TRUCK_DETAILS, which only ever offers
   -- two, and the cap XX_OTM_SUBMIT_RELEASE_CONTAINER already enforces.
   c_max_containers   CONSTANT PLS_INTEGER := 2;

   -- ── ORA-00054, restored ────────────────────────────────
   -- The 18-May ancestor had this and both prod and test then deleted it, while
   -- keeping the FOR UPDATE NOWAIT statements. Test compensated by catching
   -- WHEN OTHERS and calling everything a lock conflict, which also swallows
   -- genuine bugs and reports them to the operator as "try again later".
   -- Naming the exception means only real contention becomes a 409 and anything
   -- else reaches the 500 handler where it belongs.
   e_row_locked       EXCEPTION;
   PRAGMA EXCEPTION_INIT(e_row_locked, -54);

   -- ── JSON ───────────────────────────────────────────────
   l_clob             CLOB;
   l_is_array         BOOLEAN;
   l_count            NUMBER;
   l_truck_nbr        VARCHAR2(100);
   l_dummy            NUMBER;

   -- ── Per-container record ───────────────────────────────
   TYPE t_cont_rec IS RECORD (
      container_nbr    VARCHAR2(100),
      shipment_nbr     VARCHAR2(100),
      position         VARCHAR2(200),
      terminal         VARCHAR2(50),
      block            VARCHAR2(50),
      lot_no           VARCHAR2(50),
      row_no           VARCHAR2(50),
      level_no         NUMBER,
      shipment_name    VARCHAR2(200),
      truck_nbr        VARCHAR2(100)
   );
   TYPE t_cont_tab IS TABLE OF t_cont_rec INDEX BY BINARY_INTEGER;
   l_containers       t_cont_tab;
   l_temp_rec         t_cont_rec;

   -- ── Misc ───────────────────────────────────────────────
   l_api_response     CLOB;
   l_attribute4       VARCHAR2(200);

BEGIN
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- =====================================================
   -- 1. BLOB → CLOB → JSON PARSE
   -- =====================================================
   IF p_body IS NULL THEN
      l_response_code := 400;
      l_response_msg  := 'Empty request body';
      GOTO build_response;
   END IF;

   DECLARE
      l_dest_offset  INTEGER := 1;
      l_src_offset   INTEGER := 1;
      l_lang_context INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
      l_warning      INTEGER;
   BEGIN
      DBMS_LOB.CREATETEMPORARY(l_clob, TRUE);
      DBMS_LOB.CONVERTTOCLOB(
         dest_lob     => l_clob,
         src_blob     => p_body,
         amount       => DBMS_LOB.GETLENGTH(p_body),
         dest_offset  => l_dest_offset,
         src_offset   => l_src_offset,
         blob_csid    => DBMS_LOB.DEFAULT_CSID,
         lang_context => l_lang_context,
         warning      => l_warning
      );
   END;

   BEGIN
      APEX_JSON.PARSE(l_clob);
   EXCEPTION
      WHEN OTHERS THEN
         l_response_code := 400;
         l_response_msg  := 'Invalid JSON payload';
         GOTO cleanup_and_respond;
   END;

   -- =====================================================
   -- 2. EXTRACT CONTAINERS (array or single object)
   -- l_is_array evaluated ONCE outside loop
   -- =====================================================
   l_is_array := (APEX_JSON.GET_COUNT(p_path => '.') IS NOT NULL);
   l_count    := NVL(APEX_JSON.GET_COUNT(p_path => '.'), 1);

   -- Bound the payload. Every container costs an OTM round trip, and more than
   -- two on one truck contradicts the domain model, so it is bad data rather
   -- than a large request. Reject it plainly instead of half-processing it.
   IF l_count > c_max_containers THEN
      l_response_code := 400;
      l_response_msg  := 'At most ' || c_max_containers ||
                         ' containers can be positioned in one request; got ' || l_count || '.';
      GOTO cleanup_and_respond;
   END IF;

   FOR i IN 1..l_count LOOP

      -- Extract fields
      IF l_is_array THEN
         l_containers(i).container_nbr := APEX_JSON.GET_VARCHAR2(p_path => '[%d].container_nbr', p0 => i);
         l_containers(i).shipment_nbr  := APEX_JSON.GET_VARCHAR2(p_path => '[%d].shipment_nbr',  p0 => i);
         l_containers(i).position      := APEX_JSON.GET_VARCHAR2(p_path => '[%d].position',       p0 => i);
         l_containers(i).truck_nbr     := APEX_JSON.GET_VARCHAR2(p_path => '[%d].truck_nbr',      p0 => i);
      ELSE
         l_containers(i).container_nbr := APEX_JSON.GET_VARCHAR2(p_path => 'container_nbr');
         l_containers(i).shipment_nbr  := APEX_JSON.GET_VARCHAR2(p_path => 'shipment_nbr');
         l_containers(i).position      := APEX_JSON.GET_VARCHAR2(p_path => 'position');
         l_containers(i).truck_nbr     := APEX_JSON.GET_VARCHAR2(p_path => 'truck_nbr');
      END IF;

      -- Capture truck_nbr (last non-null wins across multi-container)
      l_truck_nbr := NVL(l_containers(i).truck_nbr, l_truck_nbr);

      -- Validate required fields
      IF l_containers(i).container_nbr IS NULL
      OR l_containers(i).shipment_nbr  IS NULL
      OR l_containers(i).position      IS NULL THEN
         l_response_code := 400;
         l_response_msg  := 'Missing required fields in container ' || i ||
                            ' (container_nbr, shipment_nbr, position required)';
         GOTO cleanup_and_respond;
      END IF;

      -- Fetch shipment_name early — needed for conditional yard check below
      BEGIN
         SELECT shipment_name INTO l_containers(i).shipment_name
         FROM   xxotm_shipments_t
         WHERE  shipment_xid = l_containers(i).shipment_nbr
         and xxotm_shipments_t.location = v_location;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN l_containers(i).shipment_name := NULL;
      END;

      -- Check: container must NOT already be active in the yard.
      -- SKIP for *STUFFING* types — container is intentionally already in yard
      -- and is being re-positioned (CFS re-stack), not newly stored.
      --
      -- NVL is load-bearing. The lookup above is location-scoped, so a shipment
      -- belonging to another site returns NO_DATA_FOUND and leaves shipment_name
      -- NULL -- and NULL NOT LIKE '%STUFFING%' evaluates to NULL, not TRUE, so
      -- the branch was skipped and the yard check never ran. It failed OPEN:
      -- an unknown shipment was the one case that could re-store a container
      -- already in the yard. Unknown must fail CLOSED.
      IF NVL(l_containers(i).shipment_name, 'X') NOT LIKE '%STUFFING%' THEN
         DECLARE
            l_in_yard NUMBER := 0;
         BEGIN
            SELECT COUNT(1) INTO l_in_yard
            FROM   xxotm_container_inventory_t
            WHERE  container_nbr           = l_containers(i).container_nbr
            AND    container_stored_time   IS NOT NULL
            AND    container_released_time IS NULL
            AND    position                != 'NA'
            AND    ROWNUM = 1
            and xxotm_container_inventory_t.location = v_location;

            IF l_in_yard > 0 THEN
               l_response_code := 409;
               l_response_msg  := 'Container ' || l_containers(i).container_nbr ||
                                  ' is already present in the yard';
               GOTO cleanup_and_respond;
            END IF;
         END;
      END IF;

      -- Parse position: TERMINAL-BLOCK-LOT-ROW-LEVEL
      l_containers(i).terminal := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 1);
      l_containers(i).block    := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 2);
      l_containers(i).lot_no   := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 3);
      l_containers(i).row_no   := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 4);
      BEGIN
         l_containers(i).level_no := TO_NUMBER(REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 5));
      EXCEPTION
         WHEN OTHERS THEN l_containers(i).level_no := 0;
      END;

   END LOOP;

   -- =====================================================
   -- 2.4 REJECT DUPLICATES WITHIN THE PAYLOAD
   --
   -- Step 3 validates each position against POSITION_MASTER, which cannot see
   -- the rest of THIS request: two containers aimed at one slot both pass,
   -- because the slot genuinely is free. The per-slot FOR UPDATE NOWAIT in 5a
   -- does not catch it either -- same session, so the second lock succeeds.
   -- The occupancy predicate on the 5b UPDATE now turns that into a 409, but by
   -- then the first container is stored and the transaction has to roll back.
   -- Catching it here costs nothing and returns a 400 that names the mistake.
   --
   -- Duplicate CONTAINER numbers are rejected for the same reason: a truck
   -- carries two DIFFERENT containers, one per shipment.
   -- =====================================================
   FOR i IN 1..l_containers.COUNT - 1 LOOP
      FOR j IN i + 1..l_containers.COUNT LOOP
         IF UPPER(TRIM(l_containers(i).position)) =
            UPPER(TRIM(l_containers(j).position)) THEN
            l_response_code := 400;
            l_response_msg  := 'Containers ' || l_containers(i).container_nbr ||
                               ' and ' || l_containers(j).container_nbr ||
                               ' were both assigned position ' ||
                               l_containers(i).position || '.';
            GOTO cleanup_and_respond;
         END IF;
         IF UPPER(TRIM(l_containers(i).container_nbr)) =
            UPPER(TRIM(l_containers(j).container_nbr)) THEN
            l_response_code := 400;
            l_response_msg  := 'Container ' || l_containers(i).container_nbr ||
                               ' appears twice in the same request.';
            GOTO cleanup_and_respond;
         END IF;
      END LOOP;
   END LOOP;

   -- =====================================================
   -- 2.5 LOCK TRUCK (race condition: prevent double-store)
   --     FOR UPDATE NOWAIT → 2nd session gets 409 instantly
   -- =====================================================
   IF l_truck_nbr IS NOT NULL THEN
      BEGIN
         SELECT 1 INTO l_dummy
         FROM   xxotm_vehicle_master_t
         WHERE  UPPER(truck_nbr) = UPPER(l_truck_nbr)
         AND    exit_time        IS NULL
         AND    xxotm_vehicle_master_t.location         = v_location
         AND    status           = 'NAQLEEN.GATE IN'
         AND    ROWNUM           = 1
         FOR UPDATE NOWAIT;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            l_response_code := 403;
            l_response_msg  := 'Truck ' || l_truck_nbr ||
                               ' is not in a valid Gate In state or has already been processed.';
            GOTO cleanup_and_respond;
         WHEN e_row_locked THEN
            l_response_code := 409;
            l_response_msg  := 'Truck ' || l_truck_nbr ||
                               ' is being processed by another user. Please wait.';
            GOTO cleanup_and_respond;
      END;
   END IF;

   -- =====================================================
   -- 3. VALIDATE: All target positions must exist & be free
   --    Done for ALL containers before any write begins
   -- =====================================================
   FOR i IN 1..l_containers.COUNT LOOP

      -- Position must exist in master
      BEGIN
         SELECT 1 INTO l_dummy
         FROM   xxotm_position_master_t
         WHERE  terminal  = l_containers(i).terminal
         AND    block     = l_containers(i).block
         AND    lot_no    = l_containers(i).lot_no
         AND    row_no    = l_containers(i).row_no
         AND    level_no  = l_containers(i).level_no
         and xxotm_position_master_t.location = v_location;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN
            l_response_code := 404;
            l_response_msg  := 'Position not defined in master: ' || l_containers(i).position;
            GOTO cleanup_and_respond;
      END;

      -- Position must be unoccupied
      BEGIN
         SELECT 1 INTO l_dummy
         FROM   xxotm_position_master_t
         WHERE  terminal  = l_containers(i).terminal
         AND    block     = l_containers(i).block
         AND    lot_no    = l_containers(i).lot_no
         AND    row_no    = l_containers(i).row_no
         AND    level_no  = l_containers(i).level_no
         AND    (is_occupied != 'N' OR shipment_nbr IS NOT NULL)
         and xxotm_position_master_t.location = v_location;

         -- Row found → position is taken
         l_response_code := 409;
         l_response_msg  := 'Position ' || l_containers(i).position || ' is already occupied.';
         GOTO cleanup_and_respond;
      EXCEPTION
         WHEN NO_DATA_FOUND THEN NULL; -- Good: slot is free
      END;

   END LOOP;

   -- =====================================================
   -- 4. SORT: Lowest level first (bottom of stack → top)
   -- =====================================================
   IF l_containers.COUNT > 1 THEN
      FOR i IN 1..l_containers.COUNT - 1 LOOP
         FOR j IN i + 1..l_containers.COUNT LOOP
            IF l_containers(i).level_no > l_containers(j).level_no THEN
               l_temp_rec      := l_containers(i);
               l_containers(i) := l_containers(j);
               l_containers(j) := l_temp_rec;
            END IF;
         END LOOP;
      END LOOP;
   END IF;

   -- =====================================================
   -- 5. EXECUTE: Lock → Update → Inventory → OTM Events
   -- All inside one transaction. ROLLBACK covers everything.
   -- =====================================================
   FOR i IN 1..l_containers.COUNT LOOP

      -- 5a. Acquire exclusive lock on position slot
      BEGIN
         SELECT 1 INTO l_dummy
         FROM   xxotm_position_master_t
         WHERE  terminal  = l_containers(i).terminal
         AND    block     = l_containers(i).block
         AND    lot_no    = l_containers(i).lot_no
         AND    row_no    = l_containers(i).row_no
         AND    level_no  = l_containers(i).level_no
         and xxotm_position_master_t.location = v_location
         FOR UPDATE NOWAIT;
      EXCEPTION
         WHEN e_row_locked THEN
            l_response_code := 409;
            l_response_msg  := 'Position locked by another session: ' || l_containers(i).POSITION ||'. Try again later ';
            GOTO cleanup_and_respond;
      END;

      -- 5b. Update position master.
      --
      -- The occupancy predicate here is what makes check-and-write ATOMIC.
      -- Step 3 established the slot was free, but that was before the lock in
      -- 5a: another session could take the slot and COMMIT in between, and
      -- FOR UPDATE NOWAIT would then succeed -- the row is no longer locked --
      -- and this UPDATE would silently overwrite their container. Both
      -- operators saw 200 and one container's position record was gone.
      -- Re-testing occupancy inside the same statement closes that window,
      -- because the row is now held by 5a's lock.
      --
      -- It also covers the same-payload case: two containers aimed at ONE slot.
      -- FOR UPDATE NOWAIT cannot catch that -- it is the same session, so the
      -- second lock succeeds -- but the second UPDATE now matches zero rows.
      UPDATE xxotm_position_master_t
      SET    shipment_nbr      = l_containers(i).shipment_nbr,
             container_nbr     = l_containers(i).container_nbr,
             is_occupied       = l_containers(i).container_nbr,
             last_event_time   = SYSTIMESTAMP,
             last_event_source = 'MOBILE'
      WHERE  terminal  = l_containers(i).terminal
      AND    block     = l_containers(i).block
      AND    lot_no    = l_containers(i).lot_no
      AND    row_no    = l_containers(i).row_no
      AND    level_no  = l_containers(i).level_no
      and xxotm_position_master_t.location = v_location
      AND    NVL(is_occupied, 'N') = 'N'
      AND    shipment_nbr IS NULL;

      -- Zero rows now means "taken since we validated", not "does not exist" --
      -- step 3 already proved it exists. 409, not 404: the client should
      -- refresh the picker and choose again, which a 404 does not convey.
      IF SQL%ROWCOUNT = 0 THEN
         l_response_code := 409;
         l_response_msg  := 'Position ' || l_containers(i).position ||
                            ' was taken while this request was in progress. '
                            || 'Please refresh and choose another slot.';
         GOTO cleanup_and_respond;
      END IF;

      -- 5c. shipment_name already fetched in Step 2 — re-fetch only if NULL
      IF l_containers(i).shipment_name IS NULL THEN
         BEGIN
            SELECT shipment_name INTO l_containers(i).shipment_name
            FROM   xxotm_shipments_t
            WHERE  shipment_xid = l_containers(i).shipment_nbr
            and xxotm_shipments_t.location = v_location;
         EXCEPTION
            WHEN NO_DATA_FOUND THEN l_containers(i).shipment_name := NULL;
         END;
      END IF;

      -- 5d. Route: CFS (CROSS_STUFFING / DESTUFFING / STUFFING) vs Standard
      DECLARE
         l_effective_shipment VARCHAR2(100) := l_containers(i).shipment_nbr;
         l_cfs_shipment       VARCHAR2(100) := NULL;
      BEGIN
         IF l_containers(i).shipment_name IN ('CROSS_STUFFING', 'DESTUFFING', 'STUFFING') THEN

            -- ── CFS PATH ─────────────────────────────────────────────────────
            -- Save CFS shipment for DELETE. Override l_effective_shipment with
            -- INBOUND shipment so tracking events fire against the right shipment.
            l_cfs_shipment := l_containers(i).shipment_nbr;
            BEGIN
               SELECT inbound_shipment_nbr INTO l_effective_shipment
               FROM   xxotm_container_inventory_t
               WHERE  container_nbr           = l_containers(i).container_nbr
               AND    container_stored_time   IS NOT NULL
               AND    container_released_time IS NULL
               and xxotm_container_inventory_t.location = v_location
               FETCH FIRST 1 ROWS ONLY;
            EXCEPTION
               WHEN NO_DATA_FOUND THEN
                  l_effective_shipment := l_containers(i).shipment_nbr; -- fallback
            END;

            -- Update inventory using inbound shipment
            UPDATE xxotm_container_inventory_t
            SET    position              = l_containers(i).position,
                   container_stored_time = TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            WHERE  inbound_shipment_nbr  = l_effective_shipment
            AND    container_nbr         = l_containers(i).container_nbr
            and xxotm_container_inventory_t.location = v_location;

            -- Post CONTAINER_RESTACKED against inbound shipment
            post_otm_tracking_events(
               p_statuscodegid => 'NAQLEEN.CONTAINER_RESTACKED',
               p_shipmentxid   => l_effective_shipment,
               p_attribute1    => l_containers(i).position,
               x_response      => l_api_response
            );

            IF l_api_response NOT LIKE '%Error%' THEN
               -- Delete from CFS table using ORIGINAL CFS shipment_nbr
               DELETE FROM xxotm_cfs_containers_t
               WHERE  container_nbr = l_containers(i).container_nbr
               AND    shipment_nbr  = l_cfs_shipment
               and xxotm_cfs_containers_t.location = v_location;
            ELSE
               l_response_code := 500;
               l_response_msg  := 'OTM API Error (CFS) for ' ||
                                  l_containers(i).container_nbr || ': ' || l_api_response;
               GOTO cleanup_and_respond;
            END IF;

         ELSE
            -- ── STANDARD PATH ─────────────────────────────────────────────────
            l_attribute4 := CASE
                               WHEN l_containers(i).shipment_name = 'STORE_AS_IT_IS' THEN 'LOADED'
                               ELSE NULL
                            END;

            -- Update inventory
            UPDATE xxotm_container_inventory_t
            SET    position              = l_containers(i).position,
                   container_stored_time = TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
            WHERE  inbound_shipment_nbr  = l_containers(i).shipment_nbr
            AND    container_nbr         = l_containers(i).container_nbr
            and xxotm_container_inventory_t.location = v_location;

            -- Post CONTAINER STORED
            post_otm_tracking_events(
               p_integration_name => 'XX_OTM_POST_POSITION_CONTAINER',
               p_statuscodegid    => 'NAQLEEN.CONTAINER STORED',
               p_shipmentxid      => l_effective_shipment,
               p_attribute1       => l_containers(i).position,
               p_attribute4       => l_attribute4,
               x_response         => l_api_response
            );

            IF l_api_response LIKE '%Error%' THEN
               l_response_code := 500;
               l_response_msg  := 'OTM API Error for ' ||
                                  l_containers(i).container_nbr || ': ' || l_api_response;
               GOTO cleanup_and_respond;
            END IF;

         END IF;
      EXCEPTION
         WHEN OTHERS THEN
            l_response_code := 500;
            l_response_msg  := 'Event processing failed for ' ||
                               l_containers(i).container_nbr || ': ' || SQLERRM;
            GOTO cleanup_and_respond;
      END;

      -- 5e. Audit log
      INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
      VALUES (
         'xx_otm_submit_container_position',
         'INFO',
         'Stored container ' || l_containers(i).container_nbr ||
         ' (' || l_containers(i).shipment_name || ') at ' || l_containers(i).position,
         l_containers(i).shipment_nbr
      );

   END LOOP;

   -- =====================================================
   -- 6. UPDATE VEHICLE MASTER STATUS
   -- =====================================================
   IF l_truck_nbr IS NOT NULL THEN
      UPDATE xxotm_vehicle_master_t
      SET    status   = 'NAQLEEN.CONTAINER STORED',
             user_id  = p_user_id
      WHERE  UPPER(truck_nbr) = UPPER(l_truck_nbr)
      AND    entry_time       IS NOT NULL
      AND    exit_time        IS NULL
      AND    xxotm_vehicle_master_t.location         = v_location;
   END IF;

   COMMIT;
   GOTO build_response;

-- =====================================================
-- RESPONSE & CLEANUP
-- =====================================================
<<cleanup_and_respond>>
   ROLLBACK;

<<build_response>>
   -- AUDIT. Every path arrives here -- success via GOTO, every rejection via
   -- cleanup_and_respond -- so one call covers them all with the real response
   -- code. The CASE guard is load-bearing: an early 400 leaves l_containers
   -- empty, and a bare l_containers(1) would raise NO_DATA_FOUND while
   -- EVALUATING THE ARGUMENT, before xxotm_log_activity could swallow it.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'POSITION',
      p_procedure_name => 'XX_OTM_SUBMIT_CONTAINER_POSITION',
      p_action         => 'SUBMIT',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck_nbr,
      p_secondary_id   => case when l_containers.COUNT > 0
                               then l_containers(1).container_nbr end,
      p_response_code  => l_response_code,
      p_message        => l_response_msg,
      p_location       => v_location);

   APEX_JSON.INITIALIZE_CLOB_OUTPUT;
   APEX_JSON.OPEN_OBJECT;
   APEX_JSON.WRITE('response_code',    l_response_code);
   APEX_JSON.WRITE('response_message', l_response_msg);
   APEX_JSON.CLOSE_OBJECT;
   HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
   APEX_JSON.FREE_OUTPUT;

   IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
      DBMS_LOB.FREETEMPORARY(l_clob);
   END IF;

EXCEPTION
   WHEN OTHERS THEN
      ROLLBACK;
      -- This path never reaches build_response, so it logs for itself.
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'POSITION',
         p_procedure_name => 'XX_OTM_SUBMIT_CONTAINER_POSITION',
         p_action         => 'SUBMIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck_nbr,
         p_response_code  => 500,
         p_message        => SQLERRM,
         p_location       => v_location);

      APEX_JSON.INITIALIZE_CLOB_OUTPUT;
      APEX_JSON.OPEN_OBJECT;
      APEX_JSON.WRITE('response_code',    500);
      APEX_JSON.WRITE('response_message', 'Critical Error: ' || SQLERRM);
      APEX_JSON.CLOSE_OBJECT;
      HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
      APEX_JSON.FREE_OUTPUT;
      IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
         DBMS_LOB.FREETEMPORARY(l_clob);
      END IF;
END xx_otm_submit_container_position;

   -- ========================================================================
   -- XX_OTM_SUBMIT_DOCUMENTS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_SUBMIT_DOCUMENTS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_submit_documents (
   p_blob_content in blob
)
as
   -- Created Date: 07-Jan-2026
   -- Description : Standalone procedure to submit multiple documents to OTM.
   --               Updated to handle array-based payload structure with DEBUGS.

   l_json_content   clob;
   l_values         apex_json.t_values;
   l_shipment_nbr   varchar2(100);
   
   -- Document variables
   l_document_count pls_integer;
   l_doc_xid        varchar2(100);
   l_doc_name       varchar2(200);
   l_doc_mime       varchar2(100);
   l_doc_content    clob;
   l_doc_response   clob;
   l_owner_gid      varchar2(100);
   
   -- Error handling & Debugging
   l_error_message  clob;
   l_has_error      boolean := false;
   l_debug_log      clob := 'Start; ';
 
   -- Blob conversion
   l_dest_offset    integer := 1;
   l_src_offset     integer := 1;
   l_lang_context   integer := dbms_lob.default_lang_ctx;
   l_warning        integer;
begin
   -- Convert BLOB to CLOB with explicit cache setup for large objects
   if p_blob_content is not null then
      l_debug_log := l_debug_log
                     || 'BLOB received length: '
                     || dbms_lob.getlength(p_blob_content)
                     || '; ';
      dbms_lob.createtemporary(
         l_json_content,
         true,
         dbms_lob.call
      );
      dbms_lob.converttoclob(
         dest_lob     => l_json_content,
         src_blob     => p_blob_content,
         amount       => dbms_lob.lobmaxsize,
         dest_offset  => l_dest_offset,
         src_offset   => l_src_offset,
         blob_csid    => dbms_lob.default_csid,
         lang_context => l_lang_context,
         warning      => l_warning
      );
      l_debug_log := l_debug_log
                     || 'Converted to CLOB length: '
                     || dbms_lob.getlength(l_json_content)
                     || '; ';
   else
      l_json_content := empty_clob();
      l_debug_log := l_debug_log || 'BLOB is null; ';
   end if;
  
   -- Parse the JSON content
   begin
      apex_json.parse(
         p_values => l_values,
         p_source => l_json_content
      );
      l_debug_log := l_debug_log || 'JSON Parsed; ';
   exception
      when others then
         l_debug_log := l_debug_log
                        || 'JSON Parse Error: '
                        || sqlerrm
                        || '; ';
         raise;
   end;
   
   -- Extract Shipment Number
   l_shipment_nbr := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'shipment_nbr'
   );
   l_debug_log := l_debug_log
                  || 'Shipment: '
                  || l_shipment_nbr
                  || '; ';

   -- -------------------------------
   -- PROCESS DOCUMENTS ARRAY
   -- -------------------------------
   l_document_count := apex_json.get_count(
      p_values => l_values,
      p_path   => 'documents'
   );
   l_debug_log := l_debug_log
                  || 'Doc Count: '
                  || l_document_count
                  || '; ';
   if l_document_count > 0 then
      for i in 1..l_document_count loop
         begin
            l_doc_xid := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].document_xid',
               p0       => i
            );
            l_doc_name := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].document_name',
               p0       => i
            );
            l_doc_mime := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].document_mime_type',
               p0       => i
            );

            l_debug_log := l_debug_log
                           || 'Processing ['
                           || i
                           || '] XID: '
                           || l_doc_xid
                           || '; ';
            
            -- Force full CLOB read using get_clob
            l_doc_content := apex_json.get_clob(
               p_values => l_values,
               p_path   => 'documents[%d].document_content',
               p0       => i
            );
            l_debug_log := l_debug_log
                           || 'Content Len: '
                           || dbms_lob.getlength(l_doc_content)
                           || '; ';

            -- Construct Owner GID
            l_owner_gid := 'NAQLEEN.'
                           || replace(
               l_shipment_nbr,
               'NAQLEEN.',
               ''
            );

            -- Post Document
            if l_doc_content is not null then
               post_otm_documents(
                  p_documentxid      => l_doc_xid,
                  p_documentfilename => l_doc_name,
                  p_ownerobjectgid   => l_owner_gid,
                  p_clobcontent      => l_doc_content,
                  p_documentmimetype => l_doc_mime,
                  p_documentdefgid   => 'NAQLEEN.PACKING_LIST',
                  x_response_clob    => l_doc_response
               );

               l_debug_log := l_debug_log
                              || 'Post Response: '
                              || dbms_lob.substr(
                  l_doc_response,
                  100,
                  1
               )
                              || '...; ';

               if l_doc_response like 'Error%' then
                  l_has_error := true;
                  l_error_message := l_error_message
                                     || 'Error ('
                                     || l_doc_xid
                                     || '): '
                                     || l_doc_response
                                     || '; ';
               end if;
            else
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Error ('
                                  || l_doc_xid
                                  || '): Content is null; ';
               l_debug_log := l_debug_log
                              || 'Content NULL for '
                              || l_doc_xid
                              || '; ';
            end if;

         exception
            when others then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Exception ('
                                  || l_doc_xid
                                  || '): '
                                  || sqlerrm
                                  || '; ';
               l_debug_log := l_debug_log
                              || 'Exception in loop: '
                              || sqlerrm
                              || '; ';
         end;
      end loop;
   else
      l_debug_log := l_debug_log || 'No documents found in array; ';
   end if;

   -- Clean up temporary CLOB
   if dbms_lob.istemporary(l_json_content) = 1 then
      dbms_lob.freetemporary(l_json_content);
   end if;

   -- -------------------------------
   -- Build JSON Response
   -- -------------------------------
   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_has_error then
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Partial or Full Failure: ' || l_error_message
      );
   else
      apex_json.write(
         'response_code',
         200
      );
      apex_json.write(
         'response_message',
         'Success'
      );
   end if;
   
   -- Add Debug Log to Response
   apex_json.write(
      'debug_log',
      l_debug_log
   );
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      -- Global Exception Handler
      if dbms_lob.istemporary(l_json_content) = 1 then
         dbms_lob.freetemporary(l_json_content);
      end if;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.write(
         'debug_log',
         l_debug_log
         || ' | Global Error: '
         || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_submit_documents;

   -- ========================================================================
   -- XX_OTM_SUBMIT_GATE_IN   [3d-high-risk / MANUAL]
   -- source: db/work/XX_OTM_SUBMIT_GATE_IN.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_submit_gate_in (
   p_blob_content in blob,
   p_user_id      in varchar2 default null
)
as
   -- Last Updated Date : 05-Feb-2026
   -- Last Updated By : Sanjit
   -- Description : Updated response code to '200' as string to fix the error in UI. but need to change to number
   -- Declared bare, assigned after BEGIN: an exception during declaration
   -- elaboration escapes this block's own handler.
   v_location             varchar2(100);
   l_check_truck          number;

   -- Dual-shipment gate-in progress. See the ownership lock and OPERATION 4.
   l_allow_any            varchar2(1);    -- GATE_IN_ALLOW_ANY_OPERATOR
   l_expected_ships       pls_integer;    -- how many shipments this truck has
   l_done_ships           pls_integer;    -- how many are gated in after this one
   l_gate_in_ships        varchar2(400);  -- VM.GATE_IN_SHIPMENTS after this one

   -- ORA-00054, restored. The 18-May ancestor guarded the gate-in lock with this
   -- and returned a clean 409; both prod and test then deleted it. Dual-container
   -- gate in makes the two-operator race MORE likely, not less -- it is the whole
   -- point of the ownership check below.
   e_row_locked           exception;
   pragma exception_init(e_row_locked, -54);

   l_json_content         clob;
   l_values               apex_json.t_values;
   l_shipment_nbr         varchar2(100);
   l_container_nbr        varchar2(100);
   l_truck                varchar2(100);
   l_driver               varchar2(100);
   l_truck_type           varchar2(100);
   l_shipment_name        varchar2(100);
   l_validate_container_nbr   varchar2(100);
   -- New fields for CRO/LRO
   l_customer_nbr         varchar2(100);
   l_customer_name        varchar2(200);
   l_booking_id           varchar2(100);
   l_order_type           varchar2(50);


   -- Document variables
   l_document_count       pls_integer;
   l_doc_xid              varchar2(100);
   l_doc_name             varchar2(200);
   l_doc_mime             varchar2(100);
   l_doc_content          clob;
   l_doc_response         clob;

   -- Tracking Event variables
   l_event_response       clob;

   -- API Request/Response
   l_request_clob         clob;
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_validate_shipment_name varchar2(100);
   l_validate_leased_land   varchar2(100);
   -- Error handling
   l_error_message        clob;
   l_has_error            boolean := false;
   l_entry_time           varchar2(50);
   l_request              json_object_t;
   l_status               varchar2(100);
   l_remarks              varchar2(100);
   l_attribute5           varchar2(100);
   l_cfs_container_nbr    varchar2(100);
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   -- Convert BLOB to CLOB
   l_json_content := to_clob(p_blob_content);

   -- Parse the JSON content
   apex_json.parse(
      p_values => l_values,
      p_source => l_json_content
   );

   -- Extract top-level fields
   l_shipment_nbr := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'shipment_nbr'
   );
   l_container_nbr := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'container_nbr'
   );
   l_truck := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'truck_nbr'
   );
   l_driver := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'driver_nbr'
   );
   l_truck_type := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'truck_type'
   );

   -- Extract new fields for CRO/LRO
   l_customer_nbr := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'customer_nbr'
   );
   l_customer_name := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'customer_name'
   );
   l_booking_id := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'booking_id'
   );
   l_order_type := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'order_type'
   );
   l_remarks := apex_json.get_varchar2(
      p_values => l_values,
      p_path   => 'remarks'
   );

   -- =====================================================
   -- GATE IN OWNERSHIP LOCK  (from test -- the core of dual-container gate in)
   -- -----------------------------------------------------
   -- A truck carrying two shipments is scanned twice. The first scan is open to
   -- any operator; the second is restricted to whoever made the first, so two
   -- people cannot half-process one truck between them.
   --
   -- Ownership keys on GATE_IN_BY, not on USER_ID or STATUS:
   --   * STATUS no longer moves to 'NAQLEEN.GATE IN' until BOTH shipments are
   --     in (see OPERATION 4), which is what keeps the truck in the gate-in
   --     list so the operator can come back to it. It therefore cannot
   --     distinguish "not started" from "half done".
   --   * USER_ID is written by inspection, position and release too, so after
   --     inspection it holds the INSPECTOR. Testing it here would block a
   --     different operator from gating in at all, which is allowed today.
   -- GATE_IN_BY is written by gate in alone, and only on the first shipment.
   --
   -- TO ALLOW ANY OPERATOR TO CONTINUE A PART-FINISHED TRUCK (shift handover):
   -- set XXOTM_APP_CONFIG.GATE_IN_ALLOW_ANY_OPERATOR = 'Y'. No code change and
   -- no deploy -- l_allow_any below short-circuits the ownership test. It is
   -- read once per call rather than inlined so the switch has exactly one home.
   --
   -- FOR UPDATE NOWAIT holds the row for the rest of this transaction, so a
   -- concurrent scan fails immediately with a 409 rather than blocking or
   -- interleaving. Prod had no lock here at all.
   -- =====================================================
   l_allow_any := nvl(xxotm_get_cfg('GATE_IN_ALLOW_ANY_OPERATOR'), 'N');

   begin
      select 1
        into l_check_truck
        from xxotm_vehicle_master_t
       where upper(truck_nbr) = upper(l_truck)
         and exit_time is null
         and xxotm_vehicle_master_t.location = v_location
         -- The truck must still be at a stage where gate in is meaningful.
         -- 'NAQLEEN.GATE IN' stays in the list for the single-shipment case,
         -- where the status does flip on the only scan.
         and xxotm_vehicle_master_t.status in
                ('NAQLEEN.INSPECTED', 'gate_in', 'NAQLEEN.GATE IN')
         and (
              -- FIRST SCAN: nobody has gated this truck in on this visit.
              xxotm_vehicle_master_t.gate_in_by is null
              or
              -- Future: any operator may continue. Config only.
              l_allow_any = 'Y'
              or
              -- SECOND SCAN: same operator who made the first.
              xxotm_vehicle_master_t.gate_in_by = p_user_id
             )
         and rownum = 1
         for update nowait;
   exception
      when no_data_found then
         -- AUDIT. The 403 is the ownership lock refusing a second operator. It
         -- is the single most useful row in this table: it is invisible in the
         -- business tables (nothing was written) and it is what tells you two
         -- people are working the same truck.
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'GATE_IN',
            p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
            p_action         => 'SUBMIT',
            p_entity_type    => 'TRUCK',
            p_entity_id      => l_truck,
            p_secondary_id   => l_container_nbr,
            p_response_code  => 403,
            p_message        => 'Not available for gate in, or held by another operator',
            p_location       => v_location);
         apex_json.initialize_clob_output;
         apex_json.open_object;
         apex_json.write('response_code', 403);
         apex_json.write('response_message',
            'Truck is not found for Gate In, or is being processed by another operator.');
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         if dbms_lob.istemporary(l_json_content) = 1 then
            dbms_lob.freetemporary(l_json_content);
         end if;
         return;
      when e_row_locked then
         xxotm_log_activity(
            p_user_id        => p_user_id,
            p_module         => 'GATE_IN',
            p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
            p_action         => 'SUBMIT',
            p_entity_type    => 'TRUCK',
            p_entity_id      => l_truck,
            p_secondary_id   => l_container_nbr,
            p_response_code  => 409,
            p_message        => 'Row locked by a concurrent gate in',
            p_location       => v_location);
         apex_json.initialize_clob_output;
         apex_json.open_object;
         apex_json.write('response_code', 409);
         apex_json.write('response_message',
            'Truck ' || l_truck || ' is being processed right now. Please try again.');
         apex_json.close_object;
         htp.prn(apex_json.get_clob_output);
         apex_json.free_output;
         if dbms_lob.istemporary(l_json_content) = 1 then
            dbms_lob.freetemporary(l_json_content);
         end if;
         return;
   end;

   -- =====================================================
   -- DUAL SHIPMENT: how far through this truck are we?
   -- -----------------------------------------------------
   -- Computed ONCE, here, because two different branches below advance the
   -- truck's status -- OPERATION 4 ('NAQLEEN.GATE IN') and the leased-land
   -- branch ('NAQLEEN.CONTAINER STORED') -- and both must defer until every
   -- shipment on the truck is in. While the status stays 'NAQLEEN.INSPECTED'
   -- the truck keeps matching the gate-in list filter and Branch A of
   -- XX_OTM_GET_GATE_IN_TRUCK_DETAILS, which is what lets an operator close
   -- the app after the first shipment and come back for the second.
   --
   -- Flip early and the truck vanishes from the app with work outstanding;
   -- flip late and it lingers in the list. Both are visible, neither silent.
   --
   -- l_expected_ships is counted the way A2 of the details procedure finds
   -- candidates -- truck_3pl + location + shipment_name -- minus its
   -- per-shipment validate_shipment_api call, far too expensive here. The
   -- local stand-in is the trip_status filter: that call's only test is "trip
   -- is neither COMPLETED nor CANCELLED". Both the prefixed and bare forms are
   -- checked because the sync writes both.
   --
   -- The shipment name is resolved HERE and not reused from OPERATION 2: that
   -- lookup runs further down, so at this point l_shipment_name is still NULL.
   -- Relying on it made the guard below always fire, pinning l_expected_ships
   -- to 1 and flipping the status on the first scan -- silently reverting the
   -- whole deferral. OPERATION 2 still does its own lookup; this one is local
   -- to the calculation and costs one indexed read.
   -- =====================================================
   begin
      select shipment_name
        into l_shipment_name
        from xxotm_shipments_t
       where shipment_xid = l_shipment_nbr
         and xxotm_shipments_t.location = v_location
       fetch first 1 rows only;
   exception
      when no_data_found then
         l_shipment_name := null;
   end;

   begin
      select count(*)
        into l_expected_ships
        from xxotm_shipments_t st
       where st.truck_3pl     = l_truck
         and st.location      = v_location
         and st.shipment_name = 'INBOUND_CONTAINER'
         and nvl(st.trip_status, 'X') not in
               ('NAQLEEN.TRIP_COMPLETED', 'NAQLEEN.TRIP_CANCELLED',
                'TRIP_COMPLETED',         'TRIP_CANCELLED');
   exception
      when others then
         l_expected_ships := null;
   end;

   -- Order types that are never doubled, or a count we could not establish:
   -- behave exactly as prod did and let this scan complete the truck.
   if l_shipment_name is null or l_shipment_name != 'INBOUND_CONTAINER' then
      l_expected_ships := 1;
   end if;
   l_expected_ships := greatest(nvl(l_expected_ships, 1), 1);

   -- GATE_IN_SHIPMENTS as it will read after this shipment is added.
   -- Comma-bounded membership, the same rule SHIPMENT_NBR uses, so a re-scan
   -- or a client retry cannot double-count and push the truck to complete.
   begin
      select case
                when t.gate_in_shipments is null
                   then l_shipment_nbr
                when instr(',' || t.gate_in_shipments || ',',
                           ',' || l_shipment_nbr || ',') > 0
                   then t.gate_in_shipments
                else t.gate_in_shipments || ',' || l_shipment_nbr
             end
        into l_gate_in_ships
        from xxotm_vehicle_master_t t
       where t.truck_nbr  = l_truck
         and t.exit_time is null
         and t.location   = v_location
         and t.entry_time = (
             select max(entry_time)
               from xxotm_vehicle_master_t
              where truck_nbr = l_truck
                and exit_time is null
                and xxotm_vehicle_master_t.location = v_location
         );
   exception
      when no_data_found then
         l_gate_in_ships := l_shipment_nbr;
   end;

   l_done_ships := case
                      when l_gate_in_ships is null then 0
                      else length(l_gate_in_ships)
                           - length(replace(l_gate_in_ships, ',', '')) + 1
                   end;

   -- =====================================================
   -- CRO/LRO: Only update vehicle master, skip all other operations
   -- =====================================================
   if l_order_type in ( 'CRO',
                        'LRO' ) then
      begin
         update xxotm_vehicle_master_t t
            set t.status = 'NAQLEEN.GATE IN',
                t.customer_nbr = l_customer_nbr,
                t.customer_name = l_customer_name,
                t.booking_id = l_booking_id,
                t.order_type = l_order_type,
                -- Records who owns this truck, so a second scan can be matched
                -- back to the same operator by the lock above.
                t.user_id = p_user_id,
                t.gate_in_time = to_char(
                   sys_extract_utc(systimestamp),
                   'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"'
                )
          where t.truck_nbr = l_truck
            and t.exit_time is null
            and t.location  = v_location
            and t.entry_time = (
            select max(entry_time)
              from xxotm_vehicle_master_t
             where truck_nbr = l_truck
               and exit_time is null
               and xxotm_vehicle_master_t.location  = v_location
         );

         if sql%rowcount = 0 then
            l_has_error := true;
            l_error_message := 'Vehicle Master Update Failed: No matching record found for ' || l_truck;
         end if;
      exception
         when others then
            l_has_error := true;
            l_error_message := 'Vehicle Master Update Exception: ' || sqlerrm;
      end;

      -- Clean up and return response for CRO/LRO
      if dbms_lob.istemporary(l_json_content) = 1 then
         dbms_lob.freetemporary(l_json_content);
      end if;

      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'GATE_IN',
         p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
         p_action         => 'SUBMIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck,
         p_secondary_id   => l_booking_id,
         p_response_code  => case when l_has_error then 500 else 200 end,
         p_message        => nvl(l_error_message, l_order_type || ' gate in'),
         p_location       => v_location);

      apex_json.initialize_clob_output;
      apex_json.open_object;
      if l_has_error then
         apex_json.write(
            'response_code',
            500
         );
         apex_json.write(
            'response_message',
            l_error_message
         );
      else
         apex_json.write(
            'response_code',
            200
         );
         apex_json.write(
            'response_message',
            'Success'
         );
      end if;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
      return;
   end if;

   -- =====================================================
   -- Regular flow for non CRO/LRO orders
   -- =====================================================

  if l_shipment_nbr is not null then
   -- -------------------------------
   -- OPERATION 1: Process Documents
   -- -------------------------------
    begin
        select shipment_name, leased_land into l_validate_shipment_name, l_validate_leased_land from xxotm_shipments_t where shipment_xid  = l_shipment_nbr
        and xxotm_shipments_t.location = v_location fetch first 1 rows only ;
        if l_validate_shipment_name  = 'STORE_AS_IT_IS' then
           select container_nbr into l_validate_container_nbr from xxotm_container_inventory_t 
           where container_stored_time is not null  and container_released_time is  null and container_nbr = l_container_nbr
           and xxotm_container_inventory_t.location = v_location fetch first 1 rows only;
            xxotm_log_activity(
               p_user_id        => p_user_id,
               p_module         => 'GATE_IN',
               p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
               p_action         => 'SUBMIT',
               p_entity_type    => 'TRUCK',
               p_entity_id      => l_truck,
               p_secondary_id   => l_container_nbr,
               p_response_code  => 400,
               p_message        => 'Container already in the yard',
               p_location       => v_location);
            apex_json.initialize_clob_output;
            apex_json.open_object;
             apex_json.write(
                 'response_code',
                 400
              );
              apex_json.write(
                 'response_message',
                 'Container present in the Yard'
              );
               apex_json.close_object;
               htp.prn(apex_json.get_clob_output);
               apex_json.free_output;
               return;
       end if;

       exception
       when others then 
       null;
    end;



   l_document_count := apex_json.get_count(
      p_values => l_values,
      p_path   => 'documents'
   );
   if l_document_count > 0 then
      for i in 1..l_document_count loop
         begin
            l_doc_xid := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].documentXid',
               p0       => i
            );
            l_doc_name := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].documentName',
               p0       => i
            );
            l_doc_mime := apex_json.get_varchar2(
               p_values => l_values,
               p_path   => 'documents[%d].documentMimeType',
               p0       => i
            );
            l_doc_content := apex_json.get_clob(
               p_values => l_values,
               p_path   => 'documents[%d].documentBase64Content',
               p0       => i
            );

            post_otm_documents(
               p_documentxid      => l_doc_xid,
               p_documentfilename => l_doc_name,
               p_ownerobjectgid   => 'NAQLEEN.'
                                   || replace(
                  l_shipment_nbr,
                  'NAQLEEN.',
                  ''
               ),
               p_clobcontent      => l_doc_content,
               p_documentmimetype => l_doc_mime,
               p_documentdefgid   => 'NAQLEEN.PACKING_LIST',
               x_response_clob    => l_doc_response
            );

            if l_doc_response like 'Error%' then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Document Error ('
                                  || l_doc_xid
                                  || '): '
                                  || l_doc_response
                                  || '; ';
            end if;
         exception
            when others then
               l_has_error := true;
               l_error_message := l_error_message
                                  || 'Document Exception ('
                                  || l_doc_xid
                                  || '): '
                                  || sqlerrm
                                  || '; ';
         end;
      end loop;
   end if;

   -- -------------------------------
   -- OPERATION 2: Process Tracking Events
   -- -------------------------------
   begin
      select shipment_name
        into l_shipment_name
        from xxotm_shipments_t
       where shipment_xid = l_shipment_nbr
       and xxotm_shipments_t.location = v_location;
   exception
      when no_data_found then
         l_shipment_name := null;
   end;

   if upper(l_shipment_name) not like '%INBOUND_CONTAINER'
   or upper(l_shipment_name) like '%CFS%'
   or upper(l_shipment_name) like '%STUFFING%'
   or upper(l_shipment_name) like '%DESTUFFING%'
   or upper(l_shipment_name) like '%STORE_AS_IT_IS%'
   or upper(l_shipment_name) like '%OFFLOADING_LCL%'
   or upper(l_shipment_name) like '%LOADING_LCL%' then
      -- Event 1: VEHICLE ENTERED
      select entry_time
        into l_entry_time
        from xxotm_vehicle_master_t xvmt
       where upper(truck_nbr) = upper(l_truck)
       and xvmt.location = v_location
       order by entry_time desc
       fetch first 1 rows only;

      begin
         post_otm_tracking_events(
            p_statuscodegid   => 'NAQLEEN.VEHICLE ENTERED',
            p_shipmentxid     => l_shipment_nbr,
            p_event_timestamp => l_entry_time,
            x_response        => l_event_response
         );
         if l_event_response like 'Error%' then
            l_has_error := true;
            l_error_message := l_error_message
                               || 'Event Error (NAQLEEN.VEHICLE ENTERED): '
                               || l_event_response
                               || '; ';
         end if;
      exception
         when others then
            l_has_error := true;
            l_error_message := l_error_message
                               || 'Event Exception (NAQLEEN.VEHICLE ENTERED): '
                               || sqlerrm
                               || '; ';
      end;
   end if;

   -- Event 2: GATE IN
   if upper(l_shipment_name) like '%CFS%'
   or upper(l_shipment_name) like '%STUFFING%'
   or upper(l_shipment_name) like '%DESTUFFING%'
   or upper(l_shipment_name) like '%STORE_AS_IT_IS%' then
      l_cfs_container_nbr := l_container_nbr;
   end if;

   if
      upper(l_shipment_name) like '%STORE_AS_IT_IS%'
      and l_remarks is not null
   then
      l_attribute5 := l_remarks;
   end if;

   begin
      post_otm_tracking_events(
         p_statuscodegid => 'NAQLEEN.GATE IN',
         p_shipmentxid   => l_shipment_nbr,
         p_attribute3    => l_cfs_container_nbr,
         p_attribute5    => l_attribute5,
         x_response      => l_event_response
      );
      if l_event_response like 'Error%' then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Error (NAQLEEN.GATE IN): '
                            || l_event_response
                            || '; ';
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Exception (NAQLEEN.GATE IN): '
                            || sqlerrm
                            || '; ';
   end;


   if(l_validate_leased_land = 'YES' AND l_shipment_name IN ('STORE_AS_IT_IS','INBOUND_CONTAINER' ))  THEN
      begin
      post_otm_tracking_events(
      	p_integration_name => 'XX_OTM_POST_POSITION_CONTAINER',
         p_statuscodegid => 'NAQLEEN.CONTAINER STORED',
         p_shipmentxid   => l_shipment_nbr,
         p_attribute1    => 'LEASED',
         p_attribute3    => l_cfs_container_nbr,
         p_attribute5    => l_attribute5,
         x_response      => l_event_response
      );

      -- vehicle master update 
      begin
         update xxotm_vehicle_master_t t
         set
            -- DUAL SHIPMENT: deferred exactly like OPERATION 4. This branch
            -- also advances the truck past the gate-in list filter, so on a
            -- two-shipment leased-land truck it would strand the second
            -- shipment just as surely as an early 'NAQLEEN.GATE IN' would.
            t.status = case
                          when l_done_ships >= l_expected_ships
                             then 'NAQLEEN.CONTAINER STORED'
                          else t.status
                       end,
            t.gate_in_shipments = l_gate_in_ships,
            t.gate_in_by = nvl(t.gate_in_by, p_user_id),
            -- DUAL CONTAINER: same accumulate-don't-overwrite rule as OPERATION 4.
            -- This branch fires for STORE_AS_IT_IS *and* INBOUND_CONTAINER, and
            -- INBOUND_CONTAINER is the main two-container flow -- so leaving the
            -- unconditional assignment here would have re-introduced, on leased
            -- land only, exactly the overwrite the CASE below exists to prevent.
            -- STORE_AS_IT_IS still overwrites, matching OPERATION 4 exactly.
            t.shipment_nbr = case
                                when l_shipment_name in ('OFFLOADING_LCL','LOADING_LCL',
                                                         'STORE_AS_IT_IS','RELEASE_CFS')
                                   then l_shipment_nbr
                                when t.shipment_nbr is null
                                   then l_shipment_nbr
                                when instr(',' || t.shipment_nbr || ',',
                                           ',' || l_shipment_nbr || ',') > 0
                                   then t.shipment_nbr   -- already recorded: re-scan or retry
                                when regexp_substr(t.shipment_nbr, '[^,]+', 1, 2) is not null
                                   then t.shipment_nbr   -- already two, matches c_max_ships
                                else t.shipment_nbr || ',' || l_shipment_nbr
                             end,
            t.user_id = p_user_id
         where t.truck_nbr = l_truck
            and t.exit_time is null
            and t.location  = v_location
            and t.entry_time = (
               select max(entry_time)
               from xxotm_vehicle_master_t
               where truck_nbr = l_truck
                  and exit_time is null
                  and xxotm_vehicle_master_t.location  = v_location
            );
            
            if sql%rowcount = 0 then
                  l_has_error := true;
                  l_error_message := l_error_message
                                    || 'Vehicle Master Update Failed: No matching record found for '
                                    || l_truck
                                    || '; ';
               else 
                  update xxotm_shipments_t
                  set
                  truck_3pl = l_truck, driver_3pl = l_driver
               where shipment_xid = l_shipment_nbr
               and xxotm_shipments_t.location = v_location;
               

               end if;
            exception
               when others then
                  l_has_error := true;
                  l_error_message := l_error_message
                                    || 'Vehicle Master Update Exception: '
                                    || sqlerrm
                                    || '; ';
      end;

      if l_event_response like 'Error%' then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Error (NAQLEEN.CONTAINER STORED): '
                            || l_event_response
                            || '; ';
      end if;
   exception
      when others then
         l_has_error := true;
         l_error_message := l_error_message
                            || 'Event Exception (NAQLEEN.CONTAINER STORED): '
                            || sqlerrm
                            || '; ';
   end;
   END IF;
   -- -------------------------------
   -- OPERATION 3: Update 3PL Truck/Driver
   -- -------------------------------
   if
      l_truck_type is not null
      and l_truck_type = '3PL'
   then
      begin
         l_request := json_object_t();
         l_request.put(
            'attribute7',
            l_truck
         );
         l_request.put(
            'attribute8',
            l_driver
         );
         l_request_clob := l_request.to_clob();
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         l_response_clob := apex_web_service.make_rest_request(
            p_url                  => xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.' || l_shipment_nbr
            ,
            p_http_method          => 'PATCH',
            p_credential_static_id => l_credential_static_id,
            p_body                 => l_request_clob,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
         );

         l_status := apex_web_service.g_status_code;
         if l_response_clob like 'Error%'
         or instr(
            lower(l_response_clob),
            'error'
         ) > 0 then
            l_has_error := true;
            l_error_message := l_error_message
                               || '3PL Update Error: '
                               || substr(
               l_response_clob,
               1,
               200
            )
                               || '; ';
         end if;
      exception
         when others then
            l_has_error := true;
            l_error_message := l_error_message
                               || '3PL Update Exception: '
                               || sqlerrm
                               || '; ';
      end;
   end if;

   -- -------------------------------
   -- OPERATION 4: Update Vehicle Master (regular update)
   -- -------------------------------
   if l_has_error != true then
      begin
         update xxotm_vehicle_master_t t
            set
            -- Only once every shipment on the truck is in. Until then the
            -- status is left untouched so the truck stays findable.
            t.status = case
                          when l_done_ships >= l_expected_ships
                             then 'NAQLEEN.GATE IN'
                          else t.status
                       end,
            t.gate_in_shipments = l_gate_in_ships,
            -- Claimed on the first shipment only; the ownership lock reads it.
            t.gate_in_by = nvl(t.gate_in_by, p_user_id),
            t.order_type = l_shipment_name,
            -- DUAL CONTAINER: a two-container truck carries BOTH shipments here,
            -- comma separated. That list form is what the rest of the system
            -- already expects -- XXOTM_DELETE_TRUCK_P unpacks element 1 AND 2
            -- with REGEXP_SUBSTR, XX_OTM_GET_POSITION_CONTAINER_TRUCKS splits on
            -- the comma, XX_OTM_SUBMIT_RELEASE_CONTAINER appends the same way,
            -- and the locals that read this column are sized 500/4000 rather
            -- than 100.
            --
            -- Prod overwrote unconditionally, so the second scan destroyed the
            -- first container's shipment. Merely keeping the old value instead
            -- would lose the SECOND one, which is no better. Append.
            --
            -- The single-shipment order types below own the column outright and
            -- keep prod's overwrite untouched; everything else accumulates.
            --
            -- The membership test is bounded by commas on BOTH sides: a bare
            -- INSTR(t.shipment_nbr, l_shipment_nbr) would report SH123 as
            -- already present when the column holds SH1234, and silently drop it.
            t.shipment_nbr = case
                                when l_shipment_name in ('OFFLOADING_LCL','LOADING_LCL',
                                                         'STORE_AS_IT_IS','RELEASE_CFS')
                                   then l_shipment_nbr
                                when t.shipment_nbr is null
                                   then l_shipment_nbr
                                when instr(',' || t.shipment_nbr || ',',
                                           ',' || l_shipment_nbr || ',') > 0
                                   then t.shipment_nbr   -- already recorded: re-scan or retry
                                when regexp_substr(t.shipment_nbr, '[^,]+', 1, 2) is not null
                                   then t.shipment_nbr   -- already two, matches c_max_ships
                                else t.shipment_nbr || ',' || l_shipment_nbr
                             end,
            t.user_id = p_user_id
          where t.truck_nbr = l_truck
            and t.exit_time is null
            and t.location  = v_location
            and t.entry_time = (
            select max(entry_time)
              from xxotm_vehicle_master_t
             where truck_nbr = l_truck
               and exit_time is null
               and xxotm_vehicle_master_t.location  = v_location
         );
        
         if sql%rowcount = 0 then
            l_has_error := true;
            l_error_message := l_error_message
                               || 'Vehicle Master Update Failed: No matching record found for '
                               || l_truck
                               || '; ';
         else 
            update xxotm_shipments_t
            set
            truck_3pl = l_truck, driver_3pl = l_driver
          where shipment_xid = l_shipment_nbr
          and xxotm_shipments_t.location = v_location;
         

         end if;
      exception
         when others then
            l_has_error := true;
            l_error_message := l_error_message
                               || 'Vehicle Master Update Exception: '
                               || sqlerrm
                               || '; ';
      end;
   end if;
   -- Clean up temporary CLOB
   if dbms_lob.istemporary(l_json_content) = 1 then
      dbms_lob.freetemporary(l_json_content);
   end if;

   -- -------------------------------
   -- Build JSON Response
   -- -------------------------------
   -- AUDIT. The main path. l_has_error is set by any of the document, event,
   -- 3PL or vehicle-master steps above, so a partial failure is recorded as a
   -- 500 here even though some of the work committed -- which is precisely the
   -- case worth being able to find later.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'GATE_IN',
      p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
      p_action         => 'SUBMIT',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck,
      p_secondary_id   => l_container_nbr,
      p_response_code  => case when l_has_error then 500 else 200 end,
      p_message        => nvl(l_error_message, l_shipment_name),
      p_location       => v_location);

   apex_json.initialize_clob_output;
   apex_json.open_object;
   if l_has_error then
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Partial or Full Failure: ' || l_error_message
      );
   else
      apex_json.write(
         'response_code',
         '200'   -- need to change to number for the next build
      );
      apex_json.write(
         'response_message',
         nvl(
            l_request_clob,
            'Success'
         )
      );
   end if;
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;

    else
       -- -------------------------------
       -- Shipment Not Found / Null
       -- -------------------------------
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'GATE_IN',
         p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
         p_action         => 'SUBMIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck,
         p_response_code  => 500,
         p_message        => 'No shipment number on the payload',
         p_location       => v_location);
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Shipment number not found. Please try again ' || l_error_message
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
   end if;

exception
   when others then
      -- Global Exception Handler
      if dbms_lob.istemporary(l_json_content) = 1 then
         dbms_lob.freetemporary(l_json_content);
      end if;
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'GATE_IN',
         p_procedure_name => 'XX_OTM_SUBMIT_GATE_IN',
         p_action         => 'SUBMIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck,
         p_secondary_id   => l_container_nbr,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_code',
         500
      );
      apex_json.write(
         'response_message',
         'Critical Error: ' || sqlerrm
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_submit_gate_in;

   -- ========================================================================
   -- XX_OTM_SUBMIT_GATE_OUT   [3d-high-risk / TAKE-PROD + test location]
   -- source: db/work/XX_OTM_SUBMIT_GATE_OUT.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_submit_gate_out (
   p_body    in blob,
   p_user_id in varchar2 default null          -- ?userId= from UserIdInterceptor
)
as
   c_proc constant varchar2(30) := 'XX_OTM_SUBMIT_GATE_OUT';
   v_location      varchar2(100);
   l_clob          clob;
   l_shipment_nbr  varchar2(100);
   l_truck_nbr     varchar2(100);
   l_status_code   varchar2(100);
   l_api_response  clob;
   l_response_code number := 200;
   l_response_msg  varchar2(4000) := 'Success';
    -- Blob conversion variables
   l_dest_offset   integer := 1;
   l_src_offset    integer := 1;
   l_lang_context  integer := dbms_lob.default_lang_ctx;
   l_warning       integer;
    -- EIR
   l_remarks       varchar2(4000);
   l_passed_user   varchar2(200);
   l_eir_ok        boolean := false;
   l_eir_msg       varchar2(4000);
    -- FIX 1 + FIX 2: ownership and concurrency
   l_vm_shipments  varchar2(4000);   -- comma list gate in recorded on this visit
   l_owned         number := 0;
   e_row_locked exception;
   pragma exception_init(e_row_locked, -54);

   procedure log_it (p_type varchar2, p_text varchar2) is
      pragma autonomous_transaction;                  -- survives a caller rollback
   begin
      insert into xx_otm_sync_logs
         (procedure_name, message_type, message_text, reference_id, log_timestamp)
      values (c_proc, p_type, substr(p_text, 1, 4000),
              nvl(l_shipment_nbr, l_truck_nbr), systimestamp);
      commit;
   exception
      when others then rollback;
   end;
begin
   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   l_clob := to_clob(p_body);

    -- Parse JSON
   apex_json.parse(l_clob);
   l_shipment_nbr := apex_json.get_varchar2('shipment_nbr');
   l_truck_nbr := apex_json.get_varchar2('truck_nbr');
   l_remarks := apex_json.get_varchar2('remarks');
   l_status_code := 'NAQLEEN.GATE OUT';

    -- FIX 3: normalise the shipment number HERE, not just before the OTM call.
    -- The ownership test below, post_otm_tracking_events, the EIR and the audit
    -- row must all see one form. ltrim/replace would eat a legitimate leading
    -- 'NAQLEEN.' only; substr(9) is exact because 'NAQLEEN.' is 8 characters.
   if l_shipment_nbr like 'NAQLEEN.%' then
      l_shipment_nbr := substr(
         l_shipment_nbr,
         9
      );
   end if;

    -- Resolve the operator's name for the EIR; fall back to the raw id
   begin
      select initcap(name)
        into l_passed_user
        from XX_USER_CONFIG
       where to_char(id) = trim(p_user_id);
   exception
      when others then
         l_passed_user := p_user_id;
   end;

    -- Both fields are mandatory. Checked explicitly because a null
    -- l_shipment_nbr would otherwise reach test (a) below, where the pattern
    -- degenerates to ',,' LIKE '%,,%' -- which is TRUE -- and a truck whose
    -- visit names no shipments would wave it straight through.
   if l_shipment_nbr is null or l_truck_nbr is null then
      l_response_code := 400;
      l_response_msg  := 'shipment_nbr and truck_nbr are both required.';
      log_it('ERROR', l_response_msg);
   end if;

    -- Confirm the truck is in the yard at THIS user's site before telling OTM
    -- anything. The tracking event is posted first and cannot be taken back: on
    -- a mismatch OTM would record a gate out, the UPDATE would then match no
    -- rows, and the caller would still get 200 plus an EIR for a gate out that
    -- never happened. Failing here lets the "if l_response_code = 200" guard
    -- skip the OTM call entirely.
    --
    -- FIX 2: the visit is now LOCKED, not merely read. FOR UPDATE takes the lock
    -- at OPEN on every matching row, so a second operator submitting the same
    -- truck gets ORA-00054 here -- translated to 409 -- instead of sailing past
    -- this check and posting a second GATE OUT. The lock is deliberately held
    -- across the OTM round trip and released by the commit after the UPDATE;
    -- releasing it earlier would reopen the exact window it exists to close.
    -- The comma list is read in the same pass, so FIX 1 below costs no extra
    -- query.
   if l_response_code = 200 then
      declare
         cursor c_visit is
         select shipment_nbr
           from xxotm_vehicle_master_t
          where truck_nbr = l_truck_nbr
            and exit_time is null
            and xxotm_vehicle_master_t.location = v_location
         for update nowait;
      begin
         open c_visit;
         fetch c_visit into l_vm_shipments;
         if c_visit%notfound then
            close c_visit;
            raise no_data_found;
         end if;
         close c_visit;
      exception
         when no_data_found then
            l_response_code := 404;
            l_response_msg  := 'Truck ' || l_truck_nbr
                               || ' is not in the yard at this location.';
            log_it('ERROR', l_response_msg);
         when e_row_locked then
            l_response_code := 409;
            l_response_msg  := 'Truck ' || l_truck_nbr
                               || ' is being gated out by another operator. '
                               || 'Try again in a moment.';
            log_it('ERROR', l_response_msg);
      end;
   end if;

    -- FIX 1: the shipment must belong to THIS truck. Two sources are accepted,
    -- because those are exactly the two XX_OTM_GATE_OUT_TRUCK_DETAILS offers the
    -- operator:
    --   (a) named on the truck's open visit  -- that procedure's PASS 1
    --   (b) linked to the truck by the sync  -- that procedure's PASS 2
    -- (b) also admits a shipment whose truck_3pl is still null: PASS 3 can
    -- surface a shipment from OTM before the sync has linked it, and rejecting
    -- that would break a path the details screen legitimately offers. It still
    -- requires the shipment to exist AT THIS SITE, which is what closes the
    -- cross-location hole. A shipment carrying a DIFFERENT truck_3pl, or one at
    -- another site, or one this database has never seen, is refused.
    --
    -- If this proves too strict in testing, relaxing it is one predicate -- but
    -- relax it deliberately, because silently gating out the wrong shipment is
    -- what it exists to prevent.
   if l_response_code = 200 then
      if ','
         || replace(replace(
               upper(l_vm_shipments),
               ' '
            ),
                    'NAQLEEN.')
         || ',' like '%,'
                     || upper(l_shipment_nbr)
                     || ',%' then
         l_owned := 1;                                   -- (a)
      else
         begin
            select 1
              into l_owned
              from xxotm_shipments_t s
             where s.shipment_xid in ( l_shipment_nbr,
                                       'NAQLEEN.' || l_shipment_nbr )
               and s.location = v_location
               and ( s.truck_3pl = l_truck_nbr
                or s.truck_3pl is null )
               and rownum = 1;                           -- (b)
         exception
            when no_data_found then
               l_owned := 0;
         end;
      end if;

      if l_owned = 0 then
         l_response_code := 409;
         l_response_msg  := 'Shipment ' || l_shipment_nbr
                            || ' is not on truck ' || l_truck_nbr
                            || ' at this location.';
         log_it('ERROR', l_response_msg);
      end if;
   end if;

    -- Call OTM Tracking Events API if local update was successful (or proceeded)
   if l_response_code = 200 then
      post_otm_tracking_events(
         p_statuscodegid => l_status_code,
         p_shipmentxid   => l_shipment_nbr,
         x_response      => l_api_response
      );

        -- Check API response
      if l_api_response like '%Error%' then
         l_response_code := 500;
         l_response_msg := 'OTM API Error: ' || l_api_response;
         log_it('ERROR', l_response_msg);
      else
        -- Update Vehicle Master Table
        begin
            update xxotm_vehicle_master_t
                set
                status = l_status_code,
                user_id = p_user_id
            where truck_nbr = l_truck_nbr
                and exit_time is null
                and xxotm_vehicle_master_t.location   = v_location;

            -- FIX 2: the OTM event is already posted and cannot be recalled, so
            -- a zero-row UPDATE must not fall through to the EIR. Holding the
            -- lock above should make this unreachable; if it ever fires, OTM and
            -- the yard have diverged and that has to surface as a 500, not as a
            -- 200 with an EIR for a gate out the database never recorded.
            if sql%rowcount = 0 then
               raise_application_error(
                  -20054,
                  'Truck ' || l_truck_nbr
                  || ' visit was closed by another session; OTM has the GATE OUT '
                  || 'event but the yard was not updated.'
               );
            end if;

            commit;

            -- Generate the EIR and push it to OTM. Gate out is already recorded by this
            -- point, so a document failure must never block the driver: warn, don't fail.
           
            begin
               xx_otm_generate_eir(
                  p_shipment_nbr => l_shipment_nbr,
                  p_truck_nbr    => l_truck_nbr,
                  p_remarks      => l_remarks,
                  p_passed_user  => l_passed_user,
                  -- Scopes the EIR's OTM order-release query to this operator's
                  -- site. Live prod hardcodes refnumValue eq "103", so a Dammam
                  -- gate out would resolve containers against Jeddah's releases.
                  p_user_id      => p_user_id,
                  x_ok           => l_eir_ok,
                  x_message      => l_eir_msg);

               if not nvl(l_eir_ok, false) then
                  l_response_msg := 'Success (warning: ' || l_eir_msg || ')';
                  log_it('ERROR', 'EIR not attached: ' || l_eir_msg);
               end if;
            exception
               when others then
                  l_eir_ok := false;
                  l_eir_msg := 'EIR failed: ' || sqlerrm;
                  l_response_msg := 'Success (warning: ' || l_eir_msg || ')';
                  log_it('ERROR', l_eir_msg);
            end;
        exception
            when others then
                l_response_code := 500;
                l_response_msg := 'Error updating vehicle master: ' || sqlerrm;
                log_it('ERROR', l_response_msg);
        end; 
      end if;
   end if;

    -- Clean up temporary CLOB
   if dbms_lob.istemporary(l_clob) = 1 then
      dbms_lob.freetemporary(l_clob);
   end if;

    -- AUDIT. l_response_code carries the real outcome by this point: 404 if the
    -- truck was not in the yard at this site, 500 if OTM rejected the event or
    -- the vehicle-master update failed, 200 otherwise. The EIR result rides in
    -- the message because a gate out that succeeded with an unattached EIR is a
    -- different operational event from a clean one.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'GATE_OUT',
      p_procedure_name => 'XX_OTM_SUBMIT_GATE_OUT',
      p_action         => 'SUBMIT',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck_nbr,
      p_secondary_id   => l_shipment_nbr,
      p_response_code  => l_response_code,
      p_message        => l_response_msg
                          || case when nvl(l_eir_ok, false) then ' | EIR ATTACHED'
                                  else ' | EIR FAILED: ' || l_eir_msg end,
      p_location       => v_location);

    -- Generate Response
   apex_json.initialize_clob_output;
   apex_json.open_object;
   apex_json.write('response_mssage',  l_response_msg);   -- existing key, kept as-is
   apex_json.write('response_message', l_response_msg);   -- correctly spelled, additive
   apex_json.write('response_code',    l_response_code);
   apex_json.write('eir_status',
      case when nvl(l_eir_ok, false) then 'ATTACHED' else 'FAILED' end);
   apex_json.write('eir_message',      l_eir_msg);
   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      if dbms_lob.istemporary(l_clob) = 1 then
         dbms_lob.freetemporary(l_clob);
      end if;

      log_it('ERROR', 'Unhandled: ' || sqlerrm);

      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'GATE_OUT',
         p_procedure_name => 'XX_OTM_SUBMIT_GATE_OUT',
         p_action         => 'SUBMIT',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck_nbr,
         p_secondary_id   => l_shipment_nbr,
         p_response_code  => 500,
         p_message        => sqlerrm,
         p_location       => v_location);

      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_submit_gate_out;

   -- ========================================================================
   -- XX_OTM_SUBMIT_RELEASE_CONTAINER   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_SUBMIT_RELEASE_CONTAINER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_submit_release_container (
   p_body    IN BLOB,
   p_user_id IN VARCHAR2 DEFAULT NULL
)
AS
   -- Response variables
   l_response_code        NUMBER := 200;
   l_response_msg         VARCHAR2(4000) := 'Success';
   -- Declared bare, assigned after BEGIN.
   v_location             VARCHAR2(100);

   -- ORA-00054, restored. This procedure issues five FOR UPDATE NOWAIT
   -- statements and prod guarded every one with a bare WHEN OTHERS, so a genuine
   -- defect inside those blocks was reported to the operator as "being processed
   -- by another session" and retried forever.
   e_row_locked           EXCEPTION;
   PRAGMA EXCEPTION_INIT(e_row_locked, -54);
   
   -- JSON parsing
   l_clob                 CLOB;
   l_values               APEX_JSON.T_VALUES;
   l_dest_offset          INTEGER := 1;
   l_src_offset           INTEGER := 1;
   l_lang_context         INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
   l_warning              INTEGER;
   
   -- Top-level fields
   l_truck_nbr            VARCHAR2(100);
   l_booking_nbr          VARCHAR2(100);
   l_order_type           VARCHAR2(50);
   l_customer_nbr         VARCHAR2(100);
   l_customer_name        VARCHAR2(200);
   l_driver_name          VARCHAR2(100);
   l_driver_iqama         VARCHAR2(100);
   l_entry_time           VARCHAR2(50);
   l_gate_in_time         VARCHAR2(50);
   l_release_type         VARCHAR2(100);
   l_container_count      PLS_INTEGER;
   
   -- Array processing structures
   TYPE t_cont_rec IS RECORD (
      container_nbr       VARCHAR2(100),
      container_type      VARCHAR2(50),
      shipment_nbr        VARCHAR2(100),
      position            VARCHAR2(200),
      order_nbr           VARCHAR2(100),
      inbound_shipment    VARCHAR2(100),
      lolo_count          NUMBER,
      plug_count          NUMBER,
      days_stored         NUMBER,
      terminal            VARCHAR2(50),
      block               VARCHAR2(50),
      lot_no              VARCHAR2(50),
      row_no              VARCHAR2(50),
      level_no            NUMBER
   );
   TYPE t_cont_tab IS TABLE OF t_cont_rec INDEX BY BINARY_INTEGER;
   l_containers t_cont_tab;
   
   -- Shipment de-duplication track
   TYPE t_str_bool IS TABLE OF BOOLEAN INDEX BY VARCHAR2(100);
   l_processed_shipments t_str_bool;
   
   -- Container payload de-duplication track
   l_processed_containers t_str_bool;
   
   -- Validation & Locks
   l_dummy                NUMBER;
   l_blocking_container   VARCHAR2(100);
   l_validation_errors    VARCHAR2(4000) := '';
   
   -- OTM Integration
   l_api_response         CLOB;
   l_credential_static_id VARCHAR2(20) := 'OTM_API_AUTH';

BEGIN
   -- =====================================================
   -- 1. BLOB → CLOB → JSON PARSE
   -- =====================================================
   IF p_body IS NULL THEN
      l_response_code := 400;
      l_response_msg  := 'Empty request body';
      GOTO build_response;
   END IF;

   DBMS_LOB.CREATETEMPORARY(l_clob, TRUE);
   DBMS_LOB.CONVERTTOCLOB(
      dest_lob     => l_clob,
      src_blob     => p_body,
      amount       => DBMS_LOB.GETLENGTH(p_body),
      dest_offset  => l_dest_offset,
      src_offset   => l_src_offset,
      blob_csid    => DBMS_LOB.DEFAULT_CSID,
      lang_context => l_lang_context,
      warning      => l_warning
   );

   v_location := xx_get_user_location(p_user_id);
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;

   BEGIN
      APEX_JSON.PARSE(p_values => l_values, p_source => l_clob);
   EXCEPTION
      WHEN OTHERS THEN
         l_response_code := 400;
         l_response_msg  := 'Invalid JSON payload';
         GOTO cleanup_and_respond;
   END;

   l_truck_nbr     := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'truck_nbr');
   l_booking_nbr   := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'booking_nbr');
   l_order_type    := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'order_type');
   l_customer_nbr  := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'customer_nbr');
   l_customer_name := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'customer_name');
   l_release_type  := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'release_type');

   IF l_truck_nbr IS NULL THEN
      l_response_code := 400;
      l_response_msg  := 'Missing required field: truck_nbr';
      GOTO cleanup_and_respond;
   END IF;

   -- =====================================================
   -- 1.5 VALIDATE: RACE CONDITION / TRUCK LOCK
   -- =====================================================
   BEGIN
      SELECT 1 INTO l_dummy
      FROM xxotm_vehicle_master_t
      WHERE upper(truck_nbr) = upper(l_truck_nbr)
        AND exit_time IS NULL
        AND xxotm_vehicle_master_t.location = v_location
        AND status = 'NAQLEEN.GATE IN'
        AND ROWNUM = 1
      FOR UPDATE NOWAIT;
   EXCEPTION
      WHEN NO_DATA_FOUND THEN
         l_response_code := 404;
         l_response_msg  := 'Truck ' || l_truck_nbr || ' not found for release or already released by another operator.';
         GOTO cleanup_and_respond;
      WHEN e_row_locked THEN
         l_response_code := 409;
         l_response_msg  := 'Truck ' || l_truck_nbr || ' is actively being released by another session. Please wait.';
         GOTO cleanup_and_respond;
   END;

   -- Get driver details and entry time
   BEGIN
      SELECT driver_name, driver_iqama, entry_time, gate_in_time
      INTO   l_driver_name, l_driver_iqama, l_entry_time, l_gate_in_time
      FROM   xxotm_vehicle_master_t
      WHERE  upper(truck_nbr) = upper(l_truck_nbr)
      AND    entry_time IS NOT NULL
      AND    exit_time IS NULL 
      AND    xxotm_vehicle_master_t.location = v_location
      AND    ROWNUM = 1;
   EXCEPTION
      WHEN NO_DATA_FOUND THEN
         l_driver_name  := NULL;
         l_driver_iqama := NULL;
         l_entry_time   := TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
         l_gate_in_time := l_entry_time;
   END;

   l_container_count := NVL(APEX_JSON.GET_COUNT(p_values => l_values, p_path => 'containers'), 0);
   IF l_container_count = 0 THEN
      l_response_code := 400;
      l_response_msg  := 'No containers specified';
      GOTO cleanup_and_respond;
   ELSIF l_container_count > 2 THEN
      l_response_code := 400;
      l_response_msg  := 'A maximum of 2 containers can be released at a time.';
      GOTO cleanup_and_respond;
   END IF;

   -- =====================================================
   -- PHASE 1: EXTRACT, VALIDATE DB STACKING & COLLECT COUNTS
   -- ALL READS HAPPEN HERE TO PREVENT HALFWAY FAILURES
   -- =====================================================
   FOR i IN 1..l_container_count LOOP
      l_containers(i).container_nbr  := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'containers[%d].container_nbr', p0 => i);
      l_containers(i).container_type := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'containers[%d].container_type', p0 => i);
      l_containers(i).shipment_nbr   := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'containers[%d].shipment_nbr', p0 => i);
      l_containers(i).position       := APEX_JSON.GET_VARCHAR2(p_values => l_values, p_path => 'containers[%d].position', p0 => i);

      -- Default counts
      l_containers(i).lolo_count := 0;
      l_containers(i).plug_count := 0;
      l_containers(i).days_stored := 0;

      -- ==========================================================
      -- VALIDATION: Prevent duplicate containers in payload
      -- ==========================================================
      IF l_processed_containers.EXISTS(l_containers(i).container_nbr) THEN
         l_response_code := 400;
         l_response_msg  := 'Duplicate container ' || l_containers(i).container_nbr || ' for the same truck.';
         GOTO cleanup_and_respond;
      ELSE
         l_processed_containers(l_containers(i).container_nbr) := TRUE;
      END IF;

      -- ==========================================================
      -- VALIDATION: Prevent releasing another truck's shipment
      -- ==========================================================
      IF l_order_type != 'RELEASE_CFS' THEN
         DECLARE
            l_check_shipment_3pl VARCHAR2(100);
         BEGIN
            SELECT truck_3pl 
            INTO   l_check_shipment_3pl 
            FROM   xxotm_shipments_t 
            WHERE  shipment_xid = l_containers(i).shipment_nbr
            and xxotm_shipments_t.location = v_location
            FOR UPDATE NOWAIT;
            
            IF l_check_shipment_3pl IS NOT NULL AND upper(l_check_shipment_3pl) != upper(l_truck_nbr) THEN
               l_response_code := 409;
               l_response_msg  := 'Shipment ' || l_containers(i).shipment_nbr || 
                                 ' is already assigned to a different truck (' || l_check_shipment_3pl || ').';
               l_validation_errors := l_validation_errors || ' Truck mismatch.';
               GOTO cleanup_and_respond;
            END IF;
         EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
            WHEN e_row_locked THEN
               l_response_code := 409;
               l_response_msg  := 'Shipment ' || l_containers(i).shipment_nbr || ' is currently being processed by another user.';
               GOTO cleanup_and_respond;
         END;
      END IF;

      -- ==========================================================
      -- VALIDATION: Ensure container is physically available and unreleased
      -- ==========================================================
      IF l_order_type != 'RELEASE_CFS' THEN
         BEGIN
            SELECT 1 INTO l_dummy
            FROM   xxotm_container_inventory_t
            WHERE  container_nbr = l_containers(i).container_nbr
            AND    container_released_time IS NULL
            AND    xxotm_container_inventory_t.location = v_location
            AND    ROWNUM = 1
            FOR UPDATE NOWAIT;
         EXCEPTION
            WHEN NO_DATA_FOUND THEN
               l_response_code := 404;
               l_response_msg  := 'Container ' || l_containers(i).container_nbr || ' is already released or not found in inventory.';
               GOTO cleanup_and_respond;
            WHEN e_row_locked THEN
               l_response_code := 409;
               l_response_msg  := 'Container ' || l_containers(i).container_nbr || ' is actively being processed by another session.';
               GOTO cleanup_and_respond;
         END;
      ELSE
         BEGIN
            SELECT 1 INTO l_dummy
            FROM   xxotm_cfs_containers_t
            WHERE  container_nbr = l_containers(i).container_nbr
            AND    release_date IS NULL
            AND    xxotm_cfs_containers_t.location = v_location
            AND    ROWNUM = 1
            FOR UPDATE NOWAIT;
         EXCEPTION
            WHEN NO_DATA_FOUND THEN
               BEGIN
                  SELECT 1 INTO l_dummy
                  FROM   xxotm_container_inventory_t
                  WHERE  container_nbr = l_containers(i).container_nbr
                  AND    container_released_time IS NULL
                  AND    xxotm_container_inventory_t.location = v_location
                  AND    ROWNUM = 1
                  FOR UPDATE NOWAIT;
               EXCEPTION
                  WHEN NO_DATA_FOUND THEN NULL;
                  WHEN e_row_locked THEN
                     l_response_code := 409;
                     l_response_msg  := 'Container ' || l_containers(i).container_nbr || ' is actively being processed by another session.';
                     GOTO cleanup_and_respond;
               END;
            WHEN e_row_locked THEN
               l_response_code := 409;
               l_response_msg  := 'CFS Container ' || l_containers(i).container_nbr || ' is actively being processed by another session.';
               GOTO cleanup_and_respond;
         END;
      END IF;

      -- Parse Position & Validate Stack Safely
      IF l_containers(i).position IS NOT NULL AND l_containers(i).position != 'CFS' THEN
         l_containers(i).terminal := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 1);
         l_containers(i).block    := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 2);
         l_containers(i).lot_no   := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 3);
         l_containers(i).row_no   := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 4);
         
         DECLARE
            v_lvl_token VARCHAR2(50) := REGEXP_SUBSTR(l_containers(i).position, '[^-]+', 1, 5);
         BEGIN
            IF v_lvl_token IS NOT NULL AND REGEXP_LIKE(v_lvl_token, '^[0-9]+$') THEN
               l_containers(i).level_no := TO_NUMBER(v_lvl_token);
            ELSE
               l_containers(i).level_no := 6;
            END IF;
         EXCEPTION
            WHEN OTHERS THEN l_containers(i).level_no := 6;
         END;

         -- Stacking check: String-based comparison to prevent ORA-01722
         IF l_containers(i).level_no < 6 THEN
            FOR check_level IN (l_containers(i).level_no + 1)..6 LOOP
               BEGIN
                  SELECT MAX(container_nbr) INTO l_blocking_container
                  FROM   xxotm_position_master_t
                  WHERE  terminal = l_containers(i).terminal
                  AND    block = l_containers(i).block
                  AND    TO_CHAR(lot_no) = l_containers(i).lot_no
                  AND    row_no = l_containers(i).row_no
                  AND    TO_CHAR(level_no) = TO_CHAR(check_level)
                  AND    shipment_nbr IS NOT NULL 
                  AND    is_occupied != 'N'
                  AND    ROWNUM = 1
                  and xxotm_position_master_t.location = v_location;

                  IF l_blocking_container IS NOT NULL THEN
                     l_validation_errors := l_validation_errors || 
                        ' Container ' || l_containers(i).container_nbr || ' is physically blocked by ' || l_blocking_container || '.';
                     EXIT;
                  END IF;
               EXCEPTION
                  WHEN NO_DATA_FOUND THEN NULL;
               END;
            END LOOP;
         END IF;
      END IF;
      
      -- Extract Order & Inbound Shipment
      BEGIN
         SELECT order_release_xid INTO l_containers(i).order_nbr
         FROM   xxotm_order_movements_t
         WHERE  shipment_xid = l_containers(i).shipment_nbr AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN l_containers(i).order_nbr := NULL; END;

      BEGIN
         SELECT inbound_shipment_nbr INTO l_containers(i).inbound_shipment
         FROM   xxotm_container_inventory_t
         WHERE  container_nbr = l_containers(i).container_nbr
         AND    container_stored_time IS NOT NULL 
         AND    container_released_time IS NULL 
         AND    xxotm_container_inventory_t.location = v_location
         ORDER BY container_stored_time DESC FETCH FIRST 1 ROWS ONLY;
      EXCEPTION WHEN NO_DATA_FOUND THEN l_containers(i).inbound_shipment := NULL; END;

      -- Calculate LOLO & Plug Metrics
      IF l_containers(i).inbound_shipment IS NOT NULL THEN
         SELECT COUNT(*) INTO l_containers(i).lolo_count
         FROM   xxotm_restack_lolo_t
         WHERE  container_nbr = l_containers(i).container_nbr 
         AND    inbound_shipment_nbr = l_containers(i).inbound_shipment;

         SELECT COUNT(*) INTO l_containers(i).plug_count
         FROM   xxotm_pluginout_t
         WHERE  container_nbr = l_containers(i).container_nbr 
         AND    inbound_shipment_nbr = l_containers(i).inbound_shipment;
      END IF;

      -- Days stored calc
      DECLARE
         l_stored_time VARCHAR2(100);
      BEGIN
         SELECT container_stored_time INTO l_stored_time
         FROM   xxotm_container_inventory_t
         WHERE  container_nbr = l_containers(i).container_nbr 
         AND    inbound_shipment_nbr = l_containers(i).inbound_shipment AND ROWNUM = 1
         and xxotm_container_inventory_t.location = v_location;
         
         IF l_stored_time IS NOT NULL AND LENGTH(TRIM(l_stored_time)) > 0 THEN
            BEGIN
               l_containers(i).days_stored := EXTRACT(DAY FROM (SYS_EXTRACT_UTC(SYSTIMESTAMP) - TO_TIMESTAMP(l_stored_time, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')));
            EXCEPTION WHEN OTHERS THEN
               BEGIN
                  l_containers(i).days_stored := EXTRACT(DAY FROM (SYS_EXTRACT_UTC(SYSTIMESTAMP) - TO_TIMESTAMP(l_stored_time, 'YYYY-MM-DD"T"HH24:MI:SS.FF"Z"')));
               EXCEPTION WHEN OTHERS THEN
                  l_containers(i).days_stored := 0;
               END;
            END;
         ELSE
            l_containers(i).days_stored := 0;
         END IF;
      EXCEPTION WHEN OTHERS THEN l_containers(i).days_stored := 0; END;
   END LOOP;

   -- Break execution on any physical blockages before API calls
   IF l_validation_errors IS NOT NULL AND LENGTH(TRIM(l_validation_errors)) > 0 THEN
      l_response_code := 400;
      l_response_msg  := 'Stacking validation failed:' || l_validation_errors;
      GOTO cleanup_and_respond;
   END IF;

   -- =====================================================
   -- PHASE 2: OTM API NETWORK INTEGRATION
   -- Done entirely before ANY Local DB updates.
   -- =====================================================
   FOR i IN 1..l_container_count LOOP
      
      -- SHIPMENT-LEVEL EVENTS: Execute ONLY ONCE per unique shipment
      IF l_order_type != 'RELEASE_CFS' AND NOT l_processed_shipments.EXISTS(l_containers(i).shipment_nbr) THEN
         
         -- Vehicle Entered Event
         post_otm_tracking_events(
            p_statuscodegid   => 'NAQLEEN.VEHICLE ENTERED',
            p_shipmentxid     => l_containers(i).shipment_nbr,
            p_event_timestamp => l_entry_time,
            x_response        => l_api_response
         );
         IF l_api_response LIKE '%Error%' THEN
            l_response_code := 500; l_response_msg := 'VEHICLE ENTERED failed against shipment ' || l_containers(i).shipment_nbr;
            GOTO cleanup_and_respond;
         END IF;

         -- Gate In Event
         post_otm_tracking_events(
            p_statuscodegid   => 'NAQLEEN.GATE IN',
            p_shipmentxid     => l_containers(i).shipment_nbr,
            p_event_timestamp => l_gate_in_time,
            x_response        => l_api_response
         );
         IF l_api_response LIKE '%Error%' THEN
            l_response_code := 500; l_response_msg := 'GATE IN failed against shipment ' || l_containers(i).shipment_nbr;
            GOTO cleanup_and_respond;
         END IF;

         -- 3PL PATCH to Cloud
         DECLARE
            l_request       JSON_OBJECT_T;
            l_request_clob  CLOB;
            l_response_clob CLOB;
         BEGIN
            l_request := JSON_OBJECT_T();
            l_request.put('attribute7', l_truck_nbr);
            l_request.put('attribute8', l_driver_iqama);
            l_request_clob := l_request.to_clob();

            APEX_WEB_SERVICE.G_REQUEST_HEADERS.DELETE;
            APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).name  := 'Content-Type';
            APEX_WEB_SERVICE.G_REQUEST_HEADERS(1).value := 'application/json';

            l_response_clob := APEX_WEB_SERVICE.MAKE_REST_REQUEST(
               p_url         => xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/NAQLEEN.' || l_containers(i).shipment_nbr,
               p_http_method => 'PATCH',
               p_credential_static_id => l_credential_static_id,
               p_body        => l_request_clob,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );

            IF l_response_clob LIKE '%Error%' OR INSTR(LOWER(l_response_clob), 'error') > 0 THEN
               l_response_code := 500;
               l_response_msg  := '3PL Cloud Update failed for shipment ' || l_containers(i).shipment_nbr;
               GOTO cleanup_and_respond;
            END IF;
         EXCEPTION
            WHEN OTHERS THEN
               l_response_code := 500; l_response_msg := '3PL Route crash: ' || SQLERRM;
               GOTO cleanup_and_respond;
         END;
         
         -- Flag shipment as done
         l_processed_shipments(l_containers(i).shipment_nbr) := TRUE;
      END IF;

      -- CONTAINER-LEVEL EVENT: Released
      post_otm_tracking_events(
         p_integration_name  => 'XX_OTM_RELEASE_CONTAINER',
         p_statuscodegid     => 'NAQLEEN.CONTAINER RELEASED',
         p_shipmentxid       => l_containers(i).shipment_nbr,
         p_attribute3        => l_containers(i).container_nbr,
         p_attribute_number1 => l_containers(i).days_stored,
         p_attribute_number2 => l_containers(i).lolo_count + 1,
         p_attribute_number3 => l_containers(i).plug_count,
         x_response          => l_api_response
      );
      IF l_api_response LIKE '%Error%' THEN
         l_response_code := 500; l_response_msg := 'CONTAINER RELEASED API failed for ' || l_containers(i).container_nbr;
         GOTO cleanup_and_respond;
      END IF;

   END LOOP;

   -- =====================================================
   -- PHASE 3: LOCAL DATABASE COMMITS & INVENTORY ROLLUPS
   -- =====================================================
   l_processed_shipments.DELETE;
   
   FOR i IN 1..l_container_count LOOP

      -- A) Shipments Table 3PL Update (Once per unique shipment)
      IF l_order_type != 'RELEASE_CFS' AND NOT l_processed_shipments.EXISTS(l_containers(i).shipment_nbr) THEN
          UPDATE xxotm_vehicle_master_t
          -- Membership must be comma-bounded on BOTH sides. The bare
          -- INSTR(shipment_nbr, x) this replaced reported SH123 as already
          -- present whenever the column held SH1234, and silently dropped it --
          -- the same list the gate-in path builds, so the tests must agree.
          -- The 2-element cap is already enforced upstream: this procedure
          -- rejects payloads with more than 2 containers.
          SET    shipment_nbr = CASE
                    WHEN shipment_nbr IS NULL THEN l_containers(i).shipment_nbr
                    WHEN INSTR(',' || shipment_nbr || ',',
                               ',' || l_containers(i).shipment_nbr || ',') > 0 THEN shipment_nbr
                    ELSE shipment_nbr || ',' || l_containers(i).shipment_nbr
                 END
          WHERE  upper(truck_nbr) = upper(l_truck_nbr)
          AND    entry_time IS NOT NULL 
          AND    exit_time IS NULL
          AND    xxotm_vehicle_master_t.location = v_location;
          
          INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
          VALUES ('xx_otm_submit_release_container', 'INFO', 'Added shipment ' || l_containers(i).shipment_nbr || ' to vehicle ' || l_truck_nbr, l_truck_nbr);
          
          UPDATE xxotm_shipments_t 
          SET    truck_3pl = l_truck_nbr, driver_3pl = l_driver_name
          WHERE  shipment_xid = l_containers(i).shipment_nbr
          and xxotm_shipments_t.location = v_location;
          
          l_processed_shipments(l_containers(i).shipment_nbr) := TRUE;
      END IF;

      -- B) CFS Special Handlers
      IF l_release_type = 'CFS_CONTAINER' THEN
         UPDATE xxotm_cfs_containers_t
         SET    release_date = TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"')
         WHERE  container_nbr = l_containers(i).container_nbr 
         AND    shipment_nbr = l_containers(i).shipment_nbr
         and xxotm_cfs_containers_t.location = v_location;
      END IF;

      IF l_containers(i).position = 'CFS' THEN
         UPDATE xxotm_cfs_containers_t
         SET    release_date = TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"')
         WHERE  container_nbr = l_containers(i).container_nbr 
         AND    release_date IS NULL
         AND    xxotm_cfs_containers_t.location = v_location;
      END IF;

      -- C) Position Master Updates (Release Yard Slot)
      IF l_containers(i).position IS NOT NULL AND l_containers(i).position != 'CFS' THEN
         UPDATE xxotm_position_master_t
         SET    is_occupied       = 'N',
                shipment_nbr      = NULL,
                container_nbr     = NULL,
                last_event_time   = SYSTIMESTAMP,
                last_event_source = 'MOBILE'
         WHERE  shipment_nbr = l_containers(i).inbound_shipment 
         AND    is_occupied = l_containers(i).container_nbr
         and xxotm_position_master_t.location = v_location;

         IF SQL%ROWCOUNT > 0 THEN
            INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
            VALUES ('xx_otm_submit_release_container', 'INFO', 'Released: Freed position ' || l_containers(i).position || ' for container ' || l_containers(i).container_nbr, l_containers(i).shipment_nbr);
         ELSE
            INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
            VALUES ('xx_otm_submit_release_container', 'WARNING', 'Released: Failed to free position (not found or condition mismatch)', l_containers(i).shipment_nbr);
         END IF;
      END IF;

      -- D) Container Inventory Timeline
      UPDATE xxotm_container_inventory_t
      SET    outbound_shipment_nbr  = l_containers(i).shipment_nbr,
             outbound_order_nbr     = l_containers(i).order_nbr,
             container_released_time = TO_CHAR(SYS_EXTRACT_UTC(SYSTIMESTAMP), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"')
      WHERE  container_nbr = l_containers(i).container_nbr
      AND    inbound_shipment_nbr = l_containers(i).inbound_shipment
      and xxotm_container_inventory_t.location = v_location;

      -- D2) Stamp the container number onto the inventory row keyed by the
      -- RELEASE shipment. Added to prod after prod_procedures.sql was taken --
      -- found by db/tools/drift_scan.py, not present in the snapshot this merge
      -- was built from. Carried verbatim except for the location predicate,
      -- which every other statement in this procedure now has.
      --
      -- Keyed on the RELEASE shipment, which is a DIFFERENT row from the one
      -- D) just closed: D) matches on the container's INBOUND shipment, this
      -- matches the row the sync creates for the outbound leg, where the
      -- release shipment is that row's inbound_shipment_nbr and container_nbr
      -- is still null. It records which physical container went out.
      --
      -- Safe under dual container: shipment:container is 1:1, so each loop
      -- iteration carries its own shipment_nbr and the two iterations match
      -- disjoint rows. (An earlier revision of this comment warned about two
      -- containers sharing one release shipment overwriting each other -- that
      -- cannot happen under the 1:1 model. A truck carries up to two SHIPMENTS,
      -- one container each; it never carries two containers on one shipment.)
      UPDATE xxotm_container_inventory_t xcit
      SET    container_nbr = l_containers(i).container_nbr
      WHERE  inbound_shipment_nbr = l_containers(i).shipment_nbr
      AND    xcit.location = v_location;

   END LOOP;

   -- E) Final Gate-Release Status Update
   UPDATE xxotm_vehicle_master_t
   SET    status = 'NAQLEEN.CONTAINER RELEASED',
          user_id = p_user_id
   WHERE  upper(truck_nbr) = upper(l_truck_nbr)
   AND    entry_time IS NOT NULL 
   AND    exit_time IS NULL 
   AND    status LIKE '%GATE IN%'
   AND    xxotm_vehicle_master_t.location = v_location;

   COMMIT;

<<build_response>>
   -- AUDIT. Success falls through; every rejection arrives via
   -- cleanup_and_respond. The CASE guard matters -- a payload rejected before
   -- the extract loop leaves l_containers empty, and evaluating
   -- l_containers(1) would raise before xxotm_log_activity could swallow it.
   xxotm_log_activity(
      p_user_id        => p_user_id,
      p_module         => 'RELEASE',
      p_procedure_name => 'XX_OTM_SUBMIT_RELEASE_CONTAINER',
      p_action         => 'RELEASE',
      p_entity_type    => 'TRUCK',
      p_entity_id      => l_truck_nbr,
      p_secondary_id   => case when l_containers.COUNT > 0
                               then l_containers(1).container_nbr end,
      p_response_code  => l_response_code,
      p_message        => l_response_msg,
      p_location       => v_location);

   APEX_JSON.INITIALIZE_CLOB_OUTPUT;
   APEX_JSON.OPEN_OBJECT;
   APEX_JSON.WRITE('response_message',     l_response_msg);
   APEX_JSON.WRITE('response_code',        l_response_code);
   APEX_JSON.WRITE('containers_processed', l_container_count);
   APEX_JSON.WRITE('truck_nbr',            l_truck_nbr);
   APEX_JSON.CLOSE_OBJECT;
   HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
   APEX_JSON.FREE_OUTPUT;
   GOTO cleanup;

<<cleanup_and_respond>>
   ROLLBACK;
   IF l_response_code >= 400 THEN
       INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
       VALUES ('xx_otm_submit_release_container', 'ERROR', 
               'Response: ' || NVL(l_response_msg, 'Unknown') || ' | Trace: ' || NVL(l_validation_errors, 'No detail available'), l_truck_nbr);
       COMMIT;
   END IF;
   GOTO build_response;

<<cleanup>>
   IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
      DBMS_LOB.FREETEMPORARY(l_clob);
   END IF;

EXCEPTION
   WHEN OTHERS THEN
      ROLLBACK;
      -- This path never reaches build_response.
      xxotm_log_activity(
         p_user_id        => p_user_id,
         p_module         => 'RELEASE',
         p_procedure_name => 'XX_OTM_SUBMIT_RELEASE_CONTAINER',
         p_action         => 'RELEASE',
         p_entity_type    => 'TRUCK',
         p_entity_id      => l_truck_nbr,
         p_response_code  => 500,
         p_message        => SQLERRM,
         p_location       => v_location);

      APEX_JSON.INITIALIZE_CLOB_OUTPUT;
      APEX_JSON.OPEN_OBJECT;
      APEX_JSON.WRITE('response_message', 'Server error: ' || SQLERRM);
      APEX_JSON.WRITE('response_code',    500);
      APEX_JSON.CLOSE_OBJECT;
      HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT());
      APEX_JSON.FREE_OUTPUT;
      IF DBMS_LOB.ISTEMPORARY(l_clob) = 1 THEN
         DBMS_LOB.FREETEMPORARY(l_clob);
      END IF;
END XX_OTM_SUBMIT_RELEASE_CONTAINER;

   -- ========================================================================
   -- XX_OTM_UPDATE_CONTAINER_NUMBERS   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_OTM_UPDATE_CONTAINER_NUMBERS.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_update_container_numbers
AS
    V_SQL VARCHAR2(4000);
    V_COUNT NUMBER;
BEGIN
    -- Get count of available container numbers from shipments
    SELECT COUNT(DISTINCT cont_no) INTO V_COUNT
    FROM xxotm_shipments_t 
    WHERE cont_no IS NOT NULL 
    AND cont_no != ' ';
    
    DBMS_OUTPUT.PUT_LINE('Available container patterns: ' || V_COUNT);
    
    -- Update container inventory with random container numbers from shipments
    -- Using DBMS_RANDOM to select random container numbers
    V_SQL := 'UPDATE XXOTM_CONTAINER_INVENTORY_T ci 
              SET container_nbr = (
                SELECT cont_no 
                FROM (
                  SELECT cont_no, 
                         ROW_NUMBER() OVER (ORDER BY DBMS_RANDOM.RANDOM) as rn
                  FROM xxotm_shipments_t 
                  WHERE cont_no IS NOT NULL 
                  AND cont_no != '' ''
                ) sh 
                WHERE sh.rn = MOD(DBMS_RANDOM.RANDOM, ' || V_COUNT || ') + 1
              )';
    
    EXECUTE IMMEDIATE V_SQL;
    
    COMMIT;
    
    DBMS_OUTPUT.PUT_LINE('Container numbers updated successfully');
    
    -- Show sample results
    FOR REC IN (SELECT container_nbr FROM XXOTM_CONTAINER_INVENTORY_T WHERE ROWNUM <= 5 ORDER BY DBMS_RANDOM.RANDOM) LOOP
        DBMS_OUTPUT.PUT_LINE('Updated container: ' || REC.container_nbr);
    END LOOP;
    
EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);
        ROLLBACK;
END XX_OTM_UPDATE_CONTAINER_NUMBERS;

   -- ========================================================================
   -- XX_OTM_UPDATE_CONTAINER_TYPE   [3c-both-moved / MANUAL 3-way]
   -- source: db/work/XX_OTM_UPDATE_CONTAINER_TYPE.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_update_container_type (
    body IN BLOB
)
AS
    -- Last Updated Date : 18-Jun-2026
    -- Last Updated By   : Antigravity AI
    -- Description       : 1. Parses JSON Body.
    --                     2. Conditional Restack Logic (if positioned).
    --                     3. OTM Shipment Refnum Sync (GET -> DELETE ALL -> POST NEW).
    --                     4. OTM Order Release Refnum Sync (GET -> DELETE ALL -> POST NEW).
    --                     5. Synchronizes Local Tables and Position Master.
    --                     6. Logs to xx_otm_sync_logs.

    l_body_clob               CLOB;
    l_container_nbr           VARCHAR2(100);
    l_shipment_nbr            VARCHAR2(100);
    l_order_nbr               VARCHAR2(100);
    l_container_type          VARCHAR2(100);
    l_position                VARCHAR2(100);
    l_new_position            VARCHAR2(100) := 'NA';

    l_url                     VARCHAR2(32767);
    l_payload                 CLOB;
    l_response_clob           CLOB;
    l_api_response            CLOB;
    l_credential_static_id    VARCHAR2(50) := 'OTM_API_AUTH';
    l_shipment_gid            VARCHAR2(200);
    l_order_gid               VARCHAR2(200);

    l_ref_count               NUMBER;
    l_ref_val                 VARCHAR2(200);

    v_curr_terminal           VARCHAR2(100);
    v_curr_block              VARCHAR2(100);
    v_curr_lot_no             VARCHAR2(100);
    v_curr_row_no             VARCHAR2(100);
    v_curr_level_no           VARCHAR2(100);
    v_inv_rows                NUMBER;
    l_container_stored_time   VARCHAR2(100);
    l_container_released_time VARCHAR2(100);

    PROCEDURE add_log_internal(p_msg IN VARCHAR2) IS
    BEGIN
        INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
        VALUES ('xx_otm_update_container_type', 'DEBUG', p_msg, l_shipment_nbr);
    END;

BEGIN
    -- Step 1: Parse JSON from Body
    l_body_clob      := TO_CLOB(body);
    apex_json.parse(l_body_clob);
    l_container_nbr  := apex_json.get_varchar2('container_nbr');
    l_shipment_nbr   := apex_json.get_varchar2('shipment_nbr');
    l_order_nbr      := apex_json.get_varchar2('order_nbr');
    l_container_type := apex_json.get_varchar2('container_type');

    -- Prepend domain if missing (Shipment)
    IF instr(l_shipment_nbr, '.') = 0 THEN
        l_shipment_gid := 'NAQLEEN.' || l_shipment_nbr;
    ELSE
        l_shipment_gid := l_shipment_nbr;
    END IF;

    -- Prepend domain if missing (Order)
    IF l_order_nbr IS NOT NULL THEN
        IF instr(l_order_nbr, '.') = 0 THEN
            l_order_gid := 'NAQLEEN.' || l_order_nbr;
       
        END IF;
    END IF;

    -- Step 2: Fetch Current Position
    BEGIN
        SELECT position, container_stored_time, container_released_time, inbound_order_nbr
          INTO l_position, l_container_stored_time, l_container_released_time,l_order_nbr
          FROM xxotm_container_inventory_t
         WHERE container_nbr = l_container_nbr
           AND inbound_shipment_nbr = l_shipment_nbr
           AND rownum = 1;        	
           l_order_gid := 'NAQLEEN.' ||l_order_nbr;
    EXCEPTION
        WHEN OTHERS THEN
            l_position := 'NA';
    END;

    -- Step 3: Conditional Restack Operation (Only if position != 'NA')
    IF nvl(l_position, 'NA') != 'NA' AND (l_container_stored_time IS NOT NULL AND l_container_released_time IS NULL) THEN
        add_log_internal('Triggering Restack for container ' || l_container_nbr || ' at ' || l_position);

        BEGIN
            v_curr_terminal := substr(l_position, 1, instr(l_position, '-', 1, 1) - 1);
            v_curr_block    := substr(l_position, instr(l_position, '-', 1, 1) + 1, instr(l_position, '-', 1, 2) - instr(l_position, '-', 1, 1) - 1);
            v_curr_lot_no   := substr(l_position, instr(l_position, '-', 1, 2) + 1, instr(l_position, '-', 1, 3) - instr(l_position, '-', 1, 2) - 1);
            v_curr_row_no   := substr(l_position, instr(l_position, '-', 1, 3) + 1, instr(l_position, '-', 1, 4) - instr(l_position, '-', 1, 3) - 1);
            v_curr_level_no := substr(l_position, instr(l_position, '-', 1, 4) + 1);
        EXCEPTION
            WHEN OTHERS THEN
                add_log_internal('Error parsing position format: ' || l_position);
        END;

        BEGIN
            post_otm_tracking_events(
                p_integration_name => 'XX_OTM_RESTACK_CONTAINER',
                p_statuscodegid    => 'NAQLEEN.CONTAINER_RESTACKED',
                p_shipmentxid      => l_shipment_nbr,
                p_attribute3       => l_container_nbr,
                p_attribute1       => 'NA',
                x_response         => l_api_response
            );
        EXCEPTION
            WHEN OTHERS THEN
                add_log_internal('OTM Restack Integration Error: ' || SQLERRM);
        END;

        UPDATE xxotm_position_master_t
           SET shipment_nbr      = NULL,
               container_nbr     = NULL,
               is_occupied        = 'N',
               last_event_time    = SYSTIMESTAMP,
               last_event_source  = 'MOBILE'
         WHERE container_nbr  = l_container_nbr
           AND shipment_nbr   = l_shipment_nbr;

        UPDATE xxotm_container_inventory_t
           SET position = l_new_position
         WHERE container_nbr         = l_container_nbr
           AND inbound_shipment_nbr  = l_shipment_nbr;

        BEGIN
            xxotm_container_grvity_script_p();
        END;

        add_log_internal('Restack complete. Position cleared to NA.');
    END IF;

    -- Step 4: OTM Shipment Refnum Synchronization (GET -> DELETE -> POST)
    l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
             || l_shipment_gid
             || '/refnums?q=shipmentRefnumQualGid eq "NAQLEEN.CONTAINER_TYPE"&fields=shipmentRefnumValue';

    BEGIN
        apex_web_service.g_request_headers.DELETE;
        l_response_clob := apex_web_service.make_rest_request(
            p_url         => l_url,
            p_http_method => 'GET',
           p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
        );

        apex_json.parse(l_response_clob);
        l_ref_count := apex_json.get_count('items');

        IF l_ref_count > 0 THEN
            FOR i IN 1..l_ref_count LOOP
                l_ref_val := apex_json.get_varchar2('items[%d].shipmentRefnumValue', i);
                IF l_ref_val IS NOT NULL THEN
                    l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                             || l_shipment_gid
                             || '/refnums/NAQLEEN.CONTAINER_TYPEx' || l_ref_val;

                    BEGIN
                        apex_web_service.g_request_headers.DELETE;
                        l_response_clob := apex_web_service.make_rest_request(
                            p_url         => l_url,
                            p_http_method => 'DELETE',
                           p_credential_static_id => l_credential_static_id,
                            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                        );
                    EXCEPTION WHEN OTHERS THEN NULL; END;
                END IF;
            END LOOP;
        END IF;
    EXCEPTION WHEN OTHERS THEN NULL; END;

    -- Local Table Updates (Shipment)
    UPDATE xxotm_shipments_t
       SET container_type = l_container_type,
           update_date    = SYSDATE
     WHERE shipment_xid = l_shipment_nbr;

    UPDATE xxotm_container_inventory_t
       SET container_type = l_container_type
     WHERE container_nbr        = l_container_nbr
       AND inbound_shipment_nbr = l_shipment_nbr;

    -- POST New Refnum to Shipment
    l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
             || l_shipment_gid
             || '/refnums';

    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write('shipmentRefnumQualGid', 'NAQLEEN.CONTAINER_TYPE');
    apex_json.write('shipmentRefnumValue',   l_container_type);
    apex_json.write('domainName',            'NAQLEEN');
    apex_json.close_object;
    l_payload := apex_json.get_clob_output;
    apex_json.free_output;

    BEGIN
        apex_web_service.g_request_headers.DELETE;
        apex_web_service.g_request_headers(1).name  := 'Content-Type';
        apex_web_service.g_request_headers(1).value := 'application/json';

        l_response_clob := apex_web_service.make_rest_request(
            p_url         => l_url,
            p_http_method => 'POST',
            p_body        => l_payload,
           p_credential_static_id => l_credential_static_id,
            p_wallet_path => xxotm_get_cfg('WALLET_PATH')
        );
    EXCEPTION
        WHEN OTHERS THEN
            l_response_clob := '{"error": "' || SQLERRM || '"}';
    END;

    -- Step 5: OTM Order Release Refnum Synchronization (only if order_nbr provided)
    IF l_order_nbr IS NOT NULL THEN

        -- GET existing order refnums
        l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/orderReleases/'
                 || l_order_gid
                 || '/refnums?q=orderReleaseRefnumQualGid eq "NAQLEEN.CONTAINER_TYPE"&fields=orderReleaseRefnumValue';

        BEGIN
            apex_web_service.g_request_headers.DELETE;
            l_response_clob := apex_web_service.make_rest_request(
                p_url         => l_url,
                p_http_method => 'GET',
              p_credential_static_id => l_credential_static_id,
                p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );

            apex_json.parse(l_response_clob);
            l_ref_count := apex_json.get_count('items');

            IF l_ref_count > 0 THEN
                FOR i IN 1..l_ref_count LOOP
                    l_ref_val := apex_json.get_varchar2('items[%d].orderReleaseRefnumValue', i);
                    IF l_ref_val IS NOT NULL THEN
                        l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/orderReleases/'
                                 || l_order_gid
                                 || '/refnums/NAQLEEN.CONTAINER_TYPEx' || l_ref_val;

                        BEGIN
                            apex_web_service.g_request_headers.DELETE;
                            l_response_clob := apex_web_service.make_rest_request(
                                p_url         => l_url,
                                p_http_method => 'DELETE',
                               p_credential_static_id => l_credential_static_id,
                                p_wallet_path => xxotm_get_cfg('WALLET_PATH')
                            );
                        EXCEPTION WHEN OTHERS THEN NULL; END;
                    END IF;
                END LOOP;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            add_log_internal('OTM Order GET/DELETE Refnum Error: ' || SQLERRM);
        END;

        -- Local Table Update (Order)
        UPDATE xxotm_container_inventory_t
           SET container_type = l_container_type
         WHERE container_nbr     = l_container_nbr
           AND inbound_order_nbr = l_order_nbr;

        -- POST New Refnum to Order Release
        l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/orderReleases/'
                 || l_order_gid
                 || '/refnums';

        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('orderReleaseRefnumQualGid', 'NAQLEEN.CONTAINER_TYPE');
        apex_json.write('orderReleaseRefnumValue',   l_container_type);
        apex_json.write('domainName',                'NAQLEEN');
        apex_json.close_object;
        l_payload := apex_json.get_clob_output;
        apex_json.free_output;

        BEGIN
            apex_web_service.g_request_headers.DELETE;
            apex_web_service.g_request_headers(1).name  := 'Content-Type';
            apex_web_service.g_request_headers(1).value := 'application/json';

            l_response_clob := apex_web_service.make_rest_request(
                p_url         => l_url,
                p_http_method => 'POST',
                p_body        => l_payload,
               p_credential_static_id => l_credential_static_id,
                p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
        EXCEPTION
            WHEN OTHERS THEN
                l_response_clob := '{"error": "' || SQLERRM || '"}';
        END;

        add_log_internal('Order Release refnum updated for ' || l_order_nbr);
    END IF;

    -- Step 6: Final Logging
    INSERT INTO xx_otm_sync_logs (procedure_name, message_type, message_text, reference_id)
    VALUES (
        'xx_otm_update_container_type',
        'INFO',
        'Type updated to ' || l_container_type || '. OTM Status: ' || SUBSTR(l_response_clob, 1, 1000),
        l_shipment_nbr
    );

    COMMIT;

    -- Success Response
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write('response_code',    200);
    apex_json.write('response_message', 'Container Type Updated Successfully.');
    apex_json.close_object;

    htp.prn(apex_json.get_clob_output);
    apex_json.free_output;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        apex_json.free_output;
        apex_json.initialize_clob_output;
        apex_json.open_object;
        apex_json.write('response_code',    500);
        apex_json.write('response_message', 'Unable to update the container type');
        apex_json.close_object;
        htp.prn(apex_json.get_clob_output);
        apex_json.free_output;
END xx_otm_update_container_type;

   -- ========================================================================
   -- XX_OTM_VALIDATE_CFS_CONTAINER_NUMBER   [3b-prod-forward / TAKE-PROD + restore location]
   -- source: db/work/XX_OTM_VALIDATE_CFS_CONTAINER_NUMBER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_validate_cfs_container_number (
   p_container_nbr in varchar2,
   p_user_id in varchar2 default null
)
as
   v_location varchar2(100);
   -- Last Updated Date : 22-Dec-2024
   -- Description : Validate container number for release/assignment
   --               Container should NOT be in shipments table with active trip status (IN_TRANSIT or TRIP_STARTED)
   
   -- Local variables
   l_shipment_xid         varchar2(200);
   l_shipment_count       number := 0;
   l_is_valid             boolean := true;
   l_validation_message   varchar2(500);
   
   -- API variables
   l_url                  varchar2(32767);
   l_response_clob        clob;
   l_credential_static_id varchar2(20) := 'OTM_API_AUTH';
   l_items_count          number;
   l_status_type          varchar2(200);
   l_status_value         varchar2(200);
   l_active_shipment_xid  varchar2(200);
   
   -- Cursor to find shipments with this container
   cursor c_container_shipments is
   select shipment_xid
     from xxotm_shipments_t
    where cont_no = p_container_nbr and xxotm_shipments_t.location = v_location;

begin
   v_location := xx_get_user_location(p_user_id);   -- assigned here, not in DECLARE: an exception during declaration elaboration escapes this block's handler
   -- Location is mandatory. xx_get_user_location returns NULL when
   -- req_location_id is absent, malformed, or not permitted for this user;
   -- it no longer falls back to a default site. Continuing on NULL would
   -- filter on "location = NULL" and return an empty result set -- an empty
   -- screen with no error, which is worse than a refusal.
   if v_location is null then
      xxotm_location_required;
      return;
   end if;
   apex_json.initialize_clob_output;
   apex_json.open_object;
   
   -- Step 1: Check if container exists in shipments table
   begin
      select count(*)
        into l_shipment_count
        from xxotm_shipments_t
       where cont_no = p_container_nbr
       and xxotm_shipments_t.location = v_location;
   exception
      when others then
         l_shipment_count := 0;
   end;

   if l_shipment_count = 0 then
      -- Container not in shipments table - VALID
      l_is_valid := true;
      l_validation_message := 'Container number is valid. No active shipments found.';
   else
      -- Container exists in shipments - check trip status via API
      l_is_valid := false; -- Assume valid until we find an active trip
      l_validation_message := 'Container number is invalid.';

      for r_ship in c_container_shipments loop
         -- Build API URL to get statuses for this shipment
         l_url := xxotm_get_cfg('OTM_BASE_URL') || '/logisticsRestApi/resources-int/v2/shipments/'
                  || 'NAQLEEN.'
                  || r_ship.shipment_xid
                  || '/?expand=statuses';
         apex_web_service.g_request_headers.delete;
         apex_web_service.g_request_headers(1).name := 'Content-Type';
         apex_web_service.g_request_headers(1).value := 'application/json';
         begin
            l_response_clob := apex_web_service.make_rest_request(
               p_url                  => l_url,
               p_http_method          => 'GET',
               p_credential_static_id => l_credential_static_id,
               p_wallet_path => xxotm_get_cfg('WALLET_PATH')
            );
            
            -- Parse JSON Response to check statuses
            apex_json.parse(l_response_clob);
            l_items_count := apex_json.get_count('statuses.items');
            if l_items_count is null then
               l_items_count := 0;
            end if;
            
            -- Iterate through statuses to find TRIP_STATUS
            for i in 1..l_items_count loop
               l_status_type := apex_json.get_varchar2(
                  'statuses.items[%d].statusTypeGid',
                  i
               );
               l_status_value := apex_json.get_varchar2(
                  'statuses.items[%d].statusValueGid',
                  i
               );
               if l_status_type = 'NAQLEEN.TRIP_STATUS' then
                  -- Check for IN_TRANSIT or TRIP_STARTED status
                  if l_status_value = 'NAQLEEN.TRIP_NOT_STARTED' then
                     l_is_valid := true;
                  ELSE   
            		 l_is_valid := false;                                  
                  end if;
               end if;
            end loop;

         exception
            when others then
               -- On API error, log but continue checking other shipments
               null;
         end;
         
         -- If we found an invalid status, exit the shipment loop
         if not l_is_valid then
            exit;
         end if;
      end loop;
      
      -- If still valid after checking all shipments
      if l_is_valid then
         l_validation_message := 'Container number is valid.';
      end if;
   end if;
   
   -- Build response
   if l_is_valid then
      apex_json.write(
         'response_message',
         'Success'
      );
      apex_json.write(
         'response_code',
         200
      );
      apex_json.open_object('data');
      apex_json.write(
         'is_valid',
         true
      );
      apex_json.write(
         'container_nbr',
         p_container_nbr
      );
      apex_json.write(
         'validation_message',
         l_validation_message
      );
      apex_json.close_object; -- data
   else
      apex_json.write(
         'response_message',
         'Validation Failed'
      );
      apex_json.write(
         'response_code',
         400
      );
      apex_json.open_object('data');
      apex_json.write(
         'is_valid',
         false
      );
      apex_json.write(
         'container_nbr',
         p_container_nbr
      );
      apex_json.write(
         'validation_message',
         l_validation_message
      );
      apex_json.write(
         'active_shipment_xid',
         l_active_shipment_xid
      );
      apex_json.close_object; -- data
   end if;

   apex_json.close_object;
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.free_output;
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_object('data');
      apex_json.write(
         'is_valid',
         false
      );
      apex_json.close_object;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_validate_cfs_container_number;

   -- ========================================================================
   -- XX_OTM_VALIDATE_STUFFING_CONTAINER_NUMBER   [3b-prod-forward / TAKE-ANCESTOR]
   -- source: db/work/XX_OTM_VALIDATE_STUFFING_CONTAINER_NUMBER.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_otm_validate_stuffing_container_number (
   p_container_nbr in varchar2,
    p_user_id IN VARCHAR2 DEFAULT NULL
)
as
   l_count number;
    v_location varchar2(100);
begin
    v_location := xx_get_user_location(p_user_id);
    -- Location is mandatory. xx_get_user_location returns NULL when
    -- req_location_id is absent, malformed, or not permitted for this user;
    -- it no longer falls back to a default site. Continuing on NULL would
    -- filter on "location = NULL" and return an empty result set -- an empty
    -- screen with no error, which is worse than a refusal.
    if v_location is null then
       xxotm_location_required;
       return;
    end if;
    -- Description: Validates if a container is present in the yard for stuffing.
    -- Criteria: stored_time IS NOT NULL AND released_time IS NULL AND position IS NOT NULL.
    -- Response Logic: is_valid = true if present, false if not.

   apex_json.initialize_clob_output;
   begin
      select count(1)
        into l_count
        from xxotm_container_inventory_t
       where container_nbr = p_container_nbr
         and container_stored_time is not null
         and container_released_time is null
         and position is not null and xxotm_container_inventory_t.location = v_location;
   exception
      when others then
         l_count := 0;
   end;

   apex_json.open_object; -- Root
   apex_json.write(
      'response_message',
      'Success'
   );
   apex_json.write(
      'response_code',
      200
   );
   apex_json.open_object('data'); -- Data Object
   if l_count > 0 then
        -- Container IS in the yard -> VALID
      apex_json.write(
         'is_valid',
         false
      );
      apex_json.write(
         'validation_message',
         'Container is present in the yard.'
      );
   else
        -- Container is NOT in the yard -> INVALID
      apex_json.write(
         'is_valid',
         true
      );
      apex_json.write(
         'validation_message',
         'Container is not present in the yard.'
      );
   end if;
   apex_json.close_object; -- Close data

   apex_json.close_object; -- Close Root
   htp.prn(apex_json.get_clob_output);
   apex_json.free_output;
exception
   when others then
      apex_json.initialize_clob_output;
      apex_json.open_object;
      apex_json.write(
         'response_message',
         'Error: ' || sqlerrm
      );
      apex_json.write(
         'response_code',
         500
      );
      apex_json.open_object('data');
      apex_json.write(
         'is_valid',
         false
      );
      apex_json.write(
         'validation_message',
         'Unexpected Error: ' || sqlerrm
      );
      apex_json.close_object;
      apex_json.close_object;
      htp.prn(apex_json.get_clob_output);
      apex_json.free_output;
end xx_otm_validate_stuffing_container_number;

   -- ========================================================================
   -- XX_UPDATE_ROLE_PERMISSION   [3a-identical / TAKE-AS-IS]
   -- source: db/work/XX_UPDATE_ROLE_PERMISSION.sql   (full rationale is in that file)
   -- ========================================================================
   procedure xx_update_role_permission (P_BODY IN CLOB)
AS
    v_json JSON_OBJECT_T;
    v_role_name VARCHAR2(100);
    v_screen_name VARCHAR2(240);
    v_screen_path VARCHAR2(500);
    v_is_active BOOLEAN;
    v_active_flag CHAR(1);
BEGIN
    v_json := JSON_OBJECT_T.PARSE(P_BODY);
    v_role_name := UPPER(TRIM(v_json.GET_STRING('roleName')));
    v_screen_name := v_json.GET_STRING('screenName');
    v_screen_path := v_json.GET_STRING('screenPath');
    v_is_active := v_json.GET_BOOLEAN('isActive');
    
    v_active_flag := CASE WHEN v_is_active THEN 'Y' ELSE 'N' END;
    
    MERGE INTO XX_ROLE_CONFIG t
    USING DUAL ON (t.ROLE = v_role_name AND t.SCREEN_PATH = v_screen_path)
    WHEN MATCHED THEN
        UPDATE SET IS_ACTIVE = v_active_flag, LAST_UPDATED_DATE = SYSDATE, LAST_UPDATED_BY = USER
    WHEN NOT MATCHED THEN
        INSERT (ROLE, SCREEN_NAME, SCREEN_PATH, IS_ACTIVE, CREATED_DATE, CREATED_BY, LAST_UPDATED_DATE, LAST_UPDATED_BY)
        VALUES (v_role_name, v_screen_name, v_screen_path, v_active_flag, SYSDATE, USER, SYSDATE, USER);
        
    COMMIT;
    
    APEX_JSON.INITIALIZE_CLOB_OUTPUT;
    APEX_JSON.OPEN_OBJECT;
    APEX_JSON.WRITE('response_code', 200);
    APEX_JSON.WRITE('response_message', 'Updated successfully');
    APEX_JSON.CLOSE_OBJECT;
    HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        APEX_JSON.INITIALIZE_CLOB_OUTPUT;
        APEX_JSON.OPEN_OBJECT;
        APEX_JSON.WRITE('response_code', 500);
        APEX_JSON.WRITE('response_message', SQLERRM);
        APEX_JSON.CLOSE_OBJECT;
        HTP.PRN(APEX_JSON.GET_CLOB_OUTPUT);
END XX_UPDATE_ROLE_PERMISSION;

end XXOTM_ENGINE_PKG;
